function findWitness(w,a,b){return Object.values(w.npcs).find(n=>n&&n.alive&&n.id!==a.id&&n.id!==b.id&&(E.areNpcsCoLocatedV1180?E.areNpcsCoLocatedV1180(w,n,a)&&E.areNpcsCoLocatedV1180(w,n,b):(at(n)!==null&&at(n)!==undefined&&at(n)===at(a)))&&(!E.canNpcPhysicallyReactV1180||E.canNpcPhysicallyReactV1180(w,n).ok)&&tier(n)>=Math.min(tier(a),tier(b)))||null;}
