  const labels={DEAD:'สิ้นชีพ',CRIPPLED:'บาดเจ็บพิการ',BASE_BROKEN:'ฐานบำเพ็ญแตก',CAPTURED:'ถูกจับ',FLED:'หนีรอด',WOUNDED:'บาดเจ็บ',SPARED:'ยอมแพ้และถูกไว้ชีวิต',HUMILIATED:'เสียเกียรติ'};
