 const report=push(s.smallBattles,{id:id(w,'SKIRMISH'),tick:num(w.tick),aIds:A.map(n=>n.id),bIds:B.map(n=>n.id),witnessId:witness?.id||null,causeTh:cause,causeId:opts.causeId||null,steps:[{phase:'ประเมิน',totalA,totalB},{phase:'ตัดสินใจ',decisions:assessments.map(x=>x.reasonTh)},{phase:'จับคู่ปะทะ',pairings},{phase:'ผล',outcomes},{phase:'ผลต่อเนื่อง',eventId:event.id}],rulesTh:opts.lethal?'ยอมรับความเป็นตาย':'มีพยาน ห้ามพิษ ยุติเมื่อยอมแพ้'},CAP.smallBattles);
