 const bribed=corrupt&&num(actor.wealthM)>2&&r.chance(.3);if(bribed)actor.wealthM=Math.max(0,num(actor.wealthM)-1);
 let sentence=num(info.evidence)<70?'ตักเตือน':info.result==='DEAD'?'ขับจากสำนัก':info.result==='BASE_BROKEN'?'กักขัง':'ชดใช้';
 if((favor||bribed)&&corrupt)sentence='ตักเตือน';
 if(st.jianghu?.orderCode==='UNORTHODOX'&&info.result==='DEAD'&&num(leader?.personality?.aggression,50)>80)sentence='ทำลายฐานบำเพ็ญ';
 if(sentence==='กักขัง'){actor.jianghu.captiveBy=leader?.id||'SECT';actor.jianghu.captiveUntil=num(w.tick)+90;}
