 if(sentence==='ทำลายฐานบำเพ็ญ'){actor.jianghu.stage=1;actor.jianghu.baseBroken=true;refresh(actor);}
 if(sentence==='ชดใช้'){const amount=Math.min(.5,num(actor.wealthM));actor.wealthM-=amount;victim.wealthM=num(victim.wealthM)+amount;}
 actor.jianghu.honor=clamp(actor.jianghu.honor-8);record(w,actor,victim,'SECT_TRIAL',`หอคุมกฎแห่ง${st.name}ตัดสินให้${actor.name}${sentence} เพราะ${info.causeTh||'ทำร้ายผู้ร่วมสำนัก'} ${favor&&corrupt?'ผู้ตัดสินเห็นแก่สายสัมพันธ์จนลดโทษ':bribed?'คำตัดสินอ่อนลงหลังทรัพย์ลับเปลี่ยนมือ':'พิจารณาจากพยานและหลักฐานตามจารีตสำนัก'}`,{world:true,causeId:info.causeId});return {sentenceTh:sentence,judgeId:leader?.id,bribed,favoritism:!!(favor&&corrupt)};
