 const successChance=clamp(.22-(opts.recipeIdV160&&E.ensureRecipePolicyV160&&E.ensureRecipePolicyV160(w,E.ensureRecipeSystemsV140(w).registry[opts.recipeIdV160]).secrecy==='SECRET'?.12:0)+Math.log2(Math.max(.05,ratio))*.15+(num(a.personality?.caution,50)-num(b.personality?.caution,50))/300+(a.jianghu.professionId==='POISON_MASTER'?.12:0)+(b.jianghu.closedDoor?.active?.08:0),.025,.9);
