function refresh(n){const j=n.jianghu;if(!j)return;const def=E.CULTIVATION_PATHS[j.path]||E.CULTIVATION_PATHS.XIAN;j.path=def.id;j.maxStage=def.maxStage;j.stage=Math.round(clamp(j.stage,1,def.maxStage,1));j.stageNameTh=def.stages[j.stage-1].nameTh;j.pathNameTh=def.nameTh;j.subPath=def.subPaths[j.subPath]?j.subPath:Object.keys(def.subPaths)[0];j.subPathNameTh=def.subPaths[j.subPath].nameTh;j.isImmortal=j.stage===def.maxStage;j.combatPower=E.computeNpcCultivationCombatPowerV100(n);}
