 if(ac.handler==='covert'&&[0,1,2,3,11,14].includes(ac.variant)&&num(relOf(w,a,b)?.level)<4)return false;
 if(ac.id==='CONFLICT_11'&&!b?.jianghu?.captiveBy)return false;
 if(ac.id==='SECT_15'&&(!j.isWanderingHero||num(j.honor)<75||num(a.wealthM)<10||tier(a)<5||Object.keys(w.states).length>=64))return false;
