 const turn=r.int(0,8),rel=relOf(w,a,b,true);
 if(turn===0&&rel.affinity>20){push(s.letters,{id:id(w,'LETTER'),from:a.id,to:b.id,deliverTick:num(w.tick)+7,delivered:false,textTh:'สหายยังระลึกถึงคำมั่นที่ให้กัน'},CAP.letters);}
 if(turn===1&&rel.bond>45){push(s.feasts,{id:id(w,'FEAST'),hostId:a.id,guestIds:[b.id],tick:num(w.tick)},CAP.feasts);rel.trust=clamp(rel.trust+3);record(w,a,b,'FEAST',`${a.name}เชิญ${b.name}ร่วมสุราระลึกทางเก่า เพราะเคยรักษาชีวิตกัน คำสนทนาช่วยขจัดความระแวง`);}
 if(turn===2&&rel.bond>60&&tier(a)>tier(b)){j.socialFlags.guardianFor=b.id;const br=relOf(w,b,a,true);br.tags=Array.from(new Set([...br.tags,'ผู้พิทักษ์'])).slice(-8);}
 if(turn===3&&rel.trust>60&&j.higherRealmLegacyId){b.jianghu.socialFlags.secretKeeperFor=a.id;rel.tags=Array.from(new Set([...rel.tags,'ผู้เก็บความลับ'])).slice(-8);j.secretExposureCount=Math.max(0,num(j.secretExposureCount)-1);}
 if(turn===4&&rel.affinity<-30&&num(a.personality?.integrity)>70){reconcile(w,a,b,'NEGOTIATION',{rng:r});}
 if(turn===5&&b.jianghu.captiveBy&&num(a.wealthM)>.3){a.wealthM-=.2;b.jianghu.captiveBy=null;b.jianghu.captiveUntil=0;applyReason(w,a,b,'PAY_RANSOM',{force:true});}
 if(turn===6&&rel.trust>50&&a.wealthM>.4&&b.wealthM<.2){a.wealthM-=.1;b.wealthM+=.1;rel.bond=clamp(rel.bond+4);record(w,a,b,'TRAVEL_FUND',`${a.name}แบ่งศิลาปราณให้${b.name} เพราะผู้ร่วมทางขัดสน หนี้ไมตรีนี้อาจหนุนให้กลับมาช่วยกันในคราวหน้า`);}
