   if(j.captiveBy&&t>=num(j.captiveUntil)){j.captiveBy=null;record(w,a,null,'RELEASE','กาลครบคำกักขัง '+a.name+'ได้รับอิสรภาพกลับสู่ยุทธภพ');}
   if(j.latentPowers.some(l=>l.state==='DORMANT')){const trigger=a.health<35?'crisis':j.path==='GOD'?'faith':rel?.bond>65?'bond':'ritual';const lp=j.latentPowers.find(l=>D.latentPowers.find(p=>p.id===l.id)?.trigger===trigger);if(lp&&r.chance(.05))awaken(w,a,lp.id,trigger,{rng:r});}
