            actionType: 'DISCIPLE_CONFLICT_INCIDENT',
            affectedSectIds: [pet.fromSect, pet.toSect].filter(Boolean),
            reasonTh: pet.causeTh || 'ข้อพิพาทระหว่างศิษย์ต่างสำนัก',
            summaryTh: `${w.npcs?.[pet.actorId]?.name || 'ศิษย์'}ก่อเหตุกระทบกระทั่งกับ${w.npcs?.[pet.victimId]?.name || 'ผู้ฝึกตนต่างสำนัก'}`
