 let powerFrame=null;
 function power(w,n){if(!powerFrame||powerFrame.w!==w||powerFrame.tick!==w.tick)return E.computeNpcCultivationCombatPowerV100(n);const key=n.id+':'+n.health+':'+n.jianghu.stage+':'+n.jianghu.internalInjury;let p=powerFrame.values.get(key);if(p===undefined){p=E.computeNpcCultivationCombatPowerV100(n);powerFrame.values.set(key,p);}return p;}
