 function bound(a,x,cap){a.unshift(x);if(a.length>cap)a.length=cap;return x;}
 function relation(w,a,b){if(a===b)return {status:'SAME_SECT',score:100,isAlly:true,isHostile:false};const r=w.states[a]?.relations?.[b],war=(w.wars||[]).some(v=>['War','SiteWar'].includes(v.status)&&((v.attackerId===a&&v.defenderId===b)||(v.attackerId===b&&v.defenderId===a)));const score=num(r?.score,50),ally=r?.status==='Alliance'||score>=85,hostile=war||['War','Hostile'].includes(r?.status)||score<=25;return {status:hostile?'HOSTILE':ally?'ALLY':score>=68?'FRIEND':'NEUTRAL',score,isAlly:ally,isHostile:hostile};}
