    while(todo.length){const cur=todo.pop();for(const cid of cur.connectedCityIds){const q=w.cities[cid];if(q&&q.landId===land.id&&!reached.has(q.id)){reached.add(q.id);todo.push(q);}}}
    if(reached.size===local.length)break;
