 function reconcileAuthorities(w){if(values(w.newWorld.mines).some(m=>m.operatorSectId&&(!w.states[m.operatorSectId]||w.states[m.operatorSectId].isExiled)))accountMines(w);for(const m of values(w.newWorld.mines))if(m.operatorSectId&&!w.states[m.operatorSectId])m.operatorSectId=null;for(const p of values(w.cities).filter(isHolding)){if(p.stateId&&!w.states[p.stateId]){p.stateId=null;p.currentOwnerId=null;p.controllerSectId=null;}if(p.headquartersFor&&p.stateId!==p.headquartersFor){p.formerHeadquartersFor=p.headquartersFor;p.headquartersFor=null;p.isCapital=false;}}for(const s of values(w.states)){const held=values(w.cities).filter(p=>isHolding(p)&&p.stateId===s.id);s.cities=held.map(p=>p.id);for(const p of held)p.controllerSectId=p.stateId;if(w.cities[s.headquartersId]?.stateId!==s.id){const next=held[0];if(next){s.headquartersId=next.id;s.capitalCityId=next.id;s.libraryCityIdV1100=next.id;next.headquartersFor=s.id;next.isCapital=true;for(const n of values(w.npcs))if(n.stateId===s.id&&(!w.cities[n.homeCityId]||w.cities[n.homeCityId].stateId!==s.id))n.homeCityId=next.id;}else{s.isExiled=true;for(const m of values(w.newWorld.mines))if(m.operatorSectId===s.id)m.operatorSectId=null;}}else{for(const n of values(w.npcs))if(n.stateId===s.id&&(!w.cities[n.homeCityId]||(isHolding(w.cities[n.homeCityId])&&w.cities[n.homeCityId].stateId!==s.id)))n.homeCityId=s.headquartersId;}if(!s.isExiled)reconcileSectPositionsNewWorld(w,s);}syncAssetSummary(w);}
 function validate(w){const issues=[],check=(x,code,id)=>{if(!x)issues.push({code,id});};if(!w.newWorld)return {ok:true,issues:[],scope:'BASELINE'};
  for(const p of values(w.cities)){check(!!landId(p)&&landId(p)===p.landId,'LOCATION_OFF_LAND',p.id);if(isCity(p))check(p.stateId===null&&p.currentOwnerId===null&&p.controllerSectId===null&&p.capturePolicy==='CIVIC_NEUTRAL'&&D.kingdoms.some(k=>k.id===p.kingdomId),'CITY_NEUTRAL',p.id);else if(isHolding(p))check(p.capturePolicy==='TERRITORIAL'&&(!p.stateId||(!!w.states[p.stateId]&&p.currentOwnerId===p.stateId&&p.controllerSectId===p.stateId)),'HOLDING_OWNER',p.id);}
  for(const s of values(w.states)){check(!!w.npcs[s.positions.HEAD_OF_STATE]?.alive||s.isExiled,'LEADER',s.id);check(isHolding(w.cities[s.headquartersId]),'HQ',s.id);check(E.getSpiritStonesV140(s)>=0,'SECT_LEDGER',s.id);}
  for(const n of values(w.npcs)){check(!n.stateId||!!w.states[n.stateId],'NPC_AFFILIATION',n.id);check(!!w.cities[n.homeCityId],'NPC_HOME',n.id);const loc=E.getEntityLocation(w,n);if(n.alive)check(!!loc&&(['TRANSIT','SUBSITE','MICRO_SITE','SKYSHIP','CAMP'].includes(loc.kind)||!!w.cities[loc.cityId]),'NPC_LOCATION',n.id);check(!n.jianghu.masterId||!!w.npcs[n.jianghu.masterId],'NPC_MASTER',n.id);for(const r of n.relationships||[])check(!!w.npcs[r.targetId],'NPC_RELATION',n.id+':'+r.targetId);check(E.getSpiritStonesV140(n)>=0,'NPC_LEDGER',n.id);}
  for(const m of values(w.newWorld.mines)){check(!m.operatorSectId||!!w.states[m.operatorSectId],'MINE_OWNER',m.id);check(m.reserveRemaining>=0&&m.lastPaidPeriod<=Math.floor(w.tick/30),'MINE_ACCOUNTING',m.id);check(!!w.cities[m.anchorId],'MINE_ANCHOR',m.id);}
  for(const e of w.newWorld.routes)check(!!w.cities[e.from]&&!!w.cities[e.to]&&e.length>0&&(e.mode!=='LAND'||w.cities[e.from].landId===w.cities[e.to].landId),'ROUTE',e.id);
  const seen=new Set();for(const row of w.newWorld.productionPeriods){const k=row.mineId+':'+row.period;check(!seen.has(k),'DUPLICATE_MINE_PERIOD',k);seen.add(k);}
  return {ok:issues.length===0,issues,inventory:inventory(w)};
 }

