  // Upgrade world initialization with Patch 1.1.0 states, 108 cities, camps, human psychology & multi-front wars
  const _origCreateInitialWorld = createInitialWorld;
  createInitialWorld = function (seed = 202611717) {
    const world = _origCreateInitialWorld(seed);
    world.version = VERSION;
    const rng = new SeededRNG(seed + 110);

    // 1. Add 10 Extra States (Total 18 Initial States)
    EXTRA_STATES_V110.forEach((cfg) => {
      world.states[cfg.id] = {
        ...cfg,
        relations: {},
        budgetAllocation: { military: 0.30, infrastructure: 0.30, education: 0.20, logistics: 0.20 },
        logisticsDirty: true,
        frontlineDirty: false,
        vacancyDirty: true,
        warPlan: null,
        positions: {
          HEAD_OF_STATE: null,
          DEFENSE_MINISTER: null,
          SUPREME_COMMANDER: null,
          LOGISTICS_CHIEF: null,
          FINANCE_MINISTER: null
        }
      };
    });

    // Ensure full bilateral diplomatic relations matrix across all 18 states
    const allStateIds = Object.keys(world.states);
    allStateIds.forEach((a) => {
      allStateIds.forEach((b) => {
        if (a === b) return;
        if (!world.states[a].relations[b]) {
          world.states[a].relations[b] = { status: 'Peace', score: 62 };
        }
      });
    });

    // 2. Add 86 Extra Cities (Total 108 Cities!)
    EXTRA_CITIES_V110.forEach((c) => {
      const eq = createEmptyEquipmentBag();
      eq.logistics.HEMTT_Truck = 28;
      eq.logistics.C17_Globemaster = c.isCapital ? 3 : 1;
      world.cities[c.id] = {
        ...c,
        governorId: null,
        isFrontline: false,
        threatLevel: 0,
        activeProject: 'ขยายโครงสร้างพื้นฐานและคลังสำรองยุทธศาสตร์ประจำภูมิภาค',
        projectProgress: rng.int(20, 80),
        supplies: {
          fuel: c.urbanLevel >= 4 ? 1350 : 950,
          ammo: c.urbanLevel >= 4 ? 900 : 650,
          rations: c.urbanLevel >= 4 ? 1600 : 1100,
          spareParts: c.urbanLevel >= 4 ? 550 : 380
        },
        troops: c.urbanLevel >= 4 ? 4200 : 2800,
        equipment: eq
      };
    });

    // 3. Add Military Camps for each of the 10 new States + populate their Leadership NPCs
    EXTRA_STATES_V110.forEach((stCfg) => {
      const st = world.states[stCfg.id];
      const capCity = Object.values(world.cities).find((c) => c.stateId === st.id && c.isCapital);
      const capId = capCity ? capCity.id : null;

      const campId = `CAMP_${st.id}_MAIN`;
      const eq = createEmptyEquipmentBag();
      eq.tanks[st.primaryTank] = 95;
      eq.apcs[st.primaryAPC] = 140;
      eq.artillery[st.primaryArtillery] = 60;
      eq.airDefense[st.primarySAM] = 24;
      eq.aircraft[st.primaryFighter] = 32;
      eq.logistics.HEMTT_Truck = 55;

      world.camps[campId] = {
        id: campId,
        name: `${st.shortName} Strategic Combined Base`,
        stateId: st.id,
        type: 'permanent_camp',
        x: st.mapCenter.x + 6,
        y: st.mapCenter.y - 5,
        terrain: 'plains',
        troops: 18500,
        commanderId: null,
        readiness: 88,
        fortification: 80,
        supplies: { fuel: 2100, ammo: 1950, rations: 2300, spareParts: 850 },
        daysOfSupply: 26,
        equipment: eq
      };

      // National Leadership for new state
      const head = generateContextualNPC(world, rng, { stateId: st.id, age: rng.int(46, 64), track: 'political', archetype: 'power_seeker', positionId: 'HEAD_OF_STATE', homeCityId: capId, assignedNodeId: capId });
      st.positions.HEAD_OF_STATE = head.id;
      const defMin = generateContextualNPC(world, rng, { stateId: st.id, age: rng.int(44, 60), track: 'military', archetype: 'ideologue', positionId: 'DEFENSE_MINISTER', homeCityId: capId, assignedNodeId: capId });
      st.positions.DEFENSE_MINISTER = defMin.id;
      const supCmd = generateContextualNPC(world, rng, { stateId: st.id, age: rng.int(45, 59), track: 'military', archetype: 'military_purist', positionId: 'SUPREME_COMMANDER', homeCityId: capId, assignedNodeId: campId });
      st.positions.SUPREME_COMMANDER = supCmd.id;
      world.camps[campId].commanderId = supCmd.id;
      const logChief = generateContextualNPC(world, rng, { stateId: st.id, age: rng.int(39, 55), track: 'military', archetype: 'logistics_master', positionId: 'LOGISTICS_CHIEF', homeCityId: capId, assignedNodeId: capId });
      st.positions.LOGISTICS_CHIEF = logChief.id;
      const finMin = generateContextualNPC(world, rng, { stateId: st.id, age: rng.int(40, 58), track: 'civilian', archetype: 'city_builder', positionId: 'FINANCE_MINISTER', homeCityId: capId, assignedNodeId: capId });
      st.positions.FINANCE_MINISTER = finMin.id;
    });

    // Assign governors to any city without a governor (for important cities, or lightweight shared regional governors so NPC count stays fast!)
    Object.values(world.cities).forEach((city) => {
      if (!city.governorId) {
        const stNpcs = Object.values(world.npcs).filter((n) => n.stateId === city.stateId && n.alive);
        const existingGov = stNpcs.find((n) => n.positionId === 'SENIOR_OFFICIAL' || n.positionId === 'MID_OFFICER');
        if (city.urbanLevel >= 4 || city.isCapital) {
          const gov = generateContextualNPC(world, rng, {
            stateId: city.stateId,
            age: rng.int(36, 56),
            track: 'civilian',
            archetype: rng.chance(0.3) ? 'power_seeker' : 'city_builder',
            positionId: 'CITY_GOVERNOR',
            homeCityId: city.id,
            assignedNodeId: city.id
          });
          city.governorId = gov.id;
        } else if (existingGov) {
          city.governorId = existingGov.id;
        }
      }
    });

    // Initialize Human Psychology attributes on all NPCs
    Object.values(world.npcs).forEach((npc) => {
      ensureNPCHumanPsychology(world, npc, rng);
    });

    // Initialize Structured Watchlist (States, Cities, NPCs, Military/Carriers)
    world.watchlistItems = [
      { kind: 'state', id: 'TH', note: 'ติดตามการพัฒนาเศรษฐกิจและกองทัพไทย' },
      { kind: 'city', id: 'CITY_TH_BKK', note: 'มหานครศูนย์กลางและคลังเสบียงหลัก' },
      { kind: 'city', id: 'CITY_TH_CNX', note: 'ศูนย์กลางภาคเหนือ' },
      { kind: 'carrier', id: 'CSG_US_FORD', note: 'ป้อมปราการลอยน้ำสหรัฐฯ' },
      { kind: 'npc', id: world.states.TH.positions.HEAD_OF_STATE, note: 'ผู้นำรัฐบาลไทย' },
      { kind: 'npc', id: world.states.TH.positions.SUPREME_COMMANDER, note: 'ผู้บัญชาการทหารสูงสุดไทย' }
    ];

    world.whatIfHistory = [];

    addChronicle(
      world,
      'SYSTEM',
      `เริ่มต้นแพตช์ v${VERSION}: โลกจำลอง ${Object.keys(world.states).length} รัฐ, ${Object.keys(world.cities).length} เมืองยุทธศาสตร์, ระบบจิตวิทยามนุษย์ (กบฏ/รัฐประหาร/ตั้งรัฐใหม่), ระบบสงครามหลายแนวรบ และเครื่องมือทดลองประวัติศาสตร์ What-If`
    );

    return world;
  };

  function ensureNPCHumanPsychology(world, npc, rng) {
    if (!npc) return;
    if (npc.satisfaction === undefined) {
      const st = world.states[npc.stateId];
      const baseSat = st ? Math.round((st.stability + st.approval) / 2) : 75;
      npc.satisfaction = Math.min(98, Math.max(20, baseSat + (rng ? rng.int(-15, 12) : 0)));
      npc.grievance = Math.max(0, 100 - npc.satisfaction);
      npc.coupReadiness = 0;
      npc.secessionDesire = 0;
      npc.humanThought = generateHumanThoughtText(world, npc);
    }
  }

  function generateHumanThoughtText(world, npc) {
    const st = world.states[npc.stateId];
    if (!st) return 'กำลังประเมินสถานการณ์บ้านเมือง';
    if (npc.satisfaction < 38 && npc.track === 'military' && npc.authority >= 68) {
      return `ไม่พอใจอย่างรุนแรงต่อทิศทางรัฐบาล ${st.shortName} (เสถียรภาพ ${st.stability}%) กำลังชั่งใจเรื่องการใช้กำลังทหารเข้าแทรกแซงหรือรัฐประหาร`;
    }
    if (npc.satisfaction < 42 && npc.positionId === 'CITY_GOVERNOR' && npc.personality.ambition >= 75) {
      return `เห็นว่ารัฐบาลกลางทอดทิ้งเมืองในปกครองและตนมีบารมีสูงพอ กำลังซ่องสุมมวลชนเพื่อแยกตัวตั้งรัฐอิสระใหม่`;
    }
    if (npc.personality.archetype === 'power_seeker') {
      return `มุ่งสร้างเครือข่ายทางการเมืองและสะสมบารมีเพื่อก้าวขึ้นสู่ตำแหน่งสูงสุดของ ${st.shortName}`;
    }
    if (npc.personality.archetype === 'city_builder') {
      return `ต้องการงบประมาณเพิ่มเติมเพื่อยกระดับโครงสร้างพื้นฐานและคุณภาพชีวิตประชาชนในพื้นที่`;
    }
    if (npc.personality.archetype === 'military_purist') {
      return `กังวลเรื่องความพร้อมรบและจำนวนเสบียง/อาวุธสมัยใหม่ของกองทัพ ${st.shortName}`;
    }
    return `ปฏิบัติหน้าที่ตามขอบเขตอำนาจ (${npc.positionTitle}) และเฝ้าดูการเปลี่ยนแปลงของรัฐ`;
  }

  // =========================================================================
  // PATCH 1.1.0 FEATURE: ADD NEW CITY DYNAMICALLY ON MAP ("เตรียมพร้อมสำหรับการเพิ่มเมือง")
  // =========================================================================
  function createCustomCity(world, opts = {}) {
    const stateId = opts.stateId || 'TH';
    const st = world.states[stateId] || Object.values(world.states)[0];
    const cityId = 'CITY_CUSTOM_' + (++world.nextId);
    const x = opts.x !== undefined ? opts.x : Math.min(950, Math.max(50, st.mapCenter.x + ((world.nextId * 17) % 60) - 30));
    const y = opts.y !== undefined ? opts.y : Math.min(490, Math.max(50, st.mapCenter.y + ((world.nextId * 23) % 60) - 30));
    if(world.newWorld&&!_exportedEngineObjV250.getNewWorldLandId({x,y})){world.nextId--;return {ok:false,reason:'ห้ามสร้างเมืองในมหาสมุทรนอกขอบเขตเส้นทาง'};}
    const name = opts.name || `เมืองใหม่ ${st.shortName}-${world.nextId % 100}`;

    const eq = createEmptyEquipmentBag();
    eq.logistics.HEMTT_Truck = 25;

    const rng = new SeededRNG(world.seed + world.nextId);
    const gov = generateContextualNPC(world, rng, {
      stateId: st.id,
      age: rng.int(34, 52),
      track: 'civilian',
      archetype: 'city_builder',
      positionId: 'CITY_GOVERNOR',
      assignedNodeId: cityId
    });
    ensureNPCHumanPsychology(world, gov, rng);

    const newCity = {
      id: cityId,
      name,
      stateId: st.id,
      regionName: opts.regionName || 'เขตพัฒนาเมืองใหม่',
      isCapital: false,
      urbanLevel: opts.urbanLevel || 3,
      specialty: opts.specialty || 'เมืองยุทธศาสตร์สร้างใหม่',
      x,
      y,
      terrain: opts.terrain || 'plains',
      popM: opts.popM || 1.5,
      infrastructure: opts.infrastructure || 80,
      economy: opts.economy || 80,
      safety: 85,
      governorId: gov.id,
      isFrontline: false,
      threatLevel: 0,
      activeProject: 'ก่อสร้างโครงสร้างพื้นฐานระยะแรก',
      projectProgress: 35,
      supplies: { fuel: 1200, ammo: 800, rations: 1500, spareParts: 500 },
      troops: 3500,
      equipment: eq
    };

    world.cities[cityId] = newCity;
    if(world.newWorld)_exportedEngineObjV250.attachNewWorldCreatedCity(world,newCity,gov);
    st.logisticsDirty = true;
    addChronicle(world, 'DEVELOPMENT', `🏙️ ก่อตั้งเมืองใหม่ "${name}" ในเขตปกครองของ ${st.name} ณ พิกัด (${x}, ${y}) โดยมี ${gov.name} เป็นผู้ว่าราชการเมืองคนแรก`, st.id);
    return newCity;
  }

  // =========================================================================
  // PATCH 1.1.0 FEATURE: NPC FOUNDING A NEW STATE / SECESSION / COUP / REBELLION
  // =========================================================================
  const NEW_STATE_COLORS = ['#f43f5e', '#8b5cf6', '#14b8a6', '#eab308', '#f97316', '#06b6d4', '#ec4899', '#84cc16'];
  const NEW_STATE_FLAGS = ['🚩', '🦅', '🦁', '⭐', '🔥', '🛡️', '⚔️', '👑'];

  function triggerNPCFoundNewState(world, founderNpc, originCity = null) {
    if (!founderNpc || !founderNpc.alive) return { ok: false, reason: 'ไม่พบตัวละครผู้ก่อตั้งรัฐ' };
    const parentState = world.states[founderNpc.stateId];
    const parentCities = Object.values(world.cities).filter((c) => c.stateId === founderNpc.stateId);
    const targetCity =
      originCity ||
      (founderNpc.assignedNodeId && world.cities[founderNpc.assignedNodeId]) ||
      parentCities.find((c) => !c.isCapital) ||
      parentCities[0];

    if (!targetCity) return { ok: false, reason: 'ไม่พบเมืองฐานที่มั่นสำหรับตั้งรัฐใหม่' };

    const idx = Object.keys(world.states).length;
    const newStateId = 'ST_' + (++world.nextId % 1000);
    const cityCleanName = targetCity.name.split(' ')[0];
    const isMilitary = founderNpc.track === 'military';
    const stateTitle = isMilitary
      ? `รัฏฐาธิปัตย์แห่ง${cityCleanName} (${cityCleanName} Sovereign State)`
      : `สาธารณรัฐอิสระ${cityCleanName} (Free Republic of ${cityCleanName})`;

    const newState = {
      id: newStateId,
      name: stateTitle,
      shortName: cityCleanName.slice(0, 3).toUpperCase() || newStateId,
      flag: NEW_STATE_FLAGS[idx % NEW_STATE_FLAGS.length],
      region: parentState ? parentState.region : 'Thailand',
      color: NEW_STATE_COLORS[idx % NEW_STATE_COLORS.length],
      policy: isMilitary ? 'Militarist' : 'Expansionist',
      governmentType: isMilitary ? 'คณะผู้ยึดอำนาจปกครองตนเอง (Military Junta)' : 'สาธารณรัฐตั้งใหม่ (Emergent Republic)',
      gdpB: Math.max(280, Math.round((parentState ? parentState.gdpB : 1200) * 0.18)),
      treasuryB: Math.max(95, Math.round((parentState ? parentState.treasuryB : 250) * 0.22)),
      taxRate: 0.20,
      stability: 74,
      approval: 79,
      educationIndex: parentState ? parentState.educationIndex : 80,
      mapCenter: { x: targetCity.x, y: targetCity.y },
      primaryTank: parentState ? parentState.primaryTank : 'Type99A',
      primaryAPC: parentState ? parentState.primaryAPC : 'BTR82A',
      primaryArtillery: parentState ? parentState.primaryArtillery : 'CAESAR_155',
      primarySAM: parentState ? parentState.primarySAM : 'IRIS_T_SLM',
      primaryFighter: parentState ? parentState.primaryFighter : 'F35A',
      primaryCarrierFighter: parentState ? parentState.primaryCarrierFighter : 'F35C',
      secondaryCarrierFighter: 'Rafale_M',
      lore: `ก่อตั้งขึ้นในปี ${world.year} โดย ${founderNpc.name} (${founderNpc.personality.archetypeLabel}) จากแรงขับดันด้านความทะเยอทะยานและอุดมการณ์ทางการเมือง โดยใช้ ${targetCity.name} เป็นเมืองหลวง`,
      relations: {},
      budgetAllocation: { military: 0.38, infrastructure: 0.28, education: 0.16, logistics: 0.18 },
      logisticsDirty: true,
      frontlineDirty: true,
      vacancyDirty: true,
      warPlan: null,
      positions: {
        HEAD_OF_STATE: founderNpc.id,
        DEFENSE_MINISTER: null,
        SUPREME_COMMANDER: null,
        LOGISTICS_CHIEF: null,
        FINANCE_MINISTER: null
      }
    };

    world.states[newStateId] = newState;

    // Transfer origin city (and any nearby sympathetic non-capital city) to the new state
    targetCity.stateId = newStateId;
    targetCity.isCapital = true;
    targetCity.governorId = founderNpc.id;

    // Unassign founder from old state posts and promote to HEAD_OF_STATE of the new state
    unassignNPCFromPosts(world, founderNpc);
    founderNpc.stateId = newStateId;
    promoteNPC(world, founderNpc, 'HEAD_OF_STATE', targetCity.id);
    founderNpc.satisfaction = 95;
    founderNpc.grievance = 5;
    founderNpc.humanThought = `ประสบความสำเร็จในการก่อตั้ง "${stateTitle}" และขึ้นดำรงตำแหน่งผู้นำสูงสุด!`;
    recordNPCMemory(founderNpc, world.year, `ประกาศแยกตัวและสถาปนารัฐใหม่ "${stateTitle}" ณ เมือง ${targetCity.name}`);

    // Create a dedicated Military Camp for the new state
    const campId = `CAMP_${newStateId}_GUARD`;
    const eq = createEmptyEquipmentBag();
    eq.tanks[newState.primaryTank] = 65;
    eq.apcs[newState.primaryAPC] = 95;
    eq.artillery[newState.primaryArtillery] = 40;
    eq.airDefense[newState.primarySAM] = 16;
    eq.aircraft[newState.primaryFighter] = 18;
    eq.logistics.HEMTT_Truck = 35;

    world.camps[campId] = {
      id: campId,
      name: `กองบัญชาการพิทักษ์เอกราช ${cityCleanName}`,
      stateId: newStateId,
      type: 'permanent_camp',
      x: targetCity.x + 8,
      y: targetCity.y - 6,
      terrain: targetCity.terrain || 'plains',
      troops: 14000,
      commanderId: founderNpc.id,
      readiness: 90,
      fortification: 78,
      supplies: { fuel: 1800, ammo: 1700, rations: 2000, spareParts: 700 },
      daysOfSupply: 25,
      equipment: eq
    };

    // Set diplomatic relations (Hostile/Truce with parent state, Peace with others)
    Object.keys(world.states).forEach((otherId) => {
      if (otherId === newStateId) return;
      const isParent = parentState && otherId === parentState.id;
      const status = isParent ? 'Hostile' : 'Peace';
      const score = isParent ? 22 : 58;
      newState.relations[otherId] = { status, score };
      world.states[otherId].relations[newStateId] = { status, score };
    });

    const rng = new SeededRNG(world.seed + world.tick + world.nextId);
    fillInstitutionalVacancies(world, rng);

    const narrative = `🚩 [สถาปนารัฐใหม่!] ${founderNpc.name} (${founderNpc.personality.archetypeLabel}, ความทะเยอทะยาน ${founderNpc.personality.ambition}) รวบรวมฐานอำนาจและกำลังพลประกาศแยกตัวจาก ${parentState ? parentState.name : 'รัฐเดิม'} ก่อตั้ง "${stateTitle}" โดยมี ${targetCity.name} เป็นเมืองหลวงแห่งใหม่!`;
    addChronicle(world, 'FOUNDATION', narrative, newStateId, { personId: founderNpc.id, cityId: targetCity.id });
    return { ok: true, newState, narrative };
  }

  function triggerMilitaryCoup(world, generalNpc) {
    if (!generalNpc || !generalNpc.alive) return { ok: false, reason: 'ไม่พบตัวละครผู้นำการรัฐประหาร' };
    const st = world.states[generalNpc.stateId];
    if (!st) return { ok: false, reason: 'ไม่พบรัฐเป้าหมาย' };

    const oldLeaderId = st.positions.HEAD_OF_STATE;
    const oldLeader = oldLeaderId ? world.npcs[oldLeaderId] : null;
    if (oldLeader && oldLeader.id === generalNpc.id) {
      return { ok: false, reason: `${generalNpc.name} เป็นผู้นำสูงสุดของรัฐนี้อยู่แล้ว` };
    }

    // Calculate Coup Power vs Government Loyalist Power
    const coupPower =
      generalNpc.authority * 1.2 +
      generalNpc.knowledge.military * 0.9 +
      generalNpc.experience.commandExp * 0.8 +
      generalNpc.personality.ambition * 0.6 +
      (100 - st.stability) * 1.1;

    const loyalistPower =
      (oldLeader ? oldLeader.authority + oldLeader.knowledge.politics : 80) +
      st.stability * 1.1 +
      st.approval * 0.9;

    const coupSuccess = coupPower >= loyalistPower * 0.82;

    if (coupSuccess) {
      if (oldLeader) {
        retireNPC(world, oldLeader);
        recordNPCMemory(oldLeader, world.year, `ถูกยึดอำนาจในการรัฐประหารนำโดย ${generalNpc.name}`);
      }
      promoteNPC(world, generalNpc, 'HEAD_OF_STATE');
      st.positions.HEAD_OF_STATE = generalNpc.id;
      st.governmentType = 'คณะปฏิรูปการปกครองแผ่นดิน (Military Junta)';
      st.policy = 'Militarist';
      st.stability = Math.max(45, st.stability - 12);
      st.approval = Math.max(42, st.approval - 8);
      generalNpc.satisfaction = 92;
      generalNpc.grievance = 8;
      generalNpc.humanThought = `ยึดอำนาจสำเร็จและขึ้นเป็นผู้นำสูงสุดของ ${st.shortName} เพื่อจัดระเบียบความมั่นคงใหม่`;
      recordNPCMemory(generalNpc, world.year, `นำกำลังทหารก่อการรัฐประหารยึดอำนาจการปกครองใน ${st.name} สำเร็จ`);

      const msg = `⚡🪖 [รัฐประหารสำเร็จ!] ${generalNpc.name} อาศัยจังหวะที่รัฐบาล ${st.name} มีความนิยมและเสถียรภาพลดลง เคลื่อนกำลังรถถังและหน่วยรบเข้ายึดศูนย์บัญชาการ ปลด ${oldLeader ? oldLeader.name : 'ผู้นำเดิม'} และสถาปนาตนเป็นผู้นำรัฐคนใหม่ เปลี่ยนนโยบายสู่ Militarist!`;
      addChronicle(world, 'COUP', msg, st.id, { personId: generalNpc.id });
      return { ok: true, success: true, summary: msg };
    } else {
      generalNpc.satisfaction = 15;
      generalNpc.mistakes += 2;
      retireNPC(world, generalNpc);
      st.stability = Math.max(40, st.stability - 6);
      const msg = `🛡️ [สกัดกั้นการรัฐประหาร!] ความพยายามก่อรัฐประหารของ ${generalNpc.name} ใน ${st.name} ล้มเหลว เนื่องจากหน่วยกำลังรักษาพระนครและฐานเสียงรัฐบาลของ ${oldLeader ? oldLeader.name : 'ผู้นำรัฐ'} ยังคงเหนียวแน่น ผู้ก่อการถูกปลดจากตำแหน่งทันที!`;
      addChronicle(world, 'COUP', msg, st.id, { personId: generalNpc.id });
      return { ok: true, success: false, summary: msg };
    }
  }

  function triggerArmedRebellion(world, rebelNpc) {
    if (!rebelNpc || !rebelNpc.alive) return { ok: false, reason: 'ไม่พบตัวละคร' };
    const st = world.states[rebelNpc.stateId];
    const stateCities = Object.values(world.cities).filter((c) => c.stateId === st.id);
    const targetCity =
      (rebelNpc.homeCityId && world.cities[rebelNpc.homeCityId]) ||
      stateCities.find((c) => !c.isCapital) ||
      stateCities[0];
    if (!targetCity) return { ok: false, reason: 'ไม่พบเมือง' };

    targetCity.isFrontline = true;
    targetCity.threatLevel = 85;
    targetCity.safety = Math.max(25, (targetCity.safety || 80) - 35);
    st.stability = Math.max(35, st.stability - 10);
    st.logisticsDirty = true;
    rebelNpc.humanThought = `นำมวลชนและกองกำลังติดอาวุธลุกฮือต่อต้านรัฐบาลที่เมือง ${targetCity.name}!`;
    recordNPCMemory(rebelNpc, world.year, `ปลุกระดมการกบฏและก่อความไม่สงบขึ้นที่ ${targetCity.name}`);

    const msg = `🔥🚩 [กบฏและการลุกฮือ!] ${rebelNpc.name} (${rebelNpc.positionTitle}) เกิดความคับข้องใจสูงสุด (ความไม่พอใจ ${rebelNpc.grievance}%) นำกองกำลังติดอาวุธและมวลชนลุกฮือก่อกบฏที่เมือง ${targetCity.name} (${st.shortName}) รัฐบาลกลางต้องเร่งส่งกำลังทหารเข้าควบคุมพื้นที่!`;
    addChronicle(world, 'REBELLION', msg, st.id, { personId: rebelNpc.id, cityId: targetCity.id });
    return { ok: true, summary: msg, city: targetCity };
  }

  // =========================================================================
  // PATCH 1.1.0 FEATURE: MULTI-FRONT WARFARE & REALISTIC COMBAT POTENTIAL
  // =========================================================================
  function calculateStateCombatPotential(world, stateId) {
    const m = getStateSummaryMetrics(world, stateId);
    if (!m) return { totalPower: 0, landPower: 0, airPower: 0, navalPower: 0, supplyReadiness: 0, commanderBonus: 1.0 };

    const st = m.state;
    const supCmd = st.positions.SUPREME_COMMANDER ? world.npcs[st.positions.SUPREME_COMMANDER] : null;
    const defMin = st.positions.DEFENSE_MINISTER ? world.npcs[st.positions.DEFENSE_MINISTER] : null;

    // Supply Readiness factor (0.35 to 1.25): armies without fuel/ammo suffer severe combat penalty!
    const totalNodes = Math.max(1, m.cities.length + m.camps.length);
    const avgSupplyPerNode = (m.totalFuel + m.totalAmmo) / totalNodes;
    const supplyReadiness = Math.min(1.25, Math.max(0.35, +(avgSupplyPerNode / 2800).toFixed(2)));

    // Commander human skill multiplier
    const cmdSkill = supCmd
      ? 1 + (supCmd.knowledge.military * 0.003 + supCmd.experience.combatExp * 0.0025 + (supCmd.intelligence - 50) * 0.002)
      : 1.0;

    // Equipment model-weighted Land, Air, and Naval Power
    const landRaw =
      m.eqTotals.tanks * 3.8 +
      m.eqTotals.apcs * 1.9 +
      m.eqTotals.artillery * 3.4 +
      m.totalTroops * 0.012;
    const airRaw =
      m.eqTotals.aircraft * 7.5 +
      m.eqTotals.airDefense * 4.5;
    const navalRaw =
      m.carriers.length * 680 +
      m.eqTotals.carrierAircraft * 8.5;

    const landPower = Math.round(landRaw * supplyReadiness * cmdSkill);
    const airPower = Math.round(airRaw * supplyReadiness * cmdSkill);
    const navalPower = Math.round(navalRaw * supplyReadiness * cmdSkill);
    const totalPower = landPower + airPower + navalPower;

    return {
      stateId,
      stateName: st.name,
      totalPower,
      landPower,
      airPower,
      navalPower,
      supplyReadinessPct: Math.round(supplyReadiness * 100),
      commanderBonusPct: Math.round((cmdSkill - 1) * 100),
      commanderName: supCmd ? supCmd.name : defMin ? defMin.name : 'เสนาธิการร่วม',
      tanks: m.eqTotals.tanks,
      artillery: m.eqTotals.artillery,
      aircraft: m.eqTotals.aircraft,
      carriers: m.carriers.length,
      troops: m.totalTroops
    };
  }

  function ensureWarMultiFronts(world, war) {
    if (!war || war.objectiveKind === 'SPECIAL_SITE_ACCESS') return;
    const atkPot = calculateStateCombatPotential(world, war.attackerId);
    const defPot = calculateStateCombatPotential(world, war.defenderId);
    war.attackerPotential = atkPot;
    war.defenderPotential = defPot;

    if (!war.fronts || war.fronts.length === 0) {
      const stA = world.states[war.attackerId];
      const stB = world.states[war.defenderId];
      const citiesA = Object.values(world.cities).filter((c) => c.stateId === war.attackerId);
      const citiesB = Object.values(world.cities).filter((c) => c.stateId === war.defenderId);
      const cityB1 = citiesB[0] || { name: 'แนวหน้าหลัก', x: 500, y: 250, terrain: 'plains' };
      const cityB2 = citiesB[1] || citiesB[0] || { name: 'แนวปีกยุทธศาสตร์', x: 520, y: 270, terrain: 'mountain' };

      war.fronts = [
        {
          id: `${war.id}_FRONT_1`,
          name: `แนวรบที่ 1: สมรภูมิภาคพื้นดินหลัก (${cityB1.name})`,
          type: 'land_primary',
          terrain: cityB1.terrain || 'plains',
          x: Math.round(((stA ? stA.mapCenter.x : 400) + cityB1.x) / 2),
          y: Math.round(((stA ? stA.mapCenter.y : 250) + cityB1.y) / 2),
          controlPct: 50, // >50 favors attacker, <50 favors defender
          attackerPower: atkPot.landPower,
          defenderPower: defPot.landPower,
          statusText: 'กำลังปะทะด้วยยานเกราะและปืนใหญ่'
        },
        {
          id: `${war.id}_FRONT_2`,
          name: `แนวรบที่ 2: แนวรบปีกยุทธศาสตร์และเส้นทางส่งกำลัง (${cityB2.name})`,
          type: 'land_flank',
          terrain: cityB2.terrain || 'mountain',
          x: Math.round(((stA ? stA.mapCenter.x : 400) + cityB2.x) / 2) + 18,
          y: Math.round(((stA ? stA.mapCenter.y : 250) + cityB2.y) / 2) - 14,
          controlPct: 50,
          attackerPower: Math.round(atkPot.landPower * 0.65),
          defenderPower: Math.round(defPot.landPower * 0.70),
          statusText: 'รบหน่วงเวลาและตัดเส้นทางลำเลียงเสบียง'
        },
        {
          id: `${war.id}_FRONT_3`,
          name: `แนวรบที่ 3: สมรภูมิครองอากาศและระบบป้องกันภัยทางอากาศ (Air & SAM Theater)`,
          type: 'air_theater',
          terrain: 'airspace',
          x: cityB1.x - 12,
          y: cityB1.y - 12,
          controlPct: 50,
          attackerPower: atkPot.airPower,
          defenderPower: defPot.airPower,
          statusText: 'ดวลฝูงบินรบยุคที่ 5 และระบบ SAM'
        }
      ];

      if (atkPot.navalPower > 0 || defPot.navalPower > 0) {
        war.fronts.push({
          id: `${war.id}_FRONT_4`,
          name: `แนวรบที่ 4: สมรภูมิทางทะเลและกองเรือบรรทุกเครื่องบิน (Maritime CSG Theater)`,
          type: 'naval_theater',
          terrain: 'ocean',
          x: Math.min(940, cityB1.x + 30),
          y: Math.min(490, cityB1.y + 28),
          controlPct: 50,
          attackerPower: atkPot.navalPower,
          defenderPower: defPot.navalPower,
          statusText: 'ปฏิบัติการครองทะเลและโจมตีจากเรือบรรทุกเครื่องบิน'
        });
      }
    } else {
      // Refresh front power numbers dynamically and advance frontline control based on realistic potential ratio!
      war.fronts.forEach((fr) => {
        if (fr.type === 'land_primary') {
          fr.attackerPower = atkPot.landPower;
          fr.defenderPower = defPot.landPower;
        } else if (fr.type === 'land_flank') {
          fr.attackerPower = Math.round(atkPot.landPower * 0.65);
          fr.defenderPower = Math.round(defPot.landPower * 0.72 * (fr.terrain === 'mountain' ? 1.2 : 1.0));
        } else if (fr.type === 'air_theater') {
          fr.attackerPower = atkPot.airPower;
          fr.defenderPower = defPot.airPower;
        } else if (fr.type === 'naval_theater') {
          fr.attackerPower = atkPot.navalPower;
          fr.defenderPower = defPot.navalPower;
        }
        const ratio = (fr.attackerPower + 100) / Math.max(100, fr.defenderPower + 100);
        const shift = Math.max(-4, Math.min(4, Math.round((ratio - 1) * 5)));
        fr.controlPct = Math.min(98, Math.max(2, fr.controlPct + shift));
        if (fr.controlPct >= 65) {
          fr.statusText = `ฝ่ายรุก (${war.attackerId}) ได้เปรียบและรุกคืบ (${fr.controlPct}%)`;
        } else if (fr.controlPct <= 35) {
          fr.statusText = `ฝ่ายรับ (${war.defenderId}) ต้านทานแข็งแกร่งและตีโต้ (${100 - fr.controlPct}%)`;
        } else {
          fr.statusText = `สมรภูมิคู่คี่ก้ำกึ่ง (ฝ่ายรุกครองพื้นที่ ${fr.controlPct}%)`;
        }
      });
    }
  }

  // =========================================================================
  // PATCH 1.1.0 FEATURE: WHAT-IF CAUSALITY SANDBOX ("เครื่องมือสร้างประวัติศาสตร์ What-If")
  // =========================================================================
  function injectWhatIfBudgetWindfall(world, stateId, amountB = 500) {
    const st = world.states[stateId];
    if (!st) return { ok: false, reason: 'ไม่พบรัฐเป้าหมาย' };

    const oldTreasury = st.treasuryB;
    st.treasuryB = +(st.treasuryB + amountB).toFixed(1);
    st.gdpB = +(st.gdpB + Math.round(amountB * 0.35)).toFixed(1);

    const head = st.positions.HEAD_OF_STATE ? world.npcs[st.positions.HEAD_OF_STATE] : null;
    const finMin = st.positions.FINANCE_MINISTER ? world.npcs[st.positions.FINANCE_MINISTER] : null;
    const defMin = st.positions.DEFENSE_MINISTER ? world.npcs[st.positions.DEFENSE_MINISTER] : null;

    // Immediate & Cascading Historical Consequences based on Leader/Cabinet Personalities!
    const stateCities = Object.values(world.cities).filter((c) => c.stateId === stateId);
    const stateCamps = Object.values(world.camps).filter((c) => c.stateId === stateId);

    // 1. Economic & Urban Mega-Project Boom
    stateCities.forEach((c) => {
      c.infrastructure = Math.min(100, +(c.infrastructure + 4).toFixed(1));
      c.economy = Math.min(100, +(c.economy + 4.5).toFixed(1));
      c.activeProject = `เมกะโปรเจกต์ความเร็วสูงและนิคมเทคโนโลยีจากงบอัดฉีดพิเศษ ($${amountB}B)`;
      c.projectProgress = Math.min(100, (c.projectProgress || 30) + 35);
    });

    // 2. Military Modernization Surge
    if (stateCamps.length > 0) {
      const mainCamp = stateCamps[0];
      mainCamp.equipment.tanks[st.primaryTank] = (mainCamp.equipment.tanks[st.primaryTank] || 0) + Math.round(amountB * 0.12);
      mainCamp.equipment.aircraft[st.primaryFighter] = (mainCamp.equipment.aircraft[st.primaryFighter] || 0) + Math.round(amountB * 0.05);
      mainCamp.equipment.airDefense[st.primarySAM] = (mainCamp.equipment.airDefense[st.primarySAM] || 0) + Math.round(amountB * 0.04);
      mainCamp.supplies.fuel += amountB * 8;
      mainCamp.supplies.ammo += amountB * 7;
      st.logisticsDirty = true;
    }

    // 3. Political & Geopolitical Doctrine Shift
    let doctrineEffect = '';
    if (head && (head.personality.ambition >= 78 || head.personality.archetype === 'power_seeker')) {
      st.policy = st.gdpB > 3500 ? 'Naval Expansion' : 'Expansionist';
      doctrineEffect = `ผู้นำ ${head.name} ซึ่งมีความทะเยอทะยานสูง (${head.personality.ambition}) ตัดสินใจเปลี่ยนยุทธศาสตร์ชาติเป็น [${st.policy}] เพื่อขยายอิทธิพลเหนือประเทศเพื่อนบ้าน`;
    } else {
      st.policy = 'Industrialization';
      doctrineEffect = `รัฐบาลนำโดย ${head ? head.name : st.shortName} และ รมว.คลัง ${finMin ? finMin.name : ''} มุ่งเน้นยุทธศาสตร์ [${st.policy}] สร้างฐานอุตสาหกรรมและเทคโนโลยีระยะยาว`;
    }

    const narrative = `💡💰 [What-If ประวัติศาสตร์เปลี่ยน: อัดฉีดงบ $${amountB}B ให้ ${st.name}] งบคงคลังพุ่งจาก $${oldTreasury}B เป็น $${st.treasuryB}B! ผลลัพธ์ที่ตามมา: (1) เมืองทั้ง ${stateCities.length} แห่งเปิดเมกะโปรเจกต์ยกระดับโครงสร้างพื้นฐานทันที, (2) กองทัพจัดซื้อรถถัง ${st.primaryTank} และฝูงบิน ${st.primaryFighter} เพิ่มเติมเข้าคลังแสง, (3) ${doctrineEffect}`;
    addChronicle(world, 'WHAT_IF', narrative, st.id);
    if (world.whatIfHistory) {
      world.whatIfHistory.unshift({ tick: world.tick, date: world.dateString, stateId: st.id, title: `อัดฉีดงบประมาณ +$${amountB}B แก่ ${st.name}`, narrative });
    }
    return { ok: true, narrative };
  }

  function injectWhatIfCarrierForSmallState(world, stateId) {
    const st = world.states[stateId];
    if (!st) return { ok: false, reason: 'ไม่พบรัฐเป้าหมาย' };

    const csgId = `CSG_WHATIF_${st.id}_${++world.nextId}`;
    const csgName = `CSG ${st.shortName} Sovereign-Carrier #${world.nextId % 100}`;
    const rng = new SeededRNG(world.seed + world.tick + world.nextId);

    const adm = generateContextualNPC(world, rng, {
      stateId: st.id,
      age: rng.int(42, 56),
      track: 'military',
      archetype: 'military_purist',
      positionId: 'CARRIER_ADMIRAL',
      assignedNodeId: csgId
    });
    ensureNPCHumanPsychology(world, adm, rng);

    world.carriers[csgId] = {
      id: csgId,
      name: csgName,
      stateId: st.id,
      carrierClass: 'CVN_Ford',
      x: Math.min(940, Math.max(60, st.mapCenter.x + 18)),
      y: Math.min(495, Math.max(60, st.mapCenter.y + 28)),
      targetX: st.mapCenter.x + 18,
      targetY: st.mapCenter.y + 28,
      homePortX: st.mapCenter.x,
      homePortY: st.mapCenter.y,
      deckCapacity: 75,
      combatRadius: 150,
      hullIntegrity: 100,
      fortressArmor: 95,
      airDefenseRating: 93,
      isMobileFortress: true,
      posture: 'Emergent Supercarrier Task Force',
      commanderId: adm.id,
      embarkedAircraft: {
        [st.primaryCarrierFighter || 'F35C']: 30,
        FA18E_SuperHornet: 24,
        E2D_Hawkeye: 5
      },
      escorts: {
        DDG_ArleighBurke: 3,
        SSN_Virginia: 1,
        AOE_SupplyOiler: 1
      },
      supplies: {
        aviationFuel: 2800,
        fleetFuel: 3800,
        airOrdnance: 2500,
        rations: 2500,
        spareParts: 950
      },
      daysOfSupply: 28,
      sortiesLaunched: 0,
      lastSortieTick: -10
    };

    st.logisticsDirty = true;

    // Analyze What-If consequences depending on whether the state is a small/medium economy vs superpower!
    const isSmallOrMidEconomy = st.gdpB < 3500;
    let consequenceText = '';
    if (isSmallOrMidEconomy) {
      st.treasuryB = Math.max(15, +(st.treasuryB - 45).toFixed(1));
      st.taxRate = Math.min(0.35, +(st.taxRate + 0.03).toFixed(2));
      st.policy = 'Naval Expansion';
      consequenceText = `เนื่องจาก ${st.name} มีขนาดเศรษฐกิจระดับกลาง/เล็ก (GDP $${st.gdpB}B) การดูแลป้อมปราการลอยน้ำและฝูงบิน 59 ลำพร้อมเรือพิฆาตคุ้มกันทำให้ต้องดึงงบคงคลังและขึ้นภาษีเป็น ${Math.round(st.taxRate * 100)}% รวมถึงเจ้ากรมส่งกำลังบำรุงต้องเร่งดึงน้ำมันอากาศยานจากเมืองหลักไปเลี้ยงกองเรือ แต่ในทางยุทธศาสตร์ ดัชนีแสนยานุภาพทางทะเลของ ${st.shortName} พุ่งขึ้นเทียบชั้นมหาอำนาจภูมิภาคทันที!`;
    } else {
      st.policy = 'Naval Expansion';
      consequenceText = `ด้วยฐานเศรษฐกิจขนาดใหญ่ของ ${st.name} กองเรือบรรทุกเครื่องบินใหม่นี้ช่วยขยายรัศมีครองทะเลและส่งกำลังทางอากาศครอบคลุมน่านน้ำสากลได้อย่างสมบูรณ์`;
    }

    const narrative = `⚓🔬 [What-If ประวัติศาสตร์เปลี่ยน: มอบกองเรือบรรทุกเครื่องบิน "${csgName}" ให้ ${st.name}] ผู้บัญชาการกองเรือ ${adm.name} นำเรือบรรทุกเครื่องบินและฝูงบินรบ 59 ลำออกปฏิบัติการ! ผลกระทบเชิงระบบ: ${consequenceText}`;
    addChronicle(world, 'WHAT_IF', narrative, st.id, { personId: adm.id });
    if (world.whatIfHistory) {
      world.whatIfHistory.unshift({ tick: world.tick, date: world.dateString, stateId: st.id, title: `มอบกองเรือบรรทุกเครื่องบินแก่ ${st.name}`, narrative });
    }
    return { ok: true, carrier: world.carriers[csgId], narrative };
  }

  // Hook into stepDay to update multi-front wars and human psychology / emergent events periodically!
  const _origStepDay = stepDay;
  stepDay = function (world, rngInstance = null) {
    _origStepDay(world, rngInstance);
    const rng = rngInstance || new SeededRNG(world.seed + world.tick * 9973);

    // Update all active wars' Multi-Fronts every 3 days
    if (world.tick % 3 === 0 && world.wars.length > 0) {
      world.wars.forEach((w) => ensureWarMultiFronts(world, w));
    }

    // Periodic Human Psychology & Emergent Political Events Check (Every 15 Days)
    if (world.tick % 15 === 0) {
      Object.values(world.npcs).forEach((npc) => {
        if (!npc.alive || npc.retired || npc.tier < 3) return;
        ensureNPCHumanPsychology(world, npc, rng);
        const st = world.states[npc.stateId];
        if (!st) return;

        // Satisfaction drifts based on state stability, approval, treasury, and personal ambition
        let delta = 0;
        if (st.stability < 65) delta -= 3;
        if (st.approval < 60) delta -= 2;
        if (st.treasuryB < 50) delta -= 3;
        if (npc.personality.ambition > 82 && npc.stage < 7) delta -= 2;
        if (st.stability >= 82 && st.treasuryB > 200) delta += 2;

        npc.satisfaction = Math.min(99, Math.max(5, npc.satisfaction + delta));
        npc.grievance = 100 - npc.satisfaction;
        npc.humanThought = generateHumanThoughtText(world, npc);

        // Spontaneous Coup / Secession / Rebellion if dissatisfaction is critically low
        if (npc.satisfaction <= 24 && rng.chance(0.06)) {
          if (npc.track === 'military' && npc.authority >= 68 && npc.personality.ambition >= 75) {
            triggerMilitaryCoup(world, npc);
          } else if (npc.positionId === 'CITY_GOVERNOR' && npc.personality.ambition >= 78) {
            triggerNPCFoundNewState(world, npc);
          } else if (npc.personality.aggression >= 72) {
            triggerArmedRebellion(world, npc);
          }
        }
      });
    }

    return world;
  };


