  Object.keys(EXTRA_EQUIPMENT_V170).forEach((cat) => {
    if (!EQUIPMENT_CATALOG[cat]) EQUIPMENT_CATALOG[cat] = {};
    Object.assign(EQUIPMENT_CATALOG[cat], EXTRA_EQUIPMENT_V170[cat]);
  });

  // Enrich all existing equipment models with standardized v1.7.0 stats (reliability, accuracy, productionTimeDays, ammoUse, logisticsBurden, techLevel, variantType)
  Object.keys(EQUIPMENT_CATALOG).forEach((cat) => {
    Object.values(EQUIPMENT_CATALOG[cat]).forEach((m) => {
      if (m.reliability === undefined) m.reliability = 90;
      if (m.accuracy === undefined) m.accuracy = m.firepower || m.attack || m.intercept || 88;
      if (m.productionTimeDays === undefined) m.productionTimeDays = cat === 'ships' ? 110 : cat === 'aircraft' ? 55 : 28;
      if (m.fuelUse === undefined) m.fuelUse = 1.5;
      if (m.ammoUse === undefined) m.ammoUse = cat === 'logistics' ? 0.1 : 2.0;
      if (m.maintNeed === undefined) m.maintNeed = 1.8;
      if (m.logisticsBurden === undefined) m.logisticsBurden = +((m.fuelUse + m.maintNeed) * 0.5).toFixed(1);
      if (m.techLevel === undefined) m.techLevel = 88;
      if (!m.variantType) {
        if (cat === 'tanks') m.variantType = 'MBT';
        else if (cat === 'apcs') m.variantType = m.id.includes('BTR') ? 'APC' : 'IFV';
        else if (cat === 'artillery') m.variantType = m.id.includes('HIMARS') || m.id.includes('Iskander') ? 'MLRS' : 'SP Artillery';
        else if (cat === 'airDefense') m.variantType = 'Air Defense';
        else if (cat === 'aircraft') {
          if (m.role === 'strategic_bomber') m.variantType = 'Bomber';
          else if (m.role === 'carrier_awacs') m.variantType = 'AEW&C';
          else if (m.role === 'tanker') m.variantType = 'Tanker';
          else if (m.role === 'recon') m.variantType = 'Reconnaissance';
          else if (m.role === 'helicopter') m.variantType = m.id.includes('AH64') ? 'Attack Helicopter' : 'Utility Helicopter';
          else if (m.role === 'carrier_strike') m.variantType = 'Strike Fighter';
          else if (m.role === 'air_superiority') m.variantType = 'Fighter';
          else m.variantType = 'Multirole Fighter';
        } else if (cat === 'ships') {
          if (m.role === 'carrier') m.variantType = 'Aircraft Carrier';
          else if (m.role === 'amphibious') m.variantType = 'Amphibious Ship';
          else if (m.role === 'escort_cg') m.variantType = 'Cruiser';
          else if (m.role === 'escort_ddg') m.variantType = 'Destroyer';
          else if (m.role === 'frigate') m.variantType = 'Frigate';
          else if (m.role === 'submarine') m.variantType = 'Attack Submarine';
          else if (m.role === 'naval_supply') m.variantType = 'Logistics Ship';
          else m.variantType = 'Destroyer';
        } else m.variantType = 'Logistics';
      }
    });
  });

