  // Ensure every state has deep v1.7.0 identity, politics, resources, industry, space, media, readiness & anti-snowball fields
  function ensureStateDeepProfileV170(world, st) {
    if (!st) return;
    const prof = EXISTING_STATE_DEEP_PROFILES[st.id] || NEW_STATES_V170.find((x) => x.id === st.id) || {};
    const resProf = prof.resourceProfile || NEW_STATE_RESOURCE_PROFILES[st.id] || {
      oil: 55, gas: 55, coal: 55, iron: 60, copper: 60, rareEarths: 55,
      uranium: 35, foodGrain: 75, water: 75, timber: 65, semiconductors: 60, chemicals: 70
    };

    if (!st.regimeCategory) st.regimeCategory = prof.regimeCategory || (/Monarchy/i.test(st.governmentType) ? 'Constitutional_Monarchy' : /Junta|Council/i.test(st.governmentType) ? 'Military_Junta' : /Socialist/i.test(st.governmentType) ? 'One_Party' : 'Democracy');
    if (!st.politicalCulture) st.politicalCulture = prof.politicalCulture || 'Constitutional National Governance';
    if (!st.economicStructure) st.economicStructure = prof.economicStructure || 'Diversified Industrial & Trade Economy';
    if (!st.doctrineType) st.doctrineType = prof.doctrineType || (st.policy === 'Naval Expansion' ? 'Naval Power' : st.policy === 'Militarist' ? 'Offensive' : 'Defensive');
    if (!st.industrialSpecialization) st.industrialSpecialization = prof.industrialSpecialization || 'Manufacturing, Logistics & Defense Support';
    if (!st.diplomaticPersonality) st.diplomaticPersonality = prof.diplomaticPersonality || 'Regional_Balancer';
    if (!st.strategicPriorities) st.strategicPriorities = prof.strategicPriorities || ['รักษาความมั่นคงอธิปไตย', 'พัฒนาเศรษฐกิจและโครงสร้างพื้นฐาน', 'เสริมสร้างพันธมิตร'];
    if (!st.foreignPolicyTendencies) st.foreignPolicyTendencies = prof.foreignPolicyTendencies || 'Pragmatic Bilateral & Regional Diplomacy';
    if (!st.rivalries) st.rivalries = (prof.rivalries || []).slice();
    if (!st.tradePartners) st.tradePartners = (prof.tradePartners || ['US', 'CN', 'TH', 'EU', 'JP']).slice();
    if (!st.vulnerabilities) st.vulnerabilities = (prof.vulnerabilities || ['ความผันผวนของเศรษฐกิจโลก']).slice();

    // 12 Resources (Section 26)
    if (!st.resources12) {
      st.resources12 = { ...resProf };
    }
    if (!st.resources) st.resources = st.resources12;
    ensureStateStrategicResources(world, st);
    st.strategicResources.oil = st.resources12.oil;
    st.strategicResources.semiconductors = st.resources12.semiconductors;
    st.strategicResources.rareEarths = st.resources12.rareEarths;
    st.strategicResources.foodGrain = st.resources12.foodGrain;

    // 9 Industrial Sectors (Section 27)
    if (!st.industrialSectors) {
      const baseInd = Math.min(96, Math.max(45, Math.round(st.educationIndex * 0.6 + (st.gdpB > 3000 ? 35 : st.gdpB > 1200 ? 25 : 15))));
      st.industrialSectors = {
        civilianIndustry: clamp(baseInd + 4, 40, 98),
        militaryIndustry: clamp(baseInd + (st.policy === 'Militarist' ? 8 : 0), 38, 98),
        aerospaceIndustry: clamp(baseInd + (['US', 'CN', 'FR', 'RU', 'GB', 'DE', 'JP', 'IN', 'BR', 'TR', 'IL'].includes(st.id) ? 10 : -5), 35, 98),
        shipbuilding: clamp(baseInd + (['CN', 'KR', 'JP', 'US', 'IT', 'FR', 'GB', 'DE', 'ES', 'TH', 'ID', 'PH'].includes(st.id) ? 10 : -6), 30, 98),
        vehicleIndustry: clamp(baseInd + (['DE', 'JP', 'CN', 'US', 'KR', 'TH', 'MX', 'FR', 'IT', 'BR'].includes(st.id) ? 9 : 0), 40, 98),
        electronics: clamp(baseInd + (['KR', 'JP', 'CN', 'US', 'SG', 'TH', 'MY', 'VN', 'DE', 'IL'].includes(st.id) ? 8 : -2), 38, 98),
        semiconductor: clamp(st.resources12.semiconductors, 25, 99),
        energyIndustry: clamp(Math.round((st.resources12.oil + st.resources12.gas) * 0.52), 35, 99),
        chemicalIndustry: clamp(st.resources12.chemicals || baseInd, 38, 98)
      };
    }

    // Political Ecosystem & Factions (Section 18)
    if (!st.factions || st.factions.length === 0) {
      const tpl = COUNTRY_FACTION_ECOSYSTEMS[st.regimeCategory] || COUNTRY_FACTION_ECOSYSTEMS.Democracy;
      st.factions = tpl.map((f) => ({
        id: `${st.id}_${f.id}`,
        name: f.name,
        type: f.type,
        influence: f.baseInfluence,
        satisfaction: clamp(Math.round((st.stability + st.approval) * 0.5 + (f.type === 'Opposition' ? -12 : 4)), 25, 95),
        leaderNpcId: null
      }));
    }

    // 10 Internal Political Pressures (Section 19)
    if (!st.politicalPressures) {
      const isAuth = ['Authoritarian', 'One_Party', 'Military_Junta'].includes(st.regimeCategory);
      st.politicalPressures = {
        governmentPopularity: st.approval || 75,
        oppositionStrength: isAuth ? 28 : clamp(100 - (st.approval || 75) + 12, 15, 85),
        militaryInfluence: st.regimeCategory === 'Military_Junta' ? 88 : st.policy === 'Militarist' ? 68 : 42,
        businessInfluence: ['US', 'KR', 'JP', 'SG', 'AE', 'DE', 'TH'].includes(st.id) ? 74 : 58,
        publicUnrest: clamp(100 - (st.stability || 80), 5, 90),
        eliteSupport: clamp(Math.round((st.stability + st.approval) * 0.52), 30, 96),
        regionalDissatisfaction: st.id === 'MM' ? 72 : 18,
        corruptionPressure: clamp(105 - (st.educationIndex || 80), 10, 75),
        economicPressure: clamp(Math.round((st.taxRate || 0.2) * 140), 12, 85),
        ideologicalPolarization: isAuth ? 35 : 44
      };
    }

    // Dictatorship Underground System (Section 20) & Democracy Dynamics (Section 21)
    if (!st.underground) {
      const isAuth = ['Authoritarian', 'One_Party', 'Military_Junta'].includes(st.regimeCategory);
      st.underground = {
        active: isAuth,
        dissidentNetwork: isAuth ? (st.id === 'MM' ? 68 : 22) : 8,
        militaryPlotLevel: isAuth ? (st.id === 'MM' ? 45 : 14) : 5,
        secretFundingB: isAuth ? 2.5 : 0,
        foreignSponsorId: null,
        intelSuppression: isAuth ? 76 : 40
      };
    }
    if (!st.democracyState) {
      st.democracyState = {
        nextElectionYear: 2026 + ((hashStr(st.id) % 4) + 1),
        coalitionStability: clamp(st.stability + 4, 30, 98),
        activeScandal: null,
        strikeLevel: 0,
        policyDispute: null
      };
    }

    // Space & Satellite Constellation (Section 44)
    if (!st.spaceProgram) {
      const spaceTier = ['US', 'CN', 'RU', 'EU', 'FR', 'IN', 'JP'].includes(st.id) ? 3 : ['GB', 'DE', 'IT', 'KR', 'IL', 'AE', 'CA', 'AU', 'BR', 'TH', 'TR', 'IR', 'PK', 'SA', 'SG'].includes(st.id) ? 2 : 1;
      st.spaceProgram = {
        spaceTier,
        reconSatellites: spaceTier === 3 ? 14 : spaceTier === 2 ? 4 : 1,
        commsSatellites: spaceTier === 3 ? 18 : spaceTier === 2 ? 6 : 2,
        navSatellites: spaceTier === 3 ? 24 : spaceTier === 2 ? 4 : 0,
        weatherSatellites: spaceTier === 3 ? 8 : spaceTier === 2 ? 3 : 1,
        earlyWarningSatellites: spaceTier === 3 ? 10 : spaceTier === 2 ? 2 : 0,
        intelBonusPct: spaceTier === 3 ? 22 : spaceTier === 2 ? 10 : 4,
        missileAccuracyBonusPct: spaceTier === 3 ? 18 : spaceTier === 2 ? 8 : 2
      };
    }

    // Media & Information Operations (Section 46)
    if (!st.informationOps) {
      st.informationOps = {
        mediaControl: ['One_Party', 'Authoritarian', 'Military_Junta'].includes(st.regimeCategory) ? 82 : 38,
        warSupport: 55,
        diplomaticReputation: clamp(Math.round(st.stability * 0.8 + 15), 25, 96),
        lastCampaignType: 'แถลงการณ์นโยบายเศรษฐกิจและความมั่นคงแห่งชาติ',
        lastCampaignTick: 0
      };
    }

    // 12-Factor Military Readiness (Section 31)
    if (!st.militaryReadiness) {
      st.militaryReadiness = {
        personnelReadiness: 88,
        equipmentReadiness: 86,
        training: 85,
        morale: 86,
        ammunition: 88,
        fuel: 88,
        spareParts: 85,
        maintenance: 87,
        commandQuality: 84,
        intelligence: 82 + (st.spaceProgram.intelBonusPct || 0) * 0.4,
        communications: 86,
        logisticsCapacity: 85,
        overallScore: 86
      };
    }

    // Anti-Snowball Burden (Section 87)
    if (st.adminBurden === undefined) st.adminBurden = 8;
    if (st.logisticsBurden === undefined) st.logisticsBurden = 10;
    if (st.occupationCostB === undefined) st.occupationCostB = 0;

    // State History (Section 49)
    if (!st.history) {
      st.history = [
        { year: 2026, date: '2026-01-01', type: 'FOUNDATION', text: `เริ่มต้นยุคปี 2026 ภายใต้ระบอบ ${st.governmentType} และนโยบาย ${st.policy}` }
      ];
    }
  }

  // Ensure every city has Tier 1-4, Archetype (14 types), Facilities, 12 Resources, Connectivity & History (Sections 7, 8, 9)
  function ensureCityDeepProfileV170(world, city) {
    if (!city) return;
    ensureCityOccupationFields(world, city);
    const st = world.states[city.stateId];

    if (!city.tier) {
      if (city.isCapital && (city.popM >= 8 || (st && st.gdpB >= 3000))) city.tier = 1;
      else if (city.urbanLevel >= 5 || city.popM >= 10) city.tier = 1;
      else if (city.isCapital || city.urbanLevel === 4 || city.popM >= 2.2) city.tier = 2;
      else if (city.urbanLevel === 3) city.tier = 3;
      else city.tier = 4;
    }

    if (!city.archetype) {
      const sp = (city.specialty || '') + ' ' + (city.name || '');
      if (city.isCapital) city.archetype = 'Capital';
      else if (/การเงิน|Finance|Financial|ตลาดทุน|ท่องเที่ยว/i.test(sp)) city.archetype = 'Financial City';
      else if (/ฐานทัพเรือ|อู่ต่อเรือ|Naval|Fleet|Submarine/i.test(sp)) city.archetype = 'Naval Base City';
      else if (/ท่าเรือ|Port|Strait|Canal|Maritime/i.test(sp)) city.archetype = 'Port City';
      else if (/อากาศยาน|การบิน|Aerospace|Aero|Fighter|Bomber|Space/i.test(sp)) city.archetype = 'Aerospace City';
      else if (/เซมิคอนดักเตอร์|ชิป|Tech|AI|ซอฟต์แวร์|Science|ไซเบอร์/i.test(sp)) city.archetype = 'Technology City';
      else if (/มหาวิทยาลัย|การศึกษา|University|Academic/i.test(sp)) city.archetype = 'University City';
      else if (/พลังงาน|น้ำมัน|ปิโตรเคมี|ก๊าซ|เขื่อน|Energy|Oil|LNG|Refinery|Nuclear/i.test(sp)) city.archetype = 'Energy City';
      else if (/เหมือง|แร่|Mining|Mineral|Iron|Gold|Lithium/i.test(sp)) city.archetype = 'Mining City';
      else if (/พรมแดน|ชายแดน|Border|Frontier|หนองคาย|เชียงราย|กาญจนบุรี/i.test(sp)) city.archetype = 'Border City';
      else if (/โลจิสติกส์|ชุมทาง|รถไฟ|Logistics|Rail|Crossroads/i.test(sp)) city.archetype = 'Logistics Hub';
      else if (/ฐานทัพ|กองทัพ|กองบิน|ป้อม|Military|Command|Armored|Bastion/i.test(sp)) city.archetype = 'Military City';
      else if (/เกษตร|อาหาร|ข้าว|Agri|Granary/i.test(sp)) city.archetype = 'Agricultural City';
      else city.archetype = 'Industrial City';
    }

    const arch = city.archetype;
    if (city.economicOutput === undefined) city.economicOutput = +(Math.max(8, (city.popM || 1.5) * (city.economy || 82) * 0.22)).toFixed(1);
    if (city.stability === undefined) city.stability = city.safety || (st ? st.stability : 84);
    if (city.development === undefined) city.development = Math.round(((city.infrastructure || 82) + (city.economy || 82)) * 0.5);
    if (city.education === undefined) city.education = clamp((st ? st.educationIndex : 80) + (arch === 'University City' || arch === 'Technology City' ? 8 : 0), 45, 99);
    if (city.health === undefined) city.health = clamp(Math.round((city.infrastructure || 80) * 0.95 + 4), 45, 99);
    if (city.industry === undefined) city.industry = clamp((city.economy || 80) + (['Industrial City', 'Aerospace City', 'Naval Base City'].includes(arch) ? 8 : -2), 35, 99);
    if (city.commerce === undefined) city.commerce = clamp((city.economy || 80) + (['Financial City', 'Capital', 'Port City', 'Border City'].includes(arch) ? 8 : 0), 35, 99);
    if (city.agriculture === undefined) city.agriculture = clamp(arch === 'Agricultural City' ? 92 : city.terrain === 'plains' ? 74 : 45, 15, 99);
    if (city.energy === undefined) city.energy = clamp(arch === 'Energy City' ? 95 : 72, 30, 99);

    if (city.fuelStorage === undefined) city.fuelStorage = (city.urbanLevel || 3) * 1200 + (arch === 'Energy City' || arch === 'Port City' ? 2500 : 0);
    if (city.ammoStorage === undefined) city.ammoStorage = (city.urbanLevel || 3) * 900 + (arch === 'Military City' || arch === 'Naval Base City' ? 2000 : 0);
    if (city.foodStorage === undefined) city.foodStorage = (city.urbanLevel || 3) * 1400 + (arch === 'Agricultural City' ? 2500 : 0);
    if (city.sparePartsStorage === undefined) city.sparePartsStorage = (city.urbanLevel || 3) * 650 + (arch === 'Industrial City' ? 1500 : 0);
    if (city.militaryPresence === undefined) city.militaryPresence = clamp(Math.round((city.troops || 3500) / 120) + (['Military City', 'Naval Base City', 'Border City'].includes(arch) ? 35 : 15), 10, 100);

    const isCoastal = ['Port City', 'Naval Base City'].includes(arch) || /Port|Naval|Sea|Coast|Bay|Strait|ท่าเรือ|สัตหีบ|ชลบุรี|ระยอง|สงขลา|ภูเก็ต|ตราด|สมุทรปราการ/i.test(city.specialty + ' ' + city.name);
    if (city.airport === undefined) city.airport = city.tier === 1 ? 5 : city.tier === 2 || arch === 'Aerospace City' ? 4 : 3;
    if (city.port === undefined) city.port = isCoastal ? (city.tier <= 2 ? 5 : 4) : (city.id === 'CITY_TH_NKI' || /River|แม่น้ำ|โขง|เจ้าพระยา/i.test(city.regionName + ' ' + city.specialty) ? 3 : 0);
    if (city.rail === undefined) city.rail = city.id === 'CITY_TH_NKI' ? 5 : (city.tier <= 2 || arch === 'Logistics Hub' ? 4 : 3);
    if (city.roadConnectivity === undefined) city.roadConnectivity = clamp((city.infrastructure || 82) + (arch === 'Logistics Hub' || arch === 'Border City' ? 6 : 0), 40, 99);
    if (city.strategicImportance === undefined) {
      city.strategicImportance = city.id === 'CITY_TH_NKI' ? 94 : clamp((city.isCapital ? 95 : (5 - (city.tier || 3)) * 18 + 30) + (['Naval Base City', 'Port City', 'Border City', 'Energy City', 'Technology City'].includes(arch) ? 10 : 0), 35, 99);
    }

    if (!city.localFaction) {
      city.localFaction = st && st.factions && st.factions[0] ? st.factions[hashStr(city.id) % st.factions.length].name : FACTIONS[0];
    }
    if (city.localUnrest === undefined) city.localUnrest = city.unrest || 8;

    if (!city.facilities) {
      city.facilities = {
        university: city.tier <= 2 || arch === 'University City' || arch === 'Technology City',
        industrialZones: ['Industrial City', 'Port City', 'Logistics Hub', 'Capital', 'Energy City'].includes(arch) || city.urbanLevel >= 4,
        techSector: ['Technology City', 'Capital', 'Financial City', 'University City', 'Aerospace City'].includes(arch),
        shipyard: ['Naval Base City', 'Port City'].includes(arch),
        aircraftFactory: arch === 'Aerospace City' || (city.isCapital && st && st.gdpB > 2500),
        tankFactory: ['Industrial City', 'Military City'].includes(arch) && (city.urbanLevel >= 4),
        semiconductorPlant: arch === 'Technology City' || ['CITY_TH_PTE', 'CITY_TH_AYA', 'CITY_SG_PEN', 'CITY_SG_WDL', 'CITY_KR_SEL', 'CITY_JP_TYO', 'CITY_CN_SZ', 'CITY_US_SFO', 'CITY_US_PHX', 'CITY_EU_AMS', 'CITY_DE_LEJ'].includes(city.id),
        refinery: ['Energy City', 'Port City'].includes(arch),
        powerPlant: true,
        logisticsHub: ['Logistics Hub', 'Port City', 'Border City', 'Capital'].includes(arch) || city.id === 'CITY_TH_NKI'
      };
    }

    if (!city.resourceProduction) {
      const r12 = (st && st.resources12) || { oil: 50, gas: 50, coal: 50, iron: 50, copper: 50, rareEarths: 50, uranium: 30, foodGrain: 70, water: 75, timber: 60, semiconductors: 55, chemicals: 65 };
      city.resourceProduction = {
        oil: arch === 'Energy City' ? Math.round(r12.oil * 0.45) : Math.round(r12.oil * 0.1),
        gas: arch === 'Energy City' ? Math.round(r12.gas * 0.45) : Math.round(r12.gas * 0.1),
        coal: arch === 'Mining City' ? Math.round(r12.coal * 0.4) : Math.round(r12.coal * 0.1),
        iron: ['Mining City', 'Industrial City'].includes(arch) ? Math.round(r12.iron * 0.4) : Math.round(r12.iron * 0.1),
        copper: arch === 'Mining City' ? Math.round(r12.copper * 0.4) : Math.round(r12.copper * 0.1),
        rareEarths: arch === 'Mining City' ? Math.round(r12.rareEarths * 0.45) : Math.round(r12.rareEarths * 0.08),
        uranium: arch === 'Mining City' ? Math.round(r12.uranium * 0.35) : 0,
        foodGrain: arch === 'Agricultural City' ? Math.round(r12.foodGrain * 0.5) : Math.round(r12.foodGrain * 0.18),
        water: 25,
        timber: city.terrain === 'forest' ? 35 : 10,
        semiconductors: city.facilities.semiconductorPlant ? Math.round(r12.semiconductors * 0.5) : 5,
        chemicals: city.facilities.refinery || city.facilities.industrialZones ? Math.round(r12.chemicals * 0.35) : 8
      };
    }
    if (!city.resources) city.resources = city.resourceProduction;

    if (!city.localHistory) {
      city.localHistory = [
        { year: 2026, text: `${city.name} ทำหน้าที่เป็น ${city.archetype} (${city.specialty || 'ศูนย์กลางภูมิภาค'}) ของ ${city.stateId}` }
      ];
    }
  }

  // Build Abstract Route Network between Cities (Domestic & Cross-Border Trade/Rail/Maritime Routes, Section 74 & 75)
  function buildCityRouteNetworkV170(world) {
    const allCities = Object.values(world.cities);
    allCities.forEach((c) => {
      if (c.connectedCityIds && c.connectedCityIds.length >= 2) return;
      const sameState = allCities
        .filter((o) => o.id !== c.id && o.stateId === c.stateId)
        .sort((a, b) => Math.hypot(a.x - c.x, a.y - c.y) - Math.hypot(b.x - c.x, b.y - c.y))
        .slice(0, 3)
        .map((o) => o.id);
      const crossBorder = (c.archetype === 'Border City' || c.archetype === 'Port City' || c.isCapital || c.id === 'CITY_TH_NKI')
        ? allCities
            .filter((o) => o.stateId !== c.stateId)
            .sort((a, b) => Math.hypot(a.x - c.x, a.y - c.y) - Math.hypot(b.x - c.x, b.y - c.y))
            .slice(0, 2)
            .map((o) => o.id)
        : [];
      c.connectedCityIds = [...new Set([...sameState, ...crossBorder])];
    });
    // Explicit strategic Laos-Mekong-China-Vietnam rail/trade corridor for Nong Khai (Section 10)
    if (world.cities.CITY_TH_NKI) {
      const nkiLinks = ['CITY_TH_UDN', 'CITY_TH_KKN', 'CITY_TH_BKK', 'CITY_CN_KM', 'CITY_VN_HAN'].filter((id) => world.cities[id]);
      world.cities.CITY_TH_NKI.connectedCityIds = [...new Set([...nkiLinks, ...(world.cities.CITY_TH_NKI.connectedCityIds || [])])];
    }
    allCities.forEach((c) => {
      c.strategicRoutes = (c.connectedCityIds || []).map((toId) => {
        const dest = world.cities[toId];
        const distKm = dest ? Math.max(45, Math.round(Math.hypot(dest.x - c.x, dest.y - c.y) * 18)) : 250;
        const rType = dest && dest.stateId !== c.stateId
          ? ((c.port >= 3 && dest.port >= 3) ? 'Maritime Trade Route' : 'Cross-Border Rail & Trade')
          : (c.rail >= 4 && dest && dest.rail >= 4 ? 'High-Speed Rail & Logistics' : 'National Highway & Rail');
        return { toCityId: toId, type: rType, distance: distKm };
      });
    });
  }

  // Enrich Military Bases with specialized Base Types & Air/Naval Capacities (Sections 38, 39, 40, 41)
  function ensureCampDeepProfileV170(world, camp) {
    if (!camp) return;
    if (!camp.baseCategory) {
      const mapType = {
        permanent_camp: 'Army Base (ค่ายทหารบก/ยานเกราะ)',
        airbase: 'Air Base (ฐานทัพอากาศ)',
        naval_base: 'Naval Base (ฐานทัพเรือ)',
        logistics_base: 'Logistics Base (ศูนย์ส่งกำลังบำรุง)',
        training_base: 'Training Base (ศูนย์ฝึกศึกษาทางทหาร)',
        missile_base: 'Missile Base (ฐานขีปนาวุธยุทธศาสตร์)',
        intel_base: 'Intelligence Base (สถานีเรดาร์และข่าวกรอง)',
        temp_camp: 'Forward Operating Base (ฐานปฏิบัติการส่วนหน้า)'
      };
      camp.baseCategory = mapType[camp.type] || 'Army Base (ค่ายทหารหลัก)';
    }
    // Link camp to nearest domestic city (Section 41: Cities <-> Military)
    if (!camp.linkedCityId) {
      const stCities = Object.values(world.cities).filter((c) => c.stateId === camp.stateId);
      if (stCities.length > 0) {
        const nearest = stCities.slice().sort((a, b) => Math.hypot(a.x - camp.x, a.y - camp.y) - Math.hypot(b.x - camp.x, b.y - camp.y))[0];
        camp.linkedCityId = nearest.id;
      }
    }
    // Airbase capacity attributes (Section 39)
    if (camp.runwayCapacity === undefined) camp.runwayCapacity = camp.type === 'airbase' ? 120 : 24;
    if (camp.aircraftCapacity === undefined) camp.aircraftCapacity = camp.type === 'airbase' ? 96 : camp.type === 'naval_base' ? 36 : 18;
    if (camp.fuelStorage === undefined) camp.fuelStorage = camp.type === 'logistics_base' ? 9000 : camp.type === 'airbase' || camp.type === 'naval_base' ? 6000 : 4200;
    if (camp.weaponsStorage === undefined) camp.weaponsStorage = camp.type === 'logistics_base' || camp.type === 'missile_base' ? 8500 : 4000;
    if (camp.maintenanceCapacity === undefined) camp.maintenanceCapacity = camp.type === 'airbase' || camp.type === 'naval_base' ? 94 : 88;
    if (camp.airDefenseRating === undefined) camp.airDefenseRating = camp.type === 'missile_base' || camp.type === 'airbase' ? 92 : 80;
    // Naval base capacity attributes (Section 40)
    if (camp.berthCapacity === undefined) camp.berthCapacity = camp.type === 'naval_base' ? 28 : 0;
    if (camp.repairCapacity === undefined) camp.repairCapacity = camp.type === 'naval_base' ? 92 : 0;
    if (camp.dryDockCount === undefined) camp.dryDockCount = camp.type === 'naval_base' ? 4 : 0;
  }

  // Ensure every NPC has full v1.7.0 attributes, career tracks, ideologies & relationships (Sections 12-17, 50)
  function ensureNPCDeepProfileV170(world, npc, rngInstance) {
    if (!npc) return;
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + hashStr(npc.id));
    const posDef = POSITION_MATRIX[npc.positionId] || POSITION_MATRIX.JUNIOR_OFFICER;
    if (!npc.firstName || !npc.lastName) {
      const parts = String(npc.name || "Officer").split(" ");
      if (!npc.firstName) npc.firstName = parts[0] || "Officer";
      if (!npc.lastName) npc.lastName = parts.slice(1).join(" ") || "Unknown";
    }
    if (npc.birthYear === undefined) npc.birthYear = (world.year || 2026) - (npc.age || 35);
    if (!npc.region) npc.region = world.states[npc.stateId]?.region || "Thailand";
    if (npc.stage === undefined) npc.stage = posDef.stage;
    if (npc.tier === undefined) npc.tier = posDef.tier;
    if (npc.authority === undefined) npc.authority = posDef.authority;
    if (!npc.positionTitle) npc.positionTitle = posDef.title;
    if (npc.education && !npc.education.specialty) {
      npc.education.specialty = npc.track === "military" ? "ยุทธศาสตร์ทหารและการส่งกำลังบำรุงร่วม" : "รัฐประศาสนศาสตร์และเศรษฐศาสตร์มหภาค";
    }
    if (npc.personality && !npc.personality.archetypeLabel) {
      const archObj = ARCHETYPES.find((a) => a.id === npc.personality.archetype);
      npc.personality.archetypeLabel = archObj ? archObj.label : "ผู้ปฏิบัติงานมืออาชีพ";
    }
    if (!npc.shortTermGoal) npc.shortTermGoal = "สร้างผลงานในตำแหน่งและเพิ่มความพร้อมของหน่วยงาน";
    if (!npc.longTermGoal) npc.longTermGoal = getCareerTargetForArchetype(npc.personality?.archetype || "quiet_professional", npc.track);
    if (!npc.careerPhase) npc.careerPhase = npc.stage >= 6 ? "ปฏิบัติหน้าที่บริหารระดับสูง" : npc.stage >= 3 ? "สะสมผลงานและสร้างเครือข่ายเพื่อเลื่อนขั้น" : "กำลังศึกษาและฝึกอบรม";
    if (!npc.lastDecisionText) npc.lastDecisionText = "ตรวจสอบความพร้อมของหน่วยงานในรับผิดชอบ";
    if (!npc.memories) npc.memories = [];
    if (!Array.isArray(npc.careerHistory)) {
      npc.careerHistory = [{ year: world.year || 2026, positionId: npc.positionId, title: posDef.title, note: `ปฏิบัติงานในสังกัด ${npc.stateId}` }];
    } else {
      npc.careerHistory.forEach((ch) => {
        if (!ch.title) ch.title = POSITION_MATRIX[ch.positionId]?.title || ch.positionId;
        if (!ch.note) ch.note = `ปฏิบัติงานในสังกัด ${npc.stateId}`;
      });
    }
    ensureNPCHumanPsychology(world, npc, rng);

    if (npc._staggerOffset === undefined) npc._staggerOffset = hashStr(npc.id) % 7;
    if (!npc.nationality) npc.nationality = npc.stateId;
    if (!npc.currentCityId) {
      if (npc.assignedNodeId && world.cities[npc.assignedNodeId]) npc.currentCityId = npc.assignedNodeId;
      else if (npc.homeCityId && world.cities[npc.homeCityId]) npc.currentCityId = npc.homeCityId;
      else {
        const cap = Object.values(world.cities).find((c) => c.stateId === npc.stateId && c.isCapital);
        npc.currentCityId = cap ? cap.id : npc.homeCityId;
      }
    }
    if (!npc.occupation) {
      const posDef = POSITION_MATRIX[npc.positionId];
      npc.occupation = posDef ? posDef.title : npc.positionTitle || 'ข้าราชการ/เจ้าหน้าที่รัฐ';
    }
    // 4 Career Track Scores (Section 12)
    if (npc.politicalTrack === undefined) npc.politicalTrack = npc.track === 'political' ? rng.int(65, 95) : rng.int(20, 55);
    if (npc.militaryTrack === undefined) npc.militaryTrack = npc.track === 'military' ? rng.int(68, 96) : rng.int(15, 45);
    if (npc.adminTrack === undefined) npc.adminTrack = (npc.track === 'civilian' || npc.track === 'political') ? rng.int(62, 92) : rng.int(25, 58);
    if (npc.businessTrack === undefined) npc.businessTrack = npc.track === 'business' ? rng.int(68, 95) : rng.int(20, 52);

    // Core Character Attributes (Section 12)
    if (npc.ambition === undefined) npc.ambition = npc.personality ? npc.personality.ambition : 65;
    if (npc.loyalty === undefined) npc.loyalty = npc.personality ? npc.personality.loyalty : 72;
    if (npc.planning === undefined) npc.planning = clamp(Math.round((npc.intelligence * 0.55) + (npc.knowledge.logistics * 0.45)), 35, 99);
    if (npc.leadership === undefined) npc.leadership = clamp(Math.round((npc.authority * 0.45) + (npc.experience.commandExp * 0.35) + 25), 35, 99);
    if (npc.charisma === undefined) npc.charisma = clamp(rng.int(42, 94), 30, 99);
    if (npc.discipline === undefined) npc.discipline = clamp(npc.track === 'military' ? rng.int(68, 96) : rng.int(50, 90), 30, 99);
    if (npc.integrity === undefined) npc.integrity = npc.personality ? npc.personality.integrity : 70;
    if (npc.riskTolerance === undefined) npc.riskTolerance = clamp(100 - (npc.personality ? npc.personality.caution : 50), 15, 95);

    if (!npc.politicalIdeology) npc.politicalIdeology = (npc.personality && npc.personality.ideology) || rng.pick(['Constitutionalist', 'Reformist', 'Nationalist', 'Social-Democrat', 'Conservative', 'Pragmatist']);
    if (!npc.militaryIdeology) npc.militaryIdeology = rng.pick(['Combined Arms Maneuver', 'Maritime & Air Deterrence', 'Precision Artillery & Missile', 'Territorial Defense', 'Network-Centric Warfare']);
    if (!npc.economicIdeology) npc.economicIdeology = rng.pick(['Industrial State-Guided', 'Free-Market Export', 'Tech & Innovation-Led', 'Welfare & Infrastructure', 'Resource Sovereign']);

    if (!npc.personalGoals) {
      npc.personalGoals = [
        npc.shortTermGoal || 'สร้างผลงานในตำแหน่งปัจจุบัน',
        npc.longTermGoal || 'ก้าวขึ้นสู่ตำแหน่งบริหารระดับสูงของประเทศ'
      ];
    }
    if (!npc.relationships) npc.relationships = [];
    if (npc.failures === undefined) npc.failures = npc.mistakes || 0;
  }

  // Build Personal Relationships Network within each State (Section 17: friend, ally, mentor, student, rival, enemy, subordinate, superior, family, political_partner, military_rival, business_partner)
  function buildNPCRelationshipNetworkV170(world, rng) {
    const byState = {};
    Object.values(world.npcs).forEach((n) => {
      if (!n.alive) return;
      (byState[n.stateId] = byState[n.stateId] || []).push(n);
    });

    Object.keys(byState).forEach((stId) => {
      const list = byState[stId].sort((a, b) => b.authority - a.authority);
      if (list.length < 3) return;
      const head = list[0];
      for (let i = 0; i < list.length; i++) {
        const a = list[i];
        if (!a.relationships) a.relationships = [];
        if (a.relationships.length >= 3) continue;

        // 1. Superior / Subordinate or Mentor / Student
        if (i > 0 && head && head.id !== a.id && i <= 10) {
          const isSameFaction = a.faction === head.faction;
          const relType = isSameFaction ? (a.track === 'political' ? 'political_partner' : 'ally') : (a.track === 'military' && a.ambition > 78 ? 'military_rival' : 'subordinate');
          a.relationships.push({ targetId: head.id, type: relType, strength: isSameFaction ? 78 : 55 });
        }
        // 2. Peer Rival or Ally in same track
        const peer = list[(i + 1) % list.length];
        if (peer && peer.id !== a.id) {
          const isRival = a.track === peer.track && Math.abs(a.stage - peer.stage) <= 1 && a.ambition >= 65 && peer.ambition >= 65 && a.faction !== peer.faction;
          const rType = isRival
            ? (a.track === 'military' ? 'military_rival' : 'rival')
            : a.lastName === peer.lastName
            ? 'family'
            : a.age - peer.age >= 12
            ? 'mentor'
            : peer.age - a.age >= 12
            ? 'student'
            : a.track === 'business'
            ? 'business_partner'
            : 'friend';
          a.relationships.push({ targetId: peer.id, type: rType, strength: isRival ? -65 : 72 });
        }
      }
    });
  }

  // Populate 1,850+ Meaningful Initial NPCs across all 36 States, Age Brackets & Professional Tracks (Sections 11-16)
  function populateInitialNPCsV170(world, rng) {
    const usedNames = new Set();
    Object.values(world.npcs).forEach((n) => usedNames.add(n.name));

    function makeUniqueNPC(opts) {
      const npc = generateContextualNPC(world, rng, opts);
      // Ensure zero duplicate full names across the world (Section 91)
      let guard = 0;
      while (usedNames.has(npc.name) && guard++ < 12) {
        const st = world.states[npc.stateId];
        const pool = NAME_POOLS[st ? st.region : 'NorthAmerica'] || NAME_POOLS.NorthAmerica;
        const fRaw = rng.pick(npc.gender === 'M' ? pool.male : pool.female);
        const lRaw = rng.pick(pool.last);
        const midPool = pool.male.concat(pool.female);
        const midInitial = guard > 5 ? ' ' + rng.pick(midPool).charAt(0).toUpperCase() + '.' : '';
        npc.firstName = fRaw.charAt(0).toUpperCase() + fRaw.slice(1);
        npc.lastName = lRaw.charAt(0).toUpperCase() + lRaw.slice(1);
        npc.name = `${npc.firstName}${midInitial} ${npc.lastName}`;
      }
      usedNames.add(npc.name);
      ensureNPCDeepProfileV170(world, npc, rng);
      return npc;
    }

    // 1. Ensure every City (all 335+ cities!) has its own dedicated City Governor
    Object.values(world.cities).forEach((city) => {
      const gov = city.governorId ? world.npcs[city.governorId] : null;
      const sharedGov = gov && gov.assignedNodeId !== city.id;
      if (!gov || sharedGov) {
        const newGov = makeUniqueNPC({
          stateId: city.stateId,
          age: rng.int(36, 62),
          track: 'civilian',
          archetype: city.tier <= 2 ? 'city_builder' : 'quiet_professional',
          positionId: 'CITY_GOVERNOR',
          homeCityId: city.id,
          assignedNodeId: city.id
        });
        city.governorId = newGov.id;
      }
    });

    // 2. Ensure every Military Base (all 96 bases!) has its own dedicated Base Commander
    Object.values(world.camps).forEach((camp) => {
      const cmd = camp.commanderId ? world.npcs[camp.commanderId] : null;
      const st = world.states[camp.stateId];
      if (!cmd || (st && st.positions.SUPREME_COMMANDER === cmd.id)) {
        const newCmd = makeUniqueNPC({
          stateId: camp.stateId,
          age: rng.int(38, 56),
          track: 'military',
          archetype: camp.type === 'logistics_base' ? 'logistics_master' : 'military_purist',
          positionId: 'BASE_COMMANDER',
          homeCityId: camp.linkedCityId || null,
          assignedNodeId: camp.id
        });
        camp.commanderId = newCmd.id;
      }
    });

    // 3. Ensure every Company (all 50 companies!) has a dedicated CEO + CFO + CTO
    world.companies.forEach((co) => {
      if (!co.ceoId || !world.npcs[co.ceoId]) {
        const ceo = makeUniqueNPC({
          stateId: co.stateId,
          age: rng.int(42, 64),
          track: 'business',
          archetype: 'opportunist',
          positionId: 'CEO_DIRECTOR',
          homeCityId: co.cityId,
          assignedNodeId: co.id
        });
        co.ceoId = ceo.id;
      }
      if (!co.cfoId) {
        const cfo = makeUniqueNPC({
          stateId: co.stateId,
          age: rng.int(35, 55),
          track: 'business',
          archetype: 'opportunist',
          positionId: 'CFO_EXECUTIVE',
          homeCityId: co.cityId,
          assignedNodeId: co.id
        });
        co.cfoId = cfo.id;
      }
      if (!co.ctoId) {
        const cto = makeUniqueNPC({
          stateId: co.stateId,
          age: rng.int(34, 54),
          track: 'business',
          archetype: 'city_builder',
          positionId: 'CTO_EXECUTIVE',
          homeCityId: co.cityId,
          assignedNodeId: co.id
        });
        co.ctoId = cto.id;
      }
    });

    // 4. For each of the 36 States, staff full Cabinet, Military High Command, Faction Leaders, Diplomats, Scientists & Generational Age Pipeline
    const roleRosterPerState = [
      // Senior Political & Cabinet (Age 45-68)
      { pos: 'PRIME_MINISTER', track: 'political', ageMin: 46, ageMax: 66, arch: 'power_seeker', stateKey: 'PRIME_MINISTER' },
      { pos: 'FOREIGN_MINISTER', track: 'political', ageMin: 44, ageMax: 64, arch: 'ideologue', stateKey: 'FOREIGN_MINISTER' },
      { pos: 'INTERIOR_MINISTER', track: 'political', ageMin: 45, ageMax: 63, arch: 'power_seeker', stateKey: 'INTERIOR_MINISTER' },
      { pos: 'INDUSTRY_MINISTER', track: 'civilian', ageMin: 42, ageMax: 62, arch: 'city_builder', stateKey: 'INDUSTRY_MINISTER' },
      { pos: 'PARTY_LEADER', track: 'political', ageMin: 45, ageMax: 67, arch: 'power_seeker', stateKey: 'PARTY_LEADER' },
      { pos: 'OPPOSITION_LEADER', track: 'political', ageMin: 40, ageMax: 62, arch: 'ideologue', stateKey: 'OPPOSITION_LEADER' },
      { pos: 'DEPUTY_MINISTER', track: 'political', ageMin: 38, ageMax: 55, arch: 'city_builder' },
      { pos: 'MP_LEGISLATOR', track: 'political', ageMin: 32, ageMax: 60, arch: 'ideologue' },
      { pos: 'MP_LEGISLATOR', track: 'political', ageMin: 35, ageMax: 64, arch: 'power_seeker' },
      { pos: 'POLITICAL_STRATEGIST', track: 'political', ageMin: 34, ageMax: 54, arch: 'ideologue' },
      { pos: 'DIPLOMAT', track: 'political', ageMin: 36, ageMax: 58, arch: 'quiet_professional' },
      { pos: 'DIPLOMAT', track: 'political', ageMin: 32, ageMax: 50, arch: 'ideologue' },

      // Military Service Chiefs & Commanders (Age 36-62)
      { pos: 'ARMY_CHIEF', track: 'military', ageMin: 48, ageMax: 61, arch: 'military_purist', stateKey: 'ARMY_CHIEF' },
      { pos: 'NAVY_CHIEF', track: 'military', ageMin: 47, ageMax: 60, arch: 'military_purist', stateKey: 'NAVY_CHIEF' },
      { pos: 'AIR_FORCE_CHIEF', track: 'military', ageMin: 46, ageMax: 59, arch: 'military_purist', stateKey: 'AIR_FORCE_CHIEF' },
      { pos: 'INTELLIGENCE_CHIEF', track: 'military', ageMin: 44, ageMax: 60, arch: 'ideologue', stateKey: 'INTELLIGENCE_CHIEF' },
      { pos: 'THEATER_COMMANDER', track: 'military', ageMin: 45, ageMax: 58, arch: 'military_purist' },
      { pos: 'ARMY_COMMANDER', track: 'military', ageMin: 44, ageMax: 57, arch: 'military_purist' },
      { pos: 'CORPS_COMMANDER', track: 'military', ageMin: 42, ageMax: 54, arch: 'military_purist' },
      { pos: 'DIVISION_COMMANDER', track: 'military', ageMin: 39, ageMax: 51, arch: 'military_purist' },
      { pos: 'DIVISION_COMMANDER', track: 'military', ageMin: 38, ageMax: 50, arch: 'logistics_master' },
      { pos: 'BRIGADE_COMMANDER', track: 'military', ageMin: 35, ageMax: 46, arch: 'military_purist' },
      { pos: 'BATTALION_COMMANDER', track: 'military', ageMin: 31, ageMax: 41, arch: 'military_purist' },
      { pos: 'FLEET_COMMANDER', track: 'military', ageMin: 42, ageMax: 55, arch: 'military_purist' },
      { pos: 'SQUADRON_COMMANDER', track: 'military', ageMin: 32, ageMax: 43, arch: 'military_purist' },
      { pos: 'OPERATIONS_OFFICER', track: 'military', ageMin: 30, ageMax: 42, arch: 'military_purist' },
      { pos: 'TRAINING_OFFICER', track: 'military', ageMin: 33, ageMax: 48, arch: 'quiet_professional' },
      { pos: 'MEDICAL_OFFICER', track: 'military', ageMin: 32, ageMax: 50, arch: 'quiet_professional' },
      { pos: 'ENGINEER_OFFICER', track: 'military', ageMin: 30, ageMax: 46, arch: 'city_builder' },

      // Business, Civilian & Academic / Scientific Track
      { pos: 'COMPANY_CHAIRMAN', track: 'business', ageMin: 50, ageMax: 68, arch: 'opportunist' },
      { pos: 'CHIEF_SCIENTIST', track: 'civilian', ageMin: 40, ageMax: 64, arch: 'city_builder', stateKey: 'CHIEF_SCIENTIST' },
      { pos: 'PROFESSOR_ACADEMIC', track: 'civilian', ageMin: 38, ageMax: 65, arch: 'quiet_professional' },
      { pos: 'JOURNALIST_MEDIA', track: 'civilian', ageMin: 28, ageMax: 52, arch: 'ideologue' },

      // Generational Youth & Rising Pipeline (Age 20-35 + Elder 70+)
      { pos: 'MID_OFFICER', track: 'military', ageMin: 29, ageMax: 37, arch: 'military_purist' },
      { pos: 'MID_OFFICER', track: 'civilian', ageMin: 29, ageMax: 37, arch: 'city_builder' },
      { pos: 'JUNIOR_OFFICER', track: 'military', ageMin: 23, ageMax: 29, arch: 'military_purist' },
      { pos: 'JUNIOR_OFFICER', track: 'political', ageMin: 24, ageMax: 30, arch: 'power_seeker' },
      { pos: 'JUNIOR_OFFICER', track: 'business', ageMin: 23, ageMax: 29, arch: 'opportunist' },
      { pos: 'CADET_TRAINEE', track: 'military', ageMin: 20, ageMax: 23, arch: 'military_purist' },
      { pos: 'CADET_TRAINEE', track: 'civilian', ageMin: 20, ageMax: 23, arch: 'city_builder' },
      { pos: 'APPLICANT', track: 'political', ageMin: 20, ageMax: 22, arch: 'power_seeker' },
      { pos: 'RETIRED', track: 'political', ageMin: 70, ageMax: 78, arch: 'ideologue' }
    ];

    Object.values(world.states).forEach((st) => {
      const stCities = Object.values(world.cities).filter((c) => c.stateId === st.id);
      const cap = stCities.find((c) => c.isCapital) || stCities[0];
      const capId = cap ? cap.id : null;

      // Ensure core 5 positions exist first
      ['HEAD_OF_STATE', 'DEFENSE_MINISTER', 'SUPREME_COMMANDER', 'LOGISTICS_CHIEF', 'FINANCE_MINISTER'].forEach((pk) => {
        if (!st.positions[pk] || !world.npcs[st.positions[pk]]) {
          const tr = pk === 'HEAD_OF_STATE' ? 'political' : pk === 'FINANCE_MINISTER' ? 'civilian' : 'military';
          const n = makeUniqueNPC({
            stateId: st.id,
            age: rng.int(46, 64),
            track: tr,
            positionId: pk,
            homeCityId: capId,
            assignedNodeId: capId
          });
          st.positions[pk] = n.id;
        }
      });

      roleRosterPerState.forEach((spec, idx) => {
        const homeCity = stCities[idx % Math.max(1, stCities.length)] || cap;
        const npc = makeUniqueNPC({
          stateId: st.id,
          age: rng.int(spec.ageMin, spec.ageMax),
          track: spec.track,
          archetype: spec.arch,
          positionId: spec.pos,
          homeCityId: homeCity ? homeCity.id : capId,
          assignedNodeId: homeCity ? homeCity.id : capId
        });
        if (spec.pos === 'RETIRED') npc.retired = true;
        if (spec.stateKey) st.positions[spec.stateKey] = npc.id;
      });

      // Assign Faction Leaders
      const stPolNpcs = Object.values(world.npcs).filter((n) => n.alive && n.stateId === st.id && n.tier >= 2);
      if (st.factions && stPolNpcs.length > 0) {
        st.factions.forEach((fac, fIdx) => {
          fac.leaderNpcId = stPolNpcs[fIdx % stPolNpcs.length].id;
        });
      }
    });

    // Ensure all NPCs (including base 276) have full v1.7.0 profile & 100% unique names
    const finalSeenNames = new Set();
    Object.values(world.npcs).forEach((n) => {
      let g = 0;
      while (finalSeenNames.has(n.name) && g++ < 80) {
        const st = world.states[n.stateId];
        const pool = NAME_POOLS[st ? st.region : "NorthAmerica"] || NAME_POOLS.NorthAmerica;
        const fRaw = rng.pick(n.gender === "M" ? pool.male : pool.female);
        const lRaw = rng.pick(pool.last);
        const mRaw = g > 8 ? " " + rng.pick(n.gender === "M" ? pool.male : pool.female) : "";
        n.firstName = fRaw.charAt(0).toUpperCase() + fRaw.slice(1);
        n.lastName = lRaw.charAt(0).toUpperCase() + lRaw.slice(1);
        n.name = `${n.firstName}${mRaw} ${n.lastName}`;
      }
      finalSeenNames.add(n.name);
      ensureNPCDeepProfileV170(world, n, rng);
    });
    // Build personal relationships across NPCs
    buildNPCRelationshipNetworkV170(world, rng);
  }

  // AI Candidate Selection for Vacancies & Succession (Sections 95, 96, 97)
  function selectBestCandidateForRole(world, stateId, positionId, assignedNodeId = null, rngInstance = null) {
    const st = world.states[stateId];
    if (!st) return null;
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + world.tick + hashStr(stateId + positionId));
    const posDef = POSITION_MATRIX[positionId] || POSITION_MATRIX.SENIOR_OFFICIAL;
    const head = st.positions.HEAD_OF_STATE ? world.npcs[st.positions.HEAD_OF_STATE] : null;

    const cands = Object.values(world.npcs).filter(
      (n) => n.alive && !n.retired && n.stateId === stateId && n.positionId !== 'HEAD_OF_STATE' && n.stage >= 3
    );

    if (cands.length === 0) {
      const fallback = generateContextualNPC(world, rng, {
        stateId,
        age: rng.int(36, 54),
        track: posDef.track === 'mixed' ? 'civilian' : posDef.track || 'civilian',
        positionId,
        assignedNodeId
      });
      ensureNPCDeepProfileV170(world, fallback, rng);
      return fallback;
    }

    let best = null;
    let bestScore = -9999;

    for (let i = 0; i < cands.length; i++) {
      const c = cands[i];
      let score = c.meritScore * 0.35 + c.intelligence * 0.2 + (c.reputation || 50) * 0.2 + c.stage * 6;
      if (posDef.track && c.track === posDef.track) score += 22;
      if (positionId === 'SUPREME_COMMANDER' || positionId === 'DEFENSE_MINISTER' || positionId === 'BASE_COMMANDER') {
        score += (c.knowledge.military || 50) * 0.3 + (c.experience.combatExp || 20) * 0.25 + (c.leadership || 50) * 0.2;
      } else if (positionId === 'LOGISTICS_CHIEF') {
        score += (c.knowledge.logistics || 50) * 0.45 + (c.planning || 50) * 0.25;
      } else if (positionId === 'FINANCE_MINISTER' || positionId === 'CEO_DIRECTOR') {
        score += (c.knowledge.economics || 50) * 0.4;
      } else {
        score += (c.knowledge.politics || 50) * 0.25 + (c.knowledge.administration || 50) * 0.25;
      }
      // Political alignment & personal relationship with Head of State (Section 17 & 97)
      if (head && head.id !== c.id) {
        if (c.faction === head.faction) score += 12;
        if (c.relationships) {
          const relToHead = c.relationships.find((r) => r.targetId === head.id);
          if (relToHead) {
            if (['ally', 'friend', 'political_partner', 'mentor', 'family'].includes(relToHead.type)) score += 16;
            if (['rival', 'enemy', 'military_rival'].includes(relToHead.type)) score -= 22;
          }
        }
      }
      if (c.age >= 35 && c.age <= 62) score += 8;
      if (score > bestScore) {
        bestScore = score;
        best = c;
      }
    }
    return best;
  }

  // Deep Bilateral Diplomatic Dimensions & International Blocs Initialization (Sections 22, 23, 24)
  function ensureDeepDiplomacyAndBlocsV170(world) {
    const stateIds = Object.keys(world.states);
    for (let i = 0; i < stateIds.length; i++) {
      const a = stateIds[i];
      const stA = world.states[a];
      if (!stA.relations) stA.relations = {};
      for (let j = 0; j < stateIds.length; j++) {
        const b = stateIds[j];
        if (a === b) continue;
        const stB = world.states[b];
        if (!stA.relations[b]) stA.relations[b] = { status: 'Peace', score: 60 };
        const rel = stA.relations[b];
        if (rel.tradeVolumeB === undefined) {
          const isPartner = (stA.tradePartners || []).includes(b) || (stB.tradePartners || []).includes(a);
          const isRival = (stA.rivalries || []).includes(b) || (stB.rivalries || []).includes(a);
          if (isRival && rel.status === 'Peace' && rel.score > 42) {
            rel.score = 36;
          } else if (isPartner && rel.status === 'Peace' && rel.score < 68) {
            rel.score = 74;
          }
          rel.tradeVolumeB = +((Math.min(stA.gdpB, stB.gdpB) * 0.018 * (isPartner ? 1.8 : 0.7) * (rel.score / 60))).toFixed(1);
          rel.militaryCoop = rel.status === 'Alliance' ? 85 : isPartner ? 58 : 25;
          rel.diplomaticTrust = rel.score;
          rel.economicDependency = clamp(Math.round((rel.tradeVolumeB / Math.max(100, stA.gdpB)) * 400), 5, 85);
          rel.intelSharing = rel.status === 'Alliance' ? 80 : 20;
          rel.rivalryScore = isRival ? 78 : clamp(100 - rel.score, 5, 95);
          const dist = (stA.mapCenter && stB.mapCenter) ? Math.hypot(stA.mapCenter.x - stB.mapCenter.x, stA.mapCenter.y - stB.mapCenter.y) : 300;
          rel.borderTension = dist < 95 ? (isRival ? 72 : 24) : 5;
          rel.historicalGrievance = isRival ? 65 : 10;
          rel.strategicPartnership = isPartner || rel.status === 'Alliance';
          rel.proxyLevel = 0;
          rel.armsDependency = ['US', 'CN', 'RU', 'FR', 'DE', 'KR', 'GB', 'IL'].includes(b) && isPartner ? 45 : 10;
        }
      }
    }

    // Ensure International Blocs (Section 24)
    const blocDefs = [
      { id: 'ALLIANCE_NATO', name: 'สนธิสัญญาแอตแลนติกเหนือ (NATO Collective Defense)', type: 'Mutual Defense Treaty', leaderId: 'US', members: ['US', 'GB', 'FR', 'DE', 'IT', 'PL', 'ES', 'CA', 'TR', 'EU'], sharedGoals: 'การป้องกันร่วมตามมาตรา 5 และความมั่นคงยูโร-แอตแลนติก', foundedYear: 1949, cohesion: 86, militaryContribution: 92, economicContribution: 78, internalDisagreements: 18, exitConditions: 'ความขัดแย้งทางยุทธศาสตร์รุนแรงหรือเปลี่ยนระบอบการปกครอง' },
      { id: 'ALLIANCE_ASEAN', name: 'ประชาคมเศรษฐกิจและความมั่นคงอาเซียน (ASEAN Community)', type: 'Economic Bloc', leaderId: 'TH', members: ['TH', 'VN', 'ID', 'PH', 'MY', 'SG', 'MM'], sharedGoals: 'ตลาดเดียวอาเซียน ความเป็นกลางทางยุทธศาสตร์ และความมั่นคงช่องแคบมะละกา-ลุ่มน้ำโขง', foundedYear: 1967, cohesion: 82, militaryContribution: 58, economicContribution: 88, internalDisagreements: 22, exitConditions: 'สงครามระหว่างรัฐสมาชิก' },
      { id: 'ALLIANCE_SCO_EURASIA', name: 'องค์การความร่วมมือเซี่ยงไฮ้และพันธมิตรยูเรเซีย (SCO Strategic Pact)', type: 'Strategic Partnership', leaderId: 'CN', members: ['CN', 'RU', 'PK', 'IR'], sharedGoals: 'ความมั่นคงภูมิภาคยูเรเซีย พลังงาน และการคานอำนาจขั้วเดียว', foundedYear: 2001, cohesion: 80, militaryContribution: 84, economicContribution: 82, internalDisagreements: 20, exitConditions: 'ความขัดแย้งพรมแดนหรือเปลี่ยนขั้วพันธมิตร' },
      { id: 'ALLIANCE_INDO_PACIFIC_QUAD', name: 'พันธมิตรเทคโนโลยีและความมั่นคงอินโด-แปซิฟิก (AUKUS & Indo-Pacific Partnership)', type: 'Technology Partnership', leaderId: 'US', members: ['US', 'JP', 'AU', 'GB', 'KR', 'IN'], sharedGoals: 'ความมั่นคงทางทะเลอินโด-แปซิฟิก เซมิคอนดักเตอร์ และเรือดำน้ำ/AI', foundedYear: 2021, cohesion: 84, militaryContribution: 86, economicContribution: 85, internalDisagreements: 15, exitConditions: 'ถอนตัวจากข้อตกลงความมั่นคงทางทะเล' },
      { id: 'ALLIANCE_EU_SINGLE_MARKET', name: 'สหภาพเศรษฐกิจและกลาโหมยุโรป (European Union & PESCO Bloc)', type: 'Economic Bloc', leaderId: 'DE', members: ['EU', 'DE', 'FR', 'IT', 'ES', 'PL'], sharedGoals: 'ตลาดร่วมยุโรป อุตสาหกรรมป้องกันประเทศร่วม และความมั่นคงพลังงาน', foundedYear: 1993, cohesion: 88, militaryContribution: 76, economicContribution: 95, internalDisagreements: 16, exitConditions: 'ประชามติแยกตัวหรือวิกฤตการคลัง' },
      { id: 'ALLIANCE_GCC_GULF', name: 'สภาความร่วมมืออ่าวอาหรับและโล่คาบสมุทร (GCC Peninsula Shield)', type: 'Defensive Alliance', leaderId: 'SA', members: ['SA', 'AE', 'ME', 'EG'], sharedGoals: 'ความมั่นคงพลังงานอ่าวเปอร์เซีย-ทะเลแดง และกองทุนความมั่งคั่งร่วม', foundedYear: 1981, cohesion: 83, militaryContribution: 78, economicContribution: 90, internalDisagreements: 14, exitConditions: 'ความขัดแย้งนโยบายพลังงานหรือภูมิภาค' },
      { id: 'ALLIANCE_BRICS_PLUS', name: 'กลุ่มความร่วมมือเศรษฐกิจโลกใต้ (BRICS+ Economic & Resource Bloc)', type: 'Trade Bloc', leaderId: 'CN', members: ['CN', 'RU', 'IN', 'BR', 'ZA', 'EG', 'AE', 'IR', 'ET'], sharedGoals: 'การค้าด้วยสกุลเงินท้องถิ่น ความมั่นคงอาหาร-พลังงาน และการเงินโลกหลายขั้ว', foundedYear: 2009, cohesion: 75, militaryContribution: 45, economicContribution: 89, internalDisagreements: 28, exitConditions: 'สงครามโดยตรงระหว่างสมาชิกหลัก' },
      { id: 'ALLIANCE_AFRICAN_UNION', name: 'สหภาพความมั่นคงและการค้าเสรีทวีปแอฟริกา (African Continental Pact)', type: 'Economic Bloc', leaderId: 'ZA', members: ['ZA', 'NG', 'ET', 'EG'], sharedGoals: 'เขตการค้าเสรีทวีปแอฟริกา (AfCFTA) และการพัฒนาโครงสร้างพื้นฐาน', foundedYear: 2002, cohesion: 76, militaryContribution: 54, economicContribution: 78, internalDisagreements: 24, exitConditions: 'สงครามแย่งชิงทรัพยากรน้ำหรือพรมแดน' },
      { id: 'ALLIANCE_AMERICAS_TRADE', name: 'พันธมิตรการค้าและอุตสาหกรรมทวีปอเมริกา (USMCA & Mercosur Bridge)', type: 'Trade Bloc', leaderId: 'US', members: ['US', 'CA', 'MX', 'BR', 'AR'], sharedGoals: 'ห่วงโซ่อุปทานอุตสาหกรรมแร่สำคัญ อาหาร และพลังงานแห่งทวีปอเมริกา', foundedYear: 2020, cohesion: 79, militaryContribution: 52, economicContribution: 91, internalDisagreements: 19, exitConditions: 'สงครามการค้าและกำแพงภาษีรุนแรง' }
    ];

    if (!world.alliances) world.alliances = [];
    blocDefs.forEach((b) => {
      const validMembers = b.members.filter((m) => world.states[m]);
      if (validMembers.length < 2) return;
      const existing = world.alliances.find((a) => a.id === b.id);
      if (!existing) {
        world.alliances.push({ ...b, members: validMembers });
      } else {
        Object.assign(existing, { ...b, members: validMembers });
      }
    });

    // Ensure all existing alliances have v1.7.0 fields
    world.alliances.forEach((al) => {
      if (!al.leaderId) al.leaderId = al.members[0] || 'US';
      if (!al.sharedGoals) al.sharedGoals = 'ความร่วมมือด้านความมั่นคงและเศรษฐกิจระหว่างประเทศสมาชิก';
      if (al.militaryContribution === undefined) al.militaryContribution = 75;
      if (al.economicContribution === undefined) al.economicContribution = 75;
      if (al.internalDisagreements === undefined) al.internalDisagreements = 15;
      if (!al.exitConditions) al.exitConditions = 'ความขัดแย้งทางผลประโยชน์แห่งชาติหรือสงคราม';
    });
  }

  // Research Institutions (Universities, Government Labs, Military Labs, Corporate R&D — Section 43)
  function ensureResearchInstitutionsV170(world) {
    if (world.researchInstitutes && Object.keys(world.researchInstitutes).length > 0) return;
    world.researchInstitutes = {};
    const instDefs = [
      { id: 'RINST_TH_NSTDA', name: 'สำนักงานพัฒนาวิทยาศาสตร์และเทคโนโลยีแห่งชาติ & สถาบันเทคโนโลยีป้องกันประเทศ (NSTDA / DTI Lab)', stateId: 'TH', cityId: 'CITY_TH_PTE', type: 'Government Lab', specialty: 'roboticsUav', outputRate: 86 },
      { id: 'RINST_TH_CHULA', name: 'ศูนย์วิจัยวิศวกรรมและ AI จุฬาลงกรณ์-ธรรมศาสตร์-ขอนแก่น', stateId: 'TH', cityId: 'CITY_TH_BKK', type: 'University', specialty: 'aiComputing', outputRate: 84 },
      { id: 'RINST_US_DARPA', name: 'DARPA & MIT Lincoln Defense Laboratory', stateId: 'US', cityId: 'CITY_US_BOS', type: 'Military Lab', specialty: 'aerospace', outputRate: 98 },
      { id: 'RINST_US_SILICON', name: 'Silicon Valley Frontier AI & Quantum Consortium', stateId: 'US', cityId: 'CITY_US_SFO', type: 'Corporate R&D', specialty: 'aiComputing', outputRate: 99 },
      { id: 'RINST_CN_CAS', name: 'Chinese Academy of Sciences (CAS) & Tsinghua National Lab', stateId: 'CN', cityId: 'CITY_CN_BJ', type: 'Government Lab', specialty: 'missiles', outputRate: 97 },
      { id: 'RINST_CN_SHENZHEN', name: 'Greater Bay Semiconductor & Autonomous Drone R&D Institute', stateId: 'CN', cityId: 'CITY_CN_SZ', type: 'Corporate R&D', specialty: 'electronics', outputRate: 96 },
      { id: 'RINST_JP_TODAI', name: 'University of Tokyo & ATLA Defense Tech Institute', stateId: 'JP', cityId: 'CITY_JP_TYO', type: 'Government Lab', specialty: 'radarSensors', outputRate: 95 },
      { id: 'RINST_KR_ADD', name: 'Agency for Defense Development (ADD Daejeon) & KAIST', stateId: 'KR', cityId: 'CITY_KR_DJN', type: 'Military Lab', specialty: 'landSystems', outputRate: 94 },
      { id: 'RINST_EU_FRAUNHOFER', name: 'ASML Veldhoven & Fraunhofer-Max Planck Research Network', stateId: 'DE', cityId: 'CITY_DE_MUC', type: 'Government Lab', specialty: 'manufacturing', outputRate: 95 },
      { id: 'RINST_FR_CEA', name: 'CEA Nuclear & ONERA Aerospace Research Lab', stateId: 'FR', cityId: 'CITY_FR_PAR', type: 'Military Lab', specialty: 'nuclearTech', outputRate: 94 },
      { id: 'RINST_GB_QINETIQ', name: 'Porton Down / QinetiQ & Oxbridge AI-Bio Lab', stateId: 'GB', cityId: 'CITY_GB_LON', type: 'Military Lab', specialty: 'cyberWarfare', outputRate: 93 },
      { id: 'RINST_RU_KURCHATOV', name: 'Kurchatov Nuclear Institute & TsAGI Aerohydrodynamic Center', stateId: 'RU', cityId: 'CITY_RU_MO', type: 'Military Lab', specialty: 'missiles', outputRate: 91 },
      { id: 'RINST_IN_DRDO', name: 'DRDO & ISRO Bengaluru Aerospace-Space Complex', stateId: 'IN', cityId: 'CITY_IN_BG', type: 'Government Lab', specialty: 'aerospace', outputRate: 90 },
      { id: 'RINST_IL_TECHNION', name: 'Technion & Weizmann Cyber-Missile Defense Institute', stateId: 'IL', cityId: 'CITY_IL_HFA', type: 'University', specialty: 'cyberWarfare', outputRate: 95 },
      { id: 'RINST_SG_ASTAR', name: 'A*STAR & DSO National Laboratories Singapore', stateId: 'SG', cityId: 'CITY_SG_SIN', type: 'Government Lab', specialty: 'electronics', outputRate: 94 }
    ];
    instDefs.forEach((d) => {
      if (!world.states[d.stateId]) return;
      const sci = Object.values(world.npcs).find((n) => n.alive && n.stateId === d.stateId && (n.positionId === 'CHIEF_SCIENTIST' || n.positionId === 'CTO_EXECUTIVE'));
      world.researchInstitutes[d.id] = {
        ...d,
        directorNpcId: sci ? sci.id : null,
        projectsCompleted: 1
      };
    });
  }

  // Master v1.7.0 World Initialization & Upgrade Function
  function ensureWorldSystemsV170(world) {
    if (!world) return world;
    const rng = new SeededRNG((world.seed || 202611717) + 170);

    // 1. Add the 18 New States (bringing total initial states from 18 to 36!)
    NEW_STATES_V170.forEach((cfg) => {
      if (!world.states[cfg.id]) {
        world.states[cfg.id] = {
          ...cfg,
          relations: {},
          budgetAllocation: { military: 0.28, infrastructure: 0.30, education: 0.22, logistics: 0.20 },
          logisticsDirty: true,
          frontlineDirty: false,
          vacancyDirty: true,
          warPlan: null,
          positions: {
            HEAD_OF_STATE: null,
            DEFENSE_MINISTER: null,
            SUPREME_COMMANDER: null,
            LOGISTICS_CHIEF: null,
            FINANCE_MINISTER: null
          }
        };
      }
    });

    // 2. Apply City Reassignments (splitting EU -> FR/DE/IT/PL/ES, ME -> SA/AE/ME, SG -> MY/SG, and Songkhla/Hat Yai)
    Object.entries(CITY_REASSIGNMENTS_V170).forEach(([cid, rinfo]) => {
      const c = world.cities[cid];
      if (c && world.states[rinfo.stateId]) {
        c.stateId = rinfo.stateId;
        c.originalOwnerId = rinfo.stateId;
        c.currentOwnerId = rinfo.stateId;
        c.name = rinfo.name;
        c.isCapital = rinfo.isCapital;
        c.lon = rinfo.lon;
        c.lat = rinfo.lat;
        c.geo = rinfo.geo;
        c.x = rinfo.x;
        c.y = rinfo.y;
      }
    });

    // 3. Add the 227 New Cities (bringing total initial cities to 335!)
    NEW_CITIES_V170.forEach((c) => {
      if (!world.cities[c.id] && world.states[c.stateId]) {
        const eq = createEmptyEquipmentBag();
        eq.logistics.HEMTT_Truck = c.urbanLevel >= 4 ? 32 : 20;
        eq.logistics.C17_Globemaster = c.isCapital ? 3 : c.urbanLevel >= 4 ? 1 : 0;
        world.cities[c.id] = {
          ...c,
          originalOwnerId: c.stateId,
          currentOwnerId: c.stateId,
          isOccupied: false,
          assimilation: 100,
          unrest: 5,
          resentment: 0,
          occupationPolicy: 'BALANCED',
          garrisonStrength: c.urbanLevel >= 4 ? 4200 : 2600,
          insurgentCells: 0,
          governorId: null,
          isFrontline: false,
          threatLevel: 0,
          activeProject: `พัฒนาโครงข่าย ${c.archetype} และโลจิสติกส์ภูมิภาค`,
          projectProgress: rng.int(25, 78),
          supplies: {
            fuel: c.urbanLevel >= 4 ? 1400 : 950,
            ammo: c.urbanLevel >= 4 ? 950 : 650,
            rations: c.urbanLevel >= 4 ? 1650 : 1150,
            spareParts: c.urbanLevel >= 4 ? 600 : 400
          },
          troops: c.urbanLevel >= 4 ? 4200 : 2600,
          equipment: eq
        };
      }
    });

    // 4. Add the 70 New Military Bases (bringing total military bases to 96 across 8 specialized types!)
    NEW_CAMPS_V170.forEach((cp) => {
      if (!world.camps[cp.id] && world.states[cp.stateId]) {
        const st = world.states[cp.stateId];
        const eq = createEmptyEquipmentBag();
        if (cp.type === 'airbase') {
          eq.aircraft[st.primaryFighter || 'F35A'] = 36;
          eq.aircraft[st.primaryCarrierFighter || 'F35C'] = 14;
          eq.airDefense[st.primarySAM || 'Patriot_PAC3'] = 24;
          eq.logistics.HEMTT_Truck = 35;
          eq.logistics.C17_Globemaster = 4;
        } else if (cp.type === 'naval_base') {
          eq.ships.FFG_Constellation = 3;
          eq.ships.DDG_ArleighBurke = 2;
          eq.ships.SSK_Soryu = 2;
          eq.airDefense[st.primarySAM || 'Patriot_PAC3'] = 22;
          eq.aircraft.MH60R_Seahawk = 10;
          eq.logistics.HEMTT_Truck = 30;
        } else if (cp.type === 'missile_base') {
          eq.artillery[st.primaryArtillery || 'M142_HIMARS'] = 64;
          eq.artillery.PHL191_MLRS = 24;
          eq.airDefense[st.primarySAM || 'Patriot_PAC3'] = 36;
          eq.logistics.HEMTT_Truck = 45;
        } else if (cp.type === 'logistics_base') {
          eq.logistics.HEMTT_Truck = 140;
          eq.logistics.C17_Globemaster = 8;
          eq.airDefense[st.primarySAM || 'Patriot_PAC3'] = 18;
        } else {
          eq.tanks[st.primaryTank || 'M1A2_SEPv3'] = 95;
          eq.apcs[st.primaryAPC || 'M2A4_Bradley'] = 135;
          eq.artillery[st.primaryArtillery || 'CAESAR_155'] = 58;
          eq.airDefense[st.primarySAM || 'IRIS_T_SLM'] = 24;
          eq.logistics.HEMTT_Truck = 55;
        }
        world.camps[cp.id] = {
          ...cp,
          commanderId: null,
          readiness: 91,
          fortification: cp.type === 'missile_base' || cp.type === 'permanent_camp' ? 86 : 78,
          supplies: {
            fuel: cp.type === 'logistics_base' ? 5200 : 2400,
            ammo: cp.type === 'logistics_base' || cp.type === 'missile_base' ? 4800 : 2200,
            rations: 2600,
            spareParts: 1050
          },
          daysOfSupply: 28,
          equipment: eq
        };
      }
    });

    // 5. Add the 42 New Companies (bringing total global corporations to 50!)
    NEW_COMPANIES_V170.forEach((co) => {
      if (!world.companies.some((x) => x.id === co.id) && world.states[co.stateId]) {
        world.companies.push({
          ...co,
          ceoId: null,
          cfoId: null,
          ctoId: null,
          lastOutputTick: 0,
          contractsCount: 2,
          exportRevenueB: +(co.capitalB * 0.12).toFixed(1),
          marketShare: rng.int(12, 38),
          solvency: 92
        });
      }
    });
    world.companies.forEach((co) => {
      if (co.rndLevel === undefined) co.rndLevel = 85;
      if (co.exportCap === undefined) co.exportCap = 82;
      if (co.contractsCount === undefined) co.contractsCount = 2;
      if (co.exportRevenueB === undefined) co.exportRevenueB = +(co.capitalB * 0.12).toFixed(1);
      if (co.solvency === undefined) co.solvency = 92;
    });

    // 6. Enrich all States, Cities & Bases with Deep v1.7.0 Profiles
    Object.values(world.states).forEach((st) => {
      ensureStateWorldSystems(world, st);
      ensureStateParliamentAndStrategicStatus(world, st);
      ensureStateDeepProfileV170(world, st);
    });
    Object.values(world.cities).forEach((c) => ensureCityDeepProfileV170(world, c));
    Object.values(world.camps).forEach((cp) => ensureCampDeepProfileV170(world, cp));
    buildCityRouteNetworkV170(world);
    syncCityIndex(world);

    // 7. Populate Expanded NPCs (~1,900+ meaningful NPCs across all 36 states) if not already populated
    if (Object.keys(world.npcs).length < 1500) {
      populateInitialNPCsV170(world, rng);
    } else {
      Object.values(world.npcs).forEach((n) => ensureNPCDeepProfileV170(world, n, rng));
    }

    // 8. Ensure Deep Diplomacy, International Blocs & Research Institutions
    ensureDeepDiplomacyAndBlocsV170(world);
    ensureResearchInstitutionsV170(world);
    if (!world.chronicleArchives) world.chronicleArchives = [];
    if (!world.globalMarket) {
      world.globalMarket = {
        oilPriceIndex: 100,
        chipSupplyIndex: 100,
        foodPriceIndex: 100,
        rareEarthIndex: 100,
        globalTradeVolumeB: 28500,
        activeGlobalCrisis: null
      };
    }

    // Force entity & military graph sync once after adding new states/camps
    world._forceGraphSync = true;
    ensureDeepMilitaryGraphV150(world);
    world._v170 = true;
    if (!world.version) world.version = VERSION;
    return world;
  }

  // =========================================================================
  // DEEP SIMULATION CYCLES (POLITICS, ECONOMY, MILITARY, DIPLOMACY, TECH, EVENTS)
  // =========================================================================

  // 1. Internal Politics, Factions, Dictatorship Underground & Democracy Dynamics (Sections 18-21, 61)
  function runInternalPoliticsAndFactionsCycle(world, rng) {
    Object.values(world.states).forEach((st) => {
      if (st.isExiled) return;
      ensureStateDeepProfileV170(world, st);
      const pp = st.politicalPressures;
      const wars = getWarsOf(world, st.id);
      const isAtWar = wars.length > 0;
      const isAuth = ['Authoritarian', 'One_Party', 'Military_Junta'].includes(st.regimeCategory);

      // Update political pressures from real economic, military & fiscal conditions
      const taxPressure = Math.max(0, (st.taxRate - 0.22) * 180);
      const foodShortage = Math.max(0, 55 - (st.resources12?.foodGrain || 75)) * 0.6;
      const warStress = (st.warExhaustion || 0) * 0.55;
      pp.economicPressure = rnd1(clamp(taxPressure + foodShortage + (st.treasuryB < 30 ? 25 : 8), 5, 98));
      pp.publicUnrest = rnd1(clamp((100 - st.stability) * 0.65 + pp.economicPressure * 0.25 + warStress * 0.2, 4, 98));
      pp.governmentPopularity = rnd1(clamp(st.approval * 0.8 + (100 - pp.economicPressure) * 0.2, 5, 98));
      pp.oppositionStrength = rnd1(clamp(100 - pp.governmentPopularity + (isAuth ? -10 : 8), 10, 95));
      pp.militaryInfluence = rnd1(clamp(pp.militaryInfluence + (isAtWar ? 1.2 : -0.3) + ((st.budgetAllocation?.military || 0.28) > 0.35 ? 0.6 : -0.2), 18, 96));
      pp.eliteSupport = rnd1(clamp((st.stability * 0.5) + (st.treasuryB > 80 ? 38 : 22) - warStress * 0.3, 15, 98));

      // Update Faction satisfaction & influence
      if (st.factions) {
        st.factions.forEach((f) => {
          if (f.type === 'Government') f.satisfaction = clamp(Math.round(pp.governmentPopularity), 15, 98);
          else if (f.type === 'Opposition') f.satisfaction = clamp(Math.round(100 - pp.publicUnrest * 0.7), 10, 95);
          else if (f.type === 'Military') f.satisfaction = clamp(Math.round(50 + (st.budgetAllocation?.military || 0.28) * 120 - (st.warExhaustion || 0) * 0.4), 15, 98);
          else if (f.type === 'Business' || f.type === 'Industrial') f.satisfaction = clamp(Math.round(85 - pp.economicPressure * 0.6), 15, 98);
        });
      }

      // A. Dictatorship / Authoritarian Underground Dynamics (Section 20 & Section 61 Multi-Factor Coup Score)
      if (isAuth && st.underground) {
        const ug = st.underground;
        ug.active = true;
        const pressureGain = (pp.publicUnrest > 45 ? 1.8 : -0.6) + (pp.economicPressure > 50 ? 1.4 : -0.4) + (warStress > 25 ? 1.5 : 0);
        ug.dissidentNetwork = rnd1(clamp(ug.dissidentNetwork + pressureGain, 5, 98));
        ug.militaryPlotLevel = rnd1(clamp(ug.militaryPlotLevel + (pp.militaryInfluence > 65 && st.stability < 55 ? 2.2 : -0.5), 4, 98));

        // Multi-factor Coup / Underground Uprising evaluation (Section 61: NO pure random!)
        const leader = st.positions.HEAD_OF_STATE ? world.npcs[st.positions.HEAD_OF_STATE] : null;
        const leaderStrength = leader ? (leader.authority * 0.4 + leader.intelligence * 0.3 + (leader.loyalty || 70) * 0.3) : 65;
        const coupScore =
          pp.militaryInfluence * 0.28 +
          (100 - st.stability) * 0.32 +
          pp.economicPressure * 0.20 +
          (100 - pp.eliteSupport) * 0.25 +
          ug.militaryPlotLevel * 0.30 -
          leaderStrength * 0.45 -
          (pp.governmentPopularity * 0.25);

        if (coupScore >= 42 && world.tick >= GRACE_TICKS_REBELLION && rng.chance(clamp((coupScore - 38) * 0.015, 0.02, 0.25))) {
          const plotter = [st.positions.SUPREME_COMMANDER, st.positions.ARMY_CHIEF, st.positions.DEFENSE_MINISTER]
            .map((id) => (id ? world.npcs[id] : null))
            .find((n) => n && n.alive && !n.retired);
          if (plotter) {
            ug.militaryPlotLevel = 15;
            triggerMilitaryCoup(world, plotter);
          }
        }
      }

      // B. Democracy Elections, Coalition Crises, Scandals & Strikes (Section 21)
      if (!isAuth && st.democracyState) {
        const ds = st.democracyState;
        ds.coalitionStability = rnd1(clamp((st.stability * 0.55) + (st.approval * 0.45) - pp.ideologicalPolarization * 0.15, 15, 98));
        if (world.year >= ds.nextElectionYear && world.dayOfYear <= 35) {
          ds.nextElectionYear = world.year + 4;
          holdParliamentSession(world, st.id, 'election');
          st.history.unshift({ year: world.year, date: world.dateString, type: 'ELECTION', text: `จัดการเลือกตั้งทั่วไปตามวาระใน ${st.name} (เสถียรภาพรัฐบาลผสม ${ds.coalitionStability}%)` });
          if (st.history.length > 25) st.history.length = 25;
        } else if (ds.coalitionStability < 36 && rng.chance(0.18)) {
          // Early election or cabinet reshuffle
          ds.nextElectionYear = world.year + 4;
          holdParliamentSession(world, st.id, 'no_confidence');
        }
      }
    });
  }

  // 2. Economic Network, City Supply Chains, Anti-Snowball Burden & Company AI (Sections 25-28, 71, 87)
  function runEconomicSupplyNetworkCycle(world, rng) {
    const campsBySt = {};
    Object.values(world.camps).forEach((cp) => { if (cp && cp.stateId) (campsBySt[cp.stateId] = campsBySt[cp.stateId] || []).push(cp); });
    // Recompute Anti-Snowball Burden & City->State Resource/Industrial Chain
    Object.values(world.states).forEach((st) => {
      if (st.isExiled) return;
      if (!st.resources) ensureStateDeepProfileV170(world, st);
      const myCities = stateCities(world, st.id);
      const occCities = myCities.filter((c) => c.isOccupied);

      // Anti-Snowball (Section 87): Admin burden, Logistics burden, Occupation cost
      const excessCities = Math.max(0, myCities.length - 12);
      st.adminBurden = rnd1(clamp(6 + excessCities * 1.35 + occCities.length * 4.5, 4, 75));
      st.logisticsBurden = rnd1(clamp(8 + excessCities * 1.1 + getWarsOf(world, st.id).length * 12, 5, 80));
      st.occupationCostB = rnd1(occCities.reduce((acc, c) => acc + ((100 - (c.assimilation || 50)) * 0.035), 0));

      if (st.occupationCostB > 0) {
        st.treasuryB = rnd1(Math.max(2, st.treasuryB - st.occupationCostB * 0.25));
      }

      // Aggregate City Resource Production & Industrial Facilities (Section 25)
      let portCount = 0;
      let tankFacCount = 0;
      let aeroFacCount = 0;
      let shipFacCount = 0;
      let chipFacCount = 0;
      let ironSupply = 0;
      let oilSupply = 0;

      for (let i = 0; i < myCities.length; i++) {
        const c = myCities[i];
        if (!c.facilities) ensureCityDeepProfileV170(world, c);
        const dmgFactor = c.isOccupied ? 0.55 : c.isFrontline ? 0.65 : 1.0;
        if (c.port >= 3) portCount++;
        if (c.facilities) {
          if (c.facilities.tankFactory) tankFacCount += dmgFactor;
          if (c.facilities.aircraftFactory) aeroFacCount += dmgFactor;
          if (c.facilities.shipyard) shipFacCount += dmgFactor;
          if (c.facilities.semiconductorPlant) chipFacCount += dmgFactor;
        }
        if (c.resourceProduction) {
          ironSupply += (c.resourceProduction.iron || 0) * dmgFactor;
          oilSupply += (c.resourceProduction.oil || 0) * dmgFactor;
        }
      }

      // If resource/industrial cities are captured or blockaded, industrial output drops and state must import
      const blockaded = st.strategicResources && st.strategicResources.blockadedBy;
      const supplyChainHealth = clamp(
        (ironSupply > 15 ? 1.0 : 0.78) *
        (oilSupply > 15 || !blockaded ? 1.0 : 0.72) *
        (1 - st.adminBurden * 0.003),
        0.45,
        1.15
      );
      st.supplyChainHealthPct = Math.round(supplyChainHealth * 100);

      // Small-state high-efficiency bonus (Section 88)
      if (myCities.length > 0 && myCities.length <= 5 && st.educationIndex >= 85) {
        st.treasuryB = rnd1(st.treasuryB + st.gdpB * 0.0025);
      }
    });

    // Company AI: R&D, Defense Contracts, Exports, Expansion & M&A (Sections 28 & 71)
    (world.companies || []).forEach((co) => {
      const st = world.states[co.stateId];
      if (!st || st.isExiled) return;
      const homeCity = co.cityId ? world.cities[co.cityId] : null;
      const cityIntact = !homeCity || (homeCity.stateId === st.id && !homeCity.isFrontline);

      if (!cityIntact) {
        co.productivity = Math.max(45, (co.productivity || 80) - 2);
        co.solvency = Math.max(20, (co.solvency || 85) - 3);
        return;
      }

      // Company fulfills state defense/industrial production contract
      const stateCamps = campsBySt[st.id] || [];
      const targetNode = stateCamps[0] || homeCity;
      if (targetNode && targetNode.equipment) {
        const spec = findEquipmentSpec(co.specialty);
        if (spec) {
          const cat = spec.categoryKey;
          const batch = cat === 'ships' ? (rng.chance(0.25) ? 1 : 0) : cat === 'aircraft' ? 2 : 5;
          if (batch > 0 && targetNode.equipment[cat]) {
            targetNode.equipment[cat][co.specialty] = (targetNode.equipment[cat][co.specialty] || 0) + batch;
          }
        }
        targetNode.supplies.spareParts = (targetNode.supplies.spareParts || 500) + 120;
      }

      // Corporate R&D & Capital Growth
      const growth = (co.productivity / 100) * (st.supplyChainHealthPct || 95) / 100 * 0.6;
      co.capitalB = rnd1(Math.max(5, co.capitalB + growth));
      co.exportRevenueB = rnd1(co.capitalB * 0.14);
      st.treasuryB = rnd1(st.treasuryB + co.exportRevenueB * 0.04);
      if (rng.chance(0.18)) {
        co.rndLevel = clamp((co.rndLevel || 80) + 1, 50, 99);
        st.researchPoints = (st.researchPoints || 0) + 2;
      }
    });
  }

  // 3. City AI Governance Cycle (Section 69: Major cities make decisions; secondary cities use abstraction)
  function runCityGovernanceCycle(world, rng) {
    const cities = Object.values(world.cities);
    for (let i = 0; i < cities.length; i++) {
      const c = cities[i];
      const st = world.states[c.stateId];
      if (!st || st.isExiled) continue;
      if (c.tier <= 2) {
        // Tier 1 & Tier 2 City AI
        const gov = c.governorId ? world.npcs[c.governorId] : null;
        const govSkill = gov ? ((gov.knowledge.administration + gov.knowledge.economics) / 200) : 0.7;
        c.projectProgress = (c.projectProgress || 40) + Math.round(6 * govSkill);
        if (c.projectProgress >= 100) {
          c.projectProgress = 15;
          if (c.infrastructure < c.economy) {
            c.infrastructure = clamp(rnd1(c.infrastructure + 1.2), 30, 99);
            c.activeProject = `ยกระดับโครงข่ายคมนาคมและโลจิสติกส์ (${c.archetype})`;
          } else {
            c.economy = clamp(rnd1(c.economy + 1.1), 30, 99);
            c.activeProject = `ขยายเขตอุตสาหกรรมและนวัตกรรม (${c.archetype})`;
          }
          c.economicOutput = +(Math.max(8, (c.popM || 1.5) * c.economy * 0.22)).toFixed(1);
        }
      } else {
        // Tier 3 & Tier 4 Regional Abstraction
        if (st.stability >= 75 && !c.isOccupied) {
          c.infrastructure = clamp(rnd1(c.infrastructure + 0.2), 30, 96);
          c.economy = clamp(rnd1(c.economy + 0.2), 30, 96);
        }
      }
    }
  }

  // 4. Military Readiness, Base Network Capacities & Logistics Interdiction (Sections 31-41)
  function runMilitaryReadinessAndBaseLogisticsCycle(world, rng) {
    const campsBySt = {};
    Object.values(world.camps).forEach((cp) => { if (cp && cp.stateId) (campsBySt[cp.stateId] = campsBySt[cp.stateId] || []).push(cp); });
    Object.values(world.states).forEach((st) => {
      if (st.isExiled) return;
      if (!st.militaryReadiness) ensureStateDeepProfileV170(world, st);
      const camps = campsBySt[st.id] || [];
      if (camps.length === 0) return;

      let totFuel = 0, totAmmo = 0, totParts = 0, totTroops = 0;
      camps.forEach((cp) => {
        if (!cp.baseCategory) ensureCampDeepProfileV170(world, cp);
        totFuel += cp.supplies?.fuel || 0;
        totAmmo += cp.supplies?.ammo || 0;
        totParts += cp.supplies?.spareParts || 0;
        totTroops += cp.troops || 0;

        // Enforce Airbase aircraft capacity limit (Section 39)
        if (cp.type === 'airbase' && cp.equipment && cp.equipment.aircraft) {
          const curAc = sumCategory(cp.equipment, 'aircraft');
          if (curAc > cp.aircraftCapacity) {
            // Overflow aircraft transferred to secondary airbase or reserve
            const otherAb = camps.find((o) => o.id !== cp.id && o.type === 'airbase' && sumCategory(o.equipment, 'aircraft') < o.aircraftCapacity);
            if (otherAb) {
              const mKey = Object.keys(cp.equipment.aircraft).find((k) => cp.equipment.aircraft[k] > 4);
              if (mKey) {
                const moveN = Math.min(cp.equipment.aircraft[mKey] - 2, curAc - cp.aircraftCapacity);
                if (moveN > 0) {
                  cp.equipment.aircraft[mKey] -= moveN;
                  otherAb.equipment.aircraft[mKey] = (otherAb.equipment.aircraft[mKey] || 0) + moveN;
                }
              }
            }
          }
        }

        // City <-> Base Factory/Port Supply Chain replenishment (Section 36 & 41)
        const linkedCity = cp.linkedCityId ? world.cities[cp.linkedCityId] : null;
        if (linkedCity && linkedCity.stateId === st.id && !linkedCity.isOccupied) {
          const routeEff = ((linkedCity.rail || 3) * 0.1 + (linkedCity.roadConnectivity || 80) * 0.008) * (1 - (st.logisticsInterdictionPct || 0) / 100);
          const addFuel = Math.round(45 * routeEff);
          const addAmmo = Math.round(40 * routeEff);
          cp.supplies.fuel = Math.min(cp.fuelStorage || 5000, (cp.supplies.fuel || 0) + addFuel);
          cp.supplies.ammo = Math.min(cp.weaponsStorage || 4500, (cp.supplies.ammo || 0) + addAmmo);
        }
      });

      const avgFuel = totFuel / camps.length;
      const avgAmmo = totAmmo / camps.length;
      const avgParts = totParts / camps.length;
      const mr = st.militaryReadiness;
      const supCmd = st.positions.SUPREME_COMMANDER ? world.npcs[st.positions.SUPREME_COMMANDER] : null;

      mr.fuel = clamp(Math.round((avgFuel / 2200) * 100), 15, 100);
      mr.ammunition = clamp(Math.round((avgAmmo / 2000) * 100), 15, 100);
      mr.spareParts = clamp(Math.round((avgParts / 900) * 100), 20, 100);
      mr.maintenance = clamp(Math.round(mr.spareParts * 0.6 + (st.industrialSectors?.militaryIndustry || 75) * 0.4), 25, 100);
      mr.equipmentReadiness = clamp(Math.round((mr.maintenance * 0.55) + (mr.fuel * 0.25) + (mr.ammunition * 0.20)), 20, 100);
      mr.personnelReadiness = clamp(Math.round(85 - (st.warExhaustion || 0) * 0.25), 35, 100);
      mr.training = clamp(Math.round((st.educationIndex || 80) * 0.5 + (st.budgetAllocation?.military || 0.28) * 140), 40, 99);
      mr.morale = clamp(Math.round((st.stability * 0.45) + (st.informationOps?.warSupport || 55) * 0.35 + 20 - (st.warExhaustion || 0) * 0.3), 25, 100);
      mr.commandQuality = supCmd ? clamp(Math.round((supCmd.knowledge.military * 0.5) + (supCmd.leadership || 75) * 0.3 + (supCmd.planning || 75) * 0.2), 40, 99) : 75;
      mr.intelligence = clamp(Math.round(72 + (st.spaceProgram?.intelBonusPct || 8) + (st.nuclear?.cyberPower || 70) * 0.15), 35, 99);
      mr.communications = clamp(Math.round(78 + ((st.spaceProgram?.commsSatellites || 2) * 1.1) - (st.logisticsInterdictionPct || 0) * 0.4), 25, 99);
      mr.logisticsCapacity = clamp(Math.round(92 - (st.logisticsBurden || 10) * 0.45 - (st.logisticsInterdictionPct || 0) * 0.5), 25, 99);
      mr.overallScore = Math.round(
        (mr.personnelReadiness + mr.equipmentReadiness + mr.training + mr.morale + mr.ammunition + mr.fuel + mr.maintenance + mr.commandQuality + mr.logisticsCapacity) / 9
      );

      // Slowly heal temporary interdiction damage
      if (st.logisticsInterdictionPct > 0) {
        st.logisticsInterdictionPct = Math.max(0, st.logisticsInterdictionPct - 4);
      }
    });
  }

  // Logistics Interdiction Operation (Section 37: Air attack, Naval blockade, Port/Rail/Bridge destruction, Cyber disruption, Sabotage)
  function executeLogisticsInterdiction(world, attackerStateId, targetStateId, method = 'air_interdiction') {
    const atk = world.states[attackerStateId];
    const def = world.states[targetStateId];
    if (!atk || !def) return { ok: false, reason: 'ไม่พบรัฐผู้โจมตีหรือเป้าหมาย' };
    ensureStateDeepProfileV170(world, def);

    const methodLabels = {
      air_interdiction: 'การโจมตีทางอากาศตัดเส้นทางรถไฟและสะพานส่งกำลังบำรุง',
      naval_blockade: 'การปิดล้อมท่าเรือและเส้นทางลำเลียงทางทะเล',
      cyber_disruption: 'การโจมตีไซเบอร์ป่วนระบบควบคุมคลังยุทธปัจจัย',
      sabotage: 'หน่วยรบพิเศษวินาศกรรมคลังเชื้อเพลิงและชุมทางขนส่ง'
    };
    const label = methodLabels[method] || methodLabels.air_interdiction;
    const hitPct = method === 'air_interdiction' ? 18 : method === 'naval_blockade' ? 16 : 14;
    def.logisticsInterdictionPct = clamp((def.logisticsInterdictionPct || 0) + hitPct, 0, 65);

    const defCamps = Object.values(world.camps).filter((c) => c.stateId === def.id);
    defCamps.forEach((cp) => {
      cp.supplies.fuel = Math.max(150, Math.round(cp.supplies.fuel * 0.88));
      cp.supplies.ammo = Math.max(150, Math.round(cp.supplies.ammo * 0.90));
      cp.daysOfSupply = Math.max(3, (cp.daysOfSupply || 20) - 4);
    });

    const narrative = `💥🚂 [ปฏิบัติการตัดสายส่งกำลังบำรุง — Logistics Interdiction] ${atk.name} เปิดปฏิบัติการ${label}ต่อ ${def.name} ส่งผลให้ประสิทธิภาพสายส่งกำลังบำรุงของ ${def.shortName} ลดลง -${hitPct}% และคลังเชื้อเพลิง/กระสุนแนวหน้าลดฮวบ!`;
    addChronicle(world, 'MILITARY', narrative, atk.id);
    return { ok: true, interdictionPct: def.logisticsInterdictionPct, narrative };
  }

  // 5. War Objectives & War Escalation Ladder (Sections 33, 34, 35)
  const WAR_ESCALATION_LEVELS = [
    'Border Incident (ปะทะชายแดน)',
    'Limited Conflict (ความขัดแย้งจำกัดขอบเขต)',
    'Regional War (สงครามระดับภูมิภาค)',
    'Major War (สงครามเต็มรูปแบบ)',
    'Total War (มหาสงครามเบ็ดเสร็จ)'
  ];
  const WAR_OBJECTIVE_TYPES = [
    'Capture Strategic City (ยึดเมืองยุทธศาสตร์)',
    'Capture Port & Sea Lane (ยึดเมืองท่าและทางออกทะเล)',
    'Capture Resource Region (ยึดแหล่งทรัพยากรและพลังงาน)',
    'Destroy Military Capability (ทำลายศักยภาพทางทหาร)',
    'Capture Capital (ยึดครองเมืองหลวง)',
    'Force Peace & Reparations (บีบให้ลงนามสงบศึก)',
    'Regime Change (เปลี่ยนขั้วรัฐบาล)',
    'Defensive War (สงครามป้องกันอธิปไตย)'
  ];

  function ensureWarEscalationAndObjectives(world, war) {
    if (!war) return;
    const stA = world.states[war.attackerId];
    const stB = world.states[war.defenderId];
    if (war.escalationLevel === undefined) war.escalationLevel = 2; // Starts at Limited Conflict or Regional War
    war.escalationLabel = WAR_ESCALATION_LEVELS[clamp(war.escalationLevel - 1, 0, 4)];
    if (!war.strategicObjective) {
      if (stA && stA.policy === 'Naval Expansion') war.strategicObjective = WAR_OBJECTIVE_TYPES[1];
      else if (stA && stA.policy === 'Expansionist') war.strategicObjective = WAR_OBJECTIVE_TYPES[0];
      else war.strategicObjective = WAR_OBJECTIVE_TYPES[3];
    }
    const age = world.tick - (war.startTick || 0);
    const totalKia = ((war.casualtiesTotal?.[war.attackerId]?.kia || 0) + (war.casualtiesTotal?.[war.defenderId]?.kia || 0));
    const citiesCap = Object.values(war.citiesCaptured || {}).reduce((a, b) => a + b, 0);

    // Escalate or de-escalate based on war intensity & exhaustion
    let newLvl = war.escalationLevel;
    if (citiesCap >= 3 || totalKia > 25000) newLvl = Math.max(newLvl, 4);
    else if (citiesCap >= 1 || totalKia > 8000 || age > 90) newLvl = Math.max(newLvl, 3);
    if (stA && stB && stA.warExhaustion > 70 && stB.warExhaustion > 70 && newLvl > 2) {
      newLvl -= 1; // De-escalation as both sides exhaust reserves
    }
    if (newLvl !== war.escalationLevel) {
      war.escalationLevel = clamp(newLvl, 1, 5);
      war.escalationLabel = WAR_ESCALATION_LEVELS[war.escalationLevel - 1];
      war.intensity = war.escalationLevel >= 4 ? 'Total / High' : war.escalationLevel === 3 ? 'Regional Medium' : 'Limited';
    }
  }

  // 6. Space Satellite Launch & Information/Media Campaign Functions (Sections 44, 46)
  function launchSatelliteMission(world, stateId, satType = 'reconSatellites') {
    const st = world.states[stateId];
    if (!st || st.isExiled) return { ok: false, reason: 'ไม่พบรัฐ' };
    ensureStateDeepProfileV170(world, st);
    const costB = 12;
    if (st.treasuryB < costB) return { ok: false, reason: 'งบคงคลังไม่พอ ($12B)' };
    st.treasuryB = rnd1(st.treasuryB - costB);
    const sp = st.spaceProgram;
    sp[satType] = (sp[satType] || 0) + 2;
    sp.intelBonusPct = clamp((sp.intelBonusPct || 8) + 2, 4, 35);
    sp.missileAccuracyBonusPct = clamp((sp.missileAccuracyBonusPct || 6) + 2, 2, 30);
    const narrative = `🛰️🚀 [ส่งดาวเทียมยุทธศาสตร์ขึ้นสู่วงโคจร] ${st.name} ส่งดาวเทียม (${satType}) เพิ่ม 2 ดวงเข้าสู่วงโคจรสำเร็จ ยกระดับข่าวกรองดาวเทียมเป็น +${sp.intelBonusPct}% และความแม่นยำขีปนาวุธเป็น +${sp.missileAccuracyBonusPct}%!`;
    addChronicle(world, 'MILITARY', narrative, st.id);
    return { ok: true, spaceProgram: sp, narrative };
  }

  function executeInformationCampaign(world, stateId, campaignType = 'propaganda') {
    const st = world.states[stateId];
    if (!st || st.isExiled) return { ok: false, reason: 'ไม่พบรัฐ' };
    ensureStateDeepProfileV170(world, st);
    const costB = 6;
    if (st.treasuryB < costB) return { ok: false, reason: 'งบคงคลังไม่พอ ($6B)' };
    st.treasuryB = rnd1(st.treasuryB - costB);
    const info = st.informationOps;
    info.lastCampaignTick = world.tick;
    if (campaignType === 'propaganda') {
      info.warSupport = clamp((info.warSupport || 55) + 8, 10, 98);
      st.approval = rnd1(clamp(st.approval + 3, 10, 98));
      info.lastCampaignType = 'แคมเปญปลุกใจรักชาติและสนับสนุนกองทัพ (National Propaganda)';
    } else if (campaignType === 'diplomatic_pr') {
      info.diplomaticReputation = clamp((info.diplomaticReputation || 70) + 6, 15, 99);
      info.lastCampaignType = 'การทูตสาธารณะและยกระดับภาพลักษณ์ระหว่างประเทศ (Reputation Management)';
    } else {
      st.stability = rnd1(clamp(st.stability + 3.5, 10, 98));
      info.lastCampaignType = 'แถลงการณ์รัฐบาลสร้างความเชื่อมั่นประชาชน (Press Conference)';
    }
    const narrative = `📺📢 [ปฏิบัติการข่าวสารและสื่อมวลชน] รัฐบาล ${st.name} ดำเนิน "${info.lastCampaignType}" ส่งผลให้ความนิยมเป็น ${st.approval}% เสถียรภาพ ${st.stability}% และแรงสนับสนุนยามสงคราม ${info.warSupport}%`;
    addChronicle(world, 'POLITICAL', narrative, st.id);
    return { ok: true, info, narrative };
  }

  // 7. Conditional Dynamic Events & Global Crises (Sections 47 & 73)
  function runDynamicEventsCycleV170(world, rng) {
    // Only trigger when prerequisites & probabilities align
    const liveStates = Object.values(world.states).filter((s) => !s.isExiled);
    if (liveStates.length === 0) return;

    // A. Global Crisis Check (every 180 ticks, low probability, condition-driven)
    if (world.tick % 180 === 0 && rng.chance(0.18)) {
      const activeWarsCount = (world.wars || []).filter((w) => w.status === 'War').length;
      const gm = world.globalMarket || (world.globalMarket = { oilPriceIndex: 100, chipSupplyIndex: 100, foodPriceIndex: 100 });
      if (activeWarsCount >= 2) {
        gm.oilPriceIndex = clamp(gm.oilPriceIndex + 18, 70, 180);
        gm.activeGlobalCrisis = 'วิกฤตราคาน้ำมันและห่วงโซ่อุปทานโลกจากสงครามภูมิภาค';
        addChronicle(world, 'ECONOMIC', `🌍🛢️ [วิกฤตพลังงานโลก] สงครามที่ขยายตัวทำให้ดัชนีราคาน้ำมันโลกพุ่งสู่ ${gm.oilPriceIndex} จุด รัฐผู้ส่งออกพลังงานมีรายได้เพิ่ม ขณะที่รัฐผู้นำเข้าเผชิญแรงกดดันเงินเฟ้อ!`, null);
      } else {
        gm.oilPriceIndex = Math.round(gm.oilPriceIndex * 0.85 + 15);
        gm.activeGlobalCrisis = null;
      }
    }

    // B. State-Level Conditional Events (Political, Economic, Military, International, Natural)
    if (!rng.chance(0.32)) return;
    const st = rng.pick(liveStates);
    if (!st) return;
    ensureStateDeepProfileV170(world, st);
    const city = rng.pick(stateCities(world, st.id));

    if (st.politicalPressures && st.politicalPressures.corruptionPressure > 52 && rng.chance(0.35)) {
      st.approval = rnd1(clamp(st.approval - 3.5, 10, 98));
      addChronicle(world, 'POLITICAL', `⚖️📰 [ข่าวอื้อฉาวทางการเมือง] สื่อมวลชนเปิดโปงคดีทุจริตการจัดซื้อจัดจ้างใน ${st.name} ส่งผลให้คะแนนนิยมรัฐบาลลดลงเหลือ ${st.approval}%`, st.id);
    } else if (st.industrialSectors && st.industrialSectors.semiconductor >= 82 && rng.chance(0.35)) {
      st.gdpB = rnd1(st.gdpB * 1.008);
      st.researchPoints = (st.researchPoints || 0) + 12;
      addChronicle(world, 'ECONOMIC', `📟✨ [การขยายตัวอุตสาหกรรมเซมิคอนดักเตอร์และ AI] นิคมเทคโนโลยีที่ ${city ? city.name : st.name} เปิดสายการผลิตชิปรุ่นใหม่ ดัน GDP ของ ${st.shortName} สู่ $${st.gdpB}B`, st.id, city ? { cityId: city.id } : {});
    } else {
      // Joint Military Exercise with Ally or Trade Partner
      const partnerId = (st.tradePartners || []).find((p) => world.states[p] && !world.states[p].isExiled && relOf(world, st.id, p).status !== 'War');
      if (partnerId && world.states[partnerId]) {
        const partner = world.states[partnerId];
        relOf(world, st.id, partnerId).score = clamp(relOf(world, st.id, partnerId).score + 2, 0, 100);
        relOf(world, partnerId, st.id).score = relOf(world, st.id, partnerId).score;
        addChronicle(world, 'MILITARY', `🎖️🤝 [การซ้อมรบร่วมและข้อตกลงยุทธศาสตร์] กองทัพ ${st.name} และ ${partner.name} จัดการฝึกผสมทางทหารและยกระดับความมั่นคงห่วงโซ่อุปทานร่วมกัน`, st.id);
      }
    }
  }

  // 8. Chronicle Compression & History Bucketing (Section 77: Prevent RAM growth over 100 years)
  function compressWorldHistoryAndChronicle(world) {
    if (!world.chronicleArchives) world.chronicleArchives = [];
    if (world.chronicle && world.chronicle.length > 420) {
      const overflow = world.chronicle.splice(360);
      const majorCount = overflow.filter((e) => ['WAR', 'BATTLE', 'OCCUPATION', 'COUP', 'FOUNDATION', 'DIGEST'].includes(e.category)).length;
      if (overflow.length > 0) {
        world.chronicleArchives.unshift({
          year: world.year,
          tick: world.tick,
          eventsCompressed: overflow.length,
          majorEventsCount: majorCount,
          summary: `แฟ้มจดหมายเหตุปี ${world.year} (รวบรวมเหตุการณ์ย่อย ${overflow.length} รายการ, เหตุการณ์ยุทธศาสตร์สำคัญ ${majorCount} รายการ)`
        });
        if (world.chronicleArchives.length > 50) world.chronicleArchives.length = 50;
      }
    }
  }

  // 9. Data Integrity Validation & Self-Healing System (Sections 93, 94, 95)
  function validateAndHealWorld(world, rngInstance = null) {
    if (!world || !world.states) return { healedCount: 0 };
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + world.tick);
    let healedCount = 0;
    const validStateIds = Object.keys(world.states);
    const fallbackStateId = validStateIds[0] || 'TH';

    // 1. Validate Cities
    Object.values(world.cities).forEach((c) => {
      if (!world.states[c.stateId]) {
        c.stateId = world.states[c.originalOwnerId] ? c.originalOwnerId : fallbackStateId;
        healedCount++;
      }
      const gov = c.governorId ? world.npcs[c.governorId] : null;
      if (!gov || !gov.alive || gov.retired) {
        const cand = selectBestCandidateForRole(world, c.stateId, 'CITY_GOVERNOR', c.id, rng);
        if (cand) {
          promoteNPC(world, cand, 'CITY_GOVERNOR', c.id);
          c.governorId = cand.id;
          healedCount++;
        }
      }
    });

    // 2. Validate Military Camps
    Object.values(world.camps).forEach((cp) => {
      if (!world.states[cp.stateId]) {
        cp.stateId = fallbackStateId;
        healedCount++;
      }
      const cmd = cp.commanderId ? world.npcs[cp.commanderId] : null;
      if (!cmd || !cmd.alive || cmd.retired) {
        const cand = selectBestCandidateForRole(world, cp.stateId, 'BASE_COMMANDER', cp.id, rng);
        if (cand) {
          promoteNPC(world, cand, 'BASE_COMMANDER', cp.id);
          cp.commanderId = cand.id;
          healedCount++;
        }
      }
    });

    // 3. Validate Carriers
    Object.values(world.carriers).forEach((csg) => {
      if (!world.states[csg.stateId]) {
        csg.stateId = fallbackStateId;
        healedCount++;
      }
      const adm = csg.commanderId ? world.npcs[csg.commanderId] : null;
      if (!adm || !adm.alive || adm.retired) {
        const cand = selectBestCandidateForRole(world, csg.stateId, 'CARRIER_ADMIRAL', csg.id, rng);
        if (cand) {
          promoteNPC(world, cand, 'CARRIER_ADMIRAL', csg.id);
          csg.commanderId = cand.id;
          healedCount++;
        }
      }
    });

    // 4. Validate Companies
    (world.companies || []).forEach((co) => {
      if (!world.states[co.stateId]) {
        co.stateId = fallbackStateId;
        healedCount++;
      }
      const ceo = co.ceoId ? world.npcs[co.ceoId] : null;
      if (!ceo || !ceo.alive || ceo.retired) {
        const cand = selectBestCandidateForRole(world, co.stateId, 'CEO_DIRECTOR', co.id, rng);
        if (cand) {
          promoteNPC(world, cand, 'CEO_DIRECTOR', co.id);
          co.ceoId = cand.id;
          healedCount++;
        }
      }
    });

    // 5. Validate State National Positions & Alliances
    Object.values(world.states).forEach((st) => {
      if (st.isExiled) return;
      ['HEAD_OF_STATE', 'DEFENSE_MINISTER', 'SUPREME_COMMANDER', 'LOGISTICS_CHIEF', 'FINANCE_MINISTER'].forEach((posKey) => {
        const cur = st.positions[posKey] ? world.npcs[st.positions[posKey]] : null;
        if (!cur || !cur.alive || cur.retired) {
          const cand = selectBestCandidateForRole(world, st.id, posKey, null, rng);
          if (cand) {
            promoteNPC(world, cand, posKey);
            st.positions[posKey] = cand.id;
            healedCount++;
          }
        }
      });
    });

    (world.alliances || []).forEach((al) => {
      al.members = (al.members || []).filter((m) => !!world.states[m]);
    });

    return { ok: true, healedCount };
  }

  // 10. Developer Diagnostics & Telemetry Helper (Section 103)
  function getDevDiagnostics(world) {
    if (!world) return {};
    const npcs = Object.values(world.npcs || {});
    const alive = npcs.filter((n) => n.alive);
    const byTier = { 4: 0, 3: 0, 2: 0, 1: 0, 0: 0 };
    alive.forEach((n) => { byTier[n.tier || 0] = (byTier[n.tier || 0] || 0) + 1; });
    const tickTimes = (world.metrics && world.metrics.tickTimesMs) || [];
    const avgTickMs = tickTimes.length > 0 ? +(tickTimes.reduce((a, b) => a + b, 0) / tickTimes.length).toFixed(2) : 0;
    const maxTickMs = tickTimes.length > 0 ? +Math.max(...tickTimes).toFixed(2) : 0;
    const dirtyStates = Object.values(world.states || {}).filter((s) => s.logisticsDirty || s.frontlineDirty || s.vacancyDirty).length;

    return {
      version: world.version || VERSION,
      year: world.year,
      tick: world.tick,
      statesCount: Object.keys(world.states || {}).length,
      citiesCount: Object.keys(world.cities || {}).length,
      campsCount: Object.keys(world.camps || {}).length,
      carriersCount: Object.keys(world.carriers || {}).length,
      shipsCount: Object.keys(world.ships || {}).length,
      armiesCount: Object.keys(world.armies || {}).length,
      unitsCount: Object.keys(world.militaryUnits || {}).length,
      companiesCount: (world.companies || []).length,
      alliancesCount: (world.alliances || []).length,
      researchInstitutesCount: Object.keys(world.researchInstitutes || {}).length,
      totalNpcRecords: npcs.length,
      aliveNpcsCount: alive.length,
      npcsByTier: byTier,
      activeWarsCount: (world.wars || []).filter((w) => w.status === 'War').length,
      activeConvoysCount: (world.convoys || []).length,
      avgTickMs,
      maxTickMs,
      totalDecisions: world.metrics?.totalDecisions || 0,
      logisticsCalls: world.metrics?.logisticsCognitionCalls || 0,
      dirtyStatesCount: dirtyStates,
      chronicleCount: (world.chronicle || []).length,
      chronicleArchivesCount: (world.chronicleArchives || []).length
    };
  }

  // =========================================================================
  // HOOK v1.7.0 INTO createInitialWorld, stepDay, migrateWorld & calculateStateCombatPotential
  // =========================================================================
  const _origResolveEntityV170 = resolveEntity;
  resolveEntity = function (world, rawUri) {
    if (!world || !rawUri) return _origResolveEntityV170(world, rawUri);
    const [rawType, ...rest] = String(rawUri).trim().split(":");
    const type = (rawType || "").toLowerCase();
    const id = rest.join(":");
    if (type === "institute" && world.researchInstitutes && world.researchInstitutes[id]) {
      const inst = world.researchInstitutes[id];
      return { uri: `institute:${inst.id}`, type: "institute", id: inst.id, title: `🔬 ${inst.name}`, badge: "RESEARCH INSTITUTE (สถาบันวิจัยแห่งชาติ)", data: inst };
    }
    if (type === "technology" && TECH_BRANCH_TH[id]) {
      return { uri: `technology:${id}`, type: "technology", id, title: `💻 สาขาเทคโนโลยี: ${TECH_BRANCH_TH[id]} (${id})`, badge: "TECHNOLOGY BRANCH (สายการวิจัยเทคโนโลยี)", data: { id, key: id, name: TECH_BRANCH_TH[id] } };
    }
    return _origResolveEntityV170(world, rawUri);
  };

  const _origGetEntityBreadcrumbsV170 = getEntityBreadcrumbs;
  getEntityBreadcrumbs = function (world, rawUri) {
    const res = resolveEntity(world, rawUri);
    if (res.type === "institute") {
      const st = world.states[res.data.stateId];
      const crumbs = [{ uri: "world:WORLD", label: "🌍 โลก (World 2026)" }];
      if (st) crumbs.push({ uri: `state:${st.id}`, label: `${st.flag || ""} ${st.shortName}` });
      crumbs.push({ uri: res.uri, label: `🔬 ${res.data.name}` });
      return crumbs;
    }
    if (res.type === "technology") {
      return [{ uri: "world:WORLD", label: "🌍 โลก (World 2026)" }, { uri: res.uri, label: res.title }];
    }
    return _origGetEntityBreadcrumbsV170(world, rawUri);
  };

  const _origSearchAllEntitiesV170 = searchAllEntities;
  searchAllEntities = function (world, query, limit = 30) {
    const base = _origSearchAllEntitiesV170(world, query, 250);
    const q = (query || "").trim().toLowerCase();
    const extra = [];
    Object.values(world.researchInstitutes || {}).forEach((inst) => {
      extra.push({ uri: `institute:${inst.id}`, type: "Research Institute (สถาบันวิจัย)", title: `🔬 ${inst.name}`, sub: `รัฐ ${inst.stateId} • ${inst.specialty}` });
    });
    TECH_BRANCH_KEYS.forEach((tk) => {
      extra.push({ uri: `technology:${tk}`, type: "Technology (เทคโนโลยี)", title: `💻 ${TECH_BRANCH_TH[tk]} (${tk})`, sub: "สายการวิจัยและพัฒนาเทคโนโลยี" });
    });
    const filtered = !q ? extra : extra.filter((it) => it.title.toLowerCase().includes(q) || it.sub.toLowerCase().includes(q) || it.type.toLowerCase().includes(q) || it.uri.toLowerCase().includes(q));
    return [...base, ...filtered].slice(0, limit);
  };

  const _origCreateInitialWorldV170 = createInitialWorld;
  createInitialWorld = function (seed = 202611717) {
    const world = _origCreateInitialWorldV170(seed);
    ensureWorldSystemsV170(world);
    return world;
  };

  const _origCalcPotentialV170 = calculateStateCombatPotential;
  calculateStateCombatPotential = function (world, stateId) {
    const p = _origCalcPotentialV170(world, stateId);
    const st = world.states[stateId];
    if (!st) return p;
    if (!st.militaryReadiness) ensureStateDeepProfileV170(world, st);
    // Apply doctrine, readiness, fuel/ammo & space intelligence modifiers (Sections 31, 32, 44)
    const mr = st.militaryReadiness;
    const readinessMod = clamp(0.65 + (mr.overallScore / 100) * 0.45, 0.45, 1.25);
    const doc = st.doctrineType;
    const landDocMod = ['Mechanized', 'Offensive', 'Attritional'].includes(doc) ? 1.08 : 1.0;
    const airDocMod = ['Air Superiority', 'Missile-centric', 'Expeditionary'].includes(doc) ? 1.10 : 1.0;
    const navDocMod = ['Naval Power', 'Expeditionary'].includes(doc) ? 1.12 : 1.0;

    p.landPower = Math.round(p.landPower * readinessMod * landDocMod);
    p.airPower = Math.round(p.airPower * readinessMod * airDocMod);
    p.navalPower = Math.round(p.navalPower * readinessMod * navDocMod);
    p.totalPower = p.landPower + p.airPower + p.navalPower;
    p.readinessScore = mr.overallScore;
    p.doctrineType = doc;
    return p;
  };

  const _origStepDayV170 = stepDay;
  stepDay = function (world, rngInstance = null) {
    if (!world._v170) {
      ensureWorldSystemsV170(world);
    }
    _origStepDayV170(world, rngInstance);
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + world.tick * 4999);
    const t = world.tick;

    // Update War Escalation & Strategic Objectives every 6 days
    if (t % 6 === 2 && world.wars && world.wars.length > 0) {
      world.wars.forEach((w) => ensureWarEscalationAndObjectives(world, w));
    }
    // Military Readiness & Base Supply Chain every 15 days
    if (t % 15 === 3) {
      runMilitaryReadinessAndBaseLogisticsCycle(world, rng);
    }
    // City AI Governance every 20 days
    if (t % 20 === 8) {
      runCityGovernanceCycle(world, rng);
    }
    // Economic Supply Chain & Company AI every 30 days
    if (t % 30 === 12) {
      runEconomicSupplyNetworkCycle(world, rng);
    }
    // Internal Politics, Factions & Underground/Democracy Dynamics every 30 days
    if (t % 30 === 18) {
      runInternalPoliticsAndFactionsCycle(world, rng);
    }
    // Dynamic Events & Chronicle Compression every 45 days
    if (t % 45 === 25) {
      runDynamicEventsCycleV170(world, rng);
      compressWorldHistoryAndChronicle(world);
    }
    // Self-Healing & Vacancy Check every 60 days
    if (t % 60 === 40) {
      validateAndHealWorld(world, rng);
    }
    return world;
  };

  const _origMigrateWorldV170 = migrateWorld;
  migrateWorld = function (world) {
    if (!world || !world.states) return world;
    _origMigrateWorldV170(world);
    ensureWorldSystemsV170(world);
    validateAndHealWorld(world);
    return world;
  };



