  // -------------------------------------------------------------------------
  // 1. NPC & POWER NETWORK 2.0 (Formal Power != Real Power)
  // -------------------------------------------------------------------------
  function getFormalPositionCategory(npc) {
    if (!npc) return 'Bureaucrat';
    if (FORMAL_POSITION_MAP_V200[npc.positionId]) return FORMAL_POSITION_MAP_V200[npc.positionId];
    if (npc.track === 'military') return npc.stage >= 5 ? 'General' : 'Junior Officer';
    if (npc.track === 'business') return npc.stage >= 6 ? 'CEO' : 'Business Leader';
    if (npc.track === 'political') return npc.stage >= 6 ? 'Minister' : 'Party Leader';
    return 'Bureaucrat';
  }

  function computeNPCSimTier(npc) {
    // Prompt Section 45:
    // Tier 0: Head of state / major generals / major CEOs / intelligence chiefs (Full detail)
    // Tier 1: Senior officials / commanders / important politicians (Medium detail)
    // Tier 2: Normal NPCs (Periodic update)
    // Tier 3: Background population / junior pool (Aggregate simulation)
    if (!npc) return 2;
    const topPositions = ['HEAD_OF_STATE', 'PRIME_MINISTER', 'SUPREME_COMMANDER', 'ARMY_CHIEF', 'NAVY_CHIEF', 'AIR_FORCE_CHIEF', 'INTELLIGENCE_CHIEF', 'CEO_DIRECTOR', 'COMPANY_CHAIRMAN'];
    if (topPositions.includes(npc.positionId) || npc.tier >= 4) return 0;
    if (npc.tier === 3 || npc.stage >= 5 || ['DEFENSE_MINISTER', 'FINANCE_MINISTER', 'FOREIGN_MINISTER', 'INTERIOR_MINISTER', 'PARTY_LEADER', 'OPPOSITION_LEADER', 'CITY_GOVERNOR', 'BASE_COMMANDER', 'CARRIER_ADMIRAL'].includes(npc.positionId)) return 1;
    if (npc.tier === 2 || npc.stage >= 3) return 2;
    return 3;
  }

  function ensureNPCPowerModelV200(world, npc) {
    if (!npc) return;
    const st = world.states[npc.stateId];
    npc.formalPosition = npc.formalPosition || getFormalPositionCategory(npc);
    npc.formalAuthority = npc.authority ?? 50;
    npc.simTier = computeNPCSimTier(npc);

    // Core abilities & traits (Section 3.1)
    if (npc.competence === undefined) {
      npc.competence = clamp(Math.round((npc.intelligence || 70) * 0.45 + (npc.meritScore || 65) * 0.35 + (npc.planning || 68) * 0.20), 25, 99);
    }
    if (npc.charisma === undefined) npc.charisma = 68;
    if (npc.strategicAbility === undefined) {
      npc.strategicAbility = clamp(Math.round((npc.planning || 70) * 0.5 + (npc.intelligence || 70) * 0.3 + (npc.knowledge?.military || 50) * 0.2), 25, 99);
    }
    if (npc.administrativeAbility === undefined) {
      npc.administrativeAbility = clamp(Math.round((npc.knowledge?.administration || 60) * 0.55 + (npc.adminTrack || 55) * 0.45), 20, 99);
    }
    if (npc.militaryAbility === undefined) {
      npc.militaryAbility = clamp(Math.round((npc.knowledge?.military || 50) * 0.5 + (npc.experience?.combatExp || 30) * 0.25 + (npc.leadership || 65) * 0.25), 15, 99);
    }
    if (npc.diplomaticAbility === undefined) {
      npc.diplomaticAbility = clamp(Math.round((npc.knowledge?.politics || 55) * 0.5 + (npc.charisma || 65) * 0.3 + (npc.intelligence || 70) * 0.2), 20, 99);
    }
    if (npc.intelligenceAbility === undefined) {
      npc.intelligenceAbility = clamp(Math.round((npc.intelligence || 70) * 0.5 + (npc.planning || 68) * 0.3 + (npc.positionId === 'INTELLIGENCE_CHIEF' ? 18 : 0)), 20, 99);
    }
    if (npc.ideology === undefined) npc.ideology = npc.politicalIdeology || 'Pragmatist';
    if (npc.corruptionRisk === undefined) {
      npc.corruptionRisk = clamp(Math.round(100 - (npc.integrity || 72) + (npc.ambition || 60) * 0.15), 5, 95);
    }
    if (npc.reputation === undefined) {
      npc.reputation = clamp(Math.round((npc.meritScore || 65) * 0.6 + (npc.charisma || 65) * 0.25 + (npc.victories || 0) * 6), 15, 99);
    }
    if (npc.legitimacy === undefined) {
      npc.legitimacy = clamp(Math.round((st ? st.stability : 75) * 0.5 + (npc.reputation || 65) * 0.3 + (npc.integrity || 70) * 0.2), 15, 99);
    }
    if (npc.fear === undefined) {
      npc.fear = clamp(npc.track === 'military' || npc.positionId === 'INTELLIGENCE_CHIEF' ? 45 : 22, 5, 98);
    }
    if (npc.trust === undefined) {
      npc.trust = clamp(Math.round((npc.loyalty || 70) * 0.5 + (npc.integrity || 70) * 0.3 + 15), 10, 98);
    }
    if (npc.victories === undefined) npc.victories = 0;
    if (npc.scandalsCount === undefined) npc.scandalsCount = 0;
    if (npc.officersLoyal === undefined) npc.officersLoyal = npc.track === 'military' ? clamp(Math.round((npc.leadership || 70) * 0.7 + (npc.reputation || 65) * 0.3), 20, 98) : 15;
    if (npc.troopsLoyal === undefined) npc.troopsLoyal = npc.track === 'military' ? clamp(Math.round((npc.charisma || 65) * 0.4 + (npc.militaryAbility || 65) * 0.6), 20, 98) : 12;

    // Upgrade Relationships to 2.0 format (Section 3.4)
    if (!Array.isArray(npc.relationships)) npc.relationships = [];
    for (let i = 0; i < npc.relationships.length; i++) {
      const r = npc.relationships[i];
      if (r.type === 'student') r.type = 'protege';
      if (r.type === 'political_partner') r.type = 'politicalPartner';
      if (r.type === 'business_partner') r.type = 'businessPartner';
      if (r.type === 'military_rival') r.type = 'rival';
      const isPos = (r.strength || 0) >= 0 && !['rival', 'enemy', 'suspectedEnemy'].includes(r.type);
      if (r.trust === undefined) r.trust = isPos ? clamp(55 + Math.round((r.strength || 50) * 0.35), 10, 98) : clamp(30 + Math.round((r.strength || -40) * 0.25), 5, 60);
      if (r.loyalty === undefined) r.loyalty = isPos ? clamp(50 + Math.round((r.strength || 50) * 0.4), 10, 98) : 15;
      if (r.reciprocity === undefined) r.reciprocity = isPos ? 72 : 25;
      if (r.lastInteraction === undefined) r.lastInteraction = world.tick || 0;
      if (!r.reason) r.reason = isPos ? 'ร่วมงานในสายบังคับบัญชาและอุดมการณ์สอดคล้องกัน' : 'แข่งขันชิงอำนาจและขัดแย้งเชิงนโยบาย';
      if (!Array.isArray(r.history)) r.history = [`[${world.year || 2026}] ${r.reason}`];
      if (r.hidden === undefined) r.hidden = r.type === 'secretContact' || r.type === 'suspectedEnemy';
      if (!r.visibility) r.visibility = r.hidden ? 'hidden' : 'public';
    }

    // Recompute derived power sources & realInfluence if dirty or missing
    if (npc.realInfluence === undefined || npc._powerDirty || !npc.powerSources || !npc.powerModel) {
      recalculateNPCPowerModel(world, npc);
    }
  }

  function recalculateNPCPowerModel(world, npc) {
    if (!npc) return;
    const st = world.states[npc.stateId];
    const formalAuth = npc.authority ?? 50;
    const isTopExec = npc.positionId === 'HEAD_OF_STATE' || npc.positionId === 'PRIME_MINISTER';
    const isMil = npc.track === 'military';
    const isBiz = npc.track === 'business';
    const isIntel = npc.positionId === 'INTELLIGENCE_CHIEF';

    // Faction & Coalition context in state
    const factions = (st && st.factions) || [];
    const myFac = factions.find((f) => f.leaderNpcId === npc.id || f.name === npc.faction || f.type === npc.faction) || factions[0];
    const facInfluence = myFac ? (myFac.power ?? myFac.influence ?? 25) : 22;
    const facCohesion = myFac ? (myFac.cohesion ?? 75) : 72;

    // State stability & support multipliers (Section 2.1: Formal Power != Real Power!)
    const milSupportForGov = st ? (st.militaryLoyalty ?? (100 - (st.politicalPressures?.militaryInfluence || 35) * 0.4)) : 75;
    const eliteSupportForGov = st ? (st.eliteSupport ?? st.politicalPressures?.eliteSupport ?? 72) : 72;
    const pubApproval = st ? (st.approval ?? 70) : 70;
    const burCompliance = st ? (st.bureaucraticCompliance ?? 78) : 78;

    // 1. Political Power Source
    let polPosScore = ['President', 'Prime Minister', 'Minister', 'Party Leader', 'Opposition Leader', 'Governor'].includes(npc.formalPosition) ? formalAuth : formalAuth * 0.45;
    if (isTopExec) {
      // If party is split, military disloyal, business elite withdraws, public angry, bureaucracy resists -> formal leader loses real political power!
      const supportPenalty =
        (facCohesion < 55 ? (55 - facCohesion) * 0.45 : 0) +
        (milSupportForGov < 55 ? (55 - milSupportForGov) * 0.35 : 0) +
        (eliteSupportForGov < 55 ? (55 - eliteSupportForGov) * 0.30 : 0) +
        (pubApproval < 50 ? (50 - pubApproval) * 0.35 : 0) +
        (burCompliance < 55 ? (55 - burCompliance) * 0.25 : 0);
      polPosScore = clamp(polPosScore - supportPenalty, 18, 99);
    }
    const partyScore = clamp(Math.round(facInfluence * 1.4 + (npc.politicalTrack || 50) * 0.35), 10, 98);
    const coalitionScore = st && st.democracyState ? (st.democracyState.coalitionStability || 70) : (st ? st.stability : 70);
    const pubSupScore = clamp(Math.round((isTopExec ? pubApproval : (npc.charisma || 65) * 0.55 + (npc.reputation || 65) * 0.45) + (npc.victories || 0) * 5 - (npc.scandalsCount || 0) * 12), 5, 99);

    const politicalSource = {
      position: Math.round(polPosScore),
      party: partyScore,
      parliament: Math.round(coalitionScore * 0.85),
      coalition: Math.round(coalitionScore),
      publicSupport: pubSupScore,
      total: clamp(Math.round(polPosScore * 0.35 + partyScore * 0.25 + coalitionScore * 0.15 + pubSupScore * 0.25), 5, 99)
    };

    // 2. Military Power Source (Section 2.1 & 3.3: Generals can accumulate high real power!)
    const hasCommand = isMil || !!(npc.assignedNodeId && (world.camps[npc.assignedNodeId] || world.carriers[npc.assignedNodeId] || world.armies?.[npc.assignedNodeId]));
    const cmdScore = isMil ? clamp(formalAuth + (hasCommand ? 12 : 0), 15, 99) : (npc.positionId === 'DEFENSE_MINISTER' ? 68 : 12);
    const troopsLoyal = clamp(npc.troopsLoyal || (isMil ? 72 : 15), 5, 99);
    const officersLoyal = clamp(npc.officersLoyal || (isMil ? 70 : 15), 5, 99);
    const milRep = clamp(Math.round((npc.reputation || 65) * (isMil ? 1.0 : 0.4) + (npc.victories || 0) * 8), 5, 99);
    const militarySource = {
      command: cmdScore,
      troopsLoyalty: troopsLoyal,
      militaryReputation: milRep,
      victories: npc.victories || 0,
      officerNetwork: officersLoyal,
      total: clamp(Math.round(cmdScore * 0.30 + troopsLoyal * 0.25 + milRep * 0.25 + officersLoyal * 0.20 + (npc.victories || 0) * 4), 5, 99)
    };

    // 3. Economic Power Source
    const ownedCompany = (isBiz || (npc.assignedNodeId && String(npc.assignedNodeId).startsWith('COMP_'))) ? (world.companies || []).find((c) => c.ceoId === npc.id || c.cfoId === npc.id || c.ctoId === npc.id || c.ownerNpcId === npc.id) : null;
    const compScore = ownedCompany ? clamp(Math.round(45 + (ownedCompany.capitalB || 30) * 0.45 + (ownedCompany.contractsCount || 1) * 5), 25, 99) : (isBiz ? 58 : 15);
    const wealthScore = clamp(Math.round(Math.min(98, (npc.wealthM || 5) * 1.2 + (isBiz ? 30 : 10))), 10, 99);
    const economicSource = {
      companyOwnership: compScore,
      wealth: wealthScore,
      industrialControl: ownedCompany ? clamp(Math.round(compScore * 0.9), 20, 98) : (npc.positionId === 'INDUSTRY_MINISTER' || npc.positionId === 'FINANCE_MINISTER' ? 78 : 20),
      tradeNetwork: clamp(Math.round((npc.businessTrack || 40) * 0.75 + (ownedCompany ? 22 : 0)), 10, 98),
      resourceAccess: st ? clamp(Math.round(((st.resources12?.oil || 50) + (st.resources12?.semiconductors || 50)) * 0.35 * (isBiz || isTopExec ? 1.2 : 0.5)), 10, 95) : 35,
      total: clamp(Math.round(compScore * 0.35 + wealthScore * 0.25 + (npc.businessTrack || 40) * 0.40), 5, 99)
    };

    // 4. Bureaucratic Power Source
    const bureaucraticSource = {
      ministry: ['Minister', 'Prime Minister', 'President', 'Governor', 'Bureaucrat'].includes(npc.formalPosition) ? clamp(formalAuth, 25, 96) : 22,
      civilServiceNetwork: clamp(Math.round((npc.administrativeAbility || 60) * 0.65 + (npc.experience?.governanceExp || 30) * 0.35), 15, 98),
      institutionalLoyalty: st ? Math.round(burCompliance) : 75,
      total: clamp(Math.round((npc.administrativeAbility || 60) * 0.5 + (npc.adminTrack || 50) * 0.3 + (isTopExec ? burCompliance * 0.2 : 12)), 8, 98)
    };

    // 5. Social Power Source
    const socialSource = {
      media: npc.formalPosition === 'Media Owner' || npc.positionId === 'POLITICAL_STRATEGIST' ? 86 : clamp(Math.round((npc.charisma || 65) * 0.65), 15, 92),
      culturalInfluence: clamp(Math.round((npc.reputation || 60) * 0.6 + (npc.legitimacy || 65) * 0.4), 15, 95),
      academicInfluence: npc.formalPosition === 'Academic Leader' ? 88 : clamp(Math.round((npc.intelligence || 70) * 0.5), 15, 90),
      regionalInfluence: npc.formalPosition === 'Governor' ? 82 : 45,
      total: clamp(Math.round(pubSupScore * 0.45 + (npc.charisma || 65) * 0.35 + (npc.reputation || 65) * 0.20), 10, 98)
    };

    // 6. Intelligence Power Source
    const secretContactsCount = (npc.relationships || []).filter((r) => r.hidden || r.type === 'secretContact').length;
    const intelligenceSource = {
      intelNetwork: isIntel ? 92 : clamp(Math.round((npc.intelligenceAbility || 60) * 0.6 + secretContactsCount * 12), 10, 96),
      secretsHeld: clamp((isIntel ? 75 : 20) + secretContactsCount * 15, 5, 98),
      informants: isIntel ? 85 : clamp(15 + secretContactsCount * 14, 5, 95),
      classifiedAccess: isIntel || isTopExec || npc.positionId === 'SUPREME_COMMANDER' ? 90 : 25,
      total: clamp(Math.round((isIntel ? 88 : (npc.intelligenceAbility || 55) * 0.55) + secretContactsCount * 10), 8, 99)
    };

    // Network Power from relationships (Allies, Partners, Subordinates, Mentors)
    let relBonus = 0;
    const rels = npc.relationships || [];
    for (let i = 0; i < rels.length; i++) {
      const r = rels[i];
      const other = world.npcs[r.targetId];
      const otherAuth = other ? (other.authority || 50) : 50;
      if (['ally', 'friend', 'mentor', 'protege', 'politicalPartner', 'businessPartner', 'militaryComrade', 'ideologicalAlly'].includes(r.type)) {
        relBonus += (otherAuth * 0.08) * ((r.trust || 65) / 100);
      } else if (['rival', 'enemy', 'suspectedEnemy'].includes(r.type)) {
        relBonus -= (otherAuth * 0.04);
      }
    }
    const networkPower = clamp(Math.round(42 + relBonus + rels.length * 4), 10, 99);
    const factionPower = clamp(Math.round(facInfluence * 1.35 + (myFac && myFac.leaderNpcId === npc.id ? 22 : 8)), 10, 99);
    const institutionalControl = clamp(Math.round(
      (isTopExec ? burCompliance * 0.45 + milSupportForGov * 0.35 + coalitionScore * 0.20 : formalAuth * 0.6 + bureaucraticSource.total * 0.4)
    ), 10, 99);

    // Sync player manual override if set
    const manualPol = npc._manualPoliticalPower;
    const manualMil = npc._manualMilitaryInfluence;
    const manualEco = npc._manualEconomicInfluence;

    npc.politicalPower = manualPol !== undefined ? manualPol : politicalSource.total;
    npc.militaryInfluence = manualMil !== undefined ? manualMil : militarySource.total;
    npc.economicInfluence = manualEco !== undefined ? manualEco : economicSource.total;
    npc.bureaucraticInfluence = bureaucraticSource.total;
    npc.publicSupport = pubSupScore;
    npc.institutionalControl = institutionalControl;
    npc.factionPower = factionPower;
    npc.networkPower = networkPower;

    // Real Power / Influence synthesis (Section 2.1: Formal Power != Real Power)
    // A General with huge militaryInfluence + publicSupport + networkPower can surpass a weak Prime Minister!
    const topDomains = [npc.politicalPower, npc.militaryInfluence, npc.economicInfluence, npc.bureaucraticInfluence, intelligenceSource.total].sort((a, b) => b - a);
    let computedReal = Math.round(
      topDomains[0] * 0.42 +
      topDomains[1] * 0.22 +
      npc.networkPower * 0.14 +
      npc.factionPower * 0.12 +
      npc.publicSupport * 0.10
    );
    if (isTopExec && (milSupportForGov < 45 || coalitionScore < 40 || pubApproval < 38)) {
      computedReal = Math.min(computedReal, Math.round(formalAuth * 0.58));
    }
    if (isMil && (npc.victories >= 2 || (st && (st.politicalPressures?.militaryInfluence || 35) >= 65))) {
      computedReal = Math.min(99, computedReal + 10 + Math.min(14, (npc.victories || 0) * 4));
    }
    npc.realInfluence = npc._manualRealInfluence !== undefined ? npc._manualRealInfluence : clamp(computedReal, 8, 99);

    npc.powerSources = {
      political: politicalSource,
      military: militarySource,
      economic: economicSource,
      bureaucratic: bureaucraticSource,
      social: socialSource,
      intelligence: intelligenceSource
    };

    npc.powerModel = {
      formalPosition: npc.formalPosition,
      formalAuthority: formalAuth,
      realInfluence: npc.realInfluence,
      politicalPower: npc.politicalPower,
      militaryInfluence: npc.militaryInfluence,
      economicInfluence: npc.economicInfluence,
      bureaucraticInfluence: npc.bureaucraticInfluence,
      publicSupport: npc.publicSupport,
      institutionalControl: npc.institutionalControl,
      factionPower: npc.factionPower,
      networkPower: npc.networkPower,
      reputation: npc.reputation,
      legitimacy: npc.legitimacy,
      loyalty: npc.loyalty,
      fear: npc.fear,
      trust: npc.trust,
      ambition: npc.ambition,
      riskTolerance: npc.riskTolerance,
      ideology: npc.ideology,
      corruptionRisk: npc.corruptionRisk,
      competence: npc.competence,
      charisma: npc.charisma,
      strategicAbility: npc.strategicAbility,
      administrativeAbility: npc.administrativeAbility,
      militaryAbility: npc.militaryAbility,
      diplomaticAbility: npc.diplomaticAbility,
      intelligenceAbility: npc.intelligenceAbility
    };

    // Debug/Observer explanation ("Why does this NPC have this power?")
    const reasons = [];
    reasons.push(`ตำแหน่งทางการ: ${npc.formalPosition} (Formal Auth ${formalAuth}) vs อำนาจจริง (Real Power ${npc.realInfluence})`);
    if (npc.realInfluence > formalAuth + 8) {
      reasons.push(`⚡ มีอำนาจจริงสูงกว่าตำแหน่ง เพราะฐานอิทธิพล (${topDomains[0]}) เครือข่ายพันธมิตร (${npc.networkPower}) และความสำเร็จ/บารมี (${npc.reputation})`);
    } else if (npc.realInfluence < formalAuth - 8) {
      reasons.push(`⚠️ อำนาจจริงต่ำกว่าตำแหน่งทางการ เนื่องจากพรรค/กลุ่มการเมืองขาดเอกภาพ (${facCohesion}%) หรือกองทัพ/กลุ่มทุน/ประชาชนไม่หนุนหลังเต็มที่`);
    }
    if (ownedCompany) reasons.push(`🏭 กุมอำนาจเศรษฐกิจผ่านบริษัท ${ownedCompany.name} (ทุน $${ownedCompany.capitalB}B)`);
    if (npc.victories > 0) reasons.push(`🎖️ ชนะสมรภูมิรบ ${npc.victories} ครั้ง ส่งผลให้ทหารใต้บังคับบัญชาภักดี ${troopsLoyal}%`);
    npc.whyPowerBreakdown = reasons;
    npc._powerDirty = false;
  }

  // Power Network Graph per State (Section 3.5: Supporters, Opponents, Most Powerful, Kingmaker, Rival, Mediator/Broker, Institutional Control)
  function analyzeStatePowerNetwork(world, stateId, preFilteredNpcs = null) {
    const st = world.states[stateId];
    if (!st) return null;
    const stateNpcs = preFilteredNpcs || Object.values(world.npcs).filter((n) => n.alive && !n.retired && n.stateId === stateId);
    const headId0 = st.positions?.HEAD_OF_STATE;
    const cmdId0 = st.positions?.SUPREME_COMMANDER;
    if (headId0 && world.npcs[headId0]) world.npcs[headId0]._powerDirty = true;
    if (cmdId0 && world.npcs[cmdId0]) world.npcs[cmdId0]._powerDirty = true;
    for (let i = 0; i < stateNpcs.length; i++) {
      const n = stateNpcs[i];
      if (n.realInfluence === undefined || n._powerDirty || n._manualRealInfluence !== undefined) {
        recalculateNPCPowerModel(world, n);
      }
    }

    const sortedByReal = stateNpcs.slice().sort((a, b) => (b.realInfluence || 0) - (a.realInfluence || 0));
    const headId = st.positions?.HEAD_OF_STATE;
    const headNpc = headId ? world.npcs[headId] : sortedByReal[0];
    const mostPowerful = sortedByReal[0] || headNpc;

    // Kingmaker: Powerful figure outside Head of State whose networkPower + factionPower/militaryInfluence/economicInfluence can tip the balance
    const kingmakerCandidates = sortedByReal.filter((n) => !headNpc || n.id !== headNpc.id);
    const kingmaker = kingmakerCandidates.sort(
      (a, b) => ((b.realInfluence || 0) * 0.45 + (b.networkPower || 0) * 0.35 + (b.factionPower || 0) * 0.20) -
                ((a.realInfluence || 0) * 0.45 + (a.networkPower || 0) * 0.35 + (a.factionPower || 0) * 0.20)
    )[0] || null;

    // Primary Rival to Head of State
    const rival = kingmakerCandidates
      .filter((n) => (n.faction && headNpc && n.faction !== headNpc.faction) || (n.relationships || []).some((r) => r.targetId === headId && ['rival', 'enemy', 'suspectedEnemy'].includes(r.type)) || (n.ambition || 50) >= 72)
      .sort((a, b) => (b.realInfluence || 0) - (a.realInfluence || 0))[0] || kingmakerCandidates[1] || null;

    // Mediator / Broker between Factions: NPC with positive relationships across different factions
    let broker = null;
    let bestCrossLinks = -1;
    for (let i = 0; i < Math.min(25, sortedByReal.length); i++) {
      const cand = sortedByReal[i];
      const crossFactions = new Set();
      (cand.relationships || []).forEach((r) => {
        if ((r.strength || 0) > 0) {
          const t = world.npcs[r.targetId];
          if (t && t.faction && t.faction !== cand.faction) crossFactions.add(t.faction);
        }
      });
      const score = crossFactions.size * 25 + (cand.diplomaticAbility || 50) * 0.4 + (cand.networkPower || 50) * 0.4;
      if (score > bestCrossLinks) {
        bestCrossLinks = score;
        broker = cand;
      }
    }

    // Supporters & Opponents of Head of State
    const supportersOfLeader = [];
    const opponentsOfLeader = [];
    if (headNpc) {
      sortedByReal.slice(0, 30).forEach((n) => {
        if (n.id === headNpc.id) return;
        const relToHead = (n.relationships || []).find((r) => r.targetId === headNpc.id);
        if (relToHead && (relToHead.strength < 0 || ['rival', 'enemy', 'suspectedEnemy'].includes(relToHead.type))) {
          opponentsOfLeader.push(n.id);
        } else if (relToHead && relToHead.strength > 0) {
          supportersOfLeader.push(n.id);
        } else if (n.faction === headNpc.faction && (n.loyalty || 65) >= 55) {
          supportersOfLeader.push(n.id);
        } else if (n.faction !== headNpc.faction && (n.ambition || 50) >= 68) {
          opponentsOfLeader.push(n.id);
        }
      });
    }

    // Institutional Control Map
    const topMil = stateNpcs.filter((n) => n.track === 'military').sort((a, b) => (b.militaryInfluence || 0) - (a.militaryInfluence || 0))[0];
    const topEco = stateNpcs.filter((n) => n.track === 'business' || (n.economicInfluence || 0) >= 70).sort((a, b) => (b.economicInfluence || 0) - (a.economicInfluence || 0))[0];
    const topBur = stateNpcs.filter((n) => n.track === 'civilian' || n.track === 'political').sort((a, b) => (b.bureaucraticInfluence || 0) - (a.bureaucraticInfluence || 0))[0];
    const topIntel = (st.positions?.INTELLIGENCE_CHIEF && world.npcs[st.positions.INTELLIGENCE_CHIEF]) || stateNpcs.sort((a, b) => (b.intelligenceAbility || 0) - (a.intelligenceAbility || 0))[0];
    const topMedia = stateNpcs.find((n) => n.positionId === 'JOURNALIST_MEDIA' || n.positionId === 'POLITICAL_STRATEGIST') || sortedByReal[0];

    // Power Chains (Section 3.5)
    const stateCompanies = (world.companies || []).filter((c) => c.stateId === stateId);
    const foreignIntelOps = (world.intelligenceOps || []).filter((op) => op.targetStateId === stateId && op.active);

    const net = {
      stateId,
      headOfStateId: headNpc ? headNpc.id : null,
      headFormalPower: headNpc ? headNpc.formalAuthority : 0,
      headRealPower: headNpc ? headNpc.realInfluence : 0,
      mostPowerfulNpcId: mostPowerful ? mostPowerful.id : null,
      kingmakerNpcId: kingmaker ? kingmaker.id : null,
      topRivalNpcId: rival ? rival.id : null,
      brokerNpcId: broker ? broker.id : null,
      supportersOfLeader,
      opponentsOfLeader,
      institutionalControl: {
        executive: headNpc ? headNpc.id : null,
        military: topMil ? topMil.id : null,
        economy: topEco ? topEco.id : null,
        bureaucracy: topBur ? topBur.id : null,
        intelligence: topIntel ? topIntel.id : null,
        media: topMedia ? topMedia.id : null
      },
      powerChains: [
        {
          chainType: 'Political-Corporate-Media Chain',
          nodes: [
            headNpc ? `person:${headNpc.id}` : `state:${stateId}`,
            st.positions?.PRIME_MINISTER ? `person:${st.positions.PRIME_MINISTER}` : `government:${stateId}`,
            topEco ? `person:${topEco.id}` : null,
            stateCompanies[0] ? `company:${stateCompanies[0].id}` : null,
            topMedia ? `person:${topMedia.id}` : null
          ].filter(Boolean),
          summary: `${headNpc ? headNpc.name : st.shortName} ➔ พรรครัฐบาล ➔ ${topEco ? topEco.name : 'กลุ่มทุน'} ➔ ${stateCompanies[0] ? stateCompanies[0].name : 'อุตสาหกรรมแห่งชาติ'} ➔ สื่อมวลชน/มติมหาชน (${st.approval}%)`
        },
        {
          chainType: 'Command-Military-Unit Chain',
          nodes: [
            headNpc ? `person:${headNpc.id}` : `state:${stateId}`,
            topMil ? `person:${topMil.id}` : null,
            `army:ARMY_${stateId}_1`,
            `unit:UNIT_${stateId}_1`
          ].filter(Boolean),
          summary: `${headNpc ? headNpc.name : st.shortName} ➔ ผบ.กองทัพ (${topMil ? topMil.name : '-'}) ➔ กองทัพที่ 1 ➔ หน่วยกำลังรบหลัก (ความภักดีกองทัพ ${st.militaryLoyalty ?? 80}%)`
        },
        ...(foreignIntelOps.length > 0
          ? [{
              chainType: 'Cross-Border Intelligence-Opposition Chain',
              nodes: [
                `state:${foreignIntelOps[0].sponsorStateId}`,
                `intelop:${foreignIntelOps[0].id}`,
                rival ? `person:${rival.id}` : `state:${stateId}`
              ],
              summary: `รัฐบาล ${foreignIntelOps[0].sponsorStateId} ➔ ข่าวกรอง (${foreignIntelOps[0].label}) ➔ ${rival ? rival.name : 'เครือข่ายฝ่ายค้าน'} ➔ แรงกดดันทางการเมืองใน ${st.shortName}`
            }]
          : [])
      ]
    };

    if (!world.powerNetworks) world.powerNetworks = {};
    world.powerNetworks[stateId] = net;
    return net;
  }

  // Emergent Power when a General wins wars/battles (Section 3.6)
  function recordGeneralVictoryEmergence(world, cmdNpc, battle, war) {
    if (!cmdNpc || !cmdNpc.alive) return;
    const st = world.states[cmdNpc.stateId];
    if (!st) return;

    cmdNpc.victories = (cmdNpc.victories || 0) + 1;
    cmdNpc.reputation = clamp((cmdNpc.reputation || 65) + 5, 10, 99);
    cmdNpc.troopsLoyal = clamp((cmdNpc.troopsLoyal || 72) + 4, 10, 99);
    cmdNpc.officersLoyal = clamp((cmdNpc.officersLoyal || 70) + 4, 10, 99);
    cmdNpc._powerDirty = true;
    ensureNPCPowerModelV200(world, cmdNpc);
    recordNPCMemory20(cmdNpc, world.year, 'victory', `นำทัพคว้าชัยชนะใน ${battle ? battle.name : 'สมรภูมิสำคัญ'} (ชัยชนะสะสม ${cmdNpc.victories} ครั้ง)`, 85, null);

    // If general wins multiple battles (victories >= 2), emergent power chain triggers!
    if (cmdNpc.victories >= 2) {
      if (st.politicalPressures) {
        st.politicalPressures.militaryInfluence = clamp(rnd1((st.politicalPressures.militaryInfluence || 40) + 4.5), 15, 98);
      }
      // Politicians approach the victorious general
      const politicians = Object.values(world.npcs).filter((n) => n.alive && n.stateId === st.id && n.track === 'political' && n.id !== cmdNpc.id);
      if (politicians.length > 0) {
        const pol = politicians[0];
        addOrUpdateNPCRelationship(world, pol, cmdNpc, 'politicalPartner', 74, 'เข้าหาแม่ทัพผู้มีชัยชนะเพื่อสร้างพันธมิตรทางการเมือง', false);
      }
      // Rival generals start opposing out of jealousy/balance
      const otherGenerals = Object.values(world.npcs).filter((n) => n.alive && n.stateId === st.id && n.track === 'military' && n.id !== cmdNpc.id && n.stage >= 5);
      if (otherGenerals.length > 0) {
        const rivGen = otherGenerals[0];
        addOrUpdateNPCRelationship(world, rivGen, cmdNpc, 'rival', -62, 'ระแวงอิทธิพลทางทหารและชื่อเสียงที่พุ่งสูงเกินไป', false);
      }
      // Military faction power rises
      const milFac = (st.factions || []).find((f) => f.type === 'Military' || f.id.includes('MILITARY'));
      if (milFac) {
        milFac.leaderNpcId = cmdNpc.id;
        milFac.influence = clamp((milFac.influence || 28) + 5, 10, 85);
        milFac.power = milFac.influence;
        milFac.publicSupport = clamp((milFac.publicSupport || 50) + 6, 10, 95);
      }
      // Government becomes cautious / nervous; foreign powers may attempt secret contact if general is ambitious
      const head = st.positions?.HEAD_OF_STATE ? world.npcs[st.positions.HEAD_OF_STATE] : null;
      if (head && head.id !== cmdNpc.id && cmdNpc.realInfluence >= head.realInfluence - 5) {
        addOrUpdateNPCRelationship(world, head, cmdNpc, 'suspectedEnemy', -45, 'รัฐบาลเริ่มระแวงแม่ทัพที่มีบารมีเหนือกองทัพและประชาชน', true);
        recordStoryHighlight(
          world,
          'RISING_GENERAL',
          `🎖️⚡ [มหาขุนพลผงาดท้าทายอำนาจรัฐ] ${cmdNpc.name} (${st.shortName}) ชนะศึกต่อเนื่องจนมีอำนาจจริง (Real Power ${cmdNpc.realInfluence}) เทียบเท่าผู้นำรัฐบาล นักการเมืองแห่เข้าหา ขณะที่นายพลคู่แข่งและทำเนียบรัฐบาลเริ่มระแวง!`,
          st.id,
          { personId: cmdNpc.id, warId: war?.id }
        );
      }
    }
  }

  function addOrUpdateNPCRelationship(world, npcA, npcB, type, strength, reason, hidden = false) {
    if (!npcA || !npcB || npcA.id === npcB.id) return;
    if (!Array.isArray(npcA.relationships)) npcA.relationships = [];
    let rel = npcA.relationships.find((r) => r.targetId === npcB.id);
    const isPos = strength >= 0 && !['rival', 'enemy', 'suspectedEnemy'].includes(type);
    if (!rel) {
      rel = {
        targetId: npcB.id,
        type,
        strength,
        trust: isPos ? 72 : 25,
        loyalty: isPos ? 70 : 15,
        reciprocity: isPos ? 75 : 20,
        lastInteraction: world.tick || 0,
        reason,
        history: [`[${world.year || 2026}] ${reason}`],
        hidden: !!hidden,
        visibility: hidden ? 'hidden' : 'public'
      };
      npcA.relationships.unshift(rel);
      if (npcA.relationships.length > 14) npcA.relationships.length = 14;
    } else {
      rel.type = type;
      rel.strength = clamp(strength, -100, 100);
      rel.trust = isPos ? clamp((rel.trust || 50) + 8, 5, 99) : clamp((rel.trust || 50) - 12, 5, 99);
      rel.lastInteraction = world.tick || 0;
      rel.reason = reason;
      rel.hidden = !!hidden;
      rel.visibility = hidden ? 'hidden' : 'public';
      if (!Array.isArray(rel.history)) rel.history = [];
      rel.history.unshift(`[${world.year || 2026}] ${reason}`);
      if (rel.history.length > 6) rel.history.length = 6;
    }
    npcA._powerDirty = true;
  }

  // Importance-Scored Memory System (Section 44)
  function recordNPCMemory20(npc, year, eventType, text, importance = 65, relatedEntityUri = null) {
    if (!npc) return;
    if (!Array.isArray(npc.memories)) npc.memories = [];
    npc.memories.unshift({
      year: year || 2026,
      type: eventType || 'event',
      text,
      importance: clamp(importance, 10, 100),
      relatedUri: relatedEntityUri
    });
    // Sort by importance + recency so high-importance memories (betrayal, victory, assassination_attempt, broken_treaty) are kept
    if (npc.memories.length > 12) {
      npc.memories.sort((a, b) => ((b.importance || 50) + (b.year || 2026) * 0.5) - ((a.importance || 50) + (a.year || 2026) * 0.5));
      npc.memories.length = 10;
    }
  }

  // Non-Omniscient Perception Model (Section 43: trueState vs knownState vs estimatedState vs suspectedState)
  function getNonOmniscientAssessment(world, observerStateId, targetStateId) {
    const obs = world.states[observerStateId];
    const tgt = world.states[targetStateId];
    if (!obs || !tgt) return null;

    const truePot = calculateStateCombatPotential(world, targetStateId);
    const spyNet = getOrInitSpyNetwork(world, observerStateId, targetStateId);
    const satBonus = obs.spaceProgram?.intelBonusPct || 6;
    const rel = obs.relations?.[targetStateId] || {};
    const intelShareBonus = (rel.intelSharing || 20) * 0.2;
    const counterIntelPenalty = (tgt.counterIntelLevel || 60) * 0.35;

    // Intel quality (0 to 100) determines how small the uncertainty band is
    const intelQuality = clamp(Math.round(35 + spyNet.networkStrength * 0.45 + satBonus + intelShareBonus - counterIntelPenalty), 15, 96);
    const uncertaintyPct = clamp(100 - intelQuality, 4, 85);

    // Deterministic pseudo-noise so estimate is not omniscient!
    const noiseSeed = hashStr(`${observerStateId}_${targetStateId}_${Math.floor((world.tick || 0) / 15)}`);
    const noiseFactor = 1 + (((noiseSeed % 200) - 100) / 100) * (uncertaintyPct / 140);

    const targetCamps = Object.values(world.camps).filter((c) => c.stateId === targetStateId);
    const targetUnits = Object.values(world.militaryUnits || {}).filter((u) => u.stateId === targetStateId);
    const knownUnitCount = Math.max(1, Math.round(targetUnits.length * (intelQuality / 100)));
    const suspectedUnitCount = Math.max(0, Math.round((targetUnits.length - knownUnitCount) * 0.7));
    const unknownUnitCount = Math.max(0, targetUnits.length - knownUnitCount - suspectedUnitCount);

    return {
      observerStateId,
      targetStateId,
      intelQuality,
      uncertaintyPct,
      knownState: {
        confirmedUnits: targetUnits.slice(0, knownUnitCount).map((u) => u.id),
        confirmedBases: targetCamps.slice(0, Math.max(1, Math.round(targetCamps.length * (intelQuality / 100)))).map((c) => c.id),
        regimeCategory: tgt.regimeCategory,
        knownAllies: alliesOf(world, targetStateId)
      },
      estimatedState: {
        estimatedTotalPower: Math.round(truePot.totalPower * noiseFactor),
        estimatedLandPower: Math.round(truePot.landPower * noiseFactor),
        estimatedAirPower: Math.round(truePot.airPower * noiseFactor),
        estimatedNavalPower: Math.round(truePot.navalPower * noiseFactor),
        estimatedReadiness: clamp(Math.round((tgt.militaryReadiness?.overallScore || 80) * noiseFactor), 20, 100),
        estimatedMorale: clamp(Math.round((tgt.militaryReadiness?.morale || 80) * noiseFactor), 20, 100),
        estimatedSupply: clamp(Math.round((truePot.supplyReadinessPct || 80) * noiseFactor), 15, 100),
        confidenceMarginPct: uncertaintyPct
      },
      suspectedState: {
        suspectedReserveUnits: suspectedUnitCount,
        unknownUnitsFog: unknownUnitCount,
        suspectedCovertOps: (world.intelligenceOps || []).filter((op) => op.sponsorStateId === targetStateId && op.targetStateId === observerStateId && (op.detected || intelQuality >= 72)).map((op) => op.id),
        suspectedNuclearCapability: (tgt.nuclear?.warheads || 0) > 0 || (tgt.nuclear?.progress || 0) >= 60
      },
      // Internal reference for Debug/Observer comparison ONLY (AI decisions MUST use estimatedState!)
      _debugTrueState: {
        trueTotalPower: truePot.totalPower,
        trueUnitsCount: targetUnits.length,
        trueReadiness: tgt.militaryReadiness?.overallScore || 85
      }
    };
  }

  // Succession & Replacement Handler for all 7 removal causes (Section 5: death, retire, dismissed, arrested, exiled, resigned, overthrown)
  function handleNPCSuccession(world, npc, causeType = 'resigned', reasonText = '') {
    if (!npc) return { ok: false };
    const st = world.states[npc.stateId];
    const oldPosId = npc.positionId;
    const oldTitle = npc.positionTitle;
    const oldNodeId = npc.assignedNodeId;

    if (causeType === 'death') {
      handleNPCDeath(world, npc, reasonText || 'เสียชีวิตในระหว่างดำรงตำแหน่ง');
    } else if (causeType === 'retired') {
      retireNPC(world, npc);
    } else {
      // dismissed, arrested, exiled, resigned, overthrown
      unassignNPCFromPosts(world, npc);
      npc.statusState = causeType;
      if (causeType === 'arrested' || causeType === 'exiled') {
        npc.retired = true;
      }
      npc.positionId = 'SENIOR_OFFICIAL';
      npc.positionTitle = causeType === 'arrested' ? 'ถูกควบคุมตัวทางการเมือง (Detained)' : causeType === 'exiled' ? 'ลี้ภัยทางการเมือง (In Exile)' : 'อดีตผู้ดำรงตำแหน่ง (Former Official)';
      npc.authority = 20;
      npc._powerDirty = true;
      recordNPCMemory20(npc, world.year, 'demotion', `พ้นจากตำแหน่ง ${oldTitle} (${causeType}: ${reasonText})`, 90, null);
    }

    // Immediate candidate selection based on competence, seniority, faction, loyalty, relationships, ideology, reputation, institutional fit
    let successor = null;
    if (st && !st.isExiled && oldPosId && oldPosId !== 'RETIRED') {
      successor = selectBestCandidateForRole(world, st.id, oldPosId, oldNodeId);
      if (successor) {
        promoteNPC(world, successor, oldPosId, oldNodeId);
        if (st.positions && st.positions[oldPosId] !== undefined) {
          st.positions[oldPosId] = successor.id;
        }
        if (oldNodeId) {
          if (world.cities[oldNodeId] && oldPosId === 'CITY_GOVERNOR') world.cities[oldNodeId].governorId = successor.id;
          if (world.camps[oldNodeId] && oldPosId === 'BASE_COMMANDER') world.camps[oldNodeId].commanderId = successor.id;
          if (world.carriers[oldNodeId] && oldPosId === 'CARRIER_ADMIRAL') world.carriers[oldNodeId].commanderId = successor.id;
          const co = (world.companies || []).find((c) => c.id === oldNodeId);
          if (co && oldPosId === 'CEO_DIRECTOR') co.ceoId = successor.id;
        }
        ensureNPCPowerModelV200(world, successor);
        recordNPCMemory20(successor, world.year, 'promotion', `ได้รับแต่งตั้งสืบทอดตำแหน่ง ${oldTitle} แทนที่ ${npc.name}`, 85, `person:${npc.id}`);
        addChronicle(
          world,
          'PERSON',
          `🔄👤 [การสืบทอดตำแหน่ง — Succession] ${successor.name} (Competence ${successor.competence}, Faction ${successor.faction}) ขึ้นดำรงตำแหน่ง ${oldTitle} แห่ง ${st.shortName} แทนที่ ${npc.name} (${causeType})`,
          st.id,
          { personId: successor.id }
        );
      }
    }
    if (st) analyzeStatePowerNetwork(world, st.id);
    return { ok: true, removedNpc: npc, successor };
  }

  // Role-Based NPC Decision Engine 2.0 (Section 42: Politician, General, Diplomat, Intelligence Chief)
  function evaluateNPCDecision20(world, npc, rng) {
    if (!npc || !npc.alive || npc.retired) return null;
    const st = world.states[npc.stateId];
    if (!st || st.isExiled) return null;
    ensureNPCPowerModelV200(world, npc);

    const role = npc.formalPosition;
    const isAtWar = getWarsOf(world, st.id).length > 0;
    const pp = st.politicalPressures || {};
    let chosenAction = null;
    let whyReason = '';

    if (['President', 'Prime Minister', 'Minister', 'Party Leader', 'Opposition Leader'].includes(role)) {
      // Politician actions: negotiate, recruit_ally, attack_rival, compromise, campaign, reform, suppress, resign
      if (role === 'Opposition Leader') {
        if ((pp.publicUnrest || 20) > 45 || st.approval < 55) {
          chosenAction = 'attack_rival';
          whyReason = `คะแนนนิยมรัฐบาลลดลง (${st.approval}%) และมีแรงกดดันประชาชน จึงเปิดอภิปรายโจมตีฝ่ายรัฐบาลเพื่อชิงความได้เปรียบ`;
          st.oppositionPressure = clamp(rnd1((st.oppositionPressure || 35) + 3.5), 10, 98);
        } else {
          chosenAction = 'campaign';
          whyReason = `ลงพื้นที่รณรงค์นโยบายของฝ่ายค้านเพื่อขยายฐานเสียง (${npc.publicSupport}%)`;
          npc.publicSupport = clamp((npc.publicSupport || 55) + 2, 10, 99);
        }
      } else if (st.stability < 42 && ['Authoritarian', 'One_Party', 'Military_Junta'].includes(st.regimeCategory) && (npc.riskTolerance || 50) > 55) {
        chosenAction = 'suppress';
        whyReason = `เสถียรภาพรัฐต่ำ (${st.stability}%) ในระบอบอำนาจนิยม จึงเลือกใช้มาตรการปราบปรามเพื่อควบคุมสถานการณ์`;
        executeAuthoritarianAction(world, st.id, 'intimidate', { silent: true });
      } else if ((pp.economicPressure || 25) > 50) {
        chosenAction = 'reform';
        whyReason = `แรงกดดันทางเศรษฐกิจสูง (${pp.economicPressure}%) จึงผลักดันการปฏิรูปเศรษฐกิจและลดความตึงเครียดภายใน`;
        st.stability = clamp(rnd1(st.stability + 1.5), 10, 99);
        pp.economicPressure = clamp(rnd1(pp.economicPressure - 2.5), 5, 98);
      } else if ((st.coalitionStability || 70) < 55) {
        chosenAction = 'compromise';
        whyReason = `เสถียรภาพพรรคร่วมรัฐบาลลดลง (${st.coalitionStability || 70}%) จึงเจรจาประนีประนอมแบ่งสรรผลประโยชน์กับกลุ่มการเมือง`;
        st.coalitionStability = clamp(rnd1((st.coalitionStability || 65) + 4), 15, 99);
      } else {
        chosenAction = 'recruit_ally';
        whyReason = `ใช้บารมีทางการเมือง (Political Power ${npc.politicalPower}) ดึงตัวชนชั้นนำและกลุ่มทุนเข้าร่วมเครือข่าย`;
        npc.networkPower = clamp((npc.networkPower || 55) + 2, 10, 99);
      }
    } else if (role === 'General' || role === 'Chief of Staff') {
      // General actions: attack, defend, redeploy, request_supply, request_reinforcement, train, lobby_government
      const lowSupplyCamp = Object.values(world.camps).find((c) => c.stateId === st.id && (c.daysOfSupply || 25) < 15);
      if (lowSupplyCamp) {
        chosenAction = 'request_supply';
        whyReason = `ตรวจพบฐานทัพ ${lowSupplyCamp.name} มีเสบียงเหลือเพียง ${lowSupplyCamp.daysOfSupply} วัน จึงเร่งขอขบวนส่งกำลังบำรุงด่วน`;
        st.logisticsDirty = true;
      } else if (isAtWar) {
        const war = getWarsOf(world, st.id)[0];
        const enemyId = war.attackerId === st.id ? war.defenderId : war.attackerId;
        const intel = getNonOmniscientAssessment(world, st.id, enemyId);
        const myPot = calculateStateCombatPotential(world, st.id);
        const estRatio = myPot.totalPower / Math.max(200, intel?.estimatedState?.estimatedTotalPower || 1000);
        if (estRatio >= 0.95) {
          chosenAction = 'attack';
          whyReason = `ประเมินข่าวกรองข้าศึก (${enemyId}) คาดว่ากำลังรบได้เปรียบ (Ratio ${estRatio.toFixed(2)}, ความคลาดเคลื่อน ±${intel?.uncertaintyPct}%) จึงสั่งรุกแนวหน้า`;
        } else {
          chosenAction = 'defend';
          whyReason = `ข่าวกรองประเมินว่าข้าศึก (${enemyId}) มีกำลังเหนือกว่า จึงสั่งตั้งรับเชิงลึกและขอเสริมกำลัง`;
        }
      } else if ((st.budgetAllocation?.military || 0.28) < 0.26 && (npc.militaryInfluence || 50) > 65) {
        chosenAction = 'lobby_government';
        whyReason = `งบกลาโหมต่ำกว่าเกณฑ์ จึงใช้อิทธิพลกองทัพ (${npc.militaryInfluence}) กดดันรัฐบาลให้เพิ่มงบประมาณและความพร้อมรบ`;
        if (st.budgetAllocation) st.budgetAllocation.military = +(Math.min(0.42, st.budgetAllocation.military + 0.02)).toFixed(2);
      } else {
        chosenAction = 'train';
        whyReason = `จัดฝึกซ้อมรบยกระดับความพร้อมรบและประสบการณ์ของหน่วยทหารใต้บังคับบัญชา`;
        if (st.militaryReadiness) st.militaryReadiness.training = clamp((st.militaryReadiness.training || 80) + 1, 30, 99);
      }
    } else if (role === 'Diplomat') {
      // Diplomat actions: negotiate, threaten, mediate, seek_alliance, seek_aid
      const rivals = st.rivalries || [];
      if (isAtWar && st.treasuryB < 80) {
        chosenAction = 'seek_aid';
        whyReason = `ประเทศอยู่ในภาวะสงครามและงบคงคลังตึงตัว ($${st.treasuryB}B) จึงเจรจาขอความช่วยเหลือจากพันธมิตร`;
      } else if (rivals.length > 0 && (st.militaryReadiness?.overallScore || 80) < 75) {
        chosenAction = 'seek_alliance';
        whyReason = `เผชิญภัยคุกคามจากคู่ขัดแย้ง (${rivals.join(', ')}) จึงเดินสายแสวงหาพันธมิตรความมั่นคงร่วม`;
      } else {
        chosenAction = 'negotiate';
        whyReason = `เจรจาขยายความตกลงทางการค้าและลดความตึงเครียดตามแนวพรมแดน (Diplomatic Ability ${npc.diplomaticAbility})`;
      }
    } else if (role === 'Intelligence Chief') {
      // Intelligence chief actions: investigate, infiltrate, monitor, recruit_asset, counterspy
      const suspectedForeignOps = (world.intelligenceOps || []).filter((op) => op.targetStateId === st.id && op.active);
      if (suspectedForeignOps.length > 0) {
        chosenAction = 'counterspy';
        whyReason = `ตรวจพบสัญญาณการแทรกแซงจากต่างชาติ จึงสั่งปฏิบัติการต่อต้านข่าวกรอง (Counterintelligence)`;
        st.counterIntelLevel = clamp((st.counterIntelLevel || 65) + 3, 20, 98);
      } else if ((st.rivalries || []).length > 0) {
        chosenAction = 'infiltrate';
        whyReason = `ส่งสายลับและรวบรวมข่าวกรองในประเทศคู่แข่ง (${st.rivalries[0]}) เพื่อลด Fog of War`;
      } else {
        chosenAction = 'monitor';
        whyReason = `เฝ้าระวังความมั่นคงภายในและตรวจสอบเครือข่ายต่อต้านรัฐบาล`;
      }
    } else {
      chosenAction = 'administer';
      whyReason = `บริหารหน่วยงานในความรับผิดชอบตามขีดความสามารถ (Competence ${npc.competence})`;
    }

    npc.lastDecisionAction = chosenAction;
    npc.lastDecisionReason = whyReason;
    npc.lastDecisionText = `[${chosenAction}] ${whyReason}`;
    return { action: chosenAction, reason: whyReason };
  }

  // -------------------------------------------------------------------------
  // 2. POLITICAL SIMULATION 2.0 (Factions, Stability, Dictatorship/Democracy, Crises, Foreign Influence)
  // -------------------------------------------------------------------------
  function ensurePoliticalSimulationV200(world, st) {
    if (!st) return;
    ensureStateDeepProfileV170(world, st);
    const isAuth = ['Authoritarian', 'One_Party', 'Military_Junta'].includes(st.regimeCategory);

    // Enrich Factions with all 13 required attributes (Sections 6 & 7)
    if (!Array.isArray(st.factions) || st.factions.length === 0) {
      const ecoTemplate = COUNTRY_FACTION_ECOSYSTEMS[st.regimeCategory] || COUNTRY_FACTION_ECOSYSTEMS.Democracy;
      st.factions = ecoTemplate.map((f) => ({ ...f, influence: f.baseInfluence }));
    }

    // Add contextual extra factions (Bureaucracy, Nationalist, Underground Resistance / Separatist where appropriate)
    const hasBureaucracy = st.factions.some((f) => f.id === 'BUREAUCRACY_FACTION' || f.type === 'Bureaucracy');
    if (!hasBureaucracy) {
      st.factions.push({
        id: 'BUREAUCRACY_FACTION',
        name: 'ข้าราชการประจำและเทคโนแครตกระทรวงหลัก (Civil Service & Technocratic Bureaucracy)',
        type: 'Bureaucracy',
        influence: 14
      });
    }
    if (isAuth && !st.factions.some((f) => f.type === 'Underground')) {
      st.factions.push({
        id: 'UNDERGROUND_RESISTANCE',
        name: 'ขบวนการต่อต้านใต้ดินและกลุ่มผู้ลี้ภัย (Underground Resistance & Dissidents)',
        type: 'Underground',
        influence: st.id === 'MM' ? 24 : 11
      });
    }

    const needNpcScan = st.factions.some((f) => !f.leaderNpcId || !world.npcs[f.leaderNpcId] || f.membership === undefined);
    const stNpcs = needNpcScan ? Object.values(world.npcs).filter((n) => n.alive && n.stateId === st.id) : [];
    st.factions.forEach((f, idx) => {
      if (f.power === undefined) f.power = f.influence ?? 20;
      f.influence = f.power;
      if (!f.leaderNpcId || !world.npcs[f.leaderNpcId]) {
        const match = stNpcs.find((n) =>
          (f.type === 'Military' && n.track === 'military') ||
          (f.type === 'Business' && n.track === 'business') ||
          (f.type === 'Opposition' && n.positionId === 'OPPOSITION_LEADER') ||
          (f.type === 'Government' && (n.positionId === 'HEAD_OF_STATE' || n.positionId === 'PRIME_MINISTER'))
        ) || stNpcs[idx % Math.max(1, stNpcs.length)];
        if (match) f.leaderNpcId = match.id;
      }
      f.leader = f.leaderNpcId;
      if (f.membership === undefined) {
        f.membership = Math.max(3, stNpcs.filter((n) => n.faction === f.name || n.faction === f.type).length);
      }
      if (!f.ideology) {
        f.ideology = f.type === 'Military' ? 'Security Nationalism' : f.type === 'Business' ? 'Market Corporatism' : f.type === 'Opposition' ? 'Democratic Reformism' : f.type === 'Underground' ? 'Anti-Regime Liberation' : 'Pragmatic Governance';
      }
      if (f.funding === undefined) {
        f.funding = f.type === 'Business' ? rnd1(st.gdpB * 0.015) : f.type === 'Government' ? rnd1(st.treasuryB * 0.08) : rnd1(st.gdpB * 0.005);
      }
      if (f.publicSupport === undefined) {
        f.publicSupport = f.type === 'Government' ? st.approval : f.type === 'Opposition' ? clamp(100 - st.approval, 15, 85) : 52;
      }
      if (f.institutionalSupport === undefined) {
        f.institutionalSupport = f.type === 'Government' || f.type === 'Bureaucracy' ? 76 : f.type === 'Military' ? 70 : 35;
      }
      if (f.militarySupport === undefined) {
        f.militarySupport = f.type === 'Military' ? 88 : f.type === 'Government' ? 68 : 20;
      }
      if (f.foreignSupport === undefined) {
        f.foreignSupport = f.type === 'Underground' || f.type === 'Opposition' ? (st.underground?.secretFundingB ? 35 : 10) : 15;
      }
      if (f.cohesion === undefined) f.cohesion = 78;
      if (f.radicalism === undefined) f.radicalism = f.type === 'Underground' ? 72 : f.type === 'Military' ? 45 : 25;
      if (!Array.isArray(f.objectives)) {
        f.objectives = f.type === 'Government'
          ? ['รักษาเสถียรภาพรัฐบาล', 'ผลักดันงบประมาณยุทธศาสตร์']
          : f.type === 'Military'
          ? ['เพิ่มงบกลาโหมและความพร้อมรบ', 'ขยายบทบาทความมั่นคงแห่งชาติ']
          : f.type === 'Business'
          ? ['ลดภาษีนิติบุคคลและขยายสัมปทานรัฐ', 'คุ้มครองเส้นทางการค้า']
          : ['ตรวจสอบรัฐบาลและผลักดันการปฏิรูปการเมือง'];
      }
      if (!Array.isArray(f.grievances)) {
        f.grievances = f.satisfaction < 50 ? ['ไม่พอใจการจัดสรรงบประมาณและนโยบายรัฐปัจจุบัน'] : [];
      }
      f.whyPowerBreakdown = [
        `อิทธิพลรวม (Power ${f.power}): สมาชิก ${f.membership} คน • ทุนสนับสนุน $${f.funding}B • แรงหนุนประชาชน ${f.publicSupport}% • แรงหนุนสถาบัน ${f.institutionalSupport}% • แรงหนุนกองทัพ ${f.militarySupport}% • ต่างชาติหนุน ${f.foreignSupport}%`
      ];
    });

    // Section 8: Government Stability 9-Metric Model
    const pp = st.politicalPressures || {};
    if (st.governmentStability === undefined) st.governmentStability = st.stability ?? 78;
    if (st.coalitionStability === undefined) st.coalitionStability = st.democracyState?.coalitionStability ?? clamp(st.stability + 3, 25, 98);
    if (st.militaryLoyalty === undefined) st.militaryLoyalty = clamp(100 - (pp.militaryInfluence || 35) * 0.35, 25, 98);
    if (st.bureaucraticCompliance === undefined) st.bureaucraticCompliance = clamp(Math.round(st.stability * 0.6 + 32 - (st.adminBurden || 8) * 0.4), 25, 98);
    if (st.publicApproval === undefined) st.publicApproval = st.approval ?? 72;
    if (st.oppositionPressure === undefined) st.oppositionPressure = pp.oppositionStrength ?? clamp(100 - st.approval, 10, 92);
    if (st.eliteSupport === undefined) st.eliteSupport = pp.eliteSupport ?? 74;
    if (st.economicPressure === undefined) st.economicPressure = pp.economicPressure ?? 22;
    if (st.legitimacy === undefined) st.legitimacy = clamp(Math.round(st.stability * 0.5 + st.approval * 0.35 + 15), 15, 99);

    // Section 9: Dictatorship / Authoritarian Politics (8 Opposition forms & suppression backfire)
    if (!st.authoritarianOpposition) {
      st.authoritarianOpposition = {
        undergroundOpposition: isAuth ? (st.underground?.dissidentNetwork || 28) : 8,
        exileGroups: st.politicalExile?.active ? 65 : (isAuth ? 24 : 5),
        dissidents: isAuth ? 32 : 10,
        militaryConspirators: isAuth ? (st.underground?.militaryPlotLevel || 18) : 6,
        intellectualOpposition: isAuth ? 30 : 18,
        regionalResistance: st.id === 'MM' ? 75 : (isAuth ? 25 : 12),
        laborResistance: clamp(Math.round((st.economicPressure || 20) * 0.7), 8, 85),
        foreignBackedOpposition: st.underground?.foreignSponsorId ? 55 : 12,
        fearLevel: isAuth ? 62 : 18,
        suppressionIntensity: isAuth ? 58 : 15,
        foreignCriticism: isAuth ? 42 : 10,
        sanctionsRisk: (st.sanctionedBy || []).length * 20 + (isAuth ? 25 : 5),
        lastRegimeAction: isAuth ? 'monitor' : 'negotiate'
      };
    }

    // Section 56 Creative Autonomy Political Subsystems
    if (!st.politicalSubsystems) {
      st.politicalSubsystems = {
        politicalFundingB: rnd1(st.gdpB * 0.008),
        lobbyingIntensity: 48,
        propagandaLevel: st.informationOps?.mediaControl || 45,
        mediaInfluence: 65,
        patronageNetwork: isAuth ? 72 : 42,
        activeCrises: []
      };
    }
  }

  // Authoritarian Regime Actions with Over-Suppression Side Effects (Section 9)
  function executeAuthoritarianAction(world, stateId, actionType = 'monitor', opts = {}) {
    const st = world.states[stateId];
    if (!st) return { ok: false, reason: 'State not found' };
    ensurePoliticalSimulationV200(world, st);
    const ao = st.authoritarianOpposition;
    ao.lastRegimeAction = actionType;

    let narrative = '';
    if (['arrest', 'censor', 'intimidate', 'eliminate_leadership'].includes(actionType)) {
      const severity = actionType === 'eliminate_leadership' ? 18 : actionType === 'arrest' ? 12 : 8;
      ao.suppressionIntensity = clamp(ao.suppressionIntensity + severity, 10, 99);
      ao.fearLevel = clamp(ao.fearLevel + severity * 0.9, 10, 99);
      ao.dissidents = clamp(ao.dissidents - severity * 0.5, 5, 95);

      // Over-suppression backfire (Section 9: fear ↑ -> legitimacy ↓ -> underground resistance ↑ -> foreign criticism ↑ -> sanctions risk ↑)
      if (ao.suppressionIntensity >= 62) {
        st.legitimacy = clamp(rnd1(st.legitimacy - severity * 0.55), 10, 99);
        ao.undergroundOpposition = clamp(rnd1(ao.undergroundOpposition + severity * 0.65), 10, 99);
        ao.foreignCriticism = clamp(rnd1(ao.foreignCriticism + severity * 0.7), 5, 99);
        ao.sanctionsRisk = clamp(rnd1(ao.sanctionsRisk + severity * 0.6), 5, 99);
        if (st.underground) st.underground.dissidentNetwork = ao.undergroundOpposition;
        narrative = `🚨⛓️ [ผลตีกลับจากการปราบปราม — Suppression Backfire] รัฐบาล ${st.name} ใช้มาตรการ [${actionType}] อย่างรุนแรง ส่งผลให้ความกลัวพุ่งสู่ ${ao.fearLevel}% แต่ความชอบธรรมลดลงเหลือ ${st.legitimacy}% ขบวนการต่อต้านใต้ดินขยายตัวเป็น ${ao.undergroundOpposition}% และเสี่ยงถูกคว่ำบาตร (${ao.sanctionsRisk}%)!`;
      } else {
        st.stability = clamp(rnd1(st.stability + 2.5), 10, 99);
        narrative = `🛡️🔒 [มาตรการควบคุมความมั่นคงภายใน] รัฐบาล ${st.name} ดำเนินมาตรการ [${actionType}] สกัดกั้นกลุ่มต่อต้าน (Fear ${ao.fearLevel}%)`;
      }
    } else if (actionType === 'negotiate' || actionType === 'reform' || actionType === 'co_opt_opposition') {
      ao.suppressionIntensity = clamp(ao.suppressionIntensity - 8, 5, 95);
      ao.fearLevel = clamp(ao.fearLevel - 6, 5, 95);
      ao.undergroundOpposition = clamp(ao.undergroundOpposition - 7, 5, 95);
      st.legitimacy = clamp(rnd1(st.legitimacy + 5), 10, 99);
      st.stability = clamp(rnd1(st.stability + 3), 10, 99);
      narrative = `🕊️🏛️ [การผ่อนปรนและดึงแนวร่วมทางการเมือง] รัฐบาล ${st.name} เลือกแนวทาง [${actionType}] ลดแรงต้านใต้ดินเหลือ ${ao.undergroundOpposition}% และฟื้นฟูความชอบธรรมสู่ ${st.legitimacy}%`;
    } else {
      // monitor / infiltrate
      ao.militaryConspirators = clamp(ao.militaryConspirators - 4, 4, 95);
      narrative = `👁️📡 [การเฝ้าระวังและแทรกซึมเครือข่ายต่อต้าน] หน่วยความมั่นคง ${st.shortName} เฝ้าติดตามกลุ่มผู้เห็นต่างและสกัดแผนสมคบคิดในกองทัพ`;
    }

    if (!opts.silent) {
      addChronicle(world, 'POLITICAL', narrative, st.id);
    }
    return { ok: true, actionType, authoritarianOpposition: ao, narrative };
  }

  // Condition-Driven Political Crisis Engine (Section 11: 12 Crisis Types)
  function evaluatePoliticalCrisesV200(world, st, rng) {
    if (!st || st.isExiled) return null;
    ensurePoliticalSimulationV200(world, st);
    const isAuth = ['Authoritarian', 'One_Party', 'Military_Junta'].includes(st.regimeCategory);
    let crisisType = null;
    let crisisTitle = '';
    let crisisDesc = '';

    // Evaluate deterministic conditions first
    if (st.militaryLoyalty < 52 && (st.politicalPressures?.militaryInfluence || 40) > 58 && st.stability < 60) {
      crisisType = 'military_intervention';
      crisisTitle = 'วิกฤตทหารแทรกแซงการเมืองและยื่นคำขาดต่อรัฐบาล (Military Intervention)';
      crisisDesc = `กองทัพมีความภักดีต่อรัฐบาลเพียง ${st.militaryLoyalty}% ขณะที่อิทธิพลทหารสูงถึง ${st.politicalPressures?.militaryInfluence}% ผู้นำกองทัพจึงกดดันรัฐบาลโดยตรง`;
      st.stability = clamp(rnd1(st.stability - 5), 10, 99);
    } else if (!isAuth && st.coalitionStability < 38) {
      crisisType = 'coalition_collapse';
      crisisTitle = 'วิกฤตพรรคร่วมรัฐบาลถอนตัวและรัฐบาลผสมล่ม (Coalition Collapse)';
      crisisDesc = `เสถียรภาพพรรคร่วมรัฐบาลลดต่ำถึง ${st.coalitionStability}% ทำให้พรรคร่วมถอนตัวและต้องจัดตั้งรัฐบาลใหม่`;
      holdParliamentSession(world, st.id, 'no_confidence');
      st.coalitionStability = 58;
    } else if (!isAuth && st.oppositionPressure > 68 && st.publicApproval < 45) {
      crisisType = 'vote_of_no_confidence';
      crisisTitle = 'ญัตติอภิปรายไม่ไว้วางใจนายกรัฐมนตรี (Vote of No Confidence)';
      crisisDesc = `ฝ่ายค้านรวบรวมเสียงกดดัน (${st.oppositionPressure}%) เมื่อคะแนนนิยมรัฐบาลลดเหลือ ${st.publicApproval}%`;
      holdParliamentSession(world, st.id, 'no_confidence');
    } else if (st.economicPressure > 64 && st.publicApproval < 48) {
      crisisType = 'mass_protest';
      crisisTitle = 'การชุมนุมประท้วงใหญ่ทั่วประเทศจากวิกฤตปากท้อง (Mass Protest)';
      crisisDesc = `แรงกดดันทางเศรษฐกิจพุ่งถึง ${st.economicPressure}% จุดชนวนการประท้วงใหญ่ในเมืองหลวงและเมืองเศรษฐกิจหลัก`;
      st.stability = clamp(rnd1(st.stability - 4), 10, 99);
    } else if ((st.politicalPressures?.corruptionPressure || 30) > 60) {
      crisisType = 'corruption_scandal';
      crisisTitle = 'วิกฤตข่าวอื้อฉาวทุจริตระดับรัฐมนตรี (Major Corruption Scandal)';
      crisisDesc = `การตรวจสอบพบเครือข่ายอุปถัมภ์และทุจริตงบประมาณ ส่งผลให้รัฐมนตรีต้องลาออกและรัฐบาลเสียความชอบธรรม`;
      st.legitimacy = clamp(rnd1(st.legitimacy - 5), 10, 99);
      st.politicalPressures.corruptionPressure = 38;
    } else if (st.bureaucraticCompliance < 45 && st.legitimacy < 48) {
      crisisType = 'constitutional_crisis';
      crisisTitle = 'วิกฤตการณ์รัฐธรรมนูญและอำนาจสถาบันขัดแย้ง (Constitutional Crisis)';
      crisisDesc = `ฝ่ายบริหาร นิติบัญญัติ และระบบราชการ (${st.bureaucraticCompliance}%) ขัดแย้งในการใช้อำนาจรัฐ`;
    }

    if (crisisType) {
      const rec = {
        id: `CRISIS_${st.id}_${world.tick}`,
        type: crisisType,
        title: crisisTitle,
        desc: crisisDesc,
        year: world.year,
        date: world.dateString,
        tick: world.tick
      };
      if (!st.politicalSubsystems.activeCrises) st.politicalSubsystems.activeCrises = [];
      st.politicalSubsystems.activeCrises.unshift(rec);
      if (st.politicalSubsystems.activeCrises.length > 8) st.politicalSubsystems.activeCrises.length = 8;
      st.history.unshift({ year: world.year, date: world.dateString, type: 'CRISIS', text: `${crisisTitle}: ${crisisDesc}` });
      if (st.history.length > 25) st.history.length = 25;
      addChronicle(world, 'POLITICAL', `⚠️🏛️ [${crisisTitle} — ${st.name}] ${crisisDesc}`, st.id);
      recordStoryHighlight(world, 'POLITICAL_CRISIS_' + crisisType.toUpperCase(), `⚠️🏛️ [${crisisTitle}] ใน ${st.name}: ${crisisDesc}`, st.id);
    }
    return crisisType;
  }

  // Foreign Influence on Domestic Politics (Section 12 & Section 33: Diplomacy <-> Politics Connection)
  function executeForeignPoliticalInfluence(world, sponsorStateId, targetStateId, actionType = 'support_opposition', opts = {}) {
    const sponsor = world.states[sponsorStateId];
    const target = world.states[targetStateId];
    if (!sponsor || !target || sponsorStateId === targetStateId) return { ok: false, reason: 'Invalid states' };
    ensurePoliticalSimulationV200(world, sponsor);
    ensurePoliticalSimulationV200(world, target);

    const costMap = {
      support_government: 8,
      support_opposition: 9,
      fund_factions: 7,
      provide_weapons: 12,
      provide_intelligence: 5,
      diplomatic_protection: 4,
      economic_pressure: 6,
      sanctions: 5,
      media_influence: 5,
      covert_support: 10
    };
    const costB = opts.costB ?? (costMap[actionType] || 7);
    if (sponsor.treasuryB < costB) return { ok: false, reason: `งบคงคลังของ ${sponsor.shortName} ไม่พอ ($${costB}B)` };
    sponsor.treasuryB = rnd1(sponsor.treasuryB - costB);

    const spyNet = getOrInitSpyNetwork(world, sponsorStateId, targetStateId);
    const detectChance = clamp(
      (['support_opposition', 'provide_weapons', 'covert_support', 'fund_factions'].includes(actionType) ? 0.28 : 0.10) +
      ((target.counterIntelLevel || 60) - (spyNet.networkStrength || 45)) * 0.003,
      0.05,
      0.65
    );
    const rng = new SeededRNG((world.seed || 2026) + world.tick * 131 + hashStr(sponsorStateId + targetStateId + actionType));
    const detected = opts.forceDetected !== undefined ? opts.forceDetected : rng.chance(detectChance);

    const oppFac = (target.factions || []).find((f) => f.type === 'Opposition' || f.type === 'Underground') || target.factions?.[1];
    const govFac = (target.factions || []).find((f) => f.type === 'Government') || target.factions?.[0];
    const rel = relOf(world, sponsorStateId, targetStateId);
    const revRel = relOf(world, targetStateId, sponsorStateId);

    let effectSummary = '';
    if (actionType === 'support_opposition' || actionType === 'covert_support' || actionType === 'fund_factions' || actionType === 'provide_weapons') {
      // Prompt Section 33: Country A supports Country B opposition -> opposition funding ↑ -> faction power ↑ -> government suspicion ↑ -> intelligence activity ↑ -> diplomatic tension ↑
      if (oppFac) {
        oppFac.funding = rnd1((oppFac.funding || 10) + costB * 0.8);
        oppFac.foreignSupport = clamp((oppFac.foreignSupport || 15) + 14, 5, 98);
        oppFac.power = clamp((oppFac.power || 25) + 5, 5, 85);
        oppFac.influence = oppFac.power;
      }
      if (target.underground) {
        target.underground.secretFundingB = rnd1((target.underground.secretFundingB || 0) + costB * 0.6);
        target.underground.foreignSponsorId = sponsorStateId;
      }
      if (target.authoritarianOpposition) {
        target.authoritarianOpposition.foreignBackedOpposition = clamp((target.authoritarianOpposition.foreignBackedOpposition || 15) + 12, 5, 98);
      }
      target.oppositionPressure = clamp(rnd1((target.oppositionPressure || 35) + 5), 10, 98);
      target.stability = clamp(rnd1(target.stability - 2.5), 10, 99);
      rel.intelligenceActivity = clamp((rel.intelligenceActivity || 25) + 12, 5, 99);
      revRel.intelligenceActivity = rel.intelligenceActivity;
      effectSummary = `ทุนฝ่ายค้านใน ${target.shortName} เพิ่มเป็น $${oppFac ? oppFac.funding : costB}B • อิทธิพลฝ่ายค้านเพิ่มเป็น ${oppFac ? oppFac.power : 30}% • แรงกดดันต่อรัฐบาลเพิ่มเป็น ${target.oppositionPressure}%`;
    } else if (actionType === 'support_government' || actionType === 'diplomatic_protection') {
      // Prompt Section 33: Economic/political aid -> economic influence ↑ -> pro-A faction stronger -> government relationship improves
      if (govFac) {
        govFac.funding = rnd1((govFac.funding || 20) + costB * 0.8);
        govFac.power = clamp((govFac.power || 35) + 4, 10, 88);
        govFac.influence = govFac.power;
      }
      target.treasuryB = rnd1(target.treasuryB + costB * 0.6);
      target.stability = clamp(rnd1(target.stability + 2.5), 10, 99);
      rel.score = clamp((rel.score || 55) + 8, 5, 100);
      revRel.score = rel.score;
      rel.diplomaticTrust = clamp((rel.diplomaticTrust || 55) + 8, 5, 100);
      revRel.diplomaticTrust = rel.diplomaticTrust;
      rel.economicDependency = clamp((rel.economicDependency || 25) + 6, 5, 98);
      syncDiplomaticTierV200(rel);
      syncDiplomaticTierV200(revRel);
      effectSummary = `เสริมเสถียรภาพรัฐบาล ${target.shortName} (+2.5%) และยกระดับความสัมพันธ์ทวิภาคีเป็น ${rel.score}/100 (${rel.tier20})`;
    } else if (actionType === 'sanctions' || actionType === 'economic_pressure') {
      if (!target.sanctionedBy) target.sanctionedBy = [];
      if (!target.sanctionedBy.includes(sponsorStateId)) target.sanctionedBy.push(sponsorStateId);
      target.economicPressure = clamp(rnd1((target.economicPressure || 25) + 8), 5, 99);
      rel.economicPressure = clamp((rel.economicPressure || 20) + 18, 5, 99);
      rel.score = clamp((rel.score || 50) - 12, 0, 100);
      revRel.score = rel.score;
      syncDiplomaticTierV200(rel);
      syncDiplomaticTierV200(revRel);
      effectSummary = `กดดันทางเศรษฐกิจต่อ ${target.shortName} ทำให้อัตราแรงกดดันเศรษฐกิจพุ่งเป็น ${target.economicPressure}%`;
    } else {
      // media_influence / provide_intelligence
      target.oppositionPressure = clamp(rnd1((target.oppositionPressure || 35) + 3), 10, 98);
      effectSummary = `ปฏิบัติการข่าวสารและข่าวกรองส่งผลต่อการเมืองภายในของ ${target.shortName}`;
    }

    // Section 32: Discovery & Diplomatic Fallout
    let falloutNarrative = '';
    if (detected && ['support_opposition', 'provide_weapons', 'covert_support', 'fund_factions'].includes(actionType)) {
      rel.score = clamp((rel.score || 50) - 18, 0, 100);
      revRel.score = rel.score;
      rel.diplomaticTrust = clamp((rel.diplomaticTrust || 50) - 22, 0, 100);
      revRel.diplomaticTrust = rel.diplomaticTrust;
      rel.borderTension = clamp((rel.borderTension || 20) + 16, 0, 100);
      revRel.borderTension = rel.borderTension;
      syncDiplomaticTierV200(rel);
      syncDiplomaticTierV200(revRel);
      target.counterIntelLevel = clamp((target.counterIntelLevel || 60) + 6, 20, 99);

      falloutNarrative = `🕵️‍♂️🚨 [เปิดโปงการแทรกแซงทางการเมืองข้ามชาติ!] หน่วยต่อต้านข่าวกรองของ ${target.name} ตรวจพบว่า ${sponsor.name} แอบดำเนินปฏิบัติการ [${actionType}] (${effectSummary}) — ความสัมพันธ์ทวิภาคีดิ่งลงเหลือ ${rel.score}/100 (${rel.tier20}) เกิดวิกฤตการทูตและการประท้วงอย่างรุนแรง!`;
      addChronicle(world, 'DIPLOMACY', falloutNarrative, target.id, { sponsorStateId, targetStateId });
      recordStoryHighlight(world, 'FOREIGN_INTERFERENCE_EXPOSED', falloutNarrative, target.id, { sponsorStateId, targetStateId });
    } else {
      falloutNarrative = `🌐🏛️ [อิทธิพลต่างชาติต่อการเมืองภายใน] ${sponsor.name} ดำเนินปฏิบัติการ [${actionType}] ต่อ ${target.name} (${effectSummary})`;
      if (!opts.silent) addChronicle(world, 'DIPLOMACY', falloutNarrative, sponsor.id);
    }

    return {
      ok: true,
      actionType,
      costB,
      detected,
      detectionChance: +detectChance.toFixed(2),
      effectSummary,
      narrative: falloutNarrative
    };
  }

  // -------------------------------------------------------------------------
  // 3. MILITARY WARFARE 2.0 (Hierarchy, Unit Data, Commander Effect, Objectives, Fronts, Logistics, Base Capacity, Fog of War & Intel)
  // -------------------------------------------------------------------------
  function ensureMilitaryWarfareV200(world) {
    if (!world) return;
    if (!world.militaryUnits || Object.keys(world.militaryUnits).length === 0) ensureDeepMilitaryGraphV150(world);

    // 1. State-Scaled Hierarchy (Section 14: State -> Military -> Service -> Command -> Army/Corps -> Division -> Brigade -> Battalion -> Unit)
    Object.values(world.states).forEach((st) => {
      const gdp = st.gdpB || 500;
      const scale = gdp >= 3000 ? 'Superpower Full Echelon (8 Levels: State ➔ Service ➔ Theater Command ➔ Field Army ➔ Corps ➔ Division ➔ Brigade ➔ Battalion)'
        : gdp >= 1200 ? 'Regional Power Echelon (6 Levels: State ➔ Service ➔ Command ➔ Corps/Army ➔ Division ➔ Brigade)'
        : 'Compact Defense Force (5 Levels: State ➔ Service ➔ Command ➔ Brigade ➔ Battalion)';
      st.militaryScaleProfile = scale;
      if (st.mobilizationLevel === undefined) st.mobilizationLevel = getWarsOf(world, st.id).length > 0 ? 65 : 25;
      if (st.reserveForces === undefined) st.reserveForces = Math.round((st.gdpB || 500) * 45);
      if (st.prisonersHeld === undefined) st.prisonersHeld = 0;
    });

    // 2. Enrich all Military Units (Section 15: 15 canonical unit fields)
    Object.values(world.militaryUnits || {}).forEach((u) => {
      const st = world.states[u.stateId];
      const cmd = u.commanderId ? world.npcs[u.commanderId] : null;
      if (u.personnel === undefined) u.personnel = u.troops || 10000;
      u.troops = u.personnel;
      if (!u.commander) u.commander = u.commanderId;
      if (!u.doctrine) u.doctrine = st ? st.doctrineType || 'Combined Arms' : 'Combined Arms';
      if (u.experience === undefined) u.experience = cmd ? (cmd.experience?.combatExp || 65) : 65;
      if (u.supply === undefined) u.supply = 88;
      if (u.ammunition === undefined) u.ammunition = 88;
      if (u.fuel === undefined) u.fuel = 88;
      if (u.maintenance === undefined) u.maintenance = 90;
      if (u.intelligence === undefined) u.intelligence = st?.militaryReadiness?.intelligence || 80;
      if (u.mobility === undefined) u.mobility = u.unitType?.includes('Armored') ? 88 : 78;
      if (!u.echelonLevel) {
        u.echelonLevel = (st && st.gdpB >= 2000) ? 'Division (กองพล)' : 'Brigade (กองพลน้อย/กรมผสม)';
      }
      // Recompute unit combatPower including Commander Effect & Supply Shortage Effect (Sections 15, 16, 19)
      recalculateUnitCombatPowerV200(world, u);
    });

    // 3. Enforce Base Capacity Limits & Effects (Sections 20 & 23)
    Object.values(world.camps || {}).forEach((cp) => {
      ensureCampDeepProfileV170(world, cp);
      const stUnits = Object.values(world.militaryUnits || {}).filter((u) => u.campId === cp.id).map((u) => u.id);
      cp.stationedUnits = stUnits;
      if (cp.capacity === undefined) {
        cp.capacity = cp.type === 'airbase' ? (cp.aircraftCapacity || 96) : cp.type === 'naval_base' ? (cp.berthCapacity || 28) : 35000;
      }
      if (cp.maintenance === undefined) cp.maintenance = cp.maintenanceCapacity || 90;
      if (cp.strategicImportance === undefined) cp.strategicImportance = cp.type === 'missile_base' || cp.type === 'naval_base' || cp.type === 'airbase' ? 92 : 82;

      // Check over-capacity penalty (Section 23: readiness ↓, maintenance efficiency ↓, vulnerability ↑)
      let currentLoad = cp.troops || 15000;
      let maxCap = cp.capacity || 35000;
      if (cp.type === 'airbase') {
        currentLoad = sumCategory(cp.equipment, 'aircraft');
        maxCap = cp.aircraftCapacity || 96;
      } else if (cp.type === 'naval_base') {
        currentLoad = sumCategory(cp.equipment, 'ships');
        maxCap = cp.berthCapacity || 28;
      }

      if (currentLoad > maxCap) {
        const overRatio = (currentLoad - maxCap) / Math.max(1, maxCap);
        const pen = clamp(Math.round(overRatio * 35), 4, 30);
        cp.overCapacityPenalty = pen;
        cp.readiness = clamp((cp.readiness || 90) - Math.round(pen * 0.4), 25, 100);
        cp.maintenanceEfficiency = clamp((cp.maintenanceCapacity || 90) - pen, 25, 100);
        cp.vulnerability = clamp(25 + pen * 1.5, 10, 95);
      } else {
        cp.overCapacityPenalty = 0;
        cp.maintenanceEfficiency = cp.maintenanceCapacity || 90;
        cp.vulnerability = 18;
      }
    });

    // 4. Enrich Active Wars & Fronts with Warfare 2.0 fields (Sections 17, 18, 24, 25)
    (world.wars || []).forEach((war) => {
      ensureWarMultiFrontsV200(world, war);
    });
  }

  function recalculateUnitCombatPowerV200(world, u) {
    if (!u) return 0;
    const cmd = u.commanderId ? world.npcs[u.commanderId] : null;
    if (cmd && cmd.militaryAbility === undefined) ensureNPCPowerModelV200(world, cmd);

    // Section 16: Commander Effect
    const cmdMil = cmd ? (cmd.militaryAbility || 65) : 60;
    const cmdLog = cmd ? (cmd.knowledge?.logistics || 60) : 60;
    const cmdMorale = cmd ? (cmd.charisma || 65) : 60;
    const cmdIntel = cmd ? (cmd.intelligenceAbility || 60) : 60;
    const cmdComp = cmd ? (cmd.competence || 65) : 60;

    const commanderMult = clamp(
      0.75 + (cmdMil / 100) * 0.25 + (cmdLog / 100) * 0.12 + (cmdMorale / 100) * 0.10 + (cmdIntel / 100) * 0.08 - (cmdComp < 45 ? 0.15 : 0),
      0.60,
      1.40
    );

    // Section 19: Supply Shortage Penalties
    const supAvg = ((u.supply ?? 85) + (u.ammunition ?? 85) + (u.fuel ?? 85)) / 3;
    if (supAvg < 55) {
      const shortage = (55 - supAvg) * 0.25;
      u.readiness = clamp(Math.round((u.readiness || 85) - shortage), 15, 100);
      u.mobility = clamp(Math.round((u.mobility || 80) - shortage * 1.1), 15, 100);
      u.morale = clamp(Math.round((u.morale || 80) - shortage * 0.9), 15, 100);
      u.attritionRatePct = rnd1(clamp((55 - supAvg) * 0.18, 0.5, 12));
    } else {
      u.attritionRatePct = 0.2;
    }

    const eqScore = (u.equipmentCount || 120) * 8;
    const basePower = ((u.personnel || 10000) * 0.12 + eqScore) * ((u.readiness || 85) / 100) * ((u.morale || 85) / 100) * (supAvg / 100);
    u.combatPower = Math.max(50, Math.round(basePower * commanderMult));
    u.commanderEffectSummary = cmd
      ? `ผบ. ${cmd.name} (Mil ${cmdMil}, Log ${cmdLog}, Comp ${cmdComp} ➔ ตัวคูณการรบ ×${commanderMult.toFixed(2)})`
      : 'ไม่มี ผบ. ประจำหน่วย (×0.85)';
    return u.combatPower;
  }

  function ensureWarMultiFrontsV200(world, war) {
    if (!war || war.objectiveKind === 'SPECIAL_SITE_ACCESS') return;
    ensureWarMultiFronts(world, war);
    ensureWarEscalationAndObjectives(world, war);

    const stA = world.states[war.attackerId];
    const stB = world.states[war.defenderId];
    if (!war.objectiveId) {
      if (stA?.policy === 'Naval Expansion') war.objectiveId = 'blockade';
      else if (stA?.policy === 'Expansionist') war.objectiveId = 'capture_city';
      else if (stA?.policy === 'Militarist') war.objectiveId = 'destroy_enemy_military';
      else war.objectiveId = 'capture_territory';
    }
    const objSpec = WAR_OBJECTIVES_V200.find((o) => o.id === war.objectiveId) || WAR_OBJECTIVES_V200[0];
    war.strategicObjective = objSpec.label;

    // Pre-attack Intelligence & Fog of War assessment for both sides (Sections 24 & 25)
    war.intelAssessment = {
      [war.attackerId]: getNonOmniscientAssessment(world, war.attackerId, war.defenderId),
      [war.defenderId]: getNonOmniscientAssessment(world, war.defenderId, war.attackerId)
    };

    const unitsA = Object.values(world.militaryUnits || {}).filter((u) => u.stateId === war.attackerId).map((u) => u.id);
    const unitsB = Object.values(world.militaryUnits || {}).filter((u) => u.stateId === war.defenderId).map((u) => u.id);
    const cmdA = stA?.positions?.SUPREME_COMMANDER || stA?.positions?.ARMY_CHIEF || null;
    const cmdB = stB?.positions?.SUPREME_COMMANDER || stB?.positions?.ARMY_CHIEF || null;
    const weathers = ['Clear (แจ่มใส)', 'Monsoon Rain (ฝนตกหนัก/โคลน)', 'Overcast (เมฆปกคลุม)', 'Heatwave (อากาศร้อนจัด)'];

    (war.fronts || []).forEach((fr, idx) => {
      fr.attacker = war.attackerId;
      fr.defender = war.defenderId;
      if (!fr.location) fr.location = fr.name;
      if (!fr.units) fr.units = [...unitsA.slice(0, 2), ...unitsB.slice(0, 2)];
      if (!fr.commander) fr.commander = { attackerCommanderId: cmdA, defenderCommanderId: cmdB };
      const supA = stA?.militaryReadiness ? Math.round((stA.militaryReadiness.fuel + stA.militaryReadiness.ammunition) * 0.5) : 82;
      const supB = stB?.militaryReadiness ? Math.round((stB.militaryReadiness.fuel + stB.militaryReadiness.ammunition) * 0.5) : 82;
      fr.supplyStatus = { attackerSupply: supA, defenderSupply: supB };
      if (!fr.weather) fr.weather = weathers[(idx + Math.floor((world.tick || 0) / 10)) % weathers.length];
      if (fr.strategicValue === undefined) fr.strategicValue = idx === 0 ? 94 : idx === 1 ? 82 : 88;
      const ratio = (fr.attackerPower + 100) / Math.max(100, fr.defenderPower + 100);
      fr.pressure = clamp(Math.round(ratio * 55), 10, 99);
      fr.momentum = clamp(Math.round(((fr.controlPct || 50) - 50) * 1.8), -95, 95);
      fr.whyWarDecision = [
        `เป้าหมายสงคราม (Objective): ${war.strategicObjective}`,
        `ทำไมจึงรุก/ตั้งรับ: กำลังประเมินฝ่ายรุก ${fr.attackerPower} vs ฝ่ายรับ ${fr.defenderPower} (Pressure ${fr.pressure}, Momentum ${fr.momentum > 0 ? '+' : ''}${fr.momentum})`,
        `สถานะเสบียงแนวรบ: ${war.attackerId} ${supA}% vs ${war.defenderId} ${supB}% • สภาพอากาศ ${fr.weather}`
      ];
    });
  }

  // Military Intelligence Operation (Section 26: reconnaissance, surveillance, signals_intelligence, human_intelligence, satellite_intelligence, counterintelligence)
  function executeMilitaryIntelOp(world, actorStateId, targetStateId, opType = 'reconnaissance') {
    const actor = world.states[actorStateId];
    const target = world.states[targetStateId];
    if (!actor || !target) return { ok: false, reason: 'Invalid states' };
    const spec = MILITARY_INTEL_SPECS_V200[opType] || MILITARY_INTEL_SPECS_V200.reconnaissance;
    if (opType === 'satellite_intelligence' && (actor.spaceProgram?.reconSatellites || 0) < 1) {
      return { ok: false, reason: `${actor.shortName} ยังไม่มีดาวเทียมลาดตระเวนในวงโคจร` };
    }
    if (actor.treasuryB < spec.costB) return { ok: false, reason: `งบคงคลังไม่พอ ($${spec.costB}B)` };
    actor.treasuryB = rnd1(actor.treasuryB - spec.costB);

    const spyNet = getOrInitSpyNetwork(world, actorStateId, targetStateId);
    const rng = new SeededRNG((world.seed || 2026) + world.tick * 97 + hashStr(actorStateId + targetStateId + opType));
    const successChance = clamp(spec.baseSuccess + (actor.militaryReadiness?.intelligence || 75) * 0.002 - (target.counterIntelLevel || 60) * 0.002, 0.25, 0.96);
    const succeeded = rng.chance(successChance);
    const detected = rng.chance(spec.detectRisk);

    if (succeeded) {
      spyNet.networkStrength = clamp(spyNet.networkStrength + 8, 10, 99);
      spyNet.lastIntelReliability = spec.reliability;
      if (actor.militaryReadiness) {
        actor.militaryReadiness.intelligence = clamp((actor.militaryReadiness.intelligence || 80) + 3, 20, 99);
      }
    }
    const assessment = getNonOmniscientAssessment(world, actorStateId, targetStateId);
    const narrative = `📡🔍 [ข่าวกรองทางทหาร — ${spec.label}] ${actor.name} ปฏิบัติการข่าวกรองต่อ ${target.name}: ${succeeded ? `สำเร็จ (ลดความคลาดเคลื่อน Fog of War เหลือ ±${assessment.uncertaintyPct}%, ความน่าเชื่อถือ ${spec.reliability}%)` : 'ถูกระบบลวงทางยุทธวิธีสกัดกั้น'}${detected ? ' (ฝ่ายตรงข้ามตรวจพบสัญญาณ!)' : ''}`;
    addChronicle(world, 'MILITARY', narrative, actor.id);
    return { ok: true, succeeded, detected, reliability: spec.reliability, assessment, narrative };
  }

  // -------------------------------------------------------------------------
  // 4. DIPLOMACY 2.0 & INTELLIGENCE / COVERT ACTION 2.0 (Sections 27-32)
  // -------------------------------------------------------------------------
  function syncDiplomaticTierV200(rel) {
    if (!rel) return 'neutral';
    const sc = rel.score ?? 55;
    if (rel.status === 'War' || sc < 20) rel.tier20 = 'hostile';
    else if (rel.status === 'Hostile' || sc < 38) rel.tier20 = 'tense';
    else if (rel.status === 'Alliance' || sc >= 86) rel.tier20 = 'alliance';
    else if (sc >= 76) rel.tier20 = 'strategic_partner';
    else if (sc >= 66) rel.tier20 = 'partner';
    else if (sc >= 54) rel.tier20 = 'friendly';
    else rel.tier20 = 'neutral';
    return rel.tier20;
  }

  function ensureDiplomacyAndIntelV200(world) {
    if (!world) return;
    if (world._dipIntelV200Ready && world.intelligenceOps && world.spyNetworks) return;
    ensureDeepDiplomacyAndBlocsV170(world);
    if (!Array.isArray(world.intelligenceOps)) world.intelligenceOps = [];
    if (!world.spyNetworks) world.spyNetworks = {};
    if (!Array.isArray(world.storyHighlights)) world.storyHighlights = [];

    const stateIds = Object.keys(world.states);
    for (let i = 0; i < stateIds.length; i++) {
      const a = stateIds[i];
      const stA = world.states[a];
      if (stA.counterIntelLevel === undefined) {
        stA.counterIntelLevel = clamp(Math.round(62 + (stA.militaryReadiness?.intelligence || 75) * 0.25), 30, 96);
      }
      for (let j = 0; j < stateIds.length; j++) {
        const b = stateIds[j];
        if (a === b) continue;
        const stB = world.states[b];
        const rel = stA.relations[b];
        if (!rel) continue;
        // 9 Required Bilateral Dimensions (Section 27):
        // trust, tradeDependency, militaryDependency, diplomaticTrust, ideologicalAffinity, borderTension, historicalGrievance, intelligenceActivity, economicPressure
        if (rel.trust === undefined) rel.trust = rel.diplomaticTrust ?? rel.score ?? 55;
        if (rel.tradeDependency === undefined) rel.tradeDependency = rel.economicDependency ?? 25;
        if (rel.militaryDependency === undefined) rel.militaryDependency = rel.armsDependency ?? 15;
        if (rel.diplomaticTrust === undefined) rel.diplomaticTrust = rel.trust;
        if (rel.ideologicalAffinity === undefined) {
          rel.ideologicalAffinity = stA.regimeCategory === stB.regimeCategory ? 78 : 42;
        }
        if (rel.borderTension === undefined) rel.borderTension = 15;
        if (rel.historicalGrievance === undefined) rel.historicalGrievance = (stA.rivalries || []).includes(b) ? 68 : 12;
        if (rel.intelligenceActivity === undefined) rel.intelligenceActivity = (stA.rivalries || []).includes(b) ? 55 : 18;
        if (rel.economicPressure === undefined) rel.economicPressure = (stB.sanctionedBy || []).includes(a) ? 65 : 10;
        syncDiplomaticTierV200(rel);
        rel.whyDiplomacy = `ระดับ ${rel.tier20.toUpperCase()} (Score ${rel.score}) • Trust ${rel.trust} • พึ่งพาการค้า ${rel.tradeDependency}% • พึ่งพาทหาร ${rel.militaryDependency}% • อุดมการณ์ ${rel.ideologicalAffinity}% • ตึงเครียดชายแดน ${rel.borderTension}%`;
      }
    }

    world._dipIntelV200Ready = true;
    // Seed initial active intelligence operations if empty so UI & tests have immediate live operations
    if (world.intelligenceOps.length === 0) {
      const seedPairs = [
        { s: 'US', t: 'CN', op: 'industrial_espionage' },
        { s: 'CN', t: 'US', op: 'spy_network' },
        { s: 'IL', t: 'IR', op: 'sabotage' },
        { s: 'RU', t: 'UA', op: 'influence_operation' },
        { s: 'TH', t: 'MM', op: 'informants' }
      ];
      seedPairs.forEach((p, idx) => {
        if (world.states[p.s] && world.states[p.t]) {
          const spec = COVERT_ACTION_SPECS_V200[p.op];
          world.intelligenceOps.push({
            id: `INTELOP_${p.s}_${p.t}_${idx + 1}`,
            sponsorStateId: p.s,
            targetStateId: p.t,
            opType: p.op,
            label: spec.label,
            costB: spec.costB,
            duration: spec.duration,
            remainingDays: spec.duration - 5,
            successChance: spec.baseSuccess,
            discoveryChance: spec.baseDetect,
            informantLoyalty: 76,
            agentRisk: 22,
            active: true,
            succeeded: true,
            detected: false,
            consequence: 'กำลังรวบรวมข่าวกรองเชิงลึกและขยายเครือข่ายสายลับ',
            whyOutcome: `ศักยภาพข่าวกรองของ ${p.s} (${world.states[p.s].militaryReadiness?.intelligence || 85}) สูงกว่าระดับตรวจจับเบื้องต้นของ ${p.t}`
          });
        }
      });
    }
  }

  function getOrInitSpyNetwork(world, sponsorId, targetId) {
    if (!world.spyNetworks) world.spyNetworks = {};
    const key = `${sponsorId}_${targetId}`;
    if (!world.spyNetworks[key]) {
      const stS = world.states[sponsorId];
      const isRival = (stS?.rivalries || []).includes(targetId);
      world.spyNetworks[key] = {
        id: `SPYNET_${key}`,
        sponsorStateId: sponsorId,
        targetStateId: targetId,
        networkStrength: isRival ? 54 : 32,
        informantsCount: isRival ? 6 : 2,
        politicalContacts: isRival ? 2 : 1,
        militaryContacts: isRival ? 2 : 0,
        informantLoyalty: 75,
        agentRisk: isRival ? 28 : 14,
        lastIntelReliability: 78
      };
    }
    return world.spyNetworks[key];
  }

  // Conditional Alliance Behavior (Section 29: Ally evaluates treatyObligation, nationalInterest, militaryCapability, domesticPolitics, economicCost, publicOpinion, riskOfEscalation)
  function evaluateAllyIntervention(world, allyStateId, belligerentStateId, enemyStateId, war = null) {
    const ally = world.states[allyStateId];
    const bell = world.states[belligerentStateId];
    const enemy = world.states[enemyStateId];
    if (!ally || !bell || !enemy || ally.isExiled) return { willJoinWar: false, supportType: 'none', score: 0, breakdown: {} };

    const relToBell = relOf(world, allyStateId, belligerentStateId);
    const relToEnemy = relOf(world, allyStateId, enemyStateId);
    const sharedAlliance = (world.alliances || []).find((a) => a.members.includes(allyStateId) && a.members.includes(belligerentStateId));

    const treatyObligation = relToBell.status === 'Alliance' ? 85 : sharedAlliance ? (sharedAlliance.type.includes('Defense') ? 82 : 55) : 25;
    const nationalInterest = clamp(Math.round((100 - (relToEnemy.score || 50)) * 0.6 + (relToBell.tradeDependency || 30) * 0.4), 10, 95);
    const allyPot = calculateStateCombatPotential(world, allyStateId);
    const enemyPot = calculateStateCombatPotential(world, enemyStateId);
    const militaryCapability = clamp(Math.round((allyPot.totalPower / Math.max(300, enemyPot.totalPower)) * 60), 15, 95);
    const domesticPolitics = clamp(Math.round((ally.stability || 70) * 0.6 + (ally.coalitionStability || 70) * 0.4 - (ally.warExhaustion || 0) * 0.8), 5, 95);
    const economicCost = clamp(Math.round((relToEnemy.tradeDependency || 20) * 0.7 + (ally.treasuryB < 60 ? 35 : 15)), 10, 95);
    const publicOpinion = clamp(Math.round((ally.informationOps?.warSupport || 50) * 0.7 + (ally.approval || 65) * 0.3), 10, 95);
    const riskOfEscalation = (enemy.nuclear?.warheads || 0) > 0 ? 78 : 35;

    const interventionScore = Math.round(
      treatyObligation * 0.25 +
      nationalInterest * 0.20 +
      militaryCapability * 0.18 +
      domesticPolitics * 0.15 +
      publicOpinion * 0.12 -
      economicCost * 0.18 -
      riskOfEscalation * 0.12
    );

    const willJoinWar = interventionScore >= 48 && ally.stability >= 45 && (ally.warExhaustion || 0) < 55;
    const supportType = willJoinWar ? 'direct_military_intervention' : interventionScore >= 28 ? 'proxy_weapons_and_intel_aid' : 'diplomatic_statement_only';

    const whyAlliance = `คะแนนตัดสินใจช่วยพันธมิตร ${interventionScore}/100 (พันธะสัญญา ${treatyObligation}, ผลประโยชน์ชาติ ${nationalInterest}, ขีดความสามารถทหาร ${militaryCapability}, การเมืองภายใน ${domesticPolitics}, ต้นทุนเศรษฐกิจ -${economicCost}, ความเสี่ยงบานปลาย -${riskOfEscalation}) ➔ ${supportType}`;
    return {
      willJoinWar,
      supportType,
      score: interventionScore,
      whyAlliance,
      breakdown: { treatyObligation, nationalInterest, militaryCapability, domesticPolitics, economicCost, publicOpinion, riskOfEscalation }
    };
  }

  // 17 Diplomatic Actions (Section 28)
  function executeDiplomaticAction20(world, actorStateId, targetStateId, actionType = 'negotiate', opts = {}) {
    const A = world.states[actorStateId];
    const B = world.states[targetStateId];
    if (!A || !B || actorStateId === targetStateId) return { ok: false, reason: 'Invalid states' };
    ensureDiplomacyAndIntelV200(world);
    const rel = relOf(world, actorStateId, targetStateId);
    const rev = relOf(world, targetStateId, actorStateId);

    let msg = '';
    switch (actionType) {
      case 'negotiate':
        rel.score = clamp(rel.score + 6, 0, 100);
        rel.trust = clamp((rel.trust || 50) + 6, 0, 100);
        rel.borderTension = clamp((rel.borderTension || 20) - 5, 0, 100);
        msg = `🤝 [การเจรจาทางการทูต] ${A.name} และ ${B.name} เปิดโต๊ะเจรจาทวิภาคี ยกระดับความไว้วางใจเป็น ${rel.trust}%`;
        break;
      case 'warn':
      case 'threaten':
      case 'demand':
        rel.score = clamp(rel.score - (actionType === 'threaten' ? 10 : 6), 0, 100);
        rel.borderTension = clamp((rel.borderTension || 20) + 12, 0, 100);
        rel.trust = clamp((rel.trust || 50) - 8, 0, 100);
        msg = `⚠️📢 [${actionType.toUpperCase()}] ${A.name} ส่งคำเตือนและแรงกดดันทางการทูตต่อ ${B.name} (ความตึงเครียดพรมแดน ${rel.borderTension}%)`;
        break;
      case 'offer_aid':
        if (A.treasuryB >= 10) {
          A.treasuryB = rnd1(A.treasuryB - 10);
          B.treasuryB = rnd1(B.treasuryB + 10);
        }
        rel.score = clamp(rel.score + 9, 0, 100);
        rel.trust = clamp((rel.trust || 50) + 8, 0, 100);
        rel.tradeDependency = clamp((rel.tradeDependency || 25) + 6, 0, 100);
        // Diplomacy <-> Politics: Pro-A faction in B gains strength!
        if (B.factions && B.factions[0]) {
          B.factions[0].power = clamp((B.factions[0].power || 35) + 3, 5, 90);
          B.factions[0].influence = B.factions[0].power;
        }
        msg = `💝💰 [ความช่วยเหลือทางเศรษฐกิจ] ${A.name} มอบเงินช่วยเหลือ $10B แก่ ${B.name} เสริมสร้างอิทธิพลทางเศรษฐกิจและความสัมพันธ์ (${rel.score}/100)`;
        break;
      case 'offer_weapons':
        executeInternationalArmsDeal(world, B.id, A.id);
        rel.militaryDependency = clamp((rel.militaryDependency || 20) + 12, 0, 100);
        rel.score = clamp(rel.score + 7, 0, 100);
        msg = `📦🛡️ [ส่งมอบอาวุธยุทโธปกรณ์] ${A.name} ส่งมอบอาวุธและที่ปรึกษาทางทหารให้ ${B.name} (ความพึ่งพาทางทหาร ${rel.militaryDependency}%)`;
        break;
      case 'military_exercise':
        rel.militaryCoop = clamp((rel.militaryCoop || 50) + 10, 0, 100);
        rel.score = clamp(rel.score + 5, 0, 100);
        if (A.militaryReadiness) A.militaryReadiness.training = clamp((A.militaryReadiness.training || 82) + 2, 30, 99);
        if (B.militaryReadiness) B.militaryReadiness.training = clamp((B.militaryReadiness.training || 82) + 2, 30, 99);
        // Military <-> Diplomacy: Neighboring rivals feel threatened!
        (A.rivalries || []).forEach((rId) => {
          const rRel = relOf(world, A.id, rId);
          if (rRel) rRel.borderTension = clamp((rRel.borderTension || 25) + 8, 0, 100);
        });
        msg = `🎖️🚢 [การซ้อมรบร่วมทางยุทธศาสตร์] ${A.name} และ ${B.name} จัดการซ้อมรบผสม เพิ่มการป้องปรามแต่ทำให้ประเทศคู่แข่งระแวงเพิ่มขึ้น`;
        break;
      case 'intelligence_sharing':
        rel.intelSharing = clamp((rel.intelSharing || 30) + 15, 0, 100);
        rel.trust = clamp((rel.trust || 50) + 7, 0, 100);
        msg = `🛰️🔐 [ข้อตกลงแบ่งปันข่าวกรอง] ${A.name} และ ${B.name} เชื่อมโยงเครือข่ายข่าวกรองร่วม (${rel.intelSharing}%)`;
        break;
      case 'sanctions':
      case 'embargo':
        if (!B.sanctionedBy) B.sanctionedBy = [];
        if (!B.sanctionedBy.includes(A.id)) B.sanctionedBy.push(A.id);
        rel.score = clamp(rel.score - 15, 0, 100);
        rel.economicPressure = clamp((rel.economicPressure || 20) + 22, 0, 100);
        B.economicPressure = clamp(rnd1((B.economicPressure || 25) + 8), 5, 99);
        msg = `🚫📉 [${actionType === 'embargo' ? 'การปิดล้อมทางการค้า (Embargo)' : 'มาตรการคว่ำบาตร (Sanctions)'}] ${A.name} ประกาศคว่ำบาตร ${B.name} กระทบห่วงโซ่อุปทานและเพิ่มแรงกดดันเศรษฐกิจเป็น ${B.economicPressure}%`;
        break;
      case 'trade_agreement':
        rel.tradeVolumeB = rnd1((rel.tradeVolumeB || 15) * 1.2 + 5);
        rel.tradeDependency = clamp((rel.tradeDependency || 25) + 8, 0, 100);
        rel.score = clamp(rel.score + 8, 0, 100);
        A.gdpB = rnd1(A.gdpB + 12);
        B.gdpB = rnd1(B.gdpB + 12);
        msg = `📈🚢 [ความตกลงการค้าเสรีทวิภาคี] ${A.name} และ ${B.name} ลงนามขยายการค้าสู่ $${rel.tradeVolumeB}B/ปี`;
        break;
      case 'defense_agreement':
      case 'alliance':
        setDiplomaticStatus(world, A.id, B.id, 'Alliance');
        rel.score = 90;
        rel.trust = 88;
        rel.militaryCoop = 88;
        msg = `🛡️🤝 [สนธิสัญญาป้องกันร่วม/พันธมิตร] ${A.name} และ ${B.name} ยกระดับเป็นพันธมิตรทางทหารอย่างเป็นทางการ`;
        break;
      case 'mediation':
      case 'peace_proposal':
      case 'ceasefire': {
        const war = (world.wars || []).find((w) => (w.attackerId === A.id && w.defenderId === B.id) || (w.attackerId === B.id && w.defenderId === A.id));
        if (war) {
          endWarPeace(world, war, A.id, B.id, 'ข้อตกลงหยุดยิงและสันติภาพทางการทูต');
        } else {
          setDiplomaticStatus(world, A.id, B.id, 'Peace');
        }
        rel.score = Math.max(55, rel.score);
        rel.borderTension = Math.max(10, (rel.borderTension || 40) - 20);
        msg = `🕊️📜 [${actionType === 'ceasefire' ? 'ข้อตกลงหยุดยิง' : 'แผนสันติภาพและการไกล่เกลี่ย'}] ${A.name} และ ${B.name} บรรลุข้อตกลงยุติการปะทะ`;
        break;
      }
      case 'secret_agreement':
        rel.secretPact = true;
        rel.intelSharing = clamp((rel.intelSharing || 30) + 18, 0, 100);
        rel.trust = clamp((rel.trust || 50) + 10, 0, 100);
        msg = `🕶️📜 [ข้อตกลงลับทางยุทธศาสตร์] ${A.name} และ ${B.name} ทำข้อตกลงลับด้านข่าวกรองและความมั่นคง`;
        break;
    }

    // Mirror bilateral fields
    rev.score = rel.score;
    rev.trust = rel.trust;
    rev.diplomaticTrust = rel.trust;
    rev.borderTension = rel.borderTension;
    rev.tradeDependency = rel.tradeDependency;
    rev.militaryDependency = rel.militaryDependency;
    rev.economicPressure = rel.economicPressure;
    syncDiplomaticTierV200(rel);
    syncDiplomaticTierV200(rev);
    rel.whyDiplomacy = `Action ล่าสุด: ${actionType} • ระดับ ${rel.tier20.toUpperCase()} (Score ${rel.score}, Trust ${rel.trust}, Tension ${rel.borderTension}%)`;
    rev.whyDiplomacy = rel.whyDiplomacy;

    addChronicle(world, 'DIPLOMACY', msg, A.id);
    return { ok: true, actionType, relation: rel, narrative: msg };
  }

  // Covert Intelligence & Proxy Operations (Sections 30, 31, 32)
  function executeCovertIntelOp(world, sponsorStateId, targetStateId, opType = 'spy_network', opts = {}) {
    const sponsor = world.states[sponsorStateId];
    const target = world.states[targetStateId];
    if (!sponsor || !target || sponsorStateId === targetStateId) return { ok: false, reason: 'Invalid states' };
    ensureDiplomacyAndIntelV200(world);

    const spec = COVERT_ACTION_SPECS_V200[opType] || COVERT_ACTION_SPECS_V200.spy_network;
    if (sponsor.treasuryB < spec.costB) return { ok: false, reason: `งบคงคลังของ ${sponsor.shortName} ไม่พอ ($${spec.costB}B)` };
    sponsor.treasuryB = rnd1(sponsor.treasuryB - spec.costB);

    const spyNet = getOrInitSpyNetwork(world, sponsorStateId, targetStateId);
    const rng = new SeededRNG((world.seed || 2026) + world.tick * 173 + hashStr(sponsorStateId + targetStateId + opType));
    const sponsorIntel = sponsor.militaryReadiness?.intelligence || 80;
    const targetCI = target.counterIntelLevel || 65;

    const successChance = clamp(spec.baseSuccess + (sponsorIntel - targetCI) * 0.004 + spyNet.networkStrength * 0.002, 0.18, 0.95);
    const discoveryChance = clamp(spec.baseDetect + (targetCI - sponsorIntel) * 0.003 + (spyNet.agentRisk || 20) * 0.002, 0.04, 0.65);

    const succeeded = opts.forceSuccess !== undefined ? opts.forceSuccess : rng.chance(successChance);
    const detected = opts.forceDetected !== undefined ? opts.forceDetected : (opType !== 'counterintelligence' && rng.chance(discoveryChance));

    let consequence = '';
    if (opType === 'counterintelligence') {
      sponsor.counterIntelLevel = clamp((sponsor.counterIntelLevel || 65) + 6, 20, 99);
      const hostileNet = getOrInitSpyNetwork(world, targetStateId, sponsorStateId);
      hostileNet.networkStrength = clamp(hostileNet.networkStrength - 12, 5, 95);
      consequence = `ยกระดับการต่อต้านข่าวกรองของ ${sponsor.shortName} เป็น ${sponsor.counterIntelLevel}% และทำลายสายลับของ ${target.shortName}`;
    } else if (succeeded) {
      if (opType === 'spy_network' || opType === 'informants') {
        spyNet.networkStrength = clamp(spyNet.networkStrength + 10, 10, 99);
        spyNet.informantsCount += 2;
        consequence = `ขยายเครือข่ายสายลับใน ${target.shortName} สู่ระดับ ${spyNet.networkStrength}% (ผู้ให้ข่าว ${spyNet.informantsCount} ราย)`;
      } else if (opType === 'political_contacts' || opType === 'covert_funding' || opType === 'influence_operation') {
        executeForeignPoliticalInfluence(world, sponsorStateId, targetStateId, 'support_opposition', { costB: 0, forceDetected: detected, silent: true });
        spyNet.politicalContacts += 1;
        consequence = `แทรกแซงการเมืองและหนุนฝ่ายค้านใน ${target.shortName} (แรงกดดันฝ่ายค้าน ${target.oppositionPressure}%)`;
      } else if (opType === 'military_contacts') {
        spyNet.militaryContacts += 1;
        target.militaryLoyalty = clamp((target.militaryLoyalty || 75) - 5, 15, 99);
        // Secret contact with a general in target state
        const targetGen = Object.values(world.npcs).find((n) => n.alive && n.stateId === target.id && n.track === 'military' && n.stage >= 5);
        const sponsorIntelChief = sponsor.positions?.INTELLIGENCE_CHIEF ? world.npcs[sponsor.positions.INTELLIGENCE_CHIEF] : null;
        if (targetGen && sponsorIntelChief) {
          addOrUpdateNPCRelationship(world, sponsorIntelChief, targetGen, 'secretContact', 58, `สายลับ ${sponsor.shortName} ติดต่อลับกับนายพลของ ${target.shortName}`, true);
        }
        consequence = `สร้างสายสัมพันธ์ลับในกองทัพ ${target.shortName} ส่งผลให้ความภักดีกองทัพต่อรัฐบาลลดลงเหลือ ${target.militaryLoyalty}%`;
      } else if (opType === 'industrial_espionage') {
        sponsor.researchPoints = (sponsor.researchPoints || 0) + 18;
        consequence = `จารกรรมข้อมูลเทคโนโลยีจาก ${target.shortName} สำเร็จ (+18 แต้มวิจัย R&D)`;
      } else if (opType === 'sabotage') {
        executeLogisticsInterdiction(world, sponsorStateId, targetStateId, 'sabotage');
        consequence = `วินาศกรรมคลังเสบียงและสายส่งกำลังบำรุงใน ${target.shortName} สำเร็จ`;
      } else {
        consequence = `แบ่งปันข้อมูลข่าวกรองเชิงลึกสำเร็จ`;
      }
    } else {
      consequence = `ปฏิบัติการถูกสกัดกั้นโดยหน่วยต่อต้านข่าวกรองของ ${target.shortName} (Counter-Intel ${targetCI}%)`;
    }

    const rel = relOf(world, sponsorStateId, targetStateId);
    const rev = relOf(world, targetStateId, sponsorStateId);
    rel.intelligenceActivity = clamp((rel.intelligenceActivity || 25) + 10, 5, 99);
    rev.intelligenceActivity = rel.intelligenceActivity;

    if (detected) {
      // Section 32: Intelligence Discovery Fallout!
      rel.score = clamp((rel.score || 50) - 18, 0, 100);
      rev.score = rel.score;
      rel.trust = clamp((rel.trust || 50) - 20, 0, 100);
      rev.trust = rel.trust;
      rel.borderTension = clamp((rel.borderTension || 20) + 15, 0, 100);
      rev.borderTension = rel.borderTension;
      syncDiplomaticTierV200(rel);
      syncDiplomaticTierV200(rev);
      spyNet.networkStrength = clamp(spyNet.networkStrength - 10, 5, 95);
      consequence += ` • 🚨 ถูกเปิดโปง! ความสัมพันธ์ลดลงเหลือ ${rel.score}/100 (${rel.tier20}) และเกิดวิกฤตการทูต!`;
    }

    const opRecord = {
      id: `INTELOP_${sponsorStateId}_${targetStateId}_${world.tick}_${(world.intelligenceOps?.length || 0) + 1}`,
      sponsorStateId,
      targetStateId,
      opType,
      label: spec.label,
      costB: spec.costB,
      duration: spec.duration,
      remainingDays: spec.duration,
      successChance: +successChance.toFixed(2),
      discoveryChance: +discoveryChance.toFixed(2),
      informantLoyalty: spyNet.informantLoyalty,
      agentRisk: spyNet.agentRisk,
      active: !detected,
      succeeded,
      detected,
      date: world.dateString,
      year: world.year,
      consequence,
      whyOutcome: `โอกาสสำเร็จ ${(successChance * 100).toFixed(0)}% (Intel ${sponsor.shortName} ${sponsorIntel} vs Counter-Intel ${target.shortName} ${targetCI}, เครือข่ายสายลับ ${spyNet.networkStrength}%) • โอกาสถูกตรวจพบ ${(discoveryChance * 100).toFixed(0)}%`
    };

    world.intelligenceOps.unshift(opRecord);
    if (world.intelligenceOps.length > 45) world.intelligenceOps.length = 45;

    const chronText = detected
      ? `🕵️‍♂️🚨 [ปฏิบัติการลับถูกเปิดโปง!] ${target.name} จับได้คาหนังคาเขาว่า ${sponsor.name} ดำเนินปฏิบัติการ "${spec.label}" — ${consequence}`
      : `🕵️‍♂️📡 [ปฏิบัติการข่าวกรองและปฏิบัติการลับ] ${sponsor.name} ดำเนิน "${spec.label}" ต่อเป้าหมาย ${target.name} — ${consequence}`;
    addChronicle(world, detected ? 'DIPLOMACY' : 'MILITARY', chronText, sponsor.id, { intelOpId: opRecord.id });
    if (detected) {
      recordStoryHighlight(world, 'INTELLIGENCE_EXPOSED', chronText, target.id, { intelOpId: opRecord.id });
    }
    return { ok: true, opRecord, narrative: chronText };
  }

  // -------------------------------------------------------------------------
  // 5. COMPANY CONNECTION, NATURAL ANTI-SNOWBALL, AUTOMATIC STORY DETECTION & 4 REPORTS
  // -------------------------------------------------------------------------
  function enrichCompaniesConnectionV200(world) {
    (world.companies || []).forEach((co) => {
      const st = world.states[co.stateId];
      const ceo = co.ceoId ? world.npcs[co.ceoId] : null;
      const isAtWar = st ? getWarsOf(world, st.id).length > 0 : false;
      if (isAtWar && co.sector?.includes('defense')) {
        co.contractsCount = Math.min(18, (co.contractsCount || 2) + 1);
        co.capitalB = rnd1(Math.min(650, (co.capitalB || 30) + 1.2));
      }
      if (co.capitalB > 380) {
        // Anti-Snowball (Section 54): Economic dominance -> competitors emerge and erode monopoly margin
        co.capitalB = rnd1(co.capitalB * 0.96);
      }
      co.militaryContracts = co.contractsCount || 2;
      co.governmentRelations = clamp(Math.round(68 + (co.contractsCount || 2) * 3), 25, 98);
      co.politicalInfluence = clamp(Math.round(35 + (co.capitalB || 30) * 0.4 + (co.contractsCount || 2) * 2.5), 15, 98);
      co.supplyChainRole = co.sector?.includes('semiconductor')
        ? 'ผลิตชิปเซมิคอนดักเตอร์และระบบเรดาร์/AI ต้นน้ำ'
        : co.sector?.includes('energy')
        ? 'กลั่นเชื้อเพลิงพลังงานและเคมีภัณฑ์ยุทธศาสตร์'
        : 'สายการผลิตยุทโธปกรณ์และอะไหล่ซ่อมบำรุงกองทัพ';
      co.strategicImportance = clamp(Math.round(60 + (co.capitalB || 30) * 0.3 + (co.rndLevel || 80) * 0.15), 40, 99);
      if (ceo) {
        ceo._manualEconomicInfluence = clamp(Math.max(ceo.economicInfluence || 60, co.politicalInfluence), 25, 99);
        ceo._powerDirty = true;
      }
    });
  }

  // Natural Anti-Snowball Mechanics (Sections 54 & 55: No artificial flat nerf; organic counter-forces!)
  function runNaturalAntiSnowballCycle(world, rng) {
    const liveStates = Object.values(world.states).filter((s) => !s.isExiled);
    liveStates.forEach((st) => {
      const myCitiesCount = (st.cities || []).length;
      const potTotal = getPowerCached(world, st.id);

      // 1. Military / Territorial Dominance -> Neighboring states feel fear & form balancing coalition
      if (myCitiesCount >= 18 || potTotal >= 24000) {
        const neighbors = liveStates.filter((o) => o.id !== st.id && (o.region === st.region || (o.rivalries || []).includes(st.id)));
        neighbors.forEach((nb) => {
          const rel = relOf(world, nb.id, st.id);
          rel.borderTension = clamp((rel.borderTension || 20) + 4, 0, 100);
          rel.trust = clamp((rel.trust || 50) - 3, 0, 100);
          syncDiplomaticTierV200(rel);
        });
      }

      // 2. Political Dominance -> Internal rivalry & opposition counter-mobilization
      const govFac = (st.factions || []).find((f) => f.type === 'Government');
      const oppFac = (st.factions || []).find((f) => f.type === 'Opposition' || f.type === 'Underground');
      if (govFac && govFac.power > 58 && oppFac) {
        govFac.cohesion = clamp((govFac.cohesion || 78) - 3, 30, 95); // Internal faction rivalry grows when too dominant
        oppFac.power = clamp((oppFac.power || 20) + 2, 10, 80);
        oppFac.influence = oppFac.power;
      }

      // 3. High NPC Personal Power -> Rivals emerge naturally (Section 54)
      const net = (world.powerNetworks && world.powerNetworks[st.id]) || analyzeStatePowerNetwork(world, st.id);
      if (net && net.mostPowerfulNpcId) {
        const topNpc = world.npcs[net.mostPowerfulNpcId];
        if (topNpc && topNpc.realInfluence >= 88 && net.topRivalNpcId && world.npcs[net.topRivalNpcId]) {
          const riv = world.npcs[net.topRivalNpcId];
          riv.ambition = clamp((riv.ambition || 65) + 3, 20, 99);
          addOrUpdateNPCRelationship(world, riv, topNpc, 'rival', -70, 'ก่อตั้งขั้วอำนาจคานบารมีผู้มีอิทธิพลสูงสุด', false);
        }
      }
    });
  }

  // Automatic Story Detection for Chronicle Highlights (Section 53)
  function recordStoryHighlight(world, storyType, text, stateId = null, refs = {}) {
    if (!Array.isArray(world.storyHighlights)) world.storyHighlights = [];
    // Avoid duplicate highlight in same year for same type+state
    if (world.storyHighlights.some((s) => s.storyType === storyType && s.stateId === stateId && s.year === world.year)) {
      return;
    }
    const item = {
      id: `STORY_${storyType}_${stateId || 'WORLD'}_${world.tick}`,
      storyType,
      year: world.year,
      date: world.dateString,
      tick: world.tick,
      stateId,
      text,
      refs
    };
    world.storyHighlights.unshift(item);
    if (world.storyHighlights.length > 45) world.storyHighlights.length = 45;
    addChronicle(world, 'STORY_HIGHLIGHT', `🌟 [Chronicle Highlight] ${text}`, stateId, refs);
  }

  function detectEmergentStories(world) {
    // Scan for organic emergent stories:
    // 1. Corporate dominance
    const dominantCorp = (world.companies || []).find((c) => (c.politicalInfluence || 0) >= 82 && (c.contractsCount || 0) >= 6);
    if (dominantCorp) {
      recordStoryHighlight(
        world,
        'CORPORATE_DOMINANCE',
        `🏭👑 [กลุ่มทุนผงาดกุมอำนาจรัฐ] บริษัท ${dominantCorp.name} (${dominantCorp.stateId}) ขยายสัญญาอาวุธและทุนสู่ $${dominantCorp.capitalB}B จนมีอิทธิพลทางการเมืองสูงถึง ${dominantCorp.politicalInfluence}/100!`,
        dominantCorp.stateId,
        { companyId: dominantCorp.id, personId: dominantCorp.ceoId }
      );
    }
    // 1b. New-generation politician rises to top leadership
    Object.values(world.states).forEach((st) => {
      if (st.isExiled) return;
      const head = st.positions?.HEAD_OF_STATE ? world.npcs[st.positions.HEAD_OF_STATE] : null;
      if (head && head.age <= 42 && head.realInfluence >= 75) {
        recordStoryHighlight(
          world,
          'NEW_GEN_LEADER',
          `🌟🏛️ [ผู้นำรุ่นใหม่ก้าวขึ้นสู่อำนาจสูงสุด] ${head.name} (วัย ${head.age} ปี, แนวคิด ${head.ideology}) ก้าวขึ้นเป็นผู้นำแห่ง ${st.name} ด้วยอำนาจจริง ${head.realInfluence}/100!`,
          st.id,
          { personId: head.id }
        );
      }
    });
    // 2. Small state holding off or defeating larger state
    (world.wars || []).forEach((w) => {
      const stA = world.states[w.attackerId];
      const stB = world.states[w.defenderId];
      if (!stA || !stB) return;
      if (stB.gdpB * 2.2 < stA.gdpB && (w.fronts?.[0]?.controlPct || 50) <= 38) {
        recordStoryHighlight(
          world,
          'ASYMMETRIC_DEFENSE',
          `🛡️🔥 [ยุทธศาสตร์อสมมาตรพลิกสมรภูมิ] ${stB.name} ซึ่งมีขนาดเศรษฐกิจเล็กกว่า สามารถต้านทานและตีโต้การรุกของมหาอำนาจ ${stA.name} จนแนวรบหลักถอยร่นเหลือ ${w.fronts[0].controlPct}%!`,
          stB.id,
          { warId: w.id }
        );
      }
    });
  }

  // 4 Comprehensive Reports Generator (Section 52: Political, Military, Diplomatic, Intelligence)
  function generateWorldReportsV200(world) {
    if (!world) return {};
    const states = Object.values(world.states).filter((s) => !s.isExiled);
    const aliveNpcs = Object.values(world.npcs).filter((n) => n.alive && !n.retired);

    // 1. Political Report
    const allFactions = [];
    states.forEach((s) => {
      ensurePoliticalSimulationV200(world, s);
      (s.factions || []).forEach((f) => {
        allFactions.push({ stateId: s.id, stateName: s.shortName, ...f });
      });
    });
    const strongestFactions = allFactions.sort((a, b) => (b.power || 0) - (a.power || 0)).slice(0, 8);
    const unstableGovernments = states.slice().sort((a, b) => (a.stability || 50) - (b.stability || 50)).slice(0, 8);
    const risingPoliticians = aliveNpcs
      .filter((n) => n.track === 'political' || ['President', 'Prime Minister', 'Minister', 'Party Leader', 'Opposition Leader'].includes(n.formalPosition))
      .sort((a, b) => (b.realInfluence || 0) - (a.realInfluence || 0))
      .slice(0, 8);
    const highMilInfluenceStates = states.slice().sort((a, b) => (b.politicalPressures?.militaryInfluence || 0) - (a.politicalPressures?.militaryInfluence || 0)).slice(0, 8);

    // 2. Military Report
    const strongestCommanders = aliveNpcs
      .filter((n) => n.track === 'military')
      .sort((a, b) => ((b.militaryAbility || 0) + (b.realInfluence || 0)) - ((a.militaryAbility || 0) + (a.realInfluence || 0)))
      .slice(0, 8);
    const supplyProblems = Object.values(world.camps)
      .filter((c) => (c.daysOfSupply || 25) < 18 || (c.overCapacityPenalty || 0) > 0)
      .sort((a, b) => (a.daysOfSupply || 25) - (b.daysOfSupply || 25))
      .slice(0, 8);
    const activeFronts = [];
    (world.wars || []).forEach((w) => {
      ensureWarMultiFrontsV200(world, w);
      (w.fronts || []).forEach((fr) => activeFronts.push({ warId: w.id, warName: w.name, ...fr }));
    });

    // 3. Diplomatic Report
    const deterioratingRelations = [];
    const seenPairs = new Set();
    states.forEach((sA) => {
      Object.entries(sA.relations || {}).forEach(([bId, rel]) => {
        const key = sA.id < bId ? `${sA.id}_${bId}` : `${bId}_${sA.id}`;
        if (seenPairs.has(key) || !world.states[bId]) return;
        seenPairs.add(key);
        if ((rel.score || 50) <= 42 || (rel.borderTension || 0) >= 45) {
          deterioratingRelations.push({ stateA: sA.id, stateB: bId, score: rel.score, tier: rel.tier20 || 'tense', borderTension: rel.borderTension || 30, status: rel.status });
        }
      });
    });
    deterioratingRelations.sort((a, b) => a.score - b.score);
    const sanctionedStates = states.filter((s) => (s.sanctionedBy || []).length > 0);

    // 4. Intelligence Report
    const activeIntelOps = (world.intelligenceOps || []).slice(0, 12);
    const detectedOps = (world.intelligenceOps || []).filter((op) => op.detected).slice(0, 10);
    const topSpyNetworks = Object.values(world.spyNetworks || {}).sort((a, b) => (b.networkStrength || 0) - (a.networkStrength || 0)).slice(0, 8);

    const reports = {
      politicalReport: { strongestFactions, unstableGovernments, risingPoliticians, highMilInfluenceStates },
      militaryReport: { strongestCommanders, supplyProblems, activeFronts, activeWarsCount: (world.wars || []).length },
      diplomaticReport: { alliances: world.alliances || [], deterioratingRelations: deterioratingRelations.slice(0, 10), sanctionedStates },
      intelligenceReport: { activeIntelOps, detectedOps, topSpyNetworks },
      storyHighlights: (world.storyHighlights || []).slice(0, 15)
    };
    world._reportsCache = reports;
    return reports;
  }

  // Debug / Observer "Why?" Inspector Tool (Section 64)
  function inspectEntityWhyV200(world, rawUri) {
    const resolved = resolveEntity(world, rawUri);
    if (!resolved) return { title: 'Unknown', explanations: [] };
    const d = resolved.data;

    if (resolved.type === 'person') {
      ensureNPCPowerModelV200(world, d);
      return {
        uri: resolved.uri,
        title: `🔍 Debug Inspector: ${d.name} (${d.stateId})`,
        sections: [
          { heading: '1. ทำไม NPC คนนี้จึงมีอำนาจระดับนี้? (Formal Power vs Real Power)', items: d.whyPowerBreakdown || [] },
          { heading: '2. แหล่งที่มาของอำนาจทั้ง 6 ด้าน (Power Sources Breakdown)', items: [
            `Political Power (${d.politicalPower}): ตำแหน่ง ${d.powerSources?.political?.position} | พรรค ${d.powerSources?.political?.party} | มวลชน ${d.powerSources?.political?.publicSupport}`,
            `Military Influence (${d.militaryInfluence}): การบังคับบัญชา ${d.powerSources?.military?.command} | ความภักดีทหาร ${d.powerSources?.military?.troopsLoyalty}% | ชัยชนะ ${d.victories || 0} ครั้ง`,
            `Economic Influence (${d.economicInfluence}): ธุรกิจ/บริษัท ${d.powerSources?.military ? d.powerSources.economic.companyOwnership : 0} | ความมั่งคั่ง $${d.wealthM}M`,
            `Bureaucratic (${d.bureaucraticInfluence}) | Network Power (${d.networkPower}) | Faction Power (${d.factionPower})`
          ] },
          { heading: '3. ทำไม NPC จึงตัดสินใจเลือก Action ล่าสุด?', items: [
            `Action ล่าสุด: ${d.lastDecisionAction || 'evaluate'}`,
            `เหตุผล: ${d.lastDecisionReason || d.lastDecisionText || 'ประเมินตามบทบาทและสถานการณ์'}`
          ] }
        ]
      };
    }
    if (resolved.type === 'state') {
      ensurePoliticalSimulationV200(world, d);
      const net = analyzeStatePowerNetwork(world, d.id);
      return {
        uri: resolved.uri,
        title: `🔍 Debug Inspector: ${d.name}`,
        sections: [
          { heading: '1. โครงสร้างอำนาจจริงภายในรัฐ (Power Network & Kingmaker)', items: [
            `ผู้นำทางการ: ${net?.headOfStateId ? world.npcs[net.headOfStateId]?.name : '-'} (Formal ${net?.headFormalPower} vs Real ${net?.headRealPower})`,
            `ผู้มีอำนาจจริงสูงสุด: ${net?.mostPowerfulNpcId ? world.npcs[net.mostPowerfulNpcId]?.name : '-'}`,
            `Kingmaker (ผู้ชี้ชะตาการเมือง): ${net?.kingmakerNpcId ? world.npcs[net.kingmakerNpcId]?.name : '-'}`,
            `คู่แข่งทางการเมืองหลัก (Primary Rival): ${net?.topRivalNpcId ? world.npcs[net.topRivalNpcId]?.name : '-'}`,
            `ตัวกลางประสานกลุ่มอำนาจ (Faction Broker): ${net?.brokerNpcId ? world.npcs[net.brokerNpcId]?.name : '-'}`
          ] },
          { heading: '2. สมการเสถียรภาพรัฐบาล (Government Stability Breakdown)', items: [
            `Government Stability: ${d.stability}% | Coalition Stability: ${d.coalitionStability}% | Legitimacy: ${d.legitimacy}%`,
            `Military Loyalty: ${d.militaryLoyalty}% | Bureaucratic Compliance: ${d.bureaucraticCompliance}% | Elite Support: ${d.eliteSupport}%`,
            `Public Approval: ${d.approval}% | Opposition Pressure: ${d.oppositionPressure}% | Economic Pressure: ${d.economicPressure}%`
          ] }
        ]
      };
    }
    if (resolved.type === 'war') {
      ensureWarMultiFrontsV200(world, d);
      return {
        uri: resolved.uri,
        title: `🔍 Debug Inspector: ${d.name}`,
        sections: [
          { heading: '1. ทำไมจึงโจมตี / ถอยร่น / ขาดแคลนเสบียงในแนวรบ?', items: (d.fronts || []).map((fr) => `${fr.name}: ${(fr.whyWarDecision || []).join(' • ')}`) },
          { heading: '2. การประเมินข่าวกรองและ Fog of War ก่อนปะทะ', items: Object.entries(d.intelAssessment || {}).map(([stId, ia]) => `${stId} ประเมินศัตรู: ความแม่นยำข่าวกรอง ${ia?.intelQuality}% (ความคลาดเคลื่อน Fog of War ±${ia?.uncertaintyPct}%, หน่วยที่ยังไม่ทราบ ${ia?.suspectedState?.unknownUnitsFog || 0} หน่วย)`) }
        ]
      };
    }
    return {
      uri: resolved.uri,
      title: `🔍 Debug Inspector: ${resolved.title}`,
      sections: [{ heading: 'ข้อมูลการตรวจสอบ', items: ['เชื่อมต่อกับระบบ Canonical Data Model เรียบร้อย'] }]
    };
  }

  // -------------------------------------------------------------------------
  // 6. PLAYER EDITS CASCADE & Immediate Simulation Respect (Sections 38, 48, 69)
  // -------------------------------------------------------------------------
  function applyPlayerEditCascade(world, category, entityId, changes = {}) {
    if (!world) return { ok: false };
    let logMsg = '';

    if (category === 'commander' || category === 'npc') {
      const npc = world.npcs[entityId];
      if (!npc) return { ok: false, reason: 'NPC not found' };
      npc.playerEdited = true;
      Object.assign(npc, changes);
      if (changes.politicalPower !== undefined) npc._manualPoliticalPower = Number(changes.politicalPower);
      if (changes.militaryInfluence !== undefined) npc._manualMilitaryInfluence = Number(changes.militaryInfluence);
      if (changes.economicInfluence !== undefined) npc._manualEconomicInfluence = Number(changes.economicInfluence);
      if (changes.realInfluence !== undefined) npc._manualRealInfluence = Number(changes.realInfluence);
      npc._powerDirty = true;
      ensureNPCPowerModelV200(world, npc);

      // Cascade: Commander -> Unit -> Army -> Front -> War -> State -> Political Faction -> Diplomacy -> Chronicle (Section 69!)
      const st = world.states[npc.stateId];
      Object.values(world.militaryUnits || {}).filter((u) => u.commanderId === npc.id || u.stateId === npc.stateId).forEach((u) => {
        recalculateUnitCombatPowerV200(world, u);
      });
      Object.values(world.armies || {}).filter((a) => a.commanderId === npc.id || a.stateId === npc.stateId).forEach((a) => {
        a.readiness = clamp(Math.round((a.readiness || 85) * 0.7 + (npc.militaryAbility || 75) * 0.3), 20, 100);
      });
      (world.wars || []).filter((w) => w.attackerId === npc.stateId || w.defenderId === npc.stateId).forEach((w) => {
        ensureWarMultiFrontsV200(world, w);
      });
      if (st) {
        st.frontlineDirty = true;
        st.logisticsDirty = true;
        const milFac = (st.factions || []).find((f) => f.type === 'Military' || f.leaderNpcId === npc.id);
        if (milFac && npc.track === 'military') {
          milFac.power = clamp(Math.round((milFac.power || 28) * 0.6 + (npc.militaryInfluence || 70) * 0.4), 10, 92);
          milFac.influence = milFac.power;
        }
        analyzeStatePowerNetwork(world, st.id);
      }
      logMsg = `⚡✏️ [Edit Hub Cascade] แก้ไขข้อมูล ${npc.name} (${npc.formalPosition}, Real Power ${npc.realInfluence}) ส่งผลเชื่อมโยงถึงหน่วยรบ กองทัพ แนวรบ การเมืองภายใน และเครือข่ายอำนาจของ ${npc.stateId} ทันที!`;
    } else if (category === 'politics' || category === 'state') {
      const st = world.states[entityId];
      if (!st) return { ok: false, reason: 'State not found' };
      st.playerEdited = true;
      Object.assign(st, changes);
      ensurePoliticalSimulationV200(world, st);
      analyzeStatePowerNetwork(world, st.id);
      logMsg = `⚡🏛️ [Edit Hub Politics] ปรับปรุงโครงสร้างการเมืองและเสถียรภาพของ ${st.name} (Stability ${st.stability}%, Approval ${st.approval}%, Military Loyalty ${st.militaryLoyalty}%)`;
    } else if (category === 'diplomacy') {
      const { stateAId, stateBId, status, score, tradeDependency, militaryDependency } = changes;
      if (status) setDiplomaticStatus(world, stateAId, stateBId, status);
      const rel = relOf(world, stateAId, stateBId);
      const rev = relOf(world, stateBId, stateAId);
      if (rel && rev) {
        if (score !== undefined) { rel.score = Number(score); rev.score = Number(score); }
        if (tradeDependency !== undefined) { rel.tradeDependency = Number(tradeDependency); rev.tradeDependency = Number(tradeDependency); }
        if (militaryDependency !== undefined) { rel.militaryDependency = Number(militaryDependency); rev.militaryDependency = Number(militaryDependency); }
        syncDiplomaticTierV200(rel);
        syncDiplomaticTierV200(rev);
      }
      logMsg = `⚡🤝 [Edit Hub Diplomacy] ปรับความสัมพันธ์ ${stateAId} ↔ ${stateBId} เป็นระดับ ${rel?.tier20 || status} (Score ${rel?.score})`;
    } else if (category === 'war') {
      const war = (world.wars || []).find((w) => w.id === entityId);
      if (!war) return { ok: false, reason: 'War not found' };
      Object.assign(war, changes);
      ensureWarMultiFrontsV200(world, war);
      logMsg = `⚡⚔️ [Edit Hub War] ปรับปรุงเป้าหมายและแนวรบของ ${war.name} (Objective: ${war.strategicObjective})`;
    }

    if (logMsg) addChronicle(world, 'EDIT', logMsg, changes.stateId || null);
    return { ok: true, logMsg };
  }

  // -------------------------------------------------------------------------
  // 7. 8 MANDATORY SCENARIO TESTS RUNNER (Section 62)
  // -------------------------------------------------------------------------
  function runScenarioTestV200(scenarioId = 1) {
    const w = createInitialWorld(2026000 + scenarioId);
    const rng = new SeededRNG(9000 + scenarioId);

    if (scenarioId === 1) {
      // Scenario 1: Weak government + powerful military -> must produce military pressure / intervention
      const st = w.states.TH;
      st.stability = 34;
      st.approval = 36;
      st.militaryLoyalty = 35;
      st.politicalPressures.militaryInfluence = 82;
      const gen = w.npcs[st.positions.SUPREME_COMMANDER];
      gen._manualMilitaryInfluence = 92;
      gen._manualRealInfluence = 90;
      ensureNPCPowerModelV200(w, gen);
      const crisis = evaluatePoliticalCrisesV200(w, st, rng);
      const net = analyzeStatePowerNetwork(w, 'TH');
      return {
        scenarioId: 1,
        name: 'Weak Government + Powerful Military',
        passed: crisis === 'military_intervention' && gen.realInfluence > w.npcs[st.positions.HEAD_OF_STATE].realInfluence,
        details: `Crisis=${crisis}, General RealPower=${gen.realInfluence} vs Head RealPower=${w.npcs[st.positions.HEAD_OF_STATE].realInfluence}, Kingmaker=${net.kingmakerNpcId}`
      };
    }
    if (scenarioId === 2) {
      // Scenario 2: Strong dictator + underground opposition -> resistance dynamics & over-suppression backfire
      const st = w.states.IR;
      st.authoritarianOpposition.suppressionIntensity = 72;
      const legBefore = st.legitimacy;
      const ugBefore = st.authoritarianOpposition.undergroundOpposition;
      executeAuthoritarianAction(w, 'IR', 'arrest');
      return {
        scenarioId: 2,
        name: 'Strong Dictator + Underground Opposition',
        passed: st.legitimacy < legBefore && st.authoritarianOpposition.undergroundOpposition > ugBefore && st.authoritarianOpposition.fearLevel > 60,
        details: `Legitimacy ${legBefore}->${st.legitimacy}, Underground ${ugBefore}->${st.authoritarianOpposition.undergroundOpposition}, Fear=${st.authoritarianOpposition.fearLevel}`
      };
    }
    if (scenarioId === 3) {
      // Scenario 3: Two major powers -> balancing behavior & conditional alliance / deterrence
      const cityCountBefore = stateCities(w, 'US').length;
      // Simulate US military dominance triggering balancing tension in rivals
      for (let i = 0; i < 6; i++) {
        const c = Object.values(w.cities).find((x) => x.stateId === 'MX');
        if (c) c.stateId = 'US';
      }
      syncCityIndex(w);
      const tensionBefore = relOf(w, 'CN', 'US').borderTension;
      runNaturalAntiSnowballCycle(w, rng);
      const tensionAfter = relOf(w, 'CN', 'US').borderTension;
      return {
        scenarioId: 3,
        name: 'Two Major Powers Balancing Behavior',
        passed: tensionAfter > tensionBefore,
        details: `US expanded cities (${cityCountBefore}->${stateCities(w, 'US').length}) -> Rival borderTension rose ${tensionBefore}->${tensionAfter}`
      };
    }
    if (scenarioId === 4) {
      // Scenario 4: Small state vs large state -> asymmetric strategy & defense
      setDiplomaticStatus(w, 'CN', 'VN', 'War');
      const war = w.wars.find((x) => x.attackerId === 'CN' && x.defenderId === 'VN');
      ensureWarMultiFrontsV200(w, war);
      war.fronts[0].controlPct = 34; // VN holds mountain/territorial defense
      detectEmergentStories(w);
      return {
        scenarioId: 4,
        name: 'Small State vs Large State Asymmetric Strategy',
        passed: w.storyHighlights.some((s) => s.storyType === 'ASYMMETRIC_DEFENSE'),
        details: `VN asymmetric defense detected in Story Highlights (${w.storyHighlights[0]?.text || ''})`
      };
    }
    if (scenarioId === 5) {
      // Scenario 5: Long war -> logistics & economic exhaustion
      setDiplomaticStatus(w, 'RU', 'PL', 'War');
      const ru = w.states.RU;
      const stab0 = ru.stability;
      for (let i = 0; i < 120; i++) stepDay(w);
      return {
        scenarioId: 5,
        name: 'Long War Logistics & Economic Exhaustion',
        passed: (ru.warExhaustion || 0) > 0 && (ru.logisticsBurden || 0) > 12,
        details: `RU warExhaustion=${ru.warExhaustion}, logisticsBurden=${ru.logisticsBurden}, stability=${stab0}->${ru.stability}`
      };
    }
    if (scenarioId === 6) {
      // Scenario 6: Foreign power supports opposition -> diplomatic crisis
      const res = executeForeignPoliticalInfluence(w, 'US', 'IR', 'support_opposition', { forceDetected: true });
      return {
        scenarioId: 6,
        name: 'Foreign Power Supports Opposition -> Diplomatic Crisis',
        passed: res.ok && res.detected && relOf(w, 'US', 'IR').score < 35,
        details: res.narrative
      };
    }
    if (scenarioId === 7) {
      // Scenario 7: Famous general becomes politically powerful -> power network shifts
      setDiplomaticStatus(w, 'TH', 'MM', 'War');
      const war = w.wars[0];
      const gen = w.npcs[w.states.TH.positions.SUPREME_COMMANDER];
      const infBefore = gen.realInfluence;
      const bat1 = executeTacticalBattle(w, war, 0, rng);
      recordGeneralVictoryEmergence(w, gen, bat1, war);
      recordGeneralVictoryEmergence(w, gen, bat1, war);
      recordGeneralVictoryEmergence(w, gen, bat1, war);
      const net = analyzeStatePowerNetwork(w, 'TH');
      return {
        scenarioId: 7,
        name: 'Famous General Becomes Politically Powerful',
        passed: gen.victories >= 3 && gen.realInfluence > infBefore && (net.mostPowerfulNpcId === gen.id || net.kingmakerNpcId === gen.id),
        details: `General ${gen.name} victories=${gen.victories}, realInfluence ${infBefore}->${gen.realInfluence}, mostPowerful=${net.mostPowerfulNpcId}, kingmaker=${net.kingmakerNpcId}`
      };
    }
    if (scenarioId === 8) {
      // Scenario 8: Major intelligence operation exposed -> impacts diplomacy
      const scoreBefore = relOf(w, 'IL', 'IR').score;
      const opRes = executeCovertIntelOp(w, 'IL', 'IR', 'sabotage', { forceDetected: true });
      const scoreAfter = relOf(w, 'IL', 'IR').score;
      return {
        scenarioId: 8,
        name: 'Major Intelligence Operation Exposed',
        passed: opRes.ok && opRes.opRecord.detected && scoreAfter < scoreBefore,
        details: `Relation score ${scoreBefore}->${scoreAfter}, Tier=${relOf(w, 'IL', 'IR').tier20}`
      };
    }
    return { scenarioId, passed: true };
  }

  // Master v2.0.0 Initialization & Step Hook
  function ensureWorldSystemsV200(world) {
    if (!world) return world;
    ensureWorldSystemsV170(world);

    Object.values(world.states).forEach((st) => {
      ensurePoliticalSimulationV200(world, st);
    });
    const npcsByState = {};
    Object.values(world.npcs).forEach((npc) => {
      if (!npc.alive) return;
      ensureNPCPowerModelV200(world, npc);
      if (!npc.retired) {
        (npcsByState[npc.stateId] = npcsByState[npc.stateId] || []).push(npc);
      }
    });
    ensureMilitaryWarfareV200(world);
    ensureDiplomacyAndIntelV200(world);
    enrichCompaniesConnectionV200(world);

    Object.keys(world.states).forEach((stId) => {
      analyzeStatePowerNetwork(world, stId, npcsByState[stId] || []);
    });

    world._v200 = true;
    if (!world.version) world.version = VERSION;
    return world;
  }

  // Hook into executeTacticalBattle so general victories & unit combat power & commander effects automatically run!
  const _origExecuteTacticalBattleV200 = executeTacticalBattle;
  executeTacticalBattle = function (world, war, frontIndex = 0, rngInstance = null) {
    ensureWarMultiFrontsV200(world, war);
    const battle = _origExecuteTacticalBattleV200(world, war, frontIndex, rngInstance);
    if (battle) {
      const wonA = /ฝ่ายรุก.*(สำเร็จ|ได้เปรียบ)/.test(battle.result);
      const winCmdId = wonA ? battle.attackerCommanderId : battle.defenderCommanderId;
      const loseCmdId = wonA ? battle.defenderCommanderId : battle.attackerCommanderId;
      if (winCmdId && world.npcs[winCmdId]) {
        recordGeneralVictoryEmergence(world, world.npcs[winCmdId], battle, war);
      }
      if (loseCmdId && world.npcs[loseCmdId]) {
        const loseCmd = world.npcs[loseCmdId];
        loseCmd.reputation = clamp((loseCmd.reputation || 60) - 3, 10, 99);
        loseCmd._powerDirty = true;
        recordNPCMemory20(loseCmd, world.year, 'defeat', `พ่ายแพ้ในการรบที่ ${battle.name}`, 80, `battle:${battle.id}`);
      }
      enrichCompaniesConnectionV200(world);
    }
    return battle;
  };

  // Hook into resolveEntity & searchAllEntities for intelop:, front:, powernet:, spynet:
  const _origResolveEntityV200 = resolveEntity;
  resolveEntity = function (world, rawUri) {
    if (!world || !rawUri) return _origResolveEntityV200(world, rawUri);
    const [rawType, ...rest] = String(rawUri).trim().split(':');
    const type = (rawType || '').toLowerCase();
    const id = rest.join(':');

    if (type === 'intelop') {
      const op = (world.intelligenceOps || []).find((x) => x.id === id) || (world.intelligenceOps || [])[0];
      if (op) {
        return { uri: `intelop:${op.id}`, type: 'intelop', id: op.id, title: `🕵️ ${op.label} (${op.sponsorStateId} ➔ ${op.targetStateId})`, badge: '🕵️ INTELLIGENCE OPERATION PAGE (หน้าปฏิบัติการข่าวกรอง)', data: op };
      }
    }
    if (type === 'front') {
      let foundFront = null;
      let parentWar = null;
      (world.wars || []).forEach((w) => {
        (w.fronts || []).forEach((fr) => {
          if (fr.id === id) { foundFront = fr; parentWar = w; }
        });
      });
      if (foundFront && parentWar) {
        return { uri: `front:${foundFront.id}`, type: 'front', id: foundFront.id, title: `🔥 ${foundFront.name}`, badge: '🔥 WAR FRONT PAGE (หน้าแนวรบยุทธศาสตร์)', data: { front: foundFront, war: parentWar } };
      }
    }
    if (type === 'powernet' && world.states[id]) {
      const net = analyzeStatePowerNetwork(world, id);
      return { uri: `powernet:${id}`, type: 'powernet', id, title: `🕸️ เครือข่ายอำนาจแห่งชาติ: ${world.states[id].name}`, badge: '🕸️ POWER NETWORK GRAPH PAGE (หน้าโครงข่ายอำนาจ)', data: net };
    }
    return _origResolveEntityV200(world, rawUri);
  };

  const _origSearchAllEntitiesV200 = searchAllEntities;
  searchAllEntities = function (world, query, limit = 30) {
    const base = _origSearchAllEntitiesV200(world, query, 250);
    const q = (query || '').trim().toLowerCase();
    const extra = [];

    // Power Networks per State
    Object.values(world.states || {}).forEach((s) => {
      extra.push({ uri: `powernet:${s.id}`, type: 'Power Network (โครงข่ายอำนาจ)', title: `🕸️ เครือข่ายอำนาจรัฐ ${s.name}`, sub: `Kingmaker, Rivals & Institutional Control` });
      (s.factions || []).forEach((f) => {
        extra.push({ uri: `faction:${f.name}`, type: 'Political Faction (กลุ่มการเมือง)', title: `⚖️ ${f.name} (${s.shortName})`, sub: `Power ${f.power || f.influence}% • แนวคิด ${f.ideology || f.type}` });
      });
    });

    // Intelligence Operations
    (world.intelligenceOps || []).forEach((op) => {
      extra.push({ uri: `intelop:${op.id}`, type: 'Intelligence Op (ข่าวกรอง)', title: `🕵️ ${op.label} (${op.sponsorStateId} ➔ ${op.targetStateId})`, sub: `${op.consequence}` });
    });

    // Active War Fronts
    (world.wars || []).forEach((w) => {
      (w.fronts || []).forEach((fr) => {
        extra.push({ uri: `front:${fr.id}`, type: 'War Front (แนวรบ)', title: `🔥 ${fr.name}`, sub: `${w.name} • พื้นที่ควบคุม ${fr.controlPct}%` });
      });
    });

    const filtered = !q ? extra : extra.filter((it) => it.title.toLowerCase().includes(q) || it.sub.toLowerCase().includes(q) || it.type.toLowerCase().includes(q) || it.uri.toLowerCase().includes(q));
    return [...base, ...filtered].slice(0, limit);
  };

  const _origCreateInitialWorldV200 = createInitialWorld;
  createInitialWorld = function (seed = 202611717) {
    const world = _origCreateInitialWorldV200(seed);
    ensureWorldSystemsV200(world);
    return world;
  };

  const _origMigrateWorldV200 = migrateWorld;
  migrateWorld = function (world) {
    if (!world || !world.states) return world;
    _origMigrateWorldV200(world);
    ensureWorldSystemsV200(world);
    return world;
  };

  const _origStepDayV200 = stepDay;
  stepDay = function (world, rngInstance = null) {
    if (!world._v200) {
      ensureWorldSystemsV200(world);
    }
    _origStepDayV200(world, rngInstance);
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + world.tick * 6151);
    const t = world.tick;

    // Staggered Tier 0 & Tier 1 Role-Based Decision Engine & Power Model refresh (every 15 days, 2 states per batch)
    if (t % 15 === 4) {
      const stateIds = Object.keys(world.states);
      const startIdx = (Math.floor(t / 15) * 2) % Math.max(1, stateIds.length);
      for (let k = 0; k < 2; k++) {
        const st = world.states[stateIds[(startIdx + k) % stateIds.length]];
        if (!st || st.isExiled) continue;
        const headId = st.positions?.HEAD_OF_STATE;
        const cmdId = st.positions?.SUPREME_COMMANDER;
        const intelId = st.positions?.INTELLIGENCE_CHIEF;
        [headId, cmdId, intelId].forEach((nid) => {
          const npc = nid ? world.npcs[nid] : null;
          if (npc && npc.alive && !npc.retired) {
            npc._powerDirty = true;
            evaluateNPCDecision20(world, npc, rng);
          }
        });
      }
    }

    // Political Simulation 2.0 Crisis & Stability sync (every 25 days)
    if (t % 25 === 11) {
      const liveStates = Object.values(world.states).filter((s) => !s.isExiled);
      liveStates.forEach((st) => {
        if (!st.politicalSubsystems) ensurePoliticalSimulationV200(world, st);
        const pp = st.politicalPressures || {};
        st.governmentStability = st.stability;
        st.publicApproval = st.approval;
        if (!st.playerEdited) {
          st.economicPressure = rnd1((st.economicPressure || 22) * 0.6 + (pp.economicPressure || 22) * 0.4 + (st.warExhaustion || 0) * 0.25);
          st.oppositionPressure = rnd1((st.oppositionPressure || 30) * 0.6 + (pp.oppositionStrength || 30) * 0.4);
          st.militaryLoyalty = clamp(Math.round(100 - (pp.militaryInfluence || 35) * 0.45 - (st.warExhaustion || 0) * 0.25), 18, 98);
          st.coalitionStability = st.democracyState ? st.democracyState.coalitionStability : clamp(st.stability + 2, 20, 98);
        }
      });
      const stressed = liveStates.filter((s) => s.stability < 62 || s.economicPressure > 48 || s.oppositionPressure > 52 || (s.warExhaustion || 0) > 35);
      const targetSt = stressed.length > 0 ? rng.pick(stressed) : rng.pick(liveStates);
      if (targetSt) {
        evaluatePoliticalCrisesV200(world, targetSt, rng);
      }
    }

    // Diplomacy & Covert Intelligence autonomous cycle (every 35 days)
    if (t % 35 === 19 && world.aiSandbox !== false) {
      const liveStates = Object.values(world.states).filter((s) => !s.isExiled);
      const actor = rng.pick(liveStates);
      if (actor && (actor.rivalries || []).length > 0 && actor.treasuryB > 40) {
        const targetId = rng.pick(actor.rivalries);
        if (world.states[targetId] && !world.states[targetId].isExiled) {
          const opPool = ['spy_network', 'informants', 'political_contacts', 'industrial_espionage', 'influence_operation'];
          executeCovertIntelOp(world, actor.id, targetId, rng.pick(opPool));
        }
      }
      // Conditional Alliance Evaluation for active wars
      (world.wars || []).forEach((w) => {
        ensureWarMultiFrontsV200(world, w);
        const defAllies = alliesOf(world, w.defenderId);
        defAllies.forEach((alId) => {
          const evalRes = evaluateAllyIntervention(world, alId, w.defenderId, w.attackerId, w);
          w.allyEvaluations = w.allyEvaluations || {};
          w.allyEvaluations[alId] = evalRes;
        });
      });
    }

    // Anti-Snowball, Company Influence & Emergent Story Detection (every 45 days)
    if (t % 45 === 29) {
      runNaturalAntiSnowballCycle(world, rng);
      enrichCompaniesConnectionV200(world);
      detectEmergentStories(world);
      world._reportsCache = null; // Mark reports dirty for lazy regeneration when UI opens
    }

    return world;
  };


