    IE: { code: 'EUR', name: 'ยูโร (Euro - Central Bank of Ireland)', bank: 'ธนาคารกลางไอร์แลนด์ & ECB', rateVsUSD: 0.92, intRate: 3.25, inf: 2.1, fxB: 95, goldT: 12, debtGdp: 42.0, rating: 'AA' },
    GR: { code: 'EUR', name: 'ยูโร (Euro - Bank of Greece)', bank: 'ธนาคารกลางกรีซ & ECB', rateVsUSD: 0.92, intRate: 3.25, inf: 2.8, fxB: 38, goldT: 114, debtGdp: 158.0, rating: 'BBB-' },
    PL: { code: 'PLN', name: 'ซวอตีโปแลนด์ (Polish Złoty)', bank: 'ธนาคารแห่งชาติโปแลนด์ (NBP)', rateVsUSD: 3.98, intRate: 5.75, inf: 3.8, fxB: 210, goldT: 420, debtGdp: 52.0, rating: 'A' },
    SE: { code: 'SEK', name: 'โครนาสวีเดน (Swedish Krona)', bank: 'ธนาคารกลางสวีเดน (Sveriges Riksbank)', rateVsUSD: 10.45, intRate: 3.00, inf: 1.9, fxB: 72, goldT: 125, debtGdp: 32.0, rating: 'AAA' },
    NO: { code: 'NOK', name: 'โครนนอร์เวย์ (Norwegian Krone)', bank: 'ธนาคารกลางนอร์เวย์ (Norges Bank)', rateVsUSD: 10.75, intRate: 4.50, inf: 2.6, fxB: 480, goldT: 38, debtGdp: 38.0, rating: 'AAA' },
    DK: { code: 'DKK', name: 'โครนเดนมาร์ก (Danish Krone)', bank: 'ธนาคารแห่งชาติเดนมาร์ก (Danmarks Nationalbank)', rateVsUSD: 6.86, intRate: 3.10, inf: 1.8, fxB: 98, goldT: 66, debtGdp: 30.0, rating: 'AAA' },
    CZ: { code: 'CZK', name: 'โครูนาเช็ก/โฟรินต์ (CZK / HUF)', bank: 'ธนาคารแห่งชาติเช็กเกีย-ฮังการี (CNB / MNB)', rateVsUSD: 23.2, intRate: 4.50, inf: 2.9, fxB: 155, goldT: 140, debtGdp: 46.0, rating: 'AA-' },
    RO: { code: 'RON', name: 'ลิวโรมาเนีย & บอลข่าน (Romanian Leu)', bank: 'ธนาคารแห่งชาติโรมาเนีย (BNR)', rateVsUSD: 4.58, intRate: 6.50, inf: 4.6, fxB: 78, goldT: 103, debtGdp: 51.0, rating: 'BBB' },
    UA: { code: 'UAH', name: 'ฮริฟเนียยูเครน (Ukrainian Hryvnia)', bank: 'ธนาคารแห่งชาติยูเครน (NBU)', rateVsUSD: 41.2, intRate: 13.00, inf: 8.5, fxB: 42, goldT: 27, debtGdp: 94.0, rating: 'CCC+' },
