  function calculateStateThreatPerceptionsV210(world) {
    if (!world || !world.states) return;
    const states = Object.values(world.states);
    const potentials = {};
    states.forEach((s) => {
      potentials[s.id] = calculateStateCombatPotential(world, s.id).totalPower || 1000;
    });

    states.forEach((st) => {
      st.threatPerception = {};
      const myPow = Math.max(400, potentials[st.id] || 1000);
      states.forEach((other) => {
        if (other.id === st.id || other.isExiled) return;
        const otherPow = potentials[other.id] || 1000;
        const powerRatio = otherPow / myPow;
        if (powerRatio < 1.15 && !(st.rivalries || []).includes(other.id) && (st.relations?.[other.id]?.score || 60) >= 50) {
          st.threatPerception[other.id] = 10;
          return;
        }
        const rel = st.relations?.[other.id] || { score: 55, borderTension: 15 };
        const dist = (st.mapCenter && other.mapCenter) ? Math.hypot(st.mapCenter.x - other.mapCenter.x, st.mapCenter.y - other.mapCenter.y) : 300;
        const proximityFactor = dist < 95 ? 28 : dist < 185 ? 16 : dist < 280 ? 8 : 2;
        const policyBonus = other.policy === 'Expansionist' ? 24 : other.policy === 'Militarist' ? 18 : other.policy === 'Naval Expansion' ? 12 : 0;
        const expansionBonus = Math.min(30, ((other.occupiedCities || []).length * 10) + (getWarsOf(world, other.id).length * 12));
        const hostilityBonus = Math.max(0, 65 - (rel.score || 55)) * 0.65 + (rel.borderTension || 15) * 0.35;
        const sizeFactor = clamp(Math.round(Math.log2(Math.max(1, powerRatio)) * 14), 0, 32);

        const rawThreat = Math.round(proximityFactor + policyBonus + expansionBonus + hostilityBonus + sizeFactor);
        st.threatPerception[other.id] = clamp(rawThreat, 5, 99);
      });
    });
  }

