      const winnersTxt = (lastLaw && lastLaw.winnersLabel) || (lastPol && lastPol.winnersLabel) || 'กลุ่มฐานเสียงรัฐบาลและเครือข่ายผู้ถืออำนาจหลัก';
      const losersTxt = (lastLaw && lastLaw.losersLabel) || (lastPol && lastPol.losersLabel) || 'กลุ่มทุนคู่แข่ง ฝ่ายค้าน และผู้เสียผลประโยชน์ทางเศรษฐกิจ';
      const sponsorTxt = (lastLaw && lastLaw.sponsorLabel) || (lastPol && lastPol.sponsorLabel) || 'กลุ่มอิทธิพลการเมืองและล็อบบี้ยิสต์หลังม่าน';
