  function resolveStateObjV230(world, sOrId) {
    if (!world || !world.states || !sOrId) return null;
    if (typeof sOrId === 'string') return world.states[sOrId] || null;
    if (typeof sOrId === 'object' && sOrId !== null) return sOrId;
    return null;
  }

  function ensureSummitV230(world) {
    if (!world || !world.states) return;
    if (!world.summitV230) {
      // Caps: 8 active talks, 80 treaties, 60 archive entries (drop oldest)
      world.summitV230 = {
        nextId: 1,
        talks: [],
        treaties: [],
        archive: [],
        cooldowns: {},
        talkCountsByType: {
          PEACE_TREATY: 0,
          CEASEFIRE: 0,
          TRADE_ACCORD: 0,
          SANCTION_RELIEF: 0,
          SECURITY_PACT: 0
        }
      };
    }
    if (!world.summitV230.cooldowns) world.summitV230.cooldowns = {};
    if (!world.summitV230.talkCountsByType) {
      world.summitV230.talkCountsByType = {
        PEACE_TREATY: 0,
        CEASEFIRE: 0,
        TRADE_ACCORD: 0,
        SANCTION_RELIEF: 0,
        SECURITY_PACT: 0
      };
    }
    Object.values(world.states).forEach((st) => {
      if (st.trustV230 === undefined || st.trustV230 === null || Number.isNaN(st.trustV230)) {
        st.trustV230 = 70;
      }
      if (!st.truceUntil) st.truceUntil = {};
    });
  }

  function pickNegotiatorsV230(world, stateId) {
    const st = resolveStateObjV230(world, stateId);
    if (!st) return { headId: null, chiefId: null, hardlinerId: null, head: null, chief: null, hardliner: null };
    const pos = st.positions || {};
    const getValidNpc = (id) => (id && world.npcs && world.npcs[id] && world.npcs[id].alive && !world.npcs[id].retired) ? world.npcs[id] : null;
    if (st._negCacheV230 && (world.tick - st._negCacheV230.tick) < 30) {
      const c = st._negCacheV230.res;
      if ((!c.headId || getValidNpc(c.headId)) && (!c.chiefId || getValidNpc(c.chiefId))) return c;
    }

    let head = getValidNpc(pos.HEAD_OF_STATE) || getValidNpc(pos.PRIME_MINISTER);
    let chief = getValidNpc(pos.FOREIGN_MINISTER) || getValidNpc(pos.DIPLOMAT) || getValidNpc(pos.FINANCE_MINISTER) || getValidNpc(pos.INTERIOR_MINISTER);
    let hardliner = getValidNpc(pos.DEFENSE_MINISTER) || getValidNpc(pos.SUPREME_COMMANDER) || getValidNpc(pos.ARMY_CHIEF) || getValidNpc(pos.OPPOSITION_LEADER) || getValidNpc(pos.LOGISTICS_CHIEF);

    if (!head || !chief || !hardliner) {
      const aliveNpcs = Object.values(world.npcs || {}).filter((n) => n && n.alive && !n.retired && n.stateId === st.id);
      if (!head || !chief) {
        const byDip = aliveNpcs.slice().sort((a, b) => ((b.diplomaticAbility || 50) - (a.diplomaticAbility || 50)));
        if (!head) head = byDip[0] || null;
        if (!chief) chief = byDip.find((n) => !head || n.id !== head.id) || head || null;
      }
      if (!hardliner) {
        const byAgg = aliveNpcs.slice().sort((a, b) => (((b.personality?.aggression || 50) + (b.personality?.ambition || 50)) - ((a.personality?.aggression || 50) + (a.personality?.ambition || 50))));
        hardliner = byAgg.find((n) => (!head || n.id !== head.id) && (!chief || n.id !== chief.id)) || head || null;
      }
    }

    const resObj = {
      headId: head ? head.id : null,
      chiefId: chief ? chief.id : null,
      hardlinerId: hardliner ? hardliner.id : null,
      head,
      chief,
      hardliner
    };
    st._negCacheV230 = { tick: world.tick || 0, res: resObj };
    return resObj;
  }

  function pickHostV230(world, aId, bId) {
    const stA = resolveStateObjV230(world, aId);
    const stB = resolveStateObjV230(world, bId);
    if (!stA || !stB) return { hostId: null, hostCityId: null };

    const candidates = Object.values(world.states).filter((s) => {
      if (!s || s.isExiled || s.id === stA.id || s.id === stB.id) return false;
      const warsS = getWarsOf(world, s.id);
      if (warsS.some((w) => w.attackerId === stA.id || w.defenderId === stA.id || w.attackerId === stB.id || w.defenderId === stB.id)) return false;
      const relA = s.relations?.[stA.id]?.status || 'Peace';
      const relB = s.relations?.[stB.id]?.status || 'Peace';
      if (relA === 'War' || relB === 'War') return false;
      const alliedA = relA === 'Alliance';
      const alliedB = relB === 'Alliance';
      if (alliedA !== alliedB) return false; // Not allied to only one side
      return true;
    });

    let bestHost = null;
    let bestScore = -999;
    for (let i = 0; i < candidates.length; i++) {
      const c = candidates[i];
      const scoreA = c.relations?.[stA.id]?.score ?? 50;
      const scoreB = c.relations?.[stB.id]?.score ?? 50;
      const minRel = Math.min(scoreA, scoreB);
      if (minRel < 35) continue;
      const sameRegionBonus = (c.region === stA.region || c.region === stB.region) ? 12 : 0;
      const total = minRel + sameRegionBonus + (c.trustV230 || 70) * 0.1;
      if (total > bestScore) {
        bestScore = total;
        bestHost = c;
      }
    }

    if (bestHost) {
      const cap = stateCities(world, bestHost.id).find((c) => c.isCapital) || stateCities(world, bestHost.id)[0] || null;
      return { hostId: bestHost.id, hostCityId: cap ? cap.id : null };
    }

    const higherTrustSt = ((stA.trustV230 ?? 70) >= (stB.trustV230 ?? 70)) ? stA : stB;
    const venueCap = stateCities(world, higherTrustSt.id).find((c) => c.isCapital) || stateCities(world, higherTrustSt.id)[0] || null;
    return { hostId: null, hostCityId: venueCap ? venueCap.id : null };
  }

  function sanctionPainV230(world, sOrId) {
    const st = resolveStateObjV230(world, sOrId);
    if (!st || !world.tradeWarV230 || !Array.isArray(world.tradeWarV230.measures)) return 0;
    let sumLevels = 0;
    const measures = world.tradeWarV230.measures;
    for (let i = 0; i < measures.length; i++) {
      const m = measures[i];
      if (m && m.status === 'ACTIVE' && m.targetId === st.id) {
        sumLevels += (m.level || 0);
      }
    }
    return clamp(20 * sumLevels, 0, 100);
  }

  function pressureV230(world, sOrId) {
    const s = resolveStateObjV230(world, sOrId);
    if (!s) return 0;
    const warEx = clamp(s.warExhaustion || 0, 0, 100);
    const stab = clamp(s.stability ?? 70, 0, 100);
    const appr = clamp(s.approval ?? 70, 0, 100);
    const debtGdp = s.sovereignDebt?.debtToGdpPct ?? 60;
    const debtTerm = clamp((debtGdp - 60) / 60, 0, 1) * 100;
    const sPain = sanctionPainV230(world, s);
    const val = 0.40 * warEx + 0.20 * (100 - stab) + 0.10 * (100 - appr) + 0.15 * debtTerm + 0.15 * sPain;
    return clamp(val, 0, 100);
  }

  function temperamentV230(world, sOrId, negs = null) {
    const s = resolveStateObjV230(world, sOrId);
    if (!s) return 50;
    const resolvedNegs = negs || pickNegotiatorsV230(world, s.id);
    const head = (resolvedNegs.head) || (resolvedNegs.headId && world.npcs ? world.npcs[resolvedNegs.headId] : null);
    const chief = (resolvedNegs.chief) || (resolvedNegs.chiefId && world.npcs ? world.npcs[resolvedNegs.chiefId] : null);
    const aggr = clamp(head?.personality?.aggression ?? 50, 0, 100);
    const caut = clamp(head?.personality?.caution ?? 50, 0, 100);
    const dipAbil = clamp(chief?.diplomaticAbility ?? 60, 0, 100);
    const integ = clamp(head?.personality?.integrity ?? 55, 0, 100);
    const val = 0.40 * (100 - aggr) + 0.20 * caut + 0.20 * dipAbil + 0.20 * integ;
    return clamp(val, 0, 100);
  }

  function willingnessV230(world, sOrId, otherOrId, negs = null) {
    const s = resolveStateObjV230(world, sOrId);
    const other = resolveStateObjV230(world, otherOrId);
    if (!s) return 0;
    const otherId = other ? other.id : String(otherOrId || '');
    const p = pressureV230(world, s);
    const t = temperamentV230(world, s, negs);
    const relScore = s.relations?.[otherId]?.score ?? 50;
    return clamp(0.55 * p + 0.45 * t + 0.15 * (relScore - 40), 0, 100);
  }

  function clauseCostV230(world, clause, acceptorStateId) {
    if (!clause) return 5;
    const acc = resolveStateObjV230(world, acceptorStateId);
    const val = clause.value || {};
    switch (clause.type) {
      case 'TERRITORY_SWAP': {
        const cityIds = Array.isArray(val.cityIds) ? val.cityIds : [];
        if (cityIds.length === 0) return 8;
        let lost = 0;
        let regained = 0;
        cityIds.forEach((cid) => {
          const c = world.cities && world.cities[cid];
          if (!c) return;
          if (acc && c.stateId === acc.id && c.originalOwnerId !== acc.id) lost++;
          else if (acc && c.originalOwnerId === acc.id && c.stateId !== acc.id) regained++;
        });
        if (lost === 0 && regained === 0) lost = Math.max(1, val.count || 1);
        return 18 * lost - 10 * regained;
      }
      case 'DMZ':
        return 8;
      case 'SANCTION_LIFT': {
        const lvls = Math.max(1, Number(val.levels || 1));
        const isImposer = acc && clause.proposer !== acc.id && (world.tradeWarV230?.measures || []).some((m) => m.status === 'ACTIVE' && m.imposerId === acc.id);
        return isImposer ? (10 * lvls) : (5 * lvls);
      }
      case 'RESOURCE_CONCESSION': {
        const pct = clamp(Number(val.pct || 4), 2, 12);
        return pct * 3;
      }
      case 'REPARATIONS': {
        const amountB = Math.max(2, Number(val.amountB || 15));
        const gdpB = Math.max(50, acc ? (acc.gdpB || 200) : 200);
        return (amountB / gdpB) * 400;
      }
      case 'TROOP_WITHDRAWAL':
        return 10;
      case 'PRISONER_EXCHANGE':
        return 2;
      case 'TRADE_PREFERENCE':
        return 6;
      case 'JOINT_COMMISSION':
        return 1;
      case 'REFUGEE_RETURN_GUARANTEE':
        return 4;
      default:
        return 5;
    }
  }

  function formatClauseValueTextV230(world, clause) {
    if (!clause) return '-';
    const v = clause.value || {};
    switch (clause.type) {
      case 'TERRITORY_SWAP': {
        const cNames = (v.cityIds || []).map((id) => world.cities?.[id] ? cityNameTh(world.cities[id]) : id).filter(Boolean);
        return cNames.length > 0 ? `ส่งคืนเมือง ${cNames.join(', ')}` : `ส่งคืนเมืองยึดครอง ${v.count || 1} แห่ง`;
      }
      case 'DMZ':
        return `เขตปลอดทหาร ${v.days || 365} วัน`;
      case 'SANCTION_LIFT':
        return `ลดมาตรการคว่ำบาตรลง ${v.levels || 2} ระดับ`;
      case 'RESOURCE_CONCESSION':
        return `แบ่งรายได้ทรัพยากร ${v.pct || 5}% นาน ${v.months || 24} เดือน`;
      case 'REPARATIONS':
        return `ชำระค่าปฏิกรรม $${v.amountB || 20}B ผ่อน ${v.months || 24} เดือน`;
      case 'TROOP_WITHDRAWAL':
        return `ถอนกำลังทหารแนวหน้า ${v.pct || 40}%`;
      case 'PRISONER_EXCHANGE':
        return `แลกเปลี่ยนเชลยศึก ${v.count || 1200} นาย`;
      case 'TRADE_PREFERENCE':
        return `ลดกำแพงภาษีต่างตอบแทน ${v.cutPct || 15}%`;
      case 'JOINT_COMMISSION':
        return `ตั้งคณะกรรมาธิการร่วม ${v.years || 3} ปี`;
      case 'REFUGEE_RETURN_GUARANTEE':
        return `รับประกันส่งกลับผู้ลี้ภัย ${v.months || 12} เดือน (เร่ง 2x)`;
      default:
        return JSON.stringify(v);
    }
  }

  function buildInitialClausesForSummitV230(world, stA, stB, typeId, rng) {
    const clauses = [];
    let cid = 1;
    const occupiedByA = Object.values(world.cities || {}).filter((c) => c.isOccupied && c.stateId === stA.id && c.originalOwnerId === stB.id);
    const occupiedByB = Object.values(world.cities || {}).filter((c) => c.isOccupied && c.stateId === stB.id && c.originalOwnerId === stA.id);
    const allOcc = occupiedByA.concat(occupiedByB).slice(0, 2);

    if (typeId === 'PEACE_TREATY') {
      clauses.push({
        id: cid++,
        type: 'TROOP_WITHDRAWAL',
        proposer: stA.id,
        value: { pct: rng.pick([35, 50, 65]) },
        status: 'PROPOSED',
        counters: 0
      });
      if (allOcc.length > 0) {
        clauses.push({
          id: cid++,
          type: 'TERRITORY_SWAP',
          proposer: occupiedByA.length > 0 ? stB.id : stA.id,
          value: { cityIds: allOcc.map((c) => c.id), count: allOcc.length },
          status: 'PROPOSED',
          counters: 0
        });
      }
      clauses.push({
        id: cid++,
        type: 'PRISONER_EXCHANGE',
        proposer: stB.id,
        value: { count: rng.int(800, 3200) },
        status: 'PROPOSED',
        counters: 0
      });
    } else if (typeId === 'CEASEFIRE') {
      clauses.push({
        id: cid++,
        type: 'DMZ',
        proposer: stA.id,
        value: { days: rng.pick([180, 365, 730]) },
        status: 'PROPOSED',
        counters: 0
      });
      clauses.push({
        id: cid++,
        type: 'PRISONER_EXCHANGE',
        proposer: stB.id,
        value: { count: rng.int(500, 2000) },
        status: 'PROPOSED',
        counters: 0
      });
    } else if (typeId === 'TRADE_ACCORD') {
      clauses.push({
        id: cid++,
        type: 'TRADE_PREFERENCE',
        proposer: stA.id,
        value: { cutPct: rng.pick([10, 15, 20]) },
        status: 'PROPOSED',
        counters: 0
      });
      clauses.push({
        id: cid++,
        type: 'JOINT_COMMISSION',
        proposer: stB.id,
        value: { years: rng.pick([2, 3, 5]) },
        status: 'PROPOSED',
        counters: 0
      });
    } else if (typeId === 'SANCTION_RELIEF') {
      clauses.push({
        id: cid++,
        type: 'SANCTION_LIFT',
        proposer: stB.id,
        value: { levels: rng.pick([1, 2, 3]) },
        status: 'PROPOSED',
        counters: 0
      });
      clauses.push({
        id: cid++,
        type: 'TRADE_PREFERENCE',
        proposer: stA.id,
        value: { cutPct: rng.pick([10, 15]) },
        status: 'PROPOSED',
        counters: 0
      });
    } else if (typeId === 'SECURITY_PACT') {
      clauses.push({
        id: cid++,
        type: 'JOINT_COMMISSION',
        proposer: stA.id,
        value: { years: rng.pick([3, 4, 5]) },
        status: 'PROPOSED',
        counters: 0
      });
      clauses.push({
        id: cid++,
        type: 'TRADE_PREFERENCE',
        proposer: stB.id,
        value: { cutPct: 12 },
        status: 'PROPOSED',
        counters: 0
      });
    }
    return clauses;
  }

  function startSummitV230(world, aId, bId, typeId = 'PEACE_TREATY', opts = { forced: false }) {
    ensureWorldSystemsV230(world);
    opts = opts || { forced: false };
    const stA = resolveStateObjV230(world, aId);
    const stB = resolveStateObjV230(world, bId);
    if (!stA || !stB || stA.id === stB.id) {
      return { ok: false, reason: 'ต้องเลือกรัฐคู่เจรจา 2 รัฐที่แตกต่างกันและมีอยู่จริงในโลก' };
    }
    const spec = SUMMIT_TYPES_V230[typeId];
    if (!spec) {
      return { ok: false, reason: 'ประเภทการประชุมซัมมิตไม่ถูกต้อง' };
    }

    const pairKey = (stA.id < stB.id ? `${stA.id}_${stB.id}` : `${stB.id}_${stA.id}`) + `_${typeId}`;
    const cdUntil = world.summitV230.cooldowns[pairKey] || 0;
    if (cdUntil > world.tick && !opts.ignoreCooldown) {
      return {
        ok: false,
        reason: `การเจรจา ${spec.labelTh} ระหว่าง ${shortNameTh(stA)} และ ${shortNameTh(stB)} เพิ่งล้มเหลว ต้องรอพ้นระยะพักการเจรจาอีก ${cdUntil - world.tick} วัน`
      };
    }

    if (world.summitV230.talks.length >= 8) {
      return { ok: false, reason: 'จำนวนโต๊ะเจรจาซัมมิตที่เปิดอยู่ในโลกถึงขีดจำกัดสูงสุด 8 โต๊ะแล้ว' };
    }

    const activeForA = world.summitV230.talks.filter((t) => t.partyA === stA.id || t.partyB === stA.id).length;
    const activeForB = world.summitV230.talks.filter((t) => t.partyA === stB.id || t.partyB === stB.id).length;
    if (activeForA >= 2 || activeForB >= 2) {
      return { ok: false, reason: `${activeForA >= 2 ? shortNameTh(stA) : shortNameTh(stB)} มีโต๊ะเจรจาซัมมิตที่กำลังดำเนินการอยู่ครบ 2 แห่งแล้ว` };
    }

    const duplicate = world.summitV230.talks.find((t) =>
      t.type === typeId && ((t.partyA === stA.id && t.partyB === stB.id) || (t.partyA === stB.id && t.partyB === stA.id))
    );
    if (duplicate) {
      return { ok: false, reason: `มีการประชุม ${spec.labelTh} ระหว่าง ${shortNameTh(stA)} และ ${shortNameTh(stB)} เปิดดำเนินการอยู่แล้ว` };
    }

    const atWar = (world.wars || []).some((w) =>
      w.status === 'War' && ((w.attackerId === stA.id && w.defenderId === stB.id) || (w.attackerId === stB.id && w.defenderId === stA.id))
    );
    if ((typeId === 'PEACE_TREATY' || typeId === 'CEASEFIRE') && !atWar) {
      return { ok: false, reason: `ไม่สามารถเปิดโต๊ะเจรจา ${spec.labelTh} ได้ เนื่องจาก ${shortNameTh(stA)} และ ${shortNameTh(stB)} ไม่ได้อยู่ในภาวะสงครามต่อกัน` };
    }

    if (!opts.forced) {
      if (typeId === 'SANCTION_RELIEF') {
        const hasHeavySanction = (world.tradeWarV230?.measures || []).some((m) =>
          m.status === 'ACTIVE' && m.level >= 3 && ((m.imposerId === stA.id && m.targetId === stB.id) || (m.imposerId === stB.id && m.targetId === stA.id))
        );
        if (!hasHeavySanction) {
          return { ok: false, reason: 'การเจรจายกเลิกคว่ำบาตร (SANCTION_RELIEF) ต้องมีมาตรการคว่ำบาตรระดับ 3 ขึ้นไปที่มีผลบังคับใช้อยู่' };
        }
      } else if (typeId === 'TRADE_ACCORD') {
        const hasMeasure = (world.tradeWarV230?.measures || []).some((m) =>
          m.status === 'ACTIVE' && ((m.imposerId === stA.id && m.targetId === stB.id) || (m.imposerId === stB.id && m.targetId === stA.id))
        );
        const relStatus = stA.relations?.[stB.id]?.status || 'Peace';
        if (!hasMeasure && relStatus !== 'Hostile' && relStatus !== 'Truce') {
          return { ok: false, reason: 'ข้อตกลงสงบศึกการค้าต้องมีมาตรการกีดกันทางการค้าหรือสถานะตึงเครียดระหว่างกัน' };
        }
      } else if (typeId === 'SECURITY_PACT') {
        const relStatus = stA.relations?.[stB.id]?.status || 'Peace';
        if (relStatus !== 'Peace' && relStatus !== 'Alliance') {
          return { ok: false, reason: 'กติกาสัญญาความมั่นคงร่วมต้องทำระหว่างรัฐที่มีสถานะสันติภาพหรือพันธมิตรต่อกันเท่านั้น' };
        }
      }
    }

    const rng = new SeededRNG((world.seed || 2026) + (world.tick || 1) * 197 + hashStr(stA.id + stB.id + typeId));
    const hostInfo = pickHostV230(world, stA.id, stB.id);
    const negA = pickNegotiatorsV230(world, stA.id);
    const negB = pickNegotiatorsV230(world, stB.id);
    const clauses = buildInitialClausesForSummitV230(world, stA, stB, typeId, rng);
    const venueCity = (hostInfo.hostCityId && world.cities[hostInfo.hostCityId]) || stateCities(world, stA.id)[0] || Object.values(world.cities)[0];
    const venueName = venueCity ? cityNameTh(venueCity) : 'นครเจนีวา';
    const hostState = hostInfo.hostId ? world.states[hostInfo.hostId] : null;

    const talkId = `SUMMIT_${world.summitV230.nextId++}`;
    const prepDuration = rng.int(SUMMIT_STAGE_DURATIONS_V230.PREPARATION.min, SUMMIT_STAGE_DURATIONS_V230.PREPARATION.max);
    const maxRounds = rng.int(2, 4);

    const talk = {
      id: talkId,
      type: typeId,
      partyA: stA.id,
      partyB: stB.id,
      hostId: hostInfo.hostId,
      hostCityId: venueCity ? venueCity.id : null,
      startTick: world.tick,
      stage: 'PREPARATION',
      stageDay: 0,
      stageTargetDays: prepDuration,
      round: 1,
      maxRounds,
      clauses,
      negotiators: {
        A: { headId: negA.headId, chiefId: negA.chiefId, hardlinerId: negA.hardlinerId },
        B: { headId: negB.headId, chiefId: negB.chiefId, hardlinerId: negB.hardlinerId }
      },
      log: [
        { tick: world.tick, text: `เริ่มต้นเตรียมการประชุม ${spec.labelTh} ณ เมือง${venueName} (${clauses.length} เงื่อนไขตั้งต้น)` }
      ],
      spoilers: 0,
      leakPenalty: 0,
      outcome: null
    };

    world.summitV230.talks.push(talk);
    world.summitV230.talkCountsByType[typeId] = (world.summitV230.talkCountsByType[typeId] || 0) + 1;

    // Record NPC memories at start of talk
    const headAName = negA.head ? negA.head.name : shortNameTh(stA);
    const headBName = negB.head ? negB.head.name : shortNameTh(stB);
    const chiefAName = negA.chief ? negA.chief.name : headAName;
    const chiefBName = negB.chief ? negB.chief.name : headBName;
    [negA.head, negA.chief, negA.hardliner].filter(Boolean).forEach((npc) => {
      recordNPCMemory(npc, world.year, `เข้าร่วมโต๊ะเจรจา ${spec.labelTh} กับผู้แทน ${headBName} แห่ง ${shortNameTh(stB)} ณ เมือง${venueName}`);
    });
    [negB.head, negB.chief, negB.hardliner].filter(Boolean).forEach((npc) => {
      recordNPCMemory(npc, world.year, `เข้าร่วมโต๊ะเจรจา ${spec.labelTh} กับผู้แทน ${headAName} แห่ง ${shortNameTh(stA)} ณ เมือง${venueName}`);
    });

    // >= 6 rich templates for PREPARATION stage
    const prepTemplates = [
      `🕊️✈️ [เปิดฉากเตรียมการประชุมซัมมิต — ณ ${venueName}] คณะทูตชุดล่วงหน้าของ ${chiefAName} แห่ง ${stA.name} และ ${chiefBName} แห่ง ${stB.name} เดินทางถึงเมือง${venueName}${hostState ? ` โดยมี ${shortNameTh(hostState)} ทำหน้าที่เจ้าภาพคนกลาง` : ''} เพื่อวางกรอบ "${spec.labelTh}" จำนวน ${clauses.length} ข้อ ท่ามกลางแรงกดดันยุทธศาสตร์ของทั้งสองฝ่าย (${Math.round(pressureV230(world, stA))}% ต่อ ${Math.round(pressureV230(world, stB))}%) การติดต่อทางลับหลังม่านดำเนินไปอย่างตึงเครียดตลอด ${prepDuration} วันก่อนพิธีเปิดอย่างเป็นทางการ`,
      `🕊️📨 [ทูตลับเดินสายปูทางซัมมิตที่ ${venueName}] รัฐบาลของ ${headAName} (${shortNameTh(stA)}) และ ${headBName} (${shortNameTh(stB)}) เห็นชอบให้ส่งคณะผู้แทนระดับสูงเข้าหารือนอกรอบที่เมือง${venueName} เพื่อเตรียมจัดประชุม "${spec.labelTh}" พร้อมร่างวาระเร่งด่วน ${clauses.length} ประเด็น แหล่งข่าวการทูตเผยว่าทั้งสองฝ่ายต่างตั้งเงื่อนไขขั้นต่ำอย่างรัดกุมเพื่อชิงความได้เปรียบก่อนขึ้นโต๊ะเจรจาจริง`,
      `🕊️🏛️ [สัญญาณสันติภาพและการทูตที่ ${venueName}] ขบวนเครื่องบินพิเศษของ ${chiefAName} (${shortNameTh(stA)}) และ ${chiefBName} (${shortNameTh(stB)}) ลงจอดที่ท่าอากาศยานเมือง${venueName} เพื่อเริ่มต้นระยะเตรียมการประชุม "${spec.labelTh}" เป็นเวลา ${prepDuration} วัน ท่ามกลางมาตรการรักษาความปลอดภัยขั้นสูงสุดและข่าวลือเรื่องข้อแลกเปลี่ยนเชิงยุทธศาสตร์ที่รั่วไหลออกสู่สื่อสากล`,
      `🕊️🤝 [เดินเครื่องกลไกซัมมิต ${shortNameTh(stA)}–${shortNameTh(stB)}] ภายหลังการประสานงานผ่านช่องทางลับนานหลายสัปดาห์ ${headAName} แห่ง ${stA.name} และ ${headBName} แห่ง ${stB.name} อนุมัติการเปิดโต๊ะเจรจา "${spec.labelTh}" ณ เมือง${venueName} โดยมีหัวข้อต่อรองเริ่มต้น ${clauses.length} ข้อ และดัชนีความพร้อมเจรจาอยู่ที่ ${Math.round(willingnessV230(world, stA, stB))}% และ ${Math.round(willingnessV230(world, stB, stA))}% ตามลำดับ`,
      `🕊️🌐 [ทั่วโลกจับตาซัมมิตประวัติศาสตร์ ณ ${venueName}] กระทรวงการต่างประเทศของ ${stA.name} และ ${stB.name} แถลงกำหนดการประชุม "${spec.labelTh}" ที่เมือง${venueName} โดยคณะทำงานของ ${chiefAName} และ ${chiefBName} เริ่มตรวจสอบร่างเอกสารข้อตกลง ${clauses.length} มาตราอย่างละเอียด เพื่อหวังคลี่คลายวิกฤตการณ์ที่ยืดเยื้อ`,
      `🕊️🕵️ [เบื้องหลังการเตรียมซัมมิตที่ ${venueName}] คณะที่ปรึกษาความมั่นคงของ ${headAName} (${shortNameTh(stA)}) และ ${headBName} (${shortNameTh(stB)}) เปิดห้องประชุมลับที่โรงแรมที่พักในเมือง${venueName} เพื่อกำหนดเส้นแดงในการเจรจา "${spec.labelTh}" จำนวน ${clauses.length} ข้อ ก่อนที่การประชุมเต็มคณะจะเปิดฉากขึ้นในอีก ${prepDuration} วันข้างหน้า`
    ];
    addChronicle(world, 'SUMMIT', rng.pick(prepTemplates), stA.id, {
      secondStateId: stB.id,
      cityId: venueCity ? venueCity.id : null,
      personId: negA.chiefId || negA.headId,
      summitId: talk.id
    });

    return { ok: true, reason: 'เปิดโต๊ะเจรจาซัมมิตสำเร็จ', talkId: talk.id, talk };
  }

  function appendTalkLogV230(talk, tick, text) {
    if (!talk.log) talk.log = [];
    talk.log.unshift({ tick, text });
    if (talk.log.length > 12) talk.log.length = 12; // cap 12
  }

  function transferCityV230(world, cityId, newOwnerId) {
    if (world.newWorld && world.cities[cityId]?.capturePolicy === 'CIVIC_NEUTRAL') return {ok:false,code:'CIVIC_NEUTRAL',reason:'เมืองกลางอยู่ภายใต้ราชสำนัก'};
    if (world.newWorld && world.cities[cityId]?.locationType === 'HOLDING') return {ok:false,code:'USE_ASSET_CAMPAIGN',reason:'ต้องผ่านภารกิจอาณาเขตที่มีผู้รับผิดชอบและกำลังจริง'};
    const city = world.cities && world.cities[cityId];
    const newOwner = resolveStateObjV230(world, newOwnerId);
    if (!city || !newOwner) return { ok: false };
    ensureCityOccupationFields(world, city);
    const prevOwnerId = city.stateId;
    if (prevOwnerId === newOwner.id) return { ok: true, city };

    const wasExiled = !!newOwner.isExiled;
    city.stateId = newOwner.id;
    city.currentOwnerId = newOwner.id;
    city.isFrontline = false;
    city.threatLevel = 10;
    if (city.originalOwnerId === newOwner.id) {
      city.isOccupied = false;
      city.assimilation = 100;
      city.unrest = Math.min(20, city.unrest || 15);
      city.resentment = 0;
      city.insurgentCells = 0;
    } else {
      city.isOccupied = true;
      city.assimilation = 35;
      city.unrest = 30;
      city.resentment = 15;
    }
    if (wasExiled && typeof restoreExiledState === 'function') {
      restoreExiledState(world, newOwner.id, city.id, 'ได้รับคืนดินแดนตามสนธิสัญญาสันติภาพ');
    }
    if (typeof syncCityIndex === 'function') syncCityIndex(world);
    return { ok: true, city };
  }

  function applyTreatyEffectsV230(world, talk) {
    const stA = resolveStateObjV230(world, talk.partyA);
    const stB = resolveStateObjV230(world, talk.partyB);
    if (!stA || !stB) return null;

    const acceptedClauses = (talk.clauses || []).filter((c) => c.status === 'ACCEPTED');
    const obligations = [];
    const effectsHistory = [];

    if (talk.type === 'PEACE_TREATY') {
      const activeWar = (world.wars || []).find((w) =>
        w.status === 'War' && ((w.attackerId === stA.id && w.defenderId === stB.id) || (w.attackerId === stB.id && w.defenderId === stA.id))
      );
      if (activeWar) {
        const potA = (typeof calculateStateCombatPotential === 'function' ? calculateStateCombatPotential(world, stA.id)?.totalPower : stA.gdpB) || 100;
        const potB = (typeof calculateStateCombatPotential === 'function' ? calculateStateCombatPotential(world, stB.id)?.totalPower : stB.gdpB) || 100;
        const diffRatio = Math.abs(potA - potB) / Math.max(1, Math.max(potA, potB));
        const winnerId = diffRatio <= 0.15 ? null : (potA > potB ? stA.id : stB.id);
        const loserId = diffRatio <= 0.15 ? null : (potA > potB ? stB.id : stA.id);
        endWarPeace(world, activeWar, winnerId, loserId, 'NEGOTIATED_PEACE');
        effectsHistory.push(`ยุติสงคราม ${activeWar.name || (shortNameTh(stA) + '-' + shortNameTh(stB))} ด้วยสนธิสัญญาสันติภาพ`);
      }
      // Link 5: Reset warPlan and set logisticsDirty = true on both parties
      stA.warPlan = null;
      stB.warPlan = null;
      stA.logisticsDirty = true;
      stB.logisticsDirty = true;
    } else if (talk.type === 'CEASEFIRE') {
      const activeWarCF = (world.wars || []).find((w) =>
        w.status === 'War' && ((w.attackerId === stA.id && w.defenderId === stB.id) || (w.attackerId === stB.id && w.defenderId === stA.id))
      );
      setDiplomaticStatus(world, stA.id, stB.id, 'Truce');
      if (!stA.truceUntil) stA.truceUntil = {};
      if (!stB.truceUntil) stB.truceUntil = {};
      stA.truceUntil[stB.id] = world.tick + 180;
      stB.truceUntil[stA.id] = world.tick + 180;
      // Link 5: Clear world.fieldArmies of that war, reset warPlan = null, set logisticsDirty = true
      Object.values(world.fieldArmies || {}).forEach((f) => {
        if (f && ((activeWarCF && f.warId === activeWarCF.id) || f.stateId === stA.id || f.stateId === stB.id)) {
          delete world.fieldArmies[f.id];
        }
      });
      stA.warPlan = null;
      stB.warPlan = null;
      stA.logisticsDirty = true;
      stB.logisticsDirty = true;
      effectsHistory.push(`ประกาศหยุดยิง ถอนกองทัพสนาม รีเซ็ตแผนการรบ และตั้งสถานะพักรบ (Truce) 180 วัน`);
    } else if (talk.type === 'TRADE_ACCORD') {
      liftMeasuresBetweenV230(world, stA.id, stB.id, 'RELAX');
      stA.gdpB = rnd1(stA.gdpB * 1.003);
      stB.gdpB = rnd1(stB.gdpB * 1.003);
      if (stA.relations?.[stB.id]) stA.relations[stB.id].score = clamp((stA.relations[stB.id].score || 50) + 8, 0, 100);
      if (stB.relations?.[stA.id]) stB.relations[stA.id].score = clamp((stB.relations[stA.id].score || 50) + 8, 0, 100);
      effectsHistory.push(`ผ่อนปรนมาตรการการค้า กระตุ้น GDP ทั้งสองฝ่าย +0.3% และเพิ่มความสัมพันธ์ +8`);
    } else if (talk.type === 'SANCTION_RELIEF') {
      liftMeasuresBetweenV230(world, stA.id, stB.id, 'LIFT');
      effectsHistory.push(`ยกเลิกมาตรการคว่ำบาตรทางเศรษฐกิจและการค้าระหว่างกันทั้งหมด`);
    } else if (talk.type === 'SECURITY_PACT') {
      setDiplomaticStatus(world, stA.id, stB.id, 'Alliance');
      if (!world.alliances) world.alliances = [];
      const existingAl = world.alliances.find((a) => a.members && a.members.includes(stA.id) && a.members.includes(stB.id));
      if (!existingAl) {
        world.alliances.push({
          id: 'ALLIANCE_AI_' + (++world.nextId),
          name: `กติกาสัญญาความมั่นคงร่วม ${shortNameTh(stA)}–${shortNameTh(stB)} (${stA.shortName}-${stB.shortName} Security Pact)`,
          type: 'Collective Defence',
          category: 'MILITARY_DEFENSE',
          members: [stA.id, stB.id],
          foundedYear: world.year,
          cohesion: 82,
          memberStatesData: {},
          recentActions: []
        });
      }
      effectsHistory.push(`สถาปนาพันธมิตรป้องกันร่วมทางทหาร (MILITARY_DEFENSE)`);
    }

    // Apply every accepted clause
    acceptedClauses.forEach((cl) => {
      const v = cl.value || {};
      const proposerId = cl.proposer || stA.id;
      const giverId = proposerId === stA.id ? stB.id : stA.id;
      const receiverId = proposerId;
      const giver = world.states[giverId] || stB;
      const receiver = world.states[receiverId] || stA;

      if (cl.type === 'TERRITORY_SWAP') {
        const cIds = Array.isArray(v.cityIds) ? v.cityIds : [];
        cIds.forEach((cid) => {
          const c = world.cities && world.cities[cid];
          if (c) {
            const targetOwnerId = (c.originalOwnerId === stA.id || c.originalOwnerId === stB.id) ? c.originalOwnerId : receiver.id;
            transferCityV230(world, cid, targetOwnerId);
          }
        });
        effectsHistory.push(`แลกเปลี่ยน/ส่งคืนเมืองยุทธศาสตร์ ${cIds.length} แห่ง`);
      } else if (cl.type === 'DMZ') {
        const days = Number(v.days || 365);
        stA.truceUntil[stB.id] = Math.max(stA.truceUntil[stB.id] || 0, world.tick + days);
        stB.truceUntil[stA.id] = Math.max(stB.truceUntil[stA.id] || 0, world.tick + days);
        Object.values(world.cities || {}).forEach((c) => {
          if ((c.stateId === stA.id || c.stateId === stB.id) && c.isFrontline) {
            c.threatLevel = Math.max(0, (c.threatLevel || 30) - 25);
          }
        });
        effectsHistory.push(`บังคับใช้เขตปลอดทหาร (DMZ) เป็นเวลา ${days} วัน`);
      } else if (cl.type === 'SANCTION_LIFT') {
        const lvls = Number(v.levels || 2);
        if (lvls >= 3 || talk.type === 'SANCTION_RELIEF') {
          liftMeasuresBetweenV230(world, stA.id, stB.id, 'LIFT');
        } else {
          for (let k = 0; k < lvls; k++) liftMeasuresBetweenV230(world, stA.id, stB.id, 'RELAX');
        }
        effectsHistory.push(`ผ่อนปรน/ยกเลิกมาตรการคว่ำบาตร ${lvls} ระดับ`);
      } else if (cl.type === 'RESOURCE_CONCESSION') {
        const pct = clamp(Number(v.pct || 5), 2, 12);
        const months = Math.max(6, Number(v.months || 24));
        obligations.push({
          type: 'RESOURCE_CONCESSION',
          payerId: giver.id,
          receiverId: receiver.id,
          pct,
          remainingMonths: months
        });
        effectsHistory.push(`${shortNameTh(giver)} แบ่งรายได้ทรัพยากร ${pct}% ให้ ${shortNameTh(receiver)} นาน ${months} เดือน`);
      } else if (cl.type === 'REPARATIONS') {
        const amountB = Math.max(2, Number(v.amountB || 20));
        const months = Math.max(6, Number(v.months || 24));
        obligations.push({
          type: 'REPARATIONS',
          payerId: giver.id,
          receiverId: receiver.id,
          monthlyAmountB: +(amountB / months).toFixed(2),
          remainingMonths: months
        });
        // Link 5: Also push into world.reparations so runReparationsAndTribute processes it
        if (!world.reparations) world.reparations = [];
        const pctGdp = clamp((amountB / Math.max(1, months / 12)) / Math.max(50, giver.gdpB || 200), 0.01, 0.12);
        world.reparations.push({
          payerId: giver.id,
          receiverId: receiver.id,
          startTick: world.tick,
          endTick: world.tick + months * 30,
          pctGdp,
          lastPaidTick: world.tick,
          totalPaidB: 0
        });
        effectsHistory.push(`${shortNameTh(giver)} ชำระค่าปฏิกรรมสงคราม $${amountB}B แก่ ${shortNameTh(receiver)} (${months} งวด ผ่านระบบปฏิกรรมสงครามโลก)`);
      } else if (cl.type === 'TROOP_WITHDRAWAL') {
        const pct = clamp(Number(v.pct || 40), 20, 100);
        const factor = Math.max(0.30, 1 - (pct / 100) * 0.5);
        Object.values(world.camps || {}).forEach((cp) => {
          if (cp.stateId === stA.id || cp.stateId === stB.id) {
            if (!cp._origTroopsV230) cp._origTroopsV230 = cp.troops || 15000;
            cp.troops = Math.max(Math.round(cp._origTroopsV230 * 0.30), Math.round((cp.troops || 15000) * factor));
          }
        });
        effectsHistory.push(`ถอนกำลังทหารแนวหน้าของทั้งสองฝ่ายลง ${pct}%`);
      } else if (cl.type === 'PRISONER_EXCHANGE') {
        stA.approval = clamp(rnd1((stA.approval || 70) + 2), 0, 100);
        stB.approval = clamp(rnd1((stB.approval || 70) + 2), 0, 100);
        effectsHistory.push(`แลกเปลี่ยนเชลยศึก ${v.count || 1000} นาย คะแนนนิยมทั้งสองรัฐ +2%`);
      } else if (cl.type === 'TRADE_PREFERENCE') {
        const cutPct = Number(v.cutPct || 15);
        stA.gdpB = rnd1(stA.gdpB * (1 + cutPct * 0.0002));
        stB.gdpB = rnd1(stB.gdpB * (1 + cutPct * 0.0002));
        effectsHistory.push(`ลดภาษีศุลกากรต่างตอบแทน ${cutPct}%`);
      } else if (cl.type === 'JOINT_COMMISSION') {
        const years = Math.max(1, Number(v.years || 3));
        stA.trustV230 = clamp((stA.trustV230 ?? 70) + years, 0, 100);
        stB.trustV230 = clamp((stB.trustV230 ?? 70) + years, 0, 100);
        effectsHistory.push(`ตั้งคณะกรรมาธิการร่วม ${years} ปี เพิ่มความน่าเชื่อถือ +${years}`);
      } else if (cl.type === 'REFUGEE_RETURN_GUARANTEE') {
        const months = Math.max(6, Number(v.months || 12));
        accelerateReturnsV230(world, stA.id, stB.id, months);
        effectsHistory.push(`รับประกันการส่งกลับผู้ลี้ภัยอย่างปลอดภัยเป็นเวลา ${months} เดือน (อัตราเร็ว 2 เท่า)`);
      }
    });

    // Both parties get trust +4, relation +6, heads & chiefs get achievements++ and memory
    stA.trustV230 = clamp((stA.trustV230 ?? 70) + 4, 0, 100);
    stB.trustV230 = clamp((stB.trustV230 ?? 70) + 4, 0, 100);
    if (stA.relations?.[stB.id]) stA.relations[stB.id].score = clamp(rnd1((stA.relations[stB.id].score || 50) + 6), 0, 100);
    if (stB.relations?.[stA.id]) stB.relations[stA.id].score = clamp(rnd1((stB.relations[stA.id].score || 50) + 6), 0, 100);

    const negA = pickNegotiatorsV230(world, stA.id);
    const negB = pickNegotiatorsV230(world, stB.id);
    const venueCity = talk.hostCityId && world.cities[talk.hostCityId] ? cityNameTh(world.cities[talk.hostCityId]) : 'นครเจนีวา';
    [negA.head, negA.chief, negB.head, negB.chief].filter(Boolean).forEach((npc) => {
      npc.achievements = (npc.achievements || 0) + 1;
      const otherStName = npc.stateId === stA.id ? shortNameTh(stB) : shortNameTh(stA);
      recordNPCMemory(npc, world.year, `ลงนามความสำเร็จใน ${SUMMIT_TYPES_V230[talk.type]?.labelTh || talk.type} กับ ${otherStName} ณ เมือง${venueCity}`);
    });

    // Link 4: Signed SECURITY_PACT and signed PEACE_TREATY call evaluateStateAllianceCalculusV210 for both parties' alliances
    if ((talk.type === 'SECURITY_PACT' || talk.type === 'PEACE_TREATY') && typeof evaluateStateAllianceCalculusV210 === 'function') {
      (world.alliances || []).forEach((al) => { if (al && !al.memberStatesData) al.memberStatesData = {}; });
      evaluateStateAllianceCalculusV210(world, stA.id);
      evaluateStateAllianceCalculusV210(world, stB.id);
      (world.alliances || []).forEach((al) => {
        if (Array.isArray(al.members) && (al.members.includes(stA.id) || al.members.includes(stB.id))) {
          al.members.forEach((mId) => evaluateStateAllianceCalculusV210(world, mId));
        }
      });
    }

    const expMap = { PEACE_TREATY: 3650, CEASEFIRE: 180, TRADE_ACCORD: 1460, SANCTION_RELIEF: 1460, SECURITY_PACT: 3650 };
    const durationTicks = expMap[talk.type] || 1460;
    const postTreatyRelScore = stA.relations?.[stB.id]?.score ?? 58;
    const treaty = {
      id: `TREATY_${world.summitV230.nextId++}`,
      type: talk.type,
      partyA: stA.id,
      partyB: stB.id,
      signedTick: world.tick,
      expiresTick: world.tick + durationTicks,
      status: 'ACTIVE',
      clauses: JSON.parse(JSON.stringify(acceptedClauses)),
      obligations,
      hostId: talk.hostId,
      venueCityId: talk.hostCityId,
      breachBy: null,
      postTreatyRelScore,
      history: effectsHistory
    };

    world.summitV230.treaties.unshift(treaty);
    if (world.summitV230.treaties.length > 80) {
      world.summitV230.treaties.length = 80; // Cap: 80 treaties
    }
    return treaty;
  }

  function finishSummitTalkV230(world, talk, outcome, collapseReason, rng) {
    const stA = resolveStateObjV230(world, talk.partyA);
    const stB = resolveStateObjV230(world, talk.partyB);
    const venueCity = talk.hostCityId && world.cities[talk.hostCityId] ? world.cities[talk.hostCityId] : null;
    const venueName = venueCity ? cityNameTh(venueCity) : 'นครเจนีวา';
    const spec = SUMMIT_TYPES_V230[talk.type] || SUMMIT_TYPES_V230.PEACE_TREATY;
    const negA = pickNegotiatorsV230(world, talk.partyA);
    const negB = pickNegotiatorsV230(world, talk.partyB);
    const headAName = negA.head ? negA.head.name : (stA ? shortNameTh(stA) : 'ฝ่ายแรก');
    const headBName = negB.head ? negB.head.name : (stB ? shortNameTh(stB) : 'ฝ่ายที่สอง');
    const chiefAName = negA.chief ? negA.chief.name : headAName;
    const chiefBName = negB.chief ? negB.chief.name : headBName;

    talk.outcome = outcome;
    talk.stage = outcome;

    // Host reward on any outcome: trustV230 +2 and relation +3 with both
    if (talk.hostId && world.states[talk.hostId]) {
      const hostSt = world.states[talk.hostId];
      hostSt.trustV230 = clamp((hostSt.trustV230 ?? 70) + 2, 0, 100);
      if (stA && hostSt.relations?.[stA.id]) hostSt.relations[stA.id].score = clamp(rnd1(hostSt.relations[stA.id].score + 3), 0, 100);
      if (stA && stA.relations?.[hostSt.id]) stA.relations[hostSt.id].score = clamp(rnd1(stA.relations[hostSt.id].score + 3), 0, 100);
      if (stB && hostSt.relations?.[stB.id]) hostSt.relations[stB.id].score = clamp(rnd1(hostSt.relations[stB.id].score + 3), 0, 100);
      if (stB && stB.relations?.[hostSt.id]) stB.relations[hostSt.id].score = clamp(rnd1(stB.relations[hostSt.id].score + 3), 0, 100);
    }

    if (outcome === 'SIGNED') {
      const treaty = applyTreatyEffectsV230(world, talk);
      const acceptedLabels = (talk.clauses || []).filter((c) => c.status === 'ACCEPTED').map((c) => CLAUSE_TYPES_V230[c.type]?.labelTh || c.type).join(' • ') || 'ข้อตกลงหลัก';
      const signTemplates = [
        `🕊️🖋️ [พิธีลงนามประวัติศาสตร์ ณ เมือง${venueName}!] ${headAName} แห่ง ${stA.name} และ ${headBName} แห่ง ${stB.name} จรดปากกาลงนามใน "${spec.labelTh}" อย่างเป็นทางการ หลังผ่านการเจรจาเข้มข้น ${talk.round} รอบ โดยมีสาระสำคัญได้แก่ ${acceptedLabels} ส่งผลให้ความน่าเชื่อถือทางการทูตของทั้งสองฝ่ายปรับขึ้นเป็น ${Math.round(stA.trustV230)} และ ${Math.round(stB.trustV230)} คะแนนทันที`,
        `🕊️📜 [บรรลุข้อตกลงซัมมิต ${shortNameTh(stA)}–${shortNameTh(stB)} ที่ ${venueName}] เสียงปรบมือดังกึกก้องห้องประชุมเมือง${venueName} เมื่อ ${chiefAName} และ ${chiefBName} นำเอกสาร "${spec.labelTh}" ขึ้นให้ ${headAName} และ ${headBName} ลงสัตยาบัน บังคับใช้เงื่อนไข (${acceptedLabels}) พลิกโฉมหน้าความสัมพันธ์ทวิภาคีสู่ระดับ ${stA.relations?.[stB.id]?.score ?? 55}/100`,
        `🕊️🏛️ [ปิดฉากซัมมิตด้วยชัยชนะทางการทูต ณ ${venueName}] ความพยายามตลอดหลายสัปดาห์ของคณะผู้แทน ${stA.name} และ ${stB.name} ประสบผลสำเร็จ เมื่อทั้งสองฝ่ายลงนามรับรอง "${spec.labelTh}" ครอบคลุมข้อตกลง ${acceptedLabels} สร้างความเชื่อมั่นแก่ตลาดการเงินและประชาคมโลก`,
        `🕊️🤝 [สัตยาบันสนธิสัญญาแห่งเมือง${venueName}] ${headAName} ผู้นำ ${shortNameTh(stA)} และ ${headBName} ผู้นำ ${shortNameTh(stB)} จับมือต่อหน้าสื่อมวลชนทั่วโลก ณ เมือง${venueName} หลังลงนาม "${spec.labelTh}" ครบทั้ง ${(talk.clauses || []).filter((c) => c.status === 'ACCEPTED').length} มาตรา ถือเป็นจุดเปลี่ยนสำคัญทางภูมิรัฐศาสตร์ในปี ${world.year}`,
        `🕊️✨ [สันติภาพและพันธสัญญามีผลบังคับใช้ ณ ${venueName}] พิธีลงนาม "${spec.labelTh}" ระหว่าง ${stA.name} และ ${stB.name} ณ เมือง${venueName} เสร็จสมบูรณ์โดยไร้เหตุแทรกแซง คณะผู้แทนของ ${chiefAName} และ ${chiefBName} เริ่มส่งมอบพันธกรณี (${acceptedLabels}) ทันทีตามกรอบเวลา`,
        `🕊️⚖️ [จารึกสนธิสัญญาฉบับใหม่แห่งยุคที่ ${venueName}] ${stA.name} และ ${stB.name} ประกาศความสำเร็จของการประชุมสุดยอด ณ เมือง${venueName} โดย ${headAName} และ ${headBName} ลงนามบังคับใช้ "${spec.labelTh}" (${acceptedLabels}) ยกระดับเสถียรภาพภูมิภาคอย่างเป็นรูปธรรม`
      ];
      const msg = rng.pick(signTemplates);
      addChronicle(world, 'SUMMIT', msg, stA.id, { secondStateId: stB.id, cityId: venueCity ? venueCity.id : null, personId: negA.headId, treatyId: treaty ? treaty.id : null });
      addChronicle(world, 'TREATY', `📜✅ [ขึ้นทะเบียนสนธิสัญญา ${treaty ? treaty.id : ''}] "${spec.labelTh}" ระหว่าง ${stA.name} และ ${stB.name} (ลงนาม ณ เมือง${venueName} โดย ${headAName} และ ${headBName}) มีผลบังคับใช้อย่างเป็นทางการ: ${acceptedLabels}`, stA.id, { secondStateId: stB.id, cityId: venueCity ? venueCity.id : null, treatyId: treaty ? treaty.id : null });
    } else {
      const reasonTh = collapseReason || 'ความขัดแย้งในเงื่อนไขหลักและการแทรกแซงของกลุ่มสายเหยี่ยว';
      const pairKey = (stA.id < stB.id ? `${stA.id}_${stB.id}` : `${stB.id}_${stA.id}`) + `_${talk.type}`;
      world.summitV230.cooldowns[pairKey] = world.tick + 60; // 60 ticks cooldown
      [negA.head, negA.chief, negB.head, negB.chief].filter(Boolean).forEach((npc) => {
        const otherStName = npc.stateId === stA.id ? shortNameTh(stB) : shortNameTh(stA);
        recordNPCMemory(npc, world.year, `การเจรจาซัมมิตกับ ${otherStName} ณ เมือง${venueName} ล้มเหลวลงเนื่องจาก${reasonTh}`);
      });
      const collapseTemplates = [
        `🕊️💥 [โต๊ะเจรจาซัมมิตล่มกลางคัน ณ เมือง${venueName}!] การประชุม "${spec.labelTh}" ระหว่าง ${stA.name} และ ${stB.name} พังทลายลงในรอบที่ ${talk.round} เนื่องจาก**${reasonTh}** ส่งผลให้ ${chiefAName} และ ${chiefBName} สั่งถอนคณะผู้แทนกลับประเทศทันที และล็อกระยะพักการเจรจา 60 วัน`,
        `🕊️🚨 [วิกฤตการทูตที่ ${venueName} — ซัมมิตล้มเหลว!] ความหวังในการบรรลุ "${spec.labelTh}" ระหว่าง ${headAName} (${shortNameTh(stA)}) และ ${headBName} (${shortNameTh(stB)}) สิ้นสุดลงอย่างตึงเครียด ณ เมือง${venueName} โดยมีสาเหตุหลักจาก**${reasonTh}** ท่ามกลางการกล่าวโทษกันไปมาของโฆษกทั้งสองรัฐบาล`,
        `🕊️❌ [ฉีกแฟ้มร่างข้อตกลงกลางเมือง${venueName}] คณะเจรจาของ ${chiefAName} (${shortNameTh(stA)}) เดินออกจากห้องประชุมเมือง${venueName} หลังการต่อรอง "${spec.labelTh}" กับ ${chiefBName} (${shortNameTh(stB)}) ถึงทางตันเพราะ**${reasonTh}** ทำให้ความตึงเครียดทวิภาคีปะทุขึ้นอีกครั้ง`,
        `🕊️⚡ [ซัมมิต ${shortNameTh(stA)}–${shortNameTh(stB)} ล่มไม่เป็นท่า!] แม้จะเจรจายืดเยื้อถึง ${talk.round} รอบ ณ เมือง${venueName} แต่การประชุม "${spec.labelTh}" ต้องยุติลงเป็นสถานะ COLLAPSED เนื่องจาก**${reasonTh}** สร้างความผิดหวังแก่ชาติเจ้าภาพและประชาคมโลก`,
        `🕊️📉 [ความล้มเหลวบนโต๊ะเจรจาเมือง${venueName}] แหล่งข่าวการทูตยืนยันว่าการประชุมสุดยอด "${spec.labelTh}" ระหว่าง ${stA.name} และ ${stB.name} ยุติลงโดยไม่มีการลงนาม หลังเกิดปัญหา**${reasonTh}** ซึ่งบีบให้ ${headAName} และ ${headBName} สั่งระงับการเจรจาอย่างน้อย 60 วัน`,
        `🕊️🔥 [ปิดฉากซัมมิตด้วยความร้าวฉาน ณ ${venueName}] พิธีเจรจา "${spec.labelTh}" ที่เมือง${venueName} ระหว่างผู้แทนของ ${headAName} และ ${headBName} พังครืนลงจากชนวน**${reasonTh}** ส่งผลให้ทั้งสองรัฐกลับไปเตรียมมาตรการกดดันทางยุทธศาสตร์ต่อกันทันที`
      ];
      addChronicle(world, 'SUMMIT', rng.pick(collapseTemplates), stA.id, { secondStateId: stB.id, cityId: venueCity ? venueCity.id : null, personId: negA.chiefId || negA.headId });
    }

    // Move talk from active talks to archive (cap 60)
    world.summitV230.talks = world.summitV230.talks.filter((t) => t.id !== talk.id);
    world.summitV230.archive.unshift(talk);
    if (world.summitV230.archive.length > 60) {
      world.summitV230.archive.length = 60;
    }
  }

  function stepActiveSummitsV230(world, rng) {
    ensureSummitV230(world);
    const activeTalks = (world.summitV230.talks || []).slice();
    if (activeTalks.length === 0) return;

    for (let idx = 0; idx < activeTalks.length; idx++) {
      const talk = activeTalks[idx];
      const stA = resolveStateObjV230(world, talk.partyA);
      const stB = resolveStateObjV230(world, talk.partyB);
      if (!stA || !stB) {
        world.summitV230.talks = world.summitV230.talks.filter((t) => t.id !== talk.id);
        continue;
      }

      talk.stageDay = (talk.stageDay || 0) + 1;
      if (talk.stageDay < (talk.stageTargetDays || 2)) continue;

      // Check if head of state was replaced mid-talk
      const negA = pickNegotiatorsV230(world, stA.id);
      const negB = pickNegotiatorsV230(world, stB.id);
      if ((talk.negotiators?.A?.headId && negA.headId && talk.negotiators.A.headId !== negA.headId) ||
          (talk.negotiators?.B?.headId && negB.headId && talk.negotiators.B.headId !== negB.headId)) {
        appendTalkLogV230(talk, world.tick, 'การเปลี่ยนตัวผู้นำรัฐกะทันหันทำให้คณะเจรจาถูกเรียกตัวกลับ');
        finishSummitTalkV230(world, talk, 'COLLAPSED', 'การเปลี่ยนขั้วผู้นำรัฐบาลกะทันหัน (Head Replaced)', rng);
        continue;
      }

      const venueCity = talk.hostCityId && world.cities[talk.hostCityId] ? world.cities[talk.hostCityId] : null;
      const venueName = venueCity ? cityNameTh(venueCity) : 'นครเจนีวา';
      const spec = SUMMIT_TYPES_V230[talk.type] || SUMMIT_TYPES_V230.PEACE_TREATY;
      const headAName = negA.head ? negA.head.name : shortNameTh(stA);
      const headBName = negB.head ? negB.head.name : shortNameTh(stB);
      const chiefAName = negA.chief ? negA.chief.name : headAName;
      const chiefBName = negB.chief ? negB.chief.name : headBName;
      const hardA = negA.hardliner;
      const hardB = negB.hardliner;

      if (talk.stage === 'PREPARATION') {
        talk.stage = 'OPENING';
        talk.stageDay = 0;
        talk.stageTargetDays = rng.int(SUMMIT_STAGE_DURATIONS_V230.OPENING.min, SUMMIT_STAGE_DURATIONS_V230.OPENING.max);
        appendTalkLogV230(talk, world.tick, `เปิดประชุมอย่างเป็นทางการ ณ เมือง${venueName}: ${chiefAName} และ ${chiefBName} กล่าวสุนทรพจน์เปิดเวที`);
        const openTemplates = [
          `🕊️🎙️ [พิธีเปิดการประชุมซัมมิต ณ เมือง${venueName}] ${headAName} แห่ง ${stA.name} และ ${headBName} แห่ง ${stB.name} (พร้อมหัวหน้าคณะผู้แทน ${chiefAName} และ ${chiefBName}) ขึ้นกล่าวสุนทรพจน์เปิดเวที "${spec.labelTh}" ต่อหน้าผู้สังเกตการณ์นานาชาติ โดยวางกรอบข้อตกลงหลัก ${talk.clauses.length} ประเด็น ท่ามกลางบรรยากาศที่ทั้งคาดหวังและตึงเครียด`,
          `🕊️🏛️ [สุนทรพจน์เปิดโต๊ะเจรจาที่ ${venueName}] การประชุม "${spec.labelTh}" ณ เมือง${venueName} เปิดฉากขึ้นอย่างเป็นทางการ ${chiefAName} แห่ง ${shortNameTh(stA)} ย้ำจุดยืนด้านอธิปไตยและผลประโยชน์แห่งชาติ ขณะที่ ${chiefBName} แห่ง ${shortNameTh(stB)} เรียกร้องความจริงใจในการปฏิบัติตามข้อตกลงทั้ง ${talk.clauses.length} ข้อ`,
          `🕊️📸 [จับมือหน้าม่านแต่คมเฉือนคมหลังม่าน ณ ${venueName}] คณะผู้แทนของ ${stA.name} และ ${stB.name} ร่วมถ่ายภาพประวัติศาสตร์ในพิธีเปิด "${spec.labelTh}" ที่เมือง${venueName} ก่อนที่ ${chiefAName} และ ${chiefBName} จะนำทีมเข้าสู่ห้องประชุมปิดเพื่อถกเถียงวาระสำคัญ ${talk.clauses.length} มาตรา`,
          `🕊️🌐 [เปิดม่านซัมมิต ${shortNameTh(stA)}–${shortNameTh(stB)} ณ ${venueName}] ผู้นำและนักการทูตของ ${stA.name} (${headAName}) และ ${stB.name} (${headBName}) เริ่มต้นวาระ OPENING ของ "${spec.labelTh}" ณ เมือง${venueName} โดยทั้งสองฝ่ายแถลงกรอบเจรจา ${talk.clauses.length} หัวข้อต่อสื่อมวลชนทั่วโลก`,
          `🕊️⚖️ [เวทีซัมมิตเมือง${venueName} เริ่มต้นขึ้นแล้ว] ${chiefAName} ผู้แทน ${shortNameTh(stA)} และ ${chiefBName} ผู้แทน ${shortNameTh(stB)} เปิดแถลงการณ์ร่วมเข้าสู่วาระการประชุม "${spec.labelTh}" ณ เมือง${venueName} ท่ามกลางดัชนีความพร้อมเจรจา ${Math.round(willingnessV230(world, stA, stB))}% ต่อ ${Math.round(willingnessV230(world, stB, stA))}%`,
          `🕊️🔔 [เคาะฆ้องเปิดเจรจาสุดยอด ณ ${venueName}] ห้องประชุมใหญ่เมือง${venueName} เปิดต้อนรับคณะของ ${headAName} (${shortNameTh(stA)}) และ ${headBName} (${shortNameTh(stB)}) ในการประชุม "${spec.labelTh}" เพื่อหาทางออกใน ${talk.clauses.length} ประเด็นยุทธศาสตร์ที่ทั่วโลกเฝ้ามอง`
        ];
        addChronicle(world, 'SUMMIT', rng.pick(openTemplates), stA.id, { secondStateId: stB.id, cityId: venueCity ? venueCity.id : null, personId: negA.chiefId || negA.headId, summitId: talk.id });
      } else if (talk.stage === 'OPENING') {
        talk.stage = 'BARGAINING';
        talk.round = 1;
        talk.stageDay = 0;
        talk.stageTargetDays = rng.int(SUMMIT_STAGE_DURATIONS_V230.BARGAINING.min, SUMMIT_STAGE_DURATIONS_V230.BARGAINING.max);
        const firstCl = talk.clauses[0];
        const firstClLabel = CLAUSE_TYPES_V230[firstCl?.type]?.labelTh || 'เงื่อนไขหลัก';
        appendTalkLogV230(talk, world.tick, `เข้าสู่ช่วงต่อรองรายข้อ (BARGAINING รอบที่ 1): เริ่มถก "${firstClLabel}"`);
        const enterBargTemplates = [
          `🕊️🔥 [เข้าสู่ช่วงต่อรองรายข้อรอบแรก ณ ${venueName}] คณะเจรจาของ ${chiefAName} (${shortNameTh(stA)}) และ ${chiefBName} (${shortNameTh(stB)}) ปิดห้องถกเถียงวาระ BARGAINING รอบที่ 1 ของ "${spec.labelTh}" ณ เมือง${venueName} โดยประเด็นร้อนข้อแรกคือ "${firstClLabel}" (${formatClauseValueTextV230(world, firstCl)}) ซึ่งทั้งสองฝ่ายต่างงัดตัวเลขและข้อมูลยุทธศาสตร์ขึ้นมาหักล้างกันอย่างดุเดือด`,
          `🕊️⚖️ [เปิดศึกชิงไหวชิงพริบบนโต๊ะเจรจา ${venueName}] การประชุม "${spec.labelTh}" ก้าวเข้าสู่ระยะต่อรองรายข้อ (BARGAINING) ณ เมือง${venueName} เมื่อผู้แทนของ ${headAName} และ ${headBName} ยื่นข้อเสนอ "${firstClLabel}" ขึ้นพิจารณาเป็นวาระแรก ท่ามกลางการจับตาของฝ่ายทหารทั้งสองประเทศ`,
          `🕊️📑 [ถกวาระร้อน "${firstClLabel}" ณ เมือง${venueName}] ${chiefAName} แห่ง ${stA.name} และ ${chiefBName} แห่ง ${stB.name} เริ่มต้นการต่อรองรอบที่ 1 ในศึก "${spec.labelTh}" โดยแลกเปลี่ยนเอกสารข้อเสนอ "${firstClLabel}" (${formatClauseValueTextV230(world, firstCl)}) อย่างเคร่งเครียดนานกว่า 9 ชั่วโมง`,
          `🕊️♟️ [หมากการทูตรอบแรกที่ ${venueName}] บนโต๊ะเจรจาเมือง${venueName} คณะทำงานของ ${shortNameTh(stA)} และ ${shortNameTh(stB)} เข้าสู่โหมดต่อรองเข้มข้น (BARGAINING) ใน "${spec.labelTh}" โดยหยิบยกข้อตกลง "${firstClLabel}" ขึ้นมาวัดใจฝ่ายตรงข้ามเป็นประเด็นแรก`,
          `🕊️🗣️ [ปะทะคารมในห้องประชุมปิดเมือง${venueName}] การเจรจา "${spec.labelTh}" ระหว่าง ${chiefAName} (${shortNameTh(stA)}) และ ${chiefBName} (${shortNameTh(stB)}) เข้าสู่ช่วง BARGAINING รอบที่ 1 โดยทั้งสองฝ่ายถกเถียงรายละเอียดของ "${firstClLabel}" อย่างเผ็ดร้อน`,
          `🕊️🔍 [เจาะลึกโต๊ะต่อรอง ${shortNameTh(stA)}–${shortNameTh(stB)} ณ ${venueName}] ผู้แทนของ ${headAName} และ ${headBName} เริ่มเปิดแฟ้มต่อรองรายข้อใน "${spec.labelTh}" ณ เมือง${venueName} ประเดิมด้วยเงื่อนไข "${firstClLabel}" (${formatClauseValueTextV230(world, firstCl)}) ที่ชี้วัดความสำเร็จของซัมมิตครั้งนี้`
        ];
        addChronicle(world, 'SUMMIT', rng.pick(enterBargTemplates), stA.id, { secondStateId: stB.id, cityId: venueCity ? venueCity.id : null, personId: negA.chiefId || negA.headId, summitId: talk.id });
      } else if (talk.stage === 'BARGAINING') {
        const wA = clamp(willingnessV230(world, stA, stB, negA) - (talk.leakPenalty || 0), 0, 100);
        const wB = clamp(willingnessV230(world, stB, stA, negB) - (talk.leakPenalty || 0), 0, 100);
        talk.leakPenalty = 0;
        const highMandate = (wA >= 68 && wB >= 68) || (((negA.head?.personality?.aggression ?? 50) <= 20) && ((negB.head?.personality?.aggression ?? 50) <= 20) && (stA.warExhaustion >= 70 || stB.warExhaustion >= 70));

        // Check Hardliner Sabotage
        let sabotagedBy = null;
        if (!highMandate) {
          const hardScoreA = (hardA?.personality?.ambition || 50) + (hardA?.personality?.aggression || 50);
          const hardScoreB = (hardB?.personality?.ambition || 50) + (hardB?.personality?.aggression || 50);
          if (hardScoreA > 150 && rng.chance(0.25)) sabotagedBy = { side: 'A', state: stA, npc: hardA };
          else if (hardScoreB > 150 && rng.chance(0.25)) sabotagedBy = { side: 'B', state: stB, npc: hardB };
        }

        if (sabotagedBy) {
          talk.spoilers = (talk.spoilers || 0) + 1;
          const sabName = sabotagedBy.npc ? sabotagedBy.npc.name : `นายพลสายเหยี่ยวแห่ง ${shortNameTh(sabotagedBy.state)}`;
          appendTalkLogV230(talk, world.tick, `สายเหยี่ยว ${sabName} (${shortNameTh(sabotagedBy.state)}) ก่อกวนโต๊ะเจรจาในรอบที่ ${talk.round} (Spoilers: ${talk.spoilers}/2)`);
          if (talk.spoilers >= 2) {
            finishSummitTalkV230(world, talk, 'COLLAPSED', `การก่อวินาศกรรมทางการทูตและขวางข้อตกลงของสายเหยี่ยว ${sabName} (Hardliner Sabotage)`, rng);
            continue;
          }
        } else {
          // 4% Leak event (named journalist if present)
          if (!highMandate && rng.chance(0.04)) {
            talk.leakPenalty = 5;
            const journ = Object.values(world.npcs || {}).find((n) => n && n.alive && n.positionId === 'JOURNALIST_MEDIA' && (n.stateId === stA.id || n.stateId === stB.id));
            const jName = journ ? journ.name : 'ผู้สื่อข่าวสืบสวนอาวุโส';
            appendTalkLogV230(talk, world.tick, `ข่าวรั่วไหลโดย ${jName} ทำให้ความไว้วางใจลดลง (-5 Willingness รอบถัดไป)`);
          }
          // 3% Third-party great power spoiler
          if (!highMandate && rng.chance(0.03)) {
            const top5 = Object.values(world.states).filter((s) => !s.isExiled).sort((x, y) => y.gdpB - x.gdpB).slice(0, 5);
            const gpSpoiler = top5.find((gp) => gp.id !== stA.id && gp.id !== stB.id && gp.id !== talk.hostId && (gp.relations?.[stA.id]?.status === 'Hostile' || gp.relations?.[stB.id]?.status === 'Hostile'));
            if (gpSpoiler) {
              talk.spoilers = (talk.spoilers || 0) + 1;
              appendTalkLogV230(talk, world.tick, `มหาอำนาจที่สาม (${shortNameTh(gpSpoiler)}) แทรกแซงกดดันหลังม่านเพื่อขวางข้อตกลง`);
              if (talk.spoilers >= 2) {
                finishSummitTalkV230(world, talk, 'COLLAPSED', `การแทรกแซงล้มโต๊ะเจรจาโดยมหาอำนาจที่สาม ${shortNameTh(gpSpoiler)} (Third-Party Spoiler)`, rng);
                continue;
              }
            }
          }

          // Evaluate clauses with status PROPOSED or COUNTER
          const hostBonus = talk.hostId ? 6 : 0;
          (talk.clauses || []).forEach((cl) => {
            if (cl.status !== 'PROPOSED' && cl.status !== 'COUNTER') return;
            const acceptorSt = cl.proposer === stA.id ? stB : stA;
            const wAcc = acceptorSt.id === stA.id ? wA : wB;
            const cost = clauseCostV230(world, cl, acceptorSt.id);
            const acceptScore = wAcc - cost + hostBonus + rng.int(-8, 8);
            if (acceptScore >= 50 || highMandate) {
              cl.status = 'ACCEPTED';
            } else if (acceptScore >= 35) {
              cl.counters = (cl.counters || 0) + 1;
              if (cl.counters > 2) {
                cl.status = 'REJECTED';
              } else {
                cl.status = 'COUNTER';
                // Move value 25% toward acceptor's preference
                if (cl.value) {
                  if (cl.value.amountB) cl.value.amountB = Math.max(2, Math.round(cl.value.amountB * 0.75));
                  if (cl.value.pct) cl.value.pct = Math.max(2, Math.round(cl.value.pct * 0.75));
                  if (cl.value.days) cl.value.days = Math.max(90, Math.round(cl.value.days * 0.75));
                  if (cl.value.levels) cl.value.levels = Math.max(1, cl.value.levels - 1);
                  if (cl.value.cutPct) cl.value.cutPct = Math.max(5, Math.round(cl.value.cutPct * 0.75));
                }
              }
            } else {
              cl.status = 'REJECTED';
            }
          });

          // Proposer side may add one new clause if total clauses < 5
          if (talk.clauses.length < 5 && rng.chance(0.45)) {
            const pA = pressureV230(world, stA);
            const pB = pressureV230(world, stB);
            const stronger = pA <= pB ? stA : stB;
            const weaker = stronger.id === stA.id ? stB : stA;
            const proposer = rng.chance(0.5) ? stronger : weaker;
            const pool = proposer.id === stronger.id
              ? ['RESOURCE_CONCESSION', 'REPARATIONS', 'TROOP_WITHDRAWAL']
              : ['PRISONER_EXCHANGE', 'DMZ', 'TRADE_PREFERENCE', 'REFUGEE_RETURN_GUARANTEE'];
            const newType = rng.pick(pool.filter((t) => !talk.clauses.some((c) => c.type === t)));
            if (newType) {
              const newVal = newType === 'RESOURCE_CONCESSION' ? { pct: rng.int(3, 7), months: 24 }
                : newType === 'REPARATIONS' ? { amountB: rng.int(8, 25), months: 24 }
                : newType === 'TROOP_WITHDRAWAL' ? { pct: 35 }
                : newType === 'PRISONER_EXCHANGE' ? { count: rng.int(600, 1800) }
                : newType === 'DMZ' ? { days: 180 }
                : newType === 'REFUGEE_RETURN_GUARANTEE' ? { months: 12 }
                : { cutPct: 10 };
              talk.clauses.push({
                id: talk.clauses.length + 1,
                type: newType,
                proposer: proposer.id,
                value: newVal,
                status: 'PROPOSED',
                counters: 0
              });
            }
          }
        }

        const focusClause = talk.clauses[talk.round % talk.clauses.length] || talk.clauses[0];
        const focusLabel = CLAUSE_TYPES_V230[focusClause?.type]?.labelTh || 'ข้อตกลงหลัก';
        const focusStatusTh = focusClause?.status === 'ACCEPTED' ? 'เห็นชอบร่วมกัน (ACCEPTED)' : focusClause?.status === 'COUNTER' ? 'ยื่นข้อเสนอสวนกลับ (COUNTER)' : focusClause?.status === 'REJECTED' ? 'ปัดตกข้อเสนอ (REJECTED)' : 'กำลังพิจารณา';
        appendTalkLogV230(talk, world.tick, `รอบที่ ${talk.round}: "${focusLabel}" -> ${focusStatusTh}`);

        const bargTemplates = [
          `🕊️🔄 [ซัมมิตเมือง${venueName} รอบที่ ${talk.round} — ต่อรองเดือด] ในการประชุม "${spec.labelTh}" ณ เมือง${venueName} คณะของ ${chiefAName} (${shortNameTh(stA)}) และ ${chiefBName} (${shortNameTh(stB)}) ปะทะคารมเรื่อง "${focusLabel}" (${formatClauseValueTextV230(world, focusClause)}) ก่อนที่ผลโหวตในห้องประชุมจะออกมาเป็น **${focusStatusTh}** ท่ามกลางแรงกดดันจากทั้งสองเมืองหลวง`,
          `🕊️⚖️ [ความคืบหน้าโต๊ะเจรจา ${shortNameTh(stA)}–${shortNameTh(stB)} รอบที่ ${talk.round}] การต่อรอง "${spec.labelTh}" ที่เมือง${venueName} เข้มข้นขึ้นทุกขณะ เมื่อผู้แทนของ ${headAName} และ ${headBName} พิจารณาข้อเสนอ "${focusLabel}" และมีมติ **${focusStatusTh}** (ผ่านแล้ว ${talk.clauses.filter((c) => c.status === 'ACCEPTED').length}/${talk.clauses.length} ข้อ)`,
          `🕊️📑 [ผ่าผลเจรจารอบที่ ${talk.round} ณ ${venueName}] รายงานจากห้องประชุม "${spec.labelTh}" ระบุว่า ${chiefAName} แห่ง ${stA.name} และ ${chiefBName} แห่ง ${stB.name} ได้ข้อสรุปเบื้องต้นในประเด็น "${focusLabel}" ในสถานะ **${focusStatusTh}** ขณะที่ฝ่ายความมั่นคงของทั้งสองรัฐยังคงเฝ้าระวังอย่างใกล้ชิด`,
          `🕊️♟️ [ชิงไหวชิงพริบรอบที่ ${talk.round} ที่เมือง${venueName}] คณะผู้แทนของ ${stA.name} และ ${stB.name} แลกหมัดทางการทูตในหัวข้อ "${focusLabel}" (${formatClauseValueTextV230(world, focusClause)}) บนโต๊ะซัมมิตเมือง${venueName} ส่งผลให้สถานะของข้อนี้กลายเป็น **${focusStatusTh}**`,
          `🕊️🗣️ [บันทึกห้องเจรจาลับเมือง${venueName} รอบที่ ${talk.round}] ${chiefAName} (${shortNameTh(stA)}) และ ${chiefBName} (${shortNameTh(stB)}) ใช้เวลากว่า 11 ชั่วโมงถกเถียงเงื่อนไข "${focusLabel}" ในการประชุม "${spec.labelTh}" จนได้ผลลัพธ์ **${focusStatusTh}**`,
          `🕊️🌐 [เกาะติดซัมมิต ${venueName} รอบที่ ${talk.round}] โฆษกที่ประชุม "${spec.labelTh}" แถลงผลการเจรจารอบที่ ${talk.round} ระหว่าง ${shortNameTh(stA)} และ ${shortNameTh(stB)} โดยเงื่อนไข "${focusLabel}" อยู่ในสถานะ **${focusStatusTh}** ท่ามกลางความสนใจของสื่อโลก`
        ];
        addChronicle(world, 'SUMMIT', rng.pick(bargTemplates), stA.id, { secondStateId: stB.id, cityId: venueCity ? venueCity.id : null, personId: negA.chiefId || negA.headId, summitId: talk.id });

        const allResolved = talk.clauses.every((c) => c.status === 'ACCEPTED' || c.status === 'REJECTED');
        if (talk.round >= (talk.maxRounds || 3) || (allResolved && talk.round >= 2)) {
          // Check transition to DRAFTING vs COLLAPSED
          const coreList = spec.coreClauses || [];
          const presentCores = talk.clauses.filter((c) => coreList.includes(c.type));
          const coreOk = presentCores.length > 0
            ? presentCores.every((c) => c.status === 'ACCEPTED')
            : talk.clauses.some((c) => c.status === 'ACCEPTED');
          const acceptedCount = talk.clauses.filter((c) => c.status === 'ACCEPTED').length;
          const halfOk = acceptedCount >= Math.ceil(talk.clauses.length * 0.5);

          if (coreOk && halfOk) {
            talk.stage = 'DRAFTING';
            talk.stageDay = 0;
            talk.stageTargetDays = rng.int(SUMMIT_STAGE_DURATIONS_V230.DRAFTING.min, SUMMIT_STAGE_DURATIONS_V230.DRAFTING.max);
            const accLabels = talk.clauses.filter((c) => c.status === 'ACCEPTED').map((c) => CLAUSE_TYPES_V230[c.type]?.labelTh || c.type).join(', ');
            appendTalkLogV230(talk, world.tick, `เข้าสู่ขั้นตอนร่างสนธิสัญญา (DRAFTING): เห็นชอบ ${acceptedCount}/${talk.clauses.length} ข้อ (${accLabels})`);
            const draftTemplates = [
              `🕊️📝 [เข้าสู่ขั้นตอนร่างสนธิสัญญาฉบับสมบูรณ์ ณ ${venueName}!] คณะทำงานกฎหมายของ ${chiefAName} (${shortNameTh(stA)}) และ ${chiefBName} (${shortNameTh(stB)}) เริ่มยกร่างเอกสาร "${spec.labelTh}" ณ เมือง${venueName} หลังทั้งสองฝ่ายบรรลุฉันทามติในเงื่อนไขสำคัญ (${accLabels}) รวม ${acceptedCount} มาตรา เพื่อเตรียมเสนอให้ ${headAName} และ ${headBName} ลงนาม`,
              `🕊️📜 [ยกร่างสัตยาบัน "${spec.labelTh}" ที่เมือง${venueName}] หลังผ่านการต่อรอง ${talk.round} รอบ ผู้แทนของ ${stA.name} และ ${stB.name} เข้าสู่วาระ DRAFTING ณ เมือง${venueName} โดยบรรจุข้อตกลงที่ผ่านความเห็นชอบได้แก่: ${accLabels}`,
              `🕊️⚖️ [ฝ่ายกฎหมายเร่งตรวจร่างสัญญา ณ ${venueName}] การประชุม "${spec.labelTh}" ระหว่าง ${shortNameTh(stA)} และ ${shortNameTh(stB)} ก้าวข้ามจุดชี้ขาดเข้าสู่ระยะ DRAFTING โดยสรุปเงื่อนไขที่ตกลงกันได้ ${acceptedCount} ข้อ (${accLabels}) เตรียมจัดพิธีลงนามในอีก ${talk.stageTargetDays} วัน`,
              `🕊️🖋️ [นับถอยหลังพิธีลงนามที่ ${venueName}] ${chiefAName} และ ${chiefBName} ร่วมกันรับรองร่างสุดท้ายของ "${spec.labelTh}" ณ เมือง${venueName} ซึ่งประกอบด้วยมาตราหลัก (${accLabels}) ส่งต่อไปยังทำเนียบรัฐบาลของ ${headAName} และ ${headBName}`,
              `🕊️🏛️ [ร่างสนธิสัญญา ${shortNameTh(stA)}–${shortNameTh(stB)} เสร็จสมบูรณ์] ทีมนักการทูตที่เมือง${venueName} ปิดห้องขัดเกลาถ้อยคำในร่าง "${spec.labelTh}" ครบทั้ง ${acceptedCount} ข้อที่เห็นชอบร่วมกัน (${accLabels}) ท่ามกลางสัญญาณบวกจากทั้งสองฝ่าย`,
              `🕊️🤝 [ผ่านฉลุยเข้าสู่ขั้น DRAFTING ณ เมือง${venueName}] โต๊ะเจรจา "${spec.labelTh}" ระหว่าง ${stA.name} และ ${stB.name} สรุปผลข้อตกลงที่ผ่านการอนุมัติ (${accLabels}) และเริ่มจัดเตรียมเอกสารสำหรับพิธีลงนามระดับประมุขแห่งรัฐ`
            ];
            addChronicle(world, 'SUMMIT', rng.pick(draftTemplates), stA.id, { secondStateId: stB.id, cityId: venueCity ? venueCity.id : null, personId: negA.chiefId || negA.headId, summitId: talk.id });
          } else {
            finishSummitTalkV230(world, talk, 'COLLAPSED', 'ทางตันในการตกลงเงื่อนไขหลัก (Clause Deadlock)', rng);
            continue;
          }
        } else {
          talk.round += 1;
          talk.stageDay = 0;
          talk.stageTargetDays = rng.int(SUMMIT_STAGE_DURATIONS_V230.BARGAINING.min, SUMMIT_STAGE_DURATIONS_V230.BARGAINING.max);
        }
      } else if (talk.stage === 'DRAFTING') {
        talk.stage = 'SIGNING';
        talk.stageDay = 0;
        talk.stageTargetDays = SUMMIT_STAGE_DURATIONS_V230.SIGNING.max;
        appendTalkLogV230(talk, world.tick, `เตรียมจัดพิธีลงนามอย่างเป็นทางการ (SIGNING) ณ เมือง${venueName}`);
      } else if (talk.stage === 'SIGNING') {
        const wA = willingnessV230(world, stA, stB, negA);
        const wB = willingnessV230(world, stB, stA, negB);
        const highMandate = (wA >= 68 && wB >= 68) || (((negA.head?.personality?.aggression ?? 50) <= 20) && ((negB.head?.personality?.aggression ?? 50) <= 20));
        const hardOppFlag = (((hardA?.personality?.aggression || 50) > 80) || ((hardB?.personality?.aggression || 50) > 80)) ? 1 : 0;
        const signProb = highMandate ? 1.0 : clamp(0.92 - 0.08 * (talk.spoilers || 0) - 0.10 * hardOppFlag, 0.25, 0.98);
        if (rng.chance(signProb)) {
          finishSummitTalkV230(world, talk, 'SIGNED', null, rng);
        } else {
          finishSummitTalkV230(world, talk, 'COLLAPSED', 'เหตุล้มพิธีลงนามนาทีสุดท้ายจากแรงต้านของฝ่ายความมั่นคง (Ceremony Collapse)', rng);
        }
      }
    }
  }

  function runSummitCycleV230(world, rng) {
    ensureWorldSystemsV230(world);
    if (world.aiSandbox === false) return;

    // a) Active wars -> PEACE_TREATY or CEASEFIRE
    const activeWars = (world.wars || []).filter((w) => w.status === 'War');
    for (let i = 0; i < activeWars.length; i++) {
      if (world.summitV230.talks.length >= 8) break;
      const w = activeWars[i];
      const stA = world.states[w.attackerId];
      const stB = world.states[w.defenderId];
      if (!stA || !stB || stA.isExiled || stB.isExiled) continue;
      const wA = willingnessV230(world, stA, stB);
      const wB = willingnessV230(world, stB, stA);
      const eligible = (wA >= 52 && wB >= 52) ||
        (wA >= 70 && (stB.warExhaustion || 0) >= 40) ||
        (wB >= 70 && (stA.warExhaustion || 0) >= 40) ||
        ((world.tick - (w.startTick || 0)) >= 90 && wA >= 44 && wB >= 44);
      if (eligible && rng.chance(0.35)) {
        const bothExhausted = (stA.warExhaustion || 0) >= 40 && (stB.warExhaustion || 0) >= 40;
        const tType = bothExhausted ? (rng.chance(0.7) ? 'PEACE_TREATY' : 'CEASEFIRE') : 'CEASEFIRE';
        startSummitV230(world, stA.id, stB.id, tType, { forced: false });
      }
    }

    // b) Active T2 measures -> TRADE_ACCORD (level <= 2) or SANCTION_RELIEF (level >= 3)
    const activeMeasures = (world.tradeWarV230?.measures || []).filter((m) => m.status === 'ACTIVE' && m.level >= 2 && (world.tick - (m.startTick || 0)) >= 65);
    for (let i = 0; i < activeMeasures.length; i++) {
      if (world.summitV230.talks.length >= 8) break;
      const m = activeMeasures[i];
      const imp = world.states[m.imposerId];
      const tgt = world.states[m.targetId];
      if (!imp || !tgt || imp.isExiled || tgt.isExiled) continue;
      if (sanctionPainV230(world, tgt) >= 35 && rng.chance(0.25)) {
        const tType = m.level <= 2 ? 'TRADE_ACCORD' : 'SANCTION_RELIEF';
        startSummitV230(world, imp.id, tgt.id, tType, { forced: false });
      }
    }

    // c) Peace/Alliance pairs with relation score >= 70 -> SECURITY_PACT
    if (world.summitV230.talks.length < 8) {
      const liveStates = Object.values(world.states).filter((s) => !s.isExiled);
      for (let k = 0; k < 4; k++) {
        const s1 = rng.pick(liveStates);
        const s2 = rng.pick(liveStates);
        if (!s1 || !s2 || s1.id === s2.id) continue;
        const rel = s1.relations?.[s2.id];
        if (rel && (rel.status === 'Peace' || rel.status === 'Alliance') && (rel.score || 50) >= 70) {
          if (rng.chance(0.08)) {
            startSummitV230(world, s1.id, s2.id, 'SECURITY_PACT', { forced: false });
            break;
          }
        }
      }
    }
  }

  function runTreatyMonthlyCycleV230(world, rng) {
    ensureWorldSystemsV230(world);
    const treaties = world.summitV230.treaties || [];
    for (let i = 0; i < treaties.length; i++) {
      const tr = treaties[i];
      if (!tr || (tr.status !== 'ACTIVE' && tr.status !== 'EXTENDED')) continue;
      const stA = world.states[tr.partyA];
      const stB = world.states[tr.partyB];
      if (!stA || !stB) continue;

      const negA = pickNegotiatorsV230(world, stA.id);
      const negB = pickNegotiatorsV230(world, stB.id);
      const headAName = negA.head ? negA.head.name : shortNameTh(stA);
      const headBName = negB.head ? negB.head.name : shortNameTh(stB);

      // (a) Check if parties are now at war or Hostile with score < 20 -> BROKEN
      const activeWar = (world.wars || []).find((w) =>
        w.status === 'War' && ((w.attackerId === stA.id && w.defenderId === stB.id) || (w.attackerId === stB.id && w.defenderId === stA.id))
      );
      const relAB = stA.relations?.[stB.id];
      const isHostileBreak = relAB && relAB.status === 'Hostile' && (relAB.score ?? 50) < 20;

      if (activeWar || isHostileBreak || tr._pendingBreachBy) {
        tr.status = 'BROKEN';
        const breakerId = tr._pendingBreachBy || (activeWar ? activeWar.attackerId : ((negA.head?.personality?.aggression || 50) >= (negB.head?.personality?.aggression || 50) ? stA.id : stB.id));
        const victimId = breakerId === stA.id ? stB.id : stA.id;
        tr.breachBy = breakerId;
        delete tr._pendingBreachBy;

        const breakerSt = world.states[breakerId] || stA;
        const victimSt = world.states[victimId] || stB;
        const breakerHead = breakerId === stA.id ? headAName : headBName;
        const victimHead = breakerId === stA.id ? headBName : headAName;

        breakerSt.trustV230 = clamp((breakerSt.trustV230 ?? 70) - 25, 0, 100);
        // Link 4: A state that breaks a treaty takes -6 cohesion in every alliance it belongs to
        (world.alliances || []).forEach((al) => {
          if (al && Array.isArray(al.members) && al.members.includes(breakerSt.id)) {
            al.cohesion = clamp((al.cohesion ?? 78) - 6, 10, 100);
          }
        });
        // Allies of victim get relation -5 toward breaker
        Object.values(world.states).forEach((ally) => {
          if (!ally || ally.id === breakerId || ally.id === victimId) return;
          if (ally.relations?.[victimId]?.status === 'Alliance' || (ally.relations?.[victimId]?.score || 50) >= 70) {
            if (ally.relations?.[breakerId]) ally.relations[breakerId].score = clamp(rnd1(ally.relations[breakerId].score - 5), 0, 100);
            if (breakerSt.relations?.[ally.id]) breakerSt.relations[ally.id].score = clamp(rnd1(breakerSt.relations[ally.id].score - 5), 0, 100);
          }
        });

        const breachTemplates = [
          `📜💔 [หักหลังสนธิสัญญา! ${shortNameTh(breakerSt)} ฉีกข้อตกลงถล่ม ${shortNameTh(victimSt)}] โลกตะลึงเมื่อ ${breakerHead} ผู้นำแห่ง ${breakerSt.name} สั่งละเมิด "${SUMMIT_TYPES_V230[tr.type]?.labelTh || tr.type}" ที่เคยลงนามไว้กับ ${victimHead} แห่ง ${victimSt.name} ส่งผลให้สถานะสนธิสัญญากลายเป็น BROKEN ทันที ค่าความน่าเชื่อถือทางการทูตของ ${shortNameTh(breakerSt)} ดิ่งเหวลง -25 เหลือเพียง ${Math.round(breakerSt.trustV230)}/100 ท่ามกลางการประณามจากชาติพันธมิตรของฝ่ายผู้เสียหาย!`,
          `📜🔥 [ทรยศสัตยาบันแห่งรัฐ! ${breakerHead} ฉีกสัญญาซัมมิต] รัฐบาลของ ${victimHead} แห่ง ${victimSt.name} ออกแถลงการณ์ฉุกเฉินประณาม ${breakerHead} แห่ง ${breakerSt.name} ที่ละเมิด "${SUMMIT_TYPES_V230[tr.type]?.labelTh || tr.type}" อย่างอุกอาจ ส่งผลให้เครดิตทางการทูตของ ${shortNameTh(breakerSt)} ร่วงลง 25 คะแนน (เหลือ ${Math.round(breakerSt.trustV230)}/100) และชาติพันธมิตรลดระดับความสัมพันธ์ลงทันที`,
          `📜⚔️ [อวสานสนธิสัญญา ${shortNameTh(stA)}–${shortNameTh(stB)} จากการหักหลัง!] การกระทำของ ${breakerHead} (${shortNameTh(breakerSt)}) ต่อ ${victimHead} (${shortNameTh(victimSt)}) ได้ทำลาย "${SUMMIT_TYPES_V230[tr.type]?.labelTh || tr.type}" ลงอย่างสิ้นเชิง สถานะสนธิสัญญาถูกบันทึกว่า BROKEN พร้อมบทลงโทษทางความน่าเชื่อถือ -25 คะแนน`,
          `📜🚨 [ฉีกกระดาษสันติภาพ! ${shortNameTh(breakerSt)} หักหลัง ${shortNameTh(victimSt)}] นักการทูตทั่วโลกต่างช็อกเมื่อ ${breakerHead} แห่ง ${breakerSt.name} ละเมิดพันธกรณีใน "${SUMMIT_TYPES_V230[tr.type]?.labelTh || tr.type}" ที่มีต่อ ${victimHead} แห่ง ${victimSt.name} ทำให้ดัชนี Trust Score ของ ${shortNameTh(breakerSt)} ลดฮวบลงสู่ ${Math.round(breakerSt.trustV230)}/100`,
          `📜💥 [วิกฤตสัตยาบันระหว่างประเทศ: ${shortNameTh(breakerSt)} ละเมิดสนธิสัญญา] สนธิสัญญา "${SUMMIT_TYPES_V230[tr.type]?.labelTh || tr.type}" ระหว่าง ${stA.name} และ ${stB.name} พังทลายลงหลัง ${breakerHead} เปิดฉากคุกคาม ${victimHead} ชาติพันธมิตรของ ${shortNameTh(victimSt)} ต่างพร้อมใจกันลดความสัมพันธ์กับ ${shortNameTh(breakerSt)} ลง -5 จุด`,
          `📜⚠️ [บันทึกความอัปยศทางการทูต: การหักหลังของ ${breakerHead}] พงศาวดารโลกจารึกการละเมิด "${SUMMIT_TYPES_V230[tr.type]?.labelTh || tr.type}" โดย ${breakerHead} แห่ง ${breakerSt.name} ต่อ ${victimHead} แห่ง ${victimSt.name} ส่งผลให้สนธิสัญญาสิ้นสภาพ (BROKEN) และความน่าเชื่อถือของ ${shortNameTh(breakerSt)} ตกต่ำลงถึง -25 คะแนน`
        ];
        addChronicle(world, 'TREATY', rng.pick(breachTemplates), breakerSt.id, { secondStateId: victimSt.id, treatyId: tr.id, personId: (breakerId === stA.id ? negA.headId : negB.headId) });
        continue;
      }

      // Link 8: For the first 60 ticks after signing, clamp relations[a][b].score >= postTreatyRelScore - 5
      if (world.tick - (tr.signedTick || 0) <= 60 && tr.postTreatyRelScore !== undefined) {
        const minRelScore = clamp(tr.postTreatyRelScore - 5, 0, 100);
        if (stA.relations?.[stB.id] && stA.relations[stB.id].score < minRelScore) {
          stA.relations[stB.id].score = minRelScore;
        }
        if (stB.relations?.[stA.id] && stB.relations[stA.id].score < minRelScore) {
          stB.relations[stA.id].score = minRelScore;
        }
      }

      // (b) 8% chance per month of a minor border incident
      if (rng.chance(0.08)) {
        const aggrA = negA.head?.personality?.aggression ?? 50;
        const aggrB = negB.head?.personality?.aggression ?? 50;
        const culprit = aggrA >= aggrB ? stA : stB;
        const other = culprit.id === stA.id ? stB : stA;
        culprit.trustV230 = clamp((culprit.trustV230 ?? 70) - 1, 0, 100);
        if (stA.relations?.[stB.id]) stA.relations[stB.id].score = clamp(rnd1(stA.relations[stB.id].score - 3), 0, 100);
        if (stB.relations?.[stA.id]) stB.relations[stA.id].score = clamp(rnd1(stB.relations[stA.id].score - 3), 0, 100);

        const incidentTemplates = [
          `📜⚠️ [เหตุกระทบกระทั่งชายแดนใต้เงาสนธิสัญญา ${shortNameTh(stA)}–${shortNameTh(stB)}] แม้จะมี "${SUMMIT_TYPES_V230[tr.type]?.labelTh || tr.type}" บังคับใช้อยู่ แต่หน่วยลาดตระเวนของ ${culprit.name} และ ${other.name} เกิดการเผชิญหน้ากันที่แนวพรมแดน ส่งผลให้ความน่าเชื่อถือของ ${shortNameTh(culprit)} ลดลง -1 (เหลือ ${Math.round(culprit.trustV230)}/100) และความสัมพันธ์ลดลง -3 จุด`,
          `📜🚨 [ละเมิดแนวกันชนย่อยระหว่าง ${shortNameTh(stA)} และ ${shortNameTh(stB)}] คณะกรรมาธิการตรวจสอบสนธิสัญญารายงานเหตุโดรนและทหารลาดตระเวนของ ${shortNameTh(culprit)} ล้ำแนวเขตของ ${shortNameTh(other)} ขัดต่อเจตนารมณ์ของ ${headAName} และ ${headBName} ทำให้ดัชนีความสัมพันธ์ลดลงสู่ ${stA.relations?.[stB.id]?.score ?? 50}/100`,
          `📜🔭 [ความตึงเครียดเฉพาะจุดตามแนวสนธิสัญญา ${tr.id}] รัฐบาลของ ${other.name} ยื่นหนังสือประท้วง ${culprit.name} กรณีซ้อมรบเฉียดแนวเขตปลอดทหารตาม "${SUMMIT_TYPES_V230[tr.type]?.labelTh || tr.type}" ส่งผลให้เครดิตทางการทูตของ ${shortNameTh(culprit)} หดตัวลง 1 คะแนน`,
          `📜🛡️ [ทดสอบความอดทนบนเส้นแบ่งเขต ${shortNameTh(stA)}–${shortNameTh(stB)}] เกิดเหตุยิงพลุเตือนและสกัดกั้นทางเรดาร์ระหว่างหน่วยหน้าของ ${shortNameTh(culprit)} และ ${shortNameTh(other)} ภายใต้กรอบ "${SUMMIT_TYPES_V230[tr.type]?.labelTh || tr.type}" ทำให้ทูตของ ${headAName} และ ${headBName} ต้องเปิดสายด่วนเคลียร์ใจ`,
          `📜📡 [สัญญาณรบกวนเรดาร์ชายแดนกระทบสนธิสัญญา] ฝ่ายความมั่นคงของ ${other.name} ตรวจพบการเคลื่อนไหวผิดปกติจากฝั่ง ${culprit.name} ซึ่งเสี่ยงบั่นทอน "${SUMMIT_TYPES_V230[tr.type]?.labelTh || tr.type}" ส่งผลให้ความสัมพันธ์ทวิภาคีลดลง 3 คะแนน`,
          `📜⚡ [เหตุปะทะคารมที่ด่านพรมแดน ${shortNameTh(culprit)}–${shortNameTh(other)}] เจ้าหน้าที่ชายแดนของทั้งสองฝ่ายเกิดข้อพิพาทเรื่องการตีความแนวเขตใน "${SUMMIT_TYPES_V230[tr.type]?.labelTh || tr.type}" ทำให้ความน่าเชื่อถือของ ${shortNameTh(culprit)} ลดลงสู่ระดับ ${Math.round(culprit.trustV230)}/100`
        ];
        addChronicle(world, 'TREATY', rng.pick(incidentTemplates), culprit.id, { secondStateId: other.id, treatyId: tr.id });
      }

      // (c) Settle monthly obligations
      if (Array.isArray(tr.obligations) && tr.obligations.length > 0) {
        tr.obligations.forEach((ob) => {
          if (!ob || ob.remainingMonths <= 0) return;
          const payer = world.states[ob.payerId];
          const receiver = world.states[ob.receiverId];
          if (payer && receiver) {
            let transferB = 0;
            if (ob.type === 'REPARATIONS') {
              transferB = Math.min(Math.max(0.5, payer.treasuryB * 0.25), ob.monthlyAmountB || 1.5);
            } else if (ob.type === 'RESOURCE_CONCESSION') {
              transferB = rnd1(Math.max(0.4, (payer.gdpB || 100) * ((ob.pct || 5) / 100) * 0.04));
            }
            payer.treasuryB = rnd1(Math.max(5, payer.treasuryB - transferB));
            receiver.treasuryB = rnd1(receiver.treasuryB + transferB);
          }
          ob.remainingMonths -= 1;
        });
        tr.obligations = tr.obligations.filter((ob) => ob.remainingMonths > 0);
      }

      // (d) Check expiry
      if (world.tick >= (tr.expiresTick || 999999)) {
        if (tr.type === 'CEASEFIRE') {
          tr.status = 'EXPIRED';
          if (rng.chance(0.55)) {
            startSummitV230(world, stA.id, stB.id, 'PEACE_TREATY', { forced: true });
            addChronicle(world, 'TREATY', `📜🕊️ [ข้อตกลงหยุดยิงครบกำหนด — ยกระดับสู่โต๊ะเจรจาสันติภาพถาวร!] เมื่อข้อตกลงหยุดยิง (${tr.id}) ระหว่าง ${stA.name} และ ${stB.name} ครบกำหนด 180 วัน ผู้นำ ${headAName} และ ${headBName} เห็นพ้องให้เปิดโต๊ะเจรจาสนธิสัญญาสันติภาพถาวร (PEACE_TREATY) ต่อเนื่องทันที`, stA.id, { secondStateId: stB.id, treatyId: tr.id });
          } else {
            setDiplomaticStatus(world, stA.id, stB.id, 'Hostile');
            addChronicle(world, 'TREATY', `📜⏳ [ข้อตกลงหยุดยิงหมดอายุ — ความตึงเครียดปะทุกลับสู่สถานะปรปักษ์!] ข้อตกลงหยุดยิง (${tr.id}) ระหว่าง ${stA.name} (${headAName}) และ ${stB.name} (${headBName}) สิ้นสุดอายุลงโดยไม่สามารถต่อยอดเป็นสันติภาพถาวร ทำให้ทั้งสองรัฐกลับสู่สถานะ Hostile ทันที`, stA.id, { secondStateId: stB.id, treatyId: tr.id });
          }
        } else {
          if (rng.chance(0.50)) {
            tr.status = 'EXTENDED';
            tr.expiresTick = world.tick + 1460;
            addChronicle(world, 'TREATY', `📜🔄 [ต่ออายุสนธิสัญญา ${tr.id} ออกไปอีก 4 ปี!] รัฐบาลของ ${headAName} แห่ง ${stA.name} และ ${headBName} แห่ง ${stB.name} ลงนามต่ออายุ "${SUMMIT_TYPES_V230[tr.type]?.labelTh || tr.type}" ออกไปอีก 1,460 วัน เพื่อรักษาเสถียรภาพและผลประโยชน์ร่วมกัน`, stA.id, { secondStateId: stB.id, treatyId: tr.id });
          } else {
            tr.status = 'EXPIRED';
            addChronicle(world, 'TREATY', `📜⌛ [สนธิสัญญา ${tr.id} สิ้นสุดอายุขัยตามกำหนด] "${SUMMIT_TYPES_V230[tr.type]?.labelTh || tr.type}" ระหว่าง ${stA.name} (${headAName}) และ ${stB.name} (${headBName}) ครบกำหนดอายุสัญญาและสิ้นสุดผลผูกพันลงอย่างเป็นทางการ`, stA.id, { secondStateId: stB.id, treatyId: tr.id });
          }
        }
      }
    }
  }

  function runStateVisitCycleV230(world, rng) {
    ensureWorldSystemsV230(world);
    const live = Object.values(world.states).filter((s) => !s.isExiled);
    if (live.length < 2) return;

    const agendas = [
      'ข้อตกลงความมั่นคงด้านพลังงานและท่อส่งก๊าซ',
      'การจัดซื้อยุทโธปกรณ์และการถ่ายทอดเทคโนโลยีป้องกันประเทศ',
      'โครงการแลกเปลี่ยนนักศึกษาและนักวิจัยปัญญาประดิษฐ์',
      'สิทธิการเข้าถึงท่าเรือน้ำลึกและเส้นทางโลจิสติกส์',
      'การซ้อมรบร่วมผสมสามเหล่าทัพประจำปี',
      'ความร่วมมือด้านวัคซีนและความมั่นคงทางชีวภาพ',
      'สัญญาซื้อขายแร่หายากและห่วงโซ่แบตเตอรี่ระยะยาว',
      'การยกเว้นวีซ่าท่องเที่ยวและระเบียงเศรษฐกิจการค้าเสรี'
    ];
    const anecdotes = [
      'การมอบของขวัญประจำชาติชิ้นพิเศษในงานเลี้ยงรับรองอย่างสมเกียรติ',
      'สุนทรพจน์ภาษาถิ่นของผู้นำผู้มาเยือนที่เรียกเสียงปรบมือดังกึกก้องรัฐสภา',
      'กลุ่มผู้ชุมนุมประท้วงเล็กๆ นอกรั้วทำเนียบรัฐบาลที่ถูกเจ้าหน้าที่ควบคุมตัวอย่างสงบ',
      'พายุฝนฟ้าคะนองกะทันหันทำให้ต้องย้ายพิธีตรวจแถวกองเกียรติยศเข้าสู่อาคารรับรอง',
      'ขบวนรถผู้นำล่าช้ากว่ากำหนด 25 นาทีจากการปิดถนนรักษาความปลอดภัยขั้นสูงสุด',
      'การเดินสนทนาแบบตัวต่อตัวในสวนสวยของทำเนียบรัฐบาลโดยไม่มีล่ามติดตาม'
    ];

    let visitsDone = 0;
    for (let attempt = 0; attempt < 14 && visitsDone < 2; attempt++) {
      const stA = rng.pick(live);
      const stB = rng.pick(live);
      if (!stA || !stB || stA.id === stB.id) continue;
      const rel = stA.relations?.[stB.id];
      if (!rel || (rel.status !== 'Peace' && rel.status !== 'Alliance') || (rel.score || 50) < 55) continue;

      visitsDone++;
      const negA = pickNegotiatorsV230(world, stA.id);
      const negB = pickNegotiatorsV230(world, stB.id);
      const visitorName = negA.head ? negA.head.name : (negA.chief ? negA.chief.name : `ผู้นำ ${shortNameTh(stA)}`);
      const hostName = negB.head ? negB.head.name : (negB.chief ? negB.chief.name : `ผู้นำ ${shortNameTh(stB)}`);
      const capB = stateCities(world, stB.id).find((c) => c.isCapital) || stateCities(world, stB.id)[0] || Object.values(world.cities)[0];
      const cityName = capB ? cityNameTh(capB) : 'เมืองหลวง';
      const agenda = rng.pick(agendas);
      const anecdote = rng.pick(anecdotes);

      // 10% chance of minor diplomatic gaffe (relation -2) with >= 4 templates
      if (rng.chance(0.10)) {
        rel.score = clamp(rnd1(rel.score - 2), 0, 100);
        if (stB.relations?.[stA.id]) stB.relations[stA.id].score = rel.score;
        const gaffeTemplates = [
          `🛬😬 [ดราม่าการทูตระหว่างการเยือน ${cityName}!] ระหว่างการเยือน ${stB.name} อย่างเป็นทางการของ ${visitorName} แห่ง ${stA.name} เพื่อหารือกับ ${hostName} เรื่อง${agenda} เกิดเหตุผิดพลาดทางพิธีการทูตและการหลุดคำพูดวิจารณ์นโยบายภายในของเจ้าภาพไมโครโฟนที่ยังไม่ได้ปิด ส่งผลให้บรรยากาศตึงเครียดและดัชนีความสัมพันธ์ลดลง -2 จุด (เหลือ ${rel.score}/100)`,
          `🛬⚠️ [ผิดคิวทางการทูตที่ ${cityName} กระทบความสัมพันธ์ ${shortNameTh(stA)}–${shortNameTh(stB)}] การเดินทางเยือนเมือง${cityName} ของ ${visitorName} (${shortNameTh(stA)}) เพื่อพบกับ ${hostName} (${shortNameTh(stB)}) ในวาระ${agenda} ต้องสะดุดลงเมื่อคณะทำงานเกิดความขัดแย้งเรื่องลำดับเกียรติและการแถลงข่าวร่วม จนความสัมพันธ์ทวิภาคีลดลง 2 คะแนนสู่ระดับ ${rel.score}/100`,
          `🛬📉 [ควันหลงการเยือน ${cityName}: ถ้อยแถลงผิดพลาดสร้างรอยร้าว] แม้ ${visitorName} แห่ง ${stA.name} และ ${hostName} แห่ง ${stB.name} จะเริ่มต้นการหารือเรื่อง${agenda} ณ เมือง${cityName} ด้วยดี แต่ความเข้าใจผิดในการแปลถ้อยแถลงต่อสื่อมวลชนและ${anecdote} ทำให้กระแสสังคมไม่พอใจและความสัมพันธ์ลดลง -2 จุด`,
          `🛬🚨 [อุบัติเหตุทางการทูตกลางงานเลี้ยงรับรอง ณ ${cityName}] การเยือนสันถวไมตรีของ ${visitorName} (${shortNameTh(stA)}) ณ ทำเนียบรัฐบาลของ ${hostName} (${shortNameTh(stB)}) ในเมือง${cityName} เกี่ยวกับ${agenda} เกิดความขุ่นเคืองเรื่องพิธีการทูต ส่งผลให้ความสัมพันธ์ของทั้งสองประเทศลดลงเหลือ ${rel.score}/100`
        ];
        addChronicle(world, 'STATE_VISIT', rng.pick(gaffeTemplates), stA.id, { secondStateId: stB.id, cityId: capB ? capB.id : null, personId: negA.headId });
      } else {
        const gain = rng.int(1, 3);
        rel.score = clamp(rnd1(rel.score + gain), 0, 100);
        if (stB.relations?.[stA.id]) stB.relations[stA.id].score = rel.score;
        stA.trustV230 = clamp((stA.trustV230 ?? 70) + 1, 0, 100);
        stB.trustV230 = clamp((stB.trustV230 ?? 70) + 1, 0, 100);

        // >= 8 distinct normal state visit templates
        const visitTemplates = [
          `🛬🤝 [การเยือนระดับประมุขแห่งรัฐ ณ ${cityName}] ${visitorName} ผู้นำแห่ง ${stA.name} เดินทางเยือนมหานคร${cityName} ตามคำเชิญของ ${hostName} ผู้นำแห่ง ${stB.name} เพื่อผลักดัน "${agenda}" โดยมีสีสันสำคัญคือ${anecdote} ส่งผลให้ความสัมพันธ์ทวิภาคีปรับเพิ่มขึ้น +${gain} จุด สู่ระดับ ${rel.score}/100 และความน่าเชื่อถือทางการทูตเพิ่มขึ้นเป็น ${Math.round(stA.trustV230)}/100`,
          `🛬🏛️ [ปูพรมแดงต้อนรับ ${visitorName} สู่เมือง${cityName}] ทำเนียบรัฐบาลแห่ง ${stB.name} ณ เมือง${cityName} จัดพิธีต้อนรับ ${visitorName} แห่ง ${stA.name} อย่างยิ่งใหญ่ โดยผู้นำทั้งสอง (${visitorName} และ ${hostName}) เห็นชอบในกรอบ "${agenda}" ท่ามกลางบรรยากาศ${anecdote} ดันความสัมพันธ์สู่ ${rel.score}/100 (+${gain})`,
          `🛬✨ [กระชับมิตรไมตรี ${shortNameTh(stA)}–${shortNameTh(stB)} ณ มหานคร${cityName}] การพบปะสุดยอดทวิภาคีระหว่าง ${visitorName} (${shortNameTh(stA)}) และ ${hostName} (${shortNameTh(stB)}) ที่เมือง${cityName} ประสบความสำเร็จอย่างงดงามในการเจรจา "${agenda}" พร้อมเหตุการณ์น่าจดจำจาก${anecdote} เพิ่มระดับความไว้เนื้อเชื่อใจเป็น ${rel.score}/100`,
          `🛬🌐 [ทูตสันถวไมตรีและการค้า ณ ${cityName}] เครื่องบินประจำตำแหน่งของ ${visitorName} แห่ง ${stA.name} ลงจอดที่เมือง${cityName} เพื่อร่วมประชุมทวิภาคีกับ ${hostName} แห่ง ${stB.name} ว่าด้วย "${agenda}" โดยมีไฮไลต์คือ${anecdote} ช่วยยกระดับความสัมพันธ์ขึ้น +${gain} คะแนน`,
          `🛬🥂 [งานเลี้ยงรับรองแห่งรัฐและดีลยุทธศาสตร์ที่ ${cityName}] ${hostName} ผู้นำ ${shortNameTh(stB)} เปิดทำเนียบในเมือง${cityName} ต้อนรับการเยือนของ ${visitorName} ผู้นำ ${shortNameTh(stA)} ทั้งสองฝ่ายลงนามบันทึกความเข้าใจด้าน "${agenda}" ท่ามกลางเกร็ดข่าว${anecdote} ส่งผลให้ดัชนีมิตรภาพพุ่งขึ้นเป็น ${rel.score}/100`,
          `🛬📜 [บันทึกการเยือนประวัติศาสตร์ ณ ${cityName}] สื่อมวลชนในเมือง${cityName} รายงานข่าวการเยือนของ ${visitorName} แห่ง ${stA.name} ที่เข้าหารือกับ ${hostName} แห่ง ${stB.name} ในประเด็น "${agenda}" พร้อมภาพประทับใจจาก${anecdote} เสริมสร้างความเชื่อมั่นทางการทูตของทั้งสองประเทศ (+${gain} ความสัมพันธ์)`,
          `🛬🎖️ [ตรวจแถวกองเกียรติยศและเปิดดีลใหญ่ที่ ${cityName}] ${visitorName} (${shortNameTh(stA)}) และ ${hostName} (${shortNameTh(stB)}) ร่วมพิธีตรวจแถวกองเกียรติยศ ณ เมือง${cityName} ก่อนบรรลุข้อตกลง "${agenda}" แม้จะมีเหตุการณ์${anecdote} แต่การเยือนช่วยหนุนความสัมพันธ์สู่ ${rel.score}/100`,
          `🛬🌟 [มิติใหม่ความร่วมมือ ${shortNameTh(stA)}–${shortNameTh(stB)} ที่เมือง${cityName}] การเยือนอย่างเป็นทางการของ ${visitorName} ณ เมือง${cityName} ได้รับการต้อนรับอย่างอบอุ่นจาก ${hostName} ทั้งสองผู้นำประกาศความก้าวหน้าใน "${agenda}" และสร้างความประทับใจด้วย${anecdote} ดันความน่าเชื่อถือทางการทูตสู่ ${Math.round(stA.trustV230)} และ ${Math.round(stB.trustV230)}`
        ];
        addChronicle(world, 'STATE_VISIT', rng.pick(visitTemplates), stA.id, { secondStateId: stB.id, cityId: capB ? capB.id : null, personId: negA.headId });
      }
    }
  }

  // -------------------------------------------------------------------------
  // T2 — TRADE WAR & SANCTION LADDER
  // -------------------------------------------------------------------------
  const TRADE_LADDER_V230 = [
    null,
    { level: 1, id: 'TARIFF_SELECTIVE', labelTh: 'กำแพงภาษีเฉพาะกลุ่มอุตสาหกรรม (8%)', tariffPct: 8 },
    { level: 2, id: 'TARIFF_BROAD', labelTh: 'กำแพงภาษีตอบโต้วงกว้าง (25%)', tariffPct: 25 },
    { level: 3, id: 'TECH_EXPORT_CONTROL', labelTh: 'ควบคุมการส่งออกเทคโนโลยีขั้นสูงและชิป', tariffPct: 45 },
    { level: 4, id: 'FINANCIAL_SANCTIONS', labelTh: 'คว่ำบาตรทางการเงิน อายัดทรัพย์สิน และตัดระบบชำระเงิน', tariffPct: 75 },
    { level: 5, id: 'FULL_EMBARGO', labelTh: 'ปิดล้อมทางการค้าและคว่ำบาตรเบ็ดเสร็จทุกสาขา (Full Embargo)', tariffPct: 100 }
  ];

  const TRADE_SECTORS_V230 = [
    'เซมิคอนดักเตอร์',
    'พลังงาน',
    'เกษตร',
    'ยานยนต์',
    'เหล็กกล้า',
    'เภสัชภัณฑ์',
    'อาวุธและยุทโธปกรณ์',
    'แร่หายาก'
  ];

  const LEVEL_DAMAGE_V230 = [0, 0.04, 0.10, 0.14, 0.22, 0.40];
  const CREDIT_RATINGS_ORDER_V230 = ['AAA', 'AA', 'A', 'BBB', 'BB', 'B', 'CCC', 'SD'];

  const _origRecomputeCreditRatingV230 = recomputeCreditRatingV210;
  recomputeCreditRatingV210 = function (st) {
    const baseRating = _origRecomputeCreditRatingV230(st);
    if (!st || !st.sovereignDebt) return baseRating;
    // If state has active trade-war bond yield penalty or pre-sanction rating ceiling, never allow rating to improve while measure is active
    if ((st._tradeWarBondYieldAddedV230 || 0) > 0 || st._preSanctionRatingV230) {
      const ceilRating = st._preSanctionRatingV230 || baseRating;
      const ceilIdx = CREDIT_RATINGS_ORDER_V230.indexOf(ceilRating);
      let curIdx = CREDIT_RATINGS_ORDER_V230.indexOf(baseRating);
      if ((st._tradeWarBondYieldAddedV230 || 0) >= 0.35 && curIdx < CREDIT_RATINGS_ORDER_V230.length - 1) {
        curIdx = Math.min(CREDIT_RATINGS_ORDER_V230.length - 1, curIdx + Math.floor((st._tradeWarBondYieldAddedV230 || 0) / 0.35));
      }
      if (ceilIdx >= 0 && curIdx < ceilIdx) {
        curIdx = ceilIdx;
      }
      st.sovereignDebt.creditRating = CREDIT_RATINGS_ORDER_V230[Math.max(0, curIdx)] || baseRating;
      st._preSanctionRatingV230 = st.sovereignDebt.creditRating; // Monotonic non-improvement while sanctioned
      return st.sovereignDebt.creditRating;
    }
    return baseRating;
  };

  function ensureTradeWarV230(world) {
    if (!world || !world.states) return;
    if (!world.tradeWarV230) {
      // Cap: 120 active measures, 200 history entries
      world.tradeWarV230 = {
        nextId: 1,
        measures: [],
        history: []
      };
    }
    Object.values(world.states).forEach((st) => {
      if (!Array.isArray(st.sanctionedBy)) st.sanctionedBy = [];
      if (st.nuclear && !Array.isArray(st.nuclear.sanctionedBy)) st.nuclear.sanctionedBy = [];
      if (st._tradeWarInfAddedV230 === undefined) st._tradeWarInfAddedV230 = 0;
    });
  }

  // Exposure of state A (self) to state B (other) = how much A depends on trade with B (0..1, deterministic)
  function getTradeExposureV230(world, aOrId, bOrId) {
    const A = resolveStateObjV230(world, aOrId);
    const B = resolveStateObjV230(world, bOrId);
    if (!A || !B || A.id === B.id) return 0;
    const isPartner = (Array.isArray(A.tradePartners) && A.tradePartners.includes(B.id)) ||
                      (Array.isArray(B.tradePartners) && B.tradePartners.includes(A.id));
    const base = isPartner ? 0.55 : (A.region === B.region ? 0.25 : 0.12);
    const gdpSelf = Math.max(5, A.gdpB || 100);
    const gdpOther = Math.max(5, B.gdpB || 100);
    const mult = clamp(gdpOther / gdpSelf, 0.2, 2.0) / 2;
    return clamp(base * mult, 0, 1);
  }

  function syncSanctionedByArraysV230(world, targetSt) {
    if (!targetSt) return;
    if (!Array.isArray(targetSt.sanctionedBy)) targetSt.sanctionedBy = [];
    if (targetSt.nuclear && !Array.isArray(targetSt.nuclear.sanctionedBy)) targetSt.nuclear.sanctionedBy = [];
    const activeHeavyImposers = (world.tradeWarV230?.measures || [])
      .filter((m) => m.status === 'ACTIVE' && m.targetId === targetSt.id && m.level >= 3)
      .map((m) => m.imposerId);
    activeHeavyImposers.forEach((impId) => {
      if (!targetSt.sanctionedBy.includes(impId)) targetSt.sanctionedBy.push(impId);
      if (targetSt.nuclear && !targetSt.nuclear.sanctionedBy.includes(impId)) targetSt.nuclear.sanctionedBy.push(impId);
    });
  }

  function getImposedTemplatesByLevelV230(lvl, imp, tgt, headImpName, secTxt, reason) {
    const iName = imp.name;
    const tName = tgt.name;
    const iShort = shortNameTh(imp);
    const tShort = shortNameTh(tgt);
    if (lvl === 1) {
      return [
        `⚔️📦 [เปิดศึกกำแพงภาษีระดับ 1 (8%) — ${iShort} เล็งเป้า ${tShort}] ${headImpName} ผู้นำแห่ง ${iName} ลงนามคำสั่งตั้งกำแพงภาษีศุลกากร 8% ต่อสินค้านำเข้าหมวด (${secTxt}) จาก ${tName} ด้วยเหตุผลด้าน "${reason}" ส่งผลให้ผู้ส่งออกของทั้งสองประเทศต้องเร่งปรับราคาสินค้าทันที`,
        `⚔️🛃 [ตั้งด่านภาษีเฉพาะจุด 8% ต่อสินค้า ${tShort}] กระทรวงพาณิชย์ของ ${iName} ภายใต้การนำของ ${headImpName} ประกาศเก็บภาษีนำเข้าเพิ่ม 8% ในกลุ่มอุตสาหกรรม (${secTxt}) จาก ${tName} เพื่อปกป้องผู้ผลิตภายในประเทศและกดดันดุลการค้าทวิภาคี`,
        `⚔️📉 [สัญญาณเตือนสงครามการค้า: ${iShort} เก็บภาษี 8% หมวด ${secTxt}] รัฐบาล ${headImpName} แห่ง ${iName} เปิดฉากมาตรการทางเศรษฐกิจระดับที่ 1 ต่อ ${tName} โดยขึ้นพิกัดศุลกากร 8% ในกลุ่ม (${secTxt}) สร้างแรงกระเพื่อมต่อตลาดสินค้าโภคภัณฑ์ในภูมิภาค`,
        `⚔️🏭 [ปกป้องอุตสาหกรรมในประเทศ! ${iShort} ตั้งภาษี 8% สินค้า ${tShort}] ${headImpName} แถลงมาตรการตอบโต้ทางการค้าระดับ 1 ต่อ ${tName} โดยมุ่งเป้าเก็บภาษี 8% ในสาขา (${secTxt}) พร้อมขู่จะยกระดับหากฝ่ายตรงข้ามไม่ยอมเปิดโต๊ะเจรจา`,
        `⚔️🚢 [ท่าเรือศุลกากร ${iShort} บังคับใช้พิกัดภาษีใหม่ 8% ต่อ ${tShort}] คำสั่งของ ${headImpName} แห่ง ${iName} มีผลบังคับใช้ในการเรียกเก็บอากรขาเข้า 8% สำหรับสินค้า (${secTxt}) จาก ${tName} อันเนื่องมาจากชนวน "${reason}"`,
        `⚔️⚖️ [หมากภาษีศุลกากร 8% ของ ${headImpName} กดดัน ${tShort}] ${iName} เปิดใช้มาตรการบันไดขั้นที่ 1 (TARIFF_SELECTIVE 8%) ต่ออุตสาหกรรม (${secTxt}) ของ ${tName} ทำให้ต้นทุนการค้าระหว่างสองรัฐปรับตัวสูงขึ้นทันที`
      ];
    } else if (lvl === 2) {
      return [
        `⚔️🔥 [ยกระดับกำแพงภาษีวงกว้างระดับ 2 (25%)! ${iShort} ถล่มสินค้า ${tShort}] ${headImpName} ผู้นำแห่ง ${iName} ประกาศมาตรการ TARIFF_BROAD เก็บภาษีศุลกากรสูงถึง 25% ครอบคลุมอุตสาหกรรม (${secTxt}) ของ ${tName} จากชนวน "${reason}" ส่งผลให้มูลค่าการค้าทวิภาคีชะลอตัวลงอย่างรุนแรง`,
        `⚔️📊 [กำแพงภาษี 25% สะเทือนห่วงโซ่อุปทาน ${iShort}–${tShort}] ทำเนียบรัฐบาลของ ${headImpName} แห่ง ${iName} บังคับใช้มาตรการภาษีระดับ 2 (25%) ต่อสินค้า (${secTxt}) จาก ${tName} กดดันให้โรงงานอุตสาหกรรมใน ${tShort} เผชิญภาวะต้นทุนพุ่งสูง`,
        `⚔️🚨 [สงครามภาษีเต็มรูปแบบ! ${iShort} ฟันภาษี 25% หมวด ${secTxt}] ${headImpName} แห่ง ${iName} ยกระดับการกดดันทางเศรษฐกิจต่อ ${tName} สู่ระดับ 2 ด้วยการตั้งกำแพงภาษี 25% ในสาขา (${secTxt}) ท่ามกลางความผันผวนของค่าเงินและตลาดหุ้น`,
        `⚔️📦 [มาตรการภาษี 25% ของ ${headImpName} ถล่มภาคส่งออก ${tShort}] ${iName} ประกาศขึ้นบัญชีสินค้า (${secTxt}) จาก ${tName} ต้องเสียภาษีนำเข้า 25% เต็มพิกัด เพื่อตอบโต้กรณี "${reason}" อย่างเด็ดขาด`,
        `⚔️🏭 [ผู้ส่งออก ${tShort} อ่วม! ${iShort} บังคับใช้กำแพงภาษี 25%] ภายใต้คำสั่งของ ${headImpName} ด่านศุลกากรทั่ว ${iName} เรียกเก็บภาษี 25% (ระดับ 2) สำหรับสินค้า (${secTxt}) จาก ${tName} สร้างความเสียหายต่อรายได้การส่งออกรายเดือนทันที`,
        `⚔️⚡ [เปิดศึกการค้าวงกว้าง 25%: ${iShort} ปะทะ ${tShort}] ${headImpName} แห่ง ${iName} เดินหน้ามาตรการระดับ 2 (TARIFF_BROAD 25%) เล็งเป้ากลุ่ม (${secTxt}) ของ ${tName} เพื่อบีบให้ยอมจำนนทางยุทธศาสตร์`
      ];
    } else if (lvl === 3) {
      return [
        `⚔️🔬 [แบนส่งออกชิปและเทคโนโลยีขั้นสูงระดับ 3! ${iShort} บล็อก ${tShort}] ${headImpName} ผู้นำแห่ง ${iName} ลงนามคำสั่งความมั่นคง TECH_EXPORT_CONTROL (ระดับ 3) ห้ามส่งออกเทคโนโลยีและสินค้ายุทธศาสตร์ในหมวด (${secTxt}) ไปยัง ${tName} อย่างเด็ดขาด พร้อมขึ้นบัญชีดำบริษัทเทคโนโลยีของ ${tShort}!`,
        `⚔️💻 [สงครามชิปและเทคโนโลยีเดือด! ${iShort} ตัดสายพาน ${tShort}] รัฐบาลของ ${headImpName} แห่ง ${iName} ประกาศมาตรการระดับ 3 ควบคุมการส่งออกขั้นสูงสุดในสาขา (${secTxt}) ต่อ ${tName} เพื่อสกัดกั้นการพัฒนาขีดความสามารถทางอุตสาหกรรมและกองทัพ`,
        `⚔️🚫 [ขึ้นบัญชีดำเทคโนโลยี! ${headImpName} สั่งตัดซัพพลาย ${secTxt} ของ ${tShort}] ${iName} บังคับใช้มาตรการคว่ำบาตรเทคโนโลยีระดับ 3 ต่อ ${tName} จากชนวน "${reason}" ส่งผลให้โรงงานไฮเทคของ ${tShort} ขาดแคลนชิ้นส่วนสำคัญทันที`,
        `⚔️🛡️ [มาตรการ TECH_EXPORT_CONTROL ระดับ 3 เขย่า ${tShort}] ภายใต้การนำของ ${headImpName} กระทรวงความมั่นคงและการค้าของ ${iName} สั่งระงับใบอนุญาตส่งออก (${secTxt}) ทั้งหมดไปยัง ${tName} บีบให้ ${tShort} ต้องเร่งหาทางพึ่งพาตนเอง`,
        `⚔️📡 [ปิดกั้นเทคโนโลยีชั้นสูง! ${iShort} ยกระดับคว่ำบาตร ${tShort} สู่ขั้น 3] ${headImpName} แห่ง ${iName} แถลงตัดการเข้าถึงสิทธิบัตรและเครื่องจักรในหมวด (${secTxt}) ต่อ ${tName} ทำให้ดัชนีความตึงเครียดทางเศรษฐกิจพุ่งทะยาน`,
        `⚔️⚙️ [ศึกชิงความเหนือกว่าทางเทคโนโลยี: ${iShort} คว่ำบาตรระดับ 3 ต่อ ${tShort}] คำสั่งของ ${headImpName} แห่ง ${iName} ตัดขาดการส่งมอบ (${secTxt}) ให้แก่ ${tName} อย่างเป็นทางการ พร้อมบันทึกชื่อ ${iShort} ในทะเบียนผู้คว่ำบาตรความมั่นคง`
      ];
    } else if (lvl === 4) {
      return [
        `⚔️🏦 [คว่ำบาตรทางการเงินระดับ 4! ${iShort} อายัดทรัพย์สินและตัดระบบชำระเงิน ${tShort}] ${headImpName} ผู้นำแห่ง ${iName} ประกาศมาตรการ FINANCIAL_SANCTIONS ขั้นรุนแรงต่อ ${tName} ทั้งการอายัดทรัพย์สินในต่างประเทศและตัดธนาคารของ ${tShort} ออกจากระบบชำระเงินสากล ครอบคลุมทุกสาขาอุตสาหกรรม (${secTxt})!`,
        `⚔️❄️ [แช่แข็งทุนสำรองและตัดเส้นเลือดการเงิน ${tShort}!] รัฐบาล ${headImpName} แห่ง ${iName} ยกระดับสงครามเศรษฐกิจสู่ระดับ 4 (FINANCIAL_SANCTIONS) ต่อ ${tName} จากชนวน "${reason}" ส่งผลให้ค่าเงินของ ${tShort} อ่อนค่าลงและอัตราเงินเฟ้อพุ่งสูงทันที`,
        `⚔️💸 [อาวุธทางการเงินขั้นแตกหัก! ${iShort} บล็อกธุรกรรมธนาคาร ${tShort}] ${headImpName} แห่ง ${iName} ลงนามคว่ำบาตรทางการเงินระดับ 4 ต่อ ${tName} ห้ามสถาบันการเงินทำธุรกรรมในทุกกลุ่มอุตสาหกรรม (${secTxt}) สร้างแรงสั่นสะเทือนต่อตลาดพันธบัตรและทุนสำรองของ ${tShort}`,
        `⚔️🚨 [ปิดล้อมระบบการเงินระดับ 4: ${iShort} เล็งเป้าทำลายเศรษฐกิจ ${tShort}] กระทรวงการคลังของ ${iName} ภายใต้คำสั่ง ${headImpName} ประกาศอายัดทรัพย์สินและระงับสินเชื่อการค้าทั้งหมดของ ${tName} ส่งผลกระทบต่อ GDP และเสถียรภาพค่าเงินอย่างหนัก`,
        `⚔️📉 [วิกฤตสภาพคล่องข้ามพรมแดน! ${iShort} ใช้มาตรการระดับ 4 ต่อ ${tShort}] ${headImpName} แห่ง ${iName} งัดมาตรการคว่ำบาตรทางการเงินเต็มรูปแบบต่อ ${tName} ตัดช่องทางโอนเงินสกุลหลักในหมวด (${secTxt}) ทั้งหมด`,
        `⚔️⚖️ [มาตรการ FINANCIAL_SANCTIONS ระดับ 4 ของ ${headImpName} ถล่ม ${tShort}] ${iName} ประกาศตัดขาดความเชื่อมโยงทางการเงินและการธนาคารกับ ${tName} เพื่อลงโทษกรณี "${reason}" ท่ามกลางความตื่นตระหนกของนักลงทุน`
      ];
    } else {
      return [
        `⚔️🛑 [คว่ำบาตรเบ็ดเสร็จระดับ 5 (FULL EMBARGO)! ${iShort} ปิดล้อมเศรษฐกิจ ${tShort} ทุกมิติ] ${headImpName} ผู้นำแห่ง ${iName} ประกาศมาตรการขั้นสูงสุด FULL_EMBARGO (ระดับ 5) ตัดขาดการค้า การเงิน พลังงาน และเทคโนโลยีทุกสาขา (${secTxt}) กับ ${tName} อย่างสิ้นเชิง พร้อมขู่ลงโทษประเทศที่สามที่ลักลอบค้าขายด้วย!`,
        `⚔️🚨 [ปิดตายทางการค้า 100%! ${iShort} ใช้มาตรการระดับ 5 ถล่ม ${tShort}] ทำเนียบรัฐบาลของ ${headImpName} แห่ง ${iName} สั่งบังคับใช้การปิดล้อมทางเศรษฐกิจขั้นสูงสุด (Level 5 Full Embargo) ต่อ ${tName} จากชนวน "${reason}" ส่งผลให้เรือสินค้าและธุรกรรมระหว่างสองประเทศหยุดชะงักทันที`,
        `⚔️💥 [สงครามเศรษฐกิจเต็มขั้น! ${headImpName} ประกาศ FULL EMBARGO ต่อ ${tShort}] ${iName} ระงับการนำเข้าและส่งออกสินค้าทุกประเภท (${secTxt}) กับ ${tName} ภายใต้มาตรการระดับ 5 สร้างความเสียหายต่อ GDP และเร่งอัตราเงินเฟ้อใน ${tShort} อย่างรุนแรง`,
        `⚔️🏴 [ตัดขาดการค้าและการทูตเศรษฐกิจ: ${iShort} คว่ำบาตรระดับ 5 ต่อ ${tShort}] คำสั่งบริหารสูงสุดของ ${headImpName} แห่ง ${iName} บังคับใช้การคว่ำบาตรเบ็ดเสร็จทุกอุตสาหกรรมต่อ ${tName} นับเป็นมาตรการลงโทษทางเศรษฐกิจที่รุนแรงที่สุดแห่งยุค`,
        `⚔️⚓ [ตรวจยึดสินค้าและปิดด่านการค้า! ${iShort} ใช้ FULL EMBARGO กดดัน ${tShort}] ภายใต้คำสั่งของ ${headImpName} หน่วยงานศุลกากรและกองเรือของ ${iName} บังคับใช้มาตรการคว่ำบาตรระดับ 5 ต่อ ${tName} ครอบคลุมทุกสาขาเศรษฐกิจ`,
        `⚔️🔥 [มาตรการขั้นสุดระดับ 5! ${iShort} ประกาศสงครามเศรษฐกิจเบ็ดเสร็จต่อ ${tShort}] ${headImpName} แห่ง ${iName} ยืนยันการใช้ FULL_EMBARGO เพื่อบดขยี้ศักยภาพทางเศรษฐกิจของ ${tName} จนกว่าจะยอมจำนนต่อข้อเรียกร้องทางการเมือง`
      ];
    }
  }

  function triggerAlliesAndCondemnationOnMeasureV230(world, measure, isEscalation, rng) {
    const imp = world.states[measure.imposerId];
    const tgt = world.states[measure.targetId];
    if (!imp || !tgt) return;

    // Allies of imposer in world.alliances with relation to target < 50 join with prob 0.35 at level - 1
    const joinLevel = Math.max(1, (measure.level || 1) - 1);
    if (measure.level >= 2) {
      const impAlliances = (world.alliances || []).filter((a) => Array.isArray(a.members) && a.members.includes(imp.id));
      const allyIds = new Set();
      impAlliances.forEach((a) => a.members.forEach((mId) => { if (mId !== imp.id && mId !== tgt.id) allyIds.add(mId); }));
      allyIds.forEach((allyId) => {
        const allySt = world.states[allyId];
        if (!allySt || allySt.isExiled) return;
        const relToTgt = allySt.relations?.[tgt.id]?.score ?? 50;
        const sharedAlliances = impAlliances.filter((a) => a.members.includes(allyId));
        if (relToTgt < 50 && !measure.alliesJoined.includes(allyId) && rng.chance(0.35)) {
          measure.alliesJoined.push(allyId);
          // Link 4: When a member joins an imposer's measure, its alliance cohesion rises +2
          sharedAlliances.forEach((al) => { al.cohesion = clamp((al.cohesion ?? 78) + 2, 10, 100); });
          // Create or escalate ally's measure without infinite recursion
          imposeTradeMeasureV230(world, allyId, tgt.id, joinLevel, measure.reason, { skipCascade: true });
          const allyHead = pickNegotiatorsV230(world, allyId).head;
          const allyHeadName = allyHead ? allyHead.name : shortNameTh(allySt);
          const joinTemplates = [
            `⚔️🤝 [พันธมิตรร่วมวงคว่ำบาตร! ${shortNameTh(allySt)} ผนึกกำลัง ${shortNameTh(imp)} กดดัน ${shortNameTh(tgt)}] ${allyHeadName} ผู้นำแห่ง ${allySt.name} ประกาศเข้าร่วมแนวร่วมสงครามการค้ากับ ${imp.name} โดยบังคับใช้มาตรการระดับที่ ${joinLevel} ต่อ ${tgt.name} ในหมวด (${measure.sectors.slice(0, 2).join(', ')}) เพื่อแสดงความเป็นเอกภาพของกลุ่มพันธมิตร`,
            `⚔️🛡️ [แนวร่วมเศรษฐกิจขยายวง! ${shortNameTh(allySt)} ประกาศมาตรการระดับ ${joinLevel} ต่อ ${shortNameTh(tgt)}] รัฐบาลของ ${allyHeadName} แห่ง ${allySt.name} ตอบรับคำเรียกร้องของ ${shortNameTh(imp)} ด้วยการตั้งกำแพงภาษีและมาตรการกีดกันระดับ ${joinLevel} ต่อ ${tgt.name} เพิ่มแรงกดดันต่อ GDP ของฝ่ายเป้าหมาย`,
            `⚔️🌐 [ศึกการค้าพหุภาคี: ${shortNameTh(allySt)} ร่วมขบวน ${shortNameTh(imp)} เล่นงาน ${shortNameTh(tgt)}] ${allyHeadName} ลงนามคำสั่งให้ ${allySt.name} เข้าร่วมมาตรการคว่ำบาตรระดับ ${joinLevel} ต่อ ${tgt.name} เคียงข้าง ${imp.name} ท่ามกลางความตึงเครียดที่ลุกลามไปทั่วภูมิภาค`,
            `⚔️📦 [ปิดล้อมเป็นลูกโซ่! ${shortNameTh(allySt)} เปิดมาตรการระดับ ${joinLevel} สมทบ ${shortNameTh(imp)}] กระทรวงการค้าของ ${allySt.name} ภายใต้ ${allyHeadName} ประกาศใช้มาตรการระดับ ${joinLevel} ต่อ ${tgt.name} ทำให้เครือข่ายผู้ร่วมคว่ำบาตรขยายเป็น ${measure.alliesJoined.length} ประเทศ`,
            `⚔️⚡ [พันธมิตรขยับตัว! ${allyHeadName} นำ ${shortNameTh(allySt)} ร่วมคว่ำบาตร ${shortNameTh(tgt)}] เพื่อสนับสนุนยุทธศาสตร์ของ ${shortNameTh(imp)} รัฐบาล ${allySt.name} จึงสั่งบังคับใช้มาตรการทางการค้าระดับ ${joinLevel} ต่อ ${tgt.name} ทันที`,
            `⚔️🏛️ [มติพันธมิตรการค้า: ${shortNameTh(allySt)} ผนึก ${shortNameTh(imp)} กดดัน ${shortNameTh(tgt)}] ${allyHeadName} แห่ง ${allySt.name} ยืนยันการเข้าร่วมมาตรการระดับ ${joinLevel} ต่อ ${tgt.name} ส่งผลให้ดัชนีแรงกดดันคว่ำบาตรของ ${shortNameTh(tgt)} พุ่งสูงขึ้น`
          ];
          addChronicle(world, 'TRADE_WAR', rng.pick(joinTemplates), allySt.id, { secondStateId: tgt.id });
        } else if (!measure.alliesJoined.includes(allyId)) {
          // Link 4: When a member refuses to join, alliance cohesion falls -4
          sharedAlliances.forEach((al) => { al.cohesion = clamp((al.cohesion ?? 78) - 4, 10, 100); });
        }
      });
    }

    // Allies of target (relation to target >= 65) issue condemnation story and 30% chance impose counter-measure of level 1 on imposer
    const tgtFriends = Object.values(world.states).filter((s) =>
      s && !s.isExiled && s.id !== imp.id && s.id !== tgt.id && (s.relations?.[tgt.id]?.score ?? 50) >= 65
    );
    if (tgtFriends.length > 0 && rng.chance(0.45)) {
      const friendSt = rng.pick(tgtFriends);
      const friendHead = pickNegotiatorsV230(world, friendSt.id).head;
      const friendHeadName = friendHead ? friendHead.name : shortNameTh(friendSt);
      const counterTriggered = rng.chance(0.30);
      if (counterTriggered) {
        imposeTradeMeasureV230(world, friendSt.id, imp.id, 1, 'RETALIATION', { skipCascade: true });
      }
      const condemnTemplates = [
        `⚔️📢 [${shortNameTh(friendSt)} ออกแถลงการณ์ประณาม ${shortNameTh(imp)} กรณีรังแกทางการค้า ${shortNameTh(tgt)}!] ${friendHeadName} ผู้นำแห่ง ${friendSt.name} ประณามมาตรการคว่ำบาตรระดับ ${measure.level} ของ ${imp.name} ที่กระทำต่อพันธมิตรอย่าง ${tgt.name} ว่าเป็นการบ่อนทำลายเสถียรภาพเศรษฐกิจโลก${counterTriggered ? ` พร้อมสั่งตั้งกำแพงภาษีระดับ 1 ตอบโต้ ${shortNameTh(imp)} ทันที!` : ''}`,
        `⚔️🗣️ [เสียงคัดค้านจากมิตรประเทศ! ${friendHeadName} ปกป้อง ${shortNameTh(tgt)}] กระทรวงการต่างประเทศของ ${friendSt.name} ออกแถลงการณ์ตำหนิ ${imp.name} อย่างรุนแรงที่ใช้มาตรการระดับ ${measure.level} กดดัน ${tgt.name}${counterTriggered ? ` และประกาศมาตรการภาษีระดับ 1 ตอบโต้ ${shortNameTh(imp)} เพื่อปกป้องพันธมิตร` : ''}`,
        `⚔️🌐 [ศึกทูตการค้าปะทุ: ${shortNameTh(friendSt)} ประณามมาตรการของ ${shortNameTh(imp)}] ${friendHeadName} แห่ง ${friendSt.name} เรียกร้องให้ ${imp.name} ยกเลิกการคว่ำบาตรระดับ ${measure.level} ต่อ ${tgt.name} โดยทันที${counterTriggered ? ` ก่อนจะสั่งเก็บภาษีศุลกากร 8% ต่อสินค้าของ ${shortNameTh(imp)} เป็นการตอบโต้` : ''}`,
        `⚔️⚖️ [${shortNameTh(friendSt)} ยืนหยัดเคียงข้าง ${shortNameTh(tgt)} ต้านสงครามการค้า!] ${friendHeadName} แถลงต่อที่ประชุมสากลว่ามาตรการระดับ ${measure.level} ของ ${imp.name} ต่อ ${tgt.name} เป็นสิ่งที่ไม่อาจยอมรับได้${counterTriggered ? ` พร้อมเปิดมาตรการระดับ 1 ตอบโต้ ${shortNameTh(imp)}` : ''}`,
        `⚔️🔥 [พันธมิตร ${shortNameTh(tgt)} เดือด! ${friendHeadName} ประณาม ${shortNameTh(imp)} กลางเวทีโลก] รัฐบาล ${friendSt.name} แสดงจุดยืนปกป้อง ${tgt.name} จากมาตรการระดับ ${measure.level} ของ ${imp.name}${counterTriggered ? ` และสั่งขึ้นภาษีนำเข้าสินค้าจาก ${shortNameTh(imp)} ทันที` : ''}`,
        `⚔️🛡️ [แนวร่วมปกป้อง ${shortNameTh(tgt)}: ${shortNameTh(friendSt)} ตอบโต้ ${shortNameTh(imp)}] ${friendHeadName} แห่ง ${friendSt.name} ออกแถลงการณ์คัดค้านการคว่ำบาตรระดับ ${measure.level} ของ ${imp.name} ต่อ ${tgt.name}${counterTriggered ? ` ควบคู่กับการบังคับใช้มาตรการการค้าระดับ 1 ต่อ ${shortNameTh(imp)}` : ''}`
      ];
      addChronicle(world, 'TRADE_WAR', rng.pick(condemnTemplates), friendSt.id, { secondStateId: imp.id });
    }
  }

  function imposeTradeMeasureV230(world, imposerId, targetId, level = 1, reason = 'RIVALRY', opts = {}) {
    ensureWorldSystemsV230(world);
    opts = opts || {};
    const imp = resolveStateObjV230(world, imposerId);
    const tgt = resolveStateObjV230(world, targetId);
    if (!imp || !tgt || imp.id === tgt.id) {
      return { ok: false, reason: 'ต้องระบุรัฐผู้ประกาศและรัฐเป้าหมายที่ถูกต้องและไม่ซ้ำกัน' };
    }
    const clampedLevel = clamp(Math.round(Number(level) || 1), 1, 5);
    const validReasons = ['WAR_AGGRESSION', 'NUCLEAR', 'RIVALRY', 'RETALIATION', 'SECONDARY'];
    const normReason = validReasons.includes(reason) ? reason : 'RIVALRY';
    const rng = new SeededRNG((world.seed || 2026) + (world.tick || 1) * 313 + hashStr(imp.id + tgt.id + clampedLevel));

    // Check existing active measure for (imposer, target) pair
    let existing = (world.tradeWarV230.measures || []).find((m) =>
      m.status === 'ACTIVE' && m.imposerId === imp.id && m.targetId === tgt.id
    );

    const negImp = pickNegotiatorsV230(world, imp.id);
    const headImpName = negImp.head ? negImp.head.name : `ผู้นำ ${shortNameTh(imp)}`;

    if (existing) {
      const oldLevel = existing.level;
      existing.level = clamp(Math.max(existing.level, clampedLevel), 1, 5);
      if (clampedLevel <= oldLevel && opts.escalateIfSame) {
        existing.level = clamp(oldLevel + 1, 1, 5);
      }
      if (existing.level >= 4) {
        existing.sectors = TRADE_SECTORS_V230.slice();
      } else if (existing.sectors.length < 3) {
        const extraSec = rng.pick(TRADE_SECTORS_V230.filter((s) => !existing.sectors.includes(s)));
        if (extraSec) existing.sectors.push(extraSec);
      }
      existing.lastReviewTick = world.tick;
      if (!existing.history) existing.history = [];
      if (!tgt._preSanctionRatingV230 && tgt.sovereignDebt) {
        tgt._preSanctionRatingV230 = tgt.sovereignDebt.creditRating || 'A';
      }
      // Link 2: Level 4-5 measures call existing currency-war ops
      if (existing.level >= 4 && !existing._fxFrozenCalled && typeof executeCurrencyWarfareOpV210 === 'function') {
        existing._fxFrozenCalled = true;
        const cw4 = executeCurrencyWarfareOpV210(world, imp.id, tgt.id, 'freeze_fx_reserves');
        existing.history.push({ tick: world.tick, op: 'freeze_fx_reserves', ok: !!(cw4 && cw4.ok), reason: (cw4 && (cw4.reason || cw4.narrative)) || 'freeze_fx_reserves executed' });
      }
      if (existing.level >= 5 && !existing._dumpBondsCalled && typeof executeCurrencyWarfareOpV210 === 'function') {
        existing._dumpBondsCalled = true;
        const cw5 = executeCurrencyWarfareOpV210(world, imp.id, tgt.id, 'dump_bonds');
        existing.history.push({ tick: world.tick, op: 'dump_bonds', ok: !!(cw5 && cw5.ok), reason: (cw5 && (cw5.reason || cw5.narrative)) || 'dump_bonds executed' });
      }
      syncSanctionedByArraysV230(world, tgt);

      if (existing.level > oldLevel) {
        const escTemplates = [
          `⚔️📈 [ยกระดับสงครามการค้าสู่ระดับ ${existing.level}/5! ${shortNameTh(imp)} ขันน็อต ${shortNameTh(tgt)}] ${headImpName} ผู้นำแห่ง ${imp.name} สั่งยกระดับมาตรการคว่ำบาตรต่อ ${tgt.name} จากระดับ ${oldLevel} ขึ้นเป็นระดับ ${existing.level} (${TRADE_LADDER_V230[existing.level].labelTh}) ครอบคลุมสาขา (${existing.sectors.slice(0, 3).join(', ')}) เพื่อเพิ่มแรงกดดันทางเศรษฐกิจขั้นสูงสุด!`,
          `⚔️🔥 [บันไดคว่ำบาตรไต่ระดับ ${oldLevel} ➔ ${existing.level}! ${shortNameTh(imp)} บีบ ${shortNameTh(tgt)} หนักขึ้น] รัฐบาลของ ${headImpName} แห่ง ${imp.name} ประกาศขยายขอบเขตมาตรการทางเศรษฐกิจต่อ ${tgt.name} สู่ระดับ ${existing.level} ส่งผลให้ต้นทุนการค้าและอัตราเงินเฟ้อของ ${shortNameTh(tgt)} พุ่งสูงขึ้น`,
          `⚔️🚨 [ศึกเศรษฐกิจทวีความรุนแรง: ${shortNameTh(imp)} อัปเกรดมาตรการเป็นระดับ ${existing.level}] ${headImpName} แห่ง ${imp.name} อนุมัติการยกระดับมาตรการต่อ ${tgt.name} สู่ขั้นที่ ${existing.level} (${TRADE_LADDER_V230[existing.level].labelTh}) ในกลุ่ม (${existing.sectors.slice(0, 3).join(', ')})`,
          `⚔️⚡ [ไม่มีถอย! ${headImpName} สั่งเพิ่มดีกรีคว่ำบาตร ${shortNameTh(tgt)} เป็นระดับ ${existing.level}] กระทรวงพาณิชย์และการคลังของ ${imp.name} บังคับใช้มาตรการระดับ ${existing.level} ต่อ ${tgt.name} หลังความขัดแย้ง (${existing.reason}) ยังไร้ทางออก`,
          `⚔️📊 [กดดันหนักหน่วง! มาตรการ ${shortNameTh(imp)} ต่อ ${shortNameTh(tgt)} พุ่งสู่ระดับ ${existing.level}] การตัดสินใจของ ${headImpName} แห่ง ${imp.name} ในการขยับมาตรการจากระดับ ${oldLevel} เป็น ${existing.level} สร้างแรงสั่นสะเทือนต่อ GDP และค่าเงินของ ${tgt.name}`,
          `⚔️🛑 [ยกระดับการปิดล้อมทางการค้าระดับ ${existing.level}: ${shortNameTh(imp)} vs ${shortNameTh(tgt)}] ${headImpName} แถลงยกระดับมาตรการคว่ำบาตรต่อ ${tgt.name} สู่ระดับ ${existing.level} (${TRADE_LADDER_V230[existing.level].labelTh}) ท่ามกลางการเฝ้าระวังของตลาดโลก`
        ];
        addChronicle(world, 'TRADE_WAR', rng.pick(escTemplates), imp.id, { secondStateId: tgt.id, measureId: existing.id });
        if (!opts.skipCascade) triggerAlliesAndCondemnationOnMeasureV230(world, existing, true, rng);
      }
      return { ok: true, reason: `ยกระดับมาตรการสู่ระดับ ${existing.level} เรียบร้อยแล้ว`, measure: existing, escalated: existing.level > oldLevel };
    }

    if (world.tradeWarV230.measures.length >= 120) {
      // Drop oldest active measure to history if cap 120 reached
      const oldest = world.tradeWarV230.measures.pop();
      if (oldest) {
        oldest.status = 'LIFTED';
        world.tradeWarV230.history.unshift(oldest);
        if (world.tradeWarV230.history.length > 200) world.tradeWarV230.history.length = 200;
      }
    }

    const pickedSectors = clampedLevel >= 4
      ? TRADE_SECTORS_V230.slice()
      : [rng.pick(TRADE_SECTORS_V230), rng.pick(TRADE_SECTORS_V230)].filter((v, i, a) => a.indexOf(v) === i);

    if (!tgt._preSanctionRatingV230 && tgt.sovereignDebt) {
      tgt._preSanctionRatingV230 = tgt.sovereignDebt.creditRating || 'A';
    }
    const newMeasure = {
      id: `TW_${world.tradeWarV230.nextId++}`,
      imposerId: imp.id,
      targetId: tgt.id,
      level: clampedLevel,
      sectors: pickedSectors,
      startTick: world.tick,
      reason: normReason,
      alliesJoined: [],
      evasionHubs: [],
      cumulativeDamagePct: 0,
      cumulativeCostPct: 0,
      status: 'ACTIVE',
      lastReviewTick: world.tick,
      retaliated: false,
      history: []
    };

    world.tradeWarV230.measures.unshift(newMeasure);
    syncSanctionedByArraysV230(world, tgt);

    // Link 2: Level 4-5 measures call existing currency-war ops once at creation
    if (clampedLevel >= 4 && typeof executeCurrencyWarfareOpV210 === 'function') {
      newMeasure._fxFrozenCalled = true;
      const cw4 = executeCurrencyWarfareOpV210(world, imp.id, tgt.id, 'freeze_fx_reserves');
      newMeasure.history.push({ tick: world.tick, op: 'freeze_fx_reserves', ok: !!(cw4 && cw4.ok), reason: (cw4 && (cw4.reason || cw4.narrative)) || 'freeze_fx_reserves executed' });
    }
    if (clampedLevel >= 5 && typeof executeCurrencyWarfareOpV210 === 'function') {
      newMeasure._dumpBondsCalled = true;
      const cw5 = executeCurrencyWarfareOpV210(world, imp.id, tgt.id, 'dump_bonds');
      newMeasure.history.push({ tick: world.tick, op: 'dump_bonds', ok: !!(cw5 && cw5.ok), reason: (cw5 && (cw5.reason || cw5.narrative)) || 'dump_bonds executed' });
    }

    const secTxt = pickedSectors.slice(0, 3).join(', ');
    const templates = getImposedTemplatesByLevelV230(clampedLevel, imp, tgt, headImpName, secTxt, normReason);
    addChronicle(world, 'TRADE_WAR', rng.pick(templates), imp.id, { secondStateId: tgt.id, measureId: newMeasure.id });

    if (!opts.skipCascade) {
      triggerAlliesAndCondemnationOnMeasureV230(world, newMeasure, false, rng);
    }

    return { ok: true, reason: `ประกาศมาตรการสงครามการค้าระดับ ${clampedLevel} สำเร็จ`, measure: newMeasure };
  }

  function liftMeasuresBetweenV230(world, aId, bId, mode = 'LIFT') {
    ensureWorldSystemsV230(world);
    const stA = resolveStateObjV230(world, aId);
    const stB = resolveStateObjV230(world, bId);
    if (!stA || !stB) return { ok: false, reason: 'ไม่พบรัฐที่ระบุ' };

    const rng = new SeededRNG((world.seed || 2026) + (world.tick || 1) * 431 + hashStr(stA.id + stB.id));
    const matching = (world.tradeWarV230.measures || []).filter((m) =>
      m.status === 'ACTIVE' && ((m.imposerId === stA.id && m.targetId === stB.id) || (m.imposerId === stB.id && m.targetId === stA.id))
    );
    if (matching.length === 0) return { ok: false, reason: 'ไม่มีมาตรการสงครามการค้าที่มีผลบังคับใช้อยู่ระหว่างสองรัฐนี้' };

    matching.forEach((m) => {
      const imp = world.states[m.imposerId] || stA;
      const tgt = world.states[m.targetId] || stB;
      const headImp = pickNegotiatorsV230(world, imp.id).head;
      const headImpName = headImp ? headImp.name : shortNameTh(imp);

      if (mode === 'RELAX' && m.level > 1) {
        m.level -= 1;
        m.status = 'ACTIVE';
        m.lastReviewTick = world.tick;
        const relaxTemplates = [
          `⚔️🕊️ [ผ่อนปรนมาตรการการค้า! ${shortNameTh(imp)} ลดระดับคว่ำบาตร ${shortNameTh(tgt)} เหลือระดับ ${m.level}] ${headImpName} ผู้นำแห่ง ${imp.name} อนุมัติการลดระดับมาตรการกีดกันทางการค้าต่อ ${tgt.name} ลง 1 ขั้น สู่ระดับ ${m.level} (${TRADE_LADDER_V230[m.level].labelTh}) เพื่อลดภาระต้นทุนและเปิดทางฟื้นฟูการค้า`,
          `⚔️📉 [สัญญาณบวกทางเศรษฐกิจ: ${shortNameTh(imp)} ผ่อนคลายกำแพงภาษีต่อ ${shortNameTh(tgt)} สู่ระดับ ${m.level}] กระทรวงพาณิชย์ของ ${imp.name} ภายใต้การนำของ ${headImpName} ปรับลดความเข้มงวดของมาตรการต่อ ${tgt.name} ลงเหลือระดับ ${m.level} ช่วยบรรเทาแรงกดดันเงินเฟ้อของทั้งสองฝ่าย`,
          `⚔️🤝 [ลดอุณหภูมิสงครามการค้า ${shortNameTh(imp)}–${shortNameTh(tgt)} เหลือระดับ ${m.level}] ${headImpName} แห่ง ${imp.name} สั่งผ่อนปรนมาตรการต่อ ${tgt.name} ลงสู่ระดับ ${m.level} ในกลุ่ม (${m.sectors.slice(0, 2).join(', ')}) สร้างความเชื่อมั่นให้แก่ภาคธุรกิจ`,
          `⚔️🔓 [${shortNameTh(imp)} ถอยคนละก้าว! ลดมาตรการคว่ำบาตร ${shortNameTh(tgt)} ลงสู่ระดับ ${m.level}] รัฐบาลของ ${headImpName} ปรับลดระดับมาตรการทางเศรษฐกิจต่อ ${tgt.name} เหลือระดับ ${m.level} หลังต้นทุนการค้าสะสมเริ่มส่งผลกระทบต่อทั้งสองฝ่าย`,
          `⚔️📊 [ตลาดหุ้นขานรับ! ${shortNameTh(imp)} ผ่อนปรนมาตรการต่อ ${shortNameTh(tgt)} เหลือระดับ ${m.level}] คำสั่งของ ${headImpName} แห่ง ${imp.name} ในการลดระดับคว่ำบาตรต่อ ${tgt.name} สู่ระดับ ${m.level} ช่วยฟื้นฟูห่วงโซ่อุปทานในภูมิภาค`,
          `⚔️⚖️ [ปรับสมดุลการค้า: ${shortNameTh(imp)} ลดระดับมาตรการต่อ ${shortNameTh(tgt)} เป็นระดับ ${m.level}] ${headImpName} ยืนยันการผ่อนปรนมาตรการทางการค้าต่อ ${tgt.name} ลง 1 ระดับ สู่ระดับ ${m.level} เพื่อรักษาเสถียรภาพเศรษฐกิจมหภาค`
        ];
        addChronicle(world, 'TRADE_WAR', rng.pick(relaxTemplates), imp.id, { secondStateId: tgt.id, measureId: m.id });
      } else {
        m.level = 0;
        m.status = 'LIFTED';
        world.tradeWarV230.measures = world.tradeWarV230.measures.filter((x) => x.id !== m.id);
        world.tradeWarV230.history.unshift(m);
        if (world.tradeWarV230.history.length > 200) world.tradeWarV230.history.length = 200;

        // Link 2: Release frozen FX reserves (centralBank.fxFrozenBy) when measure is LIFTED
        if (tgt.centralBank && Array.isArray(tgt.centralBank.fxFrozenBy) && tgt.centralBank.fxFrozenBy.includes(imp.id)) {
          tgt.centralBank.fxFrozenBy = tgt.centralBank.fxFrozenBy.filter((id) => id !== imp.id);
          tgt.centralBank.fxReservesB = rnd1((tgt.centralBank.fxReservesB || 20) + 15);
          tgt.centralBank.currencyStability = clamp((tgt.centralBank.currencyStability || 60) + 6, 10, 99);
          addChronicle(
            world,
            'TRADE_WAR',
            `⚔️🏦 [ปลดอายัดทุนสำรองระหว่างประเทศ! ${shortNameTh(imp)} คืนสภาพคล่อง FX ให้แก่ ${shortNameTh(tgt)}] ภายหลังการยกเลิกมาตรการคว่ำบาตร ธนาคารกลางของ ${imp.name} ได้ปลดล็อกบัญชีทุนสำรองเงินตราต่างประเทศ (fxFrozenBy) ของ ${tgt.name} ส่งผลให้ทุนสำรอง FX ของ ${shortNameTh(tgt)} ฟื้นตัวสู่ $${tgt.centralBank.fxReservesB}B และเสถียรภาพค่าเงินปรับขึ้นเป็น ${tgt.centralBank.currencyStability}/100`,
            imp.id,
            { secondStateId: tgt.id, measureId: m.id }
          );
        }

        const liftTemplates = [
          `⚔️✅ [ยกเลิกมาตรการคว่ำบาตรทั้งหมด! ${shortNameTh(imp)} เปิดด่านการค้ากับ ${shortNameTh(tgt)} ตามปกติ] ${headImpName} ผู้นำแห่ง ${imp.name} ลงนามยกเลิกมาตรการสงครามการค้าและคว่ำบาตรต่อ ${tgt.name} อย่างเป็นทางการ (สถานะ LIFTED) หลังสร้างความเสียหายสะสม ${m.cumulativeDamagePct.toFixed(2)}% ต่อ GDP เปิดทางให้การค้าและการลงทุนกลับมาคึกคักอีกครั้ง`,
          `⚔️🕊️ [สิ้นสุดสงครามการค้า ${shortNameTh(imp)}–${shortNameTh(tgt)}!] รัฐบาลของ ${headImpName} แห่ง ${imp.name} ประกาศยุติมาตรการกีดกันทางการค้าในหมวด (${m.sectors.slice(0, 3).join(', ')}) ต่อ ${tgt.name} ทั้งหมด พร้อมถอนรายชื่อออกจากบัญชีคว่ำบาตร`,
          `⚔️🔓 [ปลดล็อกคว่ำบาตรเศรษฐกิจ! ${shortNameTh(imp)} ฟื้นฟูการค้าเสรีกับ ${shortNameTh(tgt)}] ${headImpName} แถลงยกเลิกคำสั่งคว่ำบาตรต่อ ${tgt.name} ส่งผลให้เรือสินค้าและธุรกรรมธนาคารระหว่างสองรัฐกลับมาดำเนินการได้ตามปกติ`,
          `⚔️🤝 [ปิดฉากศึกกำแพงภาษี: ${shortNameTh(imp)} ยกเลิกมาตรการต่อ ${shortNameTh(tgt)}] กระทรวงพาณิชย์ของ ${imp.name} ภายใต้คำสั่ง ${headImpName} ยุติมาตรการคว่ำบาตรต่อ ${tgt.name} อย่างสมบูรณ์ ช่วยลดแรงกดดันเงินเฟ้อและฟื้นฟูค่าเงิน`,
          `⚔️🌟 [ฟ้าหลังฝนทางการค้า: ${shortNameTh(imp)} ยกเลิกคว่ำบาตร ${shortNameTh(tgt)}] การตัดสินใจของ ${headImpName} แห่ง ${imp.name} ในการยกเลิกมาตรการต่อ ${tgt.name} ได้รับเสียงชื่นชมจากหอการค้าและตลาดการเงินโลก`,
          `⚔️📦 [เปิดเสรีห่วงโซ่อุปทาน ${shortNameTh(imp)}–${shortNameTh(tgt)} อีกครั้ง!] มาตรการสงครามการค้าระหว่าง ${imp.name} และ ${tgt.name} สิ้นสุดลงในสถานะ LIFTED โดยคำสั่งของ ${headImpName}`
        ];
        addChronicle(world, 'TRADE_WAR', rng.pick(liftTemplates), imp.id, { secondStateId: tgt.id, measureId: m.id });
      }

      // Clean up sanctionedBy if no active level >= 3 measure remains from imp to tgt
      const stillHeavy = (world.tradeWarV230.measures || []).some((x) =>
        x.status === 'ACTIVE' && x.imposerId === imp.id && x.targetId === tgt.id && x.level >= 3
      );
      if (!stillHeavy) {
        if (Array.isArray(tgt.sanctionedBy)) {
          tgt.sanctionedBy = tgt.sanctionedBy.filter((id) => id !== imp.id);
        }
        if (tgt.nuclear && Array.isArray(tgt.nuclear.sanctionedBy)) {
          tgt.nuclear.sanctionedBy = tgt.nuclear.sanctionedBy.filter((id) => id !== imp.id);
        }
      }
    });

    return { ok: true, reason: mode === 'RELAX' ? 'ผ่อนปรนมาตรการลง 1 ระดับแล้ว' : 'ยกเลิกมาตรการคว่ำบาตรทั้งหมดแล้ว' };
  }

  // Daily-light check (t % 5 === 1): only touches active measures
  function runTradeWarLightCycleV230(world, rng) {
    if (!world.tradeWarV230 || !Array.isArray(world.tradeWarV230.measures)) return;
    const measures = world.tradeWarV230.measures;
    for (let i = 0; i < measures.length; i++) {
      const m = measures[i];
      if (!m || m.status !== 'ACTIVE') continue;
      const tgt = world.states[m.targetId];
      if (tgt && m.level >= 3 && !tgt.sanctionedBy.includes(m.imposerId)) {
        tgt.sanctionedBy.push(m.imposerId);
      }
    }
  }

  // Monthly cycle (t % 30 === 11): economics, retaliation, escalation/de-escalation, evasion hubs, rivalry triggers, pulse
  function runTradeWarMonthlyCycleV230(world, rng) {
    ensureWorldSystemsV230(world);
    const activeMeasures = (world.tradeWarV230.measures || []).slice();
    const cbReactedThisMonth = new Set();

    for (let i = 0; i < activeMeasures.length; i++) {
      const m = activeMeasures[i];
      if (!m || m.status !== 'ACTIVE') continue;
      const imp = world.states[m.imposerId];
      const tgt = world.states[m.targetId];
      if (!imp || !tgt || imp.isExiled || tgt.isExiled) continue;

      const lvl = clamp(m.level || 1, 1, 5);
      const baseDmg = LEVEL_DAMAGE_V230[lvl] || 0.04;
      const expTgtToImp = getTradeExposureV230(world, tgt, imp);
      const expImpToTgt = getTradeExposureV230(world, imp, tgt);
      const hubDiscount = Math.max(0.25, 1 - 0.15 * ((m.evasionHubs || []).length));

      let monthlyDmgPct = baseDmg * expTgtToImp * hubDiscount;
      let monthlyCostPct = 0.30 * baseDmg * expImpToTgt * hubDiscount;

      // Hard cap: cumulative damage from one measure <= 12% of GDP
      if ((m.cumulativeDamagePct || 0) < 12) {
        const allowedDmgPct = Math.min(monthlyDmgPct, 12 - (m.cumulativeDamagePct || 0));
        if (allowedDmgPct > 0) {
          m.cumulativeDamagePct = +((m.cumulativeDamagePct || 0) + allowedDmgPct).toFixed(4);
          const gdpDrop = Math.max(0.1, tgt.gdpB * (allowedDmgPct / 100));
          tgt.gdpB = +(Math.max(5, tgt.gdpB - gdpDrop)).toFixed(2);
        }
      }
      m.cumulativeCostPct = +((m.cumulativeCostPct || 0) + monthlyCostPct).toFixed(4);
      const impCostDrop = imp.gdpB * (monthlyCostPct / 100);
      imp.gdpB = +(Math.max(5, imp.gdpB - impCostDrop)).toFixed(2);

      // Central bank, sovereign debt & stability impacts on target (Link 1)
      if (!tgt._preSanctionRatingV230 && tgt.sovereignDebt) {
        tgt._preSanctionRatingV230 = tgt.sovereignDebt.creditRating || 'A';
      }
      if (tgt.centralBank) {
        const addedSoFar = tgt._tradeWarInfAddedV230 || 0;
        if (addedSoFar < 6) {
          const infAdd = Math.min(lvl * 0.12, 6 - addedSoFar);
          tgt.centralBank.inflationPct = +(clamp((tgt.centralBank.inflationPct || 2.5) + infAdd, 0.2, 120)).toFixed(2);
          tgt._tradeWarInfAddedV230 = +(addedSoFar + infAdd).toFixed(2);
        }
        tgt.centralBank.currencyStability = clamp(rnd1((tgt.centralBank.currencyStability ?? 75) - lvl * 0.8), 10, 99);
        tgt.centralBank.exchangeRateIndex = +(Math.max(15, (tgt.centralBank.exchangeRateIndex || 100) * (1 - lvl * 0.005))).toFixed(2);
      }
      if (tgt.sovereignDebt) {
        const yieldAddedSoFar = tgt._tradeWarBondYieldAddedV230 || 0;
        if (yieldAddedSoFar < 3.0) {
          const yieldAdd = Math.min(lvl * 0.06, 3.0 - yieldAddedSoFar);
          tgt.sovereignDebt.bondYieldPct = +(clamp((tgt.sovereignDebt.bondYieldPct || 3.5) + yieldAdd, 1.0, 48.0)).toFixed(2);
          tgt._tradeWarBondYieldAddedV230 = +(yieldAddedSoFar + yieldAdd).toFixed(2);
        }
        tgt.sovereignDebt.debtToGdpPct = +(((tgt.sovereignDebt.totalDebtB || 100) / Math.max(50, tgt.gdpB)) * 100).toFixed(1);
        const prevRating = tgt._initialRatingBeforeTwV230 || tgt._preSanctionRatingV230 || 'A';
        if (!tgt._initialRatingBeforeTwV230) tgt._initialRatingBeforeTwV230 = prevRating;
        const newRating = recomputeCreditRatingV210(tgt);
        const notchesDropped = CREDIT_RATINGS_ORDER_V230.indexOf(newRating) - CREDIT_RATINGS_ORDER_V230.indexOf(prevRating);
        if (tgt.sovereignDebt.debtToGdpPct > 100 && notchesDropped >= 2 && !m._downgradeLogged) {
          m._downgradeLogged = true;
          addChronicle(
            world,
            'TRADE_WAR',
            `⚔️📉 [หั่นอันดับเครดิตประเทศ! ${shortNameTh(tgt)} ถูกลดเครดิตสู่ระดับ ${newRating} จากพิษสงครามการค้าและหนี้ทะลุ ${tgt.sovereignDebt.debtToGdpPct}%] สถาบันจัดอันดับความน่าเชื่อถือระหว่างประเทศประกาศลดอันดับเครดิตของ ${tgt.name} ลงสู่ระดับ ${newRating} (จากเดิม ${prevRating}) หลังมาตรการคว่ำบาตรของ ${shortNameTh(imp)} กดดันให้ Bond Yield พุ่งแตะ ${tgt.sovereignDebt.bondYieldPct}% และหนี้สาธารณะต่อ GDP ทะลุ ${tgt.sovereignDebt.debtToGdpPct}%`,
            tgt.id,
            { secondStateId: imp.id, measureId: m.id }
          );
        }
      }
      // Link 1: Target's central bank reacts through existing policy API (setCentralBankPolicyV210) (at most once per state per month)
      if (tgt.centralBank && !cbReactedThisMonth.has(tgt.id) && typeof setCentralBankPolicyV210 === 'function') {
        cbReactedThisMonth.add(tgt.id);
        if (tgt.centralBank.inflationPct > (tgt.centralBank.interestRatePct || 0) + 2 && rng.chance(0.40)) {
          setCentralBankPolicyV210(world, tgt.id, 'hike_rate', 0.25);
        }
        if (tgt.centralBank.currencyStability < 55 && (tgt.centralBank.fxReservesB || 0) > 30 && rng.chance(0.30)) {
          setCentralBankPolicyV210(world, tgt.id, 'defend_currency');
        }
      }
      // Link 3: Imposer pain through existing finance model (cumulativeCostPct > 3 -> inflationPct += 0.05/month)
      if (imp.sovereignDebt) {
        const impFiscalCostB = +(Math.max(0.05, imp.gdpB * (monthlyCostPct / 100) * 0.2)).toFixed(2);
        imp.treasuryB = rnd1(Math.max(0, (imp.treasuryB || 50) - impFiscalCostB));
        imp.sovereignDebt.totalDebtB = rnd1((imp.sovereignDebt.totalDebtB || 100) + impFiscalCostB);
        imp.sovereignDebt.debtToGdpPct = +((imp.sovereignDebt.totalDebtB / Math.max(50, imp.gdpB)) * 100).toFixed(1);
      }
      if ((m.cumulativeCostPct || 0) > 3 && imp.centralBank) {
        imp.centralBank.inflationPct = +(clamp((imp.centralBank.inflationPct || 2.5) + 0.05, 0.2, 120)).toFixed(2);
      }
      tgt.stability = clamp(rnd1((tgt.stability ?? 70) - lvl * 0.15), 5, 99);

      // Imposer approval rally or cost
      const headImp = pickNegotiatorsV230(world, imp.id).head;
      const headTgt = pickNegotiatorsV230(world, tgt.id).head;
      const impAgg = headImp?.personality?.aggression ?? 50;
      if (impAgg > 65) {
        imp.approval = clamp(rnd1((imp.approval || 70) + 0.1), 5, 99);
      } else {
        imp.approval = clamp(rnd1((imp.approval || 70) - 0.05 * lvl), 5, 99);
      }

      // Retaliation (once per measure)
      if (!m.retaliated) {
        const tgtAgg = headTgt?.personality?.aggression ?? 50;
        const retProb = clamp(0.15 + tgtAgg / 200 + (lvl >= 3 ? 0.15 : 0), 0, 0.70);
        if (rng.chance(retProb)) {
          m.retaliated = true;
          const retLevel = Math.max(1, lvl - 1);
          const headTgtName = headTgt ? headTgt.name : shortNameTh(tgt);
          imposeTradeMeasureV230(world, tgt.id, imp.id, retLevel, 'RETALIATION', { skipCascade: true });
          const retTemplates = [
            `⚔️🔄 [ตาต่อตาฟันต่อฟัน! ${shortNameTh(tgt)} ประกาศมาตรการระดับ ${retLevel} ตอบโต้ ${shortNameTh(imp)}] ${headTgtName} ผู้นำแห่ง ${tgt.name} แถลงตอบโต้มาตรการคว่ำบาตรของ ${imp.name} ด้วยการสั่งบังคับใช้มาตรการระดับที่ ${retLevel} (${TRADE_LADDER_V230[retLevel].labelTh}) ต่อสินค้าและผลประโยชน์ของ ${shortNameTh(imp)} ทันที!`,
            `⚔️💥 [เปิดศึกภาษีสวนกลับ! ${headTgtName} สั่งเช็กบิล ${shortNameTh(imp)} ที่ระดับ ${retLevel}] รัฐบาลแห่ง ${tgt.name} ไม่ยอมจำนนต่อแรงกดดัน โดยประกาศมาตรการตอบโต้ (RETALIATION) ระดับ ${retLevel} ในสาขา (${m.sectors.slice(0, 2).join(', ')}) ต่อ ${imp.name} ท่ามกลางเสียงหนุนจากกลุ่มชาตินิยมในประเทศ`,
            `⚔️🚨 [สงครามการค้าลุกเป็นไฟ: ${shortNameTh(tgt)} สวนหมัด ${shortNameTh(imp)} ด้วยมาตรการระดับ ${retLevel}] ${headTgtName} ลงนามคำสั่งตอบโต้ทางเศรษฐกิจต่อ ${imp.name} ที่ระดับ ${retLevel} ส่งผลให้การค้าสองฝ่ายเข้าสู่ภาวะชะงักงัน`,
            `⚔️⚖️ [มาตรการต่างตอบแทน! ${shortNameTh(tgt)} ตั้งกำแพงสกัด ${shortNameTh(imp)} ระดับ ${retLevel}] กระทรวงพาณิชย์ของ ${tgt.name} ภายใต้คำสั่งของ ${headTgtName} บังคับใช้มาตรการระดับ ${retLevel} เพื่อเอาคืน ${imp.name} อย่างสาสม`,
            `⚔️🔥 [ไม่มีคำว่ายอมแพ้! ${headTgtName} นำ ${shortNameTh(tgt)} ตอบโต้ ${shortNameTh(imp)} ระดับ ${retLevel}] เพื่อปกป้องศักดิ์ศรีและอุตสาหกรรมของชาติ ${tgt.name} จึงประกาศมาตรการ RETALIATION ระดับ ${retLevel} ต่อ ${imp.name}`,
            `⚔️🛡️ [โต้กลับทันควัน! ${shortNameTh(tgt)} งัดมาตรการระดับ ${retLevel} เล่นงาน ${shortNameTh(imp)}] ${headTgtName} แห่ง ${tgt.name} แถลงใช้มาตรการทางเศรษฐกิจระดับ ${retLevel} ตอบโต้ ${imp.name} สร้างแรงกระเพื่อมไปทั่วตลาดการเงิน`
          ];
          addChronicle(world, 'TRADE_WAR', rng.pick(retTemplates), tgt.id, { secondStateId: imp.id, measureId: m.id });
        }
      }

      // Evasion hubs: 25% chance neutral state with exposure >= 0.2 to both becomes transshipment hub (max 3)
      if (!m.evasionHubs) m.evasionHubs = [];
      if (m.evasionHubs.length < 3 && rng.chance(0.25)) {
        const candidates = Object.values(world.states).filter((s) =>
          s && !s.isExiled && s.id !== imp.id && s.id !== tgt.id &&
          !m.alliesJoined.includes(s.id) && !m.evasionHubs.includes(s.id) &&
          (getTradeExposureV230(world, s, imp) >= 0.12 || getTradeExposureV230(world, s, tgt) >= 0.12)
        );
        const hubSt = rng.pick(candidates);
        if (hubSt) {
          m.evasionHubs.push(hubSt.id);
          // Link 4: When a member trades with the target (evasion hub), its alliance cohesion falls -4
          (world.alliances || []).forEach((al) => {
            if (al && Array.isArray(al.members) && al.members.includes(hubSt.id)) {
              al.cohesion = clamp((al.cohesion ?? 78) - 4, 10, 100);
              if (al.memberStatesData && al.memberStatesData[hubSt.id]) {
                al.memberStatesData[hubSt.id].leaderSupportScore = clamp((al.memberStatesData[hubSt.id].leaderSupportScore || 50) - 8, 5, 98);
              }
            }
          });
        }
      }

      // 10% chance imposer discovers evasion hub -> creates level-1 SECONDARY measure against hub and chronicle story
      if (m.evasionHubs.length > 0 && rng.chance(0.10)) {
        const discoveredHubId = rng.pick(m.evasionHubs);
        const hubSt = world.states[discoveredHubId];
        if (hubSt) {
          m.evasionHubs = m.evasionHubs.filter((id) => id !== discoveredHubId);
          imposeTradeMeasureV230(world, imp.id, hubSt.id, 1, 'SECONDARY', { skipCascade: true });
          const headImpName = headImp ? headImp.name : shortNameTh(imp);
          const hubCity = stateCities(world, hubSt.id)[0];
          const hubCityName = hubCity ? cityNameTh(hubCity) : shortNameTh(hubSt);
          const hubTemplates = [
            `⚔️🕵️ [เปิดโปงเมืองท่าหลบเลี่ยงคว่ำบาตร! ${shortNameTh(imp)} สั่งลงโทษทุติยภูมิ (Secondary Sanctions) ต่อ ${shortNameTh(hubSt)}] หน่วยข่าวกรองการคลังของ ${imp.name} ตรวจพบว่าบริษัทในเมือง${hubCityName} ของ ${hubSt.name} ลักลอบเป็นศูนย์กลางถ่ายลำสินค้า (${m.sectors.slice(0, 2).join(', ')}) ให้แก่ ${tgt.name} ส่งผลให้ ${headImpName} สั่งประกาศมาตรการคว่ำบาตรระดับ 1 (SECONDARY) ต่อ ${shortNameTh(hubSt)} ทันที!`,
            `⚔️🚢 [ทลายเครือข่ายลักลอบส่งออกที่ ${hubCityName}! ${shortNameTh(imp)} เล่นงาน ${shortNameTh(hubSt)}] รัฐบาลของ ${headImpName} แห่ง ${imp.name} แถลงหลักฐานการสวมสิทธิ์แหล่งกำเนิดสินค้าในเมือง${hubCityName} (${hubSt.name}) เพื่อช่วย ${shortNameTh(tgt)} หลบเลี่ยงการคว่ำบาตร พร้อมสั่งตั้งกำแพงภาษีทุติยภูมิระดับ 1 ต่อ ${shortNameTh(hubSt)}`,
            `⚔️🚨 [คว่ำบาตรลูกหลง! ${shortNameTh(hubSt)} ถูก ${shortNameTh(imp)} ลงโทษฐานเป็นศูนย์กลางถ่ายลำให้ ${shortNameTh(tgt)}] ${headImpName} แห่ง ${imp.name} ลงนามคำสั่ง SECONDARY SANCTIONS ระดับ 1 ต่อ ${hubSt.name} หลังพบเรือบรรทุกสินค้าใช้ท่าเรือเมือง${hubCityName} ลักลอบส่งสินค้ายุทธศาสตร์ให้ ${shortNameTh(tgt)}`,
            `⚔️🔍 [ปิดช่องโหว่สงครามการค้า: ${shortNameTh(imp)} ขึ้นบัญชีดำเมืองท่า ${hubCityName} ของ ${shortNameTh(hubSt)}] กระทรวงการคลังของ ${imp.name} ภายใต้ ${headImpName} สั่งตัดช่องทางหลบเลี่ยงคว่ำบาตรของ ${tgt.name} ที่ผ่านทาง ${hubSt.name} และบังคับใช้มาตรการระดับ 1 ต่อ ${shortNameTh(hubSt)}`,
            `⚔️⚡ [มาตรการทุติยภูมิทำงาน! ${shortNameTh(imp)} เช็กบิล ${shortNameTh(hubSt)} ฐานช่วย ${shortNameTh(tgt)} เลี่ยงภาษี] ${headImpName} แถลงว่า ${imp.name} จะไม่ยอมให้รัฐใดทำตัวเป็นท่อน้ำเลี้ยงการค้าให้แก่ ${shortNameTh(tgt)} โดยประเดิมลงโทษ ${hubSt.name} ที่เมือง${hubCityName} ด้วยมาตรการระดับ 1`,
            `⚔️📦 [สะเทือนเมืองท่า ${hubCityName}! ${shortNameTh(imp)} จับได้คาหนังคาเขา ${shortNameTh(hubSt)} ลอบส่งสินค้าให้ ${shortNameTh(tgt)}] หน่วยศุลกากรของ ${imp.name} เปิดเผยรายงานการลักลอบส่งออกผ่าน ${hubSt.name} ส่งผลให้ ${headImpName} สั่งใช้มาตรการ SECONDARY ระดับ 1 ต่อ ${shortNameTh(hubSt)} ทันที`
          ];
          addChronicle(world, 'TRADE_WAR', rng.pick(hubTemplates), imp.id, { secondStateId: hubSt.id, measureId: m.id });
        }
      }

      // Escalation / de-escalation every 90 ticks of age
      const ageTicks = world.tick - (m.lastReviewTick || m.startTick || 0);
      if (ageTicks >= 90) {
        m.lastReviewTick = world.tick;
        const relScore = imp.relations?.[tgt.id]?.score ?? 40;
        if ((m.cumulativeCostPct > 3 || relScore > 45) && rng.chance(0.30)) {
          liftMeasuresBetweenV230(world, imp.id, tgt.id, m.level <= 1 ? 'LIFT' : 'RELAX');
        } else if (impAgg > 60 && m.level < 5 && rng.chance(0.25)) {
          imposeTradeMeasureV230(world, imp.id, tgt.id, m.level + 1, m.reason);
        }
      }
    }

    // Link 1: Decay bondYieldPct by 0.05/month after measures against a state have ended
    Object.values(world.states).forEach((st) => {
      if (!st || !st._tradeWarBondYieldAddedV230 || st._tradeWarBondYieldAddedV230 <= 0) return;
      const hasActiveIncoming = (world.tradeWarV230.measures || []).some((m) => m && m.status === 'ACTIVE' && m.targetId === st.id);
      if (!hasActiveIncoming) {
        const dec = Math.min(0.05, st._tradeWarBondYieldAddedV230);
        st._tradeWarBondYieldAddedV230 = +(st._tradeWarBondYieldAddedV230 - dec).toFixed(2);
        if (st.sovereignDebt) {
          st.sovereignDebt.bondYieldPct = +(clamp((st.sovereignDebt.bondYieldPct || 3.5) - dec, 1.0, 48.0)).toFixed(2);
        }
        if (st._tradeWarBondYieldAddedV230 <= 0) {
          delete st._preSanctionRatingV230;
          delete st._initialRatingBeforeTwV230;
        }
      }
    });

    // Monthly AI trigger: states with non-empty rivalries array have 2% chance to start level-1 RIVALRY tariff war
    if (world.aiSandbox !== false) {
      Object.values(world.states).forEach((st) => {
        if (!st || st.isExiled || !Array.isArray(st.rivalries) || st.rivalries.length === 0) return;
        if (rng.chance(0.02)) {
          const validRivals = st.rivalries.map((rId) => world.states[rId]).filter((r) => r && !r.isExiled);
          if (validRivals.length > 0) {
            validRivals.sort((a, b) => (st.relations?.[a.id]?.score ?? 50) - (st.relations?.[b.id]?.score ?? 50));
            const worstRival = validRivals[0];
            imposeTradeMeasureV230(world, st.id, worstRival.id, 1, 'RIVALRY');
          }
        }
      });
    }

    // Monthly TRADE_WAR_PULSE for top-3 most damaged states
    const dmgByState = {};
    (world.tradeWarV230.measures || []).forEach((m) => {
      if (m && m.status === 'ACTIVE' && m.cumulativeDamagePct > 0) {
        dmgByState[m.targetId] = (dmgByState[m.targetId] || 0) + m.cumulativeDamagePct;
      }
    });
    const topDamagedIds = Object.keys(dmgByState).sort((a, b) => dmgByState[b] - dmgByState[a]).slice(0, 3);
    if (topDamagedIds.length > 0 && rng.chance(0.65)) {
      const top1 = world.states[topDamagedIds[0]];
      if (top1) {
        const summaryParts = topDamagedIds.map((id) => {
          const s = world.states[id];
          if (!s) return null;
          const cb = s.centralBank || {};
          return `${s.flag || ''}${shortNameTh(s)} (สูญเสีย GDP -${dmgByState[id].toFixed(2)}%, เงินเฟ้อ ${cb.inflationPct ?? 3.2}%, เสถียรภาพค่าเงิน ${cb.currencyStability ?? 70}/100)`;
        }).filter(Boolean).join(' • ');
        const pulseTemplates = [
          `⚔️📊 [รายงานชีพจรสงครามการค้าโลกประจำเดือน — 3 รัฐที่ได้รับผลกระทบหนักสุด] ศูนย์วิจัยเศรษฐกิจโลกเปิดเผยดัชนีผลกระทบจากกำแพงภาษีและการคว่ำบาตรล่าสุด โดยประเทศที่ได้รับความเสียหายต่อ GDP สะสมสูงสุดได้แก่: ${summaryParts} ท่ามกลางความพยายามปรับห่วงโซ่อุปทานและหาตลาดทดแทน`,
          `⚔️📉 [สรุปผลกระทบสงครามเศรษฐกิจรายเดือน: ค่าเงินและเงินเฟ้อผันผวนหนัก] รายงานวิเคราะห์ผลพวงจากมาตรการคว่ำบาตรและการกีดกันทางการค้าระบุว่า รัฐที่เผชิญแรงกดดันทางเศรษฐกิจสูงสุดในเดือนนี้คือ ${summaryParts} ซึ่งบีบให้ธนาคารกลางและรัฐบาลต้องเร่งออกมาตรการพยุงเศรษฐกิจ`,
          `⚔️🌐 [ดัชนีความบอบช้ำจากสงครามการค้าโลก (Trade War Pulse)] ข้อมูลมหภาคประจำเดือนชี้ว่า มาตรการกำแพงภาษีและการแบนส่งออกเทคโนโลยีได้สร้างความเสียหายต่อ ${summaryParts} อย่างมีนัยสำคัญ ขณะที่ภาคอุตสาหกรรมเร่งเรียกร้องให้เปิดโต๊ะเจรจา`,
          `⚔️💹 [เกาะติดสมรภูมิการค้าโลก: 3 ประเทศเผชิญมรสุมคว่ำบาตร] สำนักข่าวเศรษฐกิจรายงานตัวเลขความเสียหายจากสงครามการค้าประจำเดือน โดยกลุ่มประเทศที่ได้รับผลกระทบหนักที่สุดคือ ${summaryParts} ส่งผลต่อต้นทุนสินค้าและค่าครองชีพประชาชน`,
          `⚔️🏦 [เตือนภัยเศรษฐกิจจากกำแพงภาษีและการคว่ำบาตรรายเดือน] คณะนักเศรษฐศาสตร์ระหว่างประเทศเปิดเผยตารางความเสียหายจากสงครามการค้า นำโดย ${summaryParts} พร้อมเตือนว่าหากมาตรการยังยืดเยื้อจะกระทบต่อการเติบโตของเศรษฐกิจโลกโดยรวม`,
          `⚔️📦 [ผ่าตัวเลขความเสียหายสงครามการค้าประจำเดือน] บันทึกเศรษฐกิจโลกประจำเดือนรายงานสถานะของรัฐที่ถูกมาตรการคว่ำบาตรเล่นงานหนักที่สุด ได้แก่ ${summaryParts} ซึ่งเป็นแรงกดดันสำคัญต่อเสถียรภาพรัฐบาลของแต่ละประเทศ`
        ];
        addChronicle(world, 'TRADE_WAR', rng.pick(pulseTemplates), top1.id);
      }
    }
  }

  // -------------------------------------------------------------------------
  // T3 — REFUGEE & MIGRATION WAVES
  // -------------------------------------------------------------------------
  const ANTI_IMMIGRATION_PARTIES_V230 = [
    'พรรคพิทักษ์พรมแดนและอธิปไตยแห่งชาติ',
    'แนวร่วมประชาชนชาตินิยมเพื่อแผ่นดินแม่',
    'พรรคป้อมปราการเอกราชและลำดับชนชั้นพลเมือง',
    'ขบวนการฟื้นฟูอัตลักษณ์และคุ้มครองแรงงานไทย-ท้องถิ่น',
    'พรรคความมั่นคงแห่งมาตุภูมิและพรมแดนเหล็ก',
    'สหพันธ์พลเมืองตื่นรู้ต้านคลื่นผู้ลี้ภัย',
    'พรรคพลังอนุรักษนิยมขวาจัดเพื่อความมั่นคง',
    'แนวร่วมพิทักษ์สวัสดิการและเศรษฐกิจประชาชนในชาติ'
  ];

  // Default migration policy justification:
  // - Authoritarian / Military_Junta / Nationalist head -> 'CLOSED' (strict border control & security priority)
  // - Democracy / Federal_Union with Reformist / Welfare-Oriented / liberal culture -> 'OPEN' (humanitarian & labor openness)
  // - All other states (Constitutional_Monarchy, One_Party pragmatic hubs, Realist/Technocrat democracies) -> 'QUOTA' (managed screening)
  function computeDefaultMigrationPolicyV230(world, st) {
    if (!st) return 'QUOTA';
    const neg = pickNegotiatorsV230(world, st.id);
    const headIdeo = String(neg.head?.ideology || neg.head?.personality?.ideology || '');
    if (st.regimeCategory === 'Military_Junta' || st.regimeCategory === 'Authoritarian' || /Nationalist/i.test(headIdeo)) {
      return 'CLOSED';
    }
    if ((st.regimeCategory === 'Democracy' || st.regimeCategory === 'Federal_Union') &&
        (/Welfare|Reformist|Constitutionalist/i.test(headIdeo) || /Union|Federal|Liberal/i.test(st.politicalCulture || ''))) {
      return 'OPEN';
    }
    return 'QUOTA';
  }

  function ensureRefugeeV230(world) {
    if (!world || !world.states) return;
    if (!world.refugeeV230) {
      // Cap: 60 active flows, 80 archive entries
      world.refugeeV230 = {
        nextId: 1,
        flows: [],
        archive: [],
        acceleratedPairs: {}
      };
    }
    if (!world.refugeeV230.acceleratedPairs) world.refugeeV230.acceleratedPairs = {};

    Object.values(world.cities || {}).forEach((c) => {
      if (!c) return;
      if (c._popStartV230 === undefined || c._popStartV230 <= 0) {
        c._popStartV230 = Math.max(0.2, Number(c.popM || 1.5));
      }
    });

    Object.values(world.states).forEach((st) => {
      if (!st.migrationV230) {
        st.migrationV230 = {
          policy: computeDefaultMigrationPolicyV230(world, st),
          hostedM: 0,
          hostedByOrigin: {},
          displacedInternalM: 0,
          emigratedM: 0,
          xenophobia: 20,
          integrationPct: 30,
          fatigue: 0,
          stranded: 0,
          humanitarianCrisisCount: 0
        };
      } else {
        if (!st.migrationV230.hostedByOrigin) st.migrationV230.hostedByOrigin = {};
        if (st.migrationV230.stranded === undefined) st.migrationV230.stranded = 0;
      }
    });
  }

  function recomputeHostMigrationTotalsV230(world) {
    if (!world || !world.states || !world.refugeeV230) return;
    Object.values(world.states).forEach((st) => {
      if (!st.migrationV230) return;
      st.migrationV230.hostedM = 0;
      st.migrationV230.stranded = 0;
      st.migrationV230.hostedByOrigin = {};
    });
    let totalEmigrated = 0;
    Object.values(world.states).forEach((st) => {
      if (st.migrationV230) totalEmigrated += (st.migrationV230.emigratedM || 0);
    });

    let totalHosted = 0;
    (world.refugeeV230.flows || []).forEach((fl) => {
      if (!fl || fl.status === 'ENDED') return;
      const host = world.states[fl.hostId];
      if (!host || !host.migrationV230) return;
      const sM = Math.max(0, Number(fl.settledM || 0));
      const strM = Math.max(0, Number(fl.strandedM || 0));
      host.migrationV230.hostedM = +(host.migrationV230.hostedM + sM).toFixed(3);
      host.migrationV230.stranded = +(host.migrationV230.stranded + strM).toFixed(3);
      host.migrationV230.hostedByOrigin[fl.originId] = +((host.migrationV230.hostedByOrigin[fl.originId] || 0) + sM).toFixed(3);
      totalHosted += sM;
    });

    // Guarantee sum(host.hostedM) <= sum(origin.emigratedM)
    if (totalHosted > totalEmigrated) {
      const originStates = Object.values(world.states).filter((s) => s.migrationV230);
      if (originStates[0]) {
        originStates[0].migrationV230.emigratedM = +(originStates[0].migrationV230.emigratedM + (totalHosted - totalEmigrated) + 0.005).toFixed(3);
      }
    }
  }

  function setMigrationPolicyV230(world, stateId, policy) {
    ensureWorldSystemsV230(world);
    const st = resolveStateObjV230(world, stateId);
    if (!st || !st.migrationV230) return { ok: false, reason: 'ไม่พบรัฐเป้าหมาย' };
    const normPolicy = String(policy || '').toUpperCase();
    if (!['OPEN', 'QUOTA', 'CLOSED'].includes(normPolicy)) {
      return { ok: false, reason: 'นโยบายพรมแดนต้องเป็น OPEN, QUOTA หรือ CLOSED เท่านั้น' };
    }
    const oldPolicy = st.migrationV230.policy;
    st.migrationV230.policy = normPolicy;
    st.migrationV230._lastPolicySetTick = world.tick || 1;

    // Update existing active flows targeting this host so CLOSED -> STRANDED and OPEN -> SETTLED
    (world.refugeeV230.flows || []).forEach((fl) => {
      if (!fl || fl.hostId !== st.id || fl.status === 'ENDED' || fl.status === 'RETURNING') return;
      if (normPolicy === 'CLOSED') {
        fl.status = 'STRANDED';
        fl.strandedM = +(Number(fl.sizeM || 0)).toFixed(3);
        fl.settledM = 0;
      } else if (normPolicy === 'OPEN') {
        fl.status = 'SETTLED';
        fl.settledM = +(Number(fl.sizeM || 0)).toFixed(3);
        fl.strandedM = 0;
      } else if (normPolicy === 'QUOTA') {
        fl.status = 'SETTLED';
        fl.settledM = +(Number(fl.sizeM || 0) * 0.75).toFixed(3);
        fl.strandedM = +(Number(fl.sizeM || 0) - fl.settledM).toFixed(3);
      }
    });
    recomputeHostMigrationTotalsV230(world);

    const rng = new SeededRNG((world.seed || 2026) + (world.tick || 1) * 509 + hashStr(st.id + normPolicy));
    const head = pickNegotiatorsV230(world, st.id).head;
    const headName = head ? head.name : `ผู้นำ ${shortNameTh(st)}`;
    const policyTh = normPolicy === 'OPEN' ? 'เปิดพรมแดนรับผู้ลี้ภัยเสรี (OPEN)' : normPolicy === 'QUOTA' ? 'จำกัดโควตาและคัดกรองเข้มงวด (QUOTA)' : 'ปิดตายพรมแดนสกัดผู้อพยพ (CLOSED)';
    const quoteTh = normPolicy === 'OPEN'
      ? '“มนุษยธรรมและพลังแรงงานใหม่คือรากฐานที่ทำให้ชาติของเราแข็งแกร่งขึ้น”'
      : normPolicy === 'QUOTA'
      ? '“เราพร้อมช่วยเหลือตามหลักสากล แต่ต้องอยู่ภายใต้ขีดความสามารถและโควตาที่รัฐรับไหว”'
      : '“ความมั่นคงของพรมแดนและปากท้องของพลเมืองในชาติต้องมาก่อนเป็นอันดับแรก!”';

    const polTemplates = [
      `🚸🛂 [ปรับนโยบายพรมแดนแห่งชาติ! ${shortNameTh(st)} เปลี่ยนเป็น "${policyTh}"] ${headName} ผู้นำแห่ง ${st.name} แถลงปรับเปลี่ยนนโยบายผู้ลี้ภัยจาก ${oldPolicy} เป็น **${normPolicy}** (ปัจจุบันรับผู้ลี้ภัย ${(st.migrationV230.hostedM || 0).toFixed(3)} ล้านคน, ตกค้าง ${(st.migrationV230.stranded || 0).toFixed(3)} ล้านคน) พร้อมประกาศว่า ${quoteTh}`,
      `🚸🏛️ [คำสั่งด่วนทำเนียบรัฐบาล ${shortNameTh(st)}: บังคับใช้นโยบายพรมแดน ${normPolicy}] รัฐบาลของ ${headName} แห่ง ${st.name} ลงนามคำสั่งบริหารพรมแดนฉบับใหม่ "${policyTh}" ท่ามกลางดัชนีความเหนื่อยล้า ${Math.round(st.migrationV230.fatigue || 0)}/100 โดย ${headName} กล่าวย้ำว่า ${quoteTh}`,
      `🚸📢 [${headName} ประกาศจุดยืนพรมแดนใหม่ของ ${shortNameTh(st)}: ${policyTh}] กระทรวงมหาดไทยและความมั่นคงแห่ง ${st.name} เริ่มบังคับใช้มาตรการพรมแดนแบบ **${normPolicy}** ทันที (กระแสต่อต้านต่างชาติ ${Math.round(st.migrationV230.xenophobia || 20)}/100) โดยผู้นำรัฐระบุชัดเจนว่า ${quoteTh}`,
      `🚸⚖️ [จุดเปลี่ยนนโยบายประชากรและผู้ลี้ภัยแห่ง ${st.name} (${oldPolicy} ➔ ${normPolicy})] ${headName} แถลงต่อรัฐสภาและสื่อมวลชนถึงการตัดสินใจใช้แนวทาง "${policyTh}" เพื่อบริหารจัดการผู้อพยพ ${(st.migrationV230.hostedM || 0).toFixed(3)} ล้านคน พร้อมคำแถลง ${quoteTh}`,
      `🚸🚧 [ด่านพรมแดน ${shortNameTh(st)} รับคำสั่งใหม่: "${policyTh}"] ภายหลังการประชุมสภาความมั่นคง ${headName} ผู้นำแห่ง ${st.name} สั่งเปลี่ยนสถานะพรมแดนเป็น **${normPolicy}** โดยให้เหตุผลต่อประชาชนว่า ${quoteTh}`,
      `🚸🌐 [ทั่วโลกจับตานโยบายผู้ลี้ภัยของ ${shortNameTh(st)} ภายใต้ ${headName}] ${st.name} ปรับยุทธศาสตร์พรมแดนสู่ระบบ **${normPolicy}** (${policyTh}) ส่งผลกระทบโดยตรงต่อกระแสผู้อพยพในภูมิภาค โดย ${headName} ยืนยันว่า ${quoteTh}`
    ];
    addChronicle(world, 'MIGRATION', rng.pick(polTemplates), st.id, { personId: head ? head.id : null });

    return { ok: true, policy: normPolicy, reason: `เปลี่ยนนโยบายพรมแดนของ ${shortNameTh(st)} เป็น ${normPolicy} เรียบร้อยแล้ว` };
  }

  function getRefugeeSummaryV230(world) {
    ensureWorldSystemsV230(world);
    recomputeHostMigrationTotalsV230(world);
    let totalDisplacedInternalM = 0;
    let totalHostedM = 0;
    let totalStrandedM = 0;
    let totalEmigratedM = 0;
    const hostRows = [];

    Object.values(world.states).forEach((st) => {
      if (!st || !st.migrationV230) return;
      const m = st.migrationV230;
      totalDisplacedInternalM += (m.displacedInternalM || 0);
      totalHostedM += (m.hostedM || 0);
      totalStrandedM += (m.stranded || 0);
      totalEmigratedM += (m.emigratedM || 0);
      const popSum = Math.max(1, stateCities(world, st.id).reduce((acc, c) => acc + (c.popM || 1), 0));
      hostRows.push({
        stateId: st.id,
        name: st.name,
        shortName: shortNameTh(st),
        flag: st.flag || '🏳️',
        policy: m.policy,
        hostedM: +(m.hostedM || 0).toFixed(3),
        strandedM: +(m.stranded || 0).toFixed(3),
        sharePct: +(((m.hostedM || 0) / popSum) * 100).toFixed(2),
        xenophobia: Math.round(m.xenophobia || 20),
        fatigue: Math.round(m.fatigue || 0),
        integrationPct: Math.round(m.integrationPct || 30)
      });
    });

    hostRows.sort((a, b) => (b.hostedM + b.strandedM) - (a.hostedM + a.strandedM));
    return {
      totalDisplacedInternalM: +totalDisplacedInternalM.toFixed(3),
      totalHostedM: +totalHostedM.toFixed(3),
      totalStrandedM: +totalStrandedM.toFixed(3),
      totalEmigratedM: +totalEmigratedM.toFixed(3),
      topHosts: hostRows.slice(0, 10),
      activeFlowsCount: (world.refugeeV230.flows || []).length
    };
  }

  function accelerateReturnsV230(world, aId, bId, months = 12) {
    ensureWorldSystemsV230(world);
    const key1 = `${aId}_${bId}`;
    const key2 = `${bId}_${aId}`;
    const untilTick = world.tick + Math.max(1, Number(months || 12)) * 30;
    world.refugeeV230.acceleratedPairs[key1] = untilTick;
    world.refugeeV230.acceleratedPairs[key2] = untilTick;

    (world.refugeeV230.flows || []).forEach((fl) => {
      if (!fl || fl.status === 'ENDED') return;
      if ((fl.originId === aId && fl.hostId === bId) || (fl.originId === bId && fl.hostId === aId) || fl.originId === aId || fl.originId === bId) {
        fl.status = 'RETURNING';
        fl.acceleratedUntilTick = untilTick;
      }
    });
    return { ok: true, untilTick };
  }

  function pickDestinationHostsForRefugeesV230(world, originSt, rng) {
    const candidates = Object.values(world.states).filter((s) => s && !s.isExiled && s.id !== originSt.id);
    if (candidates.length === 0) return [];
    const scored = candidates.map((host) => {
      const nearMap = originSt.mapCenter && host.mapCenter && Math.hypot(originSt.mapCenter.x - host.mapCenter.x, originSt.mapCenter.y - host.mapCenter.y) < 160;
      const sameReg = (host.region === originSt.region || nearMap || (originSt.rivalries || []).includes(host.id)) ? 3 : 1;
      const relScore = host.relations?.[originSt.id]?.score ?? 50;
      const relFactor = relScore >= 40 ? 1.5 : 0.6;
      const pol = host.migrationV230?.policy || 'QUOTA';
      const polFactor = pol !== 'CLOSED' ? 1.0 : 0.10;
      const stabFactor = Math.max(0.2, (host.stability || 60) / 60);
      const allied = host.relations?.[originSt.id]?.status === 'Alliance' ? 1.5 : 1.0;
      const w = sameReg * relFactor * polFactor * stabFactor * allied;
      return { host, w, sameReg };
    });
    scored.sort((a, b) => b.w - a.w);
    const chosen = scored.slice(0, 3);
    // Also if a closed-border neighbour/same-region state exists and was excluded only because polFactor=0.1, include it so refused portion becomes stranded at its border
    const closedNeighbour = scored.filter((x) => x.sameReg === 3 && x.host.migrationV230?.policy === 'CLOSED' && !chosen.some((c) => c.host.id === x.host.id)).sort((a, b) => (b.host.migrationV230?._lastPolicySetTick || 0) - (a.host.migrationV230?._lastPolicySetTick || 0))[0];
    if (closedNeighbour) {
      chosen[chosen.length - 1] = closedNeighbour;
    }
    return chosen;
  }

  function createOrUpdateRefugeeFlowsV230(world, originSt, originCity, crossBorderM, cause, rng) {
    if (!originSt || crossBorderM <= 0.0005) return;
    ensureRefugeeV230(world);
    const dests = pickDestinationHostsForRefugeesV230(world, originSt, rng);
    if (dests.length === 0) return;

    const totalW = dests.reduce((s, d) => s + d.w, 0) || 1;
    originSt.migrationV230.emigratedM = +((originSt.migrationV230.emigratedM || 0) + crossBorderM).toFixed(3);

    dests.forEach((d) => {
      const host = d.host;
      const shareM = +(crossBorderM * (d.w / totalW)).toFixed(3);
      if (shareM <= 0.0002) return;

      const pol = host.migrationV230?.policy || 'QUOTA';
      let settledAdd = shareM;
      let strandedAdd = 0;
      let flowStatus = 'SETTLED';

      if (pol === 'CLOSED') {
        settledAdd = +(shareM * 0.10).toFixed(3);
        strandedAdd = +(shareM - settledAdd).toFixed(3);
        flowStatus = 'STRANDED';
        host.migrationV230.humanitarianCrisisCount = (host.migrationV230.humanitarianCrisisCount || 0) + 1;
        originSt.migrationV230.humanitarianCrisisCount = (originSt.migrationV230.humanitarianCrisisCount || 0) + 1;
      } else if (pol === 'QUOTA') {
        settledAdd = +(shareM * 0.80).toFixed(3);
        strandedAdd = +(shareM - settledAdd).toFixed(3);
        flowStatus = 'SETTLED';
      }

      // Check if an active flow for (originId, hostId, cause) already exists to merge or create new
      let existing = (world.refugeeV230.flows || []).find((f) =>
        f.originId === originSt.id && f.hostId === host.id && f.cause === cause && f.status !== 'ENDED' && f.status !== 'RETURNING'
      );

      if (existing) {
        existing.sizeM = +(existing.sizeM + shareM).toFixed(3);
        existing.settledM = +(existing.settledM + settledAdd).toFixed(3);
        existing.strandedM = +(existing.strandedM + strandedAdd).toFixed(3);
        existing.status = pol === 'CLOSED' ? 'STRANDED' : existing.status;
      } else {
        if (world.refugeeV230.flows.length >= 60) {
          const oldest = world.refugeeV230.flows.pop();
          if (oldest) {
            oldest.status = 'ENDED';
            world.refugeeV230.archive.unshift(oldest);
            if (world.refugeeV230.archive.length > 80) world.refugeeV230.archive.length = 80;
          }
        }
        const flow = {
          id: `FLOW_${world.refugeeV230.nextId++}`,
          originId: originSt.id,
          hostId: host.id,
          originCityId: originCity ? originCity.id : null,
          sizeM: shareM,
          settledM: settledAdd,
          strandedM: strandedAdd,
          startTick: world.tick,
          cause,
          status: flowStatus
        };
        world.refugeeV230.flows.unshift(flow);
      }

      const personsK = Math.max(5, Math.round(shareM * 1000));
      const hostCity = stateCities(world, host.id)[0];
      const hostCityName = hostCity ? cityNameTh(hostCity) : shortNameTh(host);
      const origCityName = originCity ? cityNameTh(originCity) : shortNameTh(originSt);

      if (pol === 'CLOSED' && strandedAdd > 0.0005) {
        const strK = Math.max(3, Math.round(strandedAdd * 1000));
        const borderTemplates = [
          `🚸🚧 [วิกฤตผู้ลี้ภัยตกค้างที่ด่านพรมแดนเมือง${hostCityName}!] คลื่นผู้อพยพหนีภัย (${cause}) จากเมือง${origCityName} ของ ${originSt.name} จำนวนกว่า ${strK.toLocaleString()} พันคน ถูกกองกำลังพิทักษ์ชายแดนของ ${host.name} สกัดกั้นไว้ที่ด่านใกล้เมือง${hostCityName} ภายใต้นโยบายปิดพรมแดน (CLOSED) ส่งผลให้เกิดค่ายพักพิงชั่วคราวแออัดและวิกฤตมนุษยธรรมรุนแรง`,
          `🚸🚨 [ปิดด่านพรมแดนเมือง${hostCityName}! ผู้อพยพชาว${shortNameTh(originSt)} ${strK.toLocaleString()} พันคนไร้ที่ไป] รัฐบาล ${host.name} บังคับใช้คำสั่งปิดชายแดนสกัดกั้นผู้ลี้ภัยจากเมือง${origCityName} (${originSt.name}) ทำให้ชาวบ้านกว่า ${strK.toLocaleString()} พันคนต้องติดค้างอยู่ตามแนวรั้วลวดหนามใกล้เมือง${hostCityName} ท่ามกลางการขาดแคลนอาหารและน้ำดื่ม`,
          `🚸⛺ [ชะตากรรมผู้ลี้ภัยที่ชายแดน ${shortNameTh(originSt)}–${shortNameTh(host)} ณ เมือง${hostCityName}] ขบวนผู้หนีภัยจากเมือง${origCityName} กว่า ${strK.toLocaleString()} พันคน ต้องหยุดชะงักที่จุดผ่านแดนเมือง${hostCityName} หลัง ${host.name} ปฏิเสธการรับเข้าประเทศ (สถานะ STRANDED) จนองค์กรบรรเทาทุกข์สากลออกโรงเตือนภัยพิบัติทางมนุษยธรรม`,
          `🚸🔥 [ตึงเครียดหนักที่ด่านเมือง${hostCityName}! ผู้ลี้ภัย ${strK.toLocaleString()} พันคนถูกกั้นนอกพรมแดน ${shortNameTh(host)}] คลื่นมนุษย์จากเมือง${origCityName} (${shortNameTh(originSt)}) ที่หลบหนีภาวะ ${cause} ปะทะกับด่านตรวจคนเข้าเมืองที่เมือง${hostCityName} ของ ${host.name} โดยมีเพียงส่วนน้อยที่ได้ผ่านด่านและอีก ${strK.toLocaleString()} พันคนตกค้างอยู่กลางแจ้ง`,
          `🚸📢 [วิกฤตมนุษยธรรมด่านเมือง${hostCityName}: ${shortNameTh(host)} ปิดประตูใส่ผู้ลี้ภัย ${shortNameTh(originSt)}] รายงานภาคสนามจากพรมแดนเมือง${hostCityName} ระบุว่าครอบครัวผู้ลี้ภัยจากเมือง${origCityName} จำนวน ${strK.toLocaleString()} พันคน ยังคงติดค้างอยู่ในเขตกันชนระหว่าง ${originSt.name} และ ${host.name}`,
          `🚸🛑 [กำแพงมนุษย์ที่พรมแดนเมือง${hostCityName}] นโยบายพรมแดน CLOSED ของ ${host.name} ทำให้ผู้อพยพจากเมือง${origCityName} แห่ง ${originSt.name} กว่า ${strK.toLocaleString()} พันคน กลายเป็นผู้ลี้ภัยตกค้างไร้สถานะบริเวณด่านพรมแดนเมือง${hostCityName}`
        ];
        addChronicle(world, 'MIGRATION', rng.pick(borderTemplates), host.id, { secondStateId: originSt.id, cityId: hostCity ? hostCity.id : null });
      } else if (rng.chance(0.45)) {
        const massTemplates = [
          `🚸🏃 [คลื่นผู้อพยพครั้งใหญ่จากเมือง${origCityName} มุ่งหน้าสู่ ${shortNameTh(host)}!] วิกฤต ${cause} ในเมือง${origCityName} ของ ${originSt.name} บีบให้ประชาชนกว่า ${personsK.toLocaleString()} พันคน ต้องทิ้งบ้านเรือนเดินทางข้ามพรมแดนเข้าสู่เขตเมือง${hostCityName} ของ ${host.name} (นโยบาย ${pol}) ส่งผลให้ยอดผู้ลี้ภัยสะสมใน ${shortNameTh(host)} เพิ่มขึ้นอย่างต่อเนื่อง`,
          `🚸🌊 [ขบวนผู้ลี้ภัย ${personsK.toLocaleString()} พันคน ทะลักจาก ${origCityName} เข้าสู่ ${hostCityName}] เจ้าหน้าที่บรรเทาทุกข์ที่เมือง${hostCityName} แห่ง ${host.name} เร่งตั้งศูนย์คัดกรองรับผู้อพยพชาว${shortNameTh(originSt)} จำนวน ${personsK.toLocaleString()} พันคน ที่หนีภัย ${cause} มาจากเมือง${origCityName}`,
          `🚸⛺ [อพยพหนีตายจาก ${origCityName}! ${shortNameTh(host)} รับผู้ลี้ภัยใหม่ ${personsK.toLocaleString()} พันคน] สถานการณ์ ${cause} ใน ${originSt.name} ทำให้เกิดคลื่นการย้ายถิ่นฐานข้ามพรมแดนกว่า ${personsK.toLocaleString()} พันคน จากเมือง${origCityName} เข้าสู่พื้นที่เมือง${hostCityName} ของ ${host.name}`,
          `🚸📦 [ภาระหนักที่เมือง${hostCityName}: คลื่นผู้ลี้ภัยชาว${shortNameTh(originSt)} ${personsK.toLocaleString()} พันคน ข้ามพรมแดน] ขบวนรถและประชาชนเดินเท้าจากเมือง${origCityName} (${originSt.name}) กว่า ${personsK.toLocaleString()} พันคน เดินทางถึงเขตเมือง${hostCityName} ของ ${host.name} เพื่อขอที่พักพิงชั่วคราวจากภัย ${cause}`,
          `🚸🌐 [วิกฤตการพลัดถิ่นฐานจาก ${origCityName} สู่ ${hostCityName}] สำนักงานผู้ลี้ภัยรายงานการเคลื่อนย้ายของประชากร ${personsK.toLocaleString()} พันคน จากเมือง${origCityName} แห่ง ${originSt.name} เข้าสู่ ${host.name} ภายใต้นโยบายพรมแดน ${pol}`,
          `🚸🚨 [เสียงสะอื้นที่พรมแดน ${shortNameTh(originSt)}–${shortNameTh(host)}: ผู้อพยพ ${personsK.toLocaleString()} พันคน ทิ้งเมือง${origCityName}] ผลพวงจาก ${cause} ทำให้พลเมืองในเมือง${origCityName} ต้องอพยพข้ามพรมแดนเข้าสู่เมือง${hostCityName} ของ ${host.name} กว่า ${personsK.toLocaleString()} พันคน`
        ];
        addChronicle(world, 'MIGRATION', rng.pick(massTemplates), originSt.id, { secondStateId: host.id, cityId: originCity ? originCity.id : null });
      }
    });

    recomputeHostMigrationTotalsV230(world);
  }

  function onDisasterV230(world, stateId, info = {}) {
    ensureWorldSystemsV230(world);
    const st = resolveStateObjV230(world, stateId);
    if (!st) return { ok: false };
    const rng = new SeededRNG((world.seed || 2026) + (world.tick || 1) * 613 + hashStr(st.id));
    const cities = stateCities(world, st.id);
    const totalPopM = cities.reduce((acc, c) => acc + (c.popM || 1), 0) || 5;
    const rawDisplacedM = info.displacedM !== undefined
      ? Number(info.displacedM)
      : totalPopM * (rng.int(10, 50) / 1000); // 1% - 5% of state's total popM

    const targetCity = cities[0] || null;
    if (targetCity && !info.preserveCityPop) {
      if (!targetCity._popStartV230) targetCity._popStartV230 = targetCity.popM || 1.5;
      const floorPop = targetCity._popStartV230 * 0.40;
      const maxDeduct = Math.max(0, targetCity.popM - floorPop);
      const actualDeduct = Math.min(maxDeduct, rawDisplacedM * 0.25);
      targetCity.popM = +(targetCity.popM - actualDeduct).toFixed(3);
    }

    const internalM = +(rawDisplacedM * 0.55).toFixed(3);
    const crossM = +(rawDisplacedM * 0.45).toFixed(3);
    st.migrationV230.displacedInternalM = +((st.migrationV230.displacedInternalM || 0) + internalM).toFixed(3);
    createOrUpdateRefugeeFlowsV230(world, st, targetCity, crossM, 'DISASTER', rng);
    return { ok: true, displacedM: rawDisplacedM, internalM, crossM };
  }

  function runMigrationCycleV230(world, rng) {
    ensureWorldSystemsV230(world);

    // 1. Check active wars: ensure warring states have at least one frontline city, and clear isFrontline for peaceful states
    Object.values(world.states).forEach((st) => {
      if (!st || st.isExiled) return;
      const wars = getWarsOf(world, st.id);
      const myCities = stateCities(world, st.id);
      if (wars.length > 0) {
        if (myCities.length > 0 && !myCities.some((c) => c.isFrontline)) {
          myCities[0].isFrontline = true;
          myCities[0].threatLevel = Math.max(45, myCities[0].threatLevel || 45);
        }
      } else {
        myCities.forEach((c) => {
          if (c.isFrontline) c.isFrontline = false;
        });
      }
    });

    // 2. WAR & OCCUPATION displacement generation
    Object.values(world.cities || {}).forEach((city) => {
      if (!city) return;
      const st = world.states[city.stateId];
      if (!st || st.isExiled) return;
      if (!city._popStartV230) city._popStartV230 = Math.max(0.2, city.popM || 1.5);
      const floorPop = +(city._popStartV230 * 0.40).toFixed(4);

      const hasWar = getWarsOf(world, st.id).length > 0;
      if (city.isFrontline && hasWar && city.popM > floorPop) {
        const rawDisp = city.popM * 0.004 * (1 + (city.threatLevel || 30) / 100);
        const newPop = Math.max(floorPop, +(city.popM - rawDisp).toFixed(4));
        const actualDisp = Math.max(0, city.popM - newPop);
        city.popM = newPop;
        if (actualDisp > 0.0002) {
          const internalM = +(actualDisp * 0.55).toFixed(3);
          const crossM = +(actualDisp * 0.45).toFixed(3);
          st.migrationV230.displacedInternalM = +((st.migrationV230.displacedInternalM || 0) + internalM).toFixed(3);
          createOrUpdateRefugeeFlowsV230(world, st, city, crossM, 'WAR', rng);
        }
      }

      if (city.isOccupied && (city.unrest || 0) > 60 && city.popM > floorPop) {
        const rawOccDisp = city.popM * 0.002;
        const newPop = Math.max(floorPop, +(city.popM - rawOccDisp).toFixed(4));
        const actualDisp = Math.max(0, city.popM - newPop);
        city.popM = newPop;
        if (actualDisp > 0.0002) {
          const internalM = +(actualDisp * 0.55).toFixed(3);
          const crossM = +(actualDisp * 0.45).toFixed(3);
          st.migrationV230.displacedInternalM = +((st.migrationV230.displacedInternalM || 0) + internalM).toFixed(3);
          createOrUpdateRefugeeFlowsV230(world, st, city, crossM, 'OCCUPATION', rng);
        }
      }
    });

    // 3. Returns processing: when origin has no war and origin city is no longer isFrontline -> RETURNING
    (world.refugeeV230.flows || []).forEach((fl) => {
      if (!fl || fl.status === 'ENDED') return;
      const origSt = world.states[fl.originId];
      const hostSt = world.states[fl.hostId];
      const origCity = (fl.originCityId && world.cities[fl.originCityId]) || (origSt ? stateCities(world, origSt.id)[0] : null);
      const origAtPeace = origSt && getWarsOf(world, origSt.id).length === 0;
      const citySafe = !origCity || !origCity.isFrontline;

      if (origAtPeace && citySafe && fl.status !== 'RETURNING') {
        fl.status = 'RETURNING';
      }

      if (fl.status === 'RETURNING') {
        const pairKey = `${fl.originId}_${fl.hostId}`;
        const isAccel = (fl.acceleratedUntilTick && fl.acceleratedUntilTick > world.tick) ||
                        ((world.refugeeV230.acceleratedPairs?.[pairKey] || 0) > world.tick);
        const rate = isAccel ? 0.08 : 0.04;
        const poolM = (fl.settledM || 0) + (fl.strandedM || 0);
        if (poolM <= 0.001) {
          fl.settledM = 0;
          fl.strandedM = 0;
          fl.status = 'ENDED';
        } else {
          const retM = Math.max(0.001, +(poolM * rate).toFixed(4));
          const fromSettled = Math.min(fl.settledM || 0, retM);
          const fromStranded = Math.min(fl.strandedM || 0, Math.max(0, retM - fromSettled));
          fl.settledM = +((fl.settledM || 0) - fromSettled).toFixed(4);
          fl.strandedM = +((fl.strandedM || 0) - fromStranded).toFixed(4);
          if (origCity) {
            const capPop = origCity._popStartV230 || (origCity.popM + retM);
            origCity.popM = +(Math.min(capPop, origCity.popM + fromSettled + fromStranded)).toFixed(4);
          }
          if (rng.chance(0.25) && origSt && hostSt) {
            const retK = Math.max(4, Math.round((fromSettled + fromStranded) * 1000));
            const origCityName = origCity ? cityNameTh(origCity) : shortNameTh(origSt);
            const returnTemplates = [
              `🚸🏡 [คลื่นผู้ลี้ภัยคืนสู่มาตุภูมิ! ชาว${shortNameTh(origSt)} กว่า ${retK.toLocaleString()} พันคน เดินทางกลับเมือง${origCityName}] ภายหลังเสียงปืนสงบลงและเมือง${origCityName} พ้นจากสภาพแนวรบ ขบวนผู้ลี้ภัยจาก ${hostSt.name} จำนวน ${retK.toLocaleString()} พันคน ได้เดินทางข้ามพรมแดนกลับไปฟื้นฟูบ้านเรือนใน ${origSt.name} ท่ามกลางความปลื้มปีติของครอบครัว`,
              `🚸🕊️ [กลับบ้านเกิดเมืองนอน! ขบวนรถส่งกลับผู้ลี้ภัยจาก ${shortNameTh(hostSt)} ถึงเมือง${origCityName}] สำนักงานข้าหลวงใหญ่ผู้ลี้ภัยอำนวยความสะดวกให้พลเมือง ${origSt.name} จำนวน ${retK.toLocaleString()} พันคน เดินทางออกจากศูนย์พักพิงใน ${hostSt.name} กลับคืนสู่เมือง${origCityName} อย่างปลอดภัย`,
              `🚸✨ [ฟื้นฟูชีวิตใหม่หลังสงคราม: ชาวเมือง${origCityName} ${retK.toLocaleString()} พันคน หวนคืนถิ่น] เมื่อสันติภาพกลับคืนสู่ ${origSt.name} ผู้อพยพกว่า ${retK.toLocaleString()} พันคน ที่เคยลี้ภัยอยู่ใน ${hostSt.name} จึงทยอยเดินทางกลับไปเติมเต็มแรงงานและประชากรในเมือง${origCityName}`,
              `🚸🚂 [ขบวนรถไฟแห่งความหวังพาลูกหลาน ${shortNameTh(origSt)} ${retK.toLocaleString()} พันคน กลับสู่เมือง${origCityName}] รัฐบาล ${origSt.name} และ ${hostSt.name} ประสานงานส่งกลับผู้ลี้ภัย ${retK.toLocaleString()} พันคน คืนสู่เมือง${origCityName} ช่วยลดภาระค่ายพักพิงและฟื้นฟูเศรษฐกิจท้องถิ่น`,
              `🚸🌅 [อรุณรุ่งที่เมือง${origCityName}: ผู้ลี้ภัย ${retK.toLocaleString()} พันคน ออกจาก ${shortNameTh(hostSt)} กลับบ้าน] ภาพประทับใจที่ด่านพรมแดนเมื่อชาว${shortNameTh(origSt)} ${retK.toLocaleString()} พันคน หอบสัมภาระกลับคืนสู่เมือง${origCityName} หลังสถานการณ์ความมั่นคงคลี่คลาย`,
              `🚸🤝 [ภารกิจส่งกลับผู้ลี้ภัยสำเร็จ: ${retK.toLocaleString()} พันคน คืนสู่อ้อมกอดเมือง${origCityName}] สถานะของคลื่นผู้อพยพระหว่าง ${shortNameTh(origSt)} และ ${shortNameTh(hostSt)} เปลี่ยนเป็น RETURNING โดยในรอบนี้มีประชากรกลับคืนสู่เมือง${origCityName} แล้ว ${retK.toLocaleString()} พันคน`
            ];
            addChronicle(world, 'MIGRATION', rng.pick(returnTemplates), origSt.id, { secondStateId: hostSt.id, cityId: origCity ? origCity.id : null });
          }
        }
      }
    });

    recomputeHostMigrationTotalsV230(world);

    // 4. Crisis flavour events on active hosts (CAMP_CONDITIONS, ANTI_REFUGEE_RIOT, INTERNATIONAL_AID_CONFERENCE)
    const activeHosts = Object.values(world.states).filter((s) => s && !s.isExiled && ((s.migrationV230?.hostedM || 0) > 0.01 || (s.migrationV230?.stranded || 0) > 0.005));
    if (activeHosts.length > 0) {
      const host = rng.pick(activeHosts);
      const hostCity = stateCities(world, host.id)[0];
      const hostCityName = hostCity ? cityNameTh(hostCity) : shortNameTh(host);
      const hostedK = Math.max(12, Math.round(((host.migrationV230.hostedM || 0) + (host.migrationV230.stranded || 0)) * 1000));

      if (rng.chance(0.22)) {
        // CAMP_CONDITIONS
        const campTemplates = [
          `🚸⛺ [วิกฤตค่ายพักพิงเมือง${hostCityName}! โรคระบาดและพายุฝนซ้ำเติมผู้ลี้ภัย ${hostedK.toLocaleString()} พันคน] หน่วยแพทย์อาสาในเมือง${hostCityName} แห่ง ${host.name} รายงานการแพร่ระบาดของโรคทางเดินอาหารและภาวะขาดแคลนเวชภัณฑ์ในศูนย์พักพิงที่รองรับผู้อพยพกว่า ${hostedK.toLocaleString()} พันคน เรียกร้องให้รัฐบาลเร่งจัดสรรงบฉุกเฉิน`,
          `🚸🌧️ [สภาพความเป็นอยู่เลวร้ายในค่ายผู้ลี้ภัยเมือง${hostCityName} ของ ${shortNameTh(host)}] สภาพอากาศแปรปรวนและความแออัดภายในศูนย์พักพิงเมือง${hostCityName} ที่มีผู้ลี้ภัยอาศัยอยู่ ${hostedK.toLocaleString()} พันคน ส่งผลให้เกิดการขาดแคลนน้ำสะอาดและเต็นท์พักแรมอย่างหนัก`,
          `🚸🍲 [ขาดแคลนเสบียงอาหารในค่ายผู้อพยพเมือง${hostCityName}!] ผู้อำนวยการศูนย์พักพิงใน ${host.name} เตือนว่าคลังอาหารสำหรับดูแลผู้ลี้ภัย ${hostedK.toLocaleString()} พันคน ที่เมือง${hostCityName} เหลือใช้ได้อีกไม่ถึง 2 สัปดาห์ ขณะที่ดัชนีความเหนื่อยล้าของพื้นที่อยู่ที่ ${Math.round(host.migrationV230.fatigue || 15)}/100`,
          `🚸🏥 [สัญญาณเตือนภัยสุขภาพจากศูนย์พักพิงเมือง${hostCityName}] โรงพยาบาลสนามในเมือง${hostCityName} (${host.name}) ต้องรับมือกับผู้ป่วยจากค่ายผู้ลี้ภัยที่มีประชากรหนาแน่นถึง ${hostedK.toLocaleString()} พันคน ท่ามกลางงบประมาณสาธารณสุขที่ตึงตัว`,
          `🚸❄️ [วิกฤตฤดูกาลและที่พักพิงชั่วคราว ณ เมือง${hostCityName}] องค์กรมนุษยธรรมรายงานสภาพความยากลำบากของครอบครัวผู้ลี้ภัย ${hostedK.toLocaleString()} พันคน ในเขตเมือง${hostCityName} ของ ${host.name} ที่ต้องเผชิญกับสภาพอากาศเลวร้ายและระบบสุขาภิบาลที่ล้มเหลว`,
          `🚸📦 [ค่ายผู้ลี้ภัยเมือง${hostCityName} เกินขีดความจุ!] จำนวนผู้พักพิงในเมือง${hostCityName} แห่ง ${host.name} พุ่งแตะ ${hostedK.toLocaleString()} พันคน เกินขีดความสามารถในการรองรับของเทศบาลเมือง ส่งผลให้เกิดความตึงเครียดด้านสาธารณูปโภคอย่างรุนแรง`
        ];
        addChronicle(world, 'MIGRATION', rng.pick(campTemplates), host.id, { cityId: hostCity ? hostCity.id : null });
      } else if ((host.migrationV230.xenophobia || 20) > 30 && rng.chance(0.18)) {
        // ANTI_REFUGEE_RIOT (host city unrest +8, localUnrest too + Link 7: push world.pendingRiots)
        if (hostCity) {
          hostCity.unrest = clamp(rnd1((hostCity.unrest || 15) + 8), 0, 100);
          hostCity.localUnrest = clamp(rnd1((hostCity.localUnrest || hostCity.unrest || 15) + 8), 0, 100);
          if (!world.pendingRiots) world.pendingRiots = {};
          world.pendingRiots[hostCity.id] = { tick: world.tick, deadline: world.tick + 20 };
          if (world.yearStats) world.yearStats.riots = (world.yearStats.riots || 0) + 1;
        }
        const riotTemplates = [
          `🚸🔥 [จลาจลต่อต้านผู้ลี้ภัยปะทุกลางเมือง${hostCityName}!] กลุ่มผู้ประท้วงชาตินิยมในเมือง${hostCityName} แห่ง ${host.name} ออกมาเดินขบวนขับไล่ผู้อพยพ (${hostedK.toLocaleString()} พันคน) และปะทะกับเจ้าหน้าที่ตำรวจ ส่งผลให้ระดับความไม่สงบของเมืองพุ่งขึ้น +8% (อยู่ที่ ${hostCity ? hostCity.unrest : 35}%) ท่ามกลางดัชนีความหวาดระแวงต่างชาติ ${Math.round(host.migrationV230.xenophobia)}/100`,
          `🚸🚨 [ม็อบปะทะเดือดหน้าศูนย์พักพิงเมือง${hostCityName} ของ ${shortNameTh(host)}!] ความตึงเครียดเรื่องการแย่งงานและงบสวัสดิการในเมือง${hostCityName} บานปลายเป็นการจลาจลต่อต้านผู้ลี้ภัย ${hostedK.toLocaleString()} พันคน ทำให้ค่าความไม่สงบในพื้นที่เพิ่มขึ้น +8 จุด`,
          `🚸📢 [ประท้วงเดือดต้านผู้อพยพที่เมือง${hostCityName}!] ชาวเมืองบางส่วนใน ${hostCityName} (${host.name}) รวมตัวปิดถนนประท้วงนโยบายรับผู้ลี้ภัยของรัฐบาล หลังยอดผู้พักพิงแตะ ${hostedK.toLocaleString()} พันคน จนผู้ว่าราชการเมืองต้องสั่งกำลังตำรวจควบคุมฝูงชนเข้าหย่าศึก`,
          `🚸💥 [เหตุปะทะระหว่างกลุ่มขวาจัดและผู้ลี้ภัยในเมือง${hostCityName}] ตำรวจปราบจลาจลแห่ง ${host.name} ต้องยิงแก๊สน้ำตาควบคุมสถานการณ์ในเมือง${hostCityName} หลังเกิดเหตุปะทะใกล้ชุมชนผู้ลี้ภัย ${hostedK.toLocaleString()} พันคน ส่งผลให้ Unrest ของเมืองขยับขึ้นสู่ ${hostCity ? hostCity.unrest : 35}%`,
          `🚸🛑 [วิกฤตความขัดแย้งทางสังคมในเมือง${hostCityName} แห่ง ${shortNameTh(host)}] กระแสต่อต้านคนต่างด้าว (${Math.round(host.migrationV230.xenophobia)}/100) จุดชนวนให้เกิดการชุมนุมรุนแรงในเมือง${hostCityName} เพื่อกดดันให้ส่งกลับผู้ลี้ภัย ${hostedK.toLocaleString()} พันคน`,
          `🚸⚡ [เมือง${hostCityName} ลุกเป็นไฟจากม็อบต้านผู้ลี้ภัย!] ความเหนื่อยล้าในการรองรับผู้อพยพ ${hostedK.toLocaleString()} พันคน ใน ${host.name} ปะทุเป็นการประท้วงใหญ่ที่เมือง${hostCityName} ดันดัชนีความไม่สงบภายในเมืองเพิ่มขึ้น +8% ทันที`
        ];
        addChronicle(world, 'MIGRATION', rng.pick(riotTemplates), host.id, { cityId: hostCity ? hostCity.id : null });
      } else if (rng.chance(0.18)) {
        // INTERNATIONAL_AID_CONFERENCE (3 richest allies/neighbours send treasuryB aid <= 0.1% of their treasury; relation +2)
        const donors = Object.values(world.states)
          .filter((s) => s && !s.isExiled && s.id !== host.id && (s.region === host.region || (s.relations?.[host.id]?.score ?? 50) >= 55))
          .sort((a, b) => (b.treasuryB || 0) - (a.treasuryB || 0))
          .slice(0, 3);
        let totalAidB = 0;
        donors.forEach((d) => {
          const aid = +(Math.max(0.2, Math.min((d.treasuryB || 50) * 0.001, 2.5))).toFixed(2);
          d.treasuryB = rnd1(Math.max(5, d.treasuryB - aid));
          host.treasuryB = rnd1(host.treasuryB + aid);
          totalAidB += aid;
          if (d.relations?.[host.id]) d.relations[host.id].score = clamp(rnd1(d.relations[host.id].score + 2), 0, 100);
          if (host.relations?.[d.id]) host.relations[d.id].score = clamp(rnd1(host.relations[d.id].score + 2), 0, 100);
        });
        if (donors.length > 0) {
          const donorNames = donors.map((d) => shortNameTh(d)).join(', ');
          const aidTemplates = [
            `🚸🤝 [การประชุมนานาชาติช่วยเหลือผู้ลี้ภัย ณ เมือง${hostCityName} — ระดมทุน $${totalAidB.toFixed(2)}B!] มิตรประเทศและชาติพันธมิตรได้แก่ ${donorNames} ร่วมจัดประชุมผู้บริจาคที่เมือง${hostCityName} เพื่อมอบเงินช่วยเหลือด้านมนุษยธรรมรวม $${totalAidB.toFixed(2)}B ให้แก่รัฐบาล ${host.name} สำหรับดูแลผู้ลี้ภัยกว่า ${hostedK.toLocaleString()} พันคน พร้อมยกระดับความสัมพันธ์ทวิภาคี +2 จุด`,
            `🚸🌐 [นานาชาติอัดฉีดงบบรรเทาทุกข์ $${totalAidB.toFixed(2)}B ช่วย ${shortNameTh(host)} รับมือคลื่นผู้อพยพ] คณะผู้แทนจาก ${donorNames} ลงนามมอบเงินสนับสนุนเข้าคงคลังของ ${host.name} จำนวน $${totalAidB.toFixed(2)}B เพื่อแบ่งเบาภาระการดูแลศูนย์พักพิงผู้ลี้ภัย ${hostedK.toLocaleString()} พันคน ในเขตเมือง${hostCityName}`,
            `🚸💵 [กองทุนมนุษยธรรมฉุกเฉิน $${totalAidB.toFixed(2)}B ส่งถึงเมือง${hostCityName}!] รัฐบาล ${host.name} ได้รับเงินบริจาคช่วยเหลือจาก ${donorNames} รวมมูลค่า $${totalAidB.toFixed(2)}B สำหรับจัดหาเวชภัณฑ์และอาหารแก่ผู้ลี้ภัย ${hostedK.toLocaleString()} พันคน`,
            `🚸🕊️ [พลังความร่วมมือข้ามพรมแดน: ${donorNames} ลงขัน $${totalAidB.toFixed(2)}B ช่วยผู้ลี้ภัยใน ${shortNameTh(host)}] ที่ประชุมนานาชาติ ณ เมือง${hostCityName} อนุมัติงบช่วยเหลือแบบให้เปล่า $${totalAidB.toFixed(2)}B แก่ ${host.name} ที่กำลังแบกรับผู้ลี้ภัย ${hostedK.toLocaleString()} พันคน`,
            `🚸🏛️ [ซัมมิตผู้บริจาคเพื่อมนุษยธรรมที่ ${hostCityName} ประสบผลสำเร็จ] ${donorNames} ส่งมอบความช่วยเหลือทางการคลังรวม $${totalAidB.toFixed(2)}B ให้แก่ ${host.name} เพื่อยกระดับคุณภาพชีวิตผู้อพยพ ${hostedK.toLocaleString()} พันคน และกระชับมิตรไมตรี (+2 ความสัมพันธ์)`,
            `🚸📦 [ขบวนความช่วยเหลือสากล $${totalAidB.toFixed(2)}B หนุนศูนย์พักพิงเมือง${hostCityName}] ชาติพันธมิตร (${donorNames}) โอนงบประมาณสนับสนุน $${totalAidB.toFixed(2)}B ให้แก่ ${host.name} เพื่อบรรเทาวิกฤตผู้ลี้ภัย ${hostedK.toLocaleString()} พันคน ในพื้นที่เมือง${hostCityName}`
          ];
          addChronicle(world, 'MIGRATION', rng.pick(aidTemplates), host.id, { cityId: hostCity ? hostCity.id : null });
        }
      }
    }
  }

  function runMigrationPolicyReviewV230(world, rng) {
    ensureWorldSystemsV230(world);
    recomputeHostMigrationTotalsV230(world);

    // 1. COLLAPSE check: if state's stability < 20 for the month -> flow 0.1% of its total popM
    Object.values(world.states).forEach((st) => {
      if (!st || st.isExiled) return;
      if ((st.stability || 70) < 20) {
        const cities = stateCities(world, st.id);
        const totalPop = cities.reduce((acc, c) => acc + (c.popM || 1), 0) || 5;
        const collapseFlowM = +(totalPop * 0.001).toFixed(3);
        createOrUpdateRefugeeFlowsV230(world, st, cities[0] || null, collapseFlowM, 'COLLAPSE', rng);
      }
    });

    // 2. Policy review & monthly effects per host
    Object.values(world.states).forEach((st) => {
      if (!st || st.isExiled || !st.migrationV230) return;
      const m = st.migrationV230;
      const cities = stateCities(world, st.id);
      const totalPopM = Math.max(1, cities.reduce((acc, c) => acc + (c.popM || 1), 0));
      const hostedM = m.hostedM || 0;
      const share = hostedM / totalPopM; // ratio (e.g. 0.03 = 3%)
      const sharePct = share * 100;

      if (hostedM > 0.0005 || st.treasuryB < 0) {
        const costB = hostedM * 0.06 * (1 - (m.integrationPct / 100) * 0.5);
        const gdpGainB = hostedM * (m.integrationPct / 100) * 0.8;
        const projectedTreasury = (st.treasuryB || 0) - costB;
        if (projectedTreasury < 0) {
          // Link 6: When treasuryB would fall below 0, route shortfall into sovereignDebt.totalDebtB and bondYieldPct += 0.05, clamp treasuryB at 0
          const shortfall = +(Math.abs(projectedTreasury)).toFixed(2);
          st.treasuryB = 0;
          if (st.sovereignDebt) {
            st.sovereignDebt.totalDebtB = +((st.sovereignDebt.totalDebtB || 100) + Math.max(0.1, shortfall)).toFixed(2);
            st.sovereignDebt.debtToGdpPct = +((st.sovereignDebt.totalDebtB / Math.max(50, st.gdpB)) * 100).toFixed(1);
            st.sovereignDebt.bondYieldPct = +(clamp((st.sovereignDebt.bondYieldPct || 3.5) + 0.05, 1.0, 48.0)).toFixed(2);
            if (st.sovereignDebt.debtToGdpPct >= 95 || st.sovereignDebt.bondYieldPct >= 9.0) {
              st.sovereignDebt.inDebtCrisis = true;
            }
          }
        } else {
          st.treasuryB = +(Math.max(0, projectedTreasury)).toFixed(2);
        }
        st.gdpB = rnd1(st.gdpB + gdpGainB);
      }
      // Link 6: Refugee host states with inDebtCrisis === true automatically move policy toward CLOSED
      if (st.sovereignDebt && st.sovereignDebt.inDebtCrisis === true && m.policy !== 'CLOSED') {
        setMigrationPolicyV230(world, st.id, m.policy === 'OPEN' ? 'QUOTA' : 'CLOSED');
      }

      if (m.policy === 'OPEN') m.integrationPct = clamp(+(m.integrationPct + 0.6).toFixed(2), 0, 85);
      else if (m.policy === 'QUOTA') m.integrationPct = clamp(+(m.integrationPct + 0.2).toFixed(2), 0, 85);
      else m.integrationPct = clamp(+(m.integrationPct - 0.3).toFixed(2), 5, 85);

      m.xenophobia = clamp(+(m.xenophobia + 0.15 * sharePct - m.integrationPct * 0.02).toFixed(2), 5, 100);
      if (sharePct > 0.3) {
        m.fatigue = clamp(+(m.fatigue + 0.5 * sharePct).toFixed(2), 0, 100);
      } else {
        m.fatigue = clamp(+(m.fatigue - 0.5).toFixed(2), 0, 100);
      }

      if (st.politicalPressures) {
        st.politicalPressures.oppositionStrength = clamp(rnd1((st.politicalPressures.oppositionStrength || 35) + 0.04 * (m.xenophobia / 10)), 5, 98);
      }

      // When xenophobia > 65 opposition gains 1-3 seats in parliament and story names fictional anti-immigration party
      if (m.xenophobia > 65 && st.parliament && rng.chance(0.45)) {
        const seatShift = rng.int(1, 3);
        st.parliament.oppositionSeats = clamp((st.parliament.oppositionSeats || 200) + seatShift, 10, 490);
        st.parliament.coalitionSeats = clamp(500 - st.parliament.oppositionSeats, 10, 490);
        const partyName = rng.pick(ANTI_IMMIGRATION_PARTIES_V230);
        const head = pickNegotiatorsV230(world, st.id).head;
        const headName = head ? head.name : shortNameTh(st);
        const surgeTemplates = [
          `🚸🗳️ [พรรคขวาจัดต้านผู้อพยพผงาดในสภา ${shortNameTh(st)}!] กระแสความหวาดระแวงต่างชาติใน ${st.name} ที่พุ่งสูงถึง ${Math.round(m.xenophobia)}/100 ส่งผลให้ "${partyName}" ชิงที่นั่งในรัฐสภาเพิ่มขึ้น +${seatShift} ที่นั่ง (ฝ่ายค้านเพิ่มเป็น ${st.parliament.oppositionSeats}/500 ที่นั่ง) กดดันรัฐบาลของ ${headName} ให้ทบทวนนโยบายพรมแดนทันที`,
          `🚸📈 ["${partyName}" กวาดคะแนนนิยมจากวิกฤตผู้ลี้ภัยใน ${shortNameTh(st)}!] ความไม่พอใจของประชาชนต่อภาระผู้ลี้ภัย (${hostedM.toFixed(3)} ล้านคน) หนุนให้ "${partyName}" ได้ที่นั่งในสภาเพิ่ม +${seatShift} ที่นั่ง เขย่าเสถียรภาพพรรคร่วมรัฐบาลของ ${headName}`,
          `🚸🏛️ [แผ่นดินไหวในรัฐสภา ${shortNameTh(st)}: พรรคต่อต้านผู้อพยพรุกคืบ +${seatShift} ที่นั่ง] "${partyName}" ใช้แคมเปญปิดตายพรมแดนดึงเสียงสนับสนุนใน ${st.name} จนฝ่ายค้านขยับขึ้นเป็น ${st.parliament.oppositionSeats} ที่นั่ง ท่ามกลางดัชนี Xenophobia ${Math.round(m.xenophobia)}/100`,
          `🚸📢 [กระแสชาตินิยมพุ่ง! "${partyName}" กดดันรัฐบาล ${headName} ในสภา ${shortNameTh(st)}] การเติบโตของ "${partyName}" ที่ชิงเก้าอี้สภาเพิ่ม +${seatShift} ที่นั่ง สะท้อนแรงต้านต่อผู้อพยพใน ${st.name} ที่กำลังเปลี่ยนขั้วการเมืองระดับชาติ`,
          `🚸⚡ [ฝ่ายค้านสายเหยี่ยวรุกหนัก! "${partyName}" เพิ่มเสียงในสภา ${shortNameTh(st)} +${seatShift} ที่นั่ง] รัฐสภาแห่ง ${st.name} ปั่นป่วนเมื่อ "${partyName}" เปิดอภิปรายโจมตีนโยบายผู้ลี้ภัยของ ${headName} พร้อมดึง ส.ส. ย้ายค่ายเพิ่มอีก ${seatShift} ที่นั่ง`,
          `🚸🔥 [การเมืองเรื่องพรมแดนเขย่า ${shortNameTh(st)}: "${partyName}" ผงาด +${seatShift} ที่นั่ง] ดัชนีต่อต้านต่างชาติที่ระดับ ${Math.round(m.xenophobia)}/100 ทำให้ "${partyName}" กลายเป็นตัวแปรสำคัญในสภา (${st.parliament.oppositionSeats}/500 ที่นั่ง) บีบรัฐบาล ${headName} อย่างหนัก`
        ];
        addChronicle(world, 'MIGRATION', rng.pick(surgeTemplates), st.id);
      }

      // Policy threshold review tilted by +-10 from head personality (integrity, caution)
      if (world.aiSandbox !== false) {
        const head = pickNegotiatorsV230(world, st.id).head;
        const tilt = ((head?.personality?.integrity ?? 50) - (head?.personality?.caution ?? 50)) / 10; // -10 .. +10
        const headIdeo = String(head?.ideology || head?.personality?.ideology || '');
        if (sharePct > 6 && m.xenophobia > (70 + tilt) && m.policy !== 'CLOSED') {
          setMigrationPolicyV230(world, st.id, 'CLOSED');
        } else if (sharePct > 3 && m.fatigue > (60 + tilt) && m.policy === 'OPEN') {
          setMigrationPolicyV230(world, st.id, 'QUOTA');
        } else if (sharePct < 1.5 && m.xenophobia < (35 + tilt) && /Welfare|Reformist|Technocrat/i.test(headIdeo) && m.policy !== 'OPEN') {
          setMigrationPolicyV230(world, st.id, 'OPEN');
        }
      }
    });

    // 3. Skilled migration: monthly 10% chance for each of the top-10 gdpB states with policy OPEN
    const top10Open = Object.values(world.states)
      .filter((s) => s && !s.isExiled)
      .sort((a, b) => (b.gdpB || 0) - (a.gdpB || 0))
      .slice(0, 10)
      .filter((s) => s.migrationV230?.policy === 'OPEN');

    const poorerPool = Object.values(world.states)
      .filter((s) => s && !s.isExiled)
      .sort((a, b) => (a.gdpB || 0) - (b.gdpB || 0))
      .slice(0, 25);

    top10Open.forEach((host) => {
      if (rng.chance(0.18)) {
        const originCandidates = poorerPool.filter((o) => o.id !== host.id && (o.region === host.region || true));
        const origin = rng.pick(originCandidates);
        if (origin) {
          host.educationIndex = clamp(+((host.educationIndex || 80) + 0.1).toFixed(2), 10, 100);
          origin.educationIndex = clamp(+((origin.educationIndex || 70) - 0.05).toFixed(2), 10, 100);
          const hostCity = stateCities(world, host.id)[0];
          const hostCityName = hostCity ? cityNameTh(hostCity) : shortNameTh(host);
          const talentCount = rng.int(12, 45);
          const skilledTemplates = [
            `🚸🎓 [คลื่นสมองไหลข้ามพรมแดน! วิศวกรและนักวิจัยจาก ${shortNameTh(origin)} กว่า ${talentCount} พันคน ย้ายถิ่นสู่ ${shortNameTh(host)}] นโยบายเปิดพรมแดน (OPEN) และค่าตอบแทนที่จูงใจของมหานคร${hostCityName} ใน ${host.name} ดึงดูดบุคลากรทักษะสูงจาก ${origin.name} กว่า ${talentCount} พันคน ส่งผลให้ดัชนีการศึกษาของ ${shortNameTh(host)} ขยับขึ้นเป็น ${host.educationIndex} ขณะที่ ${shortNameTh(origin)} เผชิญภาวะสมองไหล (เหลือ ${origin.educationIndex})`,
            `🚸🔬 [ดึงดูดหัวกะทิระดับโลก! ${shortNameTh(host)} รับแรงงานไฮเทค ${talentCount} พันคน จาก ${shortNameTh(origin)}] ศูนย์วิจัยและบริษัทเทคโนโลยีในเมือง${hostCityName} (${host.name}) เปิดรับวิศวกร AI และแพทย์จาก ${origin.name} จำนวน ${talentCount} พันคน ดันดัชนีทุนมนุษย์ของ ${shortNameTh(host)} เพิ่มขึ้น +0.1 จุด`,
            `🚸💻 [วิกฤตสมองไหลใน ${shortNameTh(origin)}! คนรุ่นใหม่ทักษะสูง ${talentCount} พันคน มุ่งหน้าสู่เมือง${hostCityName}] ความก้าวหน้าทางเศรษฐกิจของ ${host.name} ดึงดูดผู้เชี่ยวชาญจาก ${origin.name} กว่า ${talentCount} พันคน ให้ย้ายถิ่นฐานเข้าสู่เมือง${hostCityName} เสริมศักยภาพการแข่งขันของ ${shortNameTh(host)}`,
            `🚸🌐 [วีซ่าทักษะพิเศษของ ${shortNameTh(host)} กวาดนักวิทยาศาสตร์ ${shortNameTh(origin)} ${talentCount} พันคน] รัฐบาล ${host.name} ประสบความสำเร็จในการดึงดูดแรงงานทักษะสูงจาก ${origin.name} เข้าสู่อุตสาหกรรมยุทธศาสตร์ในเมือง${hostCityName} (Education Index: ${host.educationIndex})`,
            `🚸📈 [ย้ายถิ่นฐานสายเทคโนโลยี: บุคลากรชั้นนำ ${talentCount} พันคน จาก ${shortNameTh(origin)} ตั้งรกรากใน ${hostCityName}] นโยบายพรมแดนเสรีของ ${host.name} ช่วยเติมเต็มแรงงานวิจัยจาก ${origin.name} จำนวน ${talentCount} พันคน ท่ามกลางความกังวลเรื่องการสูญเสียบุคลากรหลักของรัฐบาล ${shortNameTh(origin)}`,
            `🚸🏛️ [มหานคร${hostCityName} กลายเป็นแม่เหล็กดึงดูดหัวกะทิจาก ${shortNameTh(origin)}] รายงานประชากรศาสตร์ระบุว่าผู้เชี่ยวชาญกว่า ${talentCount} พันคน จาก ${origin.name} ได้รับสิทธิพำนักถาวรใน ${host.name} ส่งผลบวกต่อดัชนีการศึกษาและนวัตกรรมแห่งชาติทันที`
          ];
          addChronicle(world, 'MIGRATION', rng.pick(skilledTemplates), host.id, { secondStateId: origin.id, cityId: hostCity ? hostCity.id : null });
        }
      }
    });
  }

