  function ensureDisastersV240(world) {
    if (!world) return;
    if (!world.disasterV240 || typeof world.disasterV240 !== 'object') {
      world.disasterV240 = { nextId: 1, active: [], archive: [] };
    }
    if (typeof world.disasterV240.nextId !== 'number') world.disasterV240.nextId = 1;
    if (!Array.isArray(world.disasterV240.active)) world.disasterV240.active = [];
    if (!Array.isArray(world.disasterV240.archive)) world.disasterV240.archive = [];
    if (!world._oppV240 || typeof world._oppV240 !== 'object') world._oppV240 = {};
  }

  function getRegionalDisasterLabelV240(world, typeObj, state, city, rng) {
    if (!typeObj) return 'ภัยพิบัติรุนแรง';
    if (typeObj.id === 'STORM') {
      const reg = state ? state.region : '';
      if (['Japan', 'EastAsia', 'SoutheastAsia', 'Thailand'].includes(reg)) return 'พายุไต้ฝุ่นกำลังแรง';
      if (['NorthAmerica', 'LatinAmerica'].includes(reg)) return 'พายุเฮอริเคนระดับรุนแรง';
      if (['IndoPacific', 'Oceania'].includes(reg)) return 'พายุไซโคลนกำลังแรง';
      return 'พายุหมุนเขตร้อนกำลังแรง';
    }
    if (typeObj.id === 'INDUSTRIAL_CATASTROPHE') {
      const hasNuke = state && state.nuclear && (state.nuclear.warheads > 0 || state.nuclear.programStage >= 2);
      const arch = city ? (city.archetype || city.specialty || '') : '';
      const pool = ['อุบัติเหตุโรงงานเคมีระเบิดและสารพิษรั่วไหล', 'เขื่อนกักเก็บน้ำและระบบกั้นน้ำพังทลาย', 'เพลิงไหม้โรงกลั่นน้ำมันและคลังพลังงาน'];
      if (hasNuke) pool.push('อุบัติเหตุระบบหล่อเย็นโรงไฟฟ้านิวเคลียร์รั่วไหล');
      if (/Energy/i.test(arch)) return 'เพลิงไหม้โรงกลั่นน้ำมันและคลังพลังงาน';
      if (/Industrial/i.test(arch)) return 'อุบัติเหตุโรงงานเคมีระเบิดและสารพิษรั่วไหล';
      return rng ? rng.pick(pool) : pool[0];
    }
    return typeObj.labelTh;
  }

  function pickSeverityV240(rng) {
    const u = rng.next();
    if (u < 0.35) return 1;
    if (u < 0.65) return 2;
    if (u < 0.85) return 3;
    if (u < 0.96) return 4;
    return 5;
  }

  function pickCitiesForDisasterV240(world, state, typeObj, severity, rng) {
    const cities = stateCities(world, state.id);
    if (!cities || cities.length === 0) return [];
    let sorted = cities.slice();
    const picker = typeObj ? typeObj.cityPicker : 'hazard';
    if (picker === 'coastal') {
      sorted.sort((a, b) => ((b.port || 0) + (b.terrain === 'coastal' ? 3 : 0)) - ((a.port || 0) + (a.terrain === 'coastal' ? 3 : 0)));
    } else if (picker === 'agriculture') {
      sorted.sort((a, b) => (b.agriculture || 50) - (a.agriculture || 50));
    } else if (picker === 'epidemic') {
      sorted.sort((a, b) => ((b.popM || 1) * 2 + (b.airport || 0)) - ((a.popM || 1) * 2 + (a.airport || 0)));
    } else if (picker === 'industrial') {
      sorted.sort((a, b) => ((b.industry || 50) + (b.energy || 50)) - ((a.industry || 50) + (a.energy || 50)));
    } else {
      // hazard: any city of the state
      sorted = cities.slice();
    }
    const topPool = sorted.slice(0, Math.max(1, Math.min(3, sorted.length)));
    const primary = rng.pick(topPool) || cities[0];
    const selected = [primary];

    if (severity >= 4 && cities.length > 1) {
      const targetCount = Math.min(cities.length, severity === 5 ? rng.int(3, 4) : rng.int(2, 3));
      const connIds = Array.isArray(primary.connectedCityIds) ? primary.connectedCityIds : [];
      for (let i = 0; i < connIds.length && selected.length < targetCount; i++) {
        const nc = world.cities[connIds[i]];
        if (nc && nc.stateId === state.id && !selected.some((x) => x.id === nc.id)) {
          selected.push(nc);
        }
      }
      // If still fewer than targetCount, pick nearest cities in same state
      if (selected.length < targetCount) {
        const rest = cities
          .filter((c) => !selected.some((x) => x.id === c.id))
          .sort((a, b) => Math.hypot((a.x || 0) - (primary.x || 0), (a.y || 0) - (primary.y || 0)) - Math.hypot((b.x || 0) - (primary.x || 0), (b.y || 0) - (primary.y || 0)));
        for (let i = 0; i < rest.length && selected.length < targetCount; i++) {
          selected.push(rest[i]);
        }
      }
    }
    return selected;
  }

  function getNpcSkillV240(npc, field) {
    if (!npc) return 55;
    if (typeof npc[field] === 'number' && !Number.isNaN(npc[field])) return npc[field];
    if (typeof npc.intelligence === 'number' && !Number.isNaN(npc.intelligence)) return npc.intelligence;
    return 58;
  }

  function responseScoreV240(world, stOrId, disasterOpt = null) {
    const st = typeof stOrId === 'string' ? (world && world.states ? world.states[stOrId] : null) : stOrId;
    if (!st) return 50;
    const pos = st.positions || {};
    const head = (pos.HEAD_OF_STATE && world.npcs && world.npcs[pos.HEAD_OF_STATE]) || (pos.PRIME_MINISTER && world.npcs && world.npcs[pos.PRIME_MINISTER]) || null;
    const interior = (pos.INTERIOR_MINISTER && world.npcs && world.npcs[pos.INTERIOR_MINISTER]) || head;
    const dis = disasterOpt || (world.disasterV240 && (world.disasterV240.active || []).find((d) => d.stateId === st.id)) || null;
    let worstCity = null;
    if (dis && Array.isArray(dis.cityIds) && dis.cityIds.length > 0) {
      worstCity = dis.cityIds.map((cid) => world.cities && world.cities[cid]).filter(Boolean).sort((a, b) => (b.popM || 1) - (a.popM || 1))[0] || null;
    }
    if (!worstCity) {
      worstCity = stateCities(world, st.id)[0] || null;
    }
    const gov = (worstCity && worstCity.governorId && world.npcs && world.npcs[worstCity.governorId]) || head;
    const damageB = Math.max(0.5, dis ? (dis.damageB || 5) : (st.gdpB * 0.01));

    const compInterior = getNpcSkillV240(interior, 'competence');
    const adminHead = getNpcSkillV240(head, 'administrativeAbility');
    const fiscalTerm = clamp((Math.max(0, st.treasuryB || 0) / (damageB * 4)) * 100, 0, 100);
    const compGov = getNpcSkillV240(gov, 'competence');

    const score = 0.35 * compInterior + 0.25 * adminHead + 0.20 * fiscalTerm + 0.20 * compGov;
    return +(clamp(score, 0, 100)).toFixed(1);
  }

  function getResponseLabelV240(score) {
    if (score >= 75) return 'ตอบสนองได้อย่างรวดเร็วและโปร่งใส';
    if (score >= 55) return 'ตอบสนองได้ตามมาตรฐาน';
    if (score >= 40) return 'ล่าช้าและขาดการประสานงาน';
    return 'ล้มเหลวอย่างรุนแรง';
  }

  function formatDisasterTemplateV240(tpl, ctx) {
    return String(tpl || '').replace(/\{(\w+)\}/g, (_, k) => (ctx[k] !== undefined ? ctx[k] : ''));
  }

  function spawnDisasterV240(world, stateId = null, typeId = null, severity = null, rngInstance = null) {
    if (!world || !world.states) return { ok: false, reason: 'ไม่พบข้อมูลโลก' };
    ensureDisastersV240(world);
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + (world.tick || 1) * 4099 + (world.disasterV240.nextId || 1) * 131);

    // If a state or world has COMPLETE disasters waiting only for anniversary and manual/new spawn needs space, archive COMPLETE ones first
    if (stateId) {
      const existingIdx = world.disasterV240.active.findIndex((d) => d.stateId === stateId);
      if (existingIdx >= 0) {
        const ex = world.disasterV240.active[existingIdx];
        if (ex.phase === 'COMPLETE') {
          world.disasterV240.active.splice(existingIdx, 1);
          world.disasterV240.archive.unshift(ex);
          if (world.disasterV240.archive.length > 40) world.disasterV240.archive.length = 40;
        } else {
          return { ok: false, reason: 'รัฐนี้มีภัยพิบัติที่กำลังดำเนินอยู่แล้ว' };
        }
      }
    }

    if (world.disasterV240.active.length >= 6) {
      // Check if any COMPLETE disaster can be moved to archive to make room
      const compIdx = world.disasterV240.active.findIndex((d) => d.phase === 'COMPLETE');
      if (compIdx >= 0) {
        const comp = world.disasterV240.active.splice(compIdx, 1)[0];
        world.disasterV240.archive.unshift(comp);
        if (world.disasterV240.archive.length > 40) world.disasterV240.archive.length = 40;
      } else {
        return { ok: false, reason: 'มีภัยพิบัติที่กำลังดำเนินอยู่ครบเพดาน 6 แห่งทั่วโลกแล้ว' };
      }
    }

    // Pick typeId & stateId if not provided
    let typeObj = typeId ? DISASTER_TYPES_V240.find((t) => t.id === typeId) : null;
    if (!typeObj) {
      typeObj = rng.pick(DISASTER_TYPES_V240);
    }

    let st = stateId ? world.states[stateId] : null;
    if (!st || st.isExiled) {
      const activeStateIds = new Set(world.disasterV240.active.map((d) => d.stateId));
      const candidates = Object.values(world.states).filter((s) => !s.isExiled && !activeStateIds.has(s.id) && stateCities(world, s.id).length > 0);
      if (candidates.length === 0) return { ok: false, reason: 'ไม่มีรัฐที่พร้อมสำหรับสร้างภัยพิบัติใหม่' };
      // Weighted pick by regionWeights / popM / gdpB
      let totalW = 0;
      const weights = candidates.map((s) => {
        let w = (typeObj.regionWeights && typeObj.regionWeights[s.region] !== undefined) ? typeObj.regionWeights[s.region] : 0.5;
        if (typeObj.id === 'EPIDEMIC') {
          const maxPop = Math.max(1, ...stateCities(world, s.id).map((c) => c.popM || 1));
          w = Math.max(0.5, maxPop * 0.4);
        } else if (typeObj.id === 'INDUSTRIAL_CATASTROPHE') {
          w = Math.max(0.5, Math.min(6, (s.gdpB || 100) / 300));
        }
        totalW += w;
        return w;
      });
      let roll = rng.next() * totalW;
      st = candidates[0];
      for (let i = 0; i < candidates.length; i++) {
        roll -= weights[i];
        if (roll <= 0) {
          st = candidates[i];
          break;
        }
      }
    }

    const sev = clamp(Math.round(severity || pickSeverityV240(rng)), 1, 5);
    const affectedCities = pickCitiesForDisasterV240(world, st, typeObj, sev, rng);
    if (affectedCities.length === 0) return { ok: false, reason: 'รัฐนี้ไม่มีเมืองที่สามารถเกิดภัยพิบัติได้' };

    const primaryCity = affectedCities[0];
    const regionalLabelTh = getRegionalDisasterLabelV240(world, typeObj, st, primaryCity, rng);
    const sevLabelTh = typeObj.severityLabelsTh[sev - 1] || DISASTER_SEVERITY_LABELS_TH_V240[sev - 1];

    const deadFrac = typeObj.baseDeadFrac[sev - 1];
    const homelessFrac = [0.002, 0.01, 0.04, 0.10, 0.22][sev - 1];
    const infraHitPct = [3, 8, 16, 28, 45][sev - 1];
    const econHitPct = [2, 6, 12, 20, 32][sev - 1];
    const safetyHit = [2, 4, 8, 12, 18][sev - 1];
    const unrestAdd = [2, 5, 9, 14, 20][sev - 1];
    const sectorHitPct = [4, 9, 15, 24, 35][sev - 1];

    let totalDead = 0;
    let totalInjured = 0;
    let totalHomelessM = 0;

    affectedCities.forEach((city) => {
      if (!city._preDisasterV240) {
        city._preDisasterV240 = {
          infrastructure: city.infrastructure || 75,
          economy: city.economy || 75,
          industry: city.industry ?? 80,
          commerce: city.commerce ?? 80,
          agriculture: city.agriculture ?? 75,
          energy: city.energy ?? 75,
          port: city.port,
          rail: city.rail,
          foodStorage: city.foodStorage ?? 5000
        };
      }
      const multRng = 0.6 + rng.next() * 0.8; // rng(0.6, 1.4)
      const infraVal = clamp(city.infrastructure || 75, 10, 140);
      const cDead = Math.max(1, Math.round((city.popM || 1) * 1e6 * deadFrac * (1 - infraVal / 150) * multRng));
      const cInjured = Math.round(3.5 * cDead);
      const cHomelessM = +((city.popM || 1) * homelessFrac).toFixed(4);

      totalDead += cDead;
      totalInjured += cInjured;
      totalHomelessM = +(totalHomelessM + cHomelessM).toFixed(4);

      // Reduce city.popM by dead only (in millions)
      city.popM = Math.max(0.01, +((city.popM || 1) - cDead / 1e6).toFixed(6));
      city.infrastructure = Math.max(15, +((city.infrastructure || 75) * (1 - infraHitPct / 100)).toFixed(2));
      city.economy = Math.max(15, +((city.economy || 75) * (1 - econHitPct / 100)).toFixed(2));
      city.safety = clamp(Math.round((city.safety || 80) - safetyHit), 10, 100);
      city.unrest = clamp(Math.round((city.unrest || 10) + unrestAdd), 0, 100);
      city.stability = clamp(Math.round((city.stability || 80) - unrestAdd), 5, 100);

      // Addendum Link 2: Damage supply network & governance city fields (industry, commerce, agriculture, energy, port/rail, foodStorage)
      city._disasterDownV240 = rng.int(12, 38);
      city.industry = Math.max(15, +((city.industry ?? 80) * (1 - sectorHitPct / 100)).toFixed(2));
      city.commerce = Math.max(15, +((city.commerce ?? 80) * (1 - sectorHitPct / 100)).toFixed(2));
      city.agriculture = Math.max(15, +((city.agriculture ?? 75) * (1 - sectorHitPct / 100)).toFixed(2));
      city.energy = Math.max(15, +((city.energy ?? 75) * (1 - sectorHitPct / 100)).toFixed(2));

      if (typeObj.id === 'DROUGHT_FAMINE') {
        city.agriculture = Math.max(10, +(city.agriculture * 0.78).toFixed(2));
        city.foodStorage = Math.max(200, Math.round((city.foodStorage || 4000) * (1 - 0.12 * sev)));
      } else if (typeObj.id === 'INDUSTRIAL_CATASTROPHE') {
        city.industry = Math.max(10, +(city.industry * 0.75).toFixed(2));
        city.energy = Math.max(10, +(city.energy * 0.75).toFixed(2));
      } else if (typeObj.id === 'STORM' || typeObj.id === 'FLOOD') {
        city.portDisruptedV240 = true;
        city.railDisruptedV240 = true;
        if (typeof city.port === 'boolean') city.port = false;
        else if (typeof city.port === 'number') city.port = Math.max(0, city.port - Math.min(2, sev));
        if (typeof city.rail === 'boolean') city.rail = false;
        else if (typeof city.rail === 'number') city.rail = Math.max(1, city.rail - Math.min(2, sev));
      }
    });

    // State damageB formula
    const baseDmgPct = typeObj.baseDamagePctGDP[sev - 1];
    let dmgMult = 1.0;
    if (typeObj.id === 'DROUGHT_FAMINE') {
      dmgMult = 0.4;
    } else if (typeObj.id === 'INDUSTRIAL_CATASTROPHE') {
      const preInd = primaryCity._preDisasterV240 ? primaryCity._preDisasterV240.industry : (primaryCity.industry || 80);
      if (preInd >= 70 || /Industrial|Energy|Aerospace/i.test(primaryCity.archetype || primaryCity.specialty || '')) {
        dmgMult = 2.0;
      }
    }
    const damageB = Math.max(0.1, +((st.gdpB || 50) * (baseDmgPct / 100) * dmgMult).toFixed(2));
    st.gdpB = rnd1(Math.max(5, (st.gdpB || 50) - damageB * 0.5));
    st.stability = rnd1(clamp((st.stability || 70) - [0.5, 1.2, 2.5, 4.5, 8][sev - 1], 3, 99));
    st.approval = rnd1(clamp((st.approval || 65) - [0.5, 1, 2, 3.5, 6][sev - 1], 3, 99));

    // Addendum Link 1: Disaster financing via setCentralBankPolicyV210('issue_bonds'), bondYieldPct +0.4 for sev>=4, recomputeCreditRatingV210, and qe_stimulus for sev 5 low independence
    ensureGlobalFinanceAndCurrencyV210(world);
    if ((st.treasuryB || 0) < 0.15 * damageB) {
      const borrowB = Math.max(8, +(Math.max(0.15 * damageB - Math.max(0, st.treasuryB || 0), damageB * 0.35)).toFixed(1));
      setCentralBankPolicyV210(world, st.id, 'issue_bonds', borrowB);
    }
    if (st.treasuryB < 0) st.treasuryB = 0;

    if (sev >= 4 && st.sovereignDebt) {
      st.sovereignDebt.bondYieldPct = +(clamp((st.sovereignDebt.bondYieldPct || 3.5) + 0.4, 1.0, 45.0)).toFixed(2);
      st._disasterBondYieldAddV240 = +((st._disasterBondYieldAddV240 || 0) + 0.4).toFixed(2);
      recomputeCreditRatingV210(st);
    }
    if (sev === 5 && st.centralBank && (st.centralBank.independence ?? 70) < 40 && rng.chance(0.40)) {
      setCentralBankPolicyV210(world, st.id, 'qe_stimulus', Math.max(12, +(damageB * 0.3).toFixed(1)));
    }

    // Addendum Link 6: Research institutes slow-down for severity >= 4
    if (sev >= 4 && world.researchInstitutes) {
      Object.values(world.researchInstitutes).forEach((inst) => {
        if (inst && inst.stateId === st.id) {
          inst.researchSlowMonths = (inst.researchSlowMonths || 0) + (sev === 5 ? 4 : 2);
        }
      });
    }

    const pos = st.positions || {};
    const headNpc = (pos.HEAD_OF_STATE && world.npcs[pos.HEAD_OF_STATE]) || (pos.PRIME_MINISTER && world.npcs[pos.PRIME_MINISTER]) || null;
    const minNpc = (pos.INTERIOR_MINISTER && world.npcs[pos.INTERIOR_MINISTER]) || headNpc;
    const govNpc = (primaryCity.governorId && world.npcs[primaryCity.governorId]) || minNpc;

    const initScore = responseScoreV240(world, st, { cityIds: affectedCities.map((c) => c.id), damageB });
    const initLabel = getResponseLabelV240(initScore);

    let epidemicObj = null;
    if (typeObj.id === 'EPIDEMIC') {
      const startInfM = +(Math.max(0.004, Math.min((primaryCity.popM || 1) * 0.015, 0.08))).toFixed(4);
      epidemicObj = {
        phase: 'OUTBREAK',
        originStateId: st.id,
        lethalityPct: +(0.2 + rng.next() * 1.8).toFixed(2),
        contagion: +(0.3 + rng.next() * 0.9).toFixed(2),
        infectedM: { [st.id]: startInfM },
        deadTotal: totalDead,
        borderClosedBy: [],
        vaccineProgress: 0,
        vaccineBy: null,
        noGrowthSteps: 0,
        peakTick: null
      };
    }

    const dId = `DIS_${world.year || 2026}_${world.disasterV240.nextId++}`;
    const dObj = {
      id: dId,
      typeId: typeObj.id,
      labelTh: regionalLabelTh,
      icon: typeObj.icon,
      stateId: st.id,
      severity: sev,
      severityLabelTh: sevLabelTh,
      cityIds: affectedCities.map((c) => c.id),
      startTick: world.tick || 0,
      phase: 'IMPACT',
      phaseDay: 0,
      phasesVisited: ['IMPACT'],
      casualties: {
        dead: totalDead,
        injured: totalInjured,
        homelessM: totalHomelessM
      },
      damageB,
      aidReceivedB: 0,
      aidOffers: [],
      responseScore: initScore,
      responseLabel: initLabel,
      blame: {
        npcId: (govNpc && govNpc.id) || (minNpc && minNpc.id) || null,
        role: (govNpc && primaryCity.governorId === govNpc.id) ? 'CITY_GOVERNOR' : 'INTERIOR_MINISTER'
      },
      epidemic: epidemicObj,
      log: [],
      anniversaryDone: false,
      _govEval3Done: false,
      _govEval14Done: false,
      _intlAidDone: false,
      _reliefSlicesPaid: 0,
      _milPenaltyApplied: 0
    };

    const leaderName = headNpc ? headNpc.name : `ผู้นำแห่ง ${shortNameTh(st)}`;
    const tplPool = DISASTER_IMPACT_TEMPLATES_V240[typeObj.id] || DISASTER_IMPACT_TEMPLATES_V240.EARTHQUAKE;
    const impactText = formatDisasterTemplateV240(rng.pick(tplPool), {
      typeLabel: regionalLabelTh,
      sevLabel: sevLabelTh,
      city: cityNameTh(primaryCity),
      state: shortNameTh(st),
      dead: totalDead.toLocaleString(),
      injured: totalInjured.toLocaleString(),
      homelessK: Math.max(1, Math.round(totalHomelessM * 1000)).toLocaleString(),
      damageB: damageB.toFixed(2),
      leader: leaderName
    });

    dObj.log.unshift({ tick: world.tick || 0, text: impactText });
    world.disasterV240.active.unshift(dObj);

    if (world.yearStats && typeof world.yearStats.disasters === 'number') {
      world.yearStats.disasters++;
    }
    world._v240Handled = true;

    addChronicle(world, 'DISASTER', impactText, st.id, {
      cityId: primaryCity.id,
      personId: headNpc ? headNpc.id : (govNpc ? govNpc.id : null),
      disasterId: dId
    });

    if (headNpc) recordNPCMemory(headNpc, world.year, `บัญชาการรับมือ${regionalLabelTh} (${sevLabelTh}) ที่เมือง ${cityNameTh(primaryCity)}`);
    if (govNpc && (!headNpc || govNpc.id !== headNpc.id)) {
      recordNPCMemory(govNpc, world.year, `เผชิญวิกฤต${regionalLabelTh}ในพื้นที่รับผิดชอบเมือง ${cityNameTh(primaryCity)}`);
    }

    // Hook to v2.3.0 refugee system directly (T4.1)
    if (typeof onDisasterV230 === 'function') {
      onDisasterV230(world, st.id, {
        type: typeObj.id,
        severity: sev >= 4 ? 'HIGH' : sev >= 2 ? 'MEDIUM' : 'LOW',
        displacedM: totalHomelessM,
        preserveCityPop: true
      });
    }

    return { ok: true, id: dId, disaster: dObj };
  }

  function evaluateDisasterGovResponseV240(world, d, rng, isSecondEval = false) {
    const st = world.states[d.stateId];
    if (!st) return;
    const score = responseScoreV240(world, st, d);
    const label = getResponseLabelV240(score);
    d.responseScore = score;
    d.responseLabel = label;

    // Political effects: approval += (score - 55) * 0.12
    const deltaApp = (score - 55) * 0.12;
    st.approval = rnd1(clamp((st.approval || 65) + deltaApp, 3, 99));

    const pos = st.positions || {};
    const head = (pos.HEAD_OF_STATE && world.npcs[pos.HEAD_OF_STATE]) || (pos.PRIME_MINISTER && world.npcs[pos.PRIME_MINISTER]) || null;
    const minister = (pos.INTERIOR_MINISTER && world.npcs[pos.INTERIOR_MINISTER]) || head;
    const primaryCity = d.cityIds && d.cityIds[0] ? world.cities[d.cityIds[0]] : stateCities(world, st.id)[0];
    const governor = (primaryCity && primaryCity.governorId && world.npcs[primaryCity.governorId]) || minister;

    const bucket = score >= 75 ? 'RAPID' : score >= 55 ? 'STANDARD' : score >= 40 ? 'DELAYED' : 'FAILED';
    const tpl = rng.pick(DISASTER_GOV_RESPONSE_TEMPLATES_V240[bucket]);
    const txt = formatDisasterTemplateV240(tpl, {
      typeLabel: d.labelTh,
      city: primaryCity ? cityNameTh(primaryCity) : shortNameTh(st),
      state: shortNameTh(st),
      minister: minister ? minister.name : 'รัฐมนตรีมหาดไทย',
      governor: governor ? governor.name : 'ผู้ว่าราชการเมือง',
      score: score.toFixed(1),
      label,
      damageB: d.damageB.toFixed(2),
      dead: d.casualties.dead.toLocaleString(),
      homelessK: Math.max(1, Math.round(d.casualties.homelessM * 1000)).toLocaleString()
    });

    d.log.unshift({ tick: world.tick, text: txt });
    if (d.log.length > 12) d.log.length = 12;
    addChronicle(world, 'DISASTER', txt, st.id, {
      cityId: primaryCity ? primaryCity.id : null,
      personId: minister ? minister.id : (governor ? governor.id : null),
      disasterId: d.id
    });

    if (score < 40) {
      if (!st.democracyState) st.democracyState = { activeScandal: null, strikeLevel: 0, coalitionStability: 70, nextElectionYear: (world.year || 2026) + 2 };
      st.democracyState.strikeLevel = Math.min(5, (st.democracyState.strikeLevel || 0) + 1);
      if (st.politicalPressures) {
        st.politicalPressures.publicUnrest = clamp(rnd1((st.politicalPressures.publicUnrest || 25) + 5), 0, 100);
      }
      if (['Authoritarian', 'One_Party', 'Military_Junta', 'Constitutional_Monarchy'].includes(st.regimeCategory)) {
        [pos.SUPREME_COMMANDER, pos.ARMY_CHIEF, pos.INTELLIGENCE_CHIEF, pos.DEFENSE_MINISTER].forEach((nid) => {
          const n = nid && world.npcs[nid];
          if (n && n.alive) n.coupReadiness = clamp((n.coupReadiness || 20) + 4, 0, 100);
        });
      }
      if (rng.chance(0.50) && typeof spawnScandalV240 === 'function') {
        const culprit = governor || minister || head;
        spawnScandalV240(world, st.id, 'DISASTER_NEGLIGENCE', {
          disasterId: d.id,
          culpritId: culprit ? culprit.id : null
        });
      }
    } else if (score >= 75 && st.regimeCategory === 'Democracy' && primaryCity && primaryCity.regionalPolitics && primaryCity.regionalPolitics.regionalParliament) {
      const rp = primaryCity.regionalPolitics.regionalParliament;
      rp.localSupportPct = clamp((rp.localSupportPct || 60) + 3, 10, 99);
    }
  }

  function evaluateDisasterInternationalAidV240(world, d, rng) {
    const victim = world.states[d.stateId];
    if (!victim) return;
    const primaryCity = d.cityIds && d.cityIds[0] ? world.cities[d.cityIds[0]] : stateCities(world, victim.id)[0];
    const head = (victim.positions?.HEAD_OF_STATE && world.npcs[victim.positions.HEAD_OF_STATE]) || (victim.positions?.PRIME_MINISTER && world.npcs[victim.positions.PRIME_MINISTER]) || null;

    const willingStates = [];
    const allStates = Object.values(world.states);
    for (let i = 0; i < allStates.length; i++) {
      const o = allStates[i];
      if (!o || o.isExiled || o.id === victim.id || (o.treasuryB || 0) < 15) continue;
      const rel = relOf(world, o.id, victim.id);
      const isAlly = rel.status === 'Alliance' || alliesOf(world, victim.id).includes(o.id);
      const sameReg = o.region === victim.region;
      const isHostile = rel.status === 'Hostile' || (rel.score || 50) < 35;
      let isDisasterDip = false;
      if (rel.score >= 55 || isAlly || sameReg) {
        willingStates.push({ state: o, relScore: rel.score || 50, isHostile: false, isDisasterDip: false });
      } else if (isHostile && rng.chance(0.08)) {
        isDisasterDip = true;
        willingStates.push({ state: o, relScore: rel.score || 30, isHostile: true, isDisasterDip: true });
      }
    }

    willingStates.sort((a, b) => b.relScore - a.relScore);
    const donors = willingStates.slice(0, 6);
    if (donors.length === 0) return;

    const prideScore = head && head.personality ? ((head.personality.integrity || 50) + (head.personality.ambition || 50)) : 100;

    donors.forEach((entry) => {
      const donor = entry.state;
      const rawOffer = Math.min(0.002 * Math.max(0, donor.treasuryB || 0), (0.15 * d.damageB) / Math.max(1, donors.length * 0.5));
      const amountB = Math.max(0.2, +rawOffer.toFixed(2));
      if ((donor.treasuryB || 0) < amountB) return;

      const isRival = (victim.rivalries || []).includes(donor.id) || entry.isHostile || (relOf(world, victim.id, donor.id).score || 50) < 45;
      const refuse = isRival && prideScore >= 90 && rng.chance(0.10);

      if (refuse) {
        d.aidOffers.push({ fromId: donor.id, amountB, accepted: false, isLoan: false, tick: world.tick });
        const refTpl = rng.pick(DISASTER_AID_REFUSED_TEMPLATES_V240);
        const refTxt = formatDisasterTemplateV240(refTpl, {
          leader: head ? head.name : `ผู้นำ ${shortNameTh(victim)}`,
          victim: shortNameTh(victim),
          donor: shortNameTh(donor),
          amountB: amountB.toFixed(2),
          typeLabel: d.labelTh,
          city: primaryCity ? cityNameTh(primaryCity) : shortNameTh(victim),
          damageB: d.damageB.toFixed(2)
        });
        d.log.unshift({ tick: world.tick, text: refTxt });
        if (d.log.length > 12) d.log.length = 12;
        const rAB = relOf(world, victim.id, donor.id);
        const rBA = relOf(world, donor.id, victim.id);
        rAB.score = rBA.score = clamp(rnd1((rAB.score || 45) - 3), 0, 100);
        addChronicle(world, 'DISASTER_AID', refTxt, victim.id, {
          targetStateId: donor.id,
          secondStateId: donor.id,
          cityId: primaryCity ? primaryCity.id : null,
          personId: head ? head.id : null,
          disasterId: d.id
        });
        return;
      }

      // Addendum Link 1: 30% of donors with treasuryB > 500 give loans instead of grants
      const isLoan = (donor.treasuryB || 0) > 500 && rng.chance(0.30);
      donor.treasuryB = rnd1(Math.max(0, (donor.treasuryB || 0) - amountB));
      d.aidReceivedB = +(d.aidReceivedB + amountB).toFixed(2);
      d.aidOffers.push({ fromId: donor.id, amountB, accepted: true, isLoan, tick: world.tick });

      if (isLoan && victim.sovereignDebt) {
        if (!victim.sovereignDebt.foreignCreditors) victim.sovereignDebt.foreignCreditors = {};
        victim.sovereignDebt.foreignCreditors[donor.id] = +((victim.sovereignDebt.foreignCreditors[donor.id] || 0) + amountB).toFixed(2);
        victim.sovereignDebt.totalDebtB = rnd1((victim.sovereignDebt.totalDebtB || 0) + amountB);
        victim.sovereignDebt.debtToGdpPct = +((victim.sovereignDebt.totalDebtB / Math.max(50, victim.gdpB || 100)) * 100).toFixed(1);
        recomputeCreditRatingV210(victim);
      } else {
        victim.treasuryB = rnd1((victim.treasuryB || 0) + amountB * 0.5);
      }

      const rAB = relOf(world, victim.id, donor.id);
      const rBA = relOf(world, donor.id, victim.id);
      const wasHostile = rAB.status === 'Hostile' || entry.isHostile;
      const boost = wasHostile ? 6 : 3;
      rAB.score = rBA.score = clamp(rnd1((rAB.score || 50) + boost), 0, 100);
      if (donor.trustV230 !== undefined) {
        donor.trustV230 = clamp(rnd1((donor.trustV230 || 70) + 1), 0, 100);
      }

      const aidTpl = rng.pick(DISASTER_INTL_AID_TEMPLATES_V240);
      const aidTxt = formatDisasterTemplateV240(aidTpl, {
        donor: shortNameTh(donor),
        victim: shortNameTh(victim),
        amountB: amountB.toFixed(2),
        aidKind: isLoan ? 'เงินกู้ดอกเบี้ยต่ำฉุกเฉิน' : 'เงินช่วยเหลือให้เปล่า',
        city: primaryCity ? cityNameTh(primaryCity) : shortNameTh(victim),
        typeLabel: d.labelTh,
        damageB: d.damageB.toFixed(2)
      });
      d.log.unshift({ tick: world.tick, text: aidTxt });
      if (d.log.length > 12) d.log.length = 12;
      addChronicle(world, 'DISASTER_AID', aidTxt, victim.id, {
        targetStateId: donor.id,
        secondStateId: donor.id,
        cityId: primaryCity ? primaryCity.id : null,
        personId: head ? head.id : null,
        disasterId: d.id
      });

      if (wasHostile && rAB.score >= 40) {
        const dipTpl = rng.pick(DISASTER_DIPLOMACY_TEMPLATES_V240);
        const dipTxt = formatDisasterTemplateV240(dipTpl, {
          donor: shortNameTh(donor),
          victim: shortNameTh(victim),
          amountB: amountB.toFixed(2),
          typeLabel: d.labelTh,
          city: primaryCity ? cityNameTh(primaryCity) : shortNameTh(victim),
          relScore: rAB.score.toFixed(1)
        });
        d.log.unshift({ tick: world.tick, text: dipTxt });
        if (d.log.length > 12) d.log.length = 12;
        addChronicle(world, 'DISASTER_AID', dipTxt, victim.id, {
          targetStateId: donor.id,
          secondStateId: donor.id,
          cityId: primaryCity ? primaryCity.id : null,
          personId: head ? head.id : null,
          disasterId: d.id
        });
      }
    });
  }

  function restoreCityPreDisasterMetricsV240(city, ensure95Pct = true) {
    if (!city) return;
    const pre = city._preDisasterV240;
    if (pre) {
      if (ensure95Pct) {
        city.infrastructure = Math.max(city.infrastructure || 70, +(pre.infrastructure * 0.96).toFixed(2));
        city.economy = Math.max(city.economy || 70, +(pre.economy * 0.96).toFixed(2));
      }
      city.industry = pre.industry;
      city.commerce = pre.commerce;
      city.agriculture = pre.agriculture;
      city.energy = pre.energy;
      if (pre.port !== undefined) city.port = pre.port;
      if (pre.rail !== undefined) city.rail = pre.rail;
    }
    city._disasterDownV240 = 0;
    city.portDisruptedV240 = false;
    city.railDisruptedV240 = false;
  }

  function stepDisastersLifecycleV240(world, rngInstance = null) {
    if (!world || !world.disasterV240) return;
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + (world.tick || 1) * 4211);
    const active = world.disasterV240.active;

    for (let i = active.length - 1; i >= 0; i--) {
      const d = active[i];
      const st = world.states[d.stateId];
      if (!st) {
        active.splice(i, 1);
        continue;
      }
      const elapsed = Math.max(1, (world.tick || 0) - (d.startTick || 0));
      d.phaseDay = elapsed;
      if (!Array.isArray(d.phasesVisited)) d.phasesVisited = ['IMPACT'];

      // Day 3 & Day 14 Government response evaluations
      if (elapsed >= 3 && !d._govEval3Done) {
        d._govEval3Done = true;
        evaluateDisasterGovResponseV240(world, d, rng, false);
      }
      if (elapsed >= 14 && !d._govEval14Done) {
        d._govEval14Done = true;
        evaluateDisasterGovResponseV240(world, d, rng, true);
      }

      // International response window: days 3-20
      d.intlWindowOpen = elapsed >= 3 && elapsed <= 20;
      if (elapsed >= 4 && !d._intlAidDone) {
        d._intlAidDone = true;
        evaluateDisasterInternationalAidV240(world, d, rng);
      }

      const primaryCity = d.cityIds && d.cityIds[0] ? world.cities[d.cityIds[0]] : stateCities(world, st.id)[0];
      const head = (st.positions?.HEAD_OF_STATE && world.npcs[st.positions.HEAD_OF_STATE]) || null;

      // Determine phase transitions in strict order: IMPACT -> RESCUE -> RELIEF -> RECONSTRUCTION -> COMPLETE
      if (d.phase === 'IMPACT' && elapsed >= 1) {
        if (d.typeId === 'DROUGHT_FAMINE') {
          d.phase = 'RESCUE';
        } else {
          d.phase = 'RESCUE';
        }
        if (!d.phasesVisited.includes('RESCUE')) d.phasesVisited.push('RESCUE');
        const rescueTpl = rng.pick(DISASTER_RESCUE_TEMPLATES_V240);
        const rescueTxt = formatDisasterTemplateV240(rescueTpl, {
          city: primaryCity ? cityNameTh(primaryCity) : shortNameTh(st),
          state: shortNameTh(st),
          typeLabel: d.labelTh,
          dead: d.casualties.dead.toLocaleString(),
          injured: d.casualties.injured.toLocaleString(),
          homelessK: Math.max(1, Math.round(d.casualties.homelessM * 1000)).toLocaleString(),
          damageB: d.damageB.toFixed(2),
          infraPct: primaryCity ? Math.round(primaryCity.infrastructure || 65) : 65,
          leader: head ? head.name : `ผู้นำ ${shortNameTh(st)}`
        });
        d.log.unshift({ tick: world.tick, text: rescueTxt });
        if (d.log.length > 12) d.log.length = 12;
        addChronicle(world, 'DISASTER', rescueTxt, st.id, {
          cityId: primaryCity ? primaryCity.id : null,
          personId: head ? head.id : null,
          disasterId: d.id
        });
      }

      if (d.phase === 'RESCUE' && elapsed >= 8) {
        d.phase = 'RELIEF';
        if (!d.phasesVisited.includes('RELIEF')) d.phasesVisited.push('RELIEF');
        // Addendum Link 3: If state is at war, lower militaryReadiness.logisticsCapacity and personnelReadiness by severity * 1.5 during RELIEF
        const wars = getWarsOf(world, st.id);
        if (wars.length > 0 && st.militaryReadiness && !d._milPenaltyApplied) {
          const pen = +(d.severity * 1.5).toFixed(2);
          d._milPenaltyApplied = pen;
          st.militaryReadiness.logisticsCapacity = clamp(+((st.militaryReadiness.logisticsCapacity || 80) - pen).toFixed(2), 10, 100);
          st.militaryReadiness.personnelReadiness = clamp(+((st.militaryReadiness.personnelReadiness || 80) - pen).toFixed(2), 10, 100);
          wars.forEach((w) => {
            const enemyId = w.attackerId === st.id ? w.defenderId : w.attackerId;
            if (enemyId) world._oppV240[enemyId] = (world.tick || 0) + 55;
          });
        }
      }

      // Check if state entered a war mid-RELIEF
      if (d.phase === 'RELIEF' && !d._milPenaltyApplied && st.militaryReadiness) {
        const wars = getWarsOf(world, st.id);
        if (wars.length > 0) {
          const pen = +(d.severity * 1.5).toFixed(2);
          d._milPenaltyApplied = pen;
          st.militaryReadiness.logisticsCapacity = clamp(+((st.militaryReadiness.logisticsCapacity || 80) - pen).toFixed(2), 10, 100);
          st.militaryReadiness.personnelReadiness = clamp(+((st.militaryReadiness.personnelReadiness || 80) - pen).toFixed(2), 10, 100);
          wars.forEach((w) => {
            const enemyId = w.attackerId === st.id ? w.defenderId : w.attackerId;
            if (enemyId) world._oppV240[enemyId] = (world.tick || 0) + 55;
          });
        }
      }

      if (d.phase === 'RELIEF' && elapsed >= 61) {
        d.phase = 'RECONSTRUCTION';
        if (!d.phasesVisited.includes('RECONSTRUCTION')) d.phasesVisited.push('RECONSTRUCTION');
        // Restore militaryReadiness penalty when leaving RELIEF
        if (d._milPenaltyApplied && st.militaryReadiness) {
          st.militaryReadiness.logisticsCapacity = clamp(+((st.militaryReadiness.logisticsCapacity || 75) + d._milPenaltyApplied).toFixed(2), 10, 100);
          st.militaryReadiness.personnelReadiness = clamp(+((st.militaryReadiness.personnelReadiness || 75) + d._milPenaltyApplied).toFixed(2), 10, 100);
          d._milPenaltyApplied = 0;
        }
      }

      // RELIEF & RECONSTRUCTION step recovery + RELIEF treasury slices
      if (d.phase === 'RELIEF' || d.phase === 'RECONSTRUCTION') {
        if (d.phase === 'RELIEF' && d._reliefSlicesPaid < 26) {
          d._reliefSlicesPaid++;
          const sliceB = (d.damageB * 0.25) / 26;
          if ((st.treasuryB || 0) - sliceB < 0.15 * d.damageB || (st.treasuryB || 0) < sliceB) {
            const borrowB = Math.max(5, +(Math.max(sliceB * 4, d.damageB * 0.2)).toFixed(1));
            setCentralBankPolicyV210(world, st.id, 'issue_bonds', borrowB);
          }
          st.treasuryB = Math.max(0, +((st.treasuryB || 0) - sliceB).toFixed(2));
        }

        // Recovery rate formula (T4.3): (0.4 + responseScore/200 + min(0.4, aidReceivedB/damageB)) percent of the gap per step
        // Note: To reach >=95% of pre-disaster value within the 61..540 day window while allowing RECONSTRUCTION to be observed, we close a fraction of the remaining gap each step
        const baseRatePct = 0.4 + (d.responseScore || 60) / 200 + Math.min(0.4, (d.aidReceivedB || 0) / Math.max(0.1, d.damageB));
        const stepFrac = d.phase === 'RECONSTRUCTION' ? Math.max(0.035, baseRatePct * 0.045) : (baseRatePct * 0.012);

        let allRecovered = true;
        let avgRecPct = 0;
        const cIds = d.cityIds || [];
        cIds.forEach((cid) => {
          const c = world.cities[cid];
          if (!c) return;
          const pre = c._preDisasterV240 || { infrastructure: 80, economy: 80, industry: 80, commerce: 80, agriculture: 75, energy: 75 };
          const targetInfra = pre.infrastructure * 0.96;
          const targetEcon = pre.economy * 0.96;
          if (c.infrastructure < targetInfra) {
            c.infrastructure = +(c.infrastructure + Math.max(0.15, (targetInfra - c.infrastructure) * stepFrac)).toFixed(2);
          }
          if (c.economy < targetEcon) {
            c.economy = +(c.economy + Math.max(0.15, (targetEcon - c.economy) * stepFrac)).toFixed(2);
          }
          if (c._disasterDownV240 > 0) {
            c._disasterDownV240 = Math.max(0, c._disasterDownV240 - 2);
            if (c._disasterDownV240 === 0) {
              c.portDisruptedV240 = false;
              c.railDisruptedV240 = false;
              if (pre.port !== undefined) c.port = pre.port;
              if (pre.rail !== undefined) c.rail = pre.rail;
            }
          }
          const ratio = clamp((c.infrastructure / Math.max(15, pre.infrastructure)) * 100, 10, 100);
          avgRecPct += ratio;
          if (c.infrastructure < pre.infrastructure * 0.95) {
            allRecovered = false;
          }
        });
        avgRecPct = cIds.length > 0 ? Math.round(avgRecPct / cIds.length) : 95;
        d.recoveryPct = avgRecPct;

        // Log periodic RELIEF/RECOVERY story once around day 30 or day 90
        if ((elapsed === 30 || elapsed === 31 || elapsed === 90 || elapsed === 91) && !d._loggedRecoveryProgress) {
          d._loggedRecoveryProgress = true;
          const recTpl = rng.pick(DISASTER_RELIEF_RECOVERY_TEMPLATES_V240);
          const recTxt = formatDisasterTemplateV240(recTpl, {
            city: primaryCity ? cityNameTh(primaryCity) : shortNameTh(st),
            state: shortNameTh(st),
            typeLabel: d.labelTh,
            recPct: avgRecPct,
            aidB: d.aidReceivedB.toFixed(2),
            damageB: d.damageB.toFixed(2)
          });
          d.log.unshift({ tick: world.tick, text: recTxt });
          if (d.log.length > 12) d.log.length = 12;
          addChronicle(world, 'DISASTER', recTxt, st.id, {
            cityId: primaryCity ? primaryCity.id : null,
            disasterId: d.id
          });
        }

        // Transition to COMPLETE only when in RECONSTRUCTION and (allRecovered after day 100 OR elapsed >= 340)
        if (d.phase === 'RECONSTRUCTION' && ((allRecovered && elapsed >= 100) || elapsed >= 340)) {
          d.phase = 'COMPLETE';
          d.recoveryPct = Math.max(96, avgRecPct);
          if (!d.phasesVisited.includes('COMPLETE')) d.phasesVisited.push('COMPLETE');
          cIds.forEach((cid) => {
            const c = world.cities[cid];
            if (c) restoreCityPreDisasterMetricsV240(c, true);
          });
          const compTpl = rng.pick(DISASTER_RECONSTRUCTION_COMPLETE_TEMPLATES_V240);
          const compTxt = formatDisasterTemplateV240(compTpl, {
            city: primaryCity ? cityNameTh(primaryCity) : shortNameTh(st),
            state: shortNameTh(st),
            typeLabel: d.labelTh,
            recPct: d.recoveryPct,
            damageB: d.damageB.toFixed(2),
            aidB: d.aidReceivedB.toFixed(2)
          });
          d.log.unshift({ tick: world.tick, text: compTxt });
          if (d.log.length > 12) d.log.length = 12;
          addChronicle(world, 'DISASTER', compTxt, st.id, {
            cityId: primaryCity ? primaryCity.id : null,
            disasterId: d.id
          });
        }
      }

      // Anniversary at tick + 365 ONCE, then archive
      if (elapsed >= 365 && !d.anniversaryDone) {
        if (d.phase !== 'COMPLETE') {
          if (!d.phasesVisited.includes('RECONSTRUCTION')) d.phasesVisited.push('RECONSTRUCTION');
          d.phase = 'COMPLETE';
          d.recoveryPct = 96;
          if (!d.phasesVisited.includes('COMPLETE')) d.phasesVisited.push('COMPLETE');
          (d.cityIds || []).forEach((cid) => {
            const c = world.cities[cid];
            if (c) restoreCityPreDisasterMetricsV240(c, true);
          });
        }
        if (d._milPenaltyApplied && st.militaryReadiness) {
          st.militaryReadiness.logisticsCapacity = clamp(+((st.militaryReadiness.logisticsCapacity || 75) + d._milPenaltyApplied).toFixed(2), 10, 100);
          st.militaryReadiness.personnelReadiness = clamp(+((st.militaryReadiness.personnelReadiness || 75) + d._milPenaltyApplied).toFixed(2), 10, 100);
          d._milPenaltyApplied = 0;
        }
        d.anniversaryDone = true;
        const annTpl = rng.pick(DISASTER_ANNIVERSARY_TEMPLATES_V240);
        const annTxt = formatDisasterTemplateV240(annTpl, {
          leader: head ? head.name : `ผู้นำ ${shortNameTh(st)}`,
          state: shortNameTh(st),
          city: primaryCity ? cityNameTh(primaryCity) : shortNameTh(st),
          typeLabel: d.labelTh,
          dead: d.casualties.dead.toLocaleString(),
          injured: d.casualties.injured.toLocaleString(),
          damageB: d.damageB.toFixed(2),
          score: d.responseScore.toFixed(1),
          aidB: d.aidReceivedB.toFixed(2)
        });
        d.log.unshift({ tick: world.tick, text: annTxt });
        if (d.log.length > 12) d.log.length = 12;
        addChronicle(world, 'DISASTER', annTxt, st.id, {
          cityId: primaryCity ? primaryCity.id : null,
          personId: head ? head.id : null,
          disasterId: d.id
        });

        // Clear _preDisasterV240 on cities and move to archive (cap 40)
        (d.cityIds || []).forEach((cid) => {
          const c = world.cities[cid];
          if (c) delete c._preDisasterV240;
        });
        active.splice(i, 1);
        world.disasterV240.archive.unshift(d);
        if (world.disasterV240.archive.length > 40) world.disasterV240.archive.length = 40;
      }
    }
  }

  function stepEpidemicsV240(world, rngInstance = null) {
    if (!world || !world.disasterV240 || !Array.isArray(world.disasterV240.active)) return;
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + (world.tick || 1) * 4337);

    world.disasterV240.active.forEach((d) => {
      if (!d || d.typeId !== 'EPIDEMIC' || !d.epidemic || d.epidemic.phase === 'ENDED') return;
      const ep = d.epidemic;
      const origSt = world.states[ep.originStateId] || world.states[d.stateId];
      const primaryCity = d.cityIds && d.cityIds[0] ? world.cities[d.cityIds[0]] : (origSt ? stateCities(world, origSt.id)[0] : null);

      const prevGlobalInf = Object.values(ep.infectedM).reduce((s, v) => s + (v || 0), 0);

      // Advance vaccine progress by top 3 researchPoints / CHIEF_SCIENTIST states
      const allLive = Object.values(world.states).filter((s) => !s.isExiled);
      const top3 = allLive
        .slice()
        .sort((a, b) => ((b.researchPoints || 50) + (b.positions?.CHIEF_SCIENTIST ? 40 : 0)) - ((a.researchPoints || 50) + (a.positions?.CHIEF_SCIENTIST ? 40 : 0)))
        .slice(0, 3);
      const topLeader = top3[0] || origSt;
      const avgRp = top3.reduce((s, x) => s + Math.max(40, x.researchPoints || 60), 0) / Math.max(1, top3.length);
      const vacStep = 0.8 + 0.01 * avgRp;
      const oldVac = ep.vaccineProgress || 0;
      ep.vaccineProgress = +(Math.min(100, oldVac + vacStep)).toFixed(2);

      if (ep.vaccineProgress >= 100 && !ep.vaccineBy && topLeader) {
        ep.vaccineBy = topLeader.id;
        // Donate to 4 closest-relation states
        const closest4 = Object.keys(topLeader.relations || {})
          .filter((sid) => world.states[sid] && !world.states[sid].isExiled && sid !== topLeader.id)
          .sort((a, b) => (topLeader.relations[b]?.score || 50) - (topLeader.relations[a]?.score || 50))
          .slice(0, 4);
        closest4.forEach((cid) => {
          const r1 = relOf(world, topLeader.id, cid);
          const r2 = relOf(world, cid, topLeader.id);
          r1.score = r2.score = clamp(rnd1((r1.score || 50) + 4), 0, 100);
        });
        if (topLeader.trustV230 !== undefined) {
          topLeader.trustV230 = clamp(rnd1((topLeader.trustV230 || 70) + 2), 0, 100);
        }
        addChronicle(world, 'DISASTER_AID', `💉🌍 [พัฒนาวัคซีนสำเร็จและการทูตวัคซีน] นักวิทยาศาสตร์ของ ${shortNameTh(topLeader)} พัฒนาวัคซีนต้าน${d.labelTh}สำเร็จครบ 100% และบริจาควัคซีนล็อตแรกให้พันธมิตรใกล้ชิด ${closest4.length} ประเทศ ดันความสัมพันธ์ +4 และความน่าเชื่อถือ +2`, topLeader.id, {
          disasterId: d.id
        });
      }

      // Update infected per state
      Object.keys(ep.infectedM).forEach((sid) => {
        const st = world.states[sid];
        if (!st) return;
        const totPopM = Math.max(0.5, stateCities(world, sid).reduce((s, c) => s + (c.popM || 1), 0));
        const capM = +(0.12 * totPopM).toFixed(4);
        const curM = ep.infectedM[sid] || 0;
        const isClosed = ep.borderClosedBy.includes(sid) ? 1 : 0;

        if (ep.phase === 'OUTBREAK' || ep.phase === 'SPREAD') {
          const growth = curM * ep.contagion * 0.12 * (1 - 0.5 * isClosed);
          const nextM = Math.min(capM, +(curM + growth).toFixed(5));
          const actualIncM = Math.max(0, nextM - curM);
          const addDead = Math.round(actualIncM * 1e6 * (ep.lethalityPct / 100) * 0.05);
          ep.deadTotal += addDead;
          d.casualties.dead += addDead;
          ep.infectedM[sid] = nextM;
        } else if (ep.phase === 'PEAK') {
          ep.infectedM[sid] = Math.min(capM, +(curM * 0.96).toFixed(5));
        } else if (ep.phase === 'DECLINE') {
          const nextM = +(curM * 0.52 - 0.0004).toFixed(5);
          ep.infectedM[sid] = Math.max(0, nextM);
        }

        // Border closure check: infected share > 1% -> 40% probability
        const share = (ep.infectedM[sid] || 0) / totPopM;
        if (share > 0.01 && !ep.borderClosedBy.includes(sid) && rng.chance(0.40)) {
          ep.borderClosedBy.push(sid);
          st.gdpB = rnd1(Math.max(5, st.gdpB * 0.998));
          // Addendum Link 4: Epidemic border closures reduce city.commerce for port/airport cities
          stateCities(world, sid).forEach((c) => {
            if ((c.port || 0) > 0 || (c.airport || 0) > 0) {
              c.commerce = Math.max(15, +((c.commerce || 80) - 4).toFixed(2));
            }
          });
        }
      });

      // Spread to other states while in OUTBREAK or SPREAD (max 10 infected states)
      const infectedIds = Object.keys(ep.infectedM);
      if ((ep.phase === 'OUTBREAK' || ep.phase === 'SPREAD') && infectedIds.length < 10) {
        for (let i = 0; i < allLive.length && Object.keys(ep.infectedM).length < 10; i++) {
          const cand = allLive[i];
          if (ep.infectedM[cand.id] !== undefined) continue;
          const candCities = stateCities(world, cand.id);
          const hasHub = candCities.some((c) => (c.airport || 0) >= 2 || (c.port || 0) >= 2);
          const hasTie = infectedIds.some((isid) => (relOf(world, cand.id, isid).score || 50) >= 52 || cand.region === (world.states[isid] && world.states[isid].region));
          if (!hasHub && !hasTie) continue;
          let tieStrength = (hasHub ? 1.8 : 1.0) + (hasTie ? 1.4 : 0.4);
          if (ep.borderClosedBy.includes(cand.id)) tieStrength *= 0.4;
          const pImport = 0.02 * ep.contagion * tieStrength;
          if (rng.chance(pImport)) {
            const totPop = Math.max(0.5, candCities.reduce((s, c) => s + (c.popM || 1), 0));
            ep.infectedM[cand.id] = +(Math.min(0.12 * totPop, 0.012)).toFixed(4);
          }
        }
      }

      const newGlobalInf = Object.values(ep.infectedM).reduce((s, v) => s + (v || 0), 0);
      if (newGlobalInf <= prevGlobalInf + 0.0001) {
        ep.noGrowthSteps = (ep.noGrowthSteps || 0) + 1;
      } else {
        ep.noGrowthSteps = 0;
      }

      let phaseChangedTo = null;
      if (ep.phase === 'OUTBREAK' && (Object.keys(ep.infectedM).length > 1 || (world.tick - d.startTick) >= 10)) {
        ep.phase = 'SPREAD';
        phaseChangedTo = 'SPREAD';
      } else if (ep.phase === 'SPREAD' && (ep.noGrowthSteps >= 3 || ep.vaccineProgress >= 55 || (world.tick - d.startTick) >= 85)) {
        ep.phase = 'PEAK';
        ep.peakTick = world.tick;
        phaseChangedTo = 'PEAK';
      } else if (ep.phase === 'PEAK' && (ep.vaccineProgress >= 60 || (ep.peakTick && (world.tick - ep.peakTick) >= 90))) {
        ep.phase = 'DECLINE';
        phaseChangedTo = 'DECLINE';
      } else if (ep.phase === 'DECLINE') {
        const maxStateInf = Math.max(0, ...Object.values(ep.infectedM));
        if (maxStateInf < 0.001) {
          ep.phase = 'ENDED';
          phaseChangedTo = 'ENDED';
        }
      }

      if (phaseChangedTo && EPIDEMIC_PHASE_TEMPLATES_V240[phaseChangedTo]) {
        const tpl = rng.pick(EPIDEMIC_PHASE_TEMPLATES_V240[phaseChangedTo]);
        const txt = formatDisasterTemplateV240(tpl, {
          city: primaryCity ? cityNameTh(primaryCity) : (origSt ? shortNameTh(origSt) : ''),
          state: origSt ? shortNameTh(origSt) : '',
          contagion: ep.contagion.toFixed(2),
          lethality: ep.lethalityPct.toFixed(2),
          infM: newGlobalInf.toFixed(3),
          dead: ep.deadTotal.toLocaleString(),
          numStates: Object.keys(ep.infectedM).length,
          vacPct: ep.vaccineProgress.toFixed(0)
        });
        d.log.unshift({ tick: world.tick, text: txt });
        if (d.log.length > 12) d.log.length = 12;
        addChronicle(world, 'DISASTER', txt, origSt ? origSt.id : d.stateId, {
          cityId: primaryCity ? primaryCity.id : null,
          disasterId: d.id
        });
      }
    });
  }

  function getDisasterSummaryV240(world) {
    ensureDisastersV240(world);
    const active = world.disasterV240.active || [];
    const archive = world.disasterV240.archive || [];
    const allThisYear = active.concat(archive).filter((d) => {
      const ticksAgo = (world.tick || 0) - (d.startTick || 0);
      return ticksAgo <= 365;
    });
    const totalDeadYTD = allThisYear.reduce((s, d) => s + ((d.casualties && d.casualties.dead) || 0), 0);
    const totalAidB = +(active.concat(archive).reduce((s, d) => s + (d.aidReceivedB || 0), 0)).toFixed(2);
    return {
      activeCount: active.length,
      archiveCount: archive.length,
      totalDeadYTD,
      totalAidB,
      active,
      archive
    };
  }

  // T4.1 Replace runRandomEvents (20% monthly gate: 70% lifecycle disaster via spawnDisasterV240, 30% original positive events)
  runRandomEvents = function (world, rng) {
    if (!world || !world.states) return;
    ensureDisastersV240(world);
    const r = rng || new SeededRNG((world.seed || 2026) + (world.tick || 1) * 7691);
    if (!r.chance(0.20)) return;

    if (r.chance(0.70)) {
      spawnDisasterV240(world, null, null, null, r);
      return;
    }

    // 30% of the time: original POSITIVE entries (gdp > 0: golden age, resource discovery, cultural festival)
    const live = Object.values(world.states).filter((s) => !s.isExiled);
    const st = r.pick(live);
    const posEvents = DISASTERS.filter((d) => d.gdp > 0);
    const ev = r.pick(posEvents);
    if (!st || !ev) return;
    st.gdpB = rnd1(Math.max(5, st.gdpB * (1 + ev.gdp)));
    st.stability = rnd1(clamp(st.stability + ev.stab, 3, 98));
    st.approval = rnd1(clamp(st.approval + ev.apr, 3, 98));
    const city = r.pick(stateCities(world, st.id));
    logEvent(
      world,
      'ECONOMIC',
      `${ev.icon} ${ev.t}เกิดขึ้นที่${city ? ' ' + cityNameTh(city) : ''} ของ ${shortNameTh(st)} ช่วยเสริมเศรษฐกิจ (+${(ev.gdp * 100).toFixed(1)}%) และความนิยมรัฐบาล`,
      st.id,
      city ? { cityId: city.id } : {}
    );
  };


