  const ASSASSINATION_PURGE_TEMPLATES_V240 = [
    '⛓️🪖 [กวาดล้างใหญ่ผู้ร่วมขบวนการกบฏและลอบสังหาร!] หลังแผนลอบสังหาร {target} ล้มเหลว รัฐบาล {state} สั่งจับกุมและปลดเจ้าหน้าที่ระดับสูงในเครือข่ายเดียวกันรวม {count} ราย พร้อมทลายเครือข่ายทหารใต้ดิน!',
    '⛓️🚨 [คืนวันมีดยาว! จับกุมกลุ่มสมคบคิดในทำเนียบและกองทัพ] หน่วยความมั่นคง {state} บุกจับกุมผู้ร่วมแผนลอบสังหาร {target} จำนวน {count} ราย ยึดทรัพย์และถอดยศทันที',
    '⛓️🔥 [ถอนรากถอนโคนกบฏในเงามืด] ความล้มเหลวของแผนลอบสังหาร {target} นำไปสู่การกวาดล้างครั้งใหญ่ใน {state} มีนายพลและนักการเมืองถูกจับกุม {count} ราย',
    '⛓️⚖️ [ตั้งศาลพิเศษพิพากษาผู้ร่วมแผนสังหาร] รัฐบาล {state} สั่งดำเนินคดีและปลดฟ้าผ่าเครือข่ายผู้สมรู้ร่วมคิด {count} ราย ที่พัวพันกับแผนลอบสังหาร {target}',
    '⛓️🛡️ [จัดระเบียบกองทัพและฝ่ายความมั่นคงหลังแผนแตก] ผู้นำ {target} แห่ง {state} สั่งกวาดล้างกลุ่มอิทธิพลที่คิดคดทรยศรวม {count} ราย ลดระดับแผนกบฏทหารลงอย่างฮวบฮาบ',
    '⛓️🔒 [ปิดล้อมจับกุมเครือข่ายกบฏคาบ้านพัก] ปฏิบัติการกวาดล้างสายฟ้าแลบใน {state} รวบตัวผู้เชื่อมโยงกับแผนลอบสังหาร {target} ได้ถึง {count} ราย สร้างความเกรงขามทั่วประเทศ'
  ];

  function ensureDefectionsAndPlotsV240(world) {
    if (!world) return;
    if (!world.defectionV240 || typeof world.defectionV240 !== 'object') {
      world.defectionV240 = { nextId: 1, defectors: [], archive: [] };
    }
    if (typeof world.defectionV240.nextId !== 'number') world.defectionV240.nextId = 1;
    if (!Array.isArray(world.defectionV240.defectors)) world.defectionV240.defectors = [];
    if (!Array.isArray(world.defectionV240.archive)) world.defectionV240.archive = [];

    if (!world.assassinationV240 || typeof world.assassinationV240 !== 'object') {
      world.assassinationV240 = { nextId: 1, plots: [], archive: [] };
    }
    if (typeof world.assassinationV240.nextId !== 'number') world.assassinationV240.nextId = 1;
    if (!Array.isArray(world.assassinationV240.plots)) world.assassinationV240.plots = [];
    if (!Array.isArray(world.assassinationV240.archive)) world.assassinationV240.archive = [];
  }

  function defectionRiskV240(world, npcOrId) {
    const npc = typeof npcOrId === 'string' ? (world && world.npcs ? world.npcs[npcOrId] : null) : npcOrId;
    if (!npc) return 0;
    const st = world && world.states && npc.stateId ? world.states[npc.stateId] : null;

    const grievance = clamp(npc.grievance ?? 20, 0, 100);
    const satisfaction = clamp(npc.satisfaction ?? 75, 0, 100);
    const loyalty = clamp(npc.loyalty ?? npc.personality?.loyalty ?? 75, 0, 100);
    const ambition = clamp(npc.personality?.ambition ?? npc.ambition ?? 50, 0, 100);
    const repressionIndex = clamp((st && st.underground && typeof st.underground.intelSuppression === 'number') ? st.underground.intelSuppression : 40, 0, 100);

    let risk = 0.35 * grievance + 0.25 * (100 - satisfaction) + 0.20 * (100 - loyalty) + 0.10 * ambition + 0.10 * repressionIndex;

    const isRepressive = st && (['Authoritarian', 'One_Party', 'Military_Junta'].includes(st.regimeCategory) || repressionIndex >= 60);
    if (isRepressive && npc.family && (npc.family.childrenCount || 0) > 0) {
      risk -= 15;
    }

    if (world && world.spyNetworks && npc.stateId) {
      const hasStrongForeignSpy = Object.values(world.spyNetworks).some(
        (net) => net && net.targetStateId === npc.stateId && net.sponsorStateId !== npc.stateId && (net.networkStrength || 0) > 40
      );
      if (hasStrongForeignSpy) {
        risk += 15;
      }
    }

    return +(clamp(risk, 0, 100)).toFixed(2);
  }

  function pickDefectionHostV240(world, npcOrOriginId, rngInstance = null) {
    if (!world || !world.states) return null;
    const originId = typeof npcOrOriginId === 'string' ? npcOrOriginId : (npcOrOriginId && npcOrOriginId.stateId);
    const origin = originId ? world.states[originId] : null;
    if (!origin) return null;

    const originAllies = new Set(alliesOf(world, origin.id));
    const isEligibleHost = (s) => {
      if (!s || s.isExiled || s.id === origin.id) return false;
      if (s.vassalOf === origin.id || origin.vassalOf === s.id) return false;
      if (originAllies.has(s.id)) return false;
      const rel = relOf(world, origin.id, s.id);
      if (rel.status === 'Alliance') return false;
      return true;
    };

    // 1. Prefer recruiting sponsor of a spy network targeting origin with networkStrength > 40
    if (world.spyNetworks) {
      const sponsorNets = Object.values(world.spyNetworks)
        .filter((net) => net && net.targetStateId === origin.id && (net.networkStrength || 0) > 40 && isEligibleHost(world.states[net.sponsorStateId]))
        .sort((a, b) => (b.networkStrength || 0) - (a.networkStrength || 0));
      if (sponsorNets.length > 0) {
        return world.states[sponsorNets[0].sponsorStateId];
      }
    }

    // 2. Else a rival of the origin with relation score < 40 and highest informationOps.diplomaticReputation
    const rivalsUnder40 = Object.values(world.states)
      .filter((s) => isEligibleHost(s) && (relOf(world, origin.id, s.id).score ?? 50) < 40)
      .sort((a, b) => ((b.informationOps?.diplomaticReputation ?? 65) - (a.informationOps?.diplomaticReputation ?? 65)));
    if (rivalsUnder40.length > 0) return rivalsUnder40[0];

    // 3. Fallback: any eligible non-ally state sorted by lowest relation score then highest diplomaticReputation
    const fallback = Object.values(world.states)
      .filter((s) => isEligibleHost(s))
      .sort((a, b) => (relOf(world, origin.id, a.id).score ?? 50) - (relOf(world, origin.id, b.id).score ?? 50));
    return fallback[0] || null;
  }

  function getDefectorSecretAssetLabelV240(oldPost, npc) {
    if (['SUPREME_COMMANDER', 'ARMY_CHIEF', 'NAVY_CHIEF', 'AIR_FORCE_CHIEF', 'DEFENSE_MINISTER', 'THEATER_COMMANDER'].includes(oldPost) || (npc && npc.track === 'military')) {
      return 'แฟ้มแผนยุทธการรบและพิกัดคลังแสงแนวหน้า';
    }
    if (oldPost === 'INTELLIGENCE_CHIEF') {
      return 'บัญชีรายชื่อสายลับสองหน้าและรหัสข่ายสื่อสารลับ';
    }
    if (['CHIEF_SCIENTIST', 'CTO_EXECUTIVE', 'PROFESSOR_ACADEMIC'].includes(oldPost)) {
      return 'พิมพ์เขียวเตาปฏิกรณ์และต้นแบบเทคโนโลยีชั้นสูง';
    }
    if (['DIPLOMAT', 'FOREIGN_MINISTER'].includes(oldPost)) {
      return 'บันทึกข้อตกลงลับทางการทูตและโทรเลขสถานทูต';
    }
    if (oldPost === 'CEO_DIRECTOR' || oldPost === 'FINANCE_MINISTER') {
      return 'สมุดบัญชีลับกองทุนรัฐและเครือข่ายการเงินข้ามชาติ';
    }
    return 'แฟ้มเอกสารลับระดับความมั่นคงแห่งชาติ';
  }

  function startDefectionV240(world, npcId, hostId = null, motive = null, rngInstance = null) {
    if (!world || !world.states || !world.npcs) return { ok: false, reason: 'ไม่พบข้อมูลโลก' };
    ensureDefectionsAndPlotsV240(world);
    const npc = typeof npcId === 'object' ? npcId : world.npcs[npcId];
    if (!npc || !npc.alive) return { ok: false, reason: 'ไม่พบตัวละครหรือตัวละครเสียชีวิตแล้ว' };

    const origin = world.states[npc.stateId];
    if (!origin) return { ok: false, reason: 'ไม่พบรัฐต้นสังกัดของตัวละคร' };

    const rng = rngInstance || new SeededRNG((world.seed || 2026) + (world.tick || 1) * 6133 + (world.defectionV240.nextId || 1) * 79);

    let host = null;
    if (hostId) {
      host = typeof hostId === 'object' ? hostId : world.states[hostId];
      if (!host) return { ok: false, reason: 'ไม่พบรัฐปลายทาง' };
      if (host.id === origin.id) return { ok: false, reason: 'ไม่สามารถแปรพักตร์ไปยังรัฐเดิมของตนเองได้' };
      if (host.vassalOf === origin.id || origin.vassalOf === host.id) {
        return { ok: false, reason: 'ไม่สามารถแปรพักตร์ไปยังรัฐบริวารได้' };
      }
      if (relOf(world, origin.id, host.id).status === 'Alliance' || alliesOf(world, origin.id).includes(host.id)) {
        return { ok: false, reason: 'รัฐพันธมิตรจะไม่รับผู้แปรพักตร์จากประเทศพันธมิตรด้วยกัน' };
      }
    } else {
      host = pickDefectionHostV240(world, npc, rng);
    }
    if (!host) return { ok: false, reason: 'ไม่พบรัฐปลายทางที่เหมาะสมสำหรับการลี้ภัยแปรพักตร์' };

    const oldPost = npc.positionId || 'SENIOR_OFFICIAL';
    const oldPostTitle = npc.positionTitle || oldPost;

    let chosenMotive = motive;
    if (!chosenMotive || !DEFECTION_MOTIVES_V240.some((m) => m.id === chosenMotive)) {
      if (npc._persecutedWhistleblowerV240) chosenMotive = 'PERSECUTION_FEAR';
      else if (getWarsOf(world, origin.id).length > 0 && rng.chance(0.35)) chosenMotive = 'WAR_CONSCIENCE';
      else chosenMotive = rng.pick(DEFECTION_MOTIVES_V240).id;
    }
    const motiveObj = DEFECTION_MOTIVES_V240.find((m) => m.id === chosenMotive) || DEFECTION_MOTIVES_V240[0];

    // 1. Vacate old post & trigger succession
    handleNPCSuccession(world, npc, 'dismissed', 'แปรพักตร์');
    unassignNPCFromPosts(world, npc);
    origin.vacancyDirty = true;
    origin.logisticsDirty = true;
    

    // 2. Move NPC to host state & capital
    const hostCities = stateCities(world, host.id);
    const hostCap = hostCities.find((c) => c.isCapital) || hostCities[0] || null;
    npc.stateId = host.id;
    npc.region = host.region;
    npc.currentCityId = hostCap ? hostCap.id : npc.currentCityId;
    npc.assignedNodeId = hostCap ? hostCap.id : npc.assignedNodeId;
    npc.positionId = 'SENIOR_OFFICIAL';
    npc.positionTitle = `ที่ปรึกษาอาวุโสพิเศษ (อดีต ${oldPostTitle} แห่ง ${shortNameTh(origin)})`;
    npc.retired = false;
    npc.alive = true;
    npc.defection = {
      fromStateId: origin.id,
      toStateId: host.id,
      tick: world.tick || 0,
      reason: motiveObj.labelTh,
      motive: chosenMotive
    };

    // 3. Role-specific effects on host and origin (T7.1 + Addendum Links 5 & 6)
    if (!origin.militaryReadiness) ensureStateDeepProfileV170(world, origin);
    if (!host.militaryReadiness) ensureStateDeepProfileV170(world, host);
    ensureDiplomacyAndIntelV200(world);

    const isMil = ['ARMY_CHIEF', 'NAVY_CHIEF', 'AIR_FORCE_CHIEF', 'SUPREME_COMMANDER', 'DEFENSE_MINISTER', 'THEATER_COMMANDER'].includes(oldPost) || npc.track === 'military';
    const isIntel = oldPost === 'INTELLIGENCE_CHIEF';
    const isSci = ['CHIEF_SCIENTIST', 'CTO_EXECUTIVE', 'PROFESSOR_ACADEMIC'].includes(oldPost);
    const isDip = ['DIPLOMAT', 'FOREIGN_MINISTER'].includes(oldPost);
    const isCeo = oldPost === 'CEO_DIRECTOR';

    if (isMil) {
      host.militaryReadiness.intelligence = clamp(+((host.militaryReadiness.intelligence || 75) + 0.5).toFixed(2), 10, 100);
      origin.militaryReadiness.commandQuality = clamp(+((origin.militaryReadiness.commandQuality || 75) - 3).toFixed(2), 10, 100);
      origin.militaryReadiness.intelligence = clamp(+((origin.militaryReadiness.intelligence || 75) - 4).toFixed(2), 10, 100);
    }
    if (isIntel) {
      host.militaryReadiness.intelligence = clamp(+((host.militaryReadiness.intelligence || 75) + 0.5).toFixed(2), 10, 100);
      // Burn every spyNetworks record with sponsorStateId === origin.id (-15)
      Object.values(world.spyNetworks || {}).forEach((net) => {
        if (net && net.sponsorStateId === origin.id) {
          net.networkStrength = Math.max(0, (net.networkStrength || 0) - 15);
          net.informantsCount = Math.max(0, (net.informantsCount || 1) - 1);
          net.agentRisk = clamp((net.agentRisk || 20) + 15, 0, 100);
        }
      });
      // Addendum Link 5: Mark matching intelligenceOps sponsored by origin as 'compromised'
      (world.intelligenceOps || []).forEach((op) => {
        if (op && op.sponsorStateId === origin.id) {
          op.status = 'compromised';
          op.active = false;
          op.detected = true;
        }
      });
      // Addendum Link 5: Bump networkStrength for host's network against origin by +12 and add an intelligenceOps record
      const hostNet = getOrInitSpyNetwork(world, host.id, origin.id);
      hostNet.networkStrength = clamp((hostNet.networkStrength || 35) + 12, 5, 99);
      hostNet.informantsCount = (hostNet.informantsCount || 2) + 2;
      if (Array.isArray(world.intelligenceOps)) {
        world.intelligenceOps.unshift({
          id: `INTELOP_DEF_${host.id}_${origin.id}_${world.tick || 1}`,
          sponsorStateId: host.id,
          targetStateId: origin.id,
          opType: 'spy_network',
          label: `ขยายเครือข่ายจากข้อมูลผู้แปรพักตร์ ${npc.name}`,
          costB: 0,
          duration: 60,
          remainingDays: 60,
          successChance: 0.92,
          discoveryChance: 0.08,
          informantLoyalty: 88,
          agentRisk: 12,
          active: true,
          status: 'active',
          succeeded: true,
          detected: false,
          date: world.dateString,
          year: world.year,
          consequence: `ได้รายชื่อสายลับและรหัสลับจากอดีตหัวหน้าข่าวกรอง ${npc.name} (+12 Network Strength)`
        });
        if (world.intelligenceOps.length > 45) world.intelligenceOps.length = 45;
      }
    }
    if (isSci) {
      host.researchPoints = Math.round((host.researchPoints || 0) + 8);
      origin.researchPoints = Math.max(0, Math.round((origin.researchPoints || 0) - 8));
      // Addendum Link 6: Transfer 1 level of one tech branch from origin to host if host is behind
      if (!origin.techBranches) ensureStateWorldSystems(world, origin);
      if (!host.techBranches) ensureStateWorldSystems(world, host);
      if (origin.techBranches && host.techBranches) {
        const behindBranches = Object.keys(origin.techBranches).filter(
          (k) => (host.techBranches[k] || 0) < (origin.techBranches[k] || 0)
        );
        if (behindBranches.length > 0) {
          const bKey = behindBranches[0];
          origin.techBranches[bKey] = clamp((origin.techBranches[bKey] || 50) - 1, 10, 99);
          host.techBranches[bKey] = clamp((host.techBranches[bKey] || 50) + 1, 10, 99);
        }
      }
    }
    if (isDip) {
      const r1 = relOf(world, origin.id, host.id);
      const r2 = relOf(world, host.id, origin.id);
      r1.score = r2.score = clamp(rnd1((r1.score || 45) - 5), 0, 100);
    }
    if (isCeo) {
      origin.gdpB = rnd1(Math.max(5, (origin.gdpB || 50) * 0.998));
    }

    // 4. Extradition demand: relation -= 6
    const rAB = relOf(world, origin.id, host.id);
    const rBA = relOf(world, host.id, origin.id);
    rAB.score = rBA.score = clamp(rnd1((rAB.score || 45) - 6), 0, 100);
    if (rAB.score < 28 && rAB.status === 'Peace') {
      setDiplomaticStatus(world, origin.id, host.id, 'Hostile');
    }

    const assetLabel = getDefectorSecretAssetLabelV240(oldPost, npc);
    const defId = `DEF_${world.year || 2026}_${world.defectionV240.nextId++}`;
    const defRecord = {
      id: defId,
      npcId: npc.id,
      npcName: npc.name,
      oldPost,
      oldPostTitle,
      fromStateId: origin.id,
      toStateId: host.id,
      hostCityId: hostCap ? hostCap.id : null,
      motive: chosenMotive,
      motiveLabelTh: motiveObj.labelTh,
      assetLabel,
      tick: world.tick || 0,
      date: world.dateString || `Y${world.year || 2026}`
    };

    world.defectionV240.defectors.unshift(defRecord);
    if (world.defectionV240.defectors.length > 80) {
      const overflow = world.defectionV240.defectors.pop();
      world.defectionV240.archive.unshift(overflow);
      if (world.defectionV240.archive.length > 60) world.defectionV240.archive.length = 60;
    }

    const tplPool = DEFECTION_TEMPLATES_V240[chosenMotive] || DEFECTION_TEMPLATES_V240.IDEOLOGICAL_DISILLUSION;
    const defTxt = formatDisasterTemplateV240(rng.pick(tplPool), {
      npc: npc.name,
      oldPost: oldPostTitle,
      origin: shortNameTh(origin),
      host: shortNameTh(host),
      hostCity: hostCap ? cityNameTh(hostCap) : shortNameTh(host),
      asset: assetLabel
    });

    addChronicle(world, 'DEFECTION', defTxt, origin.id, {
      personId: npc.id,
      targetStateId: host.id,
      secondStateId: host.id,
      cityId: hostCap ? hostCap.id : null,
      defectionId: defId
    });

    const extTpl = rng.pick(DEFECTION_EXTRADITION_TEMPLATES_V240);
    const extTxt = formatDisasterTemplateV240(extTpl, {
      origin: shortNameTh(origin),
      host: shortNameTh(host),
      npc: npc.name,
      oldPost: oldPostTitle,
      relScore: rAB.score.toFixed(1)
    });
    addChronicle(world, 'DEFECTION', extTxt, origin.id, {
      personId: npc.id,
      targetStateId: host.id,
      secondStateId: host.id,
      defectionId: defId
    });

    if (rng.chance(0.55)) {
      const debTpl = rng.pick(DEFECTION_DEBRIEF_TEMPLATES_V240);
      const debTxt = formatDisasterTemplateV240(debTpl, {
        host: shortNameTh(host),
        origin: shortNameTh(origin),
        npc: npc.name,
        oldPost: oldPostTitle,
        asset: assetLabel
      });
      addChronicle(world, 'DEFECTION', debTxt, host.id, {
        personId: npc.id,
        targetStateId: origin.id,
        secondStateId: origin.id,
        defectionId: defId
      });
    }

    recordNPCMemory(npc, world.year, `แปรพักตร์จาก ${shortNameTh(origin)} ไปยัง ${shortNameTh(host)} พร้อม "${assetLabel}" (${motiveObj.labelTh})`);

    // 30% chance to trigger TRAITOR_HUNT assassination plot
    if (rng.chance(0.30) && typeof startAssassinationPlotV240 === 'function') {
      startAssassinationPlotV240(world, {
        sponsorId: origin.id,
        targetId: npc.id,
        kind: 'TRAITOR_HUNT'
      });
    }

    return { ok: true, id: defId, defection: defRecord };
  }

  function runDefectionCycleV240(world, rngInstance = null) {
    if (!world || !world.npcs || !world.states) return;
    ensureDefectionsAndPlotsV240(world);
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + (world.tick || 1) * 6299);

    const eligibleRoles = new Set([
      'ARMY_CHIEF', 'NAVY_CHIEF', 'AIR_FORCE_CHIEF', 'SUPREME_COMMANDER',
      'DEFENSE_MINISTER', 'INTELLIGENCE_CHIEF', 'CHIEF_SCIENTIST',
      'DIPLOMAT', 'FOREIGN_MINISTER', 'CEO_DIRECTOR', 'THEATER_COMMANDER'
    ]);

    const stateList = Object.values(world.states).filter((st) => st && !st.isExiled && !(world.aiSandbox === false && st.id === world.playerStateId));
    if (stateList.length === 0) return;
    const roleArr = Array.from(eligibleRoles);
    const candidates = [];
    const stStart = rng.int(0, stateList.length - 1);
    for (let k = 0; k < Math.min(12, stateList.length); k++) {
      const st = stateList[(stStart + k * 5) % stateList.length];
      const pos = st.positions || {};
      const rKey = roleArr[(k + world.tick) % roleArr.length];
      const nid = pos[rKey] || pos.ARMY_CHIEF || pos.INTELLIGENCE_CHIEF || pos.FOREIGN_MINISTER || pos.SUPREME_COMMANDER;
      const n = nid && world.npcs[nid];
      if (n && n.alive && !n.retired && !n.defection) candidates.push(n);
    }
    if (candidates.length === 0) return;
    const sampleCount = candidates.length;
    const startIdx = 0;
    const stride = 1;

    for (let i = 0; i < sampleCount; i++) {
      const npc = candidates[(startIdx + i * stride) % candidates.length];
      if (!npc || npc.defection) continue;
      const risk = defectionRiskV240(world, npc);
      if (risk > 72) {
        const p = 0.06 + (risk - 72) * 0.01;
        if (rng.chance(p)) {
          startDefectionV240(world, npc.id, null, null, rng);
          break; // at most 1 spontaneous defection per cycle to keep chronicle balanced
        }
      }
    }
  }

  // =========================================================================
  // T7.2 — ASSASSINATION PLOTS
  // =========================================================================

  function computeAssassinationSuccessPV240(world, plotOrOpts) {
    if (!plotOrOpts) return 0.15;
    if (typeof plotOrOpts.forceSuccessP === 'number') {
      return clamp(plotOrOpts.forceSuccessP, 0.03, 0.99);
    }
    const planner = (plotOrOpts.plannerId && world && world.npcs && world.npcs[plotOrOpts.plannerId]) || plotOrOpts.planner || null;
    const target = (plotOrOpts.targetId && world && world.npcs && world.npcs[plotOrOpts.targetId]) || plotOrOpts.target || null;
    const targetState = (target && world && world.states && world.states[target.stateId]) || plotOrOpts.targetState || null;
    const sponsorId = plotOrOpts.sponsorStateId || plotOrOpts.sponsorId || (planner && planner.stateId) || null;

    const plannerIntel = planner ? (planner.intelligenceAbility ?? planner.intelligence ?? 70) : (plotOrOpts.plannerAbility ?? 70);
    let networkStrength = plotOrOpts.networkStrength ?? 40;
    if (world && world.spyNetworks && sponsorId && targetState && sponsorId !== targetState.id) {
      const net = world.spyNetworks[`${sponsorId}_${targetState.id}`];
      if (net && typeof net.networkStrength === 'number') networkStrength = net.networkStrength;
    }

    const baseSupp = (targetState && targetState.underground && typeof targetState.underground.intelSuppression === 'number')
      ? targetState.underground.intelSuppression
      : 40;
    const isHead = target && (target.positionId === 'HEAD_OF_STATE' || (targetState && targetState.positions?.HEAD_OF_STATE === target.id));
    let inSafeCity = true;
    if (target && world && world.cities) {
      const c = world.cities[target.currentCityId || target.assignedNodeId || ''];
      if (c) inSafeCity = c.isFrontline === false;
    }
    const targetSecurity = baseSupp + (isHead ? 25 : 0) + (inSafeCity ? 10 : 0);

    const rawP = 0.12 + 0.003 * plannerIntel + 0.002 * networkStrength - 0.004 * targetSecurity;
    return +(clamp(rawP, 0.03, 0.55)).toFixed(4);
  }

  function rollAssassinationAttributionV240(world, plot, rngInstance = null) {
    const rng = rngInstance || new SeededRNG((world && world.seed ? world.seed : 2026) + ((plot && plot.id ? String(plot.id).length : 1) * 919));
    const u = rng.next();
    const target = plot && plot.targetId && world && world.npcs ? world.npcs[plot.targetId] : null;
    const victimState = (target && world && world.states && world.states[target.stateId]) || null;

    if (u < 0.45) {
      return {
        kind: 'TRUE_SPONSOR',
        attributedStateId: (plot && plot.sponsorStateId) || (victimState ? victimState.id : null)
      };
    }
    if (u < 0.65) {
      let rivalId = null;
      if (victimState) {
        const rivals = (victimState.rivalries || []).filter((rid) => rid !== (plot && plot.sponsorStateId) && world.states[rid]);
        if (rivals.length > 0) rivalId = rng.pick(rivals);
        else {
          const otherIds = Object.keys(world.states || {}).filter((sid) => sid !== victimState.id && sid !== (plot && plot.sponsorStateId));
          if (otherIds.length > 0) rivalId = rng.pick(otherIds);
        }
      }
      return {
        kind: 'FALSE_FLAG',
        attributedStateId: rivalId || 'US'
      };
    }
    return {
      kind: 'UNKNOWN',
      attributedStateId: null
    };
  }

  function startAssassinationPlotV240(world, opts = {}) {
    if (!world || !world.states || !world.npcs) return { ok: false, reason: 'ไม่พบข้อมูลโลก' };
    ensureDefectionsAndPlotsV240(world);

    const sponsorId = opts.sponsorId || opts.sponsorStateId || null;
    const targetId = opts.targetId;
    const kind = opts.kind || (sponsorId ? 'FOREIGN_OP' : 'DOMESTIC_COUP_PLOT');
    const chainDepth = Number(opts.chainDepth || 0);

    if (chainDepth > 3) {
      return { ok: false, reason: 'ห่วงโซ่การลอบสังหารตอบโต้เกินขีดจำกัดสูงสุด 3 ขั้นแล้ว' };
    }

    const target = typeof targetId === 'object' ? targetId : world.npcs[targetId];
    if (!target || !target.alive) return { ok: false, reason: 'ไม่พบเป้าหมายหรือเป้าหมายเสียชีวิตแล้ว' };

    const targetState = world.states[target.stateId];
    if (!targetState) return { ok: false, reason: 'ไม่พบรัฐของเป้าหมาย' };

    if (world.assassinationV240.plots.length >= 8) {
      return { ok: false, reason: 'มีแผนลอบสังหารที่กำลังดำเนินอยู่ครบเพดาน 8 แผนทั่วโลกแล้ว' };
    }

    const rng = opts.rng || new SeededRNG((world.seed || 2026) + (world.tick || 1) * 7127 + (world.assassinationV240.nextId || 1) * 53);

    let planner = opts.plannerId ? world.npcs[opts.plannerId] : null;
    if (!planner) {
      if (sponsorId && world.states[sponsorId]) {
        const sp = world.states[sponsorId];
        planner = (sp.positions?.INTELLIGENCE_CHIEF && world.npcs[sp.positions.INTELLIGENCE_CHIEF]) ||
          (sp.positions?.SUPREME_COMMANDER && world.npcs[sp.positions.SUPREME_COMMANDER]) ||
          (sp.positions?.HEAD_OF_STATE && world.npcs[sp.positions.HEAD_OF_STATE]) ||
          Object.values(world.npcs).find((n) => n && n.alive && n.stateId === sponsorId && n.id !== target.id);
      } else {
        planner = Object.values(world.npcs)
          .filter((n) => n && n.alive && !n.retired && n.stateId === targetState.id && n.id !== target.id)
          .sort((a, b) => (b.coupReadiness || 20) - (a.coupReadiness || 20))[0] || null;
      }
    }

    const pId = `PLOT_${world.year || 2026}_${world.assassinationV240.nextId++}`;
    const planningDuration = opts.planningDays || rng.int(10, 40);
    const plotObj = {
      id: pId,
      kind,
      sponsorStateId: sponsorId || (kind === 'DOMESTIC_COUP_PLOT' ? targetState.id : null),
      plannerId: planner ? planner.id : null,
      targetId: target.id,
      targetStateId: targetState.id,
      stage: 'PLANNING',
      stageDay: 0,
      planningDuration,
      quality: 50,
      chainDepth,
      outcome: null,
      attributedTo: null,
      attributionKind: null,
      log: [
        {
          tick: world.tick || 0,
          text: `🗡️ เริ่มวางแผนปฏิบัติการลับ (${kind}) เป้าหมาย: ${target.name} แห่ง ${shortNameTh(targetState)}`
        }
      ]
    };

    if (planner) {
      recordNPCMemory(planner, world.year, `เริ่มวางแผนปฏิบัติการลอบสังหาร (${kind}) ต่อเป้าหมาย ${target.name}`);
    }

    world.assassinationV240.plots.unshift(plotObj);
    return { ok: true, id: pId, plot: plotObj };
  }

  function resolveAssassinationV240(world, plotOrId, opts = {}) {
    if (!world || !world.states || !world.npcs) return { ok: false, reason: 'ไม่พบข้อมูลโลก' };
    ensureDefectionsAndPlotsV240(world);
    const plot = typeof plotOrId === 'string'
      ? (world.assassinationV240.plots.find((p) => p.id === plotOrId) || world.assassinationV240.archive.find((p) => p.id === plotOrId))
      : plotOrId;
    if (!plot) return { ok: false, reason: 'ไม่พบแผนลอบสังหาร' };

    const rng = opts.rng || new SeededRNG((world.seed || 2026) + (world.tick || 1) * 7331 + String(plot.id).length * 41);
    const target = world.npcs[plot.targetId];
    const planner = plot.plannerId ? world.npcs[plot.plannerId] : null;
    const victimState = (target && world.states[target.stateId]) || world.states[plot.targetStateId];
    const sponsorState = plot.sponsorStateId ? world.states[plot.sponsorStateId] : null;

    if (!target || !target.alive || !victimState) {
      plot.stage = 'RESOLVED';
      plot.outcome = 'ABORTED';
      return { ok: true, outcome: 'ABORTED', plot };
    }

    // Check if planner died/retired/defected unless forceOutcome is passed
    if (!opts.forceOutcome && planner && (!planner.alive || planner.retired || (planner.defection && planner.stateId !== plot.sponsorStateId))) {
      plot.stage = 'RESOLVED';
      plot.outcome = 'ABORTED';
      plot._leakAtTick = (world.tick || 0) + 30;
      return { ok: true, outcome: 'ABORTED', plot };
    }

    const successP = opts.forceSuccessP !== undefined
      ? clamp(Number(opts.forceSuccessP), 0, 1)
      : computeAssassinationSuccessPV240(world, plot);

    let outcome = opts.forceOutcome || null;
    if (!outcome) {
      if (rng.chance(successP)) {
        outcome = 'SUCCESS';
      } else {
        outcome = rng.chance(0.45) ? 'FAILED_CAUGHT' : 'FAILED_ESCAPED';
      }
    }

    plot.stage = 'RESOLVED';
    plot.outcome = outcome;

    const attr = rollAssassinationAttributionV240(world, plot, rng);
    plot.attributionKind = attr.kind;
    plot.attributedTo = attr.attributedStateId;

    const oldRole = target.positionId || 'SENIOR_OFFICIAL';
    const oldRoleTitle = target.positionTitle || oldRole;
    const wasHead = oldRole === 'HEAD_OF_STATE' || victimState.positions?.HEAD_OF_STATE === target.id;
    const wasGeneral = ['SUPREME_COMMANDER', 'ARMY_CHIEF', 'NAVY_CHIEF', 'AIR_FORCE_CHIEF', 'DEFENSE_MINISTER', 'THEATER_COMMANDER', 'BASE_COMMANDER'].includes(oldRole) || target.track === 'military';
    const wasSci = ['CHIEF_SCIENTIST', 'CTO_EXECUTIVE', 'PROFESSOR_ACADEMIC'].includes(oldRole);
    const wasDefector = !!target.defection || plot.kind === 'TRAITOR_HUNT';

    if (outcome === 'SUCCESS') {
      // Addendum Link 3: Vacate through unassignNPCFromPosts, handleNPCDeath, handleNPCSuccession, mark logisticsDirty & vacancyDirty, update fieldArmies led by killed commander
      const affectedArmies = Object.values(world.fieldArmies || {}).filter(
        (fa) => fa && (fa.commanderId === target.id || (wasGeneral && fa.stateId === victimState.id && !fa.commanderId))
      );

      handleNPCSuccession(world, target, 'death', 'ถูกลอบสังหาร');
      handleNPCDeath(world, target, 'ถูกลอบสังหาร');
      unassignNPCFromPosts(world, target);
      victimState.logisticsDirty = true;
      victimState.vacancyDirty = true;
      

      const successorId = wasHead ? victimState.positions?.HEAD_OF_STATE : victimState.positions?.[oldRole];
      const successor = successorId ? world.npcs[successorId] : null;

      recordNPCMemory(target, world.year, `ถูกลอบสังหารเสียชีวิตขณะดำรงตำแหน่ง ${oldRoleTitle}`);
      if (planner) recordNPCMemory(planner, world.year, `ปฏิบัติการลอบสังหาร ${target.name} สำเร็จลุล่วง`);
      if (successor) recordNPCMemory(successor, world.year, `ขึ้นดำรงตำแหน่งสืบต่อจาก ${target.name} ที่ถูกลอบสังหาร`);

      const bucketKey = wasDefector ? 'DEFECTOR' : wasHead ? 'HEAD' : wasGeneral ? 'GENERAL' : wasSci ? 'SCIENTIST' : 'HEAD';
      const sucPool = ASSASSINATION_SUCCESS_TEMPLATES_V240[bucketKey] || ASSASSINATION_SUCCESS_TEMPLATES_V240.HEAD;
      const sucTxt = formatDisasterTemplateV240(rng.pick(sucPool), {
        target: target.name,
        role: oldRoleTitle,
        state: shortNameTh(victimState)
      });
      plot.log.unshift({ tick: world.tick, text: sucTxt });
      addChronicle(world, 'ASSASSINATION', sucTxt, victimState.id, {
        personId: target.id,
        targetStateId: plot.attributedTo || victimState.id,
        plotId: plot.id
      });

      if (wasHead) {
        if (['Democracy', 'Constitutional_Monarchy'].includes(victimState.regimeCategory)) {
          victimState.approval = clamp(rnd1((victimState.approval || 65) + 8), 5, 99);
          victimState.stability = clamp(rnd1((victimState.stability || 70) - 6), 3, 99);
          const funTxt = `🕯️🏛️ [รัฐพิธีศพประมุขแห่งรัฐท่ามกลางคลื่นมหาชน] ประชาชนใน ${shortNameTh(victimState)} ร่วมไว้อาลัยแก่ ${target.name} อย่างมืดฟ้ามัวดิน ดันคะแนนความเห็นใจต่อรัฐบาลเพิ่มขึ้น (+8% Approval) ขณะที่ผู้สืบทอด ${successor ? successor.name : ''} ให้คำมั่นจะนำตัวผู้บงการมาลงโทษ`;
          addChronicle(world, 'ASSASSINATION', funTxt, victimState.id, { personId: target.id, plotId: plot.id });
        } else {
          victimState.stability = clamp(rnd1((victimState.stability || 70) - 15), 3, 99);
          Object.values(world.npcs || {}).forEach((n) => {
            if (n && n.alive && !n.retired && n.stateId === victimState.id && (n.tier >= 2 || n.stage >= 5)) {
              n.coupReadiness = clamp((n.coupReadiness || 20) + 6, 0, 100);
              n.grievance = clamp((n.grievance || 20) + 4, 0, 100);
            }
          });
          if (rng.chance(0.30)) {
            const topGen = [victimState.positions?.SUPREME_COMMANDER, victimState.positions?.ARMY_CHIEF, victimState.positions?.DEFENSE_MINISTER]
              .map((id) => id && world.npcs[id])
              .find((n) => n && n.alive && !n.retired);
            if (topGen) {
              triggerMilitaryCoup(world, topGen);
            }
          }
        }
      }

      if (wasGeneral) {
        if (!victimState.militaryReadiness) ensureStateDeepProfileV170(world, victimState);
        victimState.militaryReadiness.morale = clamp((victimState.militaryReadiness.morale || 75) - 6, 10, 100);
        getWarsOf(world, victimState.id).forEach((w) => {
          (w.fronts || []).forEach((f) => {
            if (w.attackerId === victimState.id && f.attackerMorale !== undefined) f.attackerMorale = Math.max(10, f.attackerMorale - 15);
            if (w.defenderId === victimState.id && f.defenderMorale !== undefined) f.defenderMorale = Math.max(10, f.defenderMorale - 15);
          });
        });
        // Addendum Link 3 & Test (d): Field armies led by killed commander lose morale/readiness by 8 and get a new commander
        affectedArmies.forEach((fa) => {
          fa.morale = clamp((fa.morale ?? 80) - 8, 10, 100);
          fa.readiness = clamp((fa.readiness ?? 80) - 8, 10, 100);
          const newCmd = selectBestCandidateForRole(world, victimState.id, 'ARMY_CHIEF', null, rng);
          fa.commanderId = newCmd && newCmd.id !== target.id ? newCmd.id : null;
        });
      }

      // Attribution chronicle & diplomatic/retaliation fallout
      const accusedState = plot.attributedTo ? world.states[plot.attributedTo] : null;
      const attrPool = ASSASSINATION_ATTRIBUTION_TEMPLATES_V240[attr.kind] || ASSASSINATION_ATTRIBUTION_TEMPLATES_V240.UNKNOWN;
      const attrTxt = formatDisasterTemplateV240(rng.pick(attrPool), {
        state: shortNameTh(victimState),
        target: target.name,
        accused: accusedState ? shortNameTh(accusedState) : 'กลุ่มปฏิบัติการนิรนาม'
      });
      plot.log.unshift({ tick: world.tick, text: attrTxt });
      addChronicle(world, 'ASSASSINATION', attrTxt, victimState.id, {
        personId: target.id,
        targetStateId: accusedState ? accusedState.id : victimState.id,
        secondStateId: accusedState ? accusedState.id : null,
        plotId: plot.id
      });

      if (accusedState && accusedState.id !== victimState.id) {
        const rAB = relOf(world, victimState.id, accusedState.id);
        const rBA = relOf(world, accusedState.id, victimState.id);
        rAB.score = rBA.score = clamp(rnd1((rAB.score || 50) - 25), 0, 100);
        if (rAB.status === 'Peace' && rAB.score < 30) {
          setDiplomaticStatus(world, victimState.id, accusedState.id, 'Hostile');
        }
        if (attr.kind === 'TRUE_SPONSOR' && sponsorState && sponsorState.trustV230 !== undefined) {
          sponsorState.trustV230 = clamp(rnd1((sponsorState.trustV230 || 70) - 15), 0, 100);
        }

        const newHead = (victimState.positions?.HEAD_OF_STATE && world.npcs[victimState.positions.HEAD_OF_STATE]) || successor;
        const headAggr = newHead ? (newHead.personality?.aggression ?? 55) : 55;
        let retKindLabel = 'มาตรการคว่ำบาตรระดับ 3';
        const activeWarsCnt = (world.wars || []).filter((w) => w.status === 'War').length;
        if (headAggr > 60 && activeWarsCnt < 6 && rng.chance(0.18)) {
          setDiplomaticStatus(world, victimState.id, accusedState.id, 'War');
          retKindLabel = 'การประกาศสงครามตอบโต้เต็มรูปแบบ';
        } else if (typeof imposeTradeMeasureV230 === 'function') {
          imposeTradeMeasureV230(world, victimState.id, accusedState.id, 3, 'RIVALRY');
        }

        // Retaliation chain (REVENGE plot; max chain length 3)
        if (wasHead && (plot.chainDepth || 0) < 3 && rng.chance(0.20)) {
          const enemyLeaderId = accusedState.positions?.HEAD_OF_STATE || accusedState.positions?.PRIME_MINISTER;
          if (enemyLeaderId && world.npcs[enemyLeaderId]) {
            startAssassinationPlotV240(world, {
              sponsorId: victimState.id,
              targetId: enemyLeaderId,
              kind: 'REVENGE',
              chainDepth: (plot.chainDepth || 0) + 1,
              rng
            });
            retKindLabel = `แผนลอบสังหารเอาคืน (REVENGE ขั้นที่ ${(plot.chainDepth || 0) + 1})`;
          }
        }

        const retTpl = rng.pick(ASSASSINATION_RETALIATION_TEMPLATES_V240);
        const retTxt = formatDisasterTemplateV240(retTpl, {
          victim: shortNameTh(victimState),
          accused: shortNameTh(accusedState),
          target: target.name,
          retaliationKind: retKindLabel,
          depth: Math.min(3, (plot.chainDepth || 0) + 1)
        });
        addChronicle(world, 'ASSASSINATION', retTxt, victimState.id, {
          personId: target.id,
          targetStateId: accusedState.id,
          secondStateId: accusedState.id,
          plotId: plot.id
        });
      }
    } else if (outcome === 'FAILED_CAUGHT') {
      recordNPCMemory(target, world.year, `รอดชีวิตจากแผนลอบสังหาร (${plot.kind}) และจับกุมผู้ก่อเหตุได้สำเร็จ`);
      if (planner) recordNPCMemory(planner, world.year, `แผนลอบสังหาร ${target.name} ล้มเหลวและถูกเปิดโปง`);

      const survTpl = rng.pick(ASSASSINATION_SURVIVED_TEMPLATES_V240);
      const survTxt = formatDisasterTemplateV240(survTpl, {
        state: shortNameTh(victimState),
        target: target.name,
        role: oldRoleTitle
      });
      plot.log.unshift({ tick: world.tick, text: survTxt });
      addChronicle(world, 'ASSASSINATION', survTxt, victimState.id, {
        personId: target.id,
        plotId: plot.id
      });

      victimState.approval = clamp(rnd1((victimState.approval || 65) + 4), 5, 99);

      if (plot.kind === 'DOMESTIC_COUP_PLOT') {
        // Purge: up to 4 NPCs linked by relationships or same faction are handleNPCSuccession(..., 'arrested', ...)
        const plotterFaction = planner ? planner.faction : null;
        const linkedIds = new Set();
        if (planner && Array.isArray(planner.relationships)) {
          planner.relationships.forEach((rel) => {
            if (rel && rel.targetNpcId) linkedIds.add(rel.targetNpcId);
          });
        }
        const purgePool = Object.values(world.npcs || {}).filter(
          (n) => n && n.alive && !n.retired && n.stateId === victimState.id && n.id !== target.id &&
            (n.id === (planner && planner.id) || linkedIds.has(n.id) || (plotterFaction && n.faction === plotterFaction))
        );
        const toPurge = [];
        if (planner && planner.alive) toPurge.push(planner);
        purgePool.forEach((n) => { if (toPurge.length < 4 && !toPurge.includes(n)) toPurge.push(n); });

        toPurge.forEach((pNpc) => {
          handleNPCSuccession(world, pNpc, 'arrested', 'ถูกกวาดล้างฐานร่วมแผนลอบสังหารและกบฏ');
          unassignNPCFromPosts(world, pNpc);
          pNpc.imprisonedUntilTick = (world.tick || 0) + 540;
          pNpc.retired = true;
          recordNPCMemory(pNpc, world.year, `ถูกจับกุมในปฏิบัติการกวาดล้างหลังแผนลอบสังหาร ${target.name} ล้มเหลว`);
        });
        

        if (!victimState.underground) victimState.underground = { active: true, dissidentNetwork: 20, militaryPlotLevel: 25, intelSuppression: 65 };
        victimState.underground.militaryPlotLevel = clamp(rnd1((victimState.underground.militaryPlotLevel || 25) - 25), 0, 100);

        const purgeTpl = rng.pick(ASSASSINATION_PURGE_TEMPLATES_V240);
        const purgeTxt = formatDisasterTemplateV240(purgeTpl, {
          target: target.name,
          state: shortNameTh(victimState),
          count: Math.max(1, toPurge.length)
        });
        plot.log.unshift({ tick: world.tick, text: purgeTxt });
        addChronicle(world, 'ASSASSINATION', purgeTxt, victimState.id, {
          personId: target.id,
          plotId: plot.id
        });
      } else if (sponsorState && sponsorState.id !== victimState.id) {
        const rAB = relOf(world, victimState.id, sponsorState.id);
        const rBA = relOf(world, sponsorState.id, victimState.id);
        rAB.score = rBA.score = clamp(rnd1((rAB.score || 45) - 20), 0, 100);
        if (rAB.status === 'Peace' && rAB.score < 30) {
          setDiplomaticStatus(world, victimState.id, sponsorState.id, 'Hostile');
        }
        if (sponsorState.trustV230 !== undefined) {
          sponsorState.trustV230 = clamp(rnd1((sponsorState.trustV230 || 70) - 10), 0, 100);
        }
        if (typeof imposeTradeMeasureV230 === 'function') {
          imposeTradeMeasureV230(world, victimState.id, sponsorState.id, 2, 'ESPIONAGE_RETALIATION');
        }
      }
    } else {
      // FAILED_ESCAPED or ABORTED: stealth, only target learns now, 40% chance after 30 days a story reveals it
      recordNPCMemory(target, world.year, `ได้รับรายงานลับสุดยอดว่ามีความพยายามลอบสังหารตนเอง (${plot.kind}) แต่คนร้ายหลบหนีไปได้`);
      if (planner) recordNPCMemory(planner, world.year, `ต้องถอนตัวจากแผนลอบสังหาร ${target.name} อย่างเงียบเชียบ`);
      plot._leakAtTick = (world.tick || 0) + 30;
    }

    // Move from active plots to archive if currently in active
    const idx = world.assassinationV240.plots.indexOf(plot);
    if (idx >= 0) {
      world.assassinationV240.plots.splice(idx, 1);
    }
    if (!world.assassinationV240.archive.includes(plot)) {
      world.assassinationV240.archive.unshift(plot);
      if (world.assassinationV240.archive.length > 60) world.assassinationV240.archive.length = 60;
    }

    return { ok: true, outcome, attribution: attr, plot };
  }

  function runAssassinationCycleV240(world, rngInstance = null) {
    if (!world || !world.states || !world.npcs) return;
    ensureDefectionsAndPlotsV240(world);
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + (world.tick || 1) * 7541);

    // 1. Check delayed 30-day leak stories on archived FAILED_ESCAPED / ABORTED plots
    world.assassinationV240.archive.forEach((p) => {
      if (p && p._leakAtTick && world.tick >= p._leakAtTick && !p._leakHandled) {
        p._leakHandled = true;
        if (rng.chance(0.40)) {
          const tNpc = world.npcs[p.targetId];
          const vSt = world.states[p.targetStateId];
          if (tNpc && vSt) {
            const leakTpl = rng.pick(ASSASSINATION_PLOT_LEAKED_TEMPLATES_V240);
            const leakTxt = formatDisasterTemplateV240(leakTpl, {
              target: tNpc.name,
              state: shortNameTh(vSt),
              kind: p.kind
            });
            addChronicle(world, 'ASSASSINATION', leakTxt, vSt.id, {
              personId: tNpc.id,
              plotId: p.id
            });
          }
        }
      }
    });

    // 2. Advance active plots (cycle runs every 13 ticks -> advance stageDay by 13)
    const active = world.assassinationV240.plots;
    for (let i = active.length - 1; i >= 0; i--) {
      const p = active[i];
      p.stageDay = (p.stageDay || 0) + 13;
      const planner = p.plannerId ? world.npcs[p.plannerId] : null;
      const sponsor = p.sponsorStateId ? world.states[p.sponsorStateId] : null;
      const pAbil = planner ? (planner.intelligenceAbility ?? planner.intelligence ?? 70) : 70;
      const cyber = sponsor?.nuclear?.cyberPower ?? 65;
      p.quality = clamp(Math.round((p.quality || 50) + (pAbil * 0.05 + cyber * 0.04)), 20, 99);

      if (p.stage === 'PLANNING' && p.stageDay >= (p.planningDuration || 20)) {
        p.stage = 'EXECUTION';
        p.stageDay = 0;
      } else if (p.stage === 'EXECUTION') {
        resolveAssassinationV240(world, p, { rng });
      }
    }

    // 3. Spontaneous AI plot spawning (when active.length < 8)
    if (world.assassinationV240.plots.length >= 8) return;
    const allLive = Object.values(world.states).filter((s) => !s.isExiled);

    // (a) FOREIGN_OP: pairs at war or Hostile (score < 20) where sponsor's spyNetworks or cyberPower is high
    for (let i = 0; i < allLive.length && world.assassinationV240.plots.length < 8; i++) {
      const sp = allLive[i];
      if (world.aiSandbox === false && sp.id === world.playerStateId) continue;
      const cyber = sp.nuclear?.cyberPower ?? 60;
      if (cyber < 65 && (sp.militaryReadiness?.intelligence || 70) < 75) continue;

      const enemies = allLive.filter((o) => {
        if (o.id === sp.id) return false;
        const r = relOf(world, sp.id, o.id);
        return r.status === 'War' || (r.status === 'Hostile' && (r.score || 30) < 20);
      });
      if (enemies.length > 0 && rng.chance(0.015)) {
        const enemy = rng.pick(enemies);
        const targetRoles = ['HEAD_OF_STATE', 'SUPREME_COMMANDER', 'CHIEF_SCIENTIST'];
        const tIds = targetRoles.map((r) => enemy.positions?.[r]).filter((id) => id && world.npcs[id] && world.npcs[id].alive);
        if (tIds.length > 0) {
          startAssassinationPlotV240(world, {
            sponsorId: sp.id,
            targetId: rng.pick(tIds),
            kind: 'FOREIGN_OP',
            rng
          });
          break;
        }
      }
    }

    // (b) DOMESTIC_COUP_PLOT: state with underground.militaryPlotLevel >= 35 or NPC with coupReadiness >= 60
    if (world.assassinationV240.plots.length < 8) {
      for (let i = 0; i < allLive.length; i++) {
        const st = allLive[i];
        if (world.aiSandbox === false && st.id === world.playerStateId) continue;
        const headId = st.positions?.HEAD_OF_STATE;
        if (!headId || !world.npcs[headId] || !world.npcs[headId].alive) continue;

        const plotLvl = st.underground?.militaryPlotLevel || 0;
        const pos = st.positions || {};
        const candIds = [pos.SUPREME_COMMANDER, pos.ARMY_CHIEF, pos.DEFENSE_MINISTER, pos.INTELLIGENCE_CHIEF, pos.OPPOSITION_LEADER];
        let plotter = null;
        for (let cIdx = 0; cIdx < candIds.length; cIdx++) {
          const cn = candIds[cIdx] && world.npcs[candIds[cIdx]];
          if (cn && cn.alive && !cn.retired && cn.id !== headId && ((cn.coupReadiness || 0) >= 60 || plotLvl >= 35)) {
            plotter = cn;
            break;
          }
        }
        if (plotter && rng.chance(0.01)) {
          startAssassinationPlotV240(world, {
            sponsorId: st.id,
            plannerId: plotter.id,
            targetId: headId,
            kind: 'DOMESTIC_COUP_PLOT',
            rng
          });
          break;
        }
      }
    }
  }

  // =========================================================================
  // MASTER V2.4.0 ENSURE & CROSS-SYSTEM INTEGRATION WRAPPERS
  // =========================================================================

  function ensureWorldSystemsV240(world) {
    if (!world || !world.states) return world;
    ensureDisastersV240(world);
    ensureScandalsV240(world);
    ensureDefectionsAndPlotsV240(world);
    // Ensure fieldArmies have commanderId, morale, readiness (Addendum Link 3)
    Object.values(world.fieldArmies || {}).forEach((fa) => {
      if (!fa) return;
      const st = world.states[fa.stateId];
      if (fa.commanderId === undefined) {
        fa.commanderId = (st && (st.positions?.ARMY_CHIEF || st.positions?.SUPREME_COMMANDER)) || null;
      }
      if (fa.morale === undefined) fa.morale = st?.militaryReadiness?.morale ?? 80;
      if (fa.readiness === undefined) fa.readiness = st?.militaryReadiness?.personnelReadiness ?? 80;
    });
    world._v240 = true;
    return world;
  }

  // Addendum Link 1 & T6.2: Wrap setCentralBankPolicyV210 to support 'issue_bonds', 'qe_stimulus', 'accumulate_gold', and record lastRateChangeTick
  const _origSetCentralBankPolicyV240 = setCentralBankPolicyV210;
  setCentralBankPolicyV210 = function (world, stateId, actionType = 'hike_rate', value = null) {
    ensureGlobalFinanceAndCurrencyV210(world);
    const st = world && world.states ? world.states[stateId] : null;
    if (st && st.centralBank && (actionType === 'hike_rate' || actionType === 'cut_rate')) {
      st.centralBank.lastRateChangeTick = world.tick || 0;
    }
    if (actionType === 'issue_bonds') {
      return _origSetCentralBankPolicyV240(world, stateId, 'issue_sovereign_bonds', value);
    }
    if (actionType === 'accumulate_gold') {
      return _origSetCentralBankPolicyV240(world, stateId, 'shift_reserves_to_gold_brics', value);
    }
    if (actionType === 'qe_stimulus' && st && st.centralBank && st.sovereignDebt) {
      const cb = st.centralBank;
      const debt = st.sovereignDebt;
      const qeB = value || Math.max(15, Math.round(st.gdpB * 0.03));
      st.treasuryB = rnd1(Math.max(0, (st.treasuryB || 0) + qeB));
      debt.totalDebtB = rnd1((debt.totalDebtB || 0) + qeB * 0.75);
      debt.debtToGdpPct = +((debt.totalDebtB / Math.max(50, st.gdpB)) * 100).toFixed(1);
      cb.inflationPct = +(clamp((cb.inflationPct || 2.5) + 0.65, 0.2, 120.0)).toFixed(1);
      cb.monetaryStance = 'QE_STIMULUS';
      recomputeCreditRatingV210(st);
      const msg = `🏦💸 [มาตรการผ่อนคลายเชิงปริมาณ (QE Stimulus)] ${cb.bankName} อัดฉีดสภาพคล่องฉุกเฉิน $${qeB}B เข้าสู่งบคงคลังและตลาดพันธบัตรของ ${shortNameTh(st)} เพื่อรับมือวิกฤต (หนี้สาธารณะ ${debt.debtToGdpPct}% ของ GDP, เงินเฟ้อ ${cb.inflationPct}%)`;
      addChronicle(world, 'CENTRAL_BANK', msg, stateId);
      return { ok: true, actionType: 'qe_stimulus', centralBank: cb, sovereignDebt: debt, narrative: msg };
    }
    return _origSetCentralBankPolicyV240(world, stateId, actionType, value);
  };

  // Addendum Link 3: Wrap ensureFieldArmiesForWars so new field armies always get commanderId, morale, readiness
  const _origEnsureFieldArmiesV240 = ensureFieldArmiesForWars;
  ensureFieldArmiesForWars = function (world) {
    const res = _origEnsureFieldArmiesV240(world);
    Object.values(world.fieldArmies || {}).forEach((fa) => {
      if (!fa) return;
      const st = world.states[fa.stateId];
      if (!fa.commanderId && st) {
        fa.commanderId = st.positions?.ARMY_CHIEF || st.positions?.SUPREME_COMMANDER || null;
      }
      if (fa.morale === undefined) fa.morale = st?.militaryReadiness?.morale ?? 80;
      if (fa.readiness === undefined) fa.readiness = st?.militaryReadiness?.personnelReadiness ?? 80;
    });
    return res;
  };

  // Addendum Link 3: Wrap runMilitaryReadinessAndBaseLogisticsCycle so active disaster in RELIEF phase lowers logisticsCapacity and personnelReadiness by severity * 1.5
  if (typeof runMilitaryReadinessAndBaseLogisticsCycle === "function") {
    const _origRunMilReadinessV240 = runMilitaryReadinessAndBaseLogisticsCycle;
    runMilitaryReadinessAndBaseLogisticsCycle = function (world, rng) {
      const res = _origRunMilReadinessV240(world, rng);
      if (world && world.disasterV240 && Array.isArray(world.disasterV240.active)) {
        world.disasterV240.active.forEach((d) => {
          if (d && d.phase === "RELIEF" && d._milPenaltyApplied > 0) {
            const st = world.states && world.states[d.stateId];
            if (st && st.militaryReadiness) {
              st.militaryReadiness.logisticsCapacity = clamp(+((st.militaryReadiness.logisticsCapacity || 80) - d._milPenaltyApplied).toFixed(2), 10, 100);
              st.militaryReadiness.personnelReadiness = clamp(+((st.militaryReadiness.personnelReadiness || 80) - d._milPenaltyApplied).toFixed(2), 10, 100);
            }
          }
        });
      }
      return res;
    };
  }

  // Addendum Link 3: Wrap runSmartWarAI to read world._oppV240[enemyId] window of opportunity
  if (typeof runSmartWarAI === 'function') {
    const _origRunSmartWarAIV240 = runSmartWarAI;
    runSmartWarAI = function (world, rng) {
      if (world && world._oppV240) {
        Object.keys(world._oppV240).forEach((sid) => {
          if (world._oppV240[sid] > (world.tick || 0) && world.states && world.states[sid]) {
            const st = world.states[sid];
            const camp = Object.values(world.camps || {}).find((c) => c.stateId === sid);
            if (camp && camp.supplies) {
              camp.supplies.ammo = Math.max(camp.supplies.ammo || 700, 720);
              camp.supplies.fuel = Math.max(camp.supplies.fuel || 700, 720);
            }
          }
        });
      }
      return _origRunSmartWarAIV240(world, rng);
    };
  }

  // Addendum Link 6: Wrap runRnDCycle so researchSlowMonths on researchInstitutes slows researchPoints gain and decays monthly
  if (typeof runRnDCycle === 'function') {
    const _origRunRnDCycleV240 = runRnDCycle;
    runRnDCycle = function (world) {
      const res = _origRunRnDCycleV240(world);
      if (world && world.researchInstitutes) {
        Object.values(world.researchInstitutes).forEach((inst) => {
          if (inst && (inst.researchSlowMonths || 0) > 0) {
            const st = world.states && world.states[inst.stateId];
            if (st) {
              st.researchPoints = Math.max(0, Math.round((st.researchPoints || 0) - 2));
            }
            inst.researchSlowMonths = Math.max(0, inst.researchSlowMonths - 1);
          }
        });
      }
      return res;
    };
  }

  const _origCreateInitialWorldV240 = createInitialWorld;
  createInitialWorld = function (seed = 202611717) {
    const w = _origCreateInitialWorldV240(seed);
    ensureWorldSystemsV240(w);
    return w;
  };

  const _origMigrateWorldV240 = migrateWorld;
  migrateWorld = function (world) {
    if (!world || !world.states) return world;
    _origMigrateWorldV240(world);
    ensureWorldSystemsV240(world);
    return world;
  };

  const _origStepDayV240 = stepDay;
  stepDay = function (world, rngInstance = null) {
    if (!world._v240) ensureWorldSystemsV240(world);
    _origStepDayV240(world, rngInstance);
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + world.tick * 104729);
    const t = world.tick;

    // Cycle offsets required by Section B:
    // - Disaster lifecycle step: t % 2 === 0
    if (t % 2 === 0 && world.disasterV240 && world.disasterV240.active.length > 0) {
      stepDisastersLifecycleV240(world, rng);
    }
    // - Epidemic step: every 5 ticks for active EPIDEMIC disasters
    if (t % 5 === 0 && world.disasterV240 && world.disasterV240.active.some((d) => d.typeId === 'EPIDEMIC')) {
      stepEpidemicsV240(world, rng);
    }
    // - Monthly decay of disaster bondYieldPct addition (0.05/month, Addendum Link 1)
    if (t % 30 === 14) {
      Object.values(world.states).forEach((st) => {
        if (st && st._disasterBondYieldAddV240 > 0 && st.sovereignDebt) {
          const dec = Math.min(0.05, st._disasterBondYieldAddV240);
          st._disasterBondYieldAddV240 = +(st._disasterBondYieldAddV240 - dec).toFixed(2);
          st.sovereignDebt.bondYieldPct = +(Math.max(1.0, (st.sovereignDebt.bondYieldPct || 3.5) - dec)).toFixed(2);
        }
      });
    }
    // - Scandal cycle: t % 7 === 3
    if (t % 7 === 3) {
      runScandalCycleV240(world, rng);
    }
    // - Defection cycle: t % 11 === 5
    if (t % 11 === 5) {
      runDefectionCycleV240(world, rng);
    }
    // - Assassination-plot cycle: t % 13 === 8
    if (t % 13 === 8) {
      runAssassinationCycleV240(world, rng);
    }

    return world;
  };


