  function getCapCityOfStateV250(world, stateId) {
    if (!world || !stateId || !world.cities) return null;
    if (!world._capCityCacheV250) world._capCityCacheV250 = {};
    const cachedId = world._capCityCacheV250[stateId];
    if (cachedId && world.cities[cachedId] && world.cities[cachedId].stateId === stateId) {
      return world.cities[cachedId];
    }
    const cities = Object.values(world.cities);
    let fallback = null;
    for (let i = 0; i < cities.length; i++) {
      const c = cities[i];
      if (c && c.stateId === stateId) {
        if (c.isCapital) {
          world._capCityCacheV250[stateId] = c.id;
          return c;
        }
        if (!fallback) fallback = c;
      }
    }
    if (fallback) world._capCityCacheV250[stateId] = fallback.id;
    return fallback;
  }

  function pickFirstNameV250(world, stateId, gender, rng) {
    const st = world.states && world.states[stateId];
    const pool = (st && NAME_POOLS[st.region]) || NAME_POOLS.NorthAmerica || NAME_POOLS.Thailand;
    const arr = gender === 'F' ? pool.female : pool.male;
    const raw = rng.pick(arr);
    return raw.charAt(0).toUpperCase() + raw.slice(1);
  }

  function addHouseHistoryV250(house, year, text) {
    if (!house) return;
    if (!Array.isArray(house.history)) house.history = [];
    house.history.unshift({ year, text });
    if (house.history.length > 20) house.history.length = 20; // cap 20
  }

  function addOrBoostHouseAllianceV250(houseA, houseB, deltaBond = 30) {
    if (!houseA || !houseB || houseA.id === houseB.id) return;
    if (!Array.isArray(houseA.alliances)) houseA.alliances = [];
    if (!Array.isArray(houseB.alliances)) houseB.alliances = [];
    let a = houseA.alliances.find((x) => x.houseId === houseB.id);
    if (!a) {
      a = { houseId: houseB.id, bond: clamp(deltaBond, 0, 100) };
      houseA.alliances.push(a);
    } else {
      a.bond = clamp((a.bond || 0) + deltaBond, 0, 100);
    }
    let b = houseB.alliances.find((x) => x.houseId === houseA.id);
    if (!b) {
      b = { houseId: houseA.id, bond: clamp(deltaBond, 0, 100) };
      houseB.alliances.push(b);
    } else {
      b.bond = clamp((b.bond || 0) + deltaBond, 0, 100);
    }
    if (houseA.alliances.length > 15) houseA.alliances.length = 15;
    if (houseB.alliances.length > 15) houseB.alliances.length = 15;
  }

  function addOrEscalateFeudV250(houseA, houseB, deltaIntensity, cause, tick) {
    if (!houseA || !houseB || houseA.id === houseB.id) return null;
    if (!Array.isArray(houseA.feuds)) houseA.feuds = [];
    if (!Array.isArray(houseB.feuds)) houseB.feuds = [];
    let fA = houseA.feuds.find((x) => x.houseId === houseB.id);
    let isNew = false;
    if (!fA) {
      isNew = true;
      fA = { houseId: houseB.id, intensity: clamp(deltaIntensity, 0, 100), cause: cause || 'ความขัดแย้งทางการเมือง', sinceTick: tick || 0 };
      houseA.feuds.push(fA);
    } else {
      fA.intensity = clamp((fA.intensity || 20) + deltaIntensity, 0, 100);
      if (cause) fA.cause = cause;
    }
    let fB = houseB.feuds.find((x) => x.houseId === houseA.id);
    if (!fB) {
      fB = { houseId: houseA.id, intensity: fA.intensity, cause: fA.cause, sinceTick: fA.sinceTick };
      houseB.feuds.push(fB);
    } else {
      fB.intensity = fA.intensity;
      if (cause) fB.cause = cause;
    }
    if (houseA.feuds.length > 15) houseA.feuds.length = 15;
    if (houseB.feuds.length > 15) houseB.feuds.length = 15;
    return { feud: fA, isNew };
  }

  function syncDynastiesWithKinV250(world) {
    if (!world || !world.kinV250 || !world.kinV250.houses) return;
    if (!world.dynasties) world.dynasties = {};
    const aliveByHouse = {};
    Object.values(world.npcs || {}).forEach((npc) => {
      if (!npc || !npc.alive) return;
      const key = (npc.kinV250 && npc.kinV250.houseId) || `${npc.stateId}_${npc.lastName}`;
      if (!aliveByHouse[key]) aliveByHouse[key] = [];
      aliveByHouse[key].push(npc);
    });

    // Remove extinct/empty houses from active world.dynasties and world.kinV250.houses if they have 0 alive members and were never marked extinct with history, or keep world.dynasties synchronized with alive houses
    Object.keys(world.dynasties).forEach((k) => {
      if (!aliveByHouse[k] || aliveByHouse[k].length === 0) {
        delete world.dynasties[k];
      }
    });

    Object.keys(aliveByHouse).forEach((key) => {
      const members = aliveByHouse[key];
      const first = members[0];
      let h = world.kinV250.houses[key];
      if (!h) {
        h = {
          id: key,
          stateId: first.stateId,
          lastName: first.lastName,
          name: `ตระกูล${first.lastName}`,
          type: 'POLITICAL',
          headOfHouseId: first.id,
          memberIds: members.map((m) => m.id),
          prestige: 50,
          wealthM: 0,
          feuds: [],
          alliances: [],
          claims: [],
          history: [],
          rotatingBranchIdx: 0,
          extinct: false
        };
        world.kinV250.houses[key] = h;
      }
      h.extinct = false;
      h.memberIds = members.map((m) => m.id);
      if (!h.headOfHouseId || !world.npcs[h.headOfHouseId] || !world.npcs[h.headOfHouseId].alive || world.npcs[h.headOfHouseId].kinV250?.houseId !== key) {
        const sorted = members.slice().sort((a, b) => ((b.prestige || 50) * 100 + (b.age || 40)) - ((a.prestige || 50) * 100 + (a.age || 40)));
        h.headOfHouseId = sorted[0].id;
      }
      h.wealthM = +(members.reduce((s, m) => s + (m.wealthM || 5), 0)).toFixed(1);

      if (!world.dynasties[key]) {
        world.dynasties[key] = {
          id: key,
          stateId: h.stateId,
          familyName: h.name,
          lastName: h.lastName || first.lastName,
          prestige: h.prestige,
          wealthM: h.wealthM,
          membersCount: members.length,
          topPositionTitle: world.npcs[h.headOfHouseId]?.positionTitle || first.positionTitle
        };
      } else {
        const d = world.dynasties[key];
        d.membersCount = members.length;
        d.wealthM = h.wealthM;
        d.prestige = h.prestige;
        d.topPositionTitle = world.npcs[h.headOfHouseId]?.positionTitle || d.topPositionTitle;
      }
    });

    // Also ensure any house in world.kinV250.houses with 0 alive members is not left dangling during bootstrap comparison
    Object.keys(world.kinV250.houses).forEach((key) => {
      const h = world.kinV250.houses[key];
      const aliveM = (h.memberIds || []).filter((id) => world.npcs[id] && world.npcs[id].alive);
      h.memberIds = aliveM;
      if (aliveM.length === 0) {
        if (!world.kinV250._keepExtinctHouses) {
          delete world.kinV250.houses[key];
        } else {
          h.extinct = true;
        }
      }
    });
  }

  function capStateAliveNpcsV250(world, maxPerState = 88) {
    if (!world || !world.npcs || world.newWorld) return;
    const cntByState = {};
    let anyOver = false;
    for (const k in world.npcs) {
      const n = world.npcs[k];
      if (n && n.alive) {
        const c = (cntByState[n.stateId] = (cntByState[n.stateId] || 0) + 1);
        if (c > maxPerState) anyOver = true;
      }
    }
    if (!anyOver) return;
    const byState = {};
    for (const k in world.npcs) {
      const n = world.npcs[k];
      if (n && n.alive && cntByState[n.stateId] > maxPerState) {
        if (!byState[n.stateId]) byState[n.stateId] = [];
        byState[n.stateId].push(n);
      }
    }
    Object.keys(byState).forEach((stId) => {
      const list = byState[stId];
      if (list.length <= maxPerState) return;
      const st = world.states && world.states[stId];
      const posSet = new Set(st && st.positions ? Object.values(st.positions).filter(Boolean) : []);
      const removable = list
        .filter((n) => !posSet.has(n.id) && n.positionId !== 'HEAD_OF_STATE' && n.positionId !== 'CITY_GOVERNOR' && (n.stage || 1) <= 4)
        .sort((a, b) => (a.stage || 1) - (b.stage || 1));
      const excess = list.length - maxPerState;
      for (let i = 0; i < Math.min(excess, removable.length); i++) {
        delete world.npcs[removable[i].id];
      }
    });
  }

  function buildKinGraphV250(world, rngInstance = null) {
    if (!world || !world.states || !world.npcs) return;
    const rng = rngInstance || new SeededRNG((world.seed || 202611717) + 2501);
    ensureDynastyTracking(world);

    // 1. Ensure every Constitutional_Monarchy has successionRuleV250 and an alive HEAD_OF_STATE
    Object.values(world.states).forEach((st) => {
      if (!st) return;
      if (st.regimeCategory === 'Constitutional_Monarchy') {
        st.successionRuleV250 = SUCCESSION_RULES_V250[hashStr(st.id) % 5];
        if (!st.positions) st.positions = {};
        let head = st.positions.HEAD_OF_STATE ? world.npcs[st.positions.HEAD_OF_STATE] : null;
        if (!head || !head.alive) {
          const stNpcs = Object.values(world.npcs)
            .filter((n) => n && n.alive && n.stateId === st.id)
            .sort((a, b) => ((b.stage || 1) * 100 + (b.authority || 50)) - ((a.stage || 1) * 100 + (a.authority || 50)));
          if (stNpcs[0]) {
            head = stNpcs[0];
            st.positions.HEAD_OF_STATE = head.id;
            head.positionId = 'HEAD_OF_STATE';
          }
        }
      }
    });

    const isInitialBootstrap = Object.keys(world.kinV250.houses).length === 0;
    const membersByKey = {};
    Object.values(world.npcs).forEach((npc) => {
      if (!npc || !npc.alive) return;
      const key = (npc.kinV250 && npc.kinV250.houseId) || `${npc.stateId}_${npc.lastName}`;
      if (!membersByKey[key]) membersByKey[key] = [];
      membersByKey[key].push(npc);
    });

    // Identify the unique ROYAL house key for each Constitutional_Monarchy state
    const royalHouseKeyByState = {};
    Object.values(world.states).forEach((st) => {
      if (st && st.regimeCategory === 'Constitutional_Monarchy') {
        const head = st.positions?.HEAD_OF_STATE ? world.npcs[st.positions.HEAD_OF_STATE] : null;
        if (head && head.alive) {
          const rKey = (head.kinV250 && head.kinV250.houseId) || `${head.stateId}_${head.lastName}`;
          royalHouseKeyByState[st.id] = rKey;
          st._royalHouseIdV250 = rKey;
        }
      }
    });

    // 2. Create/update houses
    Object.keys(membersByKey).forEach((key) => {
      const members = membersByKey[key];
      const first = members[0];
      const st = world.states[first.stateId];
      const isRoyal = !!(st && st.regimeCategory === 'Constitutional_Monarchy' && royalHouseKeyByState[st.id] === key);
      const milCount = members.filter((m) => m.track === 'military').length;
      const bizCount = members.filter((m) => m.track === 'business' || m.positionId === 'CEO_DIRECTOR').length;
      const stage6Count = members.filter((m) => (m.stage || 1) >= 6).length;

      let hType = 'POLITICAL';
      if (isRoyal) hType = 'ROYAL';
      else if (milCount / members.length >= 0.5) hType = 'MILITARY';
      else if (bizCount / members.length >= 0.5) hType = 'BUSINESS';

      const baseDynPrestige = world.dynasties && world.dynasties[key] ? world.dynasties[key].prestige : 50;
      const startPrestige = clamp(Math.round(baseDynPrestige + (isRoyal ? 15 : 0) + 6 * stage6Count), 5, 100);

      const sortedForHead = members.slice().sort((a, b) => {
        if (isRoyal && st?.positions?.HEAD_OF_STATE === a.id) return -1;
        if (isRoyal && st?.positions?.HEAD_OF_STATE === b.id) return 1;
        return ((b.prestige || 50) * 100 + (b.age || 40)) - ((a.prestige || 50) * 100 + (a.age || 40));
      });
      const headNpc = sortedForHead[0];

      if (!world.kinV250.houses[key]) {
        world.kinV250.houses[key] = {
          id: key,
          stateId: first.stateId,
          lastName: first.lastName,
          name: `ตระกูล${first.lastName}`,
          type: hType,
          headOfHouseId: headNpc.id,
          memberIds: members.map((m) => m.id),
          prestige: startPrestige,
          wealthM: +(members.reduce((s, m) => s + (m.wealthM || 5), 0)).toFixed(1),
          feuds: [],
          alliances: [],
          claims: [],
          history: [{ year: world.year || 2026, text: `ก่อตั้งทำเนียบสายตระกูล ${first.lastName} แห่ง ${first.stateId}` }],
          rotatingBranchIdx: 0,
          prestigeHistory: [{ year: world.year || 2026, prestige: startPrestige }],
          extinct: false
        };
      } else {
        const h = world.kinV250.houses[key];
        if (isRoyal) h.type = 'ROYAL';
        else if (h.type === 'ROYAL' && !isRoyal) h.type = 'POLITICAL';
        h.memberIds = members.map((m) => m.id);
        if (!h.headOfHouseId || !world.npcs[h.headOfHouseId] || !world.npcs[h.headOfHouseId].alive) {
          h.headOfHouseId = headNpc.id;
        }
      }
    });

    // Ensure every alive NPC has npc.kinV250 initialized
    Object.values(world.npcs).forEach((npc) => {
      if (!npc || !npc.alive) return;
      const key = (npc.kinV250 && npc.kinV250.houseId) || `${npc.stateId}_${npc.lastName}`;
      if (!npc.kinV250) {
        npc.kinV250 = {
          houseId: key,
          fatherId: null,
          motherName: null,
          spouse: null,
          children: [],
          siblingIds: [],
          generation: 0,
          role: 'MEMBER',
          _bootstrapped: false
        };
      } else {
        npc.kinV250.houseId = key;
        if (!Array.isArray(npc.kinV250.children)) npc.kinV250.children = [];
        if (!Array.isArray(npc.kinV250.siblingIds)) npc.kinV250.siblingIds = [];
      }
    });

    // 3. Inside each house with >= 2 members, infer parent/child (gap 20..40) and siblings (gap <= 12) on initial bootstrap
    if (isInitialBootstrap) {
      let totalChildRecords = 0;
      const housesByStateAndSurname = {};
      const housesByState = {};
      Object.values(world.kinV250.houses).forEach((h) => {
        housesByStateAndSurname[`${h.stateId}_${h.lastName}`] = h;
        if (!housesByState[h.stateId]) housesByState[h.stateId] = [];
        housesByState[h.stateId].push(h);
      });

      Object.values(world.kinV250.houses).forEach((house) => {
        const members = (house.memberIds || [])
          .map((id) => world.npcs[id])
          .filter((n) => n && n.alive)
          .sort((a, b) => (b.age - a.age) || String(a.id).localeCompare(String(b.id)));

        if (members.length >= 2) {
          for (let i = 0; i < members.length; i++) {
            const older = members[i];
            for (let j = i + 1; j < members.length; j++) {
              const younger = members[j];
              const gap = older.age - younger.age;
              if (gap >= 20 && gap <= 40 && !younger.kinV250.fatherId) {
                younger.kinV250.fatherId = older.id;
                younger.kinV250.motherName = older.gender === 'F'
                  ? older.name
                  : ((older.family && older.family.spouseName) ? older.family.spouseName : `${pickFirstNameV250(world, older.stateId, 'F', rng)} ${older.lastName}`);
                younger.kinV250.generation = (older.kinV250.generation || 0) + 1;
                if (!older.kinV250.children.some((c) => c.npcId === younger.id)) {
                  older.kinV250.children.push({
                    id: 'CHD_' + (++world.kinV250.nextId),
                    name: younger.name,
                    gender: younger.gender || 'M',
                    birthYear: (world.year || 2026) - younger.age,
                    alive: true,
                    talent: clamp(younger.intelligence || 65, 30, 95),
                    ambition: clamp(younger.personality?.ambition || 60, 20, 95),
                    npcId: younger.id,
                    inheritedM: 0
                  });
                  totalChildRecords++;
                }
                addOrUpdateNPCRelationship(world, older, younger, 'family', 75, `บิดา/มารดาและบุตรใน${house.name}`);
                addOrUpdateNPCRelationship(world, younger, older, 'family', 75, `บุตรและบิดา/มารดาใน${house.name}`);
              } else if (gap <= 12 && younger.kinV250.fatherId !== older.id) {
                if (!older.kinV250.siblingIds.includes(younger.id)) older.kinV250.siblingIds.push(younger.id);
                if (!younger.kinV250.siblingIds.includes(older.id)) younger.kinV250.siblingIds.push(older.id);
                addOrUpdateNPCRelationship(world, older, younger, 'family', 68, `พี่น้องร่วมตระกูลใน${house.name}`);
                addOrUpdateNPCRelationship(world, younger, older, 'family', 68, `พี่น้องร่วมตระกูลใน${house.name}`);
              } else {
                addOrUpdateNPCRelationship(world, older, younger, 'family', 62, `เครือญาติร่วม${house.name}`);
                addOrUpdateNPCRelationship(world, younger, older, 'family', 62, `เครือญาติร่วม${house.name}`);
              }
            }
          }
        }
      });

      // 4. Convert npc.family summary into spouse and child records (total child records capped at <= 600)
      const allAlive = Object.values(world.npcs).filter((n) => n && n.alive);
      // Prioritize ROYAL and high-stage NPCs first so cap of 600 covers the most important families
      allAlive.sort((a, b) => {
        const hA = world.kinV250.houses[a.kinV250.houseId];
        const hB = world.kinV250.houses[b.kinV250.houseId];
        const rA = hA && hA.type === 'ROYAL' ? 1000 : 0;
        const rB = hB && hB.type === 'ROYAL' ? 1000 : 0;
        return (rB + (b.stage || 1) * 10) - (rA + (a.stage || 1) * 10);
      });

      for (let idx = 0; idx < allAlive.length; idx++) {
        const npc = allAlive[idx];
        const house = world.kinV250.houses[npc.kinV250.houseId];
        if (!house) continue;
        npc.kinV250._bootstrapped = true;

        if (npc.family && npc.family.married && !npc.kinV250.spouse) {
          const st = world.states[npc.stateId];
          const pool = (st && NAME_POOLS[st.region]) || NAME_POOLS.NorthAmerica || NAME_POOLS.Thailand;
          // Pick a surname from the same state's houses 35% of the time so cross-house marriage alliances form at bootstrap
          const sameStateHouses = (housesByState[npc.stateId] || []).filter((h) => h.id !== house.id);
          let spouseSurname = npc.lastName;
          let matchedOtherHouse = null;
          if (sameStateHouses.length > 0 && rng.chance(0.35)) {
            matchedOtherHouse = rng.pick(sameStateHouses);
            spouseSurname = matchedOtherHouse.lastName;
          } else if (pool && Array.isArray(pool.last) && pool.last.length > 0) {
            const candLast = rng.pick(pool.last);
            spouseSurname = candLast.charAt(0).toUpperCase() + candLast.slice(1);
            matchedOtherHouse = housesByStateAndSurname[`${npc.stateId}_${spouseSurname}`] || null;
          }
          const spouseFirst = (npc.family.spouseName && npc.family.spouseName.split(' ')[0]) || pickFirstNameV250(world, npc.stateId, npc.gender === 'M' ? 'F' : 'M', rng);
          const fullSpouseName = `${spouseFirst} ${spouseSurname}`;
          npc.family.spouseName = fullSpouseName;
          npc.kinV250.spouse = {
            name: fullSpouseName,
            originHouseName: `ตระกูล${spouseSurname}`,
            originStateId: npc.stateId,
            alive: true,
            age: Math.max(20, npc.age + rng.int(-4, 4)),
            npcId: null
          };

          if (matchedOtherHouse && matchedOtherHouse.id !== house.id) {
            addOrBoostHouseAllianceV250(house, matchedOtherHouse, 40);
            if (world.kinV250.marriages.length < 150) {
              world.kinV250.marriages.push({
                id: 'MAR_' + (++world.kinV250.nextId),
                year: world.year || 2026,
                tick: world.tick || 0,
                npcAId: npc.id,
                npcBId: null,
                spouseName: fullSpouseName,
                houseAId: house.id,
                houseBId: matchedOtherHouse.id,
                stateAId: npc.stateId,
                stateBId: npc.stateId,
                kind: 'BOOTSTRAP_ALLIANCE'
              });
            }
          }
        }

        const wantChildren = (npc.family && npc.family.childrenCount) || 0;
        const existingLinked = npc.kinV250.children.length;
        const toCreate = Math.max(0, wantChildren - existingLinked);
        if (toCreate > 0 && npc.age >= 21 && totalChildRecords < 600) {
          const maxCreate = Math.min(toCreate, 600 - totalChildRecords);
          const minBirthYear = (world.year || 2026) - (npc.age - 20);
          const maxBirthYear = world.year || 2026;
          for (let cIdx = 0; cIdx < maxCreate; cIdx++) {
            const g = rng.chance(0.52) ? 'M' : 'F';
            const cFirst = pickFirstNameV250(world, npc.stateId, g, rng);
            const bYear = rng.int(minBirthYear, maxBirthYear);
            npc.kinV250.children.push({
              id: 'CHD_' + (++world.kinV250.nextId),
              name: `${cFirst} ${npc.lastName}`,
              gender: g,
              birthYear: bYear,
              alive: true,
              talent: rng.int(30, 95),
              ambition: rng.int(20, 95),
              npcId: null,
              inheritedM: 0
            });
            totalChildRecords++;
          }
        }
      }
      world.kinV250.bootstrapChildCount = totalChildRecords;
    }

    // Assign roles inside each house (HEAD_OF_HOUSE, HEIR, ELDER, MEMBER)
    Object.values(world.kinV250.houses).forEach((house) => {
      const members = (house.memberIds || []).map((id) => world.npcs[id]).filter((n) => n && n.alive);
      if (members.length === 0) return;
      const head = world.npcs[house.headOfHouseId] || members[0];
      house.headOfHouseId = head.id;
      const heirCand = members
        .filter((m) => m.id !== head.id)
        .sort((a, b) => {
          const aIsChild = a.kinV250.fatherId === head.id ? 1 : 0;
          const bIsChild = b.kinV250.fatherId === head.id ? 1 : 0;
          if (aIsChild !== bIsChild) return bIsChild - aIsChild;
          return b.age - a.age;
        })[0];
      members.forEach((m) => {
        if (m.id === head.id) m.kinV250.role = 'HEAD_OF_HOUSE';
        else if (heirCand && m.id === heirCand.id) m.kinV250.role = 'HEIR';
        else if (m.age >= 55) m.kinV250.role = 'ELDER';
        else m.kinV250.role = 'MEMBER';
      });
    });

    syncDynastiesWithKinV250(world);
  }

  function ensureKinV250(world) {
    if (!world || !world.states) return;
    if (!world.kinV250) {
      world.kinV250 = {
        nextId: 1,
        houses: {},
        marriages: [],     // cap 150
        crises: [],        // active cap 6
        archiveCrises: [], // archive cap 30
        bootstrapChildCount: 0,
        lastDissolvedWealthM: 0
      };
    } else {
      if (!world.kinV250.houses) world.kinV250.houses = {};
      if (!Array.isArray(world.kinV250.marriages)) world.kinV250.marriages = [];
      if (!Array.isArray(world.kinV250.crises)) world.kinV250.crises = [];
      if (!Array.isArray(world.kinV250.archiveCrises)) world.kinV250.archiveCrises = [];
    }

    const npcKeysLen = `${Object.keys(world.npcs || {}).length}_${world.nextId || 0}`;
    if (Object.keys(world.kinV250.houses).length === 0) {
      buildKinGraphV250(world);
      world.kinV250._graphBuilt = true;
      world.kinV250._lastNpcCountV250 = `${Object.keys(world.npcs || {}).length}_${world.nextId || 0}`;
      return;
    }
    if (world.kinV250._graphBuilt && world.kinV250._lastNpcCountV250 === npcKeysLen) {
      return;
    }
    world.kinV250._lastNpcCountV250 = npcKeysLen;

    // Minimal default for any NPC created later (e.g. yearly intake or event spawn)
    let addedAny = false;
    const npcsList = Object.values(world.npcs || {});
    for (let i = 0; i < npcsList.length; i++) {
      const npc = npcsList[i];
      if (!npc || !npc.alive) continue;
      if (!npc.kinV250 || !npc.kinV250.houseId) {
        const key = `${npc.stateId}_${npc.lastName}`;
        npc.kinV250 = {
          houseId: key,
          fatherId: null,
          motherName: null,
          spouse: null,
          children: [],
          siblingIds: [],
          generation: 0,
          role: 'MEMBER',
          _bootstrapped: true
        };
        let h = world.kinV250.houses[key];
        if (!h) {
          h = {
            id: key,
            stateId: npc.stateId,
            lastName: npc.lastName,
            name: `ตระกูล${npc.lastName}`,
            type: npc.track === 'military' ? 'MILITARY' : npc.track === 'business' ? 'BUSINESS' : 'POLITICAL',
            headOfHouseId: npc.id,
            memberIds: [npc.id],
            prestige: 50,
            wealthM: npc.wealthM || 5,
            feuds: [],
            alliances: [],
            claims: [],
            history: [],
            rotatingBranchIdx: 0,
            extinct: false
          };
          world.kinV250.houses[key] = h;
        } else if (!h.memberIds.includes(npc.id)) {
          h.memberIds.push(npc.id);
          h.extinct = false;
        }
        addedAny = true;
      }
    }

    Object.values(world.states).forEach((st) => {
      if (st && st.regimeCategory === 'Constitutional_Monarchy' && !st.successionRuleV250) {
        st.successionRuleV250 = SUCCESSION_RULES_V250[hashStr(st.id) % 5];
      }
    });

    if (addedAny) {
      syncDynastiesWithKinV250(world);
    }
  }

  // -------------------------------------------------------------------------
  // T5.4 SUCCESSION ORDERING & SUCCESSION CRISIS ENGINE
  // -------------------------------------------------------------------------
  function computeOrderedSuccessionHeirsV250(world, st, house, outgoingNpc) {
    if (!world || !st || !house) return [];
    const curTick = world.tick || 0;
    const headId = outgoingNpc ? outgoingNpc.id : (st.positions?.HEAD_OF_STATE || house.headOfHouseId);
    const headNpc = headId ? world.npcs[headId] : null;

    // Collect all alive, non-retired adult NPCs in the house (or direct descendants of outgoingNpc)
    const houseMembers = Object.values(world.npcs || {}).filter((n) => {
      if (!n || !n.alive || n.retired) return false;
      if (headNpc && n.id === headNpc.id) return false;
      if ((n.age || 0) < 18) return false;
      if ((n.imprisonedUntilTick || 0) > curTick) return false;
      const inSameHouse = n.kinV250 && n.kinV250.houseId === house.id;
      const isDirectChild = headNpc && (n.kinV250?.fatherId === headNpc.id || (headNpc.kinV250?.children || []).some((c) => c.npcId === n.id));
      return inSameHouse || isDirectChild;
    });

    if (houseMembers.length === 0) return [];

    // Degree classification: 0 = direct children, 1 = grandchildren/descendants, 2 = siblings, 3 = nephews/collateral
    const getDegree = (n) => {
      if (!headNpc) return 3;
      if (n.kinV250?.fatherId === headNpc.id || (headNpc.kinV250?.children || []).some((c) => c.npcId === n.id)) return 0;
      // Check up to 4 steps of fatherId for descendant of headNpc
      let cur = n.kinV250?.fatherId ? world.npcs[n.kinV250.fatherId] : null;
      let steps = 0;
      while (cur && steps < 4) {
        if (cur.id === headNpc.id) return 1;
        cur = cur.kinV250?.fatherId ? world.npcs[cur.kinV250.fatherId] : null;
        steps++;
      }
      if ((headNpc.kinV250?.siblingIds || []).includes(n.id) || (headNpc.kinV250?.fatherId && n.kinV250?.fatherId === headNpc.kinV250.fatherId)) {
        return 2;
      }
      return 3;
    };

    // Check if male-line for AGNATIC
    const isMaleLine = (n) => {
      if (n.gender !== 'M') return false;
      let cur = n.kinV250?.fatherId ? world.npcs[n.kinV250.fatherId] : null;
      let steps = 0;
      while (cur && steps < 4) {
        if (headNpc && cur.id === headNpc.id) return true;
        if (cur.gender === 'F') return false;
        cur = cur.kinV250?.fatherId ? world.npcs[cur.kinV250.fatherId] : null;
        steps++;
      }
      return true;
    };

    const rule = st.successionRuleV250 || 'PRIMOGENITURE';

    if (rule === 'AGNATIC') {
      return houseMembers
        .filter((n) => isMaleLine(n))
        .sort((a, b) => {
          const dA = getDegree(a);
          const dB = getDegree(b);
          if (dA !== dB) return dA - dB;
          return (b.age - a.age) || String(a.id).localeCompare(String(b.id));
        });
    }

    if (rule === 'PRIMOGENITURE') {
      return houseMembers.slice().sort((a, b) => {
        const dA = getDegree(a);
        const dB = getDegree(b);
        if (dA !== dB) return dA - dB;
        const mA = a.gender === 'M' ? 1 : 0;
        const mB = b.gender === 'M' ? 1 : 0;
        if (mA !== mB) return mB - mA; // eldest SON first then daughters
        return (b.age - a.age) || String(a.id).localeCompare(String(b.id));
      });
    }

    if (rule === 'ABSOLUTE_PRIMOGENITURE') {
      return houseMembers.slice().sort((a, b) => {
        const dA = getDegree(a);
        const dB = getDegree(b);
        if (dA !== dB) return dA - dB;
        return (b.age - a.age) || String(a.id).localeCompare(String(b.id));
      });
    }

    if (rule === 'ELECTIVE_COUNCIL') {
      const scoreOf = (n) =>
        0.4 * (n.prestige || 50) +
        0.3 * (n.competence !== undefined ? n.competence : (n.meritScore || 60)) +
        0.3 * (n.personality?.loyalty ?? n.loyalty ?? 65);
      return houseMembers.slice().sort((a, b) => (scoreOf(b) - scoreOf(a)) || (b.age - a.age));
    }

    if (rule === 'ROTATING_BRANCHES') {
      // Group members by branch key (explicit n.kinV250.branchId, else root ancestor/fatherId or member id)
      const getBranchKey = (n) => {
        if (n.kinV250 && n.kinV250.branchId) return String(n.kinV250.branchId);
        if (n.kinV250 && n.kinV250.fatherId && (!headNpc || n.kinV250.fatherId !== headNpc.id)) {
          return String(n.kinV250.fatherId);
        }
        return String(n.id);
      };
      const headBranch = headNpc ? getBranchKey(headNpc) : (house.lastBranchKeyV250 || null);
      const branchesMap = {};
      houseMembers.forEach((m) => {
        const bk = getBranchKey(m);
        if (!branchesMap[bk]) branchesMap[bk] = [];
        branchesMap[bk].push(m);
      });
      const branchKeys = Object.keys(branchesMap).sort();
      if (branchKeys.length <= 1) {
        return houseMembers.slice().sort((a, b) => b.age - a.age);
      }
      // Rotate away from lastBranchKeyV250 / headBranch
      const lastUsed = house.lastBranchKeyV250 || headBranch;
      let startIdx = 0;
      if (lastUsed && branchKeys.includes(lastUsed)) {
        startIdx = (branchKeys.indexOf(lastUsed) + 1) % branchKeys.length;
      } else {
        startIdx = ((house.rotatingBranchIdx || 0) + 1) % branchKeys.length;
      }
      const ordered = [];
      for (let k = 0; k < branchKeys.length; k++) {
        const bKey = branchKeys[(startIdx + k) % branchKeys.length];
        const bMembers = branchesMap[bKey].slice().sort((a, b) => b.age - a.age);
        ordered.push(...bMembers);
      }
      return ordered;
    }

    return houseMembers.slice().sort((a, b) => b.age - a.age);
  }

  function openSuccessionCrisisV250(world, st, house, outgoingNpc, caretakerNpc, rngInstance = null) {
    if (!world || !st) return null;
    ensureKinV250(world);
    const existing = (world.kinV250.crises || []).find((c) => c.stateId === st.id && c.stage !== 'RESOLVED');
    if (existing) return existing;

    const rng = rngInstance || new SeededRNG((world.seed || 2026) + (world.tick || 0) * 19 + hashStr(st.id));
    const claimants = [];

    // 1. Collateral kin / other prominent houses in the same state
    const stateHouses = Object.values(world.kinV250.houses || {})
      .filter((h) => h.stateId === st.id && (h.memberIds || []).some((id) => world.npcs[id]?.alive))
      .sort((a, b) => (b.prestige || 0) - (a.prestige || 0));

    stateHouses.slice(0, 2).forEach((h, idx) => {
      const candNpc = (h.memberIds || []).map((id) => world.npcs[id]).find((n) => n && n.alive && (!caretakerNpc || n.id !== caretakerNpc.id)) || world.npcs[h.headOfHouseId];
      if (candNpc && candNpc.alive) {
        claimants.push({
          npcId: candNpc.id,
          houseId: h.id,
          name: candNpc.name,
          kind: 'COLLATERAL',
          sponsorStateId: null,
          legitimacy: clamp(Math.round((h.prestige || 60) * 0.75 + (idx === 0 ? 15 : 5)), 25, 95),
          militarySupport: clamp(Math.round((candNpc.authority || 55) * 0.6 + rng.int(10, 30)), 20, 95),
          factionSupport: clamp(Math.round((h.prestige || 60) * 0.8 + rng.int(5, 20)), 20, 95)
        });
      }
    });

    // 2. Consort families holding claims for this state (foreign houses)
    const foreignClaimHouses = Object.values(world.kinV250.houses || {}).filter(
      (h) => h.stateId !== st.id && Array.isArray(h.claims) && h.claims.some((cl) => cl.stateId === st.id)
    );
    if (foreignClaimHouses.length > 0) {
      const fh = foreignClaimHouses[0];
      const clObj = fh.claims.find((cl) => cl.stateId === st.id);
      const fHead = world.npcs[fh.headOfHouseId];
      if (fHead && fHead.alive) {
        claimants.push({
          npcId: fHead.id,
          houseId: fh.id,
          name: fHead.name,
          kind: 'FOREIGN_CONSORT',
          sponsorStateId: fh.stateId,
          legitimacy: clamp(clObj ? clObj.legitimacy + 25 : 45, 20, 90),
          militarySupport: rng.int(35, 75),
          factionSupport: rng.int(25, 65)
        });
      }
    }

    // 3. Military strongman (highest-ambition SUPREME_COMMANDER / ARMY_CHIEF / military NPC)
    const milCands = [st.positions?.SUPREME_COMMANDER, st.positions?.ARMY_CHIEF, st.positions?.DEFENSE_MINISTER]
      .map((id) => (id ? world.npcs[id] : null))
      .filter((n) => n && n.alive);
    const strongman = milCands.sort((a, b) => (b.personality?.ambition || 60) - (a.personality?.ambition || 60))[0] ||
      Object.values(world.npcs).filter((n) => n && n.alive && n.stateId === st.id && n.track === 'military').sort((a, b) => (b.personality?.ambition || 60) - (a.personality?.ambition || 60))[0];

    if (strongman && !claimants.some((c) => c.npcId === strongman.id)) {
      claimants.push({
        npcId: strongman.id,
        houseId: strongman.kinV250?.houseId || `${st.id}_${strongman.lastName}`,
        name: strongman.name,
        kind: 'MILITARY_STRONGMAN',
        sponsorStateId: null,
        legitimacy: rng.int(30, 60),
        militarySupport: clamp(Math.round((st.politicalPressures?.militaryInfluence || 55) * 0.8 + 20), 45, 98),
        factionSupport: rng.int(35, 75)
      });
      // Addendum Link 3: feed coupReadiness and militaryPlotLevel
      strongman.coupReadiness = clamp((strongman.coupReadiness || 30) + 18, 0, 100);
      if (st.underground) {
        st.underground.militaryPlotLevel = clamp(rnd1((st.underground.militaryPlotLevel || 15) + 12), 0, 100);
      }
    }

    // Ensure at least 2 claimants exist
    while (claimants.length < 2) {
      const fb = generateContextualNPC(world, rng, { stateId: st.id, age: rng.int(32, 55), positionId: 'SENIOR_OFFICIAL', track: 'political' });
      if (typeof ensureNPCDeepProfileV170 === 'function') ensureNPCDeepProfileV170(world, fb, rng);
      if (typeof ensureNPCPowerModelV200 === 'function') ensureNPCPowerModelV200(world, fb);
      ensureKinV250(world);
      claimants.push({
        npcId: fb.id,
        houseId: fb.kinV250?.houseId || (house ? house.id : `${st.id}_${fb.lastName}`),
        name: fb.name,
        kind: 'COLLATERAL',
        sponsorStateId: null,
        legitimacy: rng.int(40, 75),
        militarySupport: rng.int(35, 75),
        factionSupport: rng.int(40, 80)
      });
    }

    const crisis = {
      id: 'SCRIS_' + (++world.kinV250.nextId),
      stateId: st.id,
      houseId: house ? house.id : claimants[0].houseId,
      claimants,
      stage: 'DISPUTE',
      stageDay: 0,
      disputeDuration: rng.int(15, 30),
      councilDuration: rng.int(5, 15),
      winner: null,
      regentId: caretakerNpc ? caretakerNpc.id : null,
      initialStability: st.stability || 75,
      startedTick: world.tick || 0
    };

    if (world.kinV250.crises.length >= 6) {
      const old = world.kinV250.crises.shift();
      world.kinV250.archiveCrises.unshift(old);
      if (world.kinV250.archiveCrises.length > 30) world.kinV250.archiveCrises.length = 30;
    }
    world.kinV250.crises.push(crisis);

    const capCity = Object.values(world.cities || {}).find((c) => c.stateId === st.id && c.isCapital) || Object.values(world.cities || {}).find((c) => c.stateId === st.id);
    st.stability = clamp(rnd1((st.stability || 75) - 1.5), 5, 100);
    if (capCity) capCity.unrest = clamp(rnd1((capCity.unrest || 20) + 4), 0, 100);

    const tpl = rng.pick(DYNASTY_CRISIS_DISPUTE_TEMPLATES_V250);
    const msg = fillTemplateV250(tpl, {
      state: st.name,
      city: capCity ? capCity.name.split(' (')[0] : shortNameTh(st),
      house: house ? house.name : 'ราชตระกูล',
      claimantCount: claimants.length,
      claimantA: claimants[0].name,
      claimantB: claimants[1] ? claimants[1].name : claimants[0].name,
      stability: st.stability,
      stageDay: 1,
      year: world.year || 2026
    });
    addChronicle(world, 'DYNASTY', msg, st.id, { personId: claimants[0].npcId, cityId: capCity ? capCity.id : null, subKind: 'CRISIS_DISPUTE' });
    return crisis;
  }

  function stepSuccessionCrisesV250(world, rngInstance = null) {
    if (!world || !world.kinV250 || !Array.isArray(world.kinV250.crises) || world.kinV250.crises.length === 0) return;
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + (world.tick || 0) * 157);
    const active = world.kinV250.crises;

    for (let i = active.length - 1; i >= 0; i--) {
      const cr = active[i];
      const st = world.states && world.states[cr.stateId];
      if (!st) {
        active.splice(i, 1);
        continue;
      }
      const house = world.kinV250.houses[cr.houseId] || Object.values(world.kinV250.houses).find((h) => h.stateId === st.id);
      const capCity = Object.values(world.cities || {}).find((c) => c.stateId === st.id && c.isCapital) || Object.values(world.cities || {}).find((c) => c.stateId === st.id);
      const cA = cr.claimants[0] || { name: 'ผู้ท้าชิงสายหลัก', npcId: null };
      const cB = cr.claimants[1] || cA;

      // Advance by 5 days since stepSuccessionCrisesV250 runs on t % 5 === 2
      cr.stageDay = (cr.stageDay || 0) + 5;

      if (cr.stage === 'DISPUTE') {
        st.stability = clamp(rnd1((st.stability || 70) - 0.4), 5, 100);
        if (capCity) capCity.unrest = clamp(rnd1((capCity.unrest || 20) + 1.5), 0, 100);
        if (st.underground) {
          st.underground.dissidentNetwork = clamp(rnd1((st.underground.dissidentNetwork || 20) + 1.2), 0, 100);
        }
        if (cr.stageDay >= (cr.disputeDuration || 15)) {
          cr.stage = 'COUNCIL';
          cr.stageDay = 0;
          const tpl = rng.pick(DYNASTY_CRISIS_COUNCIL_TEMPLATES_V250);
          const msg = fillTemplateV250(tpl, {
            state: st.name,
            city: capCity ? capCity.name.split(' (')[0] : shortNameTh(st),
            house: house ? house.name : 'ราชตระกูล',
            claimantCount: cr.claimants.length,
            claimantA: cA.name,
            claimantB: cB.name,
            stability: st.stability,
            year: world.year || 2026
          });
          addChronicle(world, 'DYNASTY', msg, st.id, { personId: cA.npcId, cityId: capCity ? capCity.id : null, subKind: 'CRISIS_COUNCIL' });
        } else if (cr.stageDay === 10) {
          const tpl = rng.pick(DYNASTY_CRISIS_DISPUTE_TEMPLATES_V250);
          const msg = fillTemplateV250(tpl, {
            state: st.name,
            city: capCity ? capCity.name.split(' (')[0] : shortNameTh(st),
            house: house ? house.name : 'ราชตระกูล',
            claimantCount: cr.claimants.length,
            claimantA: cA.name,
            claimantB: cB.name,
            stability: st.stability,
            stageDay: cr.stageDay,
            year: world.year || 2026
          });
          addChronicle(world, 'DYNASTY', msg, st.id, { personId: cA.npcId, cityId: capCity ? capCity.id : null, subKind: 'CRISIS_DISPUTE' });
        }
      } else if (cr.stage === 'COUNCIL') {
        if (cr.stageDay >= (cr.councilDuration || 5)) {
          cr.stage = 'RESOLVED';
          // Score claimants: 0.4*prestige + 0.3*legitimacy + 0.3*militarySupport (+ rng ±6)
          let bestClaimant = cr.claimants[0];
          let bestScore = -999;
          cr.claimants.forEach((cl) => {
            const npcObj = cl.npcId ? world.npcs[cl.npcId] : null;
            const hObj = cl.houseId ? world.kinV250.houses[cl.houseId] : house;
            const pres = (npcObj && npcObj.prestige) || (hObj && hObj.prestige) || 60;
            const sc = 0.4 * pres + 0.3 * (cl.legitimacy || 50) + 0.3 * (cl.militarySupport || 50) + rng.int(-6, 6);
            if (sc > bestScore) {
              bestScore = sc;
              bestClaimant = cl;
            }
          });

          let winnerNpc = bestClaimant && bestClaimant.npcId ? world.npcs[bestClaimant.npcId] : null;
          if (!winnerNpc || !winnerNpc.alive) {
            winnerNpc = generateContextualNPC(world, rng, { stateId: st.id, age: rng.int(30, 52), positionId: 'HEAD_OF_STATE', track: 'political' });
            if (typeof ensureNPCDeepProfileV170 === 'function') ensureNPCDeepProfileV170(world, winnerNpc, rng);
            if (typeof ensureNPCPowerModelV200 === 'function') ensureNPCPowerModelV200(world, winnerNpc);
            ensureKinV250(world);
          }
          winnerNpc.stateId = st.id;
          promoteNPC(world, winnerNpc, 'HEAD_OF_STATE', capCity ? capCity.id : null);
          if (!st.positions) st.positions = {};
          st.positions.HEAD_OF_STATE = winnerNpc.id;
          cr.winner = winnerNpc.id;

          // Ensure winner's house in this monarchy becomes ROYAL
          const winHouseKey = (winnerNpc.kinV250 && winnerNpc.kinV250.houseId) || `${st.id}_${winnerNpc.lastName}`;
          if (world.kinV250.houses[winHouseKey]) {
            world.kinV250.houses[winHouseKey].type = 'ROYAL';
            world.kinV250.houses[winHouseKey].headOfHouseId = winnerNpc.id;
            st._royalHouseIdV250 = winHouseKey;
          }

          // Addendum Link 3: if military strongman took over a monarchy, old royal house loses 30 prestige and opens feud
          if (bestClaimant.kind === 'MILITARY_STRONGMAN' && house && house.id !== winHouseKey) {
            house.prestige = clamp((house.prestige || 60) - 30, 5, 100);
            if (world.kinV250.houses[winHouseKey]) {
              addOrEscalateFeudV250(house, world.kinV250.houses[winHouseKey], 55, 'การชิงราชบัลลังก์โดยผู้นำทหาร', world.tick || 0);
            }
          }

          // Partial stability recovery
          st.stability = clamp(rnd1((st.stability || 65) + 0.8), 10, 100);

          // Handle losers
          let loserFateText = 'ยอมรับมติสภาราชวงศ์และถวายสัตย์ปฏิญาณ';
          let mainLoserName = cB && cB.npcId !== winnerNpc.id ? cB.name : (cA.npcId !== winnerNpc.id ? cA.name : 'ฝ่ายผู้ท้าชิงรอง');

          cr.claimants.forEach((cl) => {
            if (cl.npcId === winnerNpc.id) return;
            const loserNpc = cl.npcId ? world.npcs[cl.npcId] : null;
            const roll = rng.next();
            if (roll < 0.40 && loserNpc && loserNpc.alive) {
              // Exiled to a foreign house + feud + createPoliticalExile (Addendum Link 3)
              const lHouse = world.kinV250.houses[cl.houseId] || house;
              const wHouse = world.kinV250.houses[winHouseKey] || house;
              if (lHouse && wHouse && lHouse.id !== wHouse.id) {
                addOrEscalateFeudV250(lHouse, wHouse, 45, `ถูกเนรเทศหลังพ่ายศึกชิงบัลลังก์แก่ ${winnerNpc.name}`, world.tick || 0);
              }
              if (st.regimeCategory === 'Constitutional_Monarchy' && typeof createPoliticalExile === 'function') {
                createPoliticalExile(world, st, loserNpc);
              } else {
                const friendlySt = Object.values(world.states).find((s) => s.id !== st.id && !s.isExiled) || st;
                loserNpc.stateId = friendlySt.id;
              }
              loserNpc.grievance = clamp((loserNpc.grievance || 40) + 30, 0, 100);
              loserFateText = 'ถูกเนรเทศไปตั้งเครือข่ายพลัดถิ่นในต่างแดนพร้อมประกาศความแค้นสายเลือด';
            } else if (roll < 0.55 && loserNpc && loserNpc.alive) {
              // 15% armed rebellion or found new state
              loserNpc.grievance = clamp((loserNpc.grievance || 50) + 35, 0, 100);
              loserNpc.secessionDesire = clamp((loserNpc.secessionDesire || 40) + 30, 0, 100);
              if ((loserNpc.personality?.ambition || 60) >= 85 && st.stability < 40) {
                triggerNPCFoundNewState(world, loserNpc);
                loserFateText = 'ประกาศแยกตัวก่อตั้งรัฐกบฏท้าทายอำนาจส่วนกลาง';
              } else {
                triggerArmedRebellion(world, loserNpc);
                loserFateText = 'ปลุกระดมกองกำลังติดอาวุธลุกฮือต่อต้านในภูมิภาค';
              }
            } else {
              loserFateText = 'ได้รับการไกล่เกลี่ยด้วยข้อเสนอสมรสทางการเมืองและตำแหน่งที่ปรึกษา';
            }

            // Foreign claimant backer casus belli & War of Succession hook
            if (cl.kind === 'FOREIGN_CONSORT' && cl.sponsorStateId && world.states[cl.sponsorStateId]) {
              const fSt = world.states[cl.sponsorStateId];
              if (fSt.relations && fSt.relations[st.id]) {
                fSt.relations[st.id].score = clamp((fSt.relations[st.id].score || 50) - 10, 0, 100);
              }
              if (st.relations && st.relations[fSt.id]) {
                st.relations[fSt.id].score = clamp((st.relations[fSt.id].score || 50) - 10, 0, 100);
              }
              const fHead = fSt.positions?.HEAD_OF_STATE ? world.npcs[fSt.positions.HEAD_OF_STATE] : null;
              const fAggr = fHead?.personality?.aggression ?? 60;
              if (fAggr > 65 && rng.chance(0.12)) {
                setDiplomaticStatus(world, fSt.id, st.id, 'War');
                const wTpl = rng.pick(DYNASTY_WAR_OF_SUCCESSION_TEMPLATES_V250);
                const wMsg = fillTemplateV250(wTpl, {
                  sponsor: fSt.name,
                  state: st.name,
                  city: capCity ? capCity.name.split(' (')[0] : shortNameTh(st),
                  sponsorHead: fHead ? fHead.name : `ประมุขแห่ง ${shortNameTh(fSt)}`,
                  aggr: fAggr,
                  consortHouse: world.kinV250.houses[cl.houseId]?.name || 'ราชตระกูลพันธมิตร',
                  winner: winnerNpc.name,
                  year: world.year || 2026
                });
                addChronicle(world, 'DYNASTY', wMsg, st.id, { personId: winnerNpc.id, secondStateId: fSt.id, subKind: 'WAR_OF_SUCCESSION' });
              }
            }
          });

          const rTpl = rng.pick(DYNASTY_CRISIS_RESOLVED_TEMPLATES_V250);
          const rMsg = fillTemplateV250(rTpl, {
            state: st.name,
            city: capCity ? capCity.name.split(' (')[0] : shortNameTh(st),
            house: house ? house.name : 'ราชตระกูล',
            winner: winnerNpc.name,
            loser: mainLoserName,
            loserFate: loserFateText,
            stability: st.stability,
            year: world.year || 2026
          });
          addChronicle(world, 'DYNASTY', rMsg, st.id, { personId: winnerNpc.id, cityId: capCity ? capCity.id : null, subKind: 'CRISIS_RESOLVED' });

          active.splice(i, 1);
          world.kinV250.archiveCrises.unshift(cr);
          if (world.kinV250.archiveCrises.length > 30) world.kinV250.archiveCrises.length = 30;
        }
      }
    }
  }


  // -------------------------------------------------------------------------
  // T5.3 YEARLY KIN LIFECYCLE, MARRIAGES, FEUDS & PUBLIC API
  // -------------------------------------------------------------------------
  function executeMarriageBetweenNpcsV250(world, npcA, npcB, rngInstance = null) {
    if (!world.kinV250) ensureKinV250(world);
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + (world.tick || 0) * 31 + hashStr(npcA.id + npcB.id));
    const houseA = world.kinV250.houses[npcA.kinV250?.houseId] || Object.values(world.kinV250.houses).find((h) => h.stateId === npcA.stateId);
    const houseB = world.kinV250.houses[npcB.kinV250?.houseId] || Object.values(world.kinV250.houses).find((h) => h.stateId === npcB.stateId);
    const stA = world.states[npcA.stateId];
    const stB = world.states[npcB.stateId];

    if (!npcA.family) npcA.family = { married: false, spouseName: null, childrenCount: 0 };
    if (!npcB.family) npcB.family = { married: false, spouseName: null, childrenCount: 0 };
    npcA.family.married = true;
    npcA.family.spouseName = npcB.name;
    npcB.family.married = true;
    npcB.family.spouseName = npcA.name;

    npcA.kinV250.spouse = {
      name: npcB.name,
      originHouseName: houseB ? houseB.name : `ตระกูล${npcB.lastName}`,
      originStateId: npcB.stateId,
      alive: true,
      age: npcB.age,
      npcId: npcB.id
    };
    npcB.kinV250.spouse = {
      name: npcA.name,
      originHouseName: houseA ? houseA.name : `ตระกูล${npcA.lastName}`,
      originStateId: npcA.stateId,
      alive: true,
      age: npcA.age,
      npcId: npcA.id
    };

    addOrUpdateNPCRelationship(world, npcA, npcB, 'family', 85, `คู่สมรสตามพันธะตระกูล (${world.year || 2026})`);
    addOrUpdateNPCRelationship(world, npcB, npcA, 'family', 85, `คู่สมรสตามพันธะตระกูล (${world.year || 2026})`);

    const isCrossState = npcA.stateId !== npcB.stateId;
    const capCity = getCapCityOfStateV250(world, npcA.stateId);

    if (!isCrossState) {
      if (houseA && houseB && houseA.id !== houseB.id) {
        addOrBoostHouseAllianceV250(houseA, houseB, 30);
      }
      const tpl = rng.pick(DYNASTY_DOMESTIC_MARRIAGE_TEMPLATES_V250);
      const msg = fillTemplateV250(tpl, {
        state: stA ? stA.name : npcA.stateId,
        city: capCity ? capCity.name.split(' (')[0] : npcA.stateId,
        groom: npcA.name,
        bride: npcB.name,
        houseA: houseA ? houseA.name : `ตระกูล${npcA.lastName}`,
        houseB: houseB ? houseB.name : `ตระกูล${npcB.lastName}`,
        prestigeA: houseA ? Math.round(houseA.prestige) : 65,
        prestigeB: houseB ? Math.round(houseB.prestige) : 65,
        wealth: ((houseA ? houseA.wealthM : 40) + (houseB ? houseB.wealthM : 40)).toFixed(1),
        year: world.year || 2026
      });
      addChronicle(world, 'DYNASTY', msg, npcA.stateId, { personId: npcA.id, cityId: capCity ? capCity.id : null, subKind: 'DOMESTIC_POLITICAL_MARRIAGE' });
      if (houseA) addHouseHistoryV250(houseA, world.year || 2026, `สมรสการเมืองระหว่าง ${npcA.name} กับ ${npcB.name} (${houseB ? houseB.name : ''})`);
      if (houseB && houseB !== houseA) addHouseHistoryV250(houseB, world.year || 2026, `สมรสการเมืองระหว่าง ${npcB.name} กับ ${npcA.name} (${houseA ? houseA.name : ''})`);
    } else if (stA && stB) {
      if (houseA && houseB) {
        addOrBoostHouseAllianceV250(houseA, houseB, 35);
      }
      if (!stA.relations) stA.relations = {};
      if (!stB.relations) stB.relations = {};
      if (!stA.relations[stB.id]) stA.relations[stB.id] = { status: 'Peace', score: 55 };
      if (!stB.relations[stA.id]) stB.relations[stA.id] = { status: 'Peace', score: 55 };
      const curStatus = stA.relations[stB.id].status;
      const isPeaceMarriage = curStatus === 'Hostile' || curStatus === 'Truce';
      const relGain = isPeaceMarriage ? 10 : 5;
      stA.relations[stB.id].score = clamp((stA.relations[stB.id].score || 55) + relGain, 0, 100);
      stB.relations[stA.id].score = stA.relations[stB.id].score;
      if (isPeaceMarriage) {
        if (stA.trustV230 !== undefined) stA.trustV230 = clamp((stA.trustV230 || 70) + 2, 0, 100);
        if (stB.trustV230 !== undefined) stB.trustV230 = clamp((stB.trustV230 || 70) + 2, 0, 100);
        if (curStatus === 'Hostile' && stA.relations[stB.id].score >= 45) {
          stA.relations[stB.id].status = 'Peace';
          stB.relations[stA.id].status = 'Peace';
        }
      }

      // Addendum Link 4: marriage between members of two states in the same alliance raises alliance cohesion (+3)
      (world.alliances || []).forEach((al) => {
        if (Array.isArray(al.members) && al.members.includes(stA.id) && al.members.includes(stB.id)) {
          al.cohesion = clamp((al.cohesion || 80) + 3, 25, 99);
        }
      });

      // Addendum Link 5: royal wedding gives a one-off commerce/tourism bonus to capital city (economy +1% relative for 30 days)
      if (capCity) {
        capCity.economy = clamp(rnd1((capCity.economy || 80) * 1.01), 20, 100);
        capCity._royalBonusUntilTickV250 = (world.tick || 0) + 30;
      }

      // Claim on the other throne when groom/bride's house is ROYAL (legitimacy 25)
      if (houseA && houseA.type === 'ROYAL' && houseB) {
        if (!Array.isArray(houseB.claims)) houseB.claims = [];
        if (!houseB.claims.some((cl) => cl.stateId === stA.id)) {
          houseB.claims.push({ stateId: stA.id, legitimacy: 25, via: npcA.id });
        }
      }
      if (houseB && houseB.type === 'ROYAL' && houseA) {
        if (!Array.isArray(houseA.claims)) houseA.claims = [];
        if (!houseA.claims.some((cl) => cl.stateId === stB.id)) {
          houseA.claims.push({ stateId: stB.id, legitimacy: 25, via: npcB.id });
        }
      }

      const headA = stA.positions?.HEAD_OF_STATE ? world.npcs[stA.positions.HEAD_OF_STATE] : null;
      const headB = stB.positions?.HEAD_OF_STATE ? world.npcs[stB.positions.HEAD_OF_STATE] : null;
      const giftM = rng.int(12, 65);
      const tpl = rng.pick(DYNASTY_ROYAL_WEDDING_TEMPLATES_V250);
      const msg = fillTemplateV250(tpl, {
        stateA: stA.name,
        stateB: stB.name,
        city: capCity ? capCity.name.split(' (')[0] : shortNameTh(stA),
        groom: npcA.name,
        bride: npcB.name,
        houseA: houseA ? houseA.name : `ตระกูล${npcA.lastName}`,
        houseB: houseB ? houseB.name : `ตระกูล${npcB.lastName}`,
        headA: headA ? headA.name : `ผู้นำ ${shortNameTh(stA)}`,
        headB: headB ? headB.name : `ผู้นำ ${shortNameTh(stB)}`,
        giftM,
        relGain,
        relScore: stA.relations[stB.id].score,
        year: world.year || 2026
      });
      addChronicle(world, 'DYNASTY', msg, stA.id, { personId: npcA.id, secondStateId: stB.id, cityId: capCity ? capCity.id : null, subKind: 'ROYAL_WEDDING' });
      if (houseA) addHouseHistoryV250(houseA, world.year || 2026, `อภิเษกสมรสข้ามรัฐระหว่าง ${npcA.name} กับ ${npcB.name} แห่ง ${shortNameTh(stB)}`);
      if (houseB) addHouseHistoryV250(houseB, world.year || 2026, `อภิเษกสมรสข้ามรัฐระหว่าง ${npcB.name} กับ ${npcA.name} แห่ง ${shortNameTh(stA)}`);
    }

    const marRec = {
      id: 'MAR_' + (++world.kinV250.nextId),
      year: world.year || 2026,
      tick: world.tick || 0,
      npcAId: npcA.id,
      npcBId: npcB.id,
      spouseName: npcB.name,
      houseAId: houseA ? houseA.id : null,
      houseBId: houseB ? houseB.id : null,
      stateAId: npcA.stateId,
      stateBId: npcB.stateId,
      kind: isCrossState ? 'CROSS_STATE' : 'DOMESTIC_POLITICAL'
    };
    world.kinV250.marriages.unshift(marRec);
    if (world.kinV250.marriages.length > 150) world.kinV250.marriages.length = 150; // cap 150
    return marRec;
  }

  function runAnnualKinCycleV250(world, rngInstance = null) {
    if (!world || !world.states) return;
    if (!world.kinV250 || !world.kinV250._graphBuilt) ensureKinV250(world);
    const sameTickRepeat = !rngInstance && world._lastKinCycleTickV250 === world.tick;
    world._lastKinCycleTickV250 = world.tick;
    if (!sameTickRepeat) capStateAliveNpcsV250(world, 90);
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + (world.year || 2026) * 9973 + (world.tick || 0));

    const aliveNpcs = [];
    const aliveCountByState = {};
    for (const k in world.npcs) {
      const n = world.npcs[k];
      if (n && n.alive) {
        aliveNpcs.push(n);
        aliveCountByState[n.stateId] = (aliveCountByState[n.stateId] || 0) + 1;
      }
    }
    const conversionsByState = {};
    world._lastDebutNpcsV260 = [];

    // 1. Children infant mortality (<5, p=0.006/yr) & Spouse aging/death (age >= 70, p = (age-68)*0.04)
    aliveNpcs.forEach((npc) => {
      const k = npc.kinV250;
      if (!k || ((!k.children || k.children.length === 0) && !k.spouse)) return;
      const children = npc.kinV250.children || [];
      children.forEach((ch) => {
        if (ch.npcId && world.npcs[ch.npcId]) {
          ch.alive = !!world.npcs[ch.npcId].alive;
        } else if (ch.alive) {
          const cAge = (world.year || 2026) - (ch.birthYear || 2026);
          if (cAge >= 0 && cAge < 5 && rng.chance(0.006)) {
            ch.alive = false;
          }
        }
      });

      const sp = npc.kinV250.spouse;
      if (sp && sp.alive) {
        if (sp.npcId && world.npcs[sp.npcId]) {
          sp.alive = !!world.npcs[sp.npcId].alive;
          sp.age = world.npcs[sp.npcId].age;
          if (!sp.alive && npc.family) npc.family.married = false;
        } else {
          sp.age = (sp.age || npc.age) + 1;
          if (sp.age >= 70 && rng.chance((sp.age - 68) * 0.04)) {
            sp.alive = false;
            if (npc.family) npc.family.married = false;
            npc.wealthM = rnd1((npc.wealthM || 10) + 4);
          }
        }
      }
    });

    // 2. Births: alive married NPC aged 24-44 with < 3 children: p = 0.16/yr (0.10 if age >= 38)
    let birthStoriesLogged = 0;
    let debutStoriesLogged = 0;
    let totalDebutsThisYear = 0;
    aliveNpcs.forEach((npc) => {
      if (!npc.alive || !npc.kinV250) return;
      if (!npc.family || !npc.family.married) return;
      if (npc.age < 24 || npc.age > 44) return;
      const chArr = npc.kinV250.children || [];
      let aliveKidsLen = 0;
      for (let k = 0; k < chArr.length; k++) { if (chArr[k].alive) aliveKidsLen++; }
      if (aliveKidsLen >= 3) return;
      const pBirth = npc.age >= 38 ? 0.10 : 0.16;
      if (!rng.chance(pBirth)) return;

      const g = rng.chance(0.52) ? 'M' : 'F';
      const cFirst = pickFirstNameV250(world, npc.stateId, g, rng);
      const childRec = {
        id: 'CHD_' + (++world.kinV250.nextId),
        name: `${cFirst} ${npc.lastName}`,
        gender: g,
        birthYear: world.year || 2026,
        alive: true,
        talent: clamp(Math.round(((npc.intelligence || 65) + (npc.meritScore || 60)) * 0.5 + rng.int(-12, 12)), 20, 99),
        ambition: clamp(Math.round((npc.personality?.ambition || 60) + rng.int(-12, 12)), 15, 99),
        npcId: null,
        inheritedM: 0
      };
      npc.kinV250.children.push(childRec);
      npc.family.childrenCount = aliveKidsLen + 1;

      // Also sync to spouse NPC if real NPC
      const spNpc = npc.kinV250.spouse?.npcId ? world.npcs[npc.kinV250.spouse.npcId] : null;
      if (spNpc && spNpc.alive && spNpc.kinV250 && !spNpc.kinV250.children.some((c) => c.id === childRec.id)) {
        spNpc.kinV250.children.push(childRec);
        if (spNpc.family) spNpc.family.childrenCount = spNpc.kinV250.children.filter((c) => c.alive).length;
      }

      const house = world.kinV250.houses[npc.kinV250.houseId];
      if (birthStoriesLogged < 1 && house && (house.type === 'ROYAL' || ((house.type === 'POLITICAL' || house.type === 'MILITARY') && (house.prestige || 50) >= 60))) {
        birthStoriesLogged++;
        const st = world.states[npc.stateId];
        const capCity = getCapCityOfStateV250(world, npc.stateId);
        const linePos = house.type === 'ROYAL' ? Math.max(1, aliveKidsLen + 1) : (aliveKidsLen + 1);
        const tpl = rng.pick(DYNASTY_BIRTH_TEMPLATES_V250);
        const msg = fillTemplateV250(tpl, {
          house: house.name,
          state: st ? st.name : npc.stateId,
          city: capCity ? capCity.name.split(' (')[0] : npc.stateId,
          child: childRec.name,
          parent: npc.name,
          spouse: npc.kinV250.spouse ? npc.kinV250.spouse.name : (npc.family.spouseName || 'คู่สมรส'),
          prestige: Math.round(house.prestige || 65),
          wealth: (house.wealthM || 50).toFixed(1),
          talent: childRec.talent,
          ambition: childRec.ambition,
          linePos,
          year: world.year || 2026
        });
        addChronicle(world, 'DYNASTY', msg, npc.stateId, { personId: npc.id, cityId: capCity ? capCity.id : null, subKind: 'BIRTH_OF_HEIR' });
      }
    });

    // 3. Coming of age: child turning 22 in a house with prestige >= 55 or type ROYAL/POLITICAL (parent stage >= 5)
    aliveNpcs.forEach((parent) => {
      if (totalDebutsThisYear >= 2 || !parent.alive || !parent.kinV250 || !parent.kinV250.children || parent.kinV250.children.length === 0) return;
      const house = world.kinV250.houses[parent.kinV250.houseId];
      if (!house) return;
      const qualifiesHouse = (house.prestige || 50) >= 55 || ((house.type === 'ROYAL' || house.type === 'POLITICAL') && (parent.stage || 3) >= 5);
      if (!qualifiesHouse) return;

      const stId = parent.stateId;
      if (!world.states[stId] || world.states[stId].isExiled) return;

      (parent.kinV250.children || []).forEach((ch) => {
        if (!ch.alive || ch.npcId) return;
        const cAge = (world.year || 2026) - (ch.birthYear || 2026);
        if (cAge !== 22) return;
        if (totalDebutsThisYear >= 2) return;
        if ((conversionsByState[stId] || 0) >= 3) return;
        if ((aliveCountByState[stId] || 0) >= 90) return;
        totalDebutsThisYear++;

        const chosenTrack = rng.chance(0.60) ? (parent.track || 'political') : rng.pick(['military', 'political', 'civilian', 'business']);
        const capC = getCapCityOfStateV250(world, stId);
        const newNpc = generateContextualNPC(world, rng, {
          stateId: stId,
          homeCityId: parent.homeCityId || (capC ? capC.id : null),
          assignedNodeId: parent.assignedNodeId || (capC ? capC.id : null),
          age: 22,
          gender: ch.gender || 'M',
          positionId: 'JUNIOR_OFFICER',
          track: chosenTrack
        });
        const firstPart = (ch.name && ch.name.split(' ')[0]) || newNpc.firstName;
        newNpc.firstName = firstPart;
        newNpc.lastName = parent.lastName;
        newNpc.name = `${firstPart} ${parent.lastName}`;
        newNpc.age = 22;
        newNpc.birthYear = (world.year || 2026) - 22;
        newNpc.meritScore = clamp((newNpc.meritScore || 50) + 8, 10, 99);
        newNpc.reputation = clamp((newNpc.reputation || 50) + 5, 10, 99);
        newNpc.wealthM = rnd1((newNpc.wealthM || 5) + (ch.inheritedM || 0));
        if (rng.chance(0.40) && parent.personality && parent.personality.ideology && newNpc.personality) {
          newNpc.personality.ideology = parent.personality.ideology;
        }
        newNpc.kinV250 = {
          houseId: house.id,
          fatherId: parent.id,
          motherName: parent.gender === 'F' ? parent.name : (parent.kinV250.spouse?.name || `มารดาแห่ง${house.name}`),
          spouse: null,
          children: [],
          siblingIds: [],
          generation: (parent.kinV250.generation || 0) + 1,
          role: 'MEMBER',
          _bootstrapped: true
        };

        // Link siblings
        (parent.kinV250.children || []).forEach((otherCh) => {
          if (otherCh.npcId && otherCh.npcId !== newNpc.id && world.npcs[otherCh.npcId]) {
            const sib = world.npcs[otherCh.npcId];
            if (!newNpc.kinV250.siblingIds.includes(sib.id)) newNpc.kinV250.siblingIds.push(sib.id);
            if (sib.kinV250 && !sib.kinV250.siblingIds.includes(newNpc.id)) sib.kinV250.siblingIds.push(newNpc.id);
            addOrUpdateNPCRelationship(world, newNpc, sib, 'family', 68, `พี่น้องร่วมสายเลือดใน${house.name}`);
            addOrUpdateNPCRelationship(world, sib, newNpc, 'family', 68, `พี่น้องร่วมสายเลือดใน${house.name}`);
          }
        });

        ch.npcId = newNpc.id;
        ch.name = newNpc.name;
        if (world._lastDebutNpcsV260) world._lastDebutNpcsV260.push(newNpc);
        if (!house.memberIds.includes(newNpc.id)) house.memberIds.push(newNpc.id);

        if (typeof ensureNPCDeepProfileV170 === 'function') ensureNPCDeepProfileV170(world, newNpc, rng);
        if (typeof ensureNPCPowerModelV200 === 'function') ensureNPCPowerModelV200(world, newNpc);

        addOrUpdateNPCRelationship(world, newNpc, parent, 'family', 70, `ทายาทสายตรงของ ${parent.name} (${house.name})`);
        addOrUpdateNPCRelationship(world, parent, newNpc, 'family', 70, `บิดา/มารดาของ ${newNpc.name} (${house.name})`);
        const spNpc = parent.kinV250.spouse?.npcId ? world.npcs[parent.kinV250.spouse.npcId] : null;
        if (spNpc && spNpc.alive) {
          addOrUpdateNPCRelationship(world, newNpc, spNpc, 'family', 70, `ทายาทสายตรงของ ${spNpc.name}`);
          addOrUpdateNPCRelationship(world, spNpc, newNpc, 'family', 70, `บิดา/มารดาของ ${newNpc.name}`);
        }

        recordNPCMemory(newNpc, world.year || 2026, `บรรลุนิติภาวะวัย 22 ปี ก้าวเข้าสู่สายงาน ${chosenTrack} ในฐานะทายาทแห่ง${house.name}`);
        if (typeof recordNPCMemory20 === 'function') {
          recordNPCMemory20(newNpc, world.year || 2026, 'family', `เปิดตัวเข้าสู่วงการสาย ${chosenTrack} ด้วยบารมีของ${house.name}`, 80, `person:${parent.id}`);
        }

        conversionsByState[stId] = (conversionsByState[stId] || 0) + 1;
        aliveCountByState[stId] = (aliveCountByState[stId] || 0) + 1;

        if (debutStoriesLogged < 1) {
          debutStoriesLogged++;
          const st = world.states[stId];
          const capCity = getCapCityOfStateV250(world, stId);
          const tpl = rng.pick(DYNASTY_COMING_OF_AGE_TEMPLATES_V250);
          const msg = fillTemplateV250(tpl, {
            child: newNpc.name,
            parent: parent.name,
            house: house.name,
            state: st ? st.name : stId,
            city: capCity ? capCity.name.split(' (')[0] : stId,
            track: chosenTrack,
            prestige: Math.round(house.prestige || 65),
            wealth: (house.wealthM || 50).toFixed(1),
            merit: newNpc.meritScore,
            year: world.year || 2026
          });
          addChronicle(world, 'DYNASTY', msg, stId, { personId: newNpc.id, cityId: capCity ? capCity.id : null, subKind: 'COMING_OF_AGE_DEBUT' });
        }
      });
    });

    // 4. Dynastic marriages: unmarried NPC aged 24-45 of ROYAL or POLITICAL house with prestige >= 55
    const marriageCands = aliveNpcs.filter((n) => {
      if (!n || !n.alive || n.retired) return false;
      if (n.family && n.family.married) return false;
      if (n.age < 24 || n.age > 45) return false;
      const h = n.kinV250 && world.kinV250.houses[n.kinV250.houseId];
      if (!h) return false;
      return (h.type === 'ROYAL' || h.type === 'POLITICAL') && (h.prestige || 50) >= 55;
    });

    let crossStateMarriagesThisYear = 0;
    let domesticMarriagesThisYear = 0;
    for (let i = 0; i < marriageCands.length; i++) {
      if (domesticMarriagesThisYear >= 1 && crossStateMarriagesThisYear >= 1) break;
      const npcA = marriageCands[i];
      if (!npcA.alive || (npcA.family && npcA.family.married)) continue;
      const houseA = world.kinV250.houses[npcA.kinV250.houseId];
      if (!houseA) continue;

      // a) Domestic political marriage: p = 0.06/yr
      if (domesticMarriagesThisYear < 1 && rng.chance(0.06)) {
        const partner = marriageCands.find((n) => {
          if (!n.alive || n.id === npcA.id || (n.family && n.family.married)) return false;
          if (n.stateId !== npcA.stateId) return false;
          if (n.kinV250.houseId === houseA.id) return false;
          const hB = world.kinV250.houses[n.kinV250.houseId];
          return hB && Math.abs((hB.prestige || 55) - (houseA.prestige || 55)) <= 25;
        });
        if (partner) {
          executeMarriageBetweenNpcsV250(world, npcA, partner, rng);
          domesticMarriagesThisYear++;
          continue;
        }
      }

      // b) Cross-state alliance/peace marriage: p = 0.04/yr (cap 2/yr worldwide, 4 if Hostile/Truce)
      if (crossStateMarriagesThisYear < 1 && rng.chance(0.04)) {
        const stA = world.states[npcA.stateId];
        if (!stA) continue;
        const partner = marriageCands.find((n) => {
          if (!n.alive || n.id === npcA.id || (n.family && n.family.married)) return false;
          if (n.stateId === npcA.stateId) return false;
          const rel = stA.relations && stA.relations[n.stateId];
          const score = rel ? rel.score : 50;
          const isHostileOrTruce = rel && (rel.status === 'Hostile' || rel.status === 'Truce');
          if (crossStateMarriagesThisYear >= 2 && !isHostileOrTruce) return false;
          return score >= 55 || isHostileOrTruce;
        });
        if (partner) {
          executeMarriageBetweenNpcsV250(world, npcA, partner, rng);
          crossStateMarriagesThisYear++;
        }
      }
    }

    // 6. House metrics refreshed yearly
    if (sameTickRepeat) return;
    world.kinV250._keepExtinctHouses = true;
    let fallLogsThisYear = 0;
    let riseLogsThisYear = 0;
    const housesList = world.kinV250._housesArr || (Object.defineProperty(world.kinV250, '_housesArr', { value: Object.values(world.kinV250.houses), enumerable: false, writable: true, configurable: true }), world.kinV250._housesArr);
    const yrMod = (world.year || 2026) & 7;
    for (let hIdx = 0; hIdx < housesList.length; hIdx++) {
      const house = housesList[hIdx];
      const mIds = house.memberIds || [];
      if (mIds.length === 1 && house.type !== 'ROYAL' && ((hIdx & 7) !== yrMod)) {
        const singleNpc = world.npcs[mIds[0]];
        if (singleNpc && singleNpc.alive) continue;
      }
      let aliveCount = 0;
      let highStageAuthSum = 0;
      let wealthSum = 0;
      let hasHeadRole = false;
      for (let mIdx = 0; mIdx < mIds.length; mIdx++) {
        const n = world.npcs[mIds[mIdx]];
        if (n && n.alive) {
          mIds[aliveCount++] = n.id;
          if ((n.stage || 1) >= 5) highStageAuthSum += (n.authority || 55);
          if (n.positionId === 'HEAD_OF_STATE' || n.positionId === 'PRIME_MINISTER') hasHeadRole = true;
          wealthSum += (n.wealthM || 5);
        }
      }
      mIds.length = aliveCount;

      if (aliveCount === 0) {
        if (!house.extinct) {
          house.extinct = true;
          house.prestige = 0;
          house.wealthM = 0;
          if (fallLogsThisYear < 1) {
            fallLogsThisYear++;
            const st = world.states[house.stateId];
            const capCity = getCapCityOfStateV250(world, house.stateId);
            const tpl = rng.pick(DYNASTY_HOUSE_FALL_TEMPLATES_V250);
            const msg = fillTemplateV250(tpl, {
              house: house.name,
              state: st ? st.name : house.stateId,
              city: capCity ? capCity.name.split(' (')[0] : house.stateId,
              year: world.year || 2026
            });
            addChronicle(world, 'DYNASTY', msg, house.stateId, { cityId: capCity ? capCity.id : null, subKind: 'HOUSE_FALL' });
          }
        }
        continue;
      }

      house.extinct = false;
      const roleBonus = (house.type === 'ROYAL' ? 8 : 2) + (hasHeadRole ? 6 : 0);
      const newPrestige = clamp(Math.round((house.prestige || 50) * 0.9 + 0.6 * (highStageAuthSum / aliveCount) + roleBonus), 5, 100);

      if (house.minPrestige10Yr === undefined || newPrestige < house.minPrestige10Yr) {
        house.minPrestige10Yr = Math.min(house.prestige || 50, newPrestige);
      }
      const gain = newPrestige - (house.minPrestige10Yr || 50);
      if (riseLogsThisYear < 1 && gain >= 25 && (world.year || 2026) - (house._lastRiseLoggedYear || 0) >= 10) {
        riseLogsThisYear++;
        house._lastRiseLoggedYear = world.year || 2026;
        house.minPrestige10Yr = newPrestige;
        const st = world.states[house.stateId];
        const capCity = getCapCityOfStateV250(world, house.stateId);
        const tpl = rng.pick(DYNASTY_HOUSE_RISE_TEMPLATES_V250);
        const msg = fillTemplateV250(tpl, {
          house: house.name,
          state: st ? st.name : house.stateId,
          city: capCity ? capCity.name.split(' (')[0] : house.stateId,
          gain: Math.round(gain),
          prestige: newPrestige,
          wealth: wealthSum.toFixed(1),
          members: aliveCount,
          year: world.year || 2026
        });
        addChronicle(world, 'DYNASTY', msg, house.stateId, { personId: house.headOfHouseId, cityId: capCity ? capCity.id : null, subKind: 'HOUSE_RISE' });
      }

      house.prestige = newPrestige;
      house.wealthM = Math.round(wealthSum * 10) / 10;
      if (world.dynasties && world.dynasties[house.id]) {
        const d = world.dynasties[house.id];
        d.membersCount = aliveCount;
        d.prestige = newPrestige;
        d.wealthM = house.wealthM;
      }
    }
  }

  // -------------------------------------------------------------------------
  // T5.5 FEUDS, BLOOD FEUDS & RECONCILIATION (Monthly t % 30 === 17)
  // -------------------------------------------------------------------------
  function triggerBloodFeudV250(world, victimNpc, culpritStateId = null, culpritNpcId = null, causeText = 'การลอบสังหารและประทุษร้ายคนในตระกูล', rngInstance = null) {
    if (!world || !victimNpc) return null;
    ensureKinV250(world);
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + (world.tick || 0) * 43 + hashStr(victimNpc.id));
    const houseA = (victimNpc.kinV250 && world.kinV250.houses[victimNpc.kinV250.houseId]) || Object.values(world.kinV250.houses).find((h) => h.stateId === victimNpc.stateId);
    if (!houseA) return null;

    let houseB = null;
    let targetNpc = culpritNpcId ? world.npcs[culpritNpcId] : null;
    if (targetNpc && targetNpc.kinV250 && world.kinV250.houses[targetNpc.kinV250.houseId] && targetNpc.kinV250.houseId !== houseA.id) {
      houseB = world.kinV250.houses[targetNpc.kinV250.houseId];
    } else if (culpritStateId && world.states[culpritStateId]) {
      const cSt = world.states[culpritStateId];
      const cHead = cSt.positions?.HEAD_OF_STATE ? world.npcs[cSt.positions.HEAD_OF_STATE] : null;
      if (cHead && cHead.kinV250 && world.kinV250.houses[cHead.kinV250.houseId] && cHead.kinV250.houseId !== houseA.id) {
        houseB = world.kinV250.houses[cHead.kinV250.houseId];
        targetNpc = cHead;
      }
    }
    if (!houseB) {
      houseB = Object.values(world.kinV250.houses)
        .filter((h) => h.stateId === victimNpc.stateId && h.id !== houseA.id && (h.memberIds || []).some((id) => world.npcs[id]?.alive))
        .sort((a, b) => (b.prestige || 0) - (a.prestige || 0))[0] ||
        Object.values(world.kinV250.houses).find((h) => h.id !== houseA.id);
    }
    if (!houseB) return null;
    if (!targetNpc || !targetNpc.alive) {
      targetNpc = (houseB.headOfHouseId && world.npcs[houseB.headOfHouseId]) || (houseB.memberIds || []).map((id) => world.npcs[id]).find((n) => n && n.alive) || null;
    }

    const res = addOrEscalateFeudV250(houseA, houseB, 55, causeText, world.tick || 0);
    const feud = res ? res.feud : null;

    // Adult kin in houseA may launch a REVENGE assassination plot (25% chance when startAssassinationPlotV240 exists)
    const adultKin = (houseA.memberIds || [])
      .map((id) => world.npcs[id])
      .find((n) => n && n.alive && n.id !== victimNpc.id && (n.age || 30) >= 18);

    const startPlotFn = getSoftLinkFnV250('startAssassinationPlotV240', typeof startAssassinationPlotV240 === 'function' ? startAssassinationPlotV240 : undefined);
    if (adultKin && targetNpc && targetNpc.alive && typeof startPlotFn === 'function' && rng.chance(0.25)) {
      startPlotFn(world, {
        sponsorId: null,
        plannerId: adultKin.id,
        targetId: targetNpc.id,
        kind: 'REVENGE'
      });
      const st = world.states[victimNpc.stateId];
      const capCity = Object.values(world.cities || {}).find((c) => c.stateId === victimNpc.stateId && c.isCapital) || Object.values(world.cities || {}).find((c) => c.stateId === victimNpc.stateId);
      const tpl = rng.pick(DYNASTY_REVENGE_TEMPLATES_V250);
      const msg = fillTemplateV250(tpl, {
        avenger: adultKin.name,
        houseA: houseA.name,
        state: st ? st.name : victimNpc.stateId,
        city: capCity ? capCity.name.split(' (')[0] : victimNpc.stateId,
        target: targetNpc.name,
        intensity: feud ? feud.intensity : 75,
        year: world.year || 2026
      });
      addChronicle(world, 'DYNASTY', msg, victimNpc.stateId, { personId: adultKin.id, cityId: capCity ? capCity.id : null, subKind: 'REVENGE' });
    }
    return feud;
  }

  function runMonthlyFeudCycleV250(world, rngInstance = null) {
    if (!world || !world.states) return;
    ensureKinV250(world);
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + (world.tick || 0) * 541);
    const curTick = world.tick || 0;

    // Group active houses by state
    const housesByState = {};
    Object.values(world.kinV250.houses).forEach((h) => {
      if (h.extinct || !(h.memberIds || []).some((id) => world.npcs[id]?.alive)) return;
      if (!housesByState[h.stateId]) housesByState[h.stateId] = [];
      housesByState[h.stateId].push(h);
    });

    // a) Rivalry feuds: for each state process <= 6 random houses
    Object.keys(housesByState).forEach((stateId) => {
      const st = world.states[stateId];
      if (!st || st.isExiled) return;
      const list = housesByState[stateId];
      if (list.length < 2) return;
      const sampleCount = Math.min(6, list.length);
      const sampled = [];
      for (let k = 0; k < sampleCount; k++) {
        const pickH = list[(k + rng.int(0, list.length - 1)) % list.length];
        if (!sampled.includes(pickH)) sampled.push(pickH);
      }

      for (let i = 0; i < sampled.length; i++) {
        for (let j = i + 1; j < sampled.length; j++) {
          const hA = sampled[i];
          const hB = sampled[j];
          const memA = (hA.memberIds || []).map((id) => world.npcs[id]).find((n) => n && n.alive && (n.stage || 1) >= 6);
          const memB = (hB.memberIds || []).map((id) => world.npcs[id]).find((n) => n && n.alive && (n.stage || 1) >= 6);
          if (memA && memB && memA.faction !== memB.faction && rng.chance(0.05)) {
            const delta = rng.int(8, 20);
            const res = addOrEscalateFeudV250(hA, hB, delta, `การแย่งชิงอำนาจระหว่างขั้ว ${memA.faction} และ ${memB.faction}`, curTick);
            if (res && res.feud) {
              const capCity = Object.values(world.cities || {}).find((c) => c.stateId === stateId && c.isCapital) || Object.values(world.cities || {}).find((c) => c.stateId === stateId);
              if (res.isNew) {
                const tpl = rng.pick(DYNASTY_FEUD_START_TEMPLATES_V250);
                const msg = fillTemplateV250(tpl, {
                  state: st.name,
                  city: capCity ? capCity.name.split(' (')[0] : shortNameTh(st),
                  houseA: hA.name,
                  houseB: hB.name,
                  headA: memA.name,
                  headB: memB.name,
                  intensity: res.feud.intensity,
                  year: world.year || 2026
                });
                addChronicle(world, 'DYNASTY', msg, stateId, { personId: memA.id, cityId: capCity ? capCity.id : null, subKind: 'FEUD_START' });
              } else if (res.feud.intensity >= 70) {
                addOrUpdateNPCRelationship(world, memA, memB, 'rival', -55, `คู่แค้นตระกูล ${hA.name} vs ${hB.name}`);
                addOrUpdateNPCRelationship(world, memB, memA, 'rival', -55, `คู่แค้นตระกูล ${hB.name} vs ${hA.name}`);
                addOrBoostHouseAllianceV250(hA, hB, -20);
                const tpl = rng.pick(DYNASTY_FEUD_ESCALATION_TEMPLATES_V250);
                const msg = fillTemplateV250(tpl, {
                  state: st.name,
                  city: capCity ? capCity.name.split(' (')[0] : shortNameTh(st),
                  houseA: hA.name,
                  houseB: hB.name,
                  headA: memA.name,
                  headB: memB.name,
                  intensity: res.feud.intensity,
                  year: world.year || 2026
                });
                addChronicle(world, 'DYNASTY', msg, stateId, { personId: memA.id, cityId: capCity ? capCity.id : null, subKind: 'FEUD_ESCALATION' });
              }
            }
          }
        }
      }
    });

    // Decay feuds 2/month & c) Reconciliation: 4% per month for feuds >= 1 year old (360 ticks)
    const processedPairs = new Set();
    Object.values(world.kinV250.houses).forEach((hA) => {
      if (!Array.isArray(hA.feuds) || hA.feuds.length === 0) return;
      for (let idx = hA.feuds.length - 1; idx >= 0; idx--) {
        const f = hA.feuds[idx];
        const hB = world.kinV250.houses[f.houseId];
        if (!hB) {
          hA.feuds.splice(idx, 1);
          continue;
        }
        const pairKey = hA.id < hB.id ? `${hA.id}|${hB.id}` : `${hB.id}|${hA.id}`;
        if (processedPairs.has(pairKey)) continue;
        processedPairs.add(pairKey);

        const ageTicks = curTick - (f.sinceTick || 0);
        if (ageTicks >= 360 && rng.chance(0.04)) {
          f.intensity = clamp((f.intensity || 30) - 40, 0, 100);
          const st = world.states[hA.stateId];
          const capCity = Object.values(world.cities || {}).find((c) => c.stateId === hA.stateId && c.isCapital) || Object.values(world.cities || {}).find((c) => c.stateId === hA.stateId);
          const headA = world.npcs[hA.headOfHouseId] || { name: `ผู้นำ${hA.name}` };
          const headB = world.npcs[hB.headOfHouseId] || { name: `ผู้นำ${hB.name}` };
          const tpl = rng.pick(DYNASTY_RECONCILIATION_TEMPLATES_V250);
          const msg = fillTemplateV250(tpl, {
            state: st ? st.name : hA.stateId,
            city: capCity ? capCity.name.split(' (')[0] : hA.stateId,
            houseA: hA.name,
            houseB: hB.name,
            headA: headA.name,
            headB: headB.name,
            intensity: f.intensity,
            year: world.year || 2026
          });
          addChronicle(world, 'DYNASTY', msg, hA.stateId, { personId: headA.id || null, cityId: capCity ? capCity.id : null, subKind: 'RECONCILIATION' });
        } else {
          f.intensity = clamp((f.intensity || 20) - 2, 0, 100);
        }

        const fB = (hB.feuds || []).find((x) => x.houseId === hA.id);
        if (f.intensity <= 0) {
          hA.feuds.splice(idx, 1);
          if (hB.feuds) hB.feuds = hB.feuds.filter((x) => x.houseId !== hA.id);
        } else if (fB) {
          fB.intensity = f.intensity;
        }
      }
    });
  }

  // -------------------------------------------------------------------------
  // T5.6 PUBLIC API
  // -------------------------------------------------------------------------
  function getKinOfV250(world, npcId) {
    if (!world || !npcId || !world.npcs || !world.npcs[npcId]) {
      return { father: null, mother: null, spouse: null, children: [], siblings: [], house: null };
    }
    ensureKinV250(world);
    const npc = world.npcs[npcId];
    const k = npc.kinV250 || {};
    const father = (k.fatherId && world.npcs[k.fatherId]) ? world.npcs[k.fatherId] : null;
    const mother = k.motherName ? { name: k.motherName } : null;
    const spouse = k.spouse ? (k.spouse.npcId && world.npcs[k.spouse.npcId] ? { ...k.spouse, npc: world.npcs[k.spouse.npcId] } : k.spouse) : null;
    const children = (k.children || []).map((c) => ({
      ...c,
      npc: c.npcId && world.npcs[c.npcId] ? world.npcs[c.npcId] : null
    }));
    const siblings = (k.siblingIds || []).map((id) => world.npcs[id]).filter(Boolean);
    const house = (k.houseId && world.kinV250.houses[k.houseId]) ? world.kinV250.houses[k.houseId] : null;
    return { father, mother, spouse, children, siblings, house };
  }

  function arrangeMarriageV250(world, npcAId, npcBId) {
    if (!world || !world.npcs) return { ok: false, reason: 'ไม่พบข้อมูลโลกจำลอง' };
    ensureKinV250(world);
    const npcA = world.npcs[npcAId];
    const npcB = world.npcs[npcBId];
    if (!npcA || !npcB || npcAId === npcBId) {
      return { ok: false, reason: 'ไม่พบตัวละครทั้งสองฝ่ายหรือไม่สามารถสมรสกับตนเองได้' };
    }
    if (!npcA.alive || !npcB.alive) {
      return { ok: false, reason: 'ไม่สามารถจัดพิธีสมรสได้เนื่องจากฝ่ายหนึ่งเสียชีวิตแล้ว' };
    }
    if ((npcA.age || 0) < 18 || (npcB.age || 0) < 18) {
      return { ok: false, reason: 'ไม่สามารถสมรสได้เนื่องจากยังไม่บรรลุนิติภาวะ (อายุต่ำกว่า 18 ปี)' };
    }
    if ((npcA.family && npcA.family.married) || (npcB.family && npcB.family.married)) {
      return { ok: false, reason: 'ไม่สามารถสมรสซ้อนได้เนื่องจากฝ่ายใดฝ่ายหนึ่งมีคู่สมรสอยู่แล้ว' };
    }
    const isSibling =
      (npcA.kinV250?.siblingIds || []).includes(npcB.id) ||
      (npcB.kinV250?.siblingIds || []).includes(npcA.id) ||
      (npcA.kinV250?.fatherId && npcA.kinV250.fatherId === npcB.kinV250?.fatherId) ||
      npcA.kinV250?.fatherId === npcB.id ||
      npcB.kinV250?.fatherId === npcA.id;
    if (isSibling) {
      return { ok: false, reason: 'ไม่สามารถสมรสได้เนื่องจากเป็นพี่น้องหรือสายเลือดตรงในครอบครัวเดียวกัน' };
    }

    const marriage = executeMarriageBetweenNpcsV250(world, npcA, npcB);
    return { ok: true, reason: 'จัดพิธีมงคลสมรสสำเร็จ', marriage };
  }

  function getLineOfSuccessionV250(world, stateId, n = 5) {
    if (!world || !world.states || !world.states[stateId]) return [];
    ensureKinV250(world);
    const st = world.states[stateId];
    const head = st.positions?.HEAD_OF_STATE ? world.npcs[st.positions.HEAD_OF_STATE] : null;
    const houseId = (head && head.kinV250 && head.kinV250.houseId) || st._royalHouseIdV250;
    const house = (houseId && world.kinV250.houses[houseId]) || Object.values(world.kinV250.houses).find((h) => h.stateId === stateId);
    if (!house) return [];
    const ordered = computeOrderedSuccessionHeirsV250(world, st, house, head);
    return ordered.slice(0, n);
  }

  function getHouseSummaryV250(world, houseId) {
    if (!world) return null;
    ensureKinV250(world);
    const h = world.kinV250.houses[houseId];
    if (!h) return null;
    const members = (h.memberIds || []).map((id) => world.npcs[id]).filter(Boolean);
    const head = h.headOfHouseId ? world.npcs[h.headOfHouseId] : null;
    return {
      ...h,
      head,
      members,
      aliveMemberCount: members.filter((m) => m.alive).length
    };
  }


  // =========================================================================
  // T8 — UNDERGROUND POLITICS: SEPARATISM (T8.2) & REFERENDUMS (T8.3)
