  // -------------------------------------------------------------------------
  // T8.1 ENSURE UNDERGROUND V250 & STATE FIELDS
  // -------------------------------------------------------------------------
  function computeDefaultTerrorThreatV250(world, st) {
    if (!st) return 15;
    const regDiss = st.politicalPressures?.regionalDissatisfaction ?? 25;
    const stab = st.stability ?? 75;
    const atWar = getWarsOf(world, st.id).length > 0 ? 10 : 0;
    const hasOcc = Object.values(world.cities || {}).some((c) => c.stateId === st.id && c.isOccupied) ? 10 : 0;
    const armedMovs = ((world.undergroundV250 && world.undergroundV250.movements) || []).filter((m) => m.stateId === st.id && m.armed).length;
    return clamp(Math.round(0.3 * regDiss + 0.2 * (100 - stab) + atWar + hasOcc + 8 * armedMovs), 0, 100);
  }

  function ensureUndergroundV250(world) {
    if (!world || !world.states) return;
    if (!world.undergroundV250) {
      world.undergroundV250 = {
        nextId: 1,
        movements: [],         // cap 12 active
        movementArchive: [],   // cap 40 archive
        referendums: [],       // cap 6 active
        referendumArchive: [], // cap 40 archive
        attacks: [],           // cap 40 recent
        attackArchive: [],     // cap 100 archive
        hostageCrises: []      // cap 3 active
      };
    } else {
      const u = world.undergroundV250;
      if (!Array.isArray(u.movements)) u.movements = [];
      if (!Array.isArray(u.movementArchive)) u.movementArchive = [];
      if (!Array.isArray(u.referendums)) u.referendums = [];
      if (!Array.isArray(u.referendumArchive)) u.referendumArchive = [];
      if (!Array.isArray(u.attacks)) u.attacks = [];
      if (!Array.isArray(u.attackArchive)) u.attackArchive = [];
      if (!Array.isArray(u.hostageCrises)) u.hostageCrises = [];
    }

    const stKeysLen = `${Object.keys(world.states).length}_${world.nextId || 0}`;
    if (world.undergroundV250._statesInitV250 === stKeysLen) return;
    world.undergroundV250._statesInitV250 = stKeysLen;

    Object.values(world.states).forEach((st) => {
      if (!st) return;
      if (st.terrorThreatV250 === undefined || Number.isNaN(st.terrorThreatV250)) {
        st.terrorThreatV250 = computeDefaultTerrorThreatV250(world, st);
      }
      if (st.securityPostureV250 === undefined || Number.isNaN(st.securityPostureV250)) {
        st.securityPostureV250 = 40;
      }
      if (st.executivePowerV250 === undefined || Number.isNaN(st.executivePowerV250)) {
        st.executivePowerV250 = st.regimeCategory === 'Democracy' ? 50 : 85;
      }
    });
  }

  // -------------------------------------------------------------------------
  // T8.2 SEPARATIST / AUTONOMY MOVEMENTS ENGINE
  // -------------------------------------------------------------------------
  function getClusterGdpSharePctV250(world, stateId, cityIds) {
    const allStCities = Object.values(world.cities || {}).filter((c) => c.stateId === stateId);
    if (allStCities.length === 0) return 15;
    const totalW = allStCities.reduce((s, c) => s + (c.popM || 1.5) * (c.economy || 75), 0) || 100;
    const clusterCities = (cityIds || []).map((id) => world.cities[id]).filter(Boolean);
    const clW = clusterCities.reduce((s, c) => s + (c.popM || 1.5) * (c.economy || 75), 0);
    return clamp(Math.round((clW / totalW) * 100), 6, 65);
  }

  function buildConnectedClusterV250(world, leadCity, minAutonomy = 50) {
    if (!world || !leadCity) return [];
    const stId = leadCity.stateId;
    const visited = new Set([leadCity.id]);
    const cluster = [leadCity.id];
    const queue = [leadCity];

    while (queue.length > 0 && cluster.length < 6) {
      const cur = queue.shift();
      const neighbors = Array.isArray(cur.connectedCityIds) ? cur.connectedCityIds : [];
      for (let i = 0; i < neighbors.length && cluster.length < 6; i++) {
        const nbId = neighbors[i];
        if (visited.has(nbId)) continue;
        const nb = world.cities && world.cities[nbId];
        if (!nb || nb.stateId !== stId || nb.isCapital) continue;
        const aut = nb.regionalPolitics?.regionalParliament?.autonomyDemandPct ?? 50;
        if (aut >= minAutonomy) {
          visited.add(nbId);
          cluster.push(nbId);
          queue.push(nb);
        }
      }
    }

    // Fallback: if connectedCityIds wasn't populated on the city, pick up to 2 nearby non-capital cities in the same state with autonomy >= minAutonomy
    if (cluster.length === 1) {
      const extra = Object.values(world.cities || {})
        .filter((c) => c.stateId === stId && c.id !== leadCity.id && !c.isCapital && (c.regionalPolitics?.regionalParliament?.autonomyDemandPct ?? 0) >= minAutonomy)
        .sort((a, b) => Math.hypot((a.x || 0) - (leadCity.x || 0), (a.y || 0) - (leadCity.y || 0)) - Math.hypot((b.x || 0) - (leadCity.x || 0), (b.y || 0) - (leadCity.y || 0)));
      for (let i = 0; i < Math.min(2, extra.length) && cluster.length < 6; i++) {
        cluster.push(extra[i].id);
      }
    }
    return cluster.slice(0, 6);
  }

  function computeMovementPhaseV250(strength, armed) {
    if (strength >= 55 && armed) return 'ARMED';
    if (strength >= 35) return 'MOBILIZED';
    if (strength >= 15) return 'AGITATION';
    return 'LATENT';
  }

  function computeMovementDeltaStrengthV250(world, st, mov, rngInstance = null) {
    if (!st || !mov) return 0;
    const cities = (mov.cityIds || []).map((id) => world && world.cities && world.cities[id]).filter(Boolean);
    const avgResentment = cities.length > 0
      ? cities.reduce((s, c) => s + (c.resentment ?? 40), 0) / cities.length
      : (mov.avgResentment ?? 45);
    const avgAutonomyDemand = cities.length > 0
      ? cities.reduce((s, c) => s + (c.regionalPolitics?.regionalParliament?.autonomyDemandPct ?? 50), 0) / cities.length
      : (mov.avgAutonomyDemand ?? 55);
    const stability = st.stability ?? 70;
    const respKind = (mov.response && mov.response.kind) ? mov.response.kind : (typeof mov.response === 'string' ? mov.response : null);
    const intelSupp = st.underground?.intelSuppression ?? 20;
    const noise = rngInstance ? ((rngInstance.next() * 1.2) - 0.6) : 0;

    const delta =
      0.04 * (avgResentment - 40) +
      0.05 * (avgAutonomyDemand - 50) +
      0.03 * (100 - stability) +
      (mov.sponsorId ? 1.2 : 0) +
      (respKind === 'CRACKDOWN' ? 0.8 : 0) +
      (respKind === 'CONCEDE' ? -1.6 : 0) +
      (respKind === 'CO_OPT' ? -1.1 : 0) -
      0.012 * intelSupp +
      noise;
    return +delta.toFixed(3);
  }

  function chooseGovernmentResponseV250(world, st, movement, rngInstance = null) {
    if (!st) return 'IGNORE';
    const rng = rngInstance || new SeededRNG((world && world.seed ? world.seed : 2026) + ((world && world.tick) || 0) * 71 + hashStr(st.id));
    const head = (st.positions?.HEAD_OF_STATE && world && world.npcs && world.npcs[st.positions.HEAD_OF_STATE]) || null;
    const aggr = head?.personality?.aggression ?? head?.aggression ?? 55;
    const integ = head?.personality?.integrity ?? head?.integrity ?? 55;
    const caut = head?.personality?.caution ?? head?.caution ?? 55;
    const diplo = head?.diplomaticAbility ?? 60;
    const isAuth = ['Authoritarian', 'One_Party', 'Military_Junta'].includes(st.regimeCategory);
    const isDem = st.regimeCategory === 'Democracy';
    const milInf = st.politicalPressures?.militaryInfluence ?? 50;
    const regDiss = st.politicalPressures?.regionalDissatisfaction ?? 30;
    const treasRatio = (st.treasuryB || 100) / Math.max(50, st.gdpB || 500);

    let wCrackdown = Math.max(1, aggr + (isAuth ? 30 : 0) + milInf * 0.4);
    let wNegotiate = Math.max(1, integ + (isDem ? 25 : 0) + diplo);
    let wConcede = Math.max(1, (100 - aggr) + regDiss * 0.5);
    let wCoOpt = Math.max(1, Math.min(95, treasRatio * 400) + caut * 0.5);
    let wIgnore = Math.max(1, caut * 0.8);

    if (isAuth && aggr >= 80) wCrackdown *= 2.0;
    if (isDem && integ >= 80) wNegotiate *= 1.5;

    const total = wCrackdown + wNegotiate + wConcede + wCoOpt + wIgnore;
    let roll = rng.next() * total;
    if ((roll -= wCrackdown) <= 0) return 'CRACKDOWN';
    if ((roll -= wNegotiate) <= 0) return 'NEGOTIATE';
    if ((roll -= wConcede) <= 0) return 'CONCEDE';
    if ((roll -= wCoOpt) <= 0) return 'CO_OPT';
    return 'IGNORE';
  }

  function applyMovementPhaseAlignmentV250(world, mov) {
    if (!world || !mov || !Array.isArray(mov.cityIds)) return;
    const firstCity = Object.values(world.cities || {})[0];
    if (firstCity && !firstCity.regionalPolitics && typeof ensureRegionalParliamentsAndGovernorsV210 === 'function') {
      ensureRegionalParliamentsAndGovernorsV210(world);
    }
    mov.cityIds.forEach((cid) => {
      const c = world.cities && world.cities[cid];
      if (!c || !c.regionalPolitics) return;
      if (mov.phase === 'MOBILIZED' || mov.phase === 'ARMED') {
        c.regionalPolitics.centralGovAlignment = 'OPPOSITION_STRONGHOLD';
      } else if (mov.phase === 'AUTONOMY_DEAL') {
        c.regionalPolitics.centralGovAlignment = 'ALIGNED';
      }
    });
  }

  function registerMovementProxyOpV250(world, mov) {
    if (!world || !mov || !mov.sponsorId) return null;
    if (!Array.isArray(world.proxyOps)) world.proxyOps = [];
    const existing = world.proxyOps.find((op) => op.movementId === mov.id && op.sponsorId === mov.sponsorId);
    if (existing) return existing;
    const leadCity = mov.cityIds && mov.cityIds[0] ? world.cities[mov.cityIds[0]] : null;
    const leader = mov.leaderId ? world.npcs[mov.leaderId] : null;
    const rec = {
      id: 'PROXY_' + (++world.nextId),
      date: world.dateString || '2026-01-01',
      sponsorId: mov.sponsorId,
      targetId: mov.stateId,
      cityName: leadCity ? leadCity.name : mov.stateId,
      rebelLeaderName: leader ? leader.name : mov.name,
      movementId: mov.id
    };
    world.proxyOps.unshift(rec);
    if (world.proxyOps.length > 50) world.proxyOps.length = 50;
    return rec;
  }

  function spawnMovementV250(world, stateId, leadCityId = null, opts = {}) {
    if (!world || !world.states || !world.states[stateId]) {
      return { ok: false, reason: 'ไม่พบรัฐที่ระบุ' };
    }
    ensureUndergroundV250(world);
    const firstCity = Object.values(world.cities || {})[0];
    if (firstCity && !firstCity.regionalPolitics && typeof ensureRegionalParliamentsAndGovernorsV210 === 'function') {
      ensureRegionalParliamentsAndGovernorsV210(world);
    }
    const st = world.states[stateId];
    const rng = opts.rng || new SeededRNG((world.seed || 2026) + (world.tick || 0) * 89 + hashStr(stateId + (leadCityId || '')));

    const activeMovs = world.undergroundV250.movements;
    const usedCities = new Set();
    activeMovs.forEach((m) => (m.cityIds || []).forEach((cid) => usedCities.add(cid)));

    let leadCity = leadCityId ? world.cities[leadCityId] : null;
    if (!leadCity || leadCity.stateId !== stateId) {
      const cands = Object.values(world.cities || {})
        .filter((c) => c.stateId === stateId && !c.isCapital && !usedCities.has(c.id))
        .sort((a, b) => ((b.resentment || 30) + (b.regionalPolitics?.regionalParliament?.autonomyDemandPct || 40)) - ((a.resentment || 30) + (a.regionalPolitics?.regionalParliament?.autonomyDemandPct || 40)));
      leadCity = cands[0] || Object.values(world.cities || {}).find((c) => c.stateId === stateId && !usedCities.has(c.id));
    }
    if (!leadCity) return { ok: false, reason: 'ไม่พบเมืองที่สามารถตั้งขบวนการได้' };
    if (usedCities.has(leadCity.id)) return { ok: false, reason: 'เมืองนี้มีขบวนการเคลื่อนไหวอยู่แล้ว' };

    const minAut = opts.forceCluster ? 0 : 50;
    const rawCluster = buildConnectedClusterV250(world, leadCity, minAut).filter((cid) => !usedCities.has(cid));
    const cityIds = rawCluster.length > 0 ? rawCluster.slice(0, 6) : [leadCity.id];

    const ideology = opts.ideology || rng.pick(MOVEMENT_IDEOLOGIES_V250);
    const cityShort = leadCity.name.split(' (')[0].trim();
    const namePool = MOVEMENT_NAME_TEMPLATES_V250[ideology] || MOVEMENT_NAME_TEMPLATES_V250.ETHNIC;
    const movName = fillTemplateV250(rng.pick(namePool), { city: cityShort });

    // Pick or spawn leader
    let leader = Object.values(world.npcs || {})
      .filter((n) => n && n.alive && !n.retired && n.stateId === stateId && n.positionId !== 'HEAD_OF_STATE' && (cityIds.includes(n.homeCityId) || cityIds.includes(n.assignedNodeId)))
      .sort((a, b) => (b.secessionDesire || 30) - (a.secessionDesire || 30))[0];

    if (!leader && leadCity.governorId && world.npcs[leadCity.governorId]?.alive && leadCity.regionalPolitics?.centralGovAlignment !== 'ALIGNED') {
      leader = world.npcs[leadCity.governorId];
    }
    if (!leader) {
      leader = generateContextualNPC(world, rng, {
        stateId,
        homeCityId: leadCity.id,
        assignedNodeId: leadCity.id,
        age: rng.int(35, 58),
        positionId: 'SENIOR_OFFICIAL',
        track: 'political'
      });
      if (leader.personality) leader.personality.ambition = rng.int(78, 96);
      if (typeof ensureNPCDeepProfileV170 === 'function') ensureNPCDeepProfileV170(world, leader, rng);
      if (typeof ensureNPCPowerModelV200 === 'function') ensureNPCPowerModelV200(world, leader);
      ensureKinV250(world);
    }
    leader.secessionDesire = Math.max(leader.secessionDesire || 0, rng.int(70, 95));
    recordNPCMemory(leader, world.year || 2026, `ก้าวขึ้นเป็นผู้นำขบวนการ "${movName}" ณ เมือง ${leadCity.name}`);

    const startStrength = opts.strength !== undefined ? opts.strength : rng.int(18, 36);
    const isArmed = opts.armed !== undefined ? !!opts.armed : false;
    const sponsorId = opts.sponsorId !== undefined ? opts.sponsorId : (st.underground?.foreignSponsorId || null);
    const phase = computeMovementPhaseV250(startStrength, isArmed);

    const mov = {
      id: 'MOV_' + (++world.undergroundV250.nextId),
      stateId,
      cityIds,
      name: movName,
      ideology,
      leaderId: leader.id,
      moderateShare: opts.moderateShare !== undefined ? opts.moderateShare : +(rng.int(40, 75) / 100).toFixed(2),
      strength: startStrength,
      popularSupport: clamp(Math.round(startStrength + rng.int(-4, 8)), 5, 100),
      armed: isArmed,
      fighters: isArmed ? rng.int(1800, 6500) : rng.int(250, 1200),
      sponsorId,
      phase,
      phaseDay: 0,
      armedMonths: isArmed ? 1 : 0,
      recognisedBy: [],
      response: { kind: chooseGovernmentResponseV250(world, st, null, rng), sinceTick: world.tick || 0 },
      log: [`[${world.dateString || '2026-01-01'}] ก่อตั้ง "${movName}" ณ เมือง ${cityShort} นำโดย ${leader.name}`]
    };

    if (activeMovs.length >= 12) {
      const oldest = activeMovs.shift();
      world.undergroundV250.movementArchive.unshift(oldest);
      if (world.undergroundV250.movementArchive.length > 40) world.undergroundV250.movementArchive.length = 40;
    }
    activeMovs.push(mov);

    applyMovementPhaseAlignmentV250(world, mov);
    if (sponsorId) {
      registerMovementProxyOpV250(world, mov);
    }

    const gdpShare = getClusterGdpSharePctV250(world, stateId, cityIds);
    const protesters = rng.int(3500, 28000);
    const tplPool = SEPARATISM_FOUNDED_TEMPLATES_V250[ideology] || SEPARATISM_FOUNDED_TEMPLATES_V250.ETHNIC;
    const msg = fillTemplateV250(rng.pick(tplPool), {
      city: cityShort,
      state: st.name,
      leader: leader.name,
      name: movName,
      protesters: protesters.toLocaleString(),
      fighters: mov.fighters.toLocaleString(),
      gdpShare,
      strength: Math.round(mov.strength),
      year: world.year || 2026
    });
    addChronicle(world, 'SEPARATISM', msg, stateId, { personId: leader.id, cityId: leadCity.id, subKind: `MOVEMENT_FOUNDED_${ideology}` });
    return { ok: true, id: mov.id, movement: mov, narrative: msg };
  }

  function setMovementResponseV250(world, movementId, kind) {
    if (!world) return { ok: false, reason: 'ไม่พบข้อมูลโลก' };
    ensureUndergroundV250(world);
    const validKinds = ['CRACKDOWN', 'NEGOTIATE', 'CONCEDE', 'CO_OPT', 'IGNORE'];
    if (!validKinds.includes(kind)) return { ok: false, reason: 'รูปแบบการตอบสนองไม่ถูกต้อง' };
    const mov = (world.undergroundV250.movements || []).find((m) => m.id === movementId);
    if (!mov) return { ok: false, reason: 'ไม่พบขบวนการที่ระบุ' };

    mov.response = { kind, sinceTick: world.tick || 0 };
    const st = world.states[mov.stateId];
    const leadCity = mov.cityIds && mov.cityIds[0] ? world.cities[mov.cityIds[0]] : null;
    const leader = mov.leaderId ? world.npcs[mov.leaderId] : null;
    const rng = new SeededRNG((world.seed || 2026) + (world.tick || 0) * 37 + hashStr(mov.id + kind));

    // Apply immediate response effect so manual/test triggers and monthly cycles both reflect it
    if (kind === 'CRACKDOWN') {
      mov.strength = clamp(+(mov.strength - 4).toFixed(2), 0, 100);
      (mov.cityIds || []).forEach((cid) => {
        const c = world.cities[cid];
        if (c) c.resentment = clamp(rnd1((c.resentment || 40) + 3), 0, 100);
      });
      if (st) {
        st.securityPostureV250 = clamp(rnd1((st.securityPostureV250 || 40) + 1.5), 0, 100);
        if (st.politicalPressures) {
          st.politicalPressures.publicUnrest = clamp(rnd1((st.politicalPressures.publicUnrest || 20) + 1), 0, 100);
        }
      }
    } else if (kind === 'CONCEDE') {
      (mov.cityIds || []).forEach((cid) => {
        const c = world.cities[cid];
        if (c && c.regionalPolitics && c.regionalPolitics.regionalParliament) {
          c.regionalPolitics.regionalParliament.autonomyDemandPct = clamp(rnd1((c.regionalPolitics.regionalParliament.autonomyDemandPct || 60) - 3), 0, 100);
          c.regionalPolitics.regionalParliament.localSupportPct = clamp(rnd1((c.regionalPolitics.regionalParliament.localSupportPct || 55) + 2), 0, 100);
        }
      });
      if (st) st.stability = clamp(rnd1((st.stability || 70) - 0.2), 5, 100);
    }

    const gdpShare = getClusterGdpSharePctV250(world, mov.stateId, mov.cityIds);
    const tplPool = SEPARATISM_GOV_RESPONSE_TEMPLATES_V250[kind] || SEPARATISM_GOV_RESPONSE_TEMPLATES_V250.IGNORE;
    const msg = fillTemplateV250(rng.pick(tplPool), {
      state: st ? st.name : mov.stateId,
      city: leadCity ? leadCity.name.split(' (')[0] : mov.stateId,
      name: mov.name,
      leader: leader ? leader.name : 'แกนนำขบวนการ',
      strength: Math.round(mov.strength),
      gdpShare,
      fighters: (mov.fighters || 500).toLocaleString(),
      protesters: (Math.round(mov.popularSupport * 180) + 1200).toLocaleString(),
      modPct: Math.round((mov.moderateShare || 0.5) * 100)
    });
    mov.log.unshift(`[${world.dateString || '2026-01-01'}] รัฐบาลปรับท่าทีเป็น ${kind}`);
    if (mov.log.length > 15) mov.log.length = 15;
    addChronicle(world, 'SEPARATISM', msg, mov.stateId, { personId: leader ? leader.id : null, cityId: leadCity ? leadCity.id : null, subKind: `GOV_RESPONSE_${kind}` });
    return { ok: true, movement: mov, narrative: msg };
  }

  function recordThirdStateRecognitionsV250(world, mov, parentState, newState, rngInstance = null) {
    if (!world || !mov || !parentState) return [];
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + (world.tick || 0) * 61);
    if (!Array.isArray(mov.recognisedBy)) mov.recognisedBy = [];
    const added = [];

    Object.values(world.states).forEach((other) => {
      if (!other || other.isExiled || other.id === parentState.id || (newState && other.id === newState.id)) return;
      if (mov.recognisedBy.length >= 12 || mov.recognisedBy.includes(other.id)) return;
      const relToParent = other.relations && other.relations[parentState.id];
      const relToNew = newState && other.relations && other.relations[newState.id];
      const isHostileToParent = (relToParent && (relToParent.status === 'Hostile' || relToParent.status === 'War' || relToParent.score < 42)) || (other.rivalries || []).includes(parentState.id);
      const isFriendlyToNew = (relToNew && relToNew.score >= 60) || other.id === mov.sponsorId;

      if (isFriendlyToNew || isHostileToParent) {
        mov.recognisedBy.push(other.id);
        added.push(other.id);
        if (newState) {
          setDiplomaticStatus(world, other.id, newState.id, 'Peace');
          if (other.relations && other.relations[newState.id]) other.relations[newState.id].score = Math.max(65, other.relations[newState.id].score || 65);
          if (newState.relations && newState.relations[other.id]) newState.relations[other.id].score = Math.max(65, newState.relations[other.id].score || 65);
        }
      }
    });

    if (added.length > 0) {
      const firstRec = world.states[added[0]];
      const leadCity = mov.cityIds && mov.cityIds[0] ? world.cities[mov.cityIds[0]] : null;
      const leader = mov.leaderId ? world.npcs[mov.leaderId] : null;
      const recMsg = `🌐🚩 [นานาชาติให้การรับรองเอกราช!] รัฐบาล ${firstRec ? firstRec.name : added[0]} และอีก ${added.length} ประเทศ ประกาศรับรองสถานะของ "${newState ? newState.name : mov.name}" (นำโดย ${leader ? leader.name : 'ผู้นำเอกราช'} ณ เมือง ${leadCity ? leadCity.name.split(' (')[0] : ''}) อย่างเป็นทางการ สวนทางกับท่าทีของ ${parentState.name}!`;
      addChronicle(world, 'SEPARATISM', recMsg, newState ? newState.id : parentState.id, { personId: leader ? leader.id : null, cityId: leadCity ? leadCity.id : null, subKind: 'RECOGNITION' });
    }
    return added;
  }

  function executeClusterIndependenceV250(world, mov, isNegotiatedPeace = false, rngInstance = null) {
    if (!world || !mov) return { ok: false, reason: 'ไม่พบข้อมูลขบวนการ' };
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + (world.tick || 0) * 101 + hashStr(mov.id));
    const parentState = world.states[mov.stateId];
    if (!parentState) return { ok: false, reason: 'ไม่พบรัฐแม่' };

    const clusterCities = (mov.cityIds || []).map((id) => world.cities[id]).filter(Boolean);
    const leadCity = clusterCities[0] || Object.values(world.cities).find((c) => c.stateId === parentState.id && !c.isCapital) || Object.values(world.cities).find((c) => c.stateId === parentState.id);
    if (!leadCity) return { ok: false, reason: 'ไม่พบเมืองฐานที่มั่น' };

    let leader = mov.leaderId ? world.npcs[mov.leaderId] : null;
    if (!leader || !leader.alive) {
      leader = (leadCity.governorId && world.npcs[leadCity.governorId]?.alive)
        ? world.npcs[leadCity.governorId]
        : generateContextualNPC(world, rng, { stateId: parentState.id, age: 42, positionId: 'SENIOR_OFFICIAL', track: 'political' });
      mov.leaderId = leader.id;
    }

    // Addendum Link 2: If occupied cluster and originalOwnerId state still exists, 60% return to originalOwnerId, 40% new state
    const origOwnerId = leadCity.isOccupied && leadCity.originalOwnerId && leadCity.originalOwnerId !== parentState.id ? leadCity.originalOwnerId : null;
    const origOwnerSt = origOwnerId ? world.states[origOwnerId] : null;
    if (origOwnerSt && !mov._forceNewState && rng.chance(0.60)) {
      const transferFn = getSoftLinkFnV250('transferCityV230', typeof transferCityV230 === 'function' ? transferCityV230 : undefined);
      clusterCities.forEach((c) => {
        if (typeof liberateCity === 'function' && c.originalOwnerId === origOwnerSt.id) {
          liberateCity(world, c.id, `ขบวนการ ${mov.name} ปลดแอกคืนสู่มาตุภูมิ`);
        } else if (typeof transferFn === 'function') {
          transferFn(world, c.id, origOwnerSt.id);
        }
        c.stateId = origOwnerSt.id;
        c.currentOwnerId = origOwnerSt.id;
        c.isOccupied = false;
        c.isFrontline = false;
        c.insurgentCells = 0;
        c.unrest = 18;
        c.resentment = 10;
      });
      if (origOwnerSt.isExiled && typeof restoreExiledState === 'function') {
        restoreExiledState(world, origOwnerSt.id, leadCity.id, `ปลดแอกผ่านขบวนการ ${mov.name}`);
      }
      if (typeof syncCityIndex === 'function') syncCityIndex(world);
      mov.phase = 'INDEPENDENT';
      mov.restoredStateId = origOwnerSt.id;
      recordThirdStateRecognitionsV250(world, mov, parentState, origOwnerSt, rng);
      const gdpShare = getClusterGdpSharePctV250(world, origOwnerSt.id, mov.cityIds);
      const tpl = rng.pick(SEPARATISM_INDEPENDENCE_TEMPLATES_V250);
      const msg = fillTemplateV250(tpl, {
        name: mov.name,
        leader: leader.name,
        city: leadCity.name.split(' (')[0],
        state: parentState.name,
        newState: origOwnerSt.name,
        gdpShare,
        debtShareB: '0.0',
        fighters: (mov.fighters || 2000).toLocaleString(),
        year: world.year || 2026
      });
      addChronicle(world, 'SEPARATISM', msg, origOwnerSt.id, { personId: leader.id, cityId: leadCity.id, subKind: 'INDEPENDENCE' });
      return { ok: true, restored: true, newState: origOwnerSt, narrative: msg };
    }

    // Save parent state financial baseline before founding new state
    if (typeof ensureGlobalFinanceAndCurrencyV210 === 'function') {
      ensureGlobalFinanceAndCurrencyV210(world);
    }
    const origGdpB = parentState.gdpB || 800;
    const origTreasB = parentState.treasuryB || 150;
    const origDebtB = parentState.sovereignDebt ? (parentState.sovereignDebt.totalDebtB || 0) : 0;
    const origCreditors = JSON.parse(JSON.stringify((parentState.sovereignDebt && parentState.sovereignDebt.foreignCreditors) || {}));
    const gdpSharePct = getClusterGdpSharePctV250(world, parentState.id, mov.cityIds);
    const shareRatio = clamp(gdpSharePct / 100, 0.10, 0.45);

    // Temporarily clear _inTick160 so explicit independence conditions in V2.5.0 are honoured
    const prevInTick = world._inTick160;
    world._inTick160 = false;
    const foundRes = triggerNPCFoundNewState(world, leader, leadCity);
    world._inTick160 = prevInTick;

    if (!foundRes || !foundRes.ok || !foundRes.newState) {
      return { ok: false, reason: (foundRes && foundRes.reason) || 'ไม่สามารถสถาปนารัฐใหม่ได้' };
    }

    const newState = foundRes.newState;
    const transferFn = getSoftLinkFnV250('transferCityV230', typeof transferCityV230 === 'function' ? transferCityV230 : undefined);

    // Transfer remaining cluster cities to the new state
    clusterCities.forEach((c) => {
      if (c.id !== leadCity.id) {
        if (typeof transferFn === 'function') {
          transferFn(world, c.id, newState.id);
        }
        c.stateId = newState.id;
        c.currentOwnerId = newState.id;
        c.isOccupied = false;
        c.isFrontline = false;
        c.insurgentCells = 0;
        c.unrest = Math.min(20, c.unrest || 15);
        c.resentment = Math.min(10, c.resentment || 5);
      } else {
        c.stateId = newState.id;
        c.currentOwnerId = newState.id;
        c.isOccupied = false;
        c.isFrontline = false;
        c.insurgentCells = 0;
      }
    });
    if (typeof syncCityIndex === 'function') syncCityIndex(world);

    // Addendum Link 5: split GDP, treasury, sovereignDebt.totalDebtB and foreignCreditors proportionally to GDP share
    const childGdpB = rnd1(origGdpB * shareRatio);
    const parentGdpB = rnd1(Math.max(40, origGdpB - childGdpB));
    parentState.gdpB = parentGdpB;
    newState.gdpB = Math.max(40, childGdpB);

    const childTreasB = rnd1(origTreasB * shareRatio);
    parentState.treasuryB = rnd1(Math.max(10, origTreasB - childTreasB));
    newState.treasuryB = Math.max(10, childTreasB);

    if (typeof ensureGlobalFinanceAndCurrencyV210 === 'function') {
      ensureGlobalFinanceAndCurrencyV210(world);
    }
    const childDebtB = rnd1(origDebtB * shareRatio);
    const parentDebtB = rnd1(Math.max(0, origDebtB - childDebtB));
    if (parentState.sovereignDebt && newState.sovereignDebt) {
      parentState.sovereignDebt.totalDebtB = parentDebtB;
      newState.sovereignDebt.totalDebtB = childDebtB;
      parentState.sovereignDebt.debtToGdpPct = +((parentDebtB / Math.max(40, parentState.gdpB)) * 100).toFixed(1);
      newState.sovereignDebt.debtToGdpPct = +((childDebtB / Math.max(40, newState.gdpB)) * 100).toFixed(1);
      parentState.sovereignDebt.foreignCreditors = {};
      newState.sovereignDebt.foreignCreditors = {};
      Object.keys(origCreditors).forEach((credId) => {
        const amt = origCreditors[credId] || 0;
        const cAmt = rnd1(amt * shareRatio);
        parentState.sovereignDebt.foreignCreditors[credId] = rnd1(Math.max(0, amt - cAmt));
        newState.sovereignDebt.foreignCreditors[credId] = cAmt;
      });
      if (typeof recomputeCreditRatingV210 === 'function') {
        recomputeCreditRatingV210(parentState);
        recomputeCreditRatingV210(newState);
      }
    }

    // Set diplomatic relation between parent and new state
    const relStatus = isNegotiatedPeace ? 'Peace' : 'Hostile';
    const relScore = isNegotiatedPeace ? 55 : 20;
    setDiplomaticStatus(world, parentState.id, newState.id, relStatus);
    if (parentState.relations && parentState.relations[newState.id]) {
      parentState.relations[newState.id].status = relStatus;
      parentState.relations[newState.id].score = relScore;
    }
    if (newState.relations && newState.relations[parentState.id]) {
      newState.relations[parentState.id].status = relStatus;
      newState.relations[parentState.id].score = relScore;
    }

    // Addendum Link 4: new state starts with no alliances; announce in ALLIANCE if parent was in an alliance
    (world.alliances || []).forEach((al) => {
      if (Array.isArray(al.members)) {
        al.members = al.members.filter((m) => m !== newState.id);
      }
    });
    const parentAlliances = (world.alliances || []).filter((al) => Array.isArray(al.members) && al.members.includes(parentState.id));
    if (parentAlliances.length > 0) {
      const al = parentAlliances[0];
      addChronicle(
        world,
        'ALLIANCE',
        `🛡️🚩 [ผลกระทบต่อกลุ่มพันธมิตร ${al.shortCode || al.name}] การแยกตัวของ "${newState.name}" ออกจากรัฐสมาชิก ${parentState.name} ส่งผลให้กลุ่มเมืองยุทธศาสตร์นำโดย ${leadCity.name.split(' (')[0]} พ้นจากเขตความคุ้มครองของ "${al.name}" โดยรัฐเกิดใหม่เริ่มต้นด้วยสถานะไม่สังกัดพันธมิตรใด`,
        parentState.id,
        { secondStateId: newState.id, cityId: leadCity.id }
      );
    }

    ensureUndergroundV250(world);
    ensureKinV250(world);

    mov.phase = 'INDEPENDENT';
    mov.newStateId = newState.id;

    // Addendum Link 9: recognition by third states
    recordThirdStateRecognitionsV250(world, mov, parentState, newState, rng);

    const tpl = rng.pick(SEPARATISM_INDEPENDENCE_TEMPLATES_V250);
    const msg = fillTemplateV250(tpl, {
      name: mov.name,
      leader: leader.name,
      city: leadCity.name.split(' (')[0],
      state: parentState.name,
      newState: newState.name,
      gdpShare: gdpSharePct,
      debtShareB: childDebtB.toFixed(1),
      fighters: (mov.fighters || 3500).toLocaleString(),
      year: world.year || 2026
    });
    addChronicle(world, 'SEPARATISM', msg, newState.id, { personId: leader.id, cityId: leadCity.id, secondStateId: parentState.id, subKind: 'INDEPENDENCE' });
    return { ok: true, newState, debtShareB: childDebtB, narrative: msg };
  }

  function stepMovementNegotiationOrSplitV250(world, st, mov, rngInstance = null) {
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + (world.tick || 0) * 113 + hashStr(mov.id));
    const isDem = st.regimeCategory === 'Democracy';
    const pSuccess = 0.12 + 0.35 * (mov.moderateShare ?? 0.5) + 0.2 * (isDem ? 1 : 0);
    const leadCity = mov.cityIds && mov.cityIds[0] ? world.cities[mov.cityIds[0]] : null;
    const leader = mov.leaderId ? world.npcs[mov.leaderId] : null;
    const gdpShare = getClusterGdpSharePctV250(world, mov.stateId, mov.cityIds);

    if (rng.chance(pSuccess)) {
      mov.phase = 'AUTONOMY_DEAL';
      (mov.cityIds || []).forEach((cid) => {
        const c = world.cities[cid];
        if (!c) return;
        c.resentment = clamp(rnd1((c.resentment || 40) - 12), 0, 100);
        c.isFrontline = false;
        if (c.regionalPolitics) {
          c.regionalPolitics.centralGovAlignment = 'ALIGNED';
          if (c.regionalPolitics.regionalParliament) {
            c.regionalPolitics.regionalParliament.autonomyDemandPct = clamp(rnd1((c.regionalPolitics.regionalParliament.autonomyDemandPct || 60) - 15), 0, 100);
          }
        }
      });
      const tpl = rng.pick(SEPARATISM_AUTONOMY_DEAL_TEMPLATES_V250);
      const msg = fillTemplateV250(tpl, {
        city: leadCity ? leadCity.name.split(' (')[0] : mov.stateId,
        state: st.name,
        leader: leader ? leader.name : 'แกนนำขบวนการ',
        name: mov.name,
        gdpShare,
        protesters: (Math.round(mov.popularSupport * 150) + 1500).toLocaleString(),
        year: world.year || 2026
      });
      addChronicle(world, 'SEPARATISM', msg, mov.stateId, { personId: leader ? leader.id : null, cityId: leadCity ? leadCity.id : null, subKind: 'AUTONOMY_DEAL' });
      return { outcome: 'AUTONOMY_DEAL', archived: true };
    }

    // Failure: 30% radicalisation (moderateShare -= 0.15, strength +6, may SPLIT: 30% chance a radical wing becomes a new movement with armed:true)
    if (rng.chance(0.30)) {
      mov.moderateShare = clamp(+((mov.moderateShare || 0.5) - 0.15).toFixed(2), 0.05, 0.95);
      mov.strength = clamp(+(mov.strength + 6).toFixed(2), 0, 100);
      if (rng.chance(0.30)) {
        let splitCityId = null;
        if (mov.cityIds.length > 1) {
          splitCityId = mov.cityIds.pop();
        } else {
          const usedSet = new Set();
          (world.undergroundV250.movements || []).forEach((m) => (m.cityIds || []).forEach((cid) => usedSet.add(cid)));
          const altCity = Object.values(world.cities || {}).find((c) => c.stateId === st.id && !c.isCapital && !usedSet.has(c.id));
          splitCityId = altCity ? altCity.id : (leadCity ? leadCity.id : null);
        }
        const splitCity = splitCityId ? world.cities[splitCityId] : leadCity;
        const radLeader = generateContextualNPC(world, rng, {
          stateId: st.id,
          homeCityId: splitCity ? splitCity.id : null,
          age: rng.int(29, 48),
          positionId: 'SENIOR_OFFICIAL',
          track: 'military'
        });
        if (radLeader.personality) {
          radLeader.personality.ambition = rng.int(82, 98);
          radLeader.personality.aggression = rng.int(80, 98);
        }
        radLeader.secessionDesire = rng.int(85, 99);
        if (typeof ensureNPCDeepProfileV170 === 'function') ensureNPCDeepProfileV170(world, radLeader, rng);
        if (typeof ensureNPCPowerModelV200 === 'function') ensureNPCPowerModelV200(world, radLeader);
        ensureKinV250(world);

        const newMov = {
          id: 'MOV_' + (++world.undergroundV250.nextId),
          stateId: st.id,
          cityIds: splitCity ? [splitCity.id] : mov.cityIds.slice(0, 1),
          name: `${mov.name} (ปีกติดอาวุธสายเหยี่ยว)`,
          ideology: mov.ideology,
          leaderId: radLeader.id,
          moderateShare: 0.15,
          strength: clamp(Math.max(56, Math.round(mov.strength * 0.85)), 55, 95),
          popularSupport: clamp(Math.round(mov.popularSupport * 0.75), 20, 90),
          armed: true,
          fighters: rng.int(1500, 4500),
          sponsorId: mov.sponsorId,
          phase: 'ARMED',
          phaseDay: 0,
          armedMonths: 1,
          recognisedBy: [],
          response: { kind: 'CRACKDOWN', sinceTick: world.tick || 0 },
          log: [`[${world.dateString || '2026-01-01'}] แยกตัวจาก ${mov.name} และประกาศจับอาวุธ`]
        };
        if (world.undergroundV250.movements.length < 12) {
          world.undergroundV250.movements.push(newMov);
        }
        const tpl = rng.pick(SEPARATISM_SPLIT_TEMPLATES_V250);
        const msg = fillTemplateV250(tpl, {
          name: mov.name,
          newName: newMov.name,
          city: splitCity ? splitCity.name.split(' (')[0] : st.name,
          state: st.name,
          leader: leader ? leader.name : 'ผู้นำสายพิราบ',
          newLeader: radLeader.name,
          fighters: newMov.fighters.toLocaleString(),
          strength: Math.round(newMov.strength),
          gdpShare,
          year: world.year || 2026
        });
        addChronicle(world, 'SEPARATISM', msg, st.id, { personId: radLeader.id, cityId: splitCity ? splitCity.id : null, subKind: 'SPLIT' });
        return { outcome: 'SPLIT', splitMovement: newMov };
      }
    }
    return { outcome: 'CONTINUE' };
  }

  function runMovementMonthV250(world, rngInstance = null) {
    if (!world || !world.states) return;
    ensureUndergroundV250(world);
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + (world.tick || 0) * 313);
    const active = world.undergroundV250.movements;

    for (let i = active.length - 1; i >= 0; i--) {
      const mov = active[i];
      const st = world.states[mov.stateId];
      if (!st || st.isExiled) {
        active.splice(i, 1);
        continue;
      }

      const cities = (mov.cityIds || []).map((id) => world.cities[id]).filter((c) => c && c.stateId === st.id);
      if (cities.length === 0) {
        active.splice(i, 1);
        continue;
      }
      mov.cityIds = cities.map((c) => c.id);
      const leadCity = cities[0];
      let leader = mov.leaderId ? world.npcs[mov.leaderId] : null;
      if (!leader || !leader.alive) {
        leader = generateContextualNPC(world, rng, { stateId: st.id, homeCityId: leadCity.id, age: rng.int(34, 55), positionId: 'SENIOR_OFFICIAL', track: 'political' });
        leader.secessionDesire = rng.int(75, 95);
        if (typeof ensureNPCDeepProfileV170 === 'function') ensureNPCDeepProfileV170(world, leader, rng);
        if (typeof ensureNPCPowerModelV200 === 'function') ensureNPCPowerModelV200(world, leader);
        ensureKinV250(world);
        mov.leaderId = leader.id;
      }

      const avgRes = cities.reduce((s, c) => s + (c.resentment || 40), 0) / cities.length;
      const gdpShare = getClusterGdpSharePctV250(world, st.id, mov.cityIds);

      // Government response chosen every 30 ticks
      if (!mov.response || (world.tick || 0) - (mov.response.sinceTick || 0) >= 30) {
        const nextKind = chooseGovernmentResponseV250(world, st, mov, rng);
        mov.response = { kind: nextKind, sinceTick: world.tick || 0 };
        if (rng.chance(0.45)) {
          const tplPool = SEPARATISM_GOV_RESPONSE_TEMPLATES_V250[nextKind] || SEPARATISM_GOV_RESPONSE_TEMPLATES_V250.IGNORE;
          const msg = fillTemplateV250(rng.pick(tplPool), {
            state: st.name,
            city: leadCity.name.split(' (')[0],
            name: mov.name,
            leader: leader.name,
            strength: Math.round(mov.strength),
            gdpShare,
            fighters: (mov.fighters || 600).toLocaleString(),
            protesters: (Math.round(mov.popularSupport * 180) + 1200).toLocaleString(),
            modPct: Math.round((mov.moderateShare || 0.5) * 100)
          });
          addChronicle(world, 'SEPARATISM', msg, st.id, { personId: leader.id, cityId: leadCity.id, subKind: `GOV_RESPONSE_${nextKind}` });
        }
      }

      const respKind = mov.response.kind;
      const dStr = computeMovementDeltaStrengthV250(world, st, mov, rng);
      mov.strength = clamp(+(mov.strength + dStr).toFixed(2), 0, 100);

      // Monthly government response effects
      if (respKind === 'CRACKDOWN') {
        mov.strength = clamp(+(mov.strength - 4).toFixed(2), 0, 100);
        cities.forEach((c) => {
          c.resentment = clamp(rnd1((c.resentment || 40) + 3), 0, 100);
        });
        st.securityPostureV250 = clamp(rnd1((st.securityPostureV250 || 40) + 1.5), 0, 100);
        if (st.politicalPressures) {
          st.politicalPressures.publicUnrest = clamp(rnd1((st.politicalPressures.publicUnrest || 20) + 1), 0, 100);
        }
        // 20% chance of martyrdom incident (+8 strength, story)
        if (rng.chance(0.20)) {
          mov.strength = clamp(+(mov.strength + 8).toFixed(2), 0, 100);
          const mTpl = rng.pick(SEPARATISM_MARTYR_TEMPLATES_V250);
          const mMsg = fillTemplateV250(mTpl, {
            city: leadCity.name.split(' (')[0],
            state: st.name,
            leader: leader.name,
            name: mov.name,
            strength: Math.round(mov.strength),
            protesters: (Math.round(mov.popularSupport * 220) + 2500).toLocaleString(),
            year: world.year || 2026
          });
          addChronicle(world, 'SEPARATISM', mMsg, st.id, { personId: leader.id, cityId: leadCity.id, subKind: 'MARTYR_INCIDENT' });
        }
      } else if (respKind === 'CONCEDE') {
        cities.forEach((c) => {
          if (c.regionalPolitics && c.regionalPolitics.regionalParliament) {
            c.regionalPolitics.regionalParliament.autonomyDemandPct = clamp(rnd1((c.regionalPolitics.regionalParliament.autonomyDemandPct || 60) - 3), 0, 100);
            c.regionalPolitics.regionalParliament.localSupportPct = clamp(rnd1((c.regionalPolitics.regionalParliament.localSupportPct || 55) + 2), 0, 100);
          }
        });
        st.stability = clamp(rnd1((st.stability || 70) - 0.2), 5, 100);
      } else if (respKind === 'NEGOTIATE') {
        const negRes = stepMovementNegotiationOrSplitV250(world, st, mov, rng);
        if (negRes.archived) {
          active.splice(i, 1);
          world.undergroundV250.movementArchive.unshift(mov);
          if (world.undergroundV250.movementArchive.length > 40) world.undergroundV250.movementArchive.length = 40;
          continue;
        }
      } else if (respKind === 'CO_OPT') {
        const costB = +((st.gdpB || 500) * 0.0002).toFixed(2);
        st.treasuryB = rnd1(Math.max(5, (st.treasuryB || 100) - costB));
        cities.forEach((c) => {
          c.infrastructure = clamp(rnd1((c.infrastructure || 75) + 0.5), 10, 100);
          c.economy = clamp(rnd1((c.economy || 75) + 0.4), 10, 100);
        });
        mov.popularSupport = clamp(+(mov.popularSupport - 1.0).toFixed(2), 0, 100);
      } else if (respKind === 'IGNORE') {
        mov.strength = clamp(+(mov.strength + 0.5).toFixed(2), 0, 100);
      }

      // popularSupport follows strength with lag
      mov.popularSupport = clamp(+(mov.popularSupport + (mov.strength - mov.popularSupport) * 0.35).toFixed(2), 0, 100);

      // Become armed when strength >= 50 and (sponsorId or avgResentment >= 65) with p = 0.25 per month
      if (!mov.armed && mov.strength >= 50 && (mov.sponsorId || avgRes >= 65) && rng.chance(0.25)) {
        mov.armed = true;
        mov.fighters = Math.max(mov.fighters || 1500, rng.int(2200, 7500));
        if (mov.sponsorId) registerMovementProxyOpV250(world, mov);
      }

      // Archive if strength < 5
      if (mov.strength < 5) {
        mov.phase = 'SUPPRESSED';
        active.splice(i, 1);
        world.undergroundV250.movementArchive.unshift(mov);
        if (world.undergroundV250.movementArchive.length > 40) world.undergroundV250.movementArchive.length = 40;
        continue;
      }

      const prevPhase = mov.phase;
      const nextPhase = computeMovementPhaseV250(mov.strength, mov.armed);
      mov.phase = nextPhase;

      const phaseOrder = { LATENT: 0, AGITATION: 1, MOBILIZED: 2, ARMED: 3 };
      if ((phaseOrder[nextPhase] || 0) > (phaseOrder[prevPhase] || 0)) {
        applyMovementPhaseAlignmentV250(world, mov);
        const pPool = SEPARATISM_PHASE_UP_TEMPLATES_V250[nextPhase];
        if (pPool) {
          const pMsg = fillTemplateV250(rng.pick(pPool), {
            name: mov.name,
            leader: leader.name,
            city: leadCity.name.split(' (')[0],
            state: st.name,
            strength: Math.round(mov.strength),
            protesters: (Math.round(mov.popularSupport * 250) + 2000).toLocaleString(),
            fighters: (mov.fighters || 2500).toLocaleString(),
            gdpShare,
            year: world.year || 2026
          });
          addChronicle(world, 'SEPARATISM', pMsg, st.id, { personId: leader.id, cityId: leadCity.id, subKind: `PHASE_UP_${nextPhase}` });
        }
      }

      if (nextPhase === 'MOBILIZED') {
        applyMovementPhaseAlignmentV250(world, mov);
        if (st.democracyState) {
          st.democracyState.strikeLevel = clamp(rnd1((st.democracyState.strikeLevel || 15) + 2), 0, 100);
        }
        cities.forEach((c) => {
          c.unrest = clamp(rnd1((c.unrest || 25) + 1.5), 0, 100);
        });
      }

      // ARMED insurgency monthly effects
      if (nextPhase === 'ARMED') {
        mov.armedMonths = (mov.armedMonths || 0) + 1;
        cities.forEach((c) => {
          c.safety = Math.max(20, rnd1((c.safety || 75) - 2));
          c.insurgentCells = Math.min(20, (c.insurgentCells || 0) + 1);
          c.isFrontline = true;
          if (c.isOccupied) {
            c.garrisonStrength = Math.round((c.garrisonStrength || 15000) * 0.997 + 1200);
          } else if (c.troops) {
            c.troops = Math.max(500, Math.round(c.troops * 0.997));
          }
        });
        st.stability = clamp(rnd1((st.stability || 70) - 0.3), 5, 100);
        st.warExhaustion = clamp(rnd1((st.warExhaustion || 0) + 0.2), 0, 100);
        const coinCostB = +((st.gdpB || 500) * 0.0002).toFixed(2);
        st.treasuryB = rnd1(Math.max(2, (st.treasuryB || 100) - coinCostB));

        // Addendum Link 6: Military readiness & camp supplies drain + logisticsDirty
        if (st.militaryReadiness) {
          st.militaryReadiness.morale = clamp(rnd1((st.militaryReadiness.morale ?? 80) - 0.3), 10, 100);
          st.militaryReadiness.personnelReadiness = clamp(rnd1((st.militaryReadiness.personnelReadiness ?? 80) - 0.3), 10, 100);
          st.militaryReadiness.logisticsCapacity = clamp(rnd1((st.militaryReadiness.logisticsCapacity ?? 80) - 0.3), 10, 100);
        }
        Object.values(world.camps || {}).forEach((cp) => {
          if (cp && cp.stateId === st.id && cp.supplies) {
            cp.supplies.fuel = Math.max(50, Math.round((cp.supplies.fuel || 1000) * 0.99));
            cp.supplies.ammo = Math.max(50, Math.round((cp.supplies.ammo || 1000) * 0.99));
            cp.supplies.rations = Math.max(50, Math.round((cp.supplies.rations || 1000) * 0.99));
          }
        });
        st.logisticsDirty = true;

        // Addendum Link 5: Prolonged ARMED insurgency (> 6 months) drives inflationPct += 0.1/month and may prompt hike_rate / issue_bonds
        if (mov.armedMonths > 6 && st.centralBank) {
          st.centralBank.inflationPct = +(clamp((st.centralBank.inflationPct || 2.5) + 0.1, 0.2, 120)).toFixed(1);
          if (typeof setCentralBankPolicyV210 === 'function' && rng.chance(0.15)) {
            if (st.centralBank.inflationPct > 6.5) {
              setCentralBankPolicyV210(world, st.id, 'hike_rate', 0.25);
            } else if ((st.treasuryB || 100) < 35) {
              setCentralBankPolicyV210(world, st.id, 'issue_bonds', 15);
            }
          }
        }

        // Leader capture p = 0.06*(INTELLIGENCE_CHIEF.intelligenceAbility/100) per month
        const intelChief = (st.positions?.INTELLIGENCE_CHIEF && world.npcs[st.positions.INTELLIGENCE_CHIEF]) || null;
        const intelAbil = intelChief?.intelligenceAbility ?? intelChief?.intelligence ?? 65;
        if (rng.chance(0.06 * (intelAbil / 100))) {
          const oldLeader = leader;
          oldLeader.imprisonedUntilTick = (world.tick || 0) + 360;
          oldLeader.statusState = 'arrested';
          mov.strength = clamp(+(mov.strength - 15).toFixed(2), 0, 100);
          const newLeader = generateContextualNPC(world, rng, { stateId: st.id, homeCityId: leadCity.id, age: rng.int(30, 52), positionId: 'SENIOR_OFFICIAL', track: 'military' });
          newLeader.secessionDesire = rng.int(75, 95);
          if (typeof ensureNPCDeepProfileV170 === 'function') ensureNPCDeepProfileV170(world, newLeader, rng);
          if (typeof ensureNPCPowerModelV200 === 'function') ensureNPCPowerModelV200(world, newLeader);
          ensureKinV250(world);
          mov.leaderId = newLeader.id;
          leader = newLeader;

          const cTpl = rng.pick(SEPARATISM_LEADER_CAPTURED_TEMPLATES_V250);
          const cMsg = fillTemplateV250(cTpl, {
            state: st.name,
            city: leadCity.name.split(' (')[0],
            leader: oldLeader.name,
            newLeader: newLeader.name,
            name: mov.name,
            strength: Math.round(mov.strength),
            gdpShare,
            fighters: (mov.fighters || 2000).toLocaleString(),
            year: world.year || 2026
          });
          addChronicle(world, 'SEPARATISM', cMsg, st.id, { personId: oldLeader.id, cityId: leadCity.id, subKind: 'LEADER_CAPTURED' });
          if (rng.chance(0.30)) {
            stepMovementNegotiationOrSplitV250(world, st, mov, rng);
          }
        } else if (rng.chance(0.03)) {
          // Leader killed p = 0.03 per month (50% via startAssassinationPlotV240 TRAITOR_HUNT when available)
          const oldLeader = leader;
          const startPlotFn = getSoftLinkFnV250('startAssassinationPlotV240', typeof startAssassinationPlotV240 === 'function' ? startAssassinationPlotV240 : undefined);
          if (typeof startPlotFn === 'function' && rng.chance(0.50)) {
            startPlotFn(world, { sponsorId: st.id, targetId: oldLeader.id, kind: 'TRAITOR_HUNT' });
          } else {
            handleNPCDeath(world, oldLeader, 'ถูกสังหารในปฏิบัติการต่อต้านการก่อความไม่สงบ');
          }
          const newLeader = generateContextualNPC(world, rng, { stateId: st.id, homeCityId: leadCity.id, age: rng.int(30, 50), positionId: 'SENIOR_OFFICIAL', track: 'military' });
          newLeader.secessionDesire = rng.int(80, 96);
          if (typeof ensureNPCDeepProfileV170 === 'function') ensureNPCDeepProfileV170(world, newLeader, rng);
          if (typeof ensureNPCPowerModelV200 === 'function') ensureNPCPowerModelV200(world, newLeader);
          ensureKinV250(world);
          mov.leaderId = newLeader.id;
          leader = newLeader;

          const kTpl = rng.pick(SEPARATISM_LEADER_KILLED_TEMPLATES_V250);
          const kMsg = fillTemplateV250(kTpl, {
            state: st.name,
            city: leadCity.name.split(' (')[0],
            leader: oldLeader.name,
            newLeader: newLeader.name,
            name: mov.name,
            strength: Math.round(mov.strength),
            gdpShare,
            fighters: (mov.fighters || 2000).toLocaleString(),
            year: world.year || 2026
          });
          addChronicle(world, 'SEPARATISM', kMsg, st.id, { personId: oldLeader.id, cityId: leadCity.id, subKind: 'LEADER_KILLED' });
        }

        // Independence check: ARMED and strength >= 80 and sponsorId and leader.ambition >= 80 and st.stability < 40
        const leaderAmb = leader.personality?.ambition ?? leader.ambition ?? 82;
        if (mov.strength >= 80 && mov.sponsorId && leaderAmb >= 80 && (st.stability || 70) < 40) {
          const indRes = executeClusterIndependenceV250(world, mov, false, rng);
          if (indRes && indRes.ok) {
            active.splice(i, 1);
            world.undergroundV250.movementArchive.unshift(mov);
            if (world.undergroundV250.movementArchive.length > 40) world.undergroundV250.movementArchive.length = 40;
            continue;
          }
        }
      }

      // Foreign sponsorId exposure: monthly 4% -> relation -15 and imposeTradeMeasureV230(..., 2, 'RIVALRY')
      if (mov.sponsorId && world.states[mov.sponsorId] && rng.chance(0.04)) {
        const spSt = world.states[mov.sponsorId];
        if (st.relations && st.relations[spSt.id]) {
          st.relations[spSt.id].score = clamp((st.relations[spSt.id].score || 50) - 15, 0, 100);
        }
        if (spSt.relations && spSt.relations[st.id]) {
          spSt.relations[st.id].score = clamp((spSt.relations[st.id].score || 50) - 15, 0, 100);
        }
        const tradeFn = getSoftLinkFnV250('imposeTradeMeasureV230', typeof imposeTradeMeasureV230 === 'function' ? imposeTradeMeasureV230 : undefined);
        if (typeof tradeFn === 'function') {
          tradeFn(world, st.id, spSt.id, 2, 'RIVALRY');
        }
        const sTpl = rng.pick(SEPARATISM_SPONSOR_EXPOSED_TEMPLATES_V250);
        const sMsg = fillTemplateV250(sTpl, {
          state: st.name,
          sponsor: spSt.name,
          name: mov.name,
          leader: leader.name,
          city: leadCity.name.split(' (')[0],
          fighters: (mov.fighters || 1500).toLocaleString(),
          strength: Math.round(mov.strength),
          gdpShare,
          year: world.year || 2026
        });
        addChronicle(world, 'SEPARATISM', sMsg, st.id, { personId: leader.id, secondStateId: spSt.id, cityId: leadCity.id, subKind: 'SPONSOR_EXPOSED' });
      }
    }
  }

  function runMovementCycleV250(world, rngInstance = null) {
    if (!world || !world.states) return;
    ensureUndergroundV250(world);
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + (world.tick || 0) * 271);

    // Sample <= 10 candidate cities from states that are not exiled (skip player state only if aiSandbox === false)
    const usedCities = new Set();
    (world.undergroundV250.movements || []).forEach((m) => (m.cityIds || []).forEach((cid) => usedCities.add(cid)));

    const allCities = Object.values(world.cities || {}).filter((c) => {
      if (!c || c.isCapital || usedCities.has(c.id)) return false;
      const st = world.states[c.stateId];
      if (!st || st.isExiled) return false;
      if (world.aiSandbox === false && st.id === world.playerStateId) return false;
      return true;
    });

    // Prioritize cities that meet the candidate thresholds so high-resentment clusters are reliably evaluated within the 10-city sample budget
    const qualifying = allCities.filter(
      (c) => (c.regionalPolitics?.regionalParliament?.autonomyDemandPct ?? 0) >= 60 && (c.resentment ?? 0) >= 45
    );
    const pool = qualifying.length > 0 ? qualifying : allCities;
    const sampleCount = Math.min(10, pool.length);
    const sampled = [];
    for (let k = 0; k < sampleCount; k++) {
      const idx = (k + rng.int(0, pool.length - 1)) % pool.length;
      const c = pool[idx];
      if (!sampled.includes(c)) sampled.push(c);
    }

    for (let i = 0; i < sampled.length; i++) {
      if (world.undergroundV250.movements.length >= 12) break;
      const city = sampled[i];
      if (usedCities.has(city.id)) continue;
      const aut = city.regionalPolitics?.regionalParliament?.autonomyDemandPct ?? 0;
      const res = city.resentment ?? 0;
      if (aut < 60 || res < 45) continue;

      const st = world.states[city.stateId];
      if (!st) continue;
      let p = 0.04;
      if (st.underground && st.underground.foreignSponsorId) p *= 1.5;
      const hasOccupied = Object.values(world.cities || {}).some((x) => x.stateId === st.id && x.isOccupied);
      if (hasOccupied) p *= 1.4;
      const locSup = city.regionalPolitics?.regionalParliament?.localSupportPct ?? 60;
      if (st.regimeCategory === 'Democracy' && locSup >= 70) p *= 0.5;
      // Boost when both resentment and autonomy are extreme (>= 75)
      if (aut >= 80 && res >= 75) p = Math.max(p, 0.14);

      if (rng.chance(p)) {
        const spRes = spawnMovementV250(world, st.id, city.id, { rng });
        if (spRes && spRes.ok && spRes.movement) {
          (spRes.movement.cityIds || []).forEach((cid) => usedCities.add(cid));
        }
      }
    }

    // Run monthly dynamics every 2nd movement cycle (30 ticks)
    world.undergroundV250._movCycleCount = (world.undergroundV250._movCycleCount || 0) + 1;
    if (world.undergroundV250._movCycleCount % 2 === 0) {
      runMovementMonthV250(world, rng);
    }
  }

  // -------------------------------------------------------------------------
  // T8.3 REFERENDUM ENGINE
  // -------------------------------------------------------------------------
  function initialYesPctV250(world, ref) {
    if (!world || !ref) return 50;
    const st = world.states && world.states[ref.stateId];
    if (!st) return 50;
    const cities = (ref.cityIds && ref.cityIds.length > 0)
      ? ref.cityIds.map((id) => world.cities[id]).filter(Boolean)
      : Object.values(world.cities || {}).filter((c) => c.stateId === st.id);

    const avgAutonomy = cities.length > 0
      ? cities.reduce((s, c) => s + (c.regionalPolitics?.regionalParliament?.autonomyDemandPct ?? 45), 0) / cities.length
      : 45;
    const avgLocalSupport = cities.length > 0
      ? cities.reduce((s, c) => s + (c.regionalPolitics?.regionalParliament?.localSupportPct ?? 60), 0) / cities.length
      : 60;
    const avgResentment = cities.length > 0
      ? cities.reduce((s, c) => s + (c.resentment ?? 30), 0) / cities.length
      : 30;
    const avgEconomy = cities.length > 0
      ? cities.reduce((s, c) => s + (c.economy ?? 75), 0) / cities.length
      : 75;

    const allStCities = Object.values(world.cities || {}).filter((c) => c.stateId === st.id);
    const natAvgEco = allStCities.length > 0
      ? allStCities.reduce((s, c) => s + (c.economy ?? 75), 0) / allStCities.length
      : 75;
    const economicGap = Math.max(0, Math.abs(natAvgEco - avgEconomy));

    const mov = ((world.undergroundV250 && world.undergroundV250.movements) || []).find((m) => m.stateId === st.id);
    const movStrength = mov ? (mov.strength || 35) : (ref.movementStrength || 30);

    const typeId = ref.typeId || 'AUTONOMY';
    let raw = 50;
    if (typeId === 'AUTONOMY') {
      raw = 0.5 * avgAutonomy + 0.3 * (100 - avgLocalSupport) + 0.2 * avgResentment;
    } else if (typeId === 'INDEPENDENCE') {
      raw =
        0.35 * avgAutonomy +
        0.25 * (100 - avgLocalSupport) +
        0.2 * avgResentment +
        0.1 * economicGap +
        0.1 * movStrength -
        0.15 * Math.max(0, avgEconomy - 60);
    } else if (typeId === 'ALLIANCE_MEMBERSHIP') {
      const oppStr = st.politicalPressures?.oppositionStrength ?? (100 - (st.approval || 65));
      const al = (ref.allianceId && (world.alliances || []).find((a) => a.id === ref.allianceId)) || (world.alliances || [])[0];
      const bigMemberId = (al && al.leaderId && al.leaderId !== st.id) ? al.leaderId : ((al && al.members && al.members.find((m) => m !== st.id)) || 'US');
      const relScore = st.relations?.[bigMemberId]?.score ?? 55;
      raw = 0.5 * oppStr + 0.3 * (relScore - 40) + 18;
    } else if (typeId === 'CONSTITUTIONAL_REFORM') {
      const govPop = st.politicalPressures?.governmentPopularity ?? (st.approval || 65);
      const head = st.positions?.HEAD_OF_STATE ? world.npcs[st.positions.HEAD_OF_STATE] : null;
      const charisma = head?.charisma ?? head?.reputation ?? 65;
      const execPow = st.executivePowerV250 ?? 55;
      raw = 0.45 * govPop + 0.25 * charisma + 0.2 * execPow;
    }

    return clamp(+raw.toFixed(1), 5, 95);
  }

  function computeReferendumTurnoutV250(yesPct, legal, rngInstance = null) {
    const polarisation = Math.abs((yesPct ?? 50) - 50) * 2;
    const legalBonus = legal === 'LEGAL' ? 10 : -15;
    const noise = rngInstance ? rngInstance.int(-6, 6) : 0;
    return clamp(Math.round(55 + 0.25 * polarisation + legalBonus + noise), 15, 95);
  }

  function callReferendumV250(world, stateId, typeId = 'AUTONOMY', opts = {}) {
    if (!world || !world.states || !world.states[stateId]) {
      return { ok: false, reason: 'ไม่พบรัฐที่ระบุ' };
    }
    ensureUndergroundV250(world);
    if (!REFERENDUM_TYPES_V250.includes(typeId)) {
      return { ok: false, reason: 'ประเภทประชามติไม่ถูกต้อง' };
    }
    const st = world.states[stateId];
    const activeRefs = world.undergroundV250.referendums;
    if (!opts.allowMultiple && activeRefs.some((r) => r.stateId === stateId)) {
      return { ok: false, reason: 'รัฐนี้มีการลงประชามติที่กำลังดำเนินการอยู่แล้ว' };
    }

    const rng = opts.rng || new SeededRNG((world.seed || 2026) + (world.tick || 0) * 131 + hashStr(stateId + typeId));
    const mov = activeRefs ? (world.undergroundV250.movements || []).find((m) => m.stateId === stateId) : null;

    let cityIds = opts.cityIds || null;
    if (!cityIds && (typeId === 'AUTONOMY' || typeId === 'INDEPENDENCE')) {
      if (mov && Array.isArray(mov.cityIds) && mov.cityIds.length > 0) {
        cityIds = mov.cityIds.slice();
      } else {
        const regCity = Object.values(world.cities || {})
          .filter((c) => c.stateId === stateId && !c.isCapital)
          .sort((a, b) => (b.regionalPolitics?.regionalParliament?.autonomyDemandPct || 40) - (a.regionalPolitics?.regionalParliament?.autonomyDemandPct || 40))[0];
        cityIds = regCity ? buildConnectedClusterV250(world, regCity, 40) : null;
      }
    }

    const calledBy = opts.calledBy || ((typeId === 'AUTONOMY' || typeId === 'INDEPENDENCE') ? 'REGIONAL_PARLIAMENT' : 'GOVERNMENT');
    const isDem = st.regimeCategory === 'Democracy';
    let legal = opts.legal;
    if (!legal) {
      if (isDem && calledBy === 'GOVERNMENT') legal = 'LEGAL';
      else if (isDem && calledBy === 'REGIONAL_PARLIAMENT') legal = 'CONTESTED';
      else legal = 'ILLEGAL';
    }

    let allianceId = opts.allianceId || null;
    if (typeId === 'ALLIANCE_MEMBERSHIP' && !allianceId) {
      const curAl = (world.alliances || []).find((a) => Array.isArray(a.members) && a.members.includes(stateId)) || (world.alliances || [])[0];
      allianceId = curAl ? curAl.id : 'ALLIANCE_NATO';
    }

    const ref = {
      id: 'REF_' + (++world.undergroundV250.nextId),
      typeId,
      stateId,
      cityIds,
      allianceId,
      calledBy,
      legal,
      stage: 'CALLED',
      stageDay: 0,
      calledDuration: rng.int(1, 3),
      campaignDuration: opts.campaignDuration || rng.int(20, 35),
      aftermathDuration: opts.aftermathDuration || 25,
      polls: [], // cap 8
      yesPct: 50,
      turnoutPct: 65,
      result: null,
      path: null,
      log: []
    };

    ref.yesPct = opts.yesPct !== undefined ? opts.yesPct : initialYesPctV250(world, ref);
    ref.turnoutPct = computeReferendumTurnoutV250(ref.yesPct, ref.legal, rng);
    ref.polls.push({ tick: world.tick || 0, yesPct: ref.yesPct });

    if (activeRefs.length >= 6) {
      const oldest = activeRefs.shift();
      world.undergroundV250.referendumArchive.unshift(oldest);
      if (world.undergroundV250.referendumArchive.length > 40) world.undergroundV250.referendumArchive.length = 40;
    }
    activeRefs.push(ref);

    const leadCity = (cityIds && cityIds[0] && world.cities[cityIds[0]]) || Object.values(world.cities || {}).find((c) => c.stateId === stateId && c.isCapital) || Object.values(world.cities || {}).find((c) => c.stateId === stateId);
    const head = st.positions?.HEAD_OF_STATE ? world.npcs[st.positions.HEAD_OF_STATE] : null;
    const tplPool = REFERENDUM_CALLED_TEMPLATES_V250[typeId] || REFERENDUM_CALLED_TEMPLATES_V250.AUTONOMY;
    const msg = fillTemplateV250(rng.pick(tplPool), {
      city: leadCity ? leadCity.name.split(' (')[0] : shortNameTh(st),
      state: st.name,
      legal: ref.legal,
      yesPct: Math.round(ref.yesPct),
      leader: head ? head.name : `ผู้นำ ${shortNameTh(st)}`,
      year: world.year || 2026
    });
    ref.log.unshift(`[${world.dateString || '2026-01-01'}] ประกาศจัดประชามติ ${typeId} (${ref.legal}) โพลเริ่มต้น ${Math.round(ref.yesPct)}%`);
    addChronicle(world, 'REFERENDUM', msg, stateId, { personId: head ? head.id : null, cityId: leadCity ? leadCity.id : null, subKind: `CALLED_${typeId}` });
    return { ok: true, id: ref.id, referendum: ref, narrative: msg };
  }

  function applyReferendumAftermathV250(world, ref, rngInstance = null) {
    if (!world || !ref) return;
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + (world.tick || 0) * 179 + hashStr(ref.id));
    const st = world.states[ref.stateId];
    if (!st) return;

    const head = st.positions?.HEAD_OF_STATE ? world.npcs[st.positions.HEAD_OF_STATE] : null;
    const leaderName = head ? head.name : `ผู้นำ ${shortNameTh(st)}`;
    const cities = (ref.cityIds && ref.cityIds.length > 0)
      ? ref.cityIds.map((id) => world.cities[id]).filter(Boolean)
      : Object.values(world.cities || {}).filter((c) => c.stateId === st.id);
    const leadCity = cities[0] || Object.values(world.cities || {}).find((c) => c.stateId === st.id);
    const cityShort = leadCity ? leadCity.name.split(' (')[0] : shortNameTh(st);
    let mov = (world.undergroundV250.movements || []).find((m) => m.stateId === st.id);

    // Addendum Link 1: A referendum PASSED shifts rulingSeats toward the winning side (±8-20% of seats) while preserving sum
    if (ref.result === 'PASSED') {
      cities.forEach((c) => {
        if (c && c.regionalPolitics && c.regionalPolitics.regionalParliament) {
          const par = c.regionalPolitics.regionalParliament;
          const total = par.totalSeats || ((par.rulingSeats || 30) + (par.oppositionSeats || 20)) || 50;
          par.totalSeats = total;
          const shiftPct = rng.int(8, 20) / 100;
          const deltaSeats = Math.max(1, Math.round(total * shiftPct));
          if (ref.calledBy === 'GOVERNMENT') {
            par.rulingSeats = clamp((par.rulingSeats || Math.round(total * 0.5)) + deltaSeats, 1, total - 1);
            par.oppositionSeats = total - par.rulingSeats;
          } else {
            // Regional/movement won -> shift toward regional ruling/autonomist side
            par.rulingSeats = clamp((par.rulingSeats || Math.round(total * 0.5)) + deltaSeats, 1, total - 1);
            par.oppositionSeats = total - par.rulingSeats;
          }
        }
      });
    }

    if (ref.typeId === 'INDEPENDENCE') {
      if (ref.result === 'PASSED') {
        if (ref.legal === 'LEGAL') {
          ref.path = 'NEGOTIATED_SEPARATION';
          if (!mov) {
            const sp = spawnMovementV250(world, st.id, leadCity ? leadCity.id : null, { rng, strength: 75 });
            mov = sp.movement;
          }
          if (mov) {
            executeClusterIndependenceV250(world, mov, true, rng);
          }
          const tpl = rng.pick(REFERENDUM_AFTERMATH_TEMPLATES_V250.NEGOTIATED_SEPARATION);
          const msg = fillTemplateV250(tpl, { city: cityShort, state: st.name, yesPct: Math.round(ref.yesPct), leader: leaderName });
          addChronicle(world, 'REFERENDUM', msg, st.id, { personId: head ? head.id : null, cityId: leadCity ? leadCity.id : null, subKind: 'AFTERMATH_NEGOTIATED_SEPARATION' });
        } else if (ref.legal === 'CONTESTED') {
          const isDem = st.regimeCategory === 'Democracy';
          if (isDem && rng.chance(0.30)) {
            ref.path = 'RECOGNISE';
            if (!mov) {
              const sp = spawnMovementV250(world, st.id, leadCity ? leadCity.id : null, { rng, strength: 72 });
              mov = sp.movement;
            }
            if (mov) {
              executeClusterIndependenceV250(world, mov, true, rng);
            }
            const tpl = rng.pick(REFERENDUM_AFTERMATH_TEMPLATES_V250.RECOGNISE);
            const msg = fillTemplateV250(tpl, { city: cityShort, state: st.name, yesPct: Math.round(ref.yesPct), leader: leaderName });
            addChronicle(world, 'REFERENDUM', msg, st.id, { personId: head ? head.id : null, cityId: leadCity ? leadCity.id : null, subKind: 'AFTERMATH_RECOGNISE' });
          } else {
            ref.path = 'REFUSE_INSURGENCY';
            if (!mov) {
              const sp = spawnMovementV250(world, st.id, leadCity ? leadCity.id : null, { rng, strength: 58, armed: true });
              mov = sp.movement;
            }
            if (mov) {
              mov.armed = true;
              mov.strength = clamp(+(mov.strength + 12).toFixed(2), 55, 100);
              mov.phase = 'ARMED';
              recordThirdStateRecognitionsV250(world, mov, st, null, rng);
            }
            const aggr = head?.personality?.aggression ?? 60;
            if (aggr > 70 && leadCity) {
              leadCity.isFrontline = true;
              leadCity.unrest = clamp(rnd1((leadCity.unrest || 35) + 12), 0, 100);
            }
            const tpl = rng.pick(REFERENDUM_AFTERMATH_TEMPLATES_V250.REFUSE_INSURGENCY);
            const msg = fillTemplateV250(tpl, { city: cityShort, state: st.name, yesPct: Math.round(ref.yesPct), leader: leaderName });
            addChronicle(world, 'REFERENDUM', msg, st.id, { personId: head ? head.id : null, cityId: leadCity ? leadCity.id : null, subKind: 'AFTERMATH_REFUSE_INSURGENCY' });
          }
        } else {
          // PASSED + ILLEGAL -> crushed: 70% SUPPRESSED (mass arrests, leader detained), else ARMED
          if (rng.chance(0.70)) {
            ref.path = 'SUPPRESSED';
            if (mov) {
              mov.phase = 'SUPPRESSED';
              mov.armed = false;
              mov.strength = Math.min(10, mov.strength);
              const mLeader = mov.leaderId ? world.npcs[mov.leaderId] : null;
              if (mLeader) mLeader.imprisonedUntilTick = (world.tick || 0) + 360;
            }
            if (st.underground) {
              st.underground.dissidentNetwork = clamp(rnd1((st.underground.dissidentNetwork || 25) + 8), 0, 100);
            }
            const tpl = rng.pick(REFERENDUM_AFTERMATH_TEMPLATES_V250.CRUSH);
            const msg = fillTemplateV250(tpl, { city: cityShort, state: st.name, yesPct: Math.round(ref.yesPct), leader: leaderName });
            addChronicle(world, 'REFERENDUM', msg, st.id, { personId: head ? head.id : null, cityId: leadCity ? leadCity.id : null, subKind: 'AFTERMATH_CRUSH' });
          } else {
            ref.path = 'ARMED';
            if (!mov) {
              const sp = spawnMovementV250(world, st.id, leadCity ? leadCity.id : null, { rng, strength: 60, armed: true });
              mov = sp.movement;
            }
            if (mov) {
              mov.armed = true;
              mov.strength = Math.max(58, mov.strength + 10);
              mov.phase = 'ARMED';
            }
            const tpl = rng.pick(REFERENDUM_AFTERMATH_TEMPLATES_V250.REFUSE_INSURGENCY);
            const msg = fillTemplateV250(tpl, { city: cityShort, state: st.name, yesPct: Math.round(ref.yesPct), leader: leaderName });
            addChronicle(world, 'REFERENDUM', msg, st.id, { personId: head ? head.id : null, cityId: leadCity ? leadCity.id : null, subKind: 'AFTERMATH_REFUSE_INSURGENCY' });
          }
        }
      } else {
        // FAILED -> movement strength -= 10 or radicalises 30%
        ref.path = 'FAILED';
        if (mov) {
          if (rng.chance(0.30)) {
            mov.moderateShare = clamp(+((mov.moderateShare || 0.5) - 0.15).toFixed(2), 0.05, 0.95);
            mov.strength = clamp(+(mov.strength + 5).toFixed(2), 0, 100);
          } else {
            mov.strength = clamp(+(mov.strength - 10).toFixed(2), 0, 100);
          }
        }
      }
    } else if (ref.typeId === 'AUTONOMY') {
      if (ref.result === 'PASSED') {
        ref.path = 'AUTONOMY_GRANTED';
        cities.forEach((c) => {
          if (c.regionalPolitics && c.regionalPolitics.regionalParliament) {
            c.regionalPolitics.regionalParliament.autonomyDemandPct = clamp(rnd1((c.regionalPolitics.regionalParliament.autonomyDemandPct || 60) - 15), 0, 100);
            c.regionalPolitics.regionalParliament.localSupportPct = clamp(rnd1((c.regionalPolitics.regionalParliament.localSupportPct || 55) + 5), 0, 100);
          }
        });
        st.stability = clamp(rnd1((st.stability || 70) - 1), 5, 100);
        if (mov && ref.legal === 'LEGAL') {
          mov.phase = 'AUTONOMY_DEAL';
          applyMovementPhaseAlignmentV250(world, mov);
        }
        const tpl = rng.pick(REFERENDUM_AFTERMATH_TEMPLATES_V250.AUTONOMY_GRANTED);
        const msg = fillTemplateV250(tpl, { city: cityShort, state: st.name, yesPct: Math.round(ref.yesPct), leader: leaderName });
        addChronicle(world, 'REFERENDUM', msg, st.id, { personId: head ? head.id : null, cityId: leadCity ? leadCity.id : null, subKind: 'AFTERMATH_AUTONOMY_GRANTED' });
      } else {
        ref.path = 'FAILED';
        if (mov) mov.strength = clamp(+(mov.strength - 6).toFixed(2), 0, 100);
      }
    } else if (ref.typeId === 'ALLIANCE_MEMBERSHIP') {
      if (ref.result === 'PASSED') {
        ref.path = 'ALLIANCE_CHANGE';
        const alId = ref.allianceId || ((world.alliances && world.alliances[0]) ? world.alliances[0].id : 'ALLIANCE_NATO');
        const al = (world.alliances || []).find((a) => a.id === alId);
        if (al && typeof triggerAllianceMemberExitOrJoinV210 === 'function') {
          const isMember = Array.isArray(al.members) && al.members.includes(st.id);
          const action = isMember ? 'leave' : 'join';
          // Ensure targetHegemonId doesn't block join during referendum
          if (action === 'join' && al.targetHegemonId === st.id) {
            const altAl = (world.alliances || []).find((a) => a.targetHegemonId !== st.id && !a.members.includes(st.id));
            if (altAl) triggerAllianceMemberExitOrJoinV210(world, altAl.id, st.id, 'join', 'มติประชามติระดับชาติ');
          } else {
            triggerAllianceMemberExitOrJoinV210(world, al.id, st.id, action, 'มติประชามติระดับชาติ');
          }
        }
        const tpl = rng.pick(REFERENDUM_AFTERMATH_TEMPLATES_V250.ALLIANCE_CHANGE);
        const msg = fillTemplateV250(tpl, { city: cityShort, state: st.name, yesPct: Math.round(ref.yesPct), leader: leaderName });
        addChronicle(world, 'REFERENDUM', msg, st.id, { personId: head ? head.id : null, cityId: leadCity ? leadCity.id : null, subKind: 'AFTERMATH_ALLIANCE_CHANGE' });
      } else {
        ref.path = 'FAILED';
        st.approval = clamp(rnd1((st.approval || 65) - 3), 5, 100);
      }
    } else if (ref.typeId === 'CONSTITUTIONAL_REFORM') {
      if (ref.result === 'PASSED') {
        ref.path = 'REFORM';
        st.executivePowerV250 = clamp(rnd1((st.executivePowerV250 || 50) + 15), 0, 100);
        st.stability = clamp(rnd1((st.stability || 70) + 2), 5, 100);
        // Addendum Link 8: adjust democracyState.nextElectionYear only through the existing field
        if (st.democracyState) {
          st.democracyState.nextElectionYear = (st.democracyState.nextElectionYear || (world.year || 2026) + 2) + 1;
        }
        let backslideText = '';
        const headAmb = head?.personality?.ambition ?? head?.ambition ?? 75;
        if (st.executivePowerV250 > 80 && headAmb > 85 && st.regimeCategory === 'Democracy') {
          if (st.underground) st.underground.intelSuppression = clamp(rnd1((st.underground.intelSuppression || 20) + 8), 0, 100);
          if (st.informationOps) st.informationOps.mediaControl = clamp(rnd1((st.informationOps.mediaControl || 35) + 6), 0, 100);
          st.securityPostureV250 = clamp(rnd1((st.securityPostureV250 || 40) + 8), 0, 100);
          backslideText = ' ท่ามกลางคำเตือนเรื่องภาวะประชาธิปไตยถดถอย (Democratic Backsliding) จากการรวบอำนาจบริหารและควบคุมสื่อ';
        }
        const tpl = rng.pick(REFERENDUM_AFTERMATH_TEMPLATES_V250.REFORM);
        const msg = fillTemplateV250(tpl, { city: cityShort, state: st.name, yesPct: Math.round(ref.yesPct), leader: leaderName, backslideText });
        addChronicle(world, 'REFERENDUM', msg, st.id, { personId: head ? head.id : null, cityId: leadCity ? leadCity.id : null, subKind: 'AFTERMATH_REFORM' });
      } else {
        ref.path = 'FAILED';
        if (head) head.reputation = clamp((head.reputation || 60) - 5, 5, 100);
        if (st.parliament) {
          const seatLoss = rng.int(5, 20);
          st.parliament.coalitionSeats = Math.max(50, (st.parliament.coalitionSeats || 260) - seatLoss);
          st.parliament.oppositionSeats = 500 - st.parliament.coalitionSeats;
        }
        if (st.democracyState) {
          st.democracyState.nextElectionYear = Math.min(st.democracyState.nextElectionYear || ((world.year || 2026) + 2), (world.year || 2026) + 1);
        }
      }
    }
  }

  function stepActiveReferendumsV250(world, daysStep = 7, rngInstance = null) {
    if (!world || !world.undergroundV250 || !Array.isArray(world.undergroundV250.referendums)) return;
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + (world.tick || 0) * 199);
    const active = world.undergroundV250.referendums;

    for (let i = active.length - 1; i >= 0; i--) {
      const ref = active[i];
      const st = world.states[ref.stateId];
      if (!st) {
        active.splice(i, 1);
        continue;
      }
      ref.stageDay = (ref.stageDay || 0) + daysStep;
      const mov = (world.undergroundV250.movements || []).find((m) => m.stateId === st.id);
      const leadCity = (ref.cityIds && ref.cityIds[0] && world.cities[ref.cityIds[0]]) || Object.values(world.cities || {}).find((c) => c.stateId === st.id && c.isCapital) || Object.values(world.cities || {}).find((c) => c.stateId === st.id);
      const head = st.positions?.HEAD_OF_STATE ? world.npcs[st.positions.HEAD_OF_STATE] : null;

      if (ref.stage === 'CALLED') {
        if (ref.stageDay >= (ref.calledDuration || 2)) {
          ref.stage = 'CAMPAIGN';
          ref.stageDay = 0;
        }
      } else if (ref.stage === 'CAMPAIGN') {
        const movStr = mov ? (mov.strength || 45) : 45;
        const govCounter = ref.calledBy !== 'GOVERNMENT';
        const isCrackdown = mov && mov.response && mov.response.kind === 'CRACKDOWN';
        const swing = (rng.next() * 4.5 - 2.0) + (movStr - 50) * 0.02 - (govCounter ? 1.5 : 0) + (isCrackdown ? 3.0 : 0);
        ref.yesPct = clamp(+(ref.yesPct + swing).toFixed(1), 5, 95);
        ref.polls.push({ tick: world.tick || 0, yesPct: ref.yesPct });
        if (ref.polls.length > 8) ref.polls.shift(); // cap 8

        const oppLeader = (st.positions?.OPPOSITION_LEADER && world.npcs[st.positions.OPPOSITION_LEADER]) || (mov && mov.leaderId && world.npcs[mov.leaderId]) || null;
        const yesSpeaker = ref.calledBy === 'GOVERNMENT' ? (head ? head.name : 'โฆษกรัฐบาล') : (oppLeader ? oppLeader.name : 'แกนนำฝ่ายสนับสนุน');
        const noSpeaker = ref.calledBy === 'GOVERNMENT' ? (oppLeader ? oppLeader.name : 'แกนนำฝ่ายค้าน') : (head ? head.name : 'ตัวแทนรัฐบาลกลาง');

        const pTpl = rng.pick(REFERENDUM_CAMPAIGN_POLL_TEMPLATES_V250);
        const pMsg = fillTemplateV250(pTpl, {
          type: ref.typeId,
          state: st.name,
          city: leadCity ? leadCity.name.split(' (')[0] : shortNameTh(st),
          yesPct: Math.round(ref.yesPct),
          noPct: 100 - Math.round(ref.yesPct),
          yesSpeaker,
          noSpeaker
        });
        addChronicle(world, 'REFERENDUM', pMsg, st.id, { personId: head ? head.id : null, cityId: leadCity ? leadCity.id : null, subKind: 'CAMPAIGN_POLL' });

        if (ref.stageDay >= (ref.campaignDuration || 25)) {
          ref.stage = 'VOTE';
          ref.stageDay = 0;
          ref.turnoutPct = computeReferendumTurnoutV250(ref.yesPct, ref.legal, rng);
          const vTpl = rng.pick(REFERENDUM_VOTE_DAY_TEMPLATES_V250);
          const vMsg = fillTemplateV250(vTpl, {
            type: ref.typeId,
            state: st.name,
            city: leadCity ? leadCity.name.split(' (')[0] : shortNameTh(st),
            legal: ref.legal,
            turnoutPct: Math.round(ref.turnoutPct),
            yesPct: Math.round(ref.yesPct),
            leader: head ? head.name : `ผู้นำ ${shortNameTh(st)}`
          });
          addChronicle(world, 'REFERENDUM', vMsg, st.id, { personId: head ? head.id : null, cityId: leadCity ? leadCity.id : null, subKind: 'VOTE_DAY' });
        }
      } else if (ref.stage === 'VOTE') {
        ref.stage = 'RESULT';
        ref.stageDay = 0;
        ref.turnoutPct = computeReferendumTurnoutV250(ref.yesPct, ref.legal, rng);
        const passed = ref.yesPct > 50 && (ref.turnoutPct >= 50 || ref.legal !== 'LEGAL');
        ref.result = passed ? 'PASSED' : 'FAILED';

        const rKey = `${ref.typeId}_${ref.result}`;
        const rPool = REFERENDUM_RESULT_TEMPLATES_V250[rKey] || REFERENDUM_RESULT_TEMPLATES_V250.AUTONOMY_PASSED;
        const rMsg = fillTemplateV250(rng.pick(rPool), {
          city: leadCity ? leadCity.name.split(' (')[0] : shortNameTh(st),
          state: st.name,
          yesPct: Math.round(ref.yesPct),
          turnoutPct: Math.round(ref.turnoutPct),
          legal: ref.legal,
          leader: head ? head.name : `ผู้นำ ${shortNameTh(st)}`
        });
        addChronicle(world, 'REFERENDUM', rMsg, st.id, { personId: head ? head.id : null, cityId: leadCity ? leadCity.id : null, subKind: `RESULT_${rKey}` });
      } else if (ref.stage === 'RESULT') {
        ref.stage = 'AFTERMATH';
        ref.stageDay = 0;
        applyReferendumAftermathV250(world, ref, rng);
      } else if (ref.stage === 'AFTERMATH') {
        if (ref.stageDay >= (ref.aftermathDuration || 25)) {
          active.splice(i, 1);
          world.undergroundV250.referendumArchive.unshift(ref);
          if (world.undergroundV250.referendumArchive.length > 40) world.undergroundV250.referendumArchive.length = 40;
        }
      }
    }
  }

  function runReferendumCycleV250(world, rngInstance = null) {
    if (!world || !world.states) return;
    ensureUndergroundV250(world);
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + (world.tick || 0) * 239);

    // Step existing active referendums (cycle runs every 7 ticks)
    stepActiveReferendumsV250(world, 7, rng);

    if (world.undergroundV250.referendums.length >= 6) return;

    // 1. Movement-triggered referendums: ACTIVE movement in phase >= MOBILIZED whose cluster autonomyDemandPct >= 65 and with a regional parliament: 3% per cycle
    const movs = world.undergroundV250.movements || [];
    for (let i = 0; i < movs.length; i++) {
      if (world.undergroundV250.referendums.length >= 6) break;
      const m = movs[i];
      if (m.phase !== 'MOBILIZED' && m.phase !== 'ARMED') continue;
      if (world.undergroundV250.referendums.some((r) => r.stateId === m.stateId)) continue;
      const cities = (m.cityIds || []).map((cid) => world.cities[cid]).filter(Boolean);
      const hasRegParl = cities.some((c) => c.regionalPolitics && c.regionalPolitics.regionalParliament);
      const avgAut = cities.length > 0
        ? cities.reduce((s, c) => s + (c.regionalPolitics?.regionalParliament?.autonomyDemandPct || 50), 0) / cities.length
        : 0;
      if (hasRegParl && avgAut >= 65 && rng.chance(0.03)) {
        const refType = m.strength >= 55 ? 'INDEPENDENCE' : 'AUTONOMY';
        callReferendumV250(world, m.stateId, refType, {
          calledBy: 'REGIONAL_PARLIAMENT',
          cityIds: m.cityIds.slice(),
          rng
        });
      }
    }

    // 2. Government-called ALLIANCE_MEMBERSHIP (0.4%/cycle when approval < 50 and oppositionStrength > 45) & CONSTITUTIONAL_REFORM (0.4%/cycle when executivePowerV250 >= 55 and head ambition >= 75)
    const allStates = Object.values(world.states).filter((s) => !s.isExiled && !(world.aiSandbox === false && s.id === world.playerStateId));
    for (let i = 0; i < allStates.length; i++) {
      if (world.undergroundV250.referendums.length >= 6) break;
      const st = allStates[i];
      if (world.undergroundV250.referendums.some((r) => r.stateId === st.id)) continue;

      const oppStr = st.politicalPressures?.oppositionStrength ?? (100 - (st.approval || 65));
      if ((st.approval || 70) < 50 && oppStr > 45 && rng.chance(0.004)) {
        callReferendumV250(world, st.id, 'ALLIANCE_MEMBERSHIP', { calledBy: 'GOVERNMENT', rng });
        continue;
      }

      const head = st.positions?.HEAD_OF_STATE ? world.npcs[st.positions.HEAD_OF_STATE] : null;
      const headAmb = head?.personality?.ambition ?? head?.ambition ?? 60;
      if ((st.executivePowerV250 || 50) >= 55 && headAmb >= 75 && rng.chance(0.004)) {
        callReferendumV250(world, st.id, 'CONSTITUTIONAL_REFORM', { calledBy: 'GOVERNMENT', rng });
      }
    }
  }


  // =========================================================================
  // T8.4 TERRORISM & THE SECURITY STATE
  // =========================================================================
