  // 7. Addendum Link 3: Wrap triggerMilitaryCoup so a successful coup in a monarchy penalizes old royal house prestige -30 and opens a feud
  const _origTriggerMilitaryCoupV250 = triggerMilitaryCoup;
  triggerMilitaryCoup = function (world, generalNpc) {
    ensureKinV250(world);
    const st = generalNpc && world && world.states ? world.states[generalNpc.stateId] : null;
    const wasMonarchy = !!(st && (st.regimeCategory === 'Constitutional_Monarchy' || st._royalHouseIdV250));
    const oldHeadId = st && st.positions ? st.positions.HEAD_OF_STATE : null;
    const oldHead = oldHeadId && world.npcs ? world.npcs[oldHeadId] : null;
    const oldRoyalHouseId = (oldHead && oldHead.kinV250 && oldHead.kinV250.houseId) || (st && st._royalHouseIdV250) || null;

    const res = _origTriggerMilitaryCoupV250(world, generalNpc);
    if (res && res.ok && res.success && wasMonarchy && oldRoyalHouseId && world.kinV250.houses[oldRoyalHouseId]) {
      const royalHouse = world.kinV250.houses[oldRoyalHouseId];
      royalHouse.prestige = clamp((royalHouse.prestige || 65) - 30, 5, 100);
      const genHouseId = (generalNpc.kinV250 && generalNpc.kinV250.houseId) || `${generalNpc.stateId}_${generalNpc.lastName}`;
      const genHouse = world.kinV250.houses[genHouseId];
      if (genHouse && genHouse.id !== royalHouse.id) {
        addOrEscalateFeudV250(royalHouse, genHouse, 65, `การรัฐประหารโค่นล้มราชบัลลังก์โดย ${generalNpc.name}`, world.tick || 0);
      }
      syncDynastiesWithKinV250(world);
    }
    return res;
  };

  // 8. Addendum Link 8: Wrap holdParliamentSession so a house with prestige >= 70 gives its standing member's party +2% support
  const _origHoldParliamentSessionV250 = holdParliamentSession;
  holdParliamentSession = function (world, stateId, mode = 'auto') {
    const res = _origHoldParliamentSessionV250(world, stateId, mode);
    if (!world || !world.states || !world.states[stateId]) return res;
    ensureKinV250(world);
    const st = world.states[stateId];
    const highHouses = Object.values(world.kinV250.houses || {}).filter(
      (h) => h.stateId === stateId && (h.prestige || 0) >= 70 && (h.memberIds || []).some((id) => world.npcs[id]?.alive)
    );
    if (highHouses.length > 0) {
      const topH = highHouses[0];
      const standingMember = (topH.memberIds || []).map((id) => world.npcs[id]).find((n) => n && n.alive && !n.retired) || null;
      if (Array.isArray(st.factions) && st.factions.length > 0) {
        const targetFac = (standingMember && st.factions.find((f) => f.name === standingMember.faction || f.type === 'Government')) || st.factions[0];
        if (targetFac) {
          targetFac.publicSupport = clamp((targetFac.publicSupport ?? targetFac.satisfaction ?? 55) + 2, 5, 99);
          targetFac.satisfaction = clamp((targetFac.satisfaction ?? 55) + 2, 5, 99);
        }
      }
      if (st.parliament) {
        st.parliament.coalitionSeats = clamp((st.parliament.coalitionSeats || 260) + 10, 50, 450);
        st.parliament.oppositionSeats = 500 - st.parliament.coalitionSeats;
      }
    }
    return res;
  };

  // 9. T5.5-b: Wrap applyScandalVerdictAndFalloutV240 so CONVICTED verdict triggers a blood feud
  if (typeof applyScandalVerdictAndFalloutV240 === 'function') {
    const _origApplyScandalVerdictV250 = applyScandalVerdictAndFalloutV240;
    applyScandalVerdictAndFalloutV240 = function (world, sc, rng) {
      const res = _origApplyScandalVerdictV250(world, sc, rng);
      if (sc && sc.verdict === 'CONVICTED' && sc.subjectId && world.npcs && world.npcs[sc.subjectId]) {
        triggerBloodFeudV250(world, world.npcs[sc.subjectId], sc.stateId, sc.investigatorId || sc.whistleblowerId || null, 'คำพิพากษาจำคุกในคดีการเมือง');
      }
      return res;
    };
  }

  // 10. Wrap createInitialWorld, migrateWorld, stepDay
  const _origCreateInitialWorldV250 = createInitialWorld;
  createInitialWorld = function (seed = 202611717) {
    const w = _origCreateInitialWorldV250(seed);
    ensureWorldSystemsV250(w);
    return w;
  };

  const _origMigrateWorldV250 = migrateWorld;
  migrateWorld = function (world) {
    if (!world || !world.states) return world;
    _origMigrateWorldV250(world);
    ensureWorldSystemsV250(world);
    return world;
  };

  const _origStepDayV250 = stepDay;
  stepDay = function (world, rngInstance = null) {
    if (!world._v250) ensureWorldSystemsV250(world);
    _origStepDayV250(world, rngInstance);
    const rng = rngInstance || new SeededRNG((world.seed || 2026) + world.tick * 1299709);
    const t = world.tick;

    // Cycle offsets required by Section B:
    // - succession-crisis step: t % 5 === 2 (touches only active crises)
    if (t % 5 === 2 && world.kinV250 && world.kinV250.crises && world.kinV250.crises.length > 0) {
      stepSuccessionCrisesV250(world, rng);
    }
    // - hostage-crisis step: t % 3 === 0 (touches only active hostage crises)
    if (t % 3 === 0 && world.undergroundV250 && world.undergroundV250.hostageCrises && world.undergroundV250.hostageCrises.length > 0) {
      stepHostageCrisesV250(world, rng);
    }
    // - referendum cycle: t % 7 === 6
    if (t % 7 === 6) {
      runReferendumCycleV250(world, rng);
    }
    // - terror cycle: t % 9 === 7
    if (t % 9 === 7) {
      runTerrorCycleV250(world, rng);
    }
    // - movement cycle: t % 15 === 10
    if (t % 15 === 10) {
      runMovementCycleV250(world, rng);
    }
    // - kin monthly & security posture monthly: t % 30 === 17
    if (t % 30 === 17) {
      runMonthlyFeudCycleV250(world, rng);
      runMonthlySecurityPostureCycleV250(world, rng);
    }

    return world;
  };



