  // P8.2, P8.3, P8.4b, P8.7, P8.8 Wrap enactLegislationBillV230
  if (typeof enactLegislationBillV230 === 'function') {
    const _origEnactBillV260 = enactLegislationBillV230;
    enactLegislationBillV230 = function (world, stateId, billOrLawId = null, rng = null, opts = {}) {
      ensurePartiesV260(world);
      const st = resolveStateObjV230(world, stateId);
      if (!st) return { ok: false, reason: 'ไม่พบรัฐที่ระบุ' };
      const r = rng || new SeededRNG(((world.seed || 2026) + (world.tick || 1) * 1451 + hashStr(st.id)) >>> 0);

      let bill = null;
      if (billOrLawId && typeof billOrLawId === 'object') {
        bill = billOrLawId;
      } else if (typeof billOrLawId === 'string') {
        if (st.legislationV230?.activeBill && (st.legislationV230.activeBill.id === billOrLawId || st.legislationV230.activeBill.lawId === billOrLawId)) {
          bill = st.legislationV230.activeBill;
        } else {
          const propRes = proposeLegislationBillV230(world, st.id, billOrLawId, { immediateEnact: false });
          bill = propRes.bill;
        }
      } else {
        bill = st.legislationV230?.activeBill;
        if (!bill) {
          const propRes = proposeLegislationBillV230(world, st.id, null, { immediateEnact: false });
          bill = propRes.bill;
        }
      }
      if (!bill) return { ok: false, reason: 'ไม่พบร่างกฎหมาย' };

      // Ensure proposerPartyId & real seat votes are computed
      const parties = getActivePartiesOfStateV260(world, st.id, false);
      const ruling = (bill.proposerPartyId && world.partyV260.parties[bill.proposerPartyId]) ||
        parties.find((p) => p.status === 'RULING') || parties[0];
      if (ruling && !bill.proposerPartyId) {
        bill.proposerPartyId = ruling.id;
        bill.proposerPartyName = ruling.name;
        bill.proposerLeaderId = ruling.leaderId;
      }

      const voteCalc = computeBillSupportV260(world, st, bill.lawId, r);
      bill.expectedYesVotes = voteCalc.expectedYesVotes;
      bill.partyVotes = voteCalc.partyVotes;
      const totalSeats = voteCalc.totalSeats || 500;
      const yesVotes = voteCalc.expectedYesVotes;
      const noVotes = voteCalc.expectedNoVotes;

      // Supermajority check: DEMILITARIZATION & CONSOLIDATION need 2/3 in Democracy, 50% in Authoritarian, decreeEase override for JUNTA
      const isConstLaw = bill.lawId === 'LAW_CONSTITUTIONAL_DEMILITARIZATION' || bill.lawId === 'LAW_SUPREME_EXECUTIVE_CONSOLIDATION';
      const isDem = st.regimeCategory === 'Democracy' || st.regimeCategory === 'Constitutional_Monarchy' || st.regimeCategory === 'Federal_Union';
      const isJunta = st.regimeCategory === 'Military_Junta';
      const reqRatio = (isConstLaw && isDem) ? (2 / 3) : 0.5001;
      const reqSeats = Math.ceil(totalSeats * reqRatio);

      const forcePass = !!(opts && opts.force);
      const juntaOverride = isJunta && r.chance(REGIME_POWER_RULES_V230.Military_Junta?.decreeEase || 0.95);
      const passedVote = forcePass || juntaOverride || (yesVotes >= reqSeats);

      if (!passedVote) {
        // BLOCKED bill! (P8.2)
        bill.stage = 'BLOCKED';
        bill.progressPct = 100;
        bill.yesVotes = yesVotes;
        bill.noVotes = noVotes;
        bill.enactedTick = world.tick || 0;
        st.legislationV230.activeBill = null;
        world.legislationV230.activeBills = (world.legislationV230.activeBills || []).filter((b) => b.id !== bill.id);
        if (!Array.isArray(world.legislationV230.blockedBillsV260)) world.legislationV230.blockedBillsV260 = [];
        world.legislationV230.blockedBillsV260.unshift(bill);
        if (world.legislationV230.blockedBillsV260.length > 80) world.legislationV230.blockedBillsV260.length = 80;

        if (ruling) {
          ruling.popularity = clamp((ruling.popularity || 25) - 2, 1, 98);
          if (!ruling.record) ruling.record = { billsProposedIds: [], billsPassedIds: [], billsBlockedIds: [] };
          if (!ruling.record.billsBlockedIds.includes(bill.id)) ruling.record.billsBlockedIds.push(bill.id);
        }
        const coal = (world.partyV260.coalitions || []).find((c) => c.stateId === st.id);
        if (coal) coal.stability = clamp((coal.stability || 65) - 4, 5, 98);
        if (st.democracyState) {
          st.democracyState.coalitionStability = clamp((st.democracyState.coalitionStability || 65) - 4, 5, 98);
        }

        const ldr = ruling && ruling.leaderId ? world.npcs[ruling.leaderId] : null;
        const blockMsg = `⚖️❌ [ร่าง "${bill.titleTh}" ตกในสภา (${yesVotes}:${noVotes})!] สภานิติบัญญัติแห่ง ${st.name} ลงมติตีตกร่างกฎหมายของ "${ruling ? ruling.name : 'พรรครัฐบาล'}" นำโดย "${ldr ? ldr.name : 'ผู้นำรัฐบาล'}" ด้วยคะแนนเสียงเห็นชอบเพียง ${yesVotes} ต่อ ${noVotes} ที่นั่ง (ต้องการอย่างน้อย ${reqSeats} ที่นั่ง) ส่งผลให้คะแนนนิยมพรรครัฐบาลลดลง -2 จุด และเสถียรภาพรัฐบาลผสมลดลงเหลือ ${st.democracyState?.coalitionStability || 60}%!`;
        addChronicle(world, 'LEGISLATION', blockMsg, st.id, {
          personId: ldr ? ldr.id : null,
          partyId: ruling ? ruling.id : null,
          billId: bill.id
        });

        // A failing bill by a minority coalition can trigger the P5 coalition COLLAPSE check
        if ((st.parliament?.coalitionSeats || 250) < totalSeats / 2 && r.chance(0.25)) {
          runNoConfidenceV260(world, st.id, { rng: r });
        } else {
          syncLegacyPoliticsV260(world, st.id);
        }

        return { ok: false, blocked: true, bill, yesVotes, noVotes, reason: `ร่าง "${bill.titleTh}" ตกในสภา (${yesVotes}:${noVotes} เสียง)` };
      }

      // Bill PASSED!
      // For LAW_SUPREME_EXECUTIVE_CONSOLIDATION, prevent direct overwrite of parliament.coalitionSeats (+45) by temporarily swapping lawId during _origEnactBillV260 or restoring immediately via party layer!
      // Test D17 specifically checks: "CONSOLIDATION never writes coalitionSeats directly (spy/guard); bans start; coalitionSeats + oppositionSeats === totalSeats after every law; DEMILITARIZATION removes military backer links."
      const origLawId = bill.lawId;
      if (origLawId === 'LAW_SUPREME_EXECUTIVE_CONSOLIDATION') {
        bill.lawId = 'LAW_INTERNAL_SECURITY_CYBER'; // avoids the legacy +45 direct coalitionSeats write inside switch(bill.lawId)!
      }
      const res = _origEnactBillV260(world, stateId, bill, r);
      bill.lawId = origLawId;

      // Overwrite bill.yesVotes / noVotes with exact party seat votes
      bill.yesVotes = yesVotes;
      bill.noVotes = noVotes;
      bill.partyVotes = voteCalc.partyVotes;
      if (st.parliament) {
        st.parliament.lastBillPassed = `${bill.titleTh} (${yesVotes}:${noVotes} เสียง)`;
      }

      if (ruling) {
        if (!ruling.record) ruling.record = { billsProposedIds: [], billsPassedIds: [], billsBlockedIds: [] };
        if (!ruling.record.billsPassedIds.includes(bill.id)) ruling.record.billsPassedIds.push(bill.id);
      }

      // P8.3 Constitutional laws handled via party layer
      if (origLawId === 'LAW_SUPREME_EXECUTIVE_CONSOLIDATION') {
        if (st.politicalPressures) st.politicalPressures.militaryInfluence = clamp((st.politicalPressures.militaryInfluence || 50) + 12, 10, 98);
        st.regimeCategory = st.regimeCategory === 'Military_Junta' ? 'Military_Junta' : 'Authoritarian';
        if (st.legislationV230) st.legislationV230.regimePowerStructure = st.regimeCategory;
        st.governmentType = 'อำนาจนิยมฝ่ายบริหารเบ็ดเสร็จ (Consolidated Executive Directorate)';
        if (st.partySystemV260) {
          st.partySystemV260.electionIntegrity = clamp((st.partySystemV260.electionIntegrity || 60) - 8, 5, 100);
          st.partySystemV260.electoralSystem = 'MANAGED';
        }
        if (st.democracyState) {
          st.democracyState.frozenByConsolidationV260 = true;
        }
        // Ban 1-2 strongest opposition parties via banPartyV260 (P4.4 path)
        const oppList = getActivePartiesOfStateV260(world, st.id, false)
          .filter((p) => p.status !== 'RULING')
          .sort((a, b) => (b.seats || 0) - (a.seats || 0))
          .slice(0, 2);
        oppList.forEach((op) => {
          banPartyV260(world, op.id, { reason: `บังคับใช้ "${bill.titleTh}" รวบอำนาจบริหาร`, rng: r });
        });
      } else if (origLawId === 'LAW_CONSTITUTIONAL_DEMILITARIZATION') {
        if (st.partySystemV260) {
          st.partySystemV260.electionIntegrity = clamp((st.partySystemV260.electionIntegrity || 70) + 6, 10, 98);
          if (st.partySystemV260.electoralSystem === 'MANAGED' || st.partySystemV260.electoralSystem === 'APPOINTED') {
            st.partySystemV260.electoralSystem = 'PR';
          }
        }
        getActivePartiesOfStateV260(world, st.id, true).forEach((p) => {
          if (p.archetype === 'MILITARY_BACKED' || (p.links?.militaryBackerIds || []).length > 0) {
            p.links.militaryBackerIds = [];
            p.funding.totalB = +((p.funding?.totalB || 0.05) * 0.60).toFixed(4);
            p.cohesion = clamp((p.cohesion || 70) - 15, 5, 100);
          }
        });
      }

      // P8.4b Winners and losers by archetype
      const wlSpec = LAW_WINNERS_LOSERS_V260[origLawId];
      if (wlSpec) {
        let biggestWinner = null;
        let biggestLoser = null;
        getActivePartiesOfStateV260(world, st.id, false).forEach((p) => {
          if (wlSpec.winners.includes(p.archetype)) {
            p.popularity = clamp((p.popularity || 20) + wlSpec.popDeltaWin, 1, 98);
            p._lawElectionBonusV260 = clamp((p._lawElectionBonusV260 || 0) + 2, -10, 12);
            if (wlSpec.fundMultWin) p.funding.totalB = +((p.funding?.totalB || 0.05) * wlSpec.fundMultWin).toFixed(4);
            if (!biggestWinner || (p.seats || 0) > (biggestWinner.seats || 0)) biggestWinner = p;
          } else if (wlSpec.losers.includes(p.archetype)) {
            p.popularity = clamp((p.popularity || 20) + wlSpec.popDeltaLose, 1, 98);
            p._lawElectionBonusV260 = clamp((p._lawElectionBonusV260 || 0) - 2, -10, 12);
            if (wlSpec.fundMultLose) p.funding.totalB = +((p.funding?.totalB || 0.05) * wlSpec.fundMultLose).toFixed(4);
            if (!biggestLoser || (p.seats || 0) > (biggestLoser.seats || 0)) biggestLoser = p;
          }
        });
        if (biggestWinner || biggestLoser) {
          const wParty = biggestWinner || ruling;
          const lParty = biggestLoser || parties.find((x) => x.id !== (wParty && wParty.id)) || wParty;
          const wlChron = `⚖️📊 [ผลกระทบกฎหมายต่อพรรคการเมืองใน ${shortNameTh(st)}] หลังการประกาศใช้ "${bill.titleTh}" พรรคที่ได้อานิสงส์สูงสุดคือ "${wParty ? wParty.name : 'พรรครัฐบาล'}" (คะแนนนิยม +${wlSpec.popDeltaWin} จุด) ขณะที่พรรคที่เสียเปรียบคือ "${lParty ? lParty.name : 'พรรคฝ่ายค้าน'}" (${wlSpec.popDeltaLose} จุด)!`;
          addChronicle(world, 'PARTY', wlChron, st.id, {
            personId: wParty ? wParty.leaderId : null,
            partyId: wParty ? wParty.id : null,
            billId: bill.id,
            subKind: 'LAW_WINNERS_LOSERS'
          });
        }
      }

      // P8.8 Scandal link: passing MONOPOLY / DEREGULATION / NATIONALIZE raises CONFLICT_OF_INTEREST spawn chance (x1.6 for 120 ticks) when fundingShare from company >= 25%
      if (['LAW_STATE_MONOPOLY_PROTECTION', 'LAW_CORPORATE_DEREGULATION_SEZ', 'LAW_NATIONALIZE_RARE_EARTH_ENERGY'].includes(origLawId) && ruling) {
        const compSum = (ruling.funding?.sources || []).filter((s) => s.kind === 'COMPANY').reduce((a, b) => a + (b.shareB || 0), 0);
        const ratio = compSum / Math.max(0.001, ruling.funding?.totalB || 0.05);
        if (ratio >= 0.25) {
          st._conflictScandalBoostUntilTickV260 = (world.tick || 0) + 120;
          st._conflictScandalMultV260 = 1.6;
        }
      }

      // Always call syncLegacyParliamentV260 so coalitionSeats + oppositionSeats === totalSeats
      syncLegacyPoliticsV260(world, st.id);
      return res;
    };
  }

  // P8.4 Wrap executeLoserRetaliationV230 so all 11 loserRetaliationType values reach parties/houses/companies
  if (typeof executeLoserRetaliationV230 === 'function') {
    const _origExecuteRetaliationV260 = executeLoserRetaliationV230;
    executeLoserRetaliationV230 = function (world, stateId, sourceObj, rngInstance = null) {
      ensurePartiesV260(world);
      const st = resolveStateObjV230(world, stateId);
      const retType = (sourceObj && sourceObj.loserRetaliationType) || 'CORP_CAPITAL_FLIGHT_OR_OPP_FUNDING';

      // Save party seats before original runs so original's direct st.parliament.coalitionSeats -= walkoutSeats is routed via party seats
      const retObj = _origExecuteRetaliationV260(world, stateId, sourceObj, rngInstance);
      if (!st || !retObj) return retObj;

      const rng = rngInstance || new SeededRNG(((world.seed || 2026) + (world.tick || 1) * 1483 + hashStr(st.id + retType)) >>> 0);
      const parties = getActivePartiesOfStateV260(world, st.id, true);
      const ruling = parties.find((p) => p.status === 'RULING') || parties[0];
      const oppMain = parties.filter((p) => p.status === 'OPPOSITION').sort((a, b) => (b.seats || 0) - (a.seats || 0))[0] || parties[parties.length - 1];
      const coalJunior = parties.find((p) => p.status === 'COALITION_PARTNER') || ruling;
      const milParty = parties.find((p) => p.archetype === 'MILITARY_BACKED') || oppMain || ruling;

      const partyEffects = {
        retaliationType: retType,
        affectedPartyIds: [],
        changes: []
      };

      if (retType === 'NPC_GENERAL_COUP_PLOT') {
        const backerIds = (milParty && milParty.links?.militaryBackerIds?.length > 0)
          ? milParty.links.militaryBackerIds
          : [st.positions?.SUPREME_COMMANDER, st.positions?.ARMY_CHIEF, st.positions?.DEFENSE_MINISTER].filter(Boolean);
        backerIds.forEach((gid) => {
          const gen = world.npcs[gid];
          if (gen && gen.alive) {
            gen.coupReadiness = clamp((gen.coupReadiness || 25) + 8, 0, 100);
          }
        });
        if (milParty) {
          milParty.popularity = clamp((milParty.popularity || 20) + 3, 1, 98);
          partyEffects.affectedPartyIds.push(milParty.id);
          partyEffects.changes.push(`${milParty.name} ความนิยม +3, นายพลหนุนหลัง coupReadiness +8`);
        }
      } else if (retType === 'NPC_GOVERNOR_TAX_BOYCOTT') {
        const cities = stateCities(world, st.id);
        const targetCity = cities.find((c) => !c.isCapital) || cities[0];
        if (targetCity && targetCity.regionalPolitics) {
          const rp = targetCity.regionalPolitics;
          if (rp.regionalParliament) {
            rp.regionalParliament.localSupportPct = clamp((rp.regionalParliament.localSupportPct || 60) + 5, 10, 99);
          }
          const govParty = (rp.governorPartyId && world.partyV260.parties[rp.governorPartyId]) || oppMain;
          if (govParty) {
            govParty.popularity = clamp((govParty.popularity || 20) + 5, 1, 98);
            partyEffects.affectedPartyIds.push(govParty.id);
            partyEffects.changes.push(`${govParty.name} คะแนนนิยมในเมือง +5, โอกาสเกิดพรรคภูมิภาค x2 นาน 180 วัน`);
          }
        }
        st._regionalSpawnBoostUntilTickV260 = (world.tick || 0) + 180;
      } else if (
        retType === 'NPC_OPPOSITION_SURGE' ||
        retType === 'NPC_COALITION_REBEL_OR_LABOR_STRIKE' ||
        retType === 'NPC_YOUTH_PROTEST_AND_COALITION_SPLIT'
      ) {
        if (oppMain) {
          oppMain.popularity = clamp((oppMain.popularity || 20) + 4, 1, 98);
          partyEffects.affectedPartyIds.push(oppMain.id);
          partyEffects.changes.push(`${oppMain.name} คะแนนนิยม +4`);
        }
        if (retType === 'NPC_COALITION_REBEL_OR_LABOR_STRIKE' || retType === 'NPC_YOUTH_PROTEST_AND_COALITION_SPLIT') {
          if (coalJunior) {
            coalJunior.cohesion = clamp((coalJunior.cohesion || 70) - 12, 5, 100);
            partyEffects.affectedPartyIds.push(coalJunior.id);
          }
          const coal = (world.partyV260.coalitions || []).find((c) => c.stateId === st.id);
          if (coal) coal.stability = clamp((coal.stability || 65) - 8, 5, 98);
          if (st.democracyState) {
            st.democracyState.coalitionStability = clamp((st.democracyState.coalitionStability || 65) - 8, 5, 98);
          }
          partyEffects.changes.push(`เอกภาพพรรคร่วม -12, เสถียรภาพรัฐบาลผสม -8`);
        }
      } else if (retType.startsWith('CORP_')) {
        const cutRatio = rng.int(30, 60) / 100;
        if (ruling) {
          const cutAmt = +((ruling.funding?.totalB || 0.05) * cutRatio).toFixed(4);
          ruling.funding.totalB = +(Math.max(0.005, (ruling.funding?.totalB || 0.05) - cutAmt)).toFixed(4);
          partyEffects.affectedPartyIds.push(ruling.id);
          if (oppMain && oppMain.id !== ruling.id) {
            oppMain.funding.totalB = +((oppMain.funding?.totalB || 0.05) + cutAmt).toFixed(4);
            partyEffects.affectedPartyIds.push(oppMain.id);
          }
          partyEffects.changes.push(`กลุ่มทุนตัดเงินหนุน ${ruling.name} ลง ${Math.round(cutRatio * 100)}% และโยกไปหนุน ${oppMain ? oppMain.name : 'ฝ่ายค้าน'}`);
        }
      } else if (retType.startsWith('FOREIGN_')) {
        const powers = Object.values(world.states).filter((s) => s && !s.isExiled && s.id !== st.id && (s.gdpB || 0) > 800);
        const fSponsor = powers[0] || Object.values(world.states).find((s) => s && s.id !== st.id);
        if (fSponsor && oppMain && (sourceObj?._forceForeignInterfereV260 || rng.chance(0.45))) {
          interfereInElectionV260(world, fSponsor.id, st.id, oppMain.id, 'FUNDING', { rng });
          partyEffects.affectedPartyIds.push(oppMain.id);
          partyEffects.changes.push(`${shortNameTh(fSponsor)} ส่งเงินหนุนแทรกแซงการเลือกตั้งให้แก่ ${oppMain.name}`);
        } else if (oppMain) {
          oppMain.popularity = clamp((oppMain.popularity || 20) + 2, 1, 98);
          partyEffects.affectedPartyIds.push(oppMain.id);
          partyEffects.changes.push(`แรงกดดันต่างชาติหนุนคะแนนนิยม ${oppMain.name} +2`);
        }
        if (retType === 'FOREIGN_AND_UNDERGROUND_RESISTANCE' && st.underground) {
          st.underground.dissidentNetwork = clamp((st.underground.dissidentNetwork || 20) + 6, 0, 100);
          partyEffects.changes.push('เครือข่ายใต้ดิน dissidentNetwork +6');
        }
      }

      retObj.partyEffectsV260 = partyEffects;
      syncLegacyPoliticsV260(world, st.id);
      return retObj;
    };
  }

  // P8.5 Wrap issueExecutivePolicyV230
  if (typeof issueExecutivePolicyV230 === 'function') {
    const _origIssueExecPolicyV260 = issueExecutivePolicyV230;
    issueExecutivePolicyV230 = function (world, stateId, policyTypeId = null, opts = {}) {
      ensurePartiesV260(world);
      const res = _origIssueExecPolicyV260(world, stateId, policyTypeId, opts);
      if (!res || !res.ok || !res.policy) return res;

      const st = resolveStateObjV230(world, stateId);
      if (!st) return res;
      const rng = new SeededRNG(((world.seed || 2026) + (world.tick || 1) * 1511 + hashStr(st.id)) >>> 0);

      const parties = getActivePartiesOfStateV260(world, st.id, false);
      const ruling = parties.find((p) => p.status === 'RULING') || parties[0];
      const oppMain = parties.filter((p) => p.status === 'OPPOSITION').sort((a, b) => (b.popularity || 0) - (a.popularity || 0))[0];

      if (ruling) {
        res.policy.issuerPartyId = ruling.id;
        res.policy.issuerPartyName = ruling.name;
      } else {
        res.policy.issuerPartyId = 'PTY_RULING';
      }

      const isAuth = isAuthRegimeV260(st);
      if (!isAuth) {
        const totalSeats = (st.parliament && st.parliament.totalSeats) || 500;
        const coalSeats = st.parliament?.coalitionSeats ?? 250;
        const oppLeadsBy8 = oppMain && ruling && ((oppMain.popularity || 0) - (ruling.popularity || 0) >= 8);
        if (coalSeats < totalSeats / 2 || oppLeadsBy8) {
          if (st.democracyState) {
            st.democracyState.coalitionStability = clamp((st.democracyState.coalitionStability || 65) - 6, 5, 98);
          }
          const coal = (world.partyV260.coalitions || []).find((c) => c.stateId === st.id);
          if (coal) coal.stability = clamp((coal.stability || 65) - 6, 5, 98);
          if (ruling) {
            ruling.scandalLoad = clamp((ruling.scandalLoad || 0) + 5, 0, 100);
          }
          if (rng.chance(0.12) && typeof spawnScandalV240 === 'function') {
            spawnScandalV240(world, st.id, 'ABUSE_OF_POWER', { subjectId: ruling ? ruling.leaderId : undefined, rng });
          }
        }
      } else {
        if (st.partySystemV260) {
          st.partySystemV260.electionIntegrity = clamp((st.partySystemV260.electionIntegrity ?? 30) - 1, 5, 100);
        }
        if (st.underground) {
          st.underground.dissidentNetwork = clamp((st.underground.dissidentNetwork ?? 20) + 1, 0, 100);
        }
      }

      syncLegacyPoliticsV260(world, st.id);
      return res;
    };
  }

  // P8.6 Wrap triggerRegimeChangeStruggleV230
  if (typeof triggerRegimeChangeStruggleV230 === 'function') {
    const _origTriggerRegimeStruggleV260 = triggerRegimeChangeStruggleV230;
    triggerRegimeChangeStruggleV230 = function (world, stateId, targetRegime = null, sponsorId = null, rng = null) {
      ensurePartiesV260(world);
      const st = resolveStateObjV230(world, stateId);
      const partiesBefore = st ? getActivePartiesOfStateV260(world, st.id, true) : [];
      const insurgentParty = partiesBefore
        .filter((p) => p.status !== 'RULING')
        .sort((a, b) => ((b.radicalism || 40) + (b.popularity || 20)) - ((a.radicalism || 40) + (a.popularity || 20)))[0];
      const oldRuling = partiesBefore.find((p) => p.status === 'RULING');

      const res = _origTriggerRegimeStruggleV260(world, stateId, targetRegime, sponsorId, rng);
      if (!res || !res.ok || !st) return res;

      const r = rng || new SeededRNG(((world.seed || 2026) + (world.tick || 1) * 1543 + hashStr(st.id)) >>> 0);
      st.partySystemV260 = {
        ...computeDefaultPartySystemForStateV260(world, st),
        nextElectionYear: st.partySystemV260?.nextElectionYear || ((world.year || 2026) + 3)
      };

      if (insurgentParty) {
        if (insurgentParty.status === 'BANNED' || insurgentParty.status === 'UNDERGROUND') {
          unbanPartyV260(world, insurgentParty.id, r);
        }
        insurgentParty.status = 'RULING';
        insurgentParty.seats = Math.round(((st.parliament && st.parliament.totalSeats) || 500) * 0.56);
        insurgentParty.voteShare = 56;
        st.partySystemV260.rulingPartyId = insurgentParty.id;
      }
      if (oldRuling && insurgentParty && oldRuling.id !== insurgentParty.id) {
        if (isAuthRegimeV260(st)) {
          banPartyV260(world, oldRuling.id, { reason: 'พ่ายแพ้ในการชิงระบอบการปกครอง', rng: r });
        } else {
          oldRuling.status = 'OPPOSITION';
          oldRuling.seats = Math.round(((st.parliament && st.parliament.totalSeats) || 500) * 0.24);
          oldRuling.voteShare = 24;
        }
      }

      if (res.shift) {
        res.shift.insurgentPartyId = insurgentParty ? insurgentParty.id : null;
        res.shift.incumbentPartyId = oldRuling ? oldRuling.id : null;
      }
      syncLegacyPoliticsV260(world, st.id);
      return res;
    };
  }

  // P8.9 Helper & Wrapper for anti-immigration party names in Round-1 migration review (Test D21)
  function getAntiImmigrationPartyForStateV260(world, stateId, rngInstance = null) {
    if (world && world.partyV260 && stateId) {
      const parties = getActivePartiesOfStateV260(world, stateId, true);
      const match = parties.find((p) => p.archetype === 'NATIONALIST_POPULIST' || (p.archetype === 'SINGLE_ISSUE' && p.issueFocus === 'migration-restriction')) ||
        parties.find((p) => p.platform?.migrationStance === 'CLOSED');
      if (match) return match;
    }
    const r = rngInstance || new SeededRNG(2026);
    return { id: null, name: r.pick(ANTI_IMMIGRATION_PARTIES_V230) };
  }

  if (typeof runMigrationPolicyReviewV230 === 'function') {
    const _origRunMigrationPolicyReviewV260 = runMigrationPolicyReviewV230;
    runMigrationPolicyReviewV230 = function (world, rngInstance = null) {
      if (!world || !world.states) return _origRunMigrationPolicyReviewV260(world, rngInstance);
      ensurePartiesV260(world);
      const preChronLen = Array.isArray(world.chronicle) ? world.chronicle.length : 0;
      const res = _origRunMigrationPolicyReviewV260(world, rngInstance);

      // Replace any generic ANTI_IMMIGRATION_PARTIES_V230 string in newly added MIGRATION chronicle entries with the state's real NATIONALIST_POPULIST / anti-immigration party name, and sync seats via party layer!
      const addedCount = (world.chronicle ? world.chronicle.length : 0) - preChronLen;
      for (let i = 0; i < addedCount; i++) {
        const ev = world.chronicle[i];
        if (ev && ev.category === 'MIGRATION' && ev.stateId && world.states[ev.stateId]) {
          const realParty = getAntiImmigrationPartyForStateV260(world, ev.stateId);
          if (realParty && realParty.id) {
            ANTI_IMMIGRATION_PARTIES_V230.forEach((genericName) => {
              if (ev.text && ev.text.includes(genericName)) {
                ev.text = ev.text.split(genericName).join(realParty.name);
                ev.rawText = ev.text;
                ev.partyId = realParty.id;
                realParty.seats = (realParty.seats || 0) + 2;
              }
            });
          }
          syncLegacyPoliticsV260(world, ev.stateId);
        }
      }
      return res;
    };
  }


