  function formatJianghuDateV110(worldOrDateStr, opts = {}) {
    let year = 2026, month = 1, day = 1;
    if (typeof worldOrDateStr === 'string') {
      const m = worldOrDateStr.match(/^(d{4})-(d{2})-(d{2})/);
      if (m) {
        year = parseInt(m[1], 10);
        month = parseInt(m[2], 10);
        day = parseInt(m[3], 10);
      } else if (worldOrDateStr.includes('ปีฟ้าดิน')) {
        return worldOrDateStr;
      }
    } else if (worldOrDateStr && typeof worldOrDateStr === 'object') {
      year = worldOrDateStr.year || 2026;
      const doy = worldOrDateStr.dayOfYear || ((worldOrDateStr.tick || 0) % 365) + 1;
      month = Math.min(12, Math.max(1, Math.ceil(doy / 30.42)));
      day = Math.max(1, Math.min(30, Math.round(doy - (month - 1) * 30.42) || 1));
    } else if (typeof worldOrDateStr === 'number') {
      year = worldOrDateStr;
    }
    const jYear = year >= 1800 ? (year - 742) : year;
    const jYearFmt = jYear.toLocaleString('en-US');
    const mName = JIANGHU_MONTH_NAMES_V110[(month - 1) % 12] || 'เดือนหนึ่ง';
    const sIdx = Math.floor(((month - 1) % 12) / 3);
    const sObj = JIANGHU_SEASONS_V110[sIdx] || JIANGHU_SEASONS_V110[0];
    if (opts && opts.yearOnly) return `ปีฟ้าดิน ${jYearFmt}`;
    if (opts && opts.withFestival && (day === 1 || day === 15)) {
      return `ปีฟ้าดิน ${jYearFmt} ${mName} ${sObj.nameTh} (${sObj.festivalTh})`;
    }
    if (opts && opts.short) {
      return `ปีฟ้าดิน ${jYearFmt} ${mName} ${sObj.nameTh}`;
    }
    return `ปีฟ้าดิน ${jYearFmt} ${mName} วันที่ ${day} ${sObj.nameTh}`;
  }

