    WIND: { WOOD_LIFE: 1.15, FIRE: 1.14, EARTH_METAL: 0.88 },
    LIGHT_YANG: { YIN_SHADOW: 1.35, BLOOD_DEMON: 1.38, WATER_ICE: 1.08 },
    YIN_SHADOW: { LIGHT_YANG: 0.78, LIGHTNING: 0.82, ASTRAL: 1.16 },
