    if (def.sourceRestrictionPolicy === 'CONTRACTED_BEAST_REQUIRED' && actor) {
      const beast = actor.jianghu?.contractBeast;
      if (!beast) {
        return { ok: false, code: 'MISSING_CONTRACT_BEAST', reason: 'ต้องมีสัตว์อสูรคู่สัญญาจึงจะใช้ความสามารถพันธสัญญาได้' };
      }
      if (num(beast.fatigueV190, 0) >= 85) {
        return { ok: false, code: 'BEAST_EXHAUSTED', reason: 'สัตว์อสูรคู่สัญญาอ่อนล้าเกินกว่าจะส่งปราณประสานได้' };
      }
      if (beast.activeDutyV190 && beast.activeDutyV190.type === 'FLYING_MOUNT' && beast.activeDutyV190.untilTick > num(w.tick, 0)) {
        return { ok: false, code: 'BEAST_DUTY_CONFLICT', reason: 'สัตว์อสูรกำลังทำหน้าที่พาหนะเดินทาง ไม่สามารถแยกไปเป็นตัวส่งปราณอีกพื้นที่พร้อมกันได้' };
      }
    }

