    if ((def.id === 'EFX_MASS_VITAL_HEAL' || def.id === 'EFX_HEALING_RELAY') && command.targetId && w.npcs?.[command.targetId]) {
      if (!w.npcs[command.targetId].alive) {
        return { ok: false, code: 'CORPSE_CANNOT_BE_HEALED', reason: 'ไม่สามารถรักษาผู้ที่เสียชีวิตแล้วได้' };
      }
    }

