(function (root, factory) {
  'use strict';
  const api = factory();
  if (typeof module === 'object' && module.exports) module.exports = api;
  root.JianghuTechniques190Engine = api;
})(typeof globalThis !== 'undefined' ? globalThis : this, function () {
  'use strict';

  const Core = (typeof module === 'object' && module.exports)
    ? require('./effects190_core.js')
    : (globalThis.JianghuEffects190Core || {});
  const T190 = (typeof module === 'object' && module.exports)
    ? require('../data/jianghu_techniques190_data.js')
    : (globalThis.JianghuTechniques190Data || {});
  const Doc190 = (typeof module === 'object' && module.exports)
    ? require('../data/jianghu_sect_doctrines190_data.js')
    : (globalThis.JianghuSectDoctrines190Data || {});

  const num = (v, d = 0) => (typeof v === 'number' && Number.isFinite(v) ? v : d);
  const clamp = (v, min = 0, max = 100) => Math.max(min, Math.min(max, num(v, min)));
  const clone = (o) => (o === undefined ? undefined : JSON.parse(JSON.stringify(o)));

  // 7-Stage Knowledge Progression Constants (Section 13)
  const KNOWLEDGE_STAGES = Object.freeze({
    NONE: 0,
    HEARD_RUMOR: 1,         // 1. เคยได้ยินชื่อ
    KNOWN_CLUE: 2,          // 2. รู้ตำแหน่งแหล่งเรียน/เบาะแส
    HOLDS_SCROLL: 3,        // 3. ถือหรือเข้าถึงตำราจริง (ถือคัมภีร์ != รู้วิชา!)
    AUTHORIZED_RIGHT: 4,    // 4. มีสิทธิศึกษา
    COMPREHENDED_BASIC: 5,  // 5. ศึกษาจนเข้าใจขั้นพื้นฐาน
    PRACTICED_USABLE: 6,    // 6. ฝึกจนร่าย/ใช้ได้จริง
    MASTERED_TEACHABLE: 7   // 7. เชี่ยวชาญ/ประยุกต์/ถ่ายทอดได้
  });

  const DOCTRINE_MAP = new Map((Doc190.SECT_DOCTRINES_40 || []).map((d) => [d.sectId, d]));

  function getAllTechniquesCatalogV190(E = null) {
    const baseArts = E?.MARTIAL_ARTS_CATALOG || [];
    const newArts = T190.NEW_TECHNIQUES_240 || [];
    const seen = new Set(baseArts.map((a) => a.id));
    const combined = [...baseArts];
    for (const na of newArts) {
      if (!seen.has(na.id)) {
        seen.add(na.id);
        combined.push(na);
      }
    }
    return combined;
  }

  function ensureTechniqueKnowledgeSystemV190(w, E = null, opts = {}) {
    if (!w || !w.jianghu) return null;
    if (opts.readOnly && w.jianghu.techniqueRegistryV190) {
      return w.jianghu.techniqueRegistryV190;
    }
    if (!w.jianghu.techniqueRegistryV190) {
      const reg = {
        version: '1.9.0',
        sequence: 0,
        artsById: {},
        scrollInstances: {},
        gratitudeRightsGranted: [],
        teachingHistory: [],
        recoveryHistory: [],
        metrics: {
          totalStudied: 0,
          totalPracticedToUsable: 0,
          totalTaught: 0,
          totalGratitudeTransmissions: 0,
          totalLost: 0,
          totalRecovered: 0,
          totalInventedWhitelisted: 0
        }
      };

      // Register all legacy (71) and new (240) martial arts in the world registry
      const allCatalog = getAllTechniquesCatalogV190(E);
      for (const art of allCatalog) {
        const originSects = art.acquisitionSource?.originSectIds
          || Object.values(w.states || {}).filter((s) => s.jianghu?.primaryPath === art.path).slice(0, 2).map((s) => s.id);
        const subsiteId = art.acquisitionSource?.subsiteId || 'SITE_SUB_001_01';
        const transPolicy = art.acquisitionSource?.transmissionPolicy || (art.tier >= 5 ? 'LINEAGE_RESTRICTED' : 'SECT_CURRICULUM');
        const scrollHolders = originSects.map((sid) => ({ holderType: 'SECT', holderId: sid, count: 1 }));

        reg.artsById[art.id] = {
          artId: art.id,
          nameTh: art.nameTh,
          category: art.category,
          path: art.path,
          tier: art.tier || 3,
          element: Core.normalizeElementV190(art.element),
          transmissionPolicy: transPolicy,
          originSectIds: originSects.slice(),
          archiveSubsiteId: subsiteId,
          status: 'ACTIVE', // ACTIVE | LOST_ARCHIVED
          scrollHolders,
          practitioners: [],
          teachers: []
        };
      }

      // Seed initial NPC knowledge ONLY for their equipped arts & sect curriculum elders (Section 11: catalog is NOT global free knowledge!)
      for (const npc of Object.values(w.npcs || {})) {
        if (!npc || !npc.alive || !npc.jianghu) continue;
        const j = npc.jianghu;
        j.knowledgeV190 = j.knowledgeV190 || {};
        const equipped = [j.mantraId, j.techniqueId, j.lightnessId, j.auxiliaryId, j.forbiddenId].filter(Boolean);
        const isElderOrHead = npc.positionId === 'HEAD_OF_STATE' || ['ELDER', 'SUPREME_ELDER', 'GRAND_COMMANDER'].includes(npc.positionId);

        for (const aid of equipped) {
          const stg = isElderOrHead ? KNOWLEDGE_STAGES.MASTERED_TEACHABLE : KNOWLEDGE_STAGES.PRACTICED_USABLE;
          j.knowledgeV190[aid] = {
            artId: aid,
            stage: stg,
            mastery: clamp(num(j.artMasteryV150?.[aid], isElderOrHead ? 80 : 45), 20, 100),
            authorizedBy: 'INITIAL_EQUIPPED',
            updatedTick: 0
          };
          if (reg.artsById[aid]) {
            reg.artsById[aid].practitioners.push(npc.id);
            if (stg >= KNOWLEDGE_STAGES.MASTERED_TEACHABLE) reg.artsById[aid].teachers.push(npc.id);
          }
        }

        // Sect heads & elders also know their sect's new v1.9.0 signature & restricted arts so every art has real teachers/knowers
        if (isElderOrHead && npc.stateId && DOCTRINE_MAP.has(npc.stateId)) {
          const doc = DOCTRINE_MAP.get(npc.stateId);
          for (const aid of [...(doc.signatureArtIds || []), ...(doc.restrictedSecretArtIds || [])]) {
            if (!reg.artsById[aid]) continue;
            j.knowledgeV190[aid] = {
              artId: aid,
              stage: KNOWLEDGE_STAGES.MASTERED_TEACHABLE,
              mastery: 82,
              authorizedBy: `SECT_LINEAGE:${npc.stateId}`,
              updatedTick: 0
            };
            if (!reg.artsById[aid].practitioners.includes(npc.id)) reg.artsById[aid].practitioners.push(npc.id);
            if (!reg.artsById[aid].teachers.includes(npc.id)) reg.artsById[aid].teachers.push(npc.id);
          }
        }
      }

      // Ensure every one of the 240 new arts has at least 1 living knower/scroll in its origin sect
      for (const art of T190.NEW_TECHNIQUES_240 || []) {
        const rec = reg.artsById[art.id];
        if (!rec || rec.practitioners.length > 0) continue;
        const originSect = rec.originSectIds[0] || 'TH';
        const candidate = Object.values(w.npcs || {}).find((n) => n?.alive && n.stateId === originSect && n.jianghu)
          || Object.values(w.npcs || {}).find((n) => n?.alive && n.jianghu);
        if (candidate) {
          candidate.jianghu.knowledgeV190 = candidate.jianghu.knowledgeV190 || {};
          candidate.jianghu.knowledgeV190[art.id] = {
            artId: art.id,
            stage: KNOWLEDGE_STAGES.MASTERED_TEACHABLE,
            mastery: 78,
            authorizedBy: `ORIGIN_KEEPER:${originSect}`,
            updatedTick: 0
          };
          rec.practitioners.push(candidate.id);
          rec.teachers.push(candidate.id);
        }
      }

      w.jianghu.techniqueRegistryV190 = reg;
    }
    return w.jianghu.techniqueRegistryV190;
  }

  function getNpcArtKnowledgeStageV190(w, npcOrId, artId) {
    const npc = typeof npcOrId === 'string' ? w?.npcs?.[npcOrId] : npcOrId;
    if (!npc || !npc.jianghu || !artId) return KNOWLEDGE_STAGES.NONE;
    const entry = npc.jianghu.knowledgeV190?.[artId];
    if (entry) return num(entry.stage, KNOWLEDGE_STAGES.NONE);
    const equipped = [npc.jianghu.mantraId, npc.jianghu.techniqueId, npc.jianghu.lightnessId, npc.jianghu.auxiliaryId, npc.jianghu.forbiddenId];
    if (equipped.includes(artId)) return KNOWLEDGE_STAGES.PRACTICED_USABLE;
    return KNOWLEDGE_STAGES.NONE;
  }

  function canNpcCastTechniqueV190(w, npcOrId, artId) {
    const npc = typeof npcOrId === 'string' ? w?.npcs?.[npcOrId] : npcOrId;
    if (!npc || !npc.alive || !artId) return { ok: false, reason: 'ผู้ฝึกตนไม่พร้อมใช้วิชา' };
    const reg = ensureTechniqueKnowledgeSystemV190(w, null, { readOnly: true });
    const artRec = reg?.artsById?.[artId];
    if (artRec && artRec.status === 'LOST_ARCHIVED' && getNpcArtKnowledgeStageV190(w, npc, artId) < KNOWLEDGE_STAGES.PRACTICED_USABLE) {
      return { ok: false, code: 'ART_LOST', reason: 'วิชานี้สูญหายไปแล้ว ต้องค้นคืนคัมภีร์จากโบราณสถานก่อน' };
    }
    const stg = getNpcArtKnowledgeStageV190(w, npc, artId);
    if (stg < KNOWLEDGE_STAGES.PRACTICED_USABLE) {
      return {
        ok: false,
        code: 'INSUFFICIENT_KNOWLEDGE_STAGE',
        stage: stg,
        reason: stg === KNOWLEDGE_STAGES.HOLDS_SCROLL
          ? 'เพียงถือคัมภีร์ไว้ในครอบครอง ยังไม่ได้ศึกษาและฝึกฝนจนใช้งานได้จริง'
          : `ระดับความเข้าใจวิชานี้ยังไม่ถึงขั้นใช้งานจริง (ขั้นปัจจุบัน ${stg}/6)`
      };
    }
    return { ok: true, stage: stg };
  }

  // Advance knowledge progression: Scroll/Right -> Comprehended -> Practiced Usable -> Mastered Teachable
  function studyOrPracticeTechniqueV190(w, npcOrId, artId, opts = {}, E = null) {
    const npc = typeof npcOrId === 'string' ? w?.npcs?.[npcOrId] : npcOrId;
    if (!w || !npc || !npc.alive || !npc.jianghu) return { ok: false, reason: 'ผู้ฝึกตนไม่พร้อมศึกษาวิชา' };
    const reg = ensureTechniqueKnowledgeSystemV190(w, E);
    const artRec = reg.artsById[artId];
    if (!artRec) return { ok: false, reason: `ไม่พบวิชายุทธ์ ${artId} ในทำเนียบ` };
    if (artRec.status === 'LOST_ARCHIVED' && getNpcArtKnowledgeStageV190(w, npc, artId) < KNOWLEDGE_STAGES.HOLDS_SCROLL) {
      return { ok: false, code: 'ART_LOST_ARCHIVED', reason: 'วิชานี้สูญหายจากยุทธภพแล้ว ไม่สามารถเรียนจากแม่แบบเปล่าได้' };
    }

    const techDef = Core.NEW_TECH_MAP.get(artId) || (E?.MARTIAL_ARTS_CATALOG || []).find((a) => a.id === artId);
    const j = npc.jianghu;
    j.knowledgeV190 = j.knowledgeV190 || {};
    const cur = j.knowledgeV190[artId] ? {...j.knowledgeV190[artId]} : { artId, stage: KNOWLEDGE_STAGES.NONE, mastery: 0, authorizedBy: null, updatedTick: num(w.tick, 0) };

    // Check scroll access & rights if below AUTHORIZED_RIGHT
    const hasPersonalScroll = cur.stage >= KNOWLEDGE_STAGES.HOLDS_SCROLL || (artRec.scrollHolders || []).some((h) => h.holderType === 'NPC' && h.holderId === npc.id && h.count > 0);
    const hasSectScroll = npc.stateId && (artRec.scrollHolders || []).some((h) => h.holderType === 'SECT' && h.holderId === npc.stateId && h.count > 0);

    if (cur.stage < KNOWLEDGE_STAGES.AUTHORIZED_RIGHT) {
      if (!hasPersonalScroll && !hasSectScroll && !opts.teacherNpcId) {
        return { ok: false, code: 'NO_SCROLL_OR_TEACHER', reason: 'ไม่มีคัมภีร์ต้นฉบับหรืออาจารย์ผู้ถ่ายทอดในพื้นที่' };
      }
      if (artRec.transmissionPolicy === 'LINEAGE_RESTRICTED' && !cur.authorizedBy && !opts.authorizedByTeacher) {
        const doc = DOCTRINE_MAP.get(npc.stateId);
        const minMerit = num(doc?.curriculumPolicy?.meritRequiredForSecretArt, 65);
        const isAuthLeader = E?.hasSectAuthorityV161 ? E.hasSectAuthorityV161(w, npc, npc.stateId) : false;
        if (!isAuthLeader && num(npc.meritScore, 0) < minMerit) {
          return {
            ok: false,
            code: 'MISSING_LINEAGE_RIGHT',
            reason: `วิชาลับประจำสายสืบทอด ต้องมีคุณูปการสำนัก >= ${minMerit} หรือได้รับอนุญาตจากอาจารย์/หนี้บุญคุณช่วยชีวิต`
          };
        }
        cur.authorizedBy = `MERIT_OR_AUTHORITY:${npc.stateId}`;
      } else if (!cur.authorizedBy) {
        cur.authorizedBy = hasSectScroll ? `SECT_CURRICULUM:${npc.stateId}` : 'PERSONAL_SCROLL';
      }
      cur.stage = KNOWLEDGE_STAGES.AUTHORIZED_RIGHT;
    }

    // Deduct practice stone cost
    const stoneCost = Math.max(10, num(techDef?.prerequisites?.practiceCostStones, (artRec.tier || 3) * 14));
    if (!opts.free && E?.getSpiritStonesV140 && E.getSpiritStonesV140(npc) < stoneCost) {
      return { ok: false, code: 'INSUFFICIENT_STONES', reason: `หินวิญญาณไม่พอสำหรับฝึกฝนวิชา (${stoneCost} ก้อน)` };
    }
    if (!opts.free && E?.addSpiritStonesV140) {
      E.addSpiritStonesV140(npc, -stoneCost);
    }

    // Apply LEARNING_INSIGHT multiplier if active
    const insightInstances = Core.getActiveEffectsForTarget(w, npc.id, { effectId: 'EFX_LEARNING_INSIGHT' });
    const insightMult = insightInstances.length
      ? Core.computeStackedMagnitudeV190(insightInstances, 'masteryGainMultiplier', 'MULTIPLY_WITH_CAP', 1.75, 2)
      : 1.0;

    const baseGain = Math.round((18 + num(npc.aptitudes?.comprehension, 50) * 0.15) * insightMult);
    cur.mastery = clamp(num(cur.mastery, 0) + baseGain, 0, 100);
    cur.updatedTick = num(w.tick, 0);

    if (cur.stage === KNOWLEDGE_STAGES.AUTHORIZED_RIGHT) {
      cur.stage = KNOWLEDGE_STAGES.COMPREHENDED_BASIC;
      reg.metrics.totalStudied++;
    } else if (cur.stage === KNOWLEDGE_STAGES.COMPREHENDED_BASIC && cur.mastery >= 35) {
      cur.stage = KNOWLEDGE_STAGES.PRACTICED_USABLE;
      if (!artRec.practitioners.includes(npc.id)) artRec.practitioners.push(npc.id);
      reg.metrics.totalPracticedToUsable++;
    } else if (cur.stage === KNOWLEDGE_STAGES.PRACTICED_USABLE && cur.mastery >= 80) {
      cur.stage = KNOWLEDGE_STAGES.MASTERED_TEACHABLE;
      if (!artRec.teachers.includes(npc.id)) artRec.teachers.push(npc.id);
    }

    j.knowledgeV190[artId] = cur;
    j.artMasteryV150 = j.artMasteryV150 || {};
    j.artMasteryV150[artId] = cur.mastery;

    // Equip into appropriate slot if usable and stronger than current
    if (cur.stage >= KNOWLEDGE_STAGES.PRACTICED_USABLE && techDef) {
      const slot = techDef.slotType;
      if (slot === 'TECHNIQUE' && (!j.techniqueId || (techDef.tier || 3) >= 4)) {
        j.techniqueId = artId;
        j.techniqueNameTh = techDef.nameTh;
      } else if (slot === 'MANTRA' && !j.mantraId) {
        j.mantraId = artId;
        j.mantraNameTh = techDef.nameTh;
      } else if (slot === 'LIGHTNESS' && !j.lightnessId) {
        j.lightnessId = artId;
      } else if (slot === 'AUXILIARY' && !j.auxiliaryId) {
        j.auxiliaryId = artId;
      } else if (slot === 'FORBIDDEN' && !j.forbiddenId) {
        j.forbiddenId = artId;
      }
    }

    return {
      ok: true,
      artId,
      stage: cur.stage,
      mastery: cur.mastery,
      stoneCostSpent: opts.free ? 0 : stoneCost,
      insightBonusApplied: insightMult > 1.0
    };
  }

  // Teacher-Disciple Direct Transmission (requires both idle, alive, in same city, and trust/relationship)
  function teachTechniqueToDiscipleV190(w, teacherOrId, studentOrId, artId, opts = {}, E = null) {
    const teacher = typeof teacherOrId === 'string' ? w?.npcs?.[teacherOrId] : teacherOrId;
    const student = typeof studentOrId === 'string' ? w?.npcs?.[studentOrId] : studentOrId;
    if (!w || !teacher?.alive || !student?.alive || teacher.id === student.id) {
      return { ok: false, reason: 'ครูและศิษย์ต้องมีชีวิตและเป็นคนละคนกัน' };
    }
    const reg = ensureTechniqueKnowledgeSystemV190(w, E);
    const tStage = getNpcArtKnowledgeStageV190(w, teacher, artId);
    if (tStage < KNOWLEDGE_STAGES.MASTERED_TEACHABLE) {
      return { ok: false, code: 'TEACHER_NOT_MASTERED', reason: 'ผู้สอนยังไม่ได้ฝึกวิชานี้ถึงขั้นเชี่ยวชาญถ่ายทอดได้ (ขั้น 7)' };
    }

    const locT = E?.getEntityLocation ? E.getEntityLocation(w, teacher) : { kind: 'CITY', cityId: teacher.currentCityId };
    const locS = E?.getEntityLocation ? E.getEntityLocation(w, student) : { kind: 'CITY', cityId: student.currentCityId };
    if (locT.kind !== 'CITY' || locS.kind !== 'CITY' || locT.cityId !== locS.cityId) {
      return { ok: false, code: 'NOT_SAME_LOCATION', reason: 'ครูและศิษย์ต้องอยู่ในเมืองเดียวกันจริงขณะถ่ายทอดวิชา' };
    }

    if (!opts.ignoreBusy && (E?.isNpcBusyWithTaskV161?.(w, teacher, { ignoreSameDay: true }).busy || E?.isNpcBusyWithTaskV161?.(w, student, { ignoreSameDay: true }).busy)) {
      return { ok: false, code: 'BUSY_PARTICIPANTS', reason: 'ครูหรือศิษย์กำลังติดภารกิจอื่น' };
    }

    student.jianghu.knowledgeV190 = student.jianghu.knowledgeV190 || {};
    const cur = student.jianghu.knowledgeV190[artId] || {
      artId,
      stage: KNOWLEDGE_STAGES.AUTHORIZED_RIGHT,
      mastery: 25,
      authorizedBy: `TAUGHT_BY:${teacher.id}`,
      updatedTick: num(w.tick, 0)
    };
    cur.authorizedBy = `TAUGHT_BY:${teacher.id}`;
    cur.stage = Math.max(cur.stage, KNOWLEDGE_STAGES.COMPREHENDED_BASIC);
    cur.mastery = clamp(num(cur.mastery, 25) + 30, 35, 100);
    student.jianghu.knowledgeV190[artId] = cur;
    student.jianghu.artMasteryV150 = student.jianghu.artMasteryV150 || {};
    student.jianghu.artMasteryV150[artId] = cur.mastery;

    const artRec = reg.artsById[artId];
    if (artRec && !artRec.practitioners.includes(student.id)) {
      artRec.practitioners.push(student.id);
    }

    if (E?.reserveNpcTaskWindowV161 && !opts.ignoreBusy) {
      E.reserveNpcTaskWindowV161(w, teacher, 5, 'TEACH', `ถ่ายทอดวิชา ${artRec?.nameTh || artId} ให้ ${student.name}`);
      E.reserveNpcTaskWindowV161(w, student, 5, 'STUDY_SCRIPTURE', `รับการถ่ายทอดวิชา ${artRec?.nameTh || artId} จาก ${teacher.name}`);
    }

    reg.metrics.totalTaught++;
    reg.teachingHistory.unshift({
      tick: num(w.tick, 0),
      teacherId: teacher.id,
      studentId: student.id,
      artId,
      cityId: locT.cityId
    });
    if (reg.teachingHistory.length > 80) reg.teachingHistory.length = 80;

    return { ok: true, teacherId: teacher.id, studentId: student.id, artId, studentStage: cur.stage, studentMastery: cur.mastery };
  }

  // Creative Idea #7: Life-Saving Gratitude Secret Transmission (GRATITUDE_SECRET_TRANSMISSION)
  function grantGratitudeSecretRightV190(w, benefactorOrId, savedMasterOrId, reasonTh = 'ช่วยชีวิตและรักษาเส้นชีพจรปราณ', E = null) {
    const benefactor = typeof benefactorOrId === 'string' ? w?.npcs?.[benefactorOrId] : benefactorOrId;
    const master = typeof savedMasterOrId === 'string' ? w?.npcs?.[savedMasterOrId] : savedMasterOrId;
    if (!w || !benefactor?.alive || !master?.alive || benefactor.id === master.id) {
      return { ok: false, reason: 'ไม่พบผู้มีพระคุณหรือผู้รับการช่วยเหลือ' };
    }
    const reg = ensureTechniqueKnowledgeSystemV190(w, E);
    const masterArts = Object.values(master.jianghu?.knowledgeV190 || {})
      .filter((k) => k.stage >= KNOWLEDGE_STAGES.MASTERED_TEACHABLE)
      .map((k) => k.artId);
    const secretArtId = masterArts.find((id) => getNpcArtKnowledgeStageV190(w, benefactor, id) < KNOWLEDGE_STAGES.PRACTICED_USABLE)
      || master.jianghu?.techniqueId;
    if (!secretArtId || !reg.artsById[secretArtId]) {
      return { ok: false, reason: 'ผู้รับความช่วยเหลือไม่มีเคล็ดวิชาที่สามารถถ่ายทอดตอบแทนได้' };
    }

    benefactor.jianghu.knowledgeV190 = benefactor.jianghu.knowledgeV190 || {};
    benefactor.jianghu.knowledgeV190[secretArtId] = {
      artId: secretArtId,
      stage: KNOWLEDGE_STAGES.PRACTICED_USABLE,
      mastery: 50,
      authorizedBy: `GRATITUDE_OATH:${master.id}`,
      updatedTick: num(w.tick, 0)
    };
    benefactor.jianghu.artMasteryV150 = benefactor.jianghu.artMasteryV150 || {};
    benefactor.jianghu.artMasteryV150[secretArtId] = 50;

    const artRec = reg.artsById[secretArtId];
    if (!artRec.practitioners.includes(benefactor.id)) artRec.practitioners.push(benefactor.id);
    artRec.scrollHolders.push({ holderType: 'NPC', holderId: benefactor.id, count: 1, origin: 'GRATITUDE_GIFT' });

    if (E?.recordGrudgeOrGratitudeV100) {
      E.recordGrudgeOrGratitudeV100(w, 'GRATITUDE', master.id, benefactor.id, `${reasonTh} จึงมอบเคล็ดวิชา «${artRec.nameTh}» ตอบแทน`, 85, { silent: true });
    }
    reg.metrics.totalGratitudeTransmissions++;
    reg.gratitudeRightsGranted.unshift({
      tick: num(w.tick, 0),
      benefactorId: benefactor.id,
      masterId: master.id,
      artId: secretArtId,
      reasonTh
    });
    if (reg.gratitudeRightsGranted.length > 60) reg.gratitudeRightsGranted.length = 60;

    return { ok: true, benefactorId: benefactor.id, masterId: master.id, artId: secretArtId, artNameTh: artRec.nameTh };
  }

  // Creative Idea #6: Urgent Succession when Forbidden Art burns lifespan low
  function checkForbiddenLifespanSuccessionV190(w, npcOrId, E = null) {
    const npc = typeof npcOrId === 'string' ? w?.npcs?.[npcOrId] : npcOrId;
    if (!w || !npc?.alive || !npc.jianghu) return { triggered: false };
    const remainingYears = num(npc.jianghu.lifespanMax, 100) - num(npc.age, 30);
    if (remainingYears > 12) return { triggered: false, remainingYears };

    const reg = ensureTechniqueKnowledgeSystemV190(w, E);
    const masteredIds = Object.values(npc.jianghu.knowledgeV190 || {})
      .filter((k) => k.stage >= KNOWLEDGE_STAGES.PRACTICED_USABLE)
      .map((k) => k.artId);
    const targetArtId = masteredIds[0] || npc.jianghu.techniqueId;
    if (!targetArtId || !reg.artsById[targetArtId]) return { triggered: false };

    // Find a disciple or junior in the same sect/city to inherit the scroll & teaching
    const heir = (npc.jianghu.discipleIds || []).map((id) => w.npcs?.[id]).find((d) => d?.alive)
      || Object.values(w.npcs || {}).find((n) => n?.alive && n.id !== npc.id && n.stateId === npc.stateId && num(n.age, 25) < num(npc.age, 50));
    if (heir) {
      npc.jianghu.knowledgeV190[targetArtId] = {
        ...(npc.jianghu.knowledgeV190[targetArtId] || {}),
        artId: targetArtId,
        stage: KNOWLEDGE_STAGES.MASTERED_TEACHABLE,
        mastery: 85
      };
      const teachRes = teachTechniqueToDiscipleV190(w, npc, heir, targetArtId, { ignoreBusy: true }, E);
      return {
        triggered: true,
        remainingYears,
        heirId: heir.id,
        artId: targetArtId,
        taught: teachRes.ok
      };
    }
    return { triggered: false, remainingYears };
  }

  // Handle NPC Death: Mental knowledge does NOT drop on the ground; only physical scrolls transfer!
  function handleTechniqueInheritanceOnDeathV190(w, deadNpc, heirNpc = null, E = null) {
    if (!w || !deadNpc) return;
    const reg = ensureTechniqueKnowledgeSystemV190(w, E);
    for (const artRec of Object.values(reg.artsById || {})) {
      artRec.practitioners = (artRec.practitioners || []).filter((id) => id !== deadNpc.id);
      artRec.teachers = (artRec.teachers || []).filter((id) => id !== deadNpc.id);
      for (const sh of artRec.scrollHolders || []) {
        if (sh.holderType === 'NPC' && sh.holderId === deadNpc.id && sh.count > 0) {
          if (heirNpc && heirNpc.alive) {
            sh.holderId = heirNpc.id;
            heirNpc.jianghu.knowledgeV190 = heirNpc.jianghu.knowledgeV190 || {};
            const cur = heirNpc.jianghu.knowledgeV190[artRec.artId];
            if (!cur || cur.stage < KNOWLEDGE_STAGES.HOLDS_SCROLL) {
              heirNpc.jianghu.knowledgeV190[artRec.artId] = {
                artId: artRec.artId,
                stage: KNOWLEDGE_STAGES.HOLDS_SCROLL, // Holds scroll only — must still study & practice!
                mastery: 0,
                authorizedBy: `INHERITED_SCROLL:${deadNpc.id}`,
                updatedTick: num(w.tick, 0)
              };
            }
          } else if (deadNpc.stateId && w.states?.[deadNpc.stateId]) {
            sh.holderType = 'SECT';
            sh.holderId = deadNpc.stateId;
          }
        }
      }
      // If 0 practitioners and 0 active scroll holders remain, mark as LOST_ARCHIVED
      const activeScrolls = (artRec.scrollHolders || []).reduce((acc, s) => acc + num(s.count, 0), 0);
      if (artRec.practitioners.length === 0 && activeScrolls === 0 && artRec.status !== 'LOST_ARCHIVED') {
        artRec.status = 'LOST_ARCHIVED';
        reg.metrics.totalLost++;
      }
    }
  }

  // Recover a LOST_ARCHIVED technique from its archive subsite when an explorer is physically present
  function recoverArchivedTechniqueFromSiteV190(w, explorerOrId, artId, opts = {}, E = null) {
    const explorer = typeof explorerOrId === 'string' ? w?.npcs?.[explorerOrId] : explorerOrId;
    if (!w || !explorer?.alive) return { ok: false, reason: 'ไม่พบผู้สำรวจ' };
    const reg = ensureTechniqueKnowledgeSystemV190(w, E);
    const artRec = reg.artsById[artId];
    if (!artRec) return { ok: false, reason: 'ไม่พบรหัสวิชา' };

    const loc = E?.getEntityLocation ? E.getEntityLocation(w, explorer) : null;
    if (!opts.bypassLocationCheck && (!loc || (loc.subsiteId !== artRec.archiveSubsiteId && loc.kind !== 'SUBSITE'))) {
      return { ok: false, code: 'NOT_AT_ARCHIVE_SITE', reason: `ต้องเดินทางไปถึงโบราณสถานต้นทาง (${artRec.archiveSubsiteId}) จริงจึงจะค้นคืนคัมภีร์ได้` };
    }

    artRec.status = 'ACTIVE';
    artRec.scrollHolders.push({ holderType: 'NPC', holderId: explorer.id, count: 1, origin: 'ARCHIVAL_RECOVERY' });
    explorer.jianghu.knowledgeV190 = explorer.jianghu.knowledgeV190 || {};
    explorer.jianghu.knowledgeV190[artId] = {
      artId,
      stage: Math.max(getNpcArtKnowledgeStageV190(w, explorer, artId), KNOWLEDGE_STAGES.AUTHORIZED_RIGHT),
      mastery: Math.max(20, num(explorer.jianghu.knowledgeV190[artId]?.mastery, 20)),
      authorizedBy: `RECOVERED_AT:${artRec.archiveSubsiteId}`,
      updatedTick: num(w.tick, 0)
    };
    reg.metrics.totalRecovered++;
    reg.recoveryHistory.unshift({ tick: num(w.tick, 0), explorerId: explorer.id, artId, subsiteId: artRec.archiveSubsiteId });
    return { ok: true, recovered: true, artId, explorerId: explorer.id };
  }

  // Whitelisted Procedural Art Invention (Section 11 & 13: never generate phantom effect IDs!)
  function inventWhitelistedMartialArtV190(w, creatorOrId, spec = {}, E = null) {
    const creator = typeof creatorOrId === 'string' ? w?.npcs?.[creatorOrId] : creatorOrId;
    if (!w || !creator?.alive || !creator.jianghu) return { ok: false, reason: 'ผู้คิดค้นไม่พร้อม' };
    const reg = ensureTechniqueKnowledgeSystemV190(w, E);

    const requestedEffectIds = Array.isArray(spec.effectIds) && spec.effectIds.length
      ? spec.effectIds
      : ['EFX_SWORD_STORM_STRIKE', 'EFX_WEAKNESS_EXPOSURE'];

    // Validate every requested effect ID against the authoritative whitelist
    for (const eid of requestedEffectIds) {
      const def = Core.getEffectDefinition(eid);
      if (!def || !def.handlerId) {
        return {
          ok: false,
          code: 'PHANTOM_EFFECT_REJECTED',
          rejectedEffectId: eid,
          reason: `ปฏิเสธการคิดค้นวิชา: รหัสเอฟเฟกต์ ${eid} ไม่มีอยู่ใน Whitelist ที่มี Handler จริง`
        };
      }
      if (!def.allowedSourceKinds.includes('TECHNIQUE')) {
        return {
          ok: false,
          code: 'SOURCE_POLICY_REJECTED',
          rejectedEffectId: eid,
          reason: `เอฟเฟกต์ ${eid} จำกัดเฉพาะโครงสร้าง/ค่ายกล ไม่สามารถนำมาสร้างเป็นวิชายุทธ์ส่วนบุคคลได้`
        };
      }
    }

    const tier = clamp(num(spec.tier, creator.jianghu.stage || 4), 1, 7);
    const elem = Core.normalizeElementV190(spec.element || creator.jianghu.element || 'EARTH_METAL');
    const artId = `ART190_INV_${num(w.tick, 1)}_${++reg.sequence}`;
    const nameTh = spec.nameTh || `คัมภีร์${creator.firstName || creator.name}บัญญัติ • ${elem}`;

    const bindings = requestedEffectIds.slice(0, 3).map((eid, idx) => ({
      bindingId: `INV_BIND_${artId}_${idx + 1}`,
      effectId: Core.getEffectDefinition(eid).id,
      trigger: 'CAST',
      parameters: { powerScale: +(0.9 + tier * 0.15).toFixed(2), tier, element: elem },
      rangeBand: creator.jianghu.path === 'BODY' ? 'MELEE' : 'MID',
      targetPolicy: 'HOSTILE_TARGET'
    }));

    const newArt = {
      id: artId,
      nameTh,
      category: 'COMBAT_TECHNIQUE',
      roleGroup: 'COMBAT_DEFENSE',
      slotType: 'TECHNIQUE',
      path: creator.jianghu.path || 'XIAN',
      subPath: creator.jianghu.subPath || 'SWORD_IMMORTAL',
      tier,
      requiredNormalizedTier: tier,
      element: elem,
      power: tier * 48,
      creatorId: creator.id,
      creatorNameTh: creator.name,
      moves: [`ท่าที่ 1: ${nameTh}เบิกทาง`, `ท่าที่ 2: ปราณผสานแก่นแท้`, `ท่าไม้ตาย: ${nameTh}พิพากษา`],
      effectBindings: bindings,
      isWhitelistedInventionV190: true
    };

    reg.artsById[artId] = {
      artId,
      nameTh,
      category: newArt.category,
      path: newArt.path,
      tier,
      element: elem,
      transmissionPolicy: 'LINEAGE_RESTRICTED',
      originSectIds: creator.stateId ? [creator.stateId] : [],
      archiveSubsiteId: 'SITE_SUB_001_01',
      status: 'ACTIVE',
      scrollHolders: [{ holderType: 'NPC', holderId: creator.id, count: 1, isOriginal: true }],
      practitioners: [creator.id],
      teachers: [creator.id]
    };

    creator.jianghu.customArt = newArt;
    creator.jianghu.knowledgeV190 = creator.jianghu.knowledgeV190 || {};
    creator.jianghu.knowledgeV190[artId] = {
      artId,
      stage: KNOWLEDGE_STAGES.MASTERED_TEACHABLE,
      mastery: 85,
      authorizedBy: `CREATOR:${creator.id}`,
      updatedTick: num(w.tick, 0)
    };
    reg.metrics.totalInventedWhitelisted++;

    return { ok: true, art: newArt };
  }

  return {
    KNOWLEDGE_STAGES,
    DOCTRINE_MAP,
    getAllTechniquesCatalogV190,
    ensureTechniqueKnowledgeSystemV190,
    getNpcArtKnowledgeStageV190,
    canNpcCastTechniqueV190,
    studyOrPracticeTechniqueV190,
    teachTechniqueToDiscipleV190,
    grantGratitudeSecretRightV190,
    checkForbiddenLifespanSuccessionV190,
    handleTechniqueInheritanceOnDeathV190,
    recoverArchivedTechniqueFromSiteV190,
    inventWhitelistedMartialArtV190
  };
});

;
/**
 * ยุทธภพไร้พรมแดน (Jianghu 2026) — Patch 1.9.0
 * src/techniques190_ai.js
 * ปัญญาประดิษฐ์ตัดสินใจของ NPC และเจ้าสำนัก:
 * - Pure Feasibility & Scoring (getAvailableEffectActions, evaluateEffectAction) ไม่แก้โลกและไม่สุ่ม RNG
 * - โมเดลเปรียบเทียบ 9 ทางเลือกจัดหาทรัพยากรของเจ้าสำนัก (Make/Buy/Ally/Explore/Lease/Contest/War/Substitute/Wait)
 *   คำนวณ Total Cost to Usable Delivery และถ่วงน้ำหนักตามบุคลิกจริง
 * - ระบบเกิดเรื่องราวอัตโนมัติของจอมยุทธอิสระ หมอ ช่างค่ายกล และสายสืบ
 */
(function (root, factory) {
  'use strict';
  const api = factory();
  if (typeof module === 'object' && module.exports) module.exports = api;
  root.JianghuTechniques190AI = api;
})(typeof globalThis !== 'undefined' ? globalThis : this, function () {
  'use strict';

  const Core = (typeof module === 'object' && module.exports)
    ? require('./effects190_core.js')
    : (globalThis.JianghuEffects190Core || {});
  const Movement = (typeof module === 'object' && module.exports)
    ? require('./effects190_movement.js')
    : (globalThis.JianghuEffects190Movement || {});
  const WorldAdapters = (typeof module === 'object' && module.exports)
    ? require('./effects190_world_adapters.js')
    : (globalThis.JianghuEffects190WorldAdapters || {});
  const TechEngine = (typeof module === 'object' && module.exports)
    ? require('./techniques190_engine.js')
    : (globalThis.JianghuTechniques190Engine || {});

  const num = (v, d = 0) => (typeof v === 'number' && Number.isFinite(v) ? v : d);
  const clamp = (v, min = 0, max = 100) => Math.max(min, Math.min(max, num(v, min)));

  // ===========================================================================
  // 1. PURE FEASIBILITY PROJECTION FROM ACTOR'S OWN KNOWLEDGE (ZERO MUTATION)
  // ===========================================================================
  function getAvailableEffectActions(w, actorOrId, context = {}, E = null) {
    const actor = typeof actorOrId === 'string' ? w?.npcs?.[actorOrId] : actorOrId;
    if (!w || !actor || !actor.alive || !actor.jianghu) return [];

    const j = actor.jianghu;
    const actions = [];

    // 1. Usable Martial Arts from Actor's Own Knowledge (Stage >= PRACTICED_USABLE)
    const knownEntries = Object.values(j.knowledgeV190 || {}).filter((k) => k.stage >= TechEngine.KNOWLEDGE_STAGES.PRACTICED_USABLE);
    const equippedIds = [j.mantraId, j.techniqueId, j.lightnessId, j.auxiliaryId, j.forbiddenId].filter(Boolean);
    const usableArtIds = [...new Set([...equippedIds, ...knownEntries.map((k) => k.artId)])];

    for (const artId of usableArtIds) {
      const canCast = TechEngine.canNpcCastTechniqueV190(w, actor, artId);
      if (!canCast.ok) continue;
      const bindings = Core.getSourceBindingsV190('TECHNIQUE', artId, j.customArt);
      const techDef = Core.NEW_TECH_MAP.get(artId) || Core.LEGACY_ART_BINDING_MAP.get(artId);
      const qiCost = num(techDef?.costs?.qiCost, num(techDef?.qiCost, 12));
      const vitCost = num(techDef?.costs?.vitalityCost, 0);
      const lifeCost = num(techDef?.costs?.lifespanCostYears, 0);

      for (const b of bindings) {
        const val = Core.validateEffectAction(w, {
          actorId: actor.id,
          sourceKind: 'TECHNIQUE',
          sourceId: artId,
          effectId: b.effectId,
          targetKind: context.targetKind || 'NPC',
          targetId: context.targetId || actor.id,
          combatTurn: context.combatTurn,
          cost: { qiCost, vitalityCost: vitCost, lifespanCostYears: lifeCost }
        });
        if (!val.ok) continue;
        actions.push({
          actionId: `ACT_TECH_${artId}_${b.effectId}`,
          sourceKind: 'TECHNIQUE',
          sourceId: artId,
          effectId: b.effectId,
          semanticFamily: val.definition.semanticFamily,
          nameTh: `${techDef?.nameTh || artId} (${val.definition.nameTh})`,
          cost: { qiCost, vitalityCost: vitCost, lifespanCostYears: lifeCost },
          parameters: b.parameters || {},
          isForbidden: lifeCost > 0 || b.effectId === 'EFX_BLOOD_SACRIFICE_OVERDRIVE'
        });
      }
    }

    // 2. Equipped / Held Talismans, Pills & Tools in Actor's Ledger
    const led = j.ledgerV140;
    if (led) {
      for (const eq of led.equipmentItems || []) {
        if (num(eq.durability, 100) <= 0) continue;
        if (eq.consumableCharges !== undefined && eq.consumableCharges !== null && eq.consumableCharges <= 0) continue;
        const itemDef = Core.NEW_ITEM_MAP.get(eq.id) || Core.NEW_RECIPE_ITEM_MAP.get(eq.recipeId);
        const bindings = itemDef?.effectBindings || (eq.effect?.effectId ? [{ effectId: eq.effect.effectId, parameters: eq.effect }] : []);
        for (const b of bindings) {
          const def = Core.getEffectDefinition(b.effectId);
          if (!def) continue;
          actions.push({
            actionId: `ACT_ITEM_${eq.id}_${def.id}`,
            sourceKind: itemDef?.itemCategory === 'TALISMAN' ? 'TALISMAN' : (itemDef?.itemCategory === 'TOOL' ? 'TOOL' : 'EQUIPMENT'),
            sourceId: eq.recipeId || eq.id,
            itemInstanceId: eq.id,
            effectId: def.id,
            semanticFamily: def.semanticFamily,
            nameTh: `${eq.nameTh || itemDef?.nameTh} (${def.nameTh})`,
            cost: { qiCost: 5, vitalityCost: 0, lifespanCostYears: 0 },
            parameters: b.parameters || {}
          });
        }
      }
      for (const pill of led.pillStacks || []) {
        if (num(pill.count, 0) <= 0) continue;
        const itemDef = Core.NEW_RECIPE_ITEM_MAP.get(pill.recipeId);
        const bindings = itemDef?.effectBindings || (pill.effect?.effectId ? [{ effectId: pill.effect.effectId, parameters: pill.effect }] : []);
        for (const b of bindings) {
          const def = Core.getEffectDefinition(b.effectId);
          if (!def) continue;
          actions.push({
            actionId: `ACT_PILL_${pill.id}_${def.id}`,
            sourceKind: 'PILL',
            sourceId: pill.recipeId || pill.id,
            itemInstanceId: pill.id,
            effectId: def.id,
            semanticFamily: def.semanticFamily,
            nameTh: `${pill.nameTh} (${def.nameTh})`,
            cost: { qiCost: 0, vitalityCost: 0, lifespanCostYears: 0 },
            parameters: b.parameters || {}
          });
        }
      }
    }

    // 3. Contracted Companion Beast Abilities (if not exhausted or locked on mount duty)
    if (j.contractBeast && num(j.contractBeast.fatigueV190, 0) < 80) {
      const spAbilities = Core.BEAST_SPECIES_ABILITIES_MAP.get(j.contractBeast.id) || [];
      for (const ab of spAbilities) {
        if (ab.abilityMode !== 'CONTRACTED_BOND') continue;
        const def = Core.getEffectDefinition(ab.effectId);
        if (!def) continue;
        actions.push({
          actionId: `ACT_BEAST_${ab.abilityId}`,
          sourceKind: 'BEAST_ABILITY',
          sourceId: ab.abilityId,
          effectId: def.id,
          semanticFamily: def.semanticFamily,
          nameTh: `${j.contractBeast.nameTh || ab.speciesNameTh} • ${ab.nameTh}`,
          cost: { qiCost: 8, beastFatigueCost: ab.fatigueCost || 18 },
          parameters: ab.parameters || {}
        });
      }
    }

    const pools = Core.ensureNpcCombatPoolsV190(w, actor, { readOnly: true });
    return actions.filter((a) => num(a.cost?.qiCost, 0) <= pools.currentQi && num(a.cost?.vitalityCost, 0) < pools.vitality);
  }

  // ===========================================================================
  // 2. PURE ACTION SCORING WITHOUT RNG OR MUTATION (Section 4 & 19)
  // ===========================================================================
  function evaluateEffectAction(w, actorOrId, action, context = {}, E = null) {
    const actor = typeof actorOrId === 'string' ? w?.npcs?.[actorOrId] : actorOrId;
    if (!w || !actor || !action) {
      return { feasible: false, totalScore: -1000, breakdown: {}, reasonTh: 'ข้อมูลไม่ครบ' };
    }
    const def = Core.getEffectDefinition(action.effectId);
    if (!def) return { feasible: false, totalScore: -1000, breakdown: {}, reasonTh: 'ไม่พบนิยามเอฟเฟกต์' };

    const p = actor.personality || {};
    const caution = num(p.caution, 50);
    const courage = num(p.courage, num(p.aggression, 50));
    const ambition = num(p.ambition, 50);
    const empathy = num(p.empathy, 50);
    const rationality = num(p.rationality, 55);

    const hp = num(actor.health, 100);
    const remainingLifespan = num(actor.jianghu?.lifespanMax, 100) - num(actor.age, 25);

    let expectedBenefit = 35;
    let costPenalty = num(action.cost?.qiCost, 0) * 0.25 + num(action.cost?.vitalityCost, 0) * 0.8;
    let riskPenalty = 0;
    let personalityAdjustment = 0;

    // Context-aware scoring
    if (def.tags.includes('HEAL') || def.tags.includes('CLEANSE')) {
      const targetHp = context.targetNpc ? num(context.targetNpc.health, 100) : hp;
      expectedBenefit = (100 - targetHp) * 0.95 + (context.hasToxinOrWound ? 35 : 0);
      personalityAdjustment += (empathy - 50) * 0.25;
    } else if (def.tags.includes('DEFENSE') || def.tags.includes('BARRIER') || def.tags.includes('PARRY')) {
      expectedBenefit = (100 - hp) * 0.55 + (context.enemyPowerRatio > 1.1 ? 30 : 18);
      personalityAdjustment += (caution - 50) * 0.30;
    } else if (def.tags.includes('STEALTH') || def.tags.includes('ESCAPE')) {
      expectedBenefit = context.isInfiltrationOrScout ? 52 : (hp < 45 ? 48 : 15);
      personalityAdjustment += (caution - 50) * 0.25 + (rationality - 50) * 0.15;
    } else if (action.isForbidden || def.id === 'EFX_BLOOD_SACRIFICE_OVERDRIVE') {
      const lifeCost = num(action.cost?.lifespanCostYears, 5);
      expectedBenefit = (hp <= 42 || context.isLifeAndDeathDuel) ? 78 : 22;
      costPenalty += lifeCost * 4.5;
      riskPenalty += (remainingLifespan <= 15 ? 65 : 25) + caution * 0.45;
      personalityAdjustment += (ambition - 50) * 0.35 + (courage - 50) * 0.30 - (caution - 50) * 0.45;
    } else if (def.tags.includes('OFFENSE')) {
      expectedBenefit = 44 + (context.targetHasBarrier && def.id === 'EFX_ARMOR_FRACTURE' ? 24 : 0);
      personalityAdjustment += (courage - 50) * 0.20 + (ambition - 50) * 0.15;
    }

    const totalScore = +(expectedBenefit - costPenalty - riskPenalty + personalityAdjustment).toFixed(2);
    return {
      actionId: action.actionId,
      effectId: def.id,
      feasible: true,
      totalScore,
      breakdown: {
        expectedBenefit: +expectedBenefit.toFixed(2),
        costPenalty: +costPenalty.toFixed(2),
        riskPenalty: +riskPenalty.toFixed(2),
        personalityAdjustment: +personalityAdjustment.toFixed(2)
      },
      reasonTh: `ประเมิน ${action.nameTh}: ประโยชน์ +${Math.round(expectedBenefit)} ต้นทุน -${Math.round(costPenalty)} ความเสี่ยง -${Math.round(riskPenalty)} ปรับตามนิสัย ${personalityAdjustment >= 0 ? '+' : ''}${Math.round(personalityAdjustment)}`
    };
  }

  // ===========================================================================
  // 3. SECT LEADER 9-OPTION MAKE / BUY / EXPLORE / CONTEST / WAR EVALUATOR (Section 20)
  // ===========================================================================
  function evaluateSectProcurementStrategyV190(w, sectOrLeaderId, matId, neededQty = 2, opts = {}, E = null) {
    const st = w?.states?.[sectOrLeaderId]
      || (w?.npcs?.[sectOrLeaderId]?.stateId ? w.states[w.npcs[sectOrLeaderId].stateId] : null);
    if (!w || !st || st.isExiled) {
      return { ok: false, reason: 'ไม่พบสำนักที่ประเมินแผนจัดหา' };
    }
    const callerNpc = w.npcs?.[sectOrLeaderId] || w.npcs?.[st.positions?.HEAD_OF_STATE];
    const hasAuthority = callerNpc && (E?.hasSectAuthorityV161 ? E.hasSectAuthorityV161(w, callerNpc, st.id) : st.positions?.HEAD_OF_STATE === callerNpc.id);

    const p = callerNpc?.personality || {};
    const caution = num(p.caution, 55);
    const ambition = num(p.ambition, 55);
    const aggression = num(p.aggression, num(p.courage, 50));
    const rationality = num(p.rationality, 60);
    const empathy = num(p.empathy, 50);
    const greed = num(p.greed, 45);

    const sectStones = E?.getSpiritStonesV140 ? E.getSpiritStonesV140(st) : num(st.jianghu?.spiritStones, 0);
    const haveQty = E?.getUnreservedMaterialCountV180 ? E.getUnreservedMaterialCountV180(w, st, matId) : 0;
    const deficit = Math.max(1, neededQty - haveQty);
    const marketPrice = num(w.jianghu?.economyV180?.marketPrices?.[matId]?.currentPrice, 25);

    const sectNpcs = Object.values(w.npcs || {}).filter((n) => n?.alive && n.stateId === st.id);
    const idleMembers = sectNpcs.filter((n) => !(E?.isNpcBusyWithTaskV161?.(w, n, { ignoreSameDay: true }).busy));

    // Check recipes that output this matId
    const rSys = w.jianghu?.systemsV140?.recipes;
    const craftRec = Object.values(rSys?.registry || {}).find((r) => r.outputMatId === matId && r.status === 'ACTIVE');
    const qualifiedArtisan = craftRec
      ? idleMembers.find((n) => (rSys.registry[craftRec.id].knowers || []).includes(n.id) && num(n.jianghu?.craftMasteryV140?.[craftRec.craftPath], 0) >= craftRec.minMastery)
      : null;
    const hasCraftInputs = craftRec
      ? (craftRec.inputs || []).every((inp) => (E?.getUnreservedMaterialCountV180 ? E.getUnreservedMaterialCountV180(w, st, inp.matId) : 0) >= inp.count)
      : false;

    // Check known sellers in market
    const otherStates = Object.values(w.states || {}).filter((s) => !s.isExiled && s.id !== st.id);
    const offers=w.jianghu?.progressionV1100?.publicOffers;
    const sellers = otherStates.filter(s=>offers ? (num(offers[s.id]?.[matId]?.quantity)>0&&num(w.tick)-num(offers[s.id]?.[matId]?.tick,-999)<30) : false);
    const bestSeller = sellers[0] || null;
    const allySeller = sellers.find((s) => st.relations?.[s.id]?.status === 'Alliance' || num(st.relations?.[s.id]?.score, 50) >= 75) || null;

    // Check known Micro-Sites or Special Subsites from SECT KNOWLEDGE ONLY (Strict Non-Omniscience!)
    const msSys = w.jianghu?.microSitesV180;
    const knownMicroIds = Object.keys(msSys?.sectMicroSiteKnowledge?.[st.id] || {});
    const knownMicroSite = knownMicroIds
      .map((id) => msSys?.activeSites?.[id])
      .find((s) => s && (
        (s.resources || []).some((r) => r.materialId === matId && r.available > 0) ||
        (s.population || []).some((b) => b.alive > 0)
      )) || null;

    const ssKnow = w.jianghu?.specialSitesV1?.simulationV163?.sectKnowledge?.[st.id] || {};
    const knownSubsiteReport = Object.values(ssKnow).find((rep) => (rep.resources || []).some((r) => r.matId === matId && r.units > 0)) || null;
    const rivalControlledSubsite = Object.values(ssKnow).find((rep) => (rep.rivalSects || []).length > 0 && ((rep.resources || []).some((r) => r.matId === matId) || opts.allowContestAnyKnownSite)) || null;

    const explorers = idleMembers.filter((n) => !n.jianghu?.formationStatsV180?.isFormationPillar && num(n.health, 100) >= 65);
    const hasExplorer = explorers.length > 0;

    // Helper for Total Cost to Usable Delivery
    const buildOption = (optionId, labelTh, feasible, params) => {
      const {
        itemCost = 0,
        prepCost = 0,
        roundTripDays = 1,
        escortSupplyCost = 0,
        casualtyRisk = 0,
        exposureRisk = 0,
        opportunityCost = 0,
        baseUtility = 75,
        personalityDelta = 0,
        targetId = null
      } = params;
      const totalDeliveryCost = +(
        itemCost + prepCost + roundTripDays * 2.2 + escortSupplyCost + casualtyRisk * 0.9 + exposureRisk * 0.5 + opportunityCost
      ).toFixed(2);
      const rawScore = baseUtility - totalDeliveryCost * (0.45 + rationality / 250) + personalityDelta;
      return {
        optionId,
        labelTh,
        feasible: !!feasible,
        targetId,
        totalDeliveryCost,
        breakdown: {
          itemCost,
          prepCost,
          roundTripDays,
          escortSupplyCost,
          casualtyRisk,
          exposureRisk,
          opportunityCost,
          personalityDelta: +personalityDelta.toFixed(2)
        },
        score: feasible ? +rawScore.toFixed(2) : -1000
      };
    };

    const options = [
      // 1. WAIT_CONSERVE
      buildOption('WAIT_CONSERVE', '1. ชะลอการใช้และรอจังหวะทรัพยากรฟื้นตัว', true, {
        itemCost: 0,
        prepCost: 0,
        roundTripDays: 6,
        casualtyRisk: 0,
        opportunityCost: deficit * 14,
        baseUtility: 42,
        personalityDelta: (caution - 50) * 0.35 - (ambition - 50) * 0.30
      }),
      // 2. CRAFT_INTERNAL
      buildOption('CRAFT_INTERNAL', '2. สั่งช่างในสำนักหลอมผลิตเองจากวัตถุดิบตั้งต้น', !!(craftRec && qualifiedArtisan && hasCraftInputs), {
        itemCost: 8,
        prepCost: 6,
        roundTripDays: num(craftRec?.durationDays, 3),
        casualtyRisk: 2,
        opportunityCost: 10,
        baseUtility: 88,
        personalityDelta: (rationality - 50) * 0.35 + (caution - 50) * 0.25,
        targetId: craftRec?.id || null
      }),
      // 3. BUY_MARKET
      buildOption('BUY_MARKET', '3. สั่งซื้อผ่านขบวนค้าขายจากสำนักคู่ค้าที่มีของจริง', !!(bestSeller && sectStones >= marketPrice * deficit + 10), {
        itemCost: marketPrice * deficit,
        prepCost: 4,
        roundTripDays: 4,
        escortSupplyCost: 8,
        casualtyRisk: 3,
        opportunityCost: 4,
        baseUtility: 86,
        personalityDelta: (caution - 50) * 0.45 + (rationality - 50) * 0.25 - (greed - 50) * 0.20,
        targetId: bestSeller?.id || null
      }),
      // 4. ALLY_CO_PRODUCE
      buildOption('ALLY_CO_PRODUCE', '4. แลกเปลี่ยนหรือร่วมผลิตกับสำนักพันธมิตรในราคาพิเศษ', !!(allySeller && sectStones >= Math.round(marketPrice * 0.75)), {
        itemCost: Math.round(marketPrice * deficit * 0.72),
        prepCost: 3,
        roundTripDays: 3,
        escortSupplyCost: 5,
        casualtyRisk: 2,
        opportunityCost: 5,
        baseUtility: 90,
        personalityDelta: (empathy - 50) * 0.35 + (caution - 50) * 0.25,
        targetId: allySeller?.id || null
      }),
      // 5. EXPLORE_GATHER_HUNT
      buildOption('EXPLORE_GATHER_HUNT', '5. ส่งผู้สำรวจเดินทางไปเก็บเกี่ยวหรือล่าในแหล่งที่รู้เบาะแส', !!(hasExplorer && (knownMicroSite || knownSubsiteReport) && sectStones >= 15), {
        itemCost: 0,
        prepCost: 8,
        roundTripDays: 6,
        escortSupplyCost: 12,
        casualtyRisk: 22,
        exposureRisk: 10,
        opportunityCost: 12,
        baseUtility: 84,
        personalityDelta: (ambition - 50) * 0.35 + (greed - 50) * 0.25 - (caution - 50) * 0.35,
        targetId: knownMicroSite?.instanceId || knownSubsiteReport?.subsiteId || null
      }),
      // 6. LEASE_NEGOTIATE
      buildOption('LEASE_NEGOTIATE', '6. ส่งทูตเจรจาแบ่งสิทธิหรือเช่าช่วงเก็บเกี่ยวในแดนพิเศษ', !!(hasAuthority && hasExplorer && rivalControlledSubsite && sectStones >= 35), {
        itemCost: 24,
        prepCost: 6,
        roundTripDays: 5,
        escortSupplyCost: 8,
        casualtyRisk: 8,
        exposureRisk: 6,
        opportunityCost: 8,
        baseUtility: 80,
        personalityDelta: (empathy - 50) * 0.45 + (caution - 50) * 0.35 - (aggression - 50) * 0.40,
        targetId: rivalControlledSubsite?.subsiteId || null
      }),
      // 7. CONTEST_ESCORT
      buildOption('CONTEST_ESCORT', '7. ส่งหน่วยคุ้มกันเข้าแข่งขันช่วงชิงพื้นที่ทรัพยากร', !!(hasAuthority && explorers.length >= 2 && (rivalControlledSubsite || knownMicroSite) && sectStones >= 45), {
        itemCost: 10,
        prepCost: 12,
        roundTripDays: 6,
        escortSupplyCost: 18,
        casualtyRisk: 38,
        exposureRisk: 22,
        opportunityCost: 16,
        baseUtility: 83,
        personalityDelta: (ambition - 50) * 0.55 + (aggression - 50) * 0.50 - (caution - 50) * 0.60,
        targetId: rivalControlledSubsite?.subsiteId || knownMicroSite?.instanceId || null
      }),
      // 8. RESOURCE_WAR
      buildOption('RESOURCE_WAR', '8. เปิดศึกชิงแหล่งทรัพยากร (SiteWar) เพื่อยึดครองสิทธิระยะยาว', !!(hasAuthority && explorers.length >= 2 && rivalControlledSubsite && sectStones >= 450), {
        itemCost: 120,
        prepCost: 40,
        roundTripDays: 10,
        escortSupplyCost: 45,
        casualtyRisk: 55,
        exposureRisk: 35,
        opportunityCost: 28,
        baseUtility: 78,
        personalityDelta: (aggression - 50) * 0.95 + (ambition - 50) * 0.70 - (caution - 50) * 0.90 - (empathy - 50) * 0.45,
        targetId: rivalControlledSubsite?.subsiteId || null
      }),
      // 9. SUBSTITUTE_DOCTRINE
      buildOption('SUBSTITUTE_DOCTRINE', '9. ปรับโหมดค่ายกลหรือสลับใช้วิชา/ตำรับทดแทนเพื่อลดการพึ่งพาวัสดุที่ขาด', true, {
        itemCost: 0,
        prepCost: 5,
        roundTripDays: 1,
        escortSupplyCost: 0,
        casualtyRisk: 5,
        opportunityCost: 18,
        baseUtility: 64,
        personalityDelta: (rationality - 50) * 0.40 + (caution - 50) * 0.25
      })
    ];

    // Hysteresis / Commitment Bonus: if sect committed to a valid plan within last 12 days, give +8 stability bonus
    const prevPlan = st.jianghu?.lastProcurementPlanV190;
    if (prevPlan && num(w.tick, 0) - num(prevPlan.tick, -100) < 12) {
      const matching = options.find((o) => o.optionId === prevPlan.chosenOptionId && o.feasible);
      if (matching) matching.score = +(matching.score + 8).toFixed(2);
    }

    const sorted = options.slice().sort((a, b) => b.score - a.score || a.optionId.localeCompare(b.optionId));
    const chosen = sorted.find((o) => o.feasible) || sorted[0];

    return {
      ok: true,
      sectId: st.id,
      leaderId: callerNpc?.id || null,
      hasAuthority: !!hasAuthority,
      matId,
      deficit,
      chosenOptionId: chosen.optionId,
      chosenOption: chosen,
      alternatives: sorted,
      reasonTh: `${callerNpc?.name || st.shortName} เปรียบเทียบ 9 ทางเลือกจัดหา ${matId} (ขาด ${deficit} หน่วย) เลือก «${chosen.labelTh}» (คะแนน ${chosen.score}, ต้นทุนส่งมอบรวม ${chosen.totalDeliveryCost})`
    };
  }

  function executeSectProcurementStrategyV190(w, sectOrLeaderId, matId, neededQty = 2, opts = {}, E = null) {
    const caller = w?.npcs?.[sectOrLeaderId];
    const st = w?.states?.[sectOrLeaderId] || (caller?.stateId ? w.states[caller.stateId] : null);
    if (!w || !st) return { ok: false, reason: 'ไม่พบสำนัก' };

    // Strict Authority Check: Ordinary disciples cannot debit sect vault or declare war!
    if (caller && E?.hasSectAuthorityV161 && !E.hasSectAuthorityV161(w, caller, st.id)) {
      return {
        ok: false,
        unauthorized: true,
        code: 'DISCIPLE_NO_SECT_AUTHORITY',
        reason: 'ศิษย์ทั่วไปไม่มีอำนาจสั่งการคลังสำนักหรือเปิดศึกทรัพยากร'
      };
    }

    const evalRes = evaluateSectProcurementStrategyV190(w, caller?.id || st.id, matId, neededQty, opts, E);
    if (!evalRes.ok) return evalRes;

    const pick = evalRes.chosenOption;
    let execResult = { ok: true, action: pick.optionId };

    if (pick.optionId === 'CRAFT_INTERNAL' && pick.targetId && E?.produceFromRecipeV140) {
      execResult = E.produceFromRecipeV140(w, st.id, pick.targetId);
    } else if ((pick.optionId === 'BUY_MARKET' || pick.optionId === 'ALLY_CO_PRODUCE') && pick.targetId && E?.createMaterialTradeOrderV180) {
      execResult = E.createMaterialTradeOrderV180(w, st, pick.targetId, matId, Math.min(2, evalRes.deficit), {
        ignoreHostilityForMerchant: true
      });
    } else if (pick.optionId === 'EXPLORE_GATHER_HUNT' && pick.targetId) {
      const explorer = Object.values(w.npcs || {}).find(
        (n) => n?.alive && n.stateId === st.id && !n.jianghu?.formationStatsV180?.isFormationPillar && !(E?.isNpcBusyWithTaskV161?.(w, n, { ignoreSameDay: true }).busy)
      );
      if (explorer) {
        if (String(pick.targetId).startsWith('MICRO_SITE_') && E?.executeNpcMicroSiteExpeditionV180) {
          execResult = E.executeNpcMicroSiteExpeditionV180(w, explorer, pick.targetId, 'AUTO');
        } else if (E?.planSiteMissionV163) {
          execResult = E.planSiteMissionV163(w, [explorer.id], pick.targetId, 'GATHER', {
            commanderId: evalRes.leaderId,
            payerSectId: st.id,
            targetMatId: matId
          });
        }
      }
    } else if (pick.optionId === 'LEASE_NEGOTIATE' && pick.targetId && E?.planSiteMissionV163) {
      const envoy = Object.values(w.npcs || {}).find(
        (n) => n?.alive && n.stateId === st.id && !(E?.isNpcBusyWithTaskV161?.(w, n, { ignoreSameDay: true }).busy)
      );
      if (envoy) {
        execResult = E.planSiteMissionV163(w, [envoy.id], pick.targetId, 'NEGOTIATE', {
          commanderId: evalRes.leaderId,
          payerSectId: st.id,
          targetMatId: matId
        });
      }
    } else if ((pick.optionId === 'CONTEST_ESCORT' || pick.optionId === 'RESOURCE_WAR') && pick.targetId) {
      const squad = Object.values(w.npcs || {})
        .filter((n) => n?.alive && n.stateId === st.id && !n.jianghu?.formationStatsV180?.isFormationPillar && num(n.health, 100) >= 65 && !(E?.isNpcBusyWithTaskV161?.(w, n, { ignoreSameDay: true }).busy))
        .slice(0, 2);
      if (squad.length > 0 && E?.planSiteMissionV163 && String(pick.targetId).startsWith('SITE_SUB_')) {
        execResult = E.planSiteMissionV163(
          w,
          squad.map((n) => n.id),
          pick.targetId,
          pick.optionId === 'RESOURCE_WAR' ? 'DECLARE_SITE_WAR' : 'CONTEST',
          { commanderId: evalRes.leaderId, payerSectId: st.id, targetMatId: matId }
        );
      } else if (squad.length > 0 && String(pick.targetId).startsWith('MICRO_SITE_') && E?.executeNpcMicroSiteExpeditionV180) {
        execResult = E.executeNpcMicroSiteExpeditionV180(w, squad[0], pick.targetId, 'AUTO');
      }
    } else if (pick.optionId === 'SUBSTITUTE_DOCTRINE') {
      // Shift secondary formation to standby or peacetime passive to conserve scarce material
      const forms = w.jianghu?.formationsV180?.sectFormations?.[st.id] || [];
      const nonPrimary = forms.find((f) => !f.isPrimaryGuardian && f.active);
      if (nonPrimary) {
        nonPrimary.mode = 'PEACETIME_PASSIVE';
      }
      execResult = { ok: true, substituted: true };
    }

    if (st.jianghu) {
      st.jianghu.lastProcurementPlanV190 = {
        tick: num(w.tick, 0),
        matId,
        chosenOptionId: pick.optionId,
        score: pick.score,
        totalDeliveryCost: pick.totalDeliveryCost,
        reasonTh: evalRes.reasonTh,
        alternatives: evalRes.alternatives.slice(0, 5)
      };
    }

    return {
      ...evalRes,
      executed: !!execResult?.ok,
      executionResult: execResult
    };
  }

  // ===========================================================================
  // 4. PRE-SIEGE COUNTER-DOCTRINE PROCUREMENT (CREATIVE IDEA #5)
  // ===========================================================================
  function evaluatePreSiegeCounterProcurementV190(w, attackerSectId, defenderSectId, E = null) {
    const attSect = w?.states?.[attackerSectId];
    const defSect = w?.states?.[defenderSectId];
    if (!w || !attSect || !defSect) return { ok: false };

    const defDoctrine = TechEngine.DOCTRINE_MAP.get(defenderSectId);
    const fSys = w.jianghu?.formationsV180;
    const defGuardian = (fSys?.sectFormations?.[defenderSectId] || [])[0];
    const defKeywords = E?.getFormationByIdV180?.(defGuardian?.formationId)?.controlAndUtilitySpec?.keywords || [];

    let neededCounterRecipeId = 'REC190_TAL_015'; // ยันต์ชำระสถานะอธรรม
    let counterReasonTh = 'เตรียมยันต์ชำระสถานะก่อนเปิดศึก';

    if (defKeywords.includes('KW_ILLUSION_MIST_MAZE') || defKeywords.includes('KW_STEALTH_CONCEALMENT')) {
      neededCounterRecipeId = 'REC190_TAL_004'; // ยันต์เนตรสวรรค์ส่องมายา (EFX_DETECTION_REVEAL)
      counterReasonTh = `สืบทราบว่า ${defSect.shortName} ใช้ค่ายกลหมอกมายา/เร้นกาย จึงสั่งเตรียมยันต์เนตรสวรรค์ส่องมายาก่อนบุก`;
    } else if (defKeywords.includes('KW_MERIDIAN_TOXIN_PURGE') || defDoctrine?.primarySubPath === 'ELIXIR_DAO') {
      neededCounterRecipeId = 'REC190_PILL_002'; // โอสถบัวหิมะแก้พิษประสาทและกู่
      counterReasonTh = `สืบทราบว่า ${defSect.shortName} เชี่ยวชาญพิษและกู่ จึงสั่งหลอมโอสถต้านพิษเตรียมรับมือ`;
    } else if (defKeywords.includes('KW_SOUL_MENTAL_ATTACK')) {
      neededCounterRecipeId = 'REC190_PILL_005'; // โอสถใจกระจ่างสยบจิตมาร
      counterReasonTh = `สืบทราบว่า ${defSect.shortName} โจมตีทางจิตวิญญาณ จึงสั่งเตรียมโอสถสงบจิตก่อนเคลื่อนทัพ`;
    }

    return {
      ok: true,
      attackerSectId,
      defenderSectId,
      recommendedRecipeId: neededCounterRecipeId,
      reasonTh: counterReasonTh
    };
  }

  // ===========================================================================
  // 5. PERIODIC AUTONOMOUS AI & EMERGENT STORY LOOP (Section 19, 20, 21)
  // ===========================================================================
  function stepAutonomousAiAndEmergentStoriesV190(w, E = null) {
    if (!w || E?.isNpcAutonomyEnabledV161?.(w) === false) return;
    const curTick = num(w.tick, 0);

    // Every 6 days: run bounded batch of NPC learning/healing/cache-recovery & Sect 9-option procurement
    if (curTick % 6 === 0) {
      const states = Object.values(w.states || {}).filter((s) => !s.isExiled);
      if (states.length > 0) {
        const st = states[(Math.floor(curTick / 6)) % states.length];
        const targets = w.jianghu?.economyV180?.sectReserveTargets?.[st.id] || {};
        for (const [matId, want] of Object.entries(targets)) {
          const have = E?.getUnreservedMaterialCountV180 ? E.getUnreservedMaterialCountV180(w, st, matId) : 0;
          if (have < want) {
            executeSectProcurementStrategyV190(w, st.id, matId, want, {}, E);
            break;
          }
        }
      }

      // Independent cultivators & specialists emergent loop (bounded batch of 6 NPCs)
      const aliveNpcs = Object.values(w.npcs || {}).filter((n) => n?.alive && n.jianghu);
      if (aliveNpcs.length > 0) {
        const startIdx = (Math.floor(curTick / 6) * 6) % aliveNpcs.length;
        for (let i = 0; i < Math.min(6, aliveNpcs.length); i++) {
          const npc = aliveNpcs[(startIdx + i) % aliveNpcs.length];
          if (E?.isNpcBusyWithTaskV161?.(w, npc, { ignoreSameDay: true }).busy) continue;

          // 1. Check urgent succession if NPC burned lifespan with forbidden arts
          if (num(npc.jianghu.lifespanMax, 100) - num(npc.age, 30) <= 10) {
            TechEngine.checkForbiddenLifespanSuccessionV190(w, npc, E);
          }

          // 2. If NPC holds a scroll at stage HOLDS_SCROLL or AUTHORIZED_RIGHT, study/practice it!
          const unpracticed = Object.values(npc.jianghu.knowledgeV190 || {}).find(
            (k) => k.stage >= TechEngine.KNOWLEDGE_STAGES.HOLDS_SCROLL && k.stage < TechEngine.KNOWLEDGE_STAGES.PRACTICED_USABLE
          );
          if (unpracticed && E?.getSpiritStonesV140?.(npc) >= 40) {
            E.studyOrPracticeTechniqueV190(w, npc, unpracticed.artId, {});
            continue;
          }

          // 3. If ground caches exist and independent cultivator is idle with enough stones, recover ground cache!
          const caches = w.jianghu?.microSitesV180?.groundCachesV181 || {};
          const pos=E.getEntityLocation(w,npc);
          const cacheId = Object.keys(caches).find(id=>npc.jianghu.microKnowledgeV181?.[id]||((Number.isFinite(pos.x)&&Number.isFinite(pos.y))&&Math.hypot(pos.x-caches[id].x,pos.y-caches[id].y)<=18));
          if (cacheId && E?.isIndependentCultivator?.(w, npc) && E?.getSpiritStonesV140?.(npc) >= 25) {
            WorldAdapters.executeGroundCacheRecoveryMissionV190(w, npc, cacheId, {}, E);
          }
        }
      }
    }
  }

  return {
    getAvailableEffectActions,
    evaluateEffectAction,
    evaluateSectProcurementStrategyV190,
    executeSectProcurementStrategyV190,
    evaluatePreSiegeCounterProcurementV190,
    stepAutonomousAiAndEmergentStoriesV190
  };
});

