function ensureNpc(w,n){const j=n.jianghu;if(!j.preparationV1100)j.preparationV1100={clarity:clamp(78-num(j.heartDemon)*.4),foundation:clamp(num(j.foundationScoreV150,50+num(j.stage)*2)),lastPillTick:-9999,lastRestTick:-9999,tolerance:{},longevityGained:0};return j.preparationV1100;}
function realm(n){if(n?.jianghu?.cultivationIdentityV1200&&E.getRealizationBandV1200)return E.getRealizationBandV1200(n);const j=n?.jianghu||{},a=D.REALM_ANCHORS[j.path]||D.REALM_ANCHORS.XIAN;const i=clamp(Math.floor(num(j.stage,1))-1,0,a.length-1);return a[i]+(i<a.length-1?(a[i+1]-a[i]-.12):.28)*clamp(j.cultivationProgress)/100;}
