const EMPTY_FROZEN_PRESSURES=Object.freeze({HEAL:0,GROWTH:0,LEARN:0,CRAFT:0,INFO:0,crisis:false});
// Explicit Read-Only Decision Context (Section 7)
function createDecisionContext(w,n,phase='EVALUATE',opts={}){
 const pressure=opts.pressures||(phase==='COMMIT'?EMPTY_FROZEN_PRESSURES:needs(w,n));
 const busyStatus=opts.busyStatus||E.isNpcBusyWithTaskV161(w,n);
 const cityId=opts.cityId!==undefined?opts.cityId:E.getNpcCityV1100(w,n);
 const legacyOptions=opts.legacyOptions!==undefined?opts.legacyOptions:((phase==='COMMIT'||busyStatus.busy||!cityId)?[]:E.evaluateNpcSystemChoicesV1100(w,n,{busyStatus,cityId}));
 const legacyByType=new Map();
 for(const o of legacyOptions){let a=legacyByType.get(o.type);if(!a){a=[];legacyByType.set(o.type,a);}a.push(o);}
 const ctxObj={
  npcId:n.id,
  stateId:n.stateId,
  cityId,
  tick:num(w?.tick,0),
  phase,
  scope:opts.scope||'NPC',
  pressures:opts.background?pressure:Object.freeze({...pressure}),
  busyStatus:opts.background?busyStatus:Object.freeze({...busyStatus}),
  spiritStones:opts.spiritStones!==undefined?opts.spiritStones:E.getSpiritStonesV140(n),
  legacyOptions,
  legacyByType,
  knowsConcept:(cid)=>knowsConcept(w,n,cid),
  queryBelief:(q)=>belief(w,n,q),
  getPerceivedTarget:(tid)=>getRememberedTargetPerception(w,n,tid),
  getKnowledgeGaps:()=>deriveKnowledgeGaps(w,n,ctxObj)
 };
 return opts.background?ctxObj:Object.freeze(ctxObj);
}

// Fact Requirement Evaluation Before Choice & At Commit (Section 8)
function evaluateFactRequirement(w,n,req,candidate=null){
 const factId=req.targetField?candidate?.[req.targetField]:req.id;
 if(!factId||typeof factId!=='string')return {ok:false,code:'MISSING_FACT_TARGET',reason:'ไม่พบเป้าหมายของข้อเท็จจริงที่ต้องใช้'};
 const kind=req.kind||'FACT';
 const policy=req.policy||'BELIEVES_TRUE';
 const b=belief(w,n,{...req,kind,id:factId});
 const minConf=req.minConfidence!==undefined?req.minConfidence:(policy==='KNOWN_TRUE'||policy==='VERIFIED_COMPETENCE'?0.8:0.5);
 const maxAge=req.maxAgeDays!==undefined?req.maxAgeDays:null;
 const freshAffirmative=b.evidence.filter(e=>e.value===true&&num(e.confidence,1)>=minConf&&(maxAge===null||e.ageDays===null||e.ageDays<=maxAge));

 if(policy==='UNCERTAIN_ALLOWED'){
  // Used by information-seeking / verification actions: allowed when UNKNOWN, CONFLICTING, or stale/uncertain
  return {ok:true,code:'OK',status:b.status,factId};
 }
 if(policy==='NOT_BELIEVES_FALSE'){
  if(b.status==='BELIEVES_FALSE')return {ok:false,code:'BELIEVES_FALSE_FACT',reason:`เชื่อว่าข้อเท็จจริง ${factId} เป็นเท็จ`,status:b.status,factId};
  return {ok:true,code:'OK',status:b.status,factId};
 }
 if(policy==='CONFLICT_ALLOWED'){
  if(b.status!=='BELIEVES_TRUE'&&b.status!=='CONFLICTING')return {ok:false,code:'MISSING_REQUIRED_FACT',reason:`ยังไม่รู้ข้อเท็จจริง ${factId}`,status:b.status,factId};
  if(!freshAffirmative.length)return {ok:false,code:'STALE_OR_LOW_CONFIDENCE_FACT',reason:`หลักฐานของ ${factId} เก่าหรือความเชื่อมั่นต่ำเกินเกณฑ์`,status:b.status,factId};
  return {ok:true,code:'OK',status:b.status,factId};
 }
 // Default 'BELIEVES_TRUE', 'KNOWN_TRUE', 'VERIFIED_COMPETENCE'
 if(b.status==='UNKNOWN')return {ok:false,code:'MISSING_REQUIRED_FACT',reason:`ยังไม่รู้ข้อเท็จจริงที่จำเป็น (${factId})`,status:b.status,factId};
 if(b.status==='BELIEVES_FALSE')return {ok:false,code:'BELIEVES_FALSE_FACT',reason:`ข้อมูลที่รับรู้ระบุว่า ${factId} เป็นเท็จ`,status:b.status,factId};
 if(b.status==='CONFLICTING')return {ok:false,code:'CONFLICTING_FACT_UNRESOLVED',reason:`ข้อมูลเกี่ยวกับ ${factId} ขัดแย้งกัน ต้องตรวจสอบก่อน`,status:b.status,factId};
 if(!freshAffirmative.length){
  const anyConf=b.evidence.some(e=>e.value===true&&num(e.confidence,1)>=minConf);
  return {ok:false,code:anyConf?'STALE_FACT_EVIDENCE':'LOW_CONFIDENCE_FACT',reason:anyConf?`ข้อมูล ${factId} เก่าเกินเกณฑ์`:`ความเชื่อมั่นต่อ ${factId} ยังไม่ถึงเกณฑ์`,status:b.status,factId};
 }
 if((policy==='VERIFIED_COMPETENCE'||req.minStage!==undefined)&&kind==='ART'){
  const reqStage=req.minStage??4;
  if(num(b.competenceStage,0)<reqStage)return {ok:false,code:'INSUFFICIENT_COMPETENCE',reason:`ระดับความเข้าใจวิชา ${factId} ยังไม่ถึงขั้น (${num(b.competenceStage,0)}/${reqStage})`,status:b.status,factId};
 }
 if(kind==='SECRET'&&policy!=='UNCERTAIN_ALLOWED'){
  if(!n.core?.perception?.knownSecrets?.includes(factId))return {ok:false,code:'MISSING_SECRET_ACCESS',reason:`ยังไม่มีสิทธิหรือความลับที่ยืนยันแล้ว (${factId})`,status:b.status,factId};
 }
 return {ok:true,code:'OK',status:b.status,factId};
}

function verifyAllFacts(w,n,def,candidate=null){
 const dFacts=def?.requiresFacts;
 const cFacts=candidate?.requiresFacts;
 if((!dFacts||!dFacts.length)&&(!Array.isArray(cFacts)||!cFacts.length))return {ok:true,code:'OK'};
 if(dFacts&&dFacts.length){
  for(const req of dFacts){
   const res=evaluateFactRequirement(w,n,req,candidate);
   if(!res.ok)return res;
  }
 }
 if(Array.isArray(cFacts)&&cFacts.length){
  for(const req of cFacts){
   const res=evaluateFactRequirement(w,n,req,candidate);
   if(!res.ok)return res;
  }
 }
 return {ok:true,code:'OK'};
}

// Stable Semantic Candidate Identity & Exact Deduplication (Section 11)
const IDENTITY_FIELDS=['pillId','sellerId','matId','nodeId','habitatId','recipeId','teacherId','artId','partnerId','targetId','subsiteId','topicId','channel','offerId','variant'];
function canonVal(v){
 if(v===undefined||v===null)return '';
 if(typeof v==='number')return Number.isFinite(v)?(Number.isInteger(v)?String(v):v.toFixed(4)):'NaN';
 return String(v);
}
function sameIdentity(a,b){
 if(!a||!b||(a.type||a.id)!==(b.type||b.id))return false;
 return computeCandidateIdentity({id:a.type||a.id,scope:a.scope||'NPC',payer:a.payer||'SELF'},a)===computeCandidateIdentity({id:b.type||b.id,scope:b.scope||'NPC',payer:b.payer||'SELF'},b);
}
function computeCandidateIdentity(def,c){
 const actId=def?.id||c?.type||c?.id||'ACTION';
 const scope=c?.scope||def?.scope||'NPC';
 const payer=c?.payer||def?.payer||'SELF';
 const parts=[`act=${actId}`,`scope=${scope}`,`payer=${payer}`];
 for(const k of IDENTITY_FIELDS){
  const val=c?.[k];
  if(val!==undefined&&val!==null&&val!=='')parts.push(`${k}=${canonVal(val)}`);
 }
 if(c?.effectAction){
  parts.push(`efx=${canonVal(c.effectAction.effectId)}:${canonVal(c.effectAction.sourceKind)}:${canonVal(c.effectAction.sourceId)}`);
 }
 return parts.join('|');
}

