  s.schedulerMetrics.maxQueueResidence=Math.max(s.schedulerMetrics.maxQueueResidence,queueRes);
  s.schedulerMetrics.maxOnsetToEvaluation=Math.max(s.schedulerMetrics.maxOnsetToEvaluation,onsetDelay);
  s.urgentProcessed++;
  s.schedulerMetrics.urgentEvaluated++;
