  if(!n?.alive||!n.jianghu)continue;
  if(seenThisTick.has(n.id)){
   s.schedulerMetrics.skippedAlreadyServedUrgent++;
   continue;
  }
  ordinarySlotsUsed++;
  const cId=E.getNpcCityV1100(w,n);if(!cId)continue;
  const bSt=E.isNpcBusyWithTaskV161(w,n);if(bSt.busy)continue;
  s.schedulerMetrics.ordinaryEligible++;
  s.schedulerMetrics.ordinaryEvaluated++;
  const res=processOne(w,n,s,false,null,{cityId:cId,busyStatus:bSt});
  tickOutcomesByNpc.set(n.id,res);
  if(res.selected)s.schedulerMetrics.ordinarySelected++;
  if(res.committed)s.schedulerMetrics.ordinaryCommitted++;
