  function inviteDharmaProtectorV1180(w, cultivatorOrId, protectorOrId, opts = {}) {
    const cult = getNpc(w, cultivatorOrId);
    const prot = getNpc(w, protectorOrId);
    if (!w || !cult?.alive || !prot?.alive || cult.id === prot.id) {
      return { ok: false, code: 'INVALID_PARTIES', reason: 'ผู้ฝึกตนและผู้คุ้มกันด่านต้องมีชีวิต' };
    }
    if (!areNpcsCoLocatedV1180(w, cult, prot)) {
      return { ok: false, code: 'NOT_COLOCATED', reason: 'ต้องอยู่ในสถานที่เดียวกันเพื่อเชิญคุ้มกันด่าน' };
    }
    if (E.isNpcBusyWithTaskV161(w, prot).busy) {
      return { ok: false, code: 'PROTECTOR_BUSY', reason: 'ผู้ถูกเชิญกำลังติดภารกิจอื่น' };
    }
    if(!physicallyReady(w,cult)||!physicallyReady(w,prot)||activeProtection(w,cult))return {ok:false,code:'NOT_READY_OR_ALREADY_PROTECTED'};
    const rel = E.getRelationshipV130(w, prot, cult, false);
    const isClose = num(rel?.trust, 35) >= 45 || num(rel?.bond, 0) >= 35 || cult.jianghu?.masterId === prot.id || prot.jianghu?.masterId === cult.id || (cult.jianghu?.swornSiblingIds || []).includes(prot.id);
    const fee = isClose ? 0 : Math.max(15, num(prot.jianghu?.stage, 1) * 12);
    if (!isClose && E.getSpiritStonesV140(cult) < fee) {
      return { ok: false, code: 'INSUFFICIENT_STONES', reason: 'หินวิญญาณค่าตอบแทนคุ้มกันด่านไม่พอ' };
    }
    if (fee > 0) {
      E.addSpiritStonesV140(cult, -fee);
      E.addSpiritStonesV140(prot, fee);
    }
    const days = Math.max(2, num(opts.days, 4));
    E.reserveNpcTaskWindowV161(w, prot, days, 'DHARMA_PROTECTOR', `ยืนคุ้มกันด่านทะลวงขั้นให้ ${cult.name}`);
    cult.jianghu.dharmaProtectorIdV1180 = prot.id;
    cult.jianghu.dharmaProtectionUntilTickV1180 = num(w.tick, 0) + days;
    prot.jianghu.protectingSeclusionOfIdV1180 = cult.id;

    const sys = ensureCausalSystemsV1180(w);
    sys.metrics.dharmaProtectorsJoined++;
    applyCausalRelationshipDeltaV1180(w, prot, cult, {
      causalEventId: nextId1180(w, 'DHARMA'),
      kind: 'BYSTANDER_SAVED_IN_COMBAT',
      helperRiskRatio: 0.9,
      reasonTh: `${prot.name} ยอมสละเวลายืนคุ้มกันหน้าด่านให้ ${cult.name}`
    });
    reconcileNpcConcreteNeedsV1180(w, cult);
    return { ok: true, cultivatorId: cult.id, protectorId: prot.id, feePaid: fee, untilTick: cult.jianghu.dharmaProtectionUntilTickV1180 };
  }

  function commissionArtisanV1180(w, clientOrId, artisanOrId, spec = {}) {
    const client = getNpc(w, clientOrId);
    const artisan = getNpc(w, artisanOrId);
    if (!w || !client?.alive || !artisan?.alive || client.id === artisan.id) {
      return { ok: false, code: 'INVALID_PARTIES', reason: 'ผู้ว่าจ้างและช่างฝีมือต้องมีชีวิต' };
    }
    if (!areNpcsCoLocatedV1180(w, client, artisan)) {
      return { ok: false, code: 'NOT_COLOCATED', reason: 'ผู้ว่าจ้างและช่างฝีมือต้องอยู่ในเมืองเดียวกันจริง' };
    }
    if (E.isNpcBusyWithTaskV161(w, artisan).busy) {
      return { ok: false, code: 'ARTISAN_BUSY', reason: 'ช่างฝีมือกำลังติดงานอื่น' };
    }

    const plan=planArtisanCommissionV1181(w,client,artisan,spec);
    if(!plan.ok)return plan;
    const result=E.produceFromRecipeV140(w,artisan,plan.recipe.id,{commissionClientId:client.id,commissionMaterialPolicy:plan.materialPolicy,commissionClientInputs:plan.clientInputs});
    if(!result?.ok)return result;
    E.addSpiritStonesV140(client,-plan.feeStones-plan.materialCharge);E.addSpiritStonesV140(artisan,plan.feeStones+plan.materialCharge);
    let outputEscrow=null;
    if(result.produced&&result.item){
      const led=client.jianghu.ledgerV140;
      const container=['equipmentItems','pillStacks','beastItems'].find(k=>(led[k]||[]).some(i=>i.id===result.item.id));
      if(container==='equipmentItems'){
        outputEscrow={container,item:clone(result.item)};led[container]=led[container].filter(i=>i.id!==result.item.id);E.syncLegacyArraysFromLedgerV140?.(client);
      }
    }
    const career=artisan.jianghu.artisanCareerV1181||(artisan.jianghu.artisanCareerV1181={renown:0,completedOrders:0,highestDeliveredTier:0,earnedLaborStones:0,deliveredEventIds:[]});career.earnedLaborStones+=plan.feeStones;
    const sys=ensureCausalSystemsV1180(w);
    const rec={id:nextId1180(w,'COMM'),tick:w.tick,clientId:client.id,artisanId:artisan.id,recipeId:plan.recipe.id,craftPath:plan.recipe.craftPath,feeStones:plan.feeStones,materialCharge:plan.materialCharge,materialPolicy:plan.materialPolicy,allocations:clone(plan.materialPlan.allocations),jobId:result.job?.id||null,status:outputEscrow?'FORGING':result.pending?'BREWING':result.produced?'DELIVERED':'FAILED',outputEscrow,cityId:E.getNpcCityV1100(w,artisan),finishTick:Math.max(w.tick+1,num(artisan.jianghu.busyProductionUntilTick,w.tick+plan.expectedDays)),outputNameTh:plan.recipe.outputNameTh};
    sys.commissions.unshift(rec);const active=sys.commissions.filter(c=>['BREWING','FORGING','WAITING_STORAGE'].includes(c.status)),terminal=sys.commissions.filter(c=>!['BREWING','FORGING','WAITING_STORAGE'].includes(c.status));sys.commissions=[...active,...terminal.slice(0,40)];
    if(rec.status==='DELIVERED')sys.metrics.commissionsCompleted++;
    reconcileNpcConcreteNeedsV1180(w,client);
    return outputEscrow?{ok:true,pending:true,produced:false,commission:rec}:{...result,commission:rec};
  }
  function getArtisanStandingV1181(w,npcOrId) {
    const n=getNpc(w,npcOrId);if(!n?.jianghu)return null;
    const j=n.jianghu,career=j.artisanCareerV1181||{};
    const known=values(w.jianghu?.systemsV140?.recipes?.registry).filter(r=>r.status==='ACTIVE'&&(r.knowers||[]).includes(n.id)&&(j.knownRecipeIdsV140||[]).includes(r.id)&&E.getCraftMasteryV140(n,r.craftPath)>=r.minMastery);
    const highestKnownTier=Math.max(0,...known.map(r=>num(r.tier,1)));
    const renown=clamp(num(career.renown),0,100);
    return {renown,highestKnownTier,highestDeliveredTier:num(career.highestDeliveredTier),completedOrders:num(career.completedOrders),earnedLaborStones:num(career.earnedLaborStones),titleTh:renown>=70?'ปรมาจารย์ช่างที่ยุทธภพยกย่อง':renown>=40?'อาจารย์ช่างผู้มีชื่อเสียง':renown>=15?'ช่างฝีมือที่ผู้คนไว้วางใจ':'ผู้ประกอบวิชาช่าง',knownRecipeCount:known.length};
  }
  function getCommissionMaterialPlanV1181(w,client,artisan,rec,spec={}) {
    const policy=spec.materialPolicy||'CLIENT_SUPPLIES';
    if(!['CLIENT_SUPPLIES','ARTISAN_SUPPLIES','SHARED','AUTO'].includes(policy))return {ok:false,code:'INVALID_MATERIAL_POLICY'};
    const totals={};for(const inp of rec.inputs||[])totals[inp.matId]=(totals[inp.matId]||0)+inp.count;
    const allocations=[];let materialCharge=0;
    for(const [matId,count] of Object.entries(totals)){
      const haveClient=freeMaterial(w,client,matId);
      let fromClient=policy==='CLIENT_SUPPLIES'?count:policy==='ARTISAN_SUPPLIES'?0:policy==='AUTO'?Math.min(count,haveClient):num(spec.clientInputs?.[matId],0);
      if(!Number.isInteger(fromClient)||fromClient<0||fromClient>count)return {ok:false,code:'INVALID_SHARED_ALLOCATION'};
      const fromArtisan=count-fromClient;
      if(haveClient<fromClient||freeMaterial(w,artisan,matId)<fromArtisan)return {ok:false,code:'MISSING_AGREED_INPUTS'};
      if(fromClient)allocations.push({ownerId:client.id,matId,count:fromClient});
      if(fromArtisan){allocations.push({ownerId:artisan.id,matId,count:fromArtisan});materialCharge+=Math.ceil(num(getMatMap().get(matId)?.baseValueStones,10)*fromArtisan);}
    }
    return {ok:true,policy,allocations,materialCharge};
  }
  function planArtisanCommissionV1181(w,client,artisan,spec={}) {
    client=getNpc(w,client);artisan=getNpc(w,artisan);
    if(!client?.alive||!artisan?.alive||client.id===artisan.id||!physicallyReady(w,client)||!physicallyReady(w,artisan)||!areNpcsCoLocatedV1180(w,client,artisan)||E.isNpcBusyWithTaskV161(w,artisan).busy)return {ok:false,code:'ARTISAN_NOT_READY'};
    const recipes=values(w.jianghu?.systemsV140?.recipes?.registry).filter(r=>r.status==='ACTIVE'&&!r.isPartial&&['PILL','EQUIPMENT','WEAPON','ARMOR','TALISMAN_VESSEL'].includes(r.outputType));
    const matches=recipes.filter(r=>(!spec.recipeId||r.id===spec.recipeId)&&(!spec.craftPath||r.craftPath===spec.craftPath)&&(!spec.matId||(r.inputs||[]).some(i=>i.matId===spec.matId))&&(r.knowers||[]).includes(artisan.id)&&(artisan.jianghu.knownRecipeIdsV140||[]).includes(r.id)&&E.getCraftMasteryV140(artisan,r.craftPath)>=r.minMastery);
    for(const r of matches){
      const materialPlan=getCommissionMaterialPlanV1181(w,client,artisan,r,spec);if(!materialPlan.ok)continue;
      const standing=getArtisanStandingV1181(w,artisan),p=effective(w,artisan).personality;
      const mastery=E.getCraftMasteryV140(artisan,r.craftPath);
      const knowers=(r.knowers||[]).filter(id=>w.npcs[id]?.alive&&(w.npcs[id].jianghu?.knownRecipeIdsV140||[]).includes(r.id)).length;
      const scarcityMultiplier=1+Math.max(0,5-knowers)*.08;
      const laborBase=(8+Math.pow(Math.max(1,r.tier),1.7)*9+num(r.durationDays,1)*1.5)*(1+standing.renown*.006)*scarcityMultiplier*(1+Math.max(0,mastery-r.minMastery)*.002);
      const relation=E.getRelationshipV130(w,artisan,client,false);
      const friendshipDiscount=Math.min(.22,Math.max(0,num(relation?.bond))*.002);
      const greedPremium=1+(num(effective(w,artisan).values.wealthResource,50)-50)*.003;
      const quotedLabor=Math.max(10,Math.ceil(laborBase*(1-friendshipDiscount)*greedPremium));
      const feeStones=spec.feeStones===undefined?quotedLabor:Math.round(num(spec.feeStones,-1));
      const minimumAccepted=Math.ceil(quotedLabor*(num(p.empathy,50)>=65?.65:.85));
      if(feeStones<minimumAccepted)continue;
      const fuelCost=E.PROGRESSION1100_DATA.PILL_RECIPES.some(p=>p.id===r.id)?r.tier*4:0;
      const totalCost=feeStones+materialPlan.materialCharge+fuelCost;
      if(E.getSpiritStonesV140(client)<totalCost)continue;
      return {ok:true,recipe:r,feeStones,quotedLabor,fuelCost,materialCharge:materialPlan.materialCharge,totalCost,materialPlan,materialPolicy:materialPlan.policy,clientInputs:clone(spec.clientInputs||{}),scarcityMultiplier,renown:standing.renown,expectedDays:r.durationDays||1};
    }
    return {ok:false,code:'NO_FEASIBLE_KNOWN_RECIPE',reason:'ช่างต้องรู้สูตร ฝีมือถึง ของตามข้อตกลงครบ และค่าจ้างรวมวัตถุดิบกับเชื้อเพลิงเพียงพอ'};
  }
  function recordArtisanAchievementV1181(w,artisanOrId,rec,eventId,customerId=null) {
    const n=getNpc(w,artisanOrId);if(!n?.alive||!rec)return;
    const j=n.jianghu,c=j.artisanCareerV1181||(j.artisanCareerV1181={renown:0,completedOrders:0,highestDeliveredTier:0,earnedLaborStones:0,deliveredEventIds:[]});
    if(c.deliveredEventIds.includes(eventId))return;
    pushBounded(c.deliveredEventIds,eventId,100);
    c.completedOrders++;c.highestDeliveredTier=Math.max(c.highestDeliveredTier,num(rec.tier,1));
    const gain=Math.max(.4,num(rec.tier,1)*.65+Math.max(0,num(rec.minMastery,0)-40)*.015);
    c.renown=clamp(c.renown+gain*(1-c.renown/120),0,100);
    n.reputation=clamp(num(n.reputation,40)+gain*.25,0,100);n.prestige=clamp(num(n.prestige,20)+gain*.2,0,100);
    // Respect spreads through witnesses and the satisfied customer, not an omniscient global relationship update.
    const witnesses=values(w.npcs).filter(o=>o?.alive&&o.id!==n.id&&(o.id===customerId||areNpcsCoLocatedV1180(w,n,o))).sort((a,b)=>a.id.localeCompare(b.id)).slice(0,8);
    for(const witness of witnesses){const rel=E.getRelationshipV130(w,witness,n,true);rel.respect=clamp(num(rel.respect,35)+gain*2,0,100);rel.lastInteraction=w.tick;rel.reason='ยอมรับฝีมือจากผลงาน '+rec.outputNameTh;}
  }

  function postCausalBountyV1180(w, posterOrId, targetOrId, rewardStones = 120, reasonTh = 'ชำระหนี้แค้น') {
    const poster = getNpc(w, posterOrId);
    const target = getNpc(w, targetOrId);
    if (!w || !poster?.alive || !target?.alive || poster.id === target.id) {
      return { ok: false, code: 'INVALID_PARTIES' };
    }
    const reward = Math.max(40, Math.round(num(rewardStones, 120)));
    if (E.getSpiritStonesV140(poster) < reward) {
      return { ok: false, code: 'INSUFFICIENT_STONES', reason: 'หินวิญญาณไม่พอตั้งเงินรางวัลค่าหัว' };
    }
    const sys = ensureCausalSystemsV1180(w);
    if (sys.bounties.some((b) => b.targetId === target.id && b.status === 'OPEN')) {
      return { ok: false, code: 'BOUNTY_ALREADY_OPEN', reason: 'เป้าหมายมีประกาศค่าหัวที่เปิดอยู่แล้ว' };
    }
    E.addSpiritStonesV140(poster, -reward);
    const bounty = {
      id: nextId1180(w, 'BNT1180'),
      posterId: poster.id,
      posterName: poster.name,
      targetId: target.id,
      targetName: target.name,
      rewardStones: reward,
      reasonTh,
      createdTick: num(w.tick, 0),
      expiresTick: num(w.tick, 0) + 180,
      status: 'OPEN',
      claimedById: null
    };
    sys.bounties.unshift(bounty);sys.bounties=[...sys.bounties.filter(b=>b.status==='OPEN'),...sys.bounties.filter(b=>b.status!=='OPEN').slice(0,40)];
    sys.metrics.bountiesPosted++;
    return { ok: true, bounty };
  }

  function attemptClaimBountyV1180(w, hunterOrId, bountyId) {
    const hunter = getNpc(w, hunterOrId);
    const sys = ensureCausalSystemsV1180(w);
    const bounty = (sys?.bounties || []).find((b) => b.id === bountyId && b.status === 'OPEN');
    if (!hunter?.alive || !bounty) return { ok: false, code: 'BOUNTY_NOT_OPEN' };
    const target = getNpc(w, bounty.targetId);
    if (!target?.alive || hunter.id === target.id || hunter.id === bounty.posterId) {
      return { ok: false, code: 'INVALID_TARGET' };
    }
    if (!areNpcsCoLocatedV1180(w, hunter, target)) {
      return { ok: false, code: 'TARGET_NOT_COLOCATED', reason: 'ต้องเดินทางไปพบตัวเป้าหมายในสถานที่เดียวกันก่อน' };
    }
    if (target.jianghu?.incognitoStateV1180?.active && num(target.jianghu.incognitoStateV1180.untilTick, -1) > w.tick) {
      const sense = num(hunter.core?.physiology?.senseAcuity, 50);
      if (sense < num(target.jianghu.incognitoStateV1180.stealthRating, 65)) {
        return { ok: false, code: 'TARGET_INCOGNITO_UNSEEN', reason: 'เป้าหมายเร้นกายปลอมตัวจนแยกแยะไม่ออก' };
      }
    }

    const encRes = runCausalEncounterV1180(w, hunter, target, {
      intent: 'BOUNTY_CAPTURE',
      disallowMediation: true,
      reasonTh: `${hunter.name} ล่าค่าหัว ${target.name} ตามประกาศของ ${bounty.posterName} (${bounty.reasonTh})`
    });
    if (encRes.ok && encRes.encounter?.winningSide === 'A' && (!target.alive || num(target.health,100)<=28 || encRes.encounter.surrenderedSide==='B')) {
      if(target.alive){target.jianghu.captiveBy=hunter.id;target.jianghu.captiveUntil=w.tick+7;}
      bounty.status = 'CLAIMED';
      bounty.claimedById = hunter.id;
      bounty.claimedTick = w.tick;
      E.addSpiritStonesV140(hunter, bounty.rewardStones);
      sys.metrics.bountiesClaimed++;
      const poster = w.npcs?.[bounty.posterId];
      if (poster?.alive) {
        for (const hd of poster.jianghu?.heartDemonsV1180 || []) {
          if (hd.status === 'ACTIVE' && hd.culpritNpcId === target.id) {
            hd.status = 'RESOLVED';
            poster.jianghu.heartDemon = Math.max(0, num(poster.jianghu.heartDemon, 30) - 25);
            sys.metrics.heartDemonsResolved++;
          }
        }
        reconcileNpcConcreteNeedsV1180(w, poster);
      }
      return { ok: true, claimed: true, bounty, encounter: encRes.encounter };
    }
    return { ok: true, claimed: false, bounty, encounter: encRes.encounter };
  }

  function hirePersonalEscortV1180(w, clientOrId, guardOrId, destCityId = null, opts = {}) {
    const client = getNpc(w, clientOrId);
    const guard = getNpc(w, guardOrId);
    if (!w || !client?.alive || !guard?.alive || client.id === guard.id) {
      return { ok: false, code: 'INVALID_PARTIES' };
    }
    if (!areNpcsCoLocatedV1180(w, client, guard)) {
      return { ok: false, code: 'NOT_COLOCATED' };
    }
    if (E.isNpcBusyWithTaskV161(w, guard).busy) {
      return { ok: false, code: 'GUARD_BUSY' };
    }
    if(!physicallyReady(w,client)||!physicallyReady(w,guard)||[client,guard].some(n=>n.jianghu.escortContractV1180?.untilTick>w.tick))return {ok:false,code:'NOT_READY_OR_ESCORT_ACTIVE'};
    const fee = Math.max(18, num(opts.feeStones, num(guard.jianghu?.stage, 1) * 14));
    if (E.getSpiritStonesV140(client) < fee) {
      return { ok: false, code: 'INSUFFICIENT_STONES' };
    }
    E.addSpiritStonesV140(client, -fee);
    E.addSpiritStonesV140(guard, fee);

    const days = Math.max(2, num(opts.days, 3));
    E.reserveNpcTaskWindowV161(w, guard, days, 'ESCORT_GUARD', `คุ้มกัน ${client.name} เดินทาง`);
    client.jianghu.escortContractV1180 = { partnerId: guard.id, role: 'CLIENT', untilTick: num(w.tick, 0) + days, destCityId };
    guard.jianghu.escortContractV1180 = { partnerId: client.id, role: 'GUARD', untilTick: num(w.tick, 0) + days, destCityId };

    const sys = ensureCausalSystemsV1180(w);
    sys.metrics.escortsCompleted++;
    const rec = { id: nextId1180(w, 'ESC'), tick: w.tick, clientId: client.id, guardId: guard.id, feeStones: fee, days, destCityId };
    pushBounded(sys.escorts, rec, 30);
    return { ok: true, escort: rec };
  }

  function executeTeahouseOrStallGatheringV1180(w, actorOrId, opts = {}) {
    const a = getNpc(w, actorOrId);
    const cityId = E.getNpcCityV1100(w, a);
    if (!a?.alive || !cityId || !w.cities?.[cityId]) return { ok: false, code: 'NOT_IN_CITY' };
    const sys = ensureCausalSystemsV1180(w);
    const residents = (E.getCityResidentsV1100 ? E.getCityResidentsV1100(w, cityId) : values(w.npcs).filter((x) => x.alive && E.getNpcCityV1100(w, x) === cityId))
      .filter((x) => x.id !== a.id && canNpcPhysicallyReactV1180(w, x).ok);
    if (!residents.length) return { ok: false, code: 'NO_LOCAL_PARTNERS' };

    const fee = Math.min(3, E.getSpiritStonesV140(a));
    if (fee > 0) E.addSpiritStonesV140(a, -fee);
    E.reserveNpcTaskWindowV161(w, a, 1, 'TEAHOUSE_GATHERING', `สนทนาและสำรวจแผงค้า ณ โรงน้ำชาเมือง ${w.cities[cityId].name}`);
    sys.metrics.teahouseGatherings++;

    const rng = opts.rng || makeRng(w, `TEA1180:${a.id}:${cityId}`);
    const b = residents[rng.int(0, residents.length - 1)];
    ensureNpcCausalStateV1180(w, a);
    ensureNpcCausalStateV1180(w, b);

    const needA = (a.jianghu.activeNeedsV1180 || []).find((nd) => nd.status === 'ACTIVE' && nd.matId);
    if (needA && rng.chance(0.35)) {
      const seller=residents.find(x=>E.isOfferLawfullyVisibleV1110(w,a,x,{matId:needA.matId})&&freeMaterial(w,x,needA.matId)>0);
      if(seller){
        const claimants=[a,...residents.filter(x=>x.id!==seller.id)].slice(0,3);
        const oppRes=resolveContestedResourceOpportunityV1180(w,{claimantIds:claimants.map(x=>x.id),sellerId:seller.id,stockAvailable:1,competitionMode:'LAWFUL_MARKET_PURCHASE',targetSpec:{matId:needA.matId},priceStones:Math.max(12,num(getMatMap().get(needA.matId)?.baseValueStones,12))});
        if(oppRes.ok){sys.metrics.streetStallTrades++;return {ok:true,kind:'STALL_CONTEST',partnerId:seller.id,opportunity:oppRes.opportunity};}
      }
    }

    const relAB = E.getRelationshipV130(w, a, b, false);
    if ((num(relAB?.affinity, 0) <= -25 || (num(effective(w,a).personality.aggression, 50) >= 68 && num(effective(w,b).personality.pride, 50) >= 68)) && rng.chance(0.28)) {
      sys.metrics.disputesOpened++;
      const enc = runCausalEncounterV1180(w, a, b, {
        isRuleDuel: true,
        reasonTh: `ปะทะคารมและเขม่นศักดิ์ศรีสำนักกลางโรงน้ำชา ณ ${w.cities[cityId].name}`
      });
      return { ok: true, kind: 'TEAHOUSE_FRICTION_DUEL', partnerId: b.id, encounter: enc.encounter };
    }

    a.jianghu.daoComprehension = clamp(num(a.jianghu.daoComprehension, 25) + 3, 0, 100);
    b.jianghu.daoComprehension = clamp(num(b.jianghu.daoComprehension, 25) + 2, 0, 100);
    if (num(a.jianghu.heartDemon, 0) > 0) a.jianghu.heartDemon = Math.max(0, num(a.jianghu.heartDemon, 0) - 5);
    for (const hd of a.jianghu.heartDemonsV1180 || []) {
      if (hd.status === 'ACTIVE' && hd.resolutionModes?.includes('TEAHOUSE_DAO_DEBATE')) {
        hd.status = 'RESOLVED';
        sys.metrics.heartDemonsResolved++;
      }
    }
    const bSites = Object.keys(b.jianghu.siteKnowledgeV163 || {});
    if (bSites.length > 0) {
      const sharedSiteId = bSites[0];
      a.jianghu.siteKnowledgeV163 = a.jianghu.siteKnowledgeV163 || {};
      if (!a.jianghu.siteKnowledgeV163[sharedSiteId]) {
        a.jianghu.siteKnowledgeV163[sharedSiteId] = {
          ...clone(b.jianghu.siteKnowledgeV163[sharedSiteId]),
          source: `TOLD_AT_TEAHOUSE:${b.id}`,
          tick: w.tick
        };
        sys.metrics.sourcesKnown++;
      }
    }
    applyCausalRelationshipDeltaV1180(w, a, b, {
      causalEventId: nextId1180(w, 'TEA_CHAT'),
      kind: 'GIFT_NEEDED_ITEM',
      itemKey: `TEA_DAO:${w.tick}`,
      targetValueForB: 18,
      reasonTh: `ร่วมจิบสุราถกมรรคาและแลกเปลี่ยนข่าวสารในโรงน้ำชาเมือง ${w.cities[cityId].name}`
    });
    return { ok: true, kind: 'TEAHOUSE_DAO_AND_RUMOR', partnerId: b.id };
  }

  function createPersonalLegacyCaveV1180(w, patriarchOrId, opts = {}) {
    const n = getNpc(w, patriarchOrId);
    if (!w || !n?.alive || !n.jianghu) return { ok: false, code: 'INVALID_NPC' };
    const j = n.jianghu;
    const remLife = num(j.lifespanMax, 100) - num(n.age, 30);
    if (!opts.force && (num(j.stage, 1) < 3 || remLife > 18)) {
      return { ok: false, code: 'NOT_ELIGIBLE_FOR_LEGACY_CAVE', reason: 'ต้องเป็นผู้ฝึกตนขั้นกลางขึ้นไปที่ใกล้สิ้นอายุขัย' };
    }
    if(j.createdLegacyCaveV1180)return {ok:false,code:'LEGACY_ALREADY_CREATED'};
    const loc=E.getEntityLocation(w,n);
    let subsite=loc?.kind==='SUBSITE'?w.jianghu?.specialSitesV1?.subsites[loc.subsiteId||loc.id]:null;
    if(!subsite){
      if(j.pendingLegacyCaveV1181)return {ok:false,code:'LEGACY_JOURNEY_ALREADY_PLANNED'};
      const known=values(w.jianghu?.specialSitesV1?.subsites).filter(site=>j.siteKnowledgeV163?.[site.id]);
      known.sort((a,b)=>a.id.localeCompare(b.id));
      for(const site of known){const trip=E.planSiteMissionV163(w,[n.id],site.id,'SCOUT');if(trip?.ok){j.pendingLegacyCaveV1181={subsiteId:site.id,startedTick:w.tick};return {ok:true,pending:true,legacyCaveFounderId:n.id,expectedFinishTick:trip.operation?.workUntilTick||w.tick+15,reason:'เดินทางไปจารึกวิชาในสถานที่ที่รู้จักจริง'};}}
      return {ok:false,code:'NO_REACHABLE_KNOWN_SUBSITE'};
    }
    const artId=[j.techniqueId,j.mantraId,...Object.keys(j.knowledgeV190||{})].find(id=>id&&num(j.knowledgeV190?.[id]?.stage)>=6&&w.jianghu.techniqueRegistryV190?.artsById[id]);
    if(!artId)return {ok:false,code:'NO_MASTERED_ART_TO_BEQUEATH'};
    if(E.getSpiritStonesV140(n)<20)return {ok:false,code:'INSUFFICIENT_INSCRIPTION_COST'};
    E.addSpiritStonesV140(n,-20);
    subsite.dormantScrollIds=subsite.dormantScrollIds||[];
    if(!subsite.dormantScrollIds.includes(artId))subsite.dormantScrollIds.push(artId);
    const registry=w.jianghu.techniqueRegistryV190.artsById[artId];registry.scrollHolders=registry.scrollHolders||[];
    let holder=registry.scrollHolders.find(h=>h.holderType==='SUBSITE'&&h.holderId===subsite.id);
    if(!holder){holder={holderType:'SUBSITE',holderId:subsite.id,count:0,source:'PERSONAL_LEGACY_INSCRIPTION',discoverable:true,tradable:true};registry.scrollHolders.push(holder);}holder.count++;
    const eqItem = null; // Only the newly inscribed scroll is deposited; personal equipment remains owned.
    const sys = ensureCausalSystemsV1180(w);
    const cave = {
      id: nextId1180(w, 'LEGACY_CAVE'),
      founderId: n.id,
      founderName: n.name,
      subsiteId: subsite.id,
      subsiteNameTh: subsite.nameTh,
      depositedArtId: artId,
      depositedEquipmentNameTh: eqItem?.nameTh || null,
      createdTick: num(w.tick, 0),
      status: 'SEALED_WAITING_FATED_ONE'
    };
    pushBounded(sys.legacyCaves, cave, 30);
    sys.metrics.legacyCavesCreated++;
    j.createdLegacyCaveV1180=cave.id;delete j.pendingLegacyCaveV1181;
    E.reserveNpcTaskWindowV161(w, n, 3, 'CREATE_LEGACY_CAVE', `จารึกวิชาฝากไว้ในถ้ำมรดก ณ ${subsite.nameTh}`);
    reconcileNpcConcreteNeedsV1180(w, n);
    return { ok: true, legacyCave: cave };
  }

  function goIncognitoV1180(w, npcOrId, opts = {}) {
    const n = getNpc(w, npcOrId);
    if (!w || !n?.alive || !n.jianghu) return { ok: false, code: 'INVALID_NPC' };
    const cost = 15;
    if (E.getSpiritStonesV140(n) < cost) return { ok: false, code: 'INSUFFICIENT_STONES' };
    E.addSpiritStonesV140(n, -cost);
    const days = Math.max(15, num(opts.days, 30));
    n.jianghu.incognitoStateV1180 = {
      active: true,
      startedTick: num(w.tick, 0),
      untilTick: num(w.tick, 0) + days,
      aliasTh: `ผู้พเนจรชุดคลุมครามแห่ง${w.cities?.[E.getNpcCityV1100(w, n)]?.name || 'แดนไกล'}`,
      stealthRating: clamp(50 + num(effective(w,n).personality.caution, 50) * 0.4, 55, 92)
    };
    const sys = ensureCausalSystemsV1180(w);
    sys.metrics.incognitoEscapes++;
    E.reserveNpcTaskWindowV161(w, n, 1, 'GO_INCOGNITO', 'อำพรางกลิ่นอายปราณและเปลี่ยนฉายาเร้นกาย');
    return { ok: true, incognito: n.jianghu.incognitoStateV1180 };
  }

  // =========================================================================
  // 11. REGISTER CAUSAL & LIVING JIANGHU ACTIONS IN NPC_FOUNDATION1110
