      reasonTh: 'มอบวัตถุดิบหรือโอสถที่สหาย/คนในครอบครัวกำลังขาดแคลนอย่างเร่งด่วน',
      scope: 'NPC',
      decisionMaker: 'SELF',
      actors: 'SELF_AND_COLOCATED_PARTNER',
      payer: 'OWN_LEDGER',
      permissions: 'OWNED_SURPLUS_ITEM_AND_COLOCATED_RECIPIENT',
      taskCategory: 'CAUSAL_GIFT',
      requiresConcepts: ['HEALTH_FIRST', 'FINITE_RESOURCES'],
