          if (!trusted) continue;
          const isClose = num(rel?.bond, 0) >= 45 || j.masterId === other.id || (j.swornSiblingIds || []).includes(other.id);
          const fee = isClose ? 0 : Math.max(15, num(other.jianghu?.stage, 1) * 12);
          if (E.getSpiritStonesV140(n) < fee) continue;
