        cap.qiConduitStability = clamp(num(cap.qiConduitStability, 0) + Math.round(barrierBonus * 0.3), 0, 100);
        cap.qiConduitOutput = Math.round(num(cap.qiConduitOutput, 0) * (1 + barrierBonus * 0.005));
